REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f4fe869266af5f85abf283d1e654d7e1', '丁今凯', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪丰宁县县长、伪隆化县县长', '1933-1945', '', '任伪丰宁县县长期间，推行保甲制度，强征劳工，配合日军“集家并村”，制造无人区，迫害抗日群众。；投靠日军后任隆化县伪县长，强征民夫修筑公路和军事工事，配合日军“治安肃正”，迫害抗日军民。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('052953092dd65cd0842745f73b88095e', '丁今吾', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪围场县县长、伪平泉县县长、伪承德县县长、伪满洲国热河省警务厅厅长、伪满洲国青龙县（含今宽城部分区域）县长', '1933-1945', '', '日军侵占围场后首任伪县长，协助日军建立保甲制度，组织清乡队搜捕抗日人员，强征粮食支援日军；在宽城、青龙一带为日军效命，组织伪警察和保甲制度，参与“治安肃正”，围剿抗日游击队，强征民夫修建警备道路和碉堡。；负责热河地区伪警察体系，抓捕抗日志士，配合日军“治安肃正”行动。；1933年日军侵占平泉后出任伪县长，推行保甲制度，强征劳工，为日军提供粮秣，镇压当地反满抗日活动。；任伪承德县县长期间，在鹰手营子矿区及周边强征劳工开采矿产，为日军提供战略资源，并配合日伪军清剿抗日游击队。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3613c9792d855571bd9dcedeb3091e5e', '丁其昌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、河北', '内蒙古、河北', '[]', '伪丰镇县县长、伪兴隆县警务科长、伪冀东道尹、伪察哈尔省公署警务厅长、伪库伦旗旗长、伪张家口市市长、伪承德县知事、伪敖汉旗公署旗长、伪绥远省公署警务厅长、伪赤峰县县长', '1933-1945', '', '任伪丰镇县长期间，推行日伪苛政，强征粮税，抓捕抗日志士，协助日军建立保甲制度，镇压当地反抗。；在绥东（含集宁）组织伪警察，协助日军搜捕抗日分子，破坏地下组织。；日军侵占赤峰后出任伪县长，推行日伪殖民政策，强征民夫、收缴民间武器，协助日军维持统治。；任伪赤峰县县长期间，为日军征粮派夫，强征劳工，协助日军建立保甲制度，迫害抗日军民。；任伪敖汉旗旗长期间，积极推行日伪“治安肃正”政策，强征劳工，搜刮粮食，配合日军“讨伐”抗日武装。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c4ae1042a69351fc8d55d4754e948c5d', '丁其昌（重复？不，另列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东道尹（后任）', '1942-1945', '', '在廊坊东部推行“集家并村”，制造无人区。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('43144196b1f4559fb246a1a5759d567e', '丁其达', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪兴安总省省长、伪包头市公署市长、伪商都县县长', '1932-1945', '', '投靠日军，任商都县伪县长，推行日伪法令，强征民夫，搜刮粮食，镇压当地抗日力量。；作为伪满兴安总省（辖今兴安盟、乌兰浩特）最高行政长官，推行日本殖民政策，强征劳工，镇压反满抗日活动。；任伪包头市长期间，为日军征集物资、强征劳工，在九原区推行保甲制度，镇压抗日地下活动，协助日军建立特务组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('862e824365745b4b96bf87b400b96032', '丁原璜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪通辽县县长', '1932-1937', '', '投靠日军后任伪县长，推行保甲制度，强征粮食物资，协助日军建立殖民秩序。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2ccc9a42e40e54a5b4d02397b3fcd7fd', '丁强', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪围场县县长、伪满洲国热河省警务厅厅长、伪热河省警务厅厅长、伪热河省警务厅长', '1933-1945', '', '负责热河地区伪警察体系，配合日军进行“讨伐”，抓捕抗日地下工作者，实施“连坐”政策。；在承德、丰宁地区建立特务情报网，多次指挥围剿抗日游击队，逮捕并杀害抗日军民，参与“集家并村”行动，制造无人区。；负责伪满警察系统，在承德及双桥地区大肆搜捕抗日分子，实施“治安肃正”，制造多起屠杀事件。；任伪围场县县长期间，推行保甲制度，强征民夫修建警备道路和碉堡，为日军提供粮秣情报，多次配合日伪军“扫荡”围场抗日游击区。；原热河省警察头目，投日后任伪警务厅长，在宽城、承德等地推行保甲制度，抓捕抗日军民，提供情报给日军。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6112f4dfd9635c88a5c0c89afa7da57a', '丁春阳', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪通辽县县长', '1932-1945', '', '任伪通辽县县长期间，为日军征收粮饷，抓捕抗日志士，协助日军建立保甲制度，实施“连坐”统治。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('34d2f5cd1a415681a4c190c808de571c', '丁树本', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀南道保安司令', '1941-1945', '', '投敌后任伪冀南道保安司令，管辖包括宁晋在内的多个县，组织伪军配合日军“蚕食”根据地，杀害抗日家属。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('181a098fc1fb5ed5a72da41548f64fed', '丁超', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、河北、辽宁', '吉林、河北、辽宁', '[]', '伪满军政部顾问（曾驻阜新）、伪满吉林地区治安军头目、伪满吉林地区警备司令、伪满安东省省长（后任）、伪满洲国参议、伪热河省民生厅长、伪满洲国吉林省伪警备司令、伪满洲国热河省警务厅厅长、伪满洲国热河省警务厅长、伪满热河省警务厅长', '1931-1945', '', '原东北军将领，投日后在辽源、龙山一带率伪军围剿抗日游击队，制造多起惨案。；原东北军旅长，一度抗日，后投降日军，任伪吉林警备司令，参与围剿抗联。；原东北军将领，投日后组织治安军，在榆树、长春周边围剿抗联。；原东北军军官，投日后任伪热河省警务厅长，在承德、滦平一带组织伪警察，协助日军清乡、搜捕抗日人员。；原东北军将领，投日后在伪热河省任职，推行日伪奴化教育，强征粮食和民夫，为日军侵华战争服务。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2b437180a5505d89afed6a8146c9383e', '丁鉴修', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、河北、辽宁', '吉林、河北、辽宁', '[]', '伪吉林省实业厅长、伪满交通部大臣、伪满交通部大臣、伪满奉天省省长、伪满交通部大臣（曾活动于长春）、伪满交通部大臣（曾管理辽宁铁路）、伪满交通部大臣（沈阳籍）、伪满交通部大臣（管辖阜新地区铁路运输）、伪满洲国交通部大臣、伪满洲国交通部大臣（曾任吉林铁路伪职）、伪满洲国交通部大臣（管辖阜新铁路运输）、伪满洲国交通部大臣（辽宁籍）、伪满洲国交通部大臣（辽宁籍，曾负责辽南铁路）、伪满洲国交通部大臣（长春）、伪满洲国司法部大臣（曾在长春任职）、伪满洲国吉林地区保安局局长、伪满洲国实业部大臣、伪满洲国热河省警务厅厅长、伪热河省警务厅厅长、伪热河省警务厅长', '1931-1945', '', '原东北交通官员，投日后管理四平铁路枢纽，为日军运输兵员物资，并参与镇压铁路沿线抗日游击队。；负责伪满交通建设，在长春（新京）及吉林地区修建军用铁路和公路，服务于日军侵略。；组织汉奸特务，在公主岭、长春等地搜捕抗联地下工作者。；协助日本掠夺吉林矿产、森林资源，强征中国劳工。；管理伪满交通，为日军运输军需物资，协助军事占领。……（共涉及31个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0b11d3d3ebcc5d43aef8c018b2c76642', '上官云相', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪阳城县“剿共”委员会主任', '1943-1943', '', '组织“剿共”委员会，配合日军进行“清乡”，逮捕抗日家属，逼供情报。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('542aa343469854edb392ad575fba43d2', '业喜海顺', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪兴安南省参事官', '1933-1945', '', '投靠日伪，在兴安南省（阿尔山一带）任参事官，协助日军推行“治安肃正”，迫害当地抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bae12dcc23085ac1ac1f1ca631dfb851', '乌力吉巴雅尔', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪达拉特旗保安队副官', '1940-1945', '', '为日军效力，参与围剿八路军游击队，抓捕并杀害抗日群众，充当日军翻译和密探。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9a2d8c78a78b5e01bfaed10eb6318722', '乌力图', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪通辽县公署参事官、伪兴安南省民政厅长', '1935-1945', '', '科尔沁左翼中旗人。在通辽地区协助日军建立保甲制度，强征劳工修建军用公路和机场，参与“清乡”行动，逮捕抗日地下工作者。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('45b4f714531a53cb9ffa7f24686924ae', '乌勒吉', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪克什克腾旗警务科长', '1935-1945', '', '效忠日本特务机关，组织伪警察抓捕抗日志士，参与“治安肃正”行动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ab27f867dab453599e0a5cdf56ab966d', '乌勒吉敖其尔', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪蒙疆政府包头地区参事', '1940-1945', '', '蒙古族投日分子，在包头、白云鄂博地区协助日军管理蒙古族事务，煽动民族分裂，破坏抗日统一战线。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b182d6095559505a81aea13144dfe038', '乌勒吉敖喜尔（后反正）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪蒙古军第9师师长（前期）', '1938-1945', '', '在乌拉特中旗驻防期间曾执行日军命令，参与对抗日根据地的封锁，但后期于1945年率部反正（仍列入前期汉奸行为）。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7893cdab2278525ca46f22df1ae1de18', '乌古廷', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、河北', '内蒙古、河北', '[]', '伪兴安军管区司令、伪兴安南省省长、伪兴安南省警备军参谋长、伪兴安南省警备军司令、伪兴安西省警务厅长、伪满洲国兴安北省省长、伪蒙古军参谋长、伪蒙古军参谋长、伪蒙疆政府军事部长、伪蒙古军总参谋长、伪蒙古军第1师师长、伪蒙古军第9师师长、伪蒙古军第3师师长、伪蒙古军第4军军长、伪蒙古军第4师师长、伪蒙古军第5军军长、伪蒙疆政府内政部长、伪蒙疆政府军事部长', '1932-1945', '', '伪蒙古军高级指挥官，活动于乌兰察布南部及兴和一带，多次率部袭击八路军大青山支队，破坏抗日政权。；在化德及周边地区驻防，配合日军“清乡”，迫害抗日家属。；指挥伪兴安军驻守乌兰浩特，多次配合日军进攻抗联三路军，屠杀抗日军民。；伪满洲国兴安南省（辖今兴安盟及阿尔山部分地区）省长，推行日伪殖民政策，强征劳工，协助日军统治当地蒙汉民众。；蒙古族军官，投靠德王后任伪军参谋长，在包头地区参与军事指挥，协助日军围剿抗日游击队。……（共涉及19个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5c07d91a317b5e17b90f1fabc6916450', '乌尔金', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪兴安军第1师师长、伪兴安军第2师师长', '1933-1945', '', '指挥伪兴安军配合日军“讨伐”抗日武装，在呼伦贝尔地区制造多起屠杀事件，强征牧民入伍。；在呼伦贝尔西部活动，协助日军建立军事据点，迫害牧民', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4382b97ee65d52428cd4f3d0685924eb', '乔效曾', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪祁县保安队副队长、伪祁县保安队队长', '1940-1945', '', '率保安队配合日军袭击祁县抗日游击队，杀害抗日干部，抢夺物资，并参与“治安强化运动”。；率伪保安队多次配合日军扫荡抗日根据地，杀害抗日干部和群众，抢劫财物，破坏地下党组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('eb30ef64b60d52fdbba910bc5475ca42', '乔日成', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪和顺县保安队队长、伪山阴县保安队队长、伪警察署署长、伪平鲁县保安队队长、伪榆社县保安队队长、伪清太徐游击司令（清源、太原、徐沟地区）、伪神池县保安队队长、伪雁北挺进队司令、伪雁北挺进队司令（活动涉及晋北）', '1938-1945', '', '原为土匪，后投靠日军，在清徐、太原一带活动，袭击抗日武装，残害百姓，后反正但历史评价复杂。；投靠日军后任神池县伪保安队长，多次带路袭击八路军游击队，杀害抗日群众，强征粮饷。；原土匪出身，投日后任和顺县伪保安队长，多次带队袭击抗日游击队，杀害抗日干部，强征百姓财物；盘踞雁北，多次配合日军进攻晋中根据地，残杀抗日干部和群众，制造多起惨案。；投靠日军后任榆社县保安队队长，多次配合日军扫荡抗日根据地，抓捕抗日军民，抢劫粮食物资，残害百姓。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
