REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('143ce6584bf65a4e94082cf414c2f803', '于冲汉（重复？）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满鞍山铁矿株式会社总办', '1931-1945', '', '已列，补充其曾克扣劳工口粮。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c26803f6684e5028aefd0f491d4c762b', '于品卿', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪张家口商会会长、伪蒙疆银行总经理、伪张家口市公署市长、伪张家口市公署市长（后任伪蒙疆政府实业部长）、伪张家口市公署市长（后任伪蒙疆政府经济部长）、伪张家口市公署市长（后任伪蒙疆联合自治政府副主席）、伪张家口市市长、伪张家口市市长、伪察哈尔省公署厅长、伪张家口市市长、伪察哈尔省省长、伪张家口市市长、伪蒙疆政府经济部长、伪张家口市市长、伪蒙疆联合委员会经济部长、伪张家口市市长、伪蒙疆联合自治政府参议、伪张家口特别市公署参事、伪察南政厅厅长、伪张家口特别市公署市长、伪张家口特别市公署市长（后任伪蒙疆政府实业部长）', '1937-1945', '', '原张家口商会会长，日军占领后出任伪市长，为日军征粮派款，镇压抗日活动，协助维持殖民秩序。；原为张家口商会会长，日军占领后出任伪市长，积极组织维持会，为日军筹措军费，强征民夫修建军事设施，并参与伪蒙疆政府的物资掠夺政策。；原为张家口商会会长，投日后任伪张家口市长，为日军筹集物资，协助建立保甲制度，镇压抗日活动。；投靠日军，历任伪职，在张家口、下花园一带推行保甲制度，协助日军清乡，迫害抗日军民。；原为张家口商会头目，投日后任伪市长，为日军推行保甲制度，强征劳工，在下花园矿区压榨矿工，提供煤炭资源给日军。……（共涉及25个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('baf662e572cd50f88a38c21df20b9775', '于振声', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府保安队第五总队长、伪沧州地区特务机关长', '1935-1944', '', '在唐山丰润一带活动，协助日军抓捕抗日志士，破坏地下党组织。；建立情报网，多次侦破抗日地下组织，导致数十名抗日志士被捕牺牲。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bdc65b94361955e98916b39f842b9e00', '于文成', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪丰润县保安大队长、伪丰润县知事（含丰南地区）、伪丰润县知事（含丰南部分地区）、伪冀东政府滦县（含迁安西部）维持会长、伪唐山商会会长、伪唐山特别市公署警察局长、伪唐山特别市警察局局长、伪唐山维持会会长、伪唐山警察局局长、伪唐山警察局长、伪秦皇岛警察局局长、伪迁西县知事（县长）、唐山伪市长（日占时期）', '1937-1945', '', '为日伪筹集军费，强迫商户捐献，协助日军经济掠夺。；指挥伪警察搜捕抗日地下党员，破坏地下交通线，参与“大检举”行动，逮捕杀害多名爱国人士。；在丰润、丰南一带任伪县长，推行保甲连坐，强征粮食，配合日军“治安强化运动”，多次带队清乡。；在丰润、丰南一带推行日伪法令，强征民夫修筑据点，协助日军“治安强化运动”。；在唐山、丰润交界处设立检查站，搜捕抗日人员，严刑逼供，杀害多名地下党员。……（共涉及16个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('966848419e655049868e7b6310c7c5de', '于文斗', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满洲国于洪地区维持会会长', '1931-1932', '', '沈阳于洪地区人，九一八事变后组织地方维持会，迎接日军，协助建立伪政权。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4862f2cbb251501ba341d28724c21db9', '于文甲', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满安东省教育厅厅长', '1932-1945', '', '原安东教育界人士，投日后任伪满安东省教育厅厅长，在丹东、凤城地区推行奴化教育，强制学校教授日语。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c1678fb1f25657d499495f03556efa76', '于琛澂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪吉林省“讨伐”司令（曾率部在蛟河地区作战）、伪吉林省警备司令、伪满军政部大臣、伪满吉林剿匪总司令、伪满吉林警备军司令、伪满陆军上将、伪满吉林警备司令、伪满陆军上将', '1931-1945', '', '原东北军将领，投日后任伪吉林警备军司令，多次率伪军“围剿”抗日游击队，在丰满一带参与清乡和屠杀抗日军民。；原吉林军军官，叛变投日，在吉林地区多次围剿抗日游击队，参与“讨伐”杨靖宇等抗联部队。；率伪军多次进攻桦甸、磐石一带的抗日游击队和抗联部队，制造多起惨案，是日寇在吉林地区的主要帮凶。；伪满军事将领，多次率伪军进入蛟河、敦化一带“讨伐”抗日武装，制造多起屠杀事件。；原吉林军将领，叛国投敌，率伪军围剿抗日武装，在吉林、长春地区多次参与“讨伐”行动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
