REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('35e268a2eb6a57f5b5a3be250f503a59', '于镜涛', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪新京宪兵队队长（后任伪军职）、伪新京特别市公署总务厅长、伪长春特别市警察局长、伪长春（新京）特别市警察局局长', '1932-1945', '', '在长春地区指挥伪警察，参与多次大搜捕，迫害抗日地下工作者和普通民众。；率伪宪兵协助日军，在长春及周边地区屠杀抗联伤员和群众；在长春及绿园一带指挥伪警特，大肆搜捕抗日分子，制造多起血腥事件。；伪长春市政核心汉奸，协助日本殖民管理，参与“勤劳奉仕”等奴役劳工计划。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9b5824136943524caac2b49f4d988458', '于静远', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪吉林省协和会会长、伪新京特别市警察局长、伪满奉天省实业厅厅长、伪满奉天省实业厅长、铁西工业区管理要员、伪满洲国交通部大臣（曾在长春任职）、伪满洲国奉天省协和会事务长、伪满洲国新京特别市市长（后任经济部大臣）、伪满洲国长春市伪市长（后期）、伪长春市市长（后期）', '1932-1945', '', '组织协和会，宣传“王道乐土”，煽动民众支持伪满政权，监视抗日言行。；在长春推行粮食配给制，强征民夫，协助日军建立防空体系；参与修建军事铁路和公路，便利日军运输，强征劳工。；指挥伪警察配合日本宪兵，逮捕抗日地下工作者，制造多起惨案。；管理伪都“新京”，配合日本殖民统治，实施粮食配给制。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
