REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('37b4d45b85b2500c8c00d62157eee60d', '余晋龢', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪北京市市长、伪北京市长（曾协调秦皇岛日伪事务）、伪北平市市长、伪北平市市长、伪华北政务委员会常委、伪北平市市长（1938-1943）、伪北平市市长（1940-1943）、伪北平市市长（后任伪华北政务委员会建设总署督办）、伪北平市市长（曾涉廊坊）、伪北平市市长（继江朝宗后）、伪北平市长、伪华北政务委员会委员、伪北平市长（兼辖冀东部分地区）、伪北平特别市市长（1938-1943年）、伪华北政务委员会常委（分管石家庄）', '1937-1945', '', '1938年出任伪北京市市长，在任期间配合日军实施保甲制度、粮食统制，镇压北平城内抗日地下活动。；继任伪北平市长，在丰台地区设立伪警察机构，配合日军“清乡”和粮食统制。；原国民党官员，投日后任伪北平市长，管辖包括大兴在内的郊区，推行日伪法令，镇压抗日活动，组织“献铜献铁”等物资搜刮。；在北平推行保甲制度，配合日军搜捕抗日人士，强制推行粮食统制，导致民不聊生。；原国民党官员，投日后任伪北平市长，在延庆等辖区推行日伪法令，组织“献铜献铁”，协助日军强化治安。……（共涉及18个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b80378be9e295e1998165b8257e2187c', '余晋龢（重复？不，另列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪北平市市长（曾涉廊坊）', '1937-1943', '', '其伪政权势力延伸至廊坊北郊，支持日军在通县、香河一带建立“非武装区”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5993a6ed873f592abe5a6d7be2fff99b', '佟世清', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满新抚区维持会会长、伪满本溪县保安队队长', '1931-1945', '', '组织地方维持会，为日军提供粮草情报，协助建立伪政权。；率伪保安队配合日军在本溪、溪湖山区“扫荡”，杀害抗联伤员和百姓，烧毁村庄，是当地民愤极大的汉奸武装头目。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d191b4e79d905a0196a88c5a8279243b', '佟世荫', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪抚顺县警务科科长、伪抚顺市市长（伪满时期）、伪满新宾县县长', '1932-1941', '', '主持伪抚顺市政，为日军提供煤炭资源，强制推行“勤劳奉仕”，镇压矿工反抗。；在新宾县（当时称兴京县）组织伪县署，配合日军“清乡”，多次率伪警察队袭击抗联游击队，杀害抗日群众。；指挥伪警察配合日军“讨伐”，多次围剿抚顺、顺城一带的抗日游击队，抓捕并杀害抗日志士。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f547887d2b36594a96bc5c9bbd6e531c', '佟兆元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满苏家屯区公署区长', '1933-1945', '', '在苏家屯区实施伪满政策，强征劳工，收缴民间武器。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9e1735775df351d99a4b6206468b05fb', '佟德胜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满铁岭县清河警察署特务股长', '1941-1945', '', '专门负责‘思想犯’侦缉，在清河地区逮捕进步教师和学生，酷刑审讯后移送抚顺监狱。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('509fbde6a2cf5cab82eaa47e6dff85fa', '佟景阳', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪青龙县讨伐队副队长', '1942-1945', '', '随日军讨伐队进攻抗日根据地，参与屠杀平民，掠夺牲畜和财物，并负责审讯被俘的抗日人员。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('41a08e4dbe3e5201a005669abde72788', '佟玉璞', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满本溪湖市宪兵队翻译', '1937-1945', '', '本溪湖宪兵队汉奸翻译，参与刑讯逼供抗日志士，直接导致抗联侦察员牺牲，并协助日军在桓仁地区进行“大讨伐”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6a1ef5b397c15509b1605e37411576fc', '佟衡', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满奉天市副市长、伪满奉天省警察厅特务科科长、伪满洲国奉天省协和会会长、伪满铁西地区协和会会长', '1932-1945', '', '在抚顺、清原等地建立特务网络，搜捕抗日地下工作者，曾参与破坏中共南满地下组织。；协助日伪推行经济统制，迫害民族工商业者。；原沈阳士绅，投日后组织协和会，在沈北农村进行思想宣传，瓦解民众抗日意识。；任协和会铁西分会会长，推行奴化宣传，组织青年训练，为日军输送劳工。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
