REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6da181400a015ced8f2b9e4cbb31b41d', '侯俊明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪河津县新民会会长、伪离石县保安大队长', '1940-1945', '', '在离石区多次率伪军袭击八路军运输队，抢夺物资。；宣传中日亲善，组织奴化教育，搜集抗日情报，破坏地下党组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
