REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('24701b00857b5bc29c2eab5a2ad3e5c4', '冯涵清', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满司法部大臣（曾管辖辽宁法院）、伪满洲国交通部大臣', '1932-1945', '', '在沈阳设立伪法院，以“反满抗日”罪名判处爱国人士，协助日本关东军镇压反抗。；原东北交通委员会成员，投日后管理伪满交通，为日军运输军事物资提供便利。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2f5ae369af5d5ad4850f67907bb9b8aa', '冷家骥', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪北平商会会长、伪北平商会会长（曾涉廊坊）、伪北平市商会会长', '1937-1945', '', '任伪北平商会会长期间，强迫商户为日军提供物资，协助日伪进行经济掠夺和粮食配给。；在北平商会为日伪筹款，强迫昌平商户捐献物资。；为日军征调物资，协助经济统制。；通过商会控制廊坊地区商业，为日军筹集物资，并强迫商户“献金”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
