REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d0bfafacf89d5f0d93c40f5018954c98', '凌升', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪兴安北省省长（早期）、伪满洲国兴安北分省省长（后任）、伪满洲国兴安北省省长（前期）、伪满洲国兴安北省省长（后因反日被处决）', '1932-1936', '', '曾任伪兴安北省省长，后因对日本关东军不满被日军以“通苏”罪名处决，但其前期在伪职期间执行了日本殖民统治政策。；曾任伪兴安北省省长，后因与日本关东军产生矛盾，被指控“通苏通蒙”罪名，于1936年被日军处决，但其前期曾协助日伪建立统治。；曾任伪兴安北省省长，后因与日本关东军矛盾被处死，但前期曾协助日军建立伪政权；初期投靠日本，任伪兴安北省省长，后因反对日本移民政策及秘密联络抗日势力，于1936年被日本关东军以“通苏”罪名处决。；初期为日伪效力，后因与日本关东军产生矛盾被处决，但此前在陈巴尔虎旗地区执行过日伪行政命令。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f202fbdcda495844a9359d951d1723f7', '刘三旺', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪保德县警备队中队长', '1942-1945', '', '率警备队多次突袭抗日村庄，烧毁民房，抢掠粮食，并参与杀害八路军伤病员。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
