REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('29b4079aa77d5c5b8908d899dde123b2', '刘佩忱', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪东光县县长、伪冀东防共自治政府保安队总队长、伪华北治安军第1集团军司令、伪冀东防共自治政府保安队总队长、伪华北治安军第二集团军司令、伪南皮县知事、伪吴桥县知事、伪沧县县长、伪沧县知事、伪沧州知事、伪沧州道尹、伪河北省政府参议、伪沧州道尹、伪河北省政府委员、伪河间县县长、伪献县县长、伪盐山县县长、伪肃宁县知事（县长）、伪青县县长', '1935-1945', '', '投靠日军，任伪沧州道尹，协助日军推行治安强化运动，镇压抗日力量，征收苛捐杂税，迫害百姓。；投靠日军后出任伪沧州道尹，协助日军推行“治安强化运动”，强征民夫、搜刮粮食，镇压抗日活动，并参与组织伪军配合日军扫荡冀中根据地。；投靠日军，任东光县伪县长，推行日伪统治，强征粮税，镇压抗日民众。；日军占领南皮后出任伪县知事，协助日军推行“治安强化运动”，强征民夫修筑炮楼、封锁沟，并组织伪警备队配合日军扫荡抗日根据地，残害抗日军民。；投靠日军，任吴桥县伪政权首脑，协助日军推行“治安强化运动”，强征民夫、搜刮粮食物资，镇压抗日群众。……（共涉及28个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('54f0ab10414753ccbe4ffa04b9c5098b', '刘佩臣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪任丘县县长、伪任丘县知事、伪华北治安军第14集团军司令、伪大厂县知事、伪文安县保安队大队长、伪河间县保安联队队长、伪献县警备队大队长、伪黄骅县保安联队队长、伪黄骅县县长', '1937-1945', '', '任伪县知事期间，推行日伪保甲制度，强征粮食，抓捕抗日群众，为日军提供情报。；率伪军多次袭击文安、大城交界抗日武装，烧毁村庄，掠夺财物，制造多起惨案。；率伪治安军在廊坊、霸州一带驻防，参与日军“清剿”行动，烧杀抢掠，制造多起惨案。；在任丘县推行日伪统治，强征粮食，镇压抗日群众，协助日军建立保甲制度，抓捕抗日军民送交日军宪兵队。；任伪任丘县知事期间，积极推行日伪政权，协助日军清乡、征粮、抓捕抗日人员，破坏抗日组织。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
