REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('87337018bc85555cb8cd92602b5c34ea', '刘冠三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪冀南剿共军司令、伪冀南道尹公署顾问（魏县籍）、伪石家庄新民会会长、伪邯郸县商会会长、伪邯郸道尹公署顾问（兼馆陶事务）、伪阳泉特务队队长、永年县伪维持会会长、馆陶县伪商会会长', '1937-1945', '', '直属日军宪兵队指挥，专门搜捕八路军地下工作者，曾破获阳泉地下党联络站，致使多名党员牺牲。；宣传奴化思想，组织“新民会”青年团，协助日军进行文化侵略和特务活动。；为日军统制邯郸商业，强制商户缴纳‘慰劳金’，为日军收购粮食、棉花等战略物资。；日军占领永年后，率先组织维持会，为日军筹粮派款，提供情报，帮助日军建立伪政权。；组建伪剿共军，在邯郸、磁县、成安等地频繁袭击抗日武装，杀害抗日家属，烧毁村庄。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0909e1c37d255f0a9bcc9067de346e18', '刘冠儒', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪山西省高等法院院长、伪阳城县警察局局长、伪阳曲县保安队队长、伪陵川县知事、伪高平新民会会长', '1939-1945', '', '利用司法机构迫害抗日群众，以“反满抗日”罪名判处爱国人士死刑或劳役。；率伪保安队多次袭击抗日游击队，烧毁村庄，杀害无辜群众。；在陵川县实施“三光政策”配合，纵容伪军烧杀抢掠，残害抗日干部数十人。；指挥伪警察搜捕抗日地下党员，严刑逼供，破坏中共阳城地下组织。；主持新民会，推行奴化教育，组织“青少年团”为日军服务，告密抗日活动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('32be57e5150f566ebc18c0d354730dc5', '刘冠英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪藁城县（今藁城区）知事、伪邯郸县新民会会长、伪邯郸县知事、正定县伪维持会会长、肥乡县伪维持会会长', '1937-1945', '', '日军占领正定后率先组织维持会，为日军征粮派夫，提供情报。；组织伪警备队，参与对抗日根据地的封锁和扫荡。；在邯郸县城任伪知事，推行日伪法令，强征苛捐杂税，并协助日军建立情报网络。；推行奴化教育，宣传“中日亲善”，诱骗青年参加伪军。；在邯郸县城推行伪政权，设立‘良民证’制度，协助日军控制交通线，镇压抗日活动，并强迫商户‘捐献’军费……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('945e7424b19450a5b5390fe6766eb3e1', '刘冠雄', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪石家庄特务机关长（汉奸情报头目）', '1939-1945', '', '建立汉奸情报网，破坏中共地下组织，逮捕杀害多名抗日志士。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0948048118f050898c5e091379fc491b', '刘凤山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪邱县特务队队长、元氏县伪自卫团团长、衡水伪商会会长、邢台地区伪“剿共”自卫团团长', '1938-1945', '', '带领伪自卫团配合日军封锁抗日根据地，抢劫百姓财物。；充当日军经济汉奸，控制衡水商会，为日军筹集物资，强迫商户“献金”，垄断粮食贸易。；在邢台东部及平乡一带活动，率伪军袭击八路军游击队，烧毁村庄。；充当日军特务，刺探抗日军情，抓捕并刑讯抗日人员，罪行累累。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('41265d62a2c9566781d8e01edc3f99c1', '刘凤池', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪平谷县保安团团长、伪廊坊维持会会长', '1937-1940', '', '组织地方伪武装，多次袭击八路军游击队，破坏中共地下组织，杀害抗日干部和群众。；日军占领廊坊后组织维持会，为日军筹集粮款，强迫商户悬挂日伪旗帜。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
