REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f5fe59e9e13854cbb87a474a95350c50', '刘子英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、山西、河北', '内蒙古、山西、河北', '[]', '乡宁县伪维持会会长、代县伪警察局局长、伪五原县警察局长、伪大同省特务机关长（汉奸特务）、伪忻县（今忻府区）知事、伪新华区（原石门市第六区）维持会会长、静乐县伪区公所区长（康家会区）', '1937-1945', '', '为日军效忠，搜捕抗日地下人员，破坏地下交通线，并参与镇压当地民众的反抗。；日军占领乡宁期间，组织维持会为日军筹粮派款，提供抗日武装活动情报，导致多名地下党员被捕牺牲。；为日军宪兵队效命，在新荣地区发展特务网络，破坏地下抗日组织，逮捕并杀害多名共产党员和进步人士。；在忻县任伪职期间，为日军提供情报，组织伪政权征税派捐，协助日军建立“无人区”，迫害抗日家属。；效忠日伪政权，搜捕地下抗日人员，破坏抗日组织，勒索百姓财物。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('36858bfafe7c5a60a38a37d68095dc4c', '刘子谦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '应县伪保安队队长', '1939-1945', '', '率伪保安队配合日军袭击抗日根据地，烧杀抢掠，民愤极大。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a167c786caa25640ba5019fb83d620f9', '刘子麟', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪徐水县知事（县长）、伪易县警备大队大队长', '1939-1945', '', '在任期间推行日伪政权各项政策，强征粮税，抓捕抗日人士，协助日军建立保甲制度。；率伪警备队多次袭击八路军游击队和抗日村庄，抓捕并杀害抗日军民，参与制造“北娄山惨案”，后随日军投降。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
