REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8c21ecedfc7c52f9a1d27a5d5a4e2e7d', '刘山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪岚县保安团长、伪柳林镇维持会会长、方山县伪县长', '1938-1945', '', '在岚县（今吕梁岚县）率伪军围攻抗日根据地，杀害干部。；投靠日军，任方山县伪县长，协助日军推行“治安强化运动”，强征民夫修筑碉堡，搜捕抗日军民，勒索百姓财物。；在柳林镇为日军摊派粮款，强迫民众劳役，告密抗日分子。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b55380060edf5bc4bd753bdff58b6cf1', '刘崇武', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津', '天津', '[]', '伪天津县知事（继任）、伪宁河县保安队队长', '1940-1945', '', '率领伪保安队配合日军扫荡宁河地区，袭击抗日武装，杀害抗日军民。；继续在津南实施日伪统治，组织“自卫团”对抗八路军，破坏津南抗日根据地。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0f8507acbd04517392556339bcaf8db4', '刘干', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪离石县保安队队长', '1940-1940', '', '充当日军走狗，率保安队多次袭击离石周边抗日村庄，烧杀抢掠，并协助日军建立“无人区”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
