REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0b8d38c714dd5762a6adfc277b45558c', '刘庆和', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪满洲国热河省特务机关宽城分室主任', '1939-1945', '', '为日本关东军特务机关效力，在宽城发展特务网络，破坏地下抗日组织，逮捕并杀害多名抗日志士。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
