REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('30e372454b6252f4b301d91d5616ecab', '刘德才', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、河北', '吉林、河北', '[]', '伪热河省滦平县自卫团团长、伪磐石县自卫团团长、蛟河县伪警察署署长', '1932-1945', '', '率自卫团配合日军在磐石山区搜捕抗联战士，曾参与袭击杨靖宇部队后方医院，杀害伤员和医护人员。；效忠日伪，指挥伪警察搜捕抗日分子，刑讯逼供，破坏抗日联络站，罪行累累。；组织伪自卫团，协助日军在滦平山区建立“集团部落”，制造无人区，导致大量平民死亡。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('55d5c28516215af6bb912b6e514aad47', '刘德权', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪义县警察署署长、伪九台县县长、伪北镇县警务科科长、伪双阳县县长（继任）、伪吉林市市长（吉林市属吉林地区）、伪吉林市警察局长、伪大连市公署市长、伪大连市警察局局长、伪大连警察局局长、伪宏伟区（今宏伟区）日伪警察署署长、伪新京特别市建设局长、伪新民县协和会分会会长、伪满伊通县警务科科长、伪满凤城县保安队副队长、伪满千山地区维持会会长、汉奸、伪满台安地区“协和会”会长、伪满吉林保安队队长、伪满四平市警察局局长、伪满四平街市市长、伪满奉天市警察局长、伪满奉天省协和会头目、伪满开原县协和会会长、伪满德惠县协和会会长、伪满昌图县县长、伪满法库县警务科科长、伪满洲国双台子警察署署长、伪满洲国吉林市警察署长、伪满洲国大连警察署署长、伪满洲国奉天省高等法院院长、伪满洲国康平县协和会会长、伪满洲国弓长岭铁矿矿警队队长、伪满洲国沈北保安队队长、伪满洲国锦州省绥中县县长（曾辖兴城周边）、伪满海城保安队队长、伪满清河地区自卫团团长、伪满盘山县警务科科长、伪满立山地区保安队队长、伪满营口县县长、伪满营口市市长、伪满调兵山维持会会长、伪满辽中县教育局长、伪满辽阳商会会长、伪满铁岭保安队队长、伪满锦州地区保安队队长、伪满阜新市警察局局长、伪满阜新矿务局督办、伪满鞍山地区“宣抚班”班长、伪金州民政署署长、伪长春警察局长', '1931-1945', '', '在吉林市实施白色恐怖，搜捕抗日学生和地下工作者。；在四平地区组织伪警察，协助日军“讨伐”抗联，抓捕地下党员，实施白色恐怖。；原伊通县警察，投日后任伪满伊通县警务科科长，亲自带队搜捕抗日联军联络员，在伊通山区多次参与“讨伐”行动。；四平街（今四平市）伪市长，积极推行日伪“国策”，组织劳工为日军修建军事设施，镇压反满抗日活动。；率伪保安队在舒兰山区围剿抗联第三军，烧毁民房，屠杀百姓。……（共涉及49个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2b02c3265040584390408b2316e1dad9', '刘德权（重复？）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满鞍山地区“宣抚班”班长', '1937-1945', '', '已列，补充其曾诱骗儿童当间谍。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b64098b07f0051a18ecf0098f573eba7', '刘德胜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪冀东防共自治政府唐山青年训练所所长、伪吴桥县知事、伪太原县保安队副队长（古交驻防）、伪沙河县特务队长、伪神池县警备队小队长、伪长治县保安队分队长、伪阳高县保安队队长、灵寿县伪税务局局长', '1935-1945', '', '率领伪保安队配合日军进攻抗日根据地，在阳高南山一带烧毁村庄，屠杀抗日家属。；在古交河口、镇城底等地设卡盘查，抢劫百姓财物，杀害抗日家属。；多次带队突袭抗日村庄，烧毁民房，抢掠牲畜，杀害抗日军属，并参与“清乡”行动。；率队袭击八路军运输队，抢夺物资，杀害押运战士。；在唐山诱骗青年加入伪军，充当日军炮灰。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
