REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ce4c63c9505e5b01ba9aa9d1ec2f09f4', '刘振东', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、吉林、河北、辽宁', '内蒙古、吉林、河北、辽宁', '[]', '伪喀喇沁左旗警务科长、伪建平县警察署署长、伪承德县（含兴隆部分）维持会会长、伪满建平县县长、伪满洲国朝阳地区伪警察署长、伪热河省龙城县（今属朝阳）维持会会长、伪赤峰保安队队长、南和县伪保安联队队长', '1933-1945', '', '率保安队配合日军“扫荡”，烧杀抢掠，多次参与围剿赤峰周边的抗日游击队。；在朝阳地区任伪警察署长，抓捕抗日群众，为日军提供情报。；投靠日军，组织维持会为日军征粮派款，提供劳役，并告密抗日分子，导致多名抗日人员被捕牺牲。；组织伪保安队，配合日军扫荡抗日根据地，抓捕抗日军民，烧杀抢掠。；任伪建平县县长期间，强制推行“粮谷出荷”，导致百姓饿殍遍野，并告密逮捕地下抗日人员。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3d54f8fc40a95bcca4bf279c54506cf6', '刘振华', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪云州自卫团团长、伪平城商会会长、伪汾阳县警备队长', '1939-1945', '', '在汾阳地区参与日军“扫荡”，杀害多名抗日游击队员。；组织伪自卫团，配合日军扫荡云州周边村庄，烧杀抢掠，强征壮丁。；任伪平城商会会长，为日军统制物资，强制商户低价出售粮食、布匹，从中牟利，资助伪军。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
