REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('79c7ab309ad05f5fb005c5d2a3639b11', '刘显世', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满本溪湖煤铁公司总务部长', '1931-1945', '', '负责本溪湖煤铁公司（溪湖地区）的劳工管理，残酷压榨中国矿工，大量劳工因虐待致死，并协助日军将矿工充当劳役修筑军事工事。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('1885517c4b5b53f093b96c0dece295e7', '刘景文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪宽甸县县长、伪岫岩县警务科科长', '1933-1945', '', '继任伪宽甸县长，推行“归屯并户”，制造无人区，配合日军围剿杨靖宇领导的抗联部队。；原岫岩警察，投日后任伪警务科长，组织伪警察队，多次参与对抗日武装的“讨伐”，杀害多名抗联侦察员。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
