REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c8802c2d7c1f574987b6e310d8e9e5dd', '刘景新', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满洲国绥中县警务科长', '1933-1945', '', '在绥中地区组织伪警察队，多次参与围剿抗日义勇军和八路军游击队，残害百姓。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('052bb743ad3e5fe192318989a646a950', '刘景良', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪华北治安军第3集团军司令（曾驻沧州地区）', '1939-1945', '', '率伪治安军在沧州、盐山一带配合日军“清剿”，杀害抗日干部，烧毁村庄，强抓壮丁。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7ee6b737ce1d55a9866b5156643815fa', '刘桂堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、山西、河北、辽宁', '内蒙古、山西、河北、辽宁', '[]', '伪‘冀东防共自治军’沧州支队司令、伪“山东自治联军”司令（流窜邢台）、伪冀东土匪军头目（活动于唐山）、伪冀南道尹公署顾问（驻邯郸）、伪华北治安军第3集团军司令（活动于晋东南）、伪华北治安军第3集团军司令（活动涉及晋冀边界）、伪华北治安军第一军军长、伪渤海警备队总队长、伪满‘讨伐’军头目、伪满洲国兴安西省警备军司令、伪满热河省警备军司令、伪满热河省（含锦州西部）伪军旅长、伪满锦州地区土匪改编伪军头目、伪热河省承德县县长', '1931-1945', '', '在内蒙古东部及呼伦贝尔南部流窜，率伪军烧杀抢掠，配合日军扫荡；土匪出身，投靠日军后率伪军在库伦旗、通辽一带‘讨伐’抗日武装，屠杀百姓，掠夺牲畜。；率治安军多次进入晋中东部山区“扫荡”，在左权县外围烧毁村庄，杀害百姓。；惯匪出身，投日后率伪治安军驻扎长治周边，参与日军对长子县抗日根据地的“铁壁合围”，屠杀无辜百姓。；率匪军投靠日军，在唐山、遵化等地烧杀抢掠，配合日军扫荡。……（共涉及15个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('34279a10aeeb55cb97ee1ff96fae70fd', '刘梦庚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、河北、辽宁', '北京、天津、河北、辽宁', '[]', '伪冀东道公署顾问、伪唐山宪兵队翻译官、伪唐山特别市市长、伪天津县知事、伪天津县知事（继任）、伪天津市商会会长、伪天津特别市公署秘书长、伪满绥中县（今属葫芦岛市）县长、伪滦平县县长（双滦地区属滦平管辖时期）、伪热河省教育督学、伪秦皇岛警察局局长、伪通县知事（日据时期）、伪顺义县知事（1938-1940）', '1933-1945', '', '长期担任通县伪政权负责人，配合日军“清乡”和“治安强化运动”，迫害抗日军民。；在顺义县内积极推行日伪政策，强征粮食，破坏抗日组织，残害抗日群众。；在任期间协助日军推行“治安强化运动”，在东丽地区（如军粮城、赤土一带）设立据点，搜捕抗日分子。；继任伪天津县知事，在北辰地区推行日伪法令，抓捕抗日群众。；为日军筹措军费，强制摊派商业捐税，协助日伪经济掠夺。……（共涉及14个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('898e9d9aabf45e469bc462f4e26c136f', '刘步云', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '定襄县伪维持会会长', '1938-1942', '', '日军占领定襄后率先组织维持会，为日军筹粮派款，欺压百姓。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('dd9772cb0b4e5fb595942b0228831d15', '刘殿臣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '景县伪新民会会长', '1941-1945', '', '在景县推行奴化教育，宣传“中日亲善”，组织汉奸团体，刺探抗日情报，协助日军进行经济封锁。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7d2df74e1a825c519643471762c31aa7', '刘永昌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪沁源县维持会副会长', '1940-1942', '', '协助会长征收苛捐杂税，向日军报告抗日武装动向。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('edab9b9b38df5aee90d6eaffa789decb', '刘汉三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪垣曲县新民会主任、伪尧都区自卫团团长、夏县伪新民会会长、蒲县汉奸密探队队长、运城日伪特务队队长、闻喜县伪合作社社长', '1940-1945', '', '组织自卫团协助日军清乡，抢劫百姓财物，杀害抗日家属。；专门刺探八路军和抗日政府情报，多次带领日军偷袭抗日村庄，杀害抗日军属。；组织新民会宣传“大东亚共荣”，刺探抗日情报，并组织汉奸团体破坏抗日群众组织。；宣传“中日亲善”，强迫群众参加新民会，刺探抗日情报，协助日军推行奴化教育。；充当日军特务，刺探抗日情报，带领特务队突袭村庄，杀害抗日家属，制造多起惨案。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('cc4780eaa18152e6ae6635d3cc27fbd8', '刘汉兴', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北、辽宁', '河北、辽宁', '[]', '伪唐山铁路警察署长、伪承德县警察署署长、伪满本溪湖炭矿株式会社矿警队长', '1936-1945', '', '在唐山铁路沿线搜捕抗日交通员，破坏地下交通线。；在承德地区充当日军鹰犬，抓捕抗日群众，刑讯逼供，破坏地下抗日组织，罪行累累。；本溪湖煤矿汉奸，管理矿警队，残酷镇压矿工反抗，向日军提供抗联活动情报，并参与抓捕逃往桓仁山区的抗日矿工。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('466551fbaffe5ad0a078e82d80a2cd63', '刘汉卿', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、辽宁', '山西、辽宁', '[]', '伪满清原县协和会会长、伪满营口地区（含盘锦）汉奸头目、伪运城新民会会长', '1931-1945', '', '推行奴化教育，组织“中日亲善”宣传，强迫民众参加反共集会；宣传“日满亲善”，诱骗青年参加伪军，协助日军收集抗联情报，破坏群众抗日组织。；原为地方豪强，投日后担任伪职，在盘锦、营口交界处为日军征收粮饷，迫害百姓。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e31dd3c5867d579fbfb475b0be922af5', '刘汉杰', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪热河省警务厅特务科科长', '1935-1945', '', '在围场地区建立特务网络，逮捕抗日志士，刑讯逼供，破坏地下抗日组织', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c552feab438259f9bed94b87f2042708', '刘汉臣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、吉林、河北、辽宁', '内蒙古、吉林、河北、辽宁', '[]', '伪承德县协和会会长、伪敖汉旗协和会事务长、伪桦甸县司法矫正局局长、伪满东边道“讨伐”队队长、伪满朝阳县协和会会长、伪满本溪县县长、伪满本溪县县长（本溪县含南芬地区）、伪满洲国军热河省警备军团长、伪满西安县宪兵队翻译、伪满西安县（今辽源）自卫团长、伪热河省协和会北票分会会长、伪热河省协和会承德支部长、伪连镇警备队队长', '1932-1945', '', '负责协和会宣传，组织“勤劳奉仕”运动，强迫民众为日军修路筑堡，收集情报供日军使用。；将抓捕的抗联嫌疑人和无辜百姓投入矫正院，实施酷刑和劳役，致多人死亡，是日伪法西斯统治的忠实执行者。；组织地方自卫团，协助日军维持治安，多次参与袭击抗联小分队，杀害无辜群众。；在西安县（今辽源市）宪兵队任翻译，参与审讯和刑讯抗日志士，多次歪曲供词陷害无辜百姓，协助日军制造多起惨案，如“西安县大逮捕”事件。；率伪军驻防承德、丰宁，多次参与对抗日根据地的“讨伐”，烧毁村庄，掠夺牲畜，在丰宁黑山嘴一带制造多起惨案。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e5ef67441fec579094e14f26f59652a5', '刘洛进', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '行唐县伪警察所所长', '1941-1945', '', '效忠日军，负责伪警察事务，搜捕抗日地下人员，严刑逼供，破坏中共地下交通线，为日军提供情报。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('81630a2fb4475f6f9739f4b7c0996e70', '刘玉书', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、山西、河北', '北京、天津、山西、河北', '[]', '伪冀东防共自治政府乐亭县县长、伪冀东防共自治政府教育厅长、伪冀东防共自治政府教育处长、伪北京市警察局局长、伪北平市宪兵司令、伪北平市警察局局长、伪北平特别市警察局局长、伪塘沽警察署署长、伪天津市商会会长、伪天津特别市公署参事、伪华北政务委员会委员、伪天津特别市公署参事、伪河东区区长、伪天津特别市警察局局长、伪天津特别市警察局局长（1937-1943）、伪天津警察局局长、伪太原商会会长、伪河北省保安副司令、伪静海县知事', '1935-1945', '', '任伪北京市警察局局长，负责北平城内的治安监控，大肆搜捕抗日志士，协助日军进行“思想战”。；长期任伪北平警察头目，在丰台地区抓捕抗日地下人员，执行日伪保甲制度。；在任期间指挥伪警察在大兴等地抓捕抗日志士，破坏地下组织，协助日军设立“爱护村”和封锁沟。；在北平及大兴地区指挥伪警察，协助日军逮捕抗日志士，破坏地下交通线，参与“治安强化”运动。；在北平及延庆地区指挥伪警察，搜捕抗日地下人员，破坏中共地下组织，参与“治安强化运动”。……（共涉及30个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a6f0c5faddd8529a8381b8e50e39bd7a', '刘玉书（重复？不，另列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪河北省保安副司令', '1941-1945', '', '在廊坊各县组织伪保安团，协助日军“扫荡”，并参与屠杀抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('dcc74cdf99a8568a9b64577e8f3ea98f', '刘玉山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪临汾新民会会长、伪怀来县保安团团长、伪赤城县警察署署长', '1939-1945', '', '主持伪新民会临汾分会，推行奴化教育，宣传“中日亲善”，诱骗青年参加伪军，刺探抗日情报。；配合日军“清乡”，在怀来山区搜捕八路军伤员，抢劫百姓财物，杀害抗日家属。；在赤城县城及乡镇建立伪警察网络，搜捕八路军侦察员和抗日家属，实施酷刑。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
