REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c53095643ff251209d089e6871f45622', '刘祖笙', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪通州商会会长、伪霸县知事', '1938-1945', '', '为日军征购物资，强迫商户捐款，垄断粮食贸易，资助伪政权和日军。；在霸县（今霸州）推行“自首”政策，诱降抗日人员，并组织“新民会”进行奴化宣传。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0896c231dc995157b35c51cc6ca0606b', '刘绍先', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、天津', '吉林、天津', '[]', '伪宝坻县新民会会长、伪满洲国公主岭地区协和会会长', '1935-1945', '', '宣传“日满亲善”，组织民众欢迎日军，协助征粮和征兵。；推行新民会奴化宣传，组织“反共”活动，强迫民众参加日伪集会。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
