REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2e90f6004a1c59a6aa685f9d961ea568', '刘绍琨', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北', '天津、河北', '[]', '伪临榆县（山海关）保安团长、伪天津市警察局局长、伪天津特别市公署警察局局长、伪天津特别市市长（代理）、伪天津特别市警察局局长、伪天津警察局局长、伪武清县知事、伪津海道尹（辖津南地区）', '1937-1945', '', '长期担任伪天津警察机构负责人，协助日军搜捕抗日分子，镇压民众反抗。；七七事变后投敌，任伪天津市治安维持会委员，后代理伪市长，配合日军建立殖民统治，推行奴化教育。；指挥伪警察镇压抗日学生和地下党，搜捕爱国人士，配合日军“清乡”。；指挥伪警察协助日军搜捕抗日志士，破坏地下组织，参与镇压学生运动。；任伪武清县知事，组织伪县署，为日军征粮派夫，镇压当地抗日武装。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a2bccda0ab0f53c1808a09f401ea85ca', '刘绍衣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪满洲国吉林省教育厅长', '1932-1945', '', '投日后推行奴化教育，强制学校教授日语，灌输“忠君爱国”思想。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ca1777c7d53f5030baa885e371b5244b', '刘继光', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪东河区维持会会长', '1937-1940', '', '日军占领包头初期，在东河组织维持会，为日军带路、提供民夫，协助建立伪政权，欺压百姓。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7e8afb5020b9579d98ff2ca0dfcb94b7', '刘继唐', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、河北', '内蒙古、河北', '[]', '伪张家口宣抚班班长、伪张家口市市长、伪绥东宣抚使、伪蒙疆银行张家口分行经理', '1937-1945', '', '原为国民党地方官员，投日后任伪绥东宣抚使，在卓资、集宁一带进行亲日宣传，瓦解民众抗日意志，协助日军建立伪政权。；协助日本发行伪蒙疆货币，掠夺张家口地区财富，控制金融命脉。；在张家口市推行日伪市政管理，协助日军实行经济统制，迫害市民。；在张家口推行日伪统治，协助日军经济掠夺，对康保等县实施物资统制。；负责对张家口及怀安民众进行“宣抚”洗脑，劝降抗日人员，搜集情报。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
