REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8f028572bc1a552bba6fad0a6f6d1025', '刘芳圃', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪任丘县知事、伪沧州道尹公署顾问、伪泊头镇维持会会长、伪盐山县警备队大队长', '1937-1945', '', '在任丘地区为日军征粮征税，组织伪自卫团，参与围剿八路军游击队。；日军占领泊头后出任维持会长，为日军筹集粮款，出卖抗日志士，导致多人被捕牺牲。；作为日方顾问参与沧州地区伪政权管理，协助日军征粮、抓夫，破坏抗日组织。；充当日军走狗，率伪警备队多次围剿八路军游击队，抓捕抗日干部，制造多起惨案。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7ed6330d6faf5ac6b72d758ad6ffec4a', '刘荫亭', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '饶阳县伪保安联队队长', '1940-1945', '', '率伪军多次袭击八路军和地方抗日武装，杀害抗日干部和群众，制造多起惨案，后随日军投降。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
