REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('87dbb7322f44513194984602d632aa51', '刘鉴', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '临县伪县长', '1938-1945', '', '任临县伪县长期间，积极推行日伪政权各项政策，强征民夫、粮食，协助日军扫荡抗日根据地，镇压抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c59753d40023599bb37dc71e965c1008', '刘铁山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪东光县知事', '1939-1945', '', '任伪东光县知事，积极推行保甲制度，强迫百姓领取“良民证”，多次向日军报告抗日武装动向。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f4b02dede310526483957360bad8a6e2', '刘锡三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪三河县警察局局长、伪冀东剿共军第一路司令、伪冀东银行唐山分行经理、伪文安县保安大队长、伪遵化县知事', '1938-1945', '', '发行伪币，扰乱金融，为日军掠夺唐山资源服务。；率伪军驻防丰润、玉田，多次围剿八路军冀东军区部队，杀害抗日战士和群众。；遵化伪县长，参与镇压冀东暴动余部，为日军提供情报。；在文安洼地区围剿抗日游击队，并参与“水淹”根据地行动。；指挥伪警察协助日军搜捕抗日分子，破坏中共地下交通站，参与“大检举”行动，杀害无辜百姓。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c27e1315b228549bb3e6ef238a9ec5f2', '刘锡三（重复？不，另列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪文安县保安大队长', '1943-1945', '', '在文安洼地区围剿抗日游击队，并参与“水淹”根据地行动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('64cd6973a53a573988b1719436273d16', '刘锡九', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东盐务局局长（辖汉沽盐区）、伪唐山宪兵队翻译官、伪大城县警备队队长、伪文安县警备队长、伪沧县知事、伪秦皇岛警察局局长、伪邢台县商会会长', '1937-1945', '', '管理汉沽盐场，将大量食盐低价供给日军，禁止民间私盐，导致当地百姓食盐困难，并镇压盐工反抗。；为日军宪兵队充当翻译，参与刑讯逼供抗日志士，罪行累累。；任伪大城县警备队队长，长期在县境及周边（含廊坊南部）执行日军命令，参与多次“扫荡”，杀害抗日军民数十人。；率伪警备队多次袭击文安抗日游击队，杀害多名抗日群众。；推行日伪“治安强化”运动，组织汉奸团体，迫害进步人士。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2af01e48c8c458878ff249af74b6c59e', '刘锡彤', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北', '天津、河北', '[]', '伪三河县警察所所长、伪冀东防共自治政府滦州警察局长、伪天津县保安队队长、伪天津特别市宣传处处长、伪静海县保安队队长', '1935-1945', '', '率伪保安队在东丽地区（如大毕庄、金钟河沿岸）巡逻，协助日军封锁交通，抓捕抗日人员。；负责在天津及西青地区推行“中日亲善”宣传，查禁抗日书刊，控制舆论。；率伪保安队协助日军围剿八路军游击队，多次袭击村庄，杀害抗日干部。；在滦州城内搜捕抗日学生和进步人士，严刑逼供。；指挥伪警察抓捕抗日军民，提供情报给日军，参与“治安强化运动”中的清乡行动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3625d7a5951c578ba741e08f6f316f4e', '刘锡田', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪固安新民会会长、伪永清县警察所所长', '1939-1945', '', '为日军推行奴化教育，组织汉奸宣传队，强迫民众参加“反共”集会，搜集抗日情报供日军使用。；指挥伪警察抓捕抗日地下党员，破坏抗日交通站，参与“治安强化运动”中的清乡行动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('16cc46a367c6542d8b1867ebb053fa72', '刘镜堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪大名县警备队大队长', '1940-1945', '', '率警备队多次袭击抗日武装，抓捕并杀害抗日家属，破坏地下党组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
