REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b6338152f2385378a8ba94f3d763879d', '刘雨田', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪大连地区维持会会长、伪大连警察署署长、伪满大连地区维持会会长、伪满洲国大连民政署长、伪满洲国旅顺市市长', '1931-1945', '', '大连地区汉奸，任伪民政署长，推行保甲制度，强征劳工，为日军提供物资。；在大连地区指挥伪警察抓捕抗日志士，协助日军进行特务活动。；旅顺地方士绅，投日后任伪旅顺市市长，配合日军镇压旅顺地区抗日武装。；辽宁普兰店人（原复县），九一八后组织地方维持会，协助日军控制普兰店地区，残害抗日志士。；效忠日本关东军，指挥伪警察搜捕抗日地下组织，多次参与屠杀和镇压大连沙河口地区工人罢工与抗日群众。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
