REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7db565fbb6f85076949c7779b860a64f', '周大文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北、辽宁', '北京、河北、辽宁', '[]', '伪北京市工务局局长、伪北平市卫生局局长、伪北平市工务局局长、伪北平市社会局局长、伪北平市长（后任，曾涉廊坊）、伪北平特别市市长（1943-1945年）、伪满洲国奉天市市长（曾影响辽西）', '1931-1945', '', '负责北平市政工程，为日军修建军事设施，强征民夫，破坏城市基础设施。；在丰台地区推行日伪社会控制，组织“新民会”分会，进行奴化宣传。；继任伪北平市长，在延庆等地区继续推行日伪“粮食统制”，强征农民粮食，配合日军“扫荡”。；在石景山地区强征民夫修建军事道路和碉堡，服务于日军对平西根据地的“扫荡”。；在门头沟矿区推行日军防疫政策，限制民众流动，间接协助日军控制疫情和人口。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('1fffcb7aa29c573492ba9e32be289440', '周大文（重复？不，另列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪北平市长（后任，曾涉廊坊）', '1943-1945', '', '其管辖范围涉及廊坊北郊，配合日军在潮白河沿岸“清乡”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8b43c208d0485aee879750ce49e29111', '周子厚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪邢台县商会会长、枣强县伪税务局局长', '1938-1945', '', '为日军征收各种苛捐杂税，强征棉花、粮食，导致百姓负担沉重，并贪污勒索中饱私囊。；勾结日军，控制商业贸易，为日军采购军需物资，强迫商户缴纳“慰劳金”，剥削商民。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6fb38717c5655b83a7471ed547f994bd', '周子明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪晋北政厅偏关办事处主任', '1942-1945', '', '为日军征收苛捐杂税，强征民夫修筑碉堡和公路，并诱骗青年加入伪军，破坏抗日动员工作。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c1b3444d68145490a449eadd1b79505b', '周文富', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪中山区警察署署长、伪大连西岗区区长、伪甘井子警察署署长', '1938-1945', '', '在中山区指挥伪警镇压学生运动和工人罢工，多次参与逮捕抗日地下党员。；辽宁大连甘井子人，任伪警察署长，配合日军抓捕抗日分子，参与“治安肃正”行动，迫害当地居民。；辽宁大连人，曾任伪西岗区区长，推行保甲制度，协助日军搜查抗日分子，强征民夫。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('1c5a5b4b57a35e3887780282d0b228d6', '周文彬', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北、辽宁', '山西、河北、辽宁', '[]', '伪保定宪兵队特高课翻译兼密探队长、伪冀中道尹公署参事（分管望都）、伪太原县知事（尖草坪属太原县辖区）、伪安次县警察局局长、伪定兴县警察局局长、伪山阴县维持会会长、伪涿县警察局局长、伪满营口港务局局长、伪献县警备团团长、伪雁北道公署参事、伪香河县警察局长', '1937-1945', '', '任伪太原县知事，管辖包括尖草坪在内的乡村地区，推行保甲制度，强征壮丁。；日军占领山阴后出任维持会长，为日军筹集粮款，出卖抗日情报。；在朔州、怀仁一带为日军推行“以华制华”政策，组织汉奸宣传队，破坏抗日统一战线，并参与策划对抗日根据地的经济封锁。；原为保定商人，投日后充当日军翻译，组建密探网，在白沟新城、容城、雄县等地诱捕抗日志士，直接参与刑讯逼供。；效忠日军，指挥伪警察抓捕抗日地下党员，破坏交通线，协助日军建立保甲制度。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9b0436fb47615db386551fba69ea63bb', '周文焕', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北、辽宁', '山西、河北、辽宁', '[]', '五寨县伪区公所区长、伪代县税务局局长、伪保德县情报组组长、伪广灵县翻译官、伪忻县教育科长、伪景县警备队队长、伪朔县商会会长、伪沧州道公署参事、伪涞水县教育督学、伪满鞍山地区协和会会长、伪石楼县维持会会长、伪阳高县合作社联合社理事长、定襄县伪区公所区长（第二区）、景县伪税务局长、运城伪新民会会长', '1936-1945', '', '在石楼县为日军提供民夫，并参与迫害抗日家属。；为日军驻广灵部队担任翻译，多次参与审讯抗日志士，并利用翻译身份敲诈勒索百姓，曾向日军告密导致多名地下党员被捕牺牲。；垄断阳高粮食、棉花等物资，低价强购后供给日军，导致百姓饥荒，并从中贪污中饱。；在日军控制区任伪区长，协助日军建立保甲制度，强迫村民‘自首’抗日分子。；为日军征收各种苛捐杂税，强征粮食和物资，导致百姓负担沉重，部分收入用于资助伪军。……（共涉及15个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
