REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('62a4d32628c35cb08f36429635b022ed', '周文贵', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北、辽宁', '河北、辽宁', '[]', '伪唐山商会会长、伪沙河口区保安队队长、伪满铁岭县教育局长、伪满阜新市公署参事、伪秦皇岛港务局局长、伪金州地区维持会会长', '1931-1945', '', '为日军筹措军费，强迫商户捐献，控制唐山粮食和煤炭贸易，从中牟利并资助伪军。；协助日军控制秦皇岛港口，管理港口运输，为日军运送兵员和物资，出卖港口权益。；率保安队配合日军扫荡，围捕抗日武装，参与杀害沙河口地区抗日群众，罪行累累。；九一八后组织维持会，协助日军接管金州，后任伪职。；原铁岭县教育界人士，投日后任伪教育局长，强制推行日语教育，篡改历史教材，毒化青少年思想。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fde502a7b6095a29a49c6c8ec56ef3b3', '周文郁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪热河省建昌县教育督学', '1934-1945', '', '推行日本奴化教育，强制学校教授日语，删除中国历史内容，灌输“日满亲善”思想，毒害青少年。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('68139bf5da4659cb84fd1528c8758bab', '周文龙', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪三河县新民会会长、伪保定道尹公署参事（分管定兴）、伪冀东政府迁安保安团长、伪唐山矿务局督办、伪大厂县新民会会长、伪易县新民会会长、伪沧州保安团团长、伪迁西警察署署长、伪阜平县新民会会长、伪高碑店警察署署长、伪黄骅县新民会会长', '1938-1945', '', '在保定道任职期间，督导定兴县伪政权推行“治安强化运动”，组织保甲制度，强推“良民证”，协助日军经济封锁抗日根据地。；负责在易县推行奴化教育，组织“新民会”宣传“中日亲善”，搜集抗日情报，协助日军建立伪政权和维持会。；推行奴化教育，强迫群众参加“反共救国”集会，搜集抗日情报，并参与诱降八路军基层干部。；指挥伪警察搜捕抗日地下工作者，破坏地下交通站，严刑拷打被捕人员，致死多人。；管理唐山煤矿，强迫矿工为日军生产煤炭，克扣工资，镇压矿工罢工，致多起矿难。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
