REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4c6ec48b14d35db9a7441c63256666c3', '图布升吉尔格勒', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪郡王旗（今伊金霍洛旗）扎萨克', '1938-1945', '', '公开投日，在郡王旗悬挂日本旗，强迫旗民向日军献马献粮，并阻挠成吉思汗陵西迁中的抗日宣传。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bc30a098483b5d089fb9d8e46c9211df', '夏恭', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪大同县知事（兼辖天镇事务）、伪大同省公署参事、伪晋北自治政府主席、伪晋北自治政府主席、伪大同省省长、伪晋北自治政府主席（后并入蒙疆）、伪晋北自治政府主席（驻大同）、伪晋北自治政府副主席、伪晋北自治政府最高委员、伪晋北自治政府（大同）最高委员', '1937-1945', '', '日军占领大同后，出任伪晋北自治政府最高委员，组织维持会，为日军征粮派款，协助建立伪政权。；日军侵占大同后，出任伪晋北自治政府主席，推行奴化教育，组织伪警察协助日军维持秩序，强征民夫修建军事设施。；日军扶植的伪晋北自治政府首脑，驻大同，主持伪政权日常事务，为日军提供粮秣、情报，协助镇压抗日力量。；日军占领大同后出任伪县知事，组织维持会，协助日军建立伪政权，并参与对天镇地区抗日武装的围剿。；1937年日军占领大同后，出任伪晋北自治政府主席，后任伪大同省省长，积极为日军征粮、抓夫，组织伪警察镇压左云等地抗日活动。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d8371b88ce3259b7b3252464e4585980', '奇凤鸣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪达拉特旗东协理', '1939-1945', '', '充当日军傀儡，参与组织伪旗公署，协助日军推行“治安强化运动”，迫害抗日军民。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('48d43b75209b51e7a30d96d4dd8a4319', '奇子祥', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪伊克昭盟盟长、伪蒙古军第2军军长、伪达拉特旗西协理兼保安团长', '1938-1945', '', '蒙古族贵族，投靠日本后任伪伊克昭盟盟长，在鄂尔多斯地区推行日伪统治，强迫牧民缴粮纳税，协助日军清剿抗日力量。；投靠日伪，任伪达拉特旗西协理，配合日军“扫荡”抗日根据地，向日军提供情报并征收粮草。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('349c2c8dff795beaaa9abd88acb394e4', '奇文英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '乌审旗协理、伪伊克昭盟乌审旗代理扎萨克、伪乌审旗保安团长、伪伊克昭盟警备军指挥官、鄂托克旗伪旗长（日伪时期）', '1938-1945', '', '在乌审旗残酷镇压牧民抗日活动，多次袭击八路军骑兵支队，杀害多名革命干部。；与日军及伪蒙疆政府勾结，在乌审旗推行伪蒙疆政策，协助日军征收粮草、马匹，破坏抗日活动，参与围剿中共领导的抗日游击队。；在日本顾问控制下出任伪旗长，推行日伪“蒙疆”政策，强制收缴民间枪支，强迫牧民“捐献”牲畜支持日军，并协助日军镇压反日牧民。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('daa7800f6f0d536db2b4db1f4fbebc90', '奇玉山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '乌审旗保安团团长、伪伊克昭盟乌审旗扎萨克、伪乌拉特后旗保安队队长、伪鄂托克旗保安司令', '1937-1945', '', '在乌拉特后旗为日军效力，协助维持伪政权，镇压当地抗日牧民，征收苛捐杂税。；依附日军，在鄂托克旗设立伪警察所，禁止牧民与抗日武装接触，并参与日军“清边”行动。；投靠日军及伪蒙疆政权，任乌审旗保安团团长，协助日军镇压抗日力量，参与“伊盟事变”中镇压蒙古族人民的反抗，迫害进步人士，强征民夫为日军服务。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7131a0b05ae85c1c99de06bbd99c2f8f', '姚天福', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪猗氏县新民会会长', '1942-1945', '', '利用新民会宣传‘中日亲善’，强迫青年参加伪军训练，并密报抗日活动，导致多名地下党员被捕。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('79bb05de63395319ab27fff095ca2ac8', '姜全我', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪满安东县（今东港市）县长、伪满安东省协和会会长、伪磐石县警务局指导官', '1932-1945', '', '协助日军镇压磐石抗日游击队，多次参与“讨伐”杨靖宇领导的南满抗日武装，抓捕抗日群众并刑讯逼供。；任伪安东省协和会会长，宣传“日满亲善”，组织汉奸团体，配合日军进行思想奴化，收集抗日情报。；原安东县公安局长，投日后任伪县长，协助日军掠夺资源，镇压当地抗日民众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
