REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0da09f00ee6a55878e86adbb70127338', '孙其昌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、河北、辽宁', '吉林、河北、辽宁', '[]', '伪吉林省实业厅长、伪吉林省教育厅长、伪吉林省教育厅长、伪满民生部大臣、伪吉林省民政厅长、伪吉林省民政厅长、伪吉林省长（后期）、伪吉林省民政厅长、伪满民生部大臣、伪吉林省财政厅厅长、伪吉林省财政厅厅长、伪满经济部大臣、伪吉林省财政厅长、伪满伊通县县长、伪满吉林省实业厅厅长、伪满吉林省实业厅长、伪满吉林省教育厅长、伪满吉林省省长、伪满民生部大臣、伪满吉林省省长（继任）、伪满吉林省财政厅厅长、伪满吉林省财政厅长、伪满吉林省财政厅长、伪满民生部大臣、伪满奉天省实业厅长、伪满民生部大臣、伪满民生部大臣（曾涉本溪劳工）、伪满民生部大臣（曾管辖阜新劳工政策）、伪满民生部大臣（涉辽宁）、伪满洲国交通部大臣（曾任吉林省伪省长）、伪满洲国交通部大臣（曾任吉林省长）、伪满洲国吉林省伪省长、民生部大臣、伪满洲国吉林省民政厅长、伪满洲国吉林省财政厅长、伪满洲国实业部大臣、伪满洲国文教部大臣、伪满洲国文教部大臣（曾在长春任职）、伪满洲国民生部大臣、伪满洲国热河省民生厅厅长、伪满洲国财政部大臣、伪满洲国财政部大臣（原辽宁籍）、伪满洲国财政部大臣（辽宁籍）、伪满财政部大臣、伪满锦州省民生厅厅长、伪热河省教育厅厅长、伪热河省教育厅长', '1931-1945', '', '管理伪省财政，为日军侵略战争筹措资金，参与鸦片专卖等掠夺政策。；负责为日军和伪满政权搜刮吉林地区资源，包括丰满水电站建设资金和粮食征购，间接导致当地民众饥荒。；在伊通（今属四平）强征民夫修建军事工事，并配合日军“清剿”抗联杨靖宇部。；原吉林实业界人士，投日后任伪满吉林省实业厅厅长，在四平、伊通等地强占土地，开办日伪企业，掠夺当地资源。；为日军筹措军费，在昌邑强征捐税，掠夺粮食资源，支持侵华战争。……（共涉及46个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
