REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('af38dcd12a6252ce88bc3eb8d4a489a4', '孙润宇', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪冀东防共自治政府司法部长、伪北平市工务局局长、伪北平市财政局局长、伪河北省教育厅厅长', '1935-1945', '', '在北平及昌平强征劳工，修建日军军事设施。；在石景山地区强征各种苛捐杂税，包括“国防献金”，搜刮民财供日军使用。；投日后控制河北教育，在保定各学校推行奴化教育，强迫学生学日语，取缔抗日教材，迫害爱国教师。；在唐山地区设立伪法院，迫害抗日人士，判刑无辜百姓。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d76c106f90b152f096965302c4b30acb', '孙润生', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津', '天津', '[]', '伪天津河东区商会会长', '1938-1945', '', '担任河东区伪商会会长，为日军强制摊派捐款，控制粮食配给，从中牟利，压迫商户和百姓。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c926652ec0d1522e89e96328f99a2fe8', '孙玉堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪桦甸县保安队队长、伪满本溪县保安队队长', '1932-1945', '', '率保安队配合日军在桦甸夹皮沟、老金厂等地围剿抗联第一路军，多次提供日军情报，并杀害抗联侦察员。；本溪县地方武装头目，投日后任保安队长，多次配合日军扫荡本溪、桓仁交界山区，杀害抗联伤员和百姓，抢夺粮食。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('34141ca126ff51c0a4a5eb7a8c5b4040', '孙玉田', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪磐石县司法科科长', '1933-1945', '', '审判并迫害抗日志士，以“反满抗日”罪名判处多人死刑或长期监禁，并协助日军建立“思想矫正院”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('1cf24e0dd2285d7b95a248b021456e1c', '孙百魁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满洲国锦州省教育厅长、伪满瓦房店维持会会长、伪满盘山县保安队队长、伪满绥中县警察署长、伪满连山警察署署长、伪满锦县警察署长、伪满阜新县警务科长、伪锦州省教育厅厅长', '1931-1945', '', '九一八后组织瓦房店维持会，协助日军建立地方伪政权，镇压当地抗日民众。；盘山土匪出身，被日伪收编后任保安队队长，在盘山、大洼一带袭击抗日游击队，烧毁村庄。；指挥伪警察在绥中（今葫芦岛）抓捕抗日地下党员，破坏抗日组织。；在锦州省（含绥中）推行奴化教育，篡改历史，强迫学生学日语。；原地方警察，投日后任连山地区伪警察署长，直接执行日伪“治安肃正”，逮捕、刑讯抗日嫌疑人员，参与“大检举”行动。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('359f67e3978f550ebc17a547be54484a', '孙耀宗', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪广灵县警备队副队长、定襄县伪教育科科长、景县伪自卫团团长', '1940-1945', '', '率警备队配合日军在广灵县东部山区“扫荡”，烧毁村庄多处，并参与杀害八路军伤病员和抗日群众，1943年在暖泉镇附近伏击抗日游击队。；推行日伪奴化教育，强制学校使用伪满教材，迫害爱国教师，解散抗日小学。；率自卫团配合日军“清乡”，在景县南部地区抓捕抗日家属，抢劫粮食，破坏地道，杀害多名抗日民兵。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fdc924a005d9538a8da27a0094bf8f69', '孙耀庭', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北、辽宁', '山西、河北、辽宁', '[]', '伪交城县保安团长、伪代县警备队副队长、伪垣曲县警备队小队长、伪大同宪兵队密探（阳高籍）、伪天镇县警备队队长、伪宽甸县协和会会长、伪满凤城县警务科科长、伪满开原县警务科科长、伪满盖平县教育局长、伪盐山县保安队副官、伪石家庄特务机关情报员、伪运城警察局局长、夏县伪情报组组长、太谷县伪税务局局长、运城伪警备队副队长', '1934-1945', '', '在交城县率伪军参与“清剿”，杀害抗日村长。；率警备队多次袭击八路军游击队，杀害抗日干部，并参与日军“三光”政策，烧杀抢掠。；充当日军宪兵队密探，多次告密破坏地下抗日组织，致使数十名抗日志士被捕牺牲。；参与日军“三光”政策行动，在代县山区烧毁村庄，屠杀无辜百姓，多次带队突袭抗日根据地。；为日军征收各种苛捐杂税，强征粮食和棉花，导致百姓负担沉重，部分物资被转运至日军军需。……（共涉及16个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b46657ea48515d69991ec5ab9ccca515', '孙耀祖', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '交城县伪新民会会长、伪太原县（今太原市晋源区）知事、唐山伪新民会会长、平陆县伪区公所区长、浮山县伪警备队中队长、灵丘县伪区公所区长（东河南区）、灵石县伪新民会会长', '1938-1945', '', '率伪警备队驻守浮山重要据点，多次伏击抗日游击队，并参与“清乡”行动，杀害抗日群众十余人。；宣扬“中日亲善”，组织奴化教育，诱骗青年参加伪军，破坏抗日宣传。；协助日军建立“无人区”，强拆民房，驱赶百姓，为日军提供向导和粮食。；在太原县（含娄烦部分地区）推行日伪统治，强征劳工，参与“治安强化运动”。；推行奴化教育，宣传‘中日亲善’，强迫学生和民众参加反共集会。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6e7674650d00594ca6dfbef4d3f3e1cd', '孙老万（孙玉堂）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪清苑县警察局局长', '1940-1945', '', '指挥伪警察镇压抗日活动，破坏交通线，逮捕并杀害抗日游击队员。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0dd3beb27d8b597baf7b6be86e893586', '孙良诚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北', '天津、河北', '[]', '伪“第二方面军”总司令（活动于冀南）、伪冀东绥靖军司令（后期）、伪第2方面军总司令（曾率部在保定满城一带驻防）、伪第二方面军总司令（后投日）、伪第二方面军总司令（投日后）、伪第二方面军总司令（投日）、伪第二方面军总司令（曾辖冀东）、伪第二方面军总司令（曾驻沧县）、伪第二方面军总司令（活动于冀南）、伪第二方面军总司令（活动于邢台周边）、伪第二方面军总司令（活动区域含邢台沙河）、伪第二方面军总司令（活动涉及天津）、伪第二方面军总司令（涉冀中活动）', '1942-1945', '', '率伪军在天津郊区及武清一带驻防，协助日军“清剿”。；原西北军将领，1942年投日，其部队在河北南部、山东北部活动，参与“扫荡”冀鲁豫根据地。；率伪军数万人在冀中、冀西地区包括满城，配合日军进行“铁壁合围”扫荡。；率伪军在唐山沿海地区布防，对抗登陆盟军和游击队。；投日后其部队曾调至冀东，在唐山、芦台一带协助日军维持占领区秩序。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a17bc27105825aaa88d762386e014d62', '孙良诚（注：投敌后活动范围含冀南）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪第2方面军总司令（后）', '1942-1945', '', '原西北军将领，投敌后在冀南包括巨鹿地区参与“扫荡”，为日军效力。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
