REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('01580a2207fc546097fc33e00c2593b9', '孙鸣山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪满东辽县（今东辽）协和会事务长、伪满辽源县协和会会长、伪满铁岭县清河区区长', '1935-1945', '', '负责协和会宣传，推行奴化教育，煽动民众“日满亲善”，并监视举报抗日分子。；在辽源县（今双辽市）推行奴化教育，组织“协和会”宣传“日满亲善”，强迫民众捐献铜铁支援日军，并告密检举反满抗日分子，导致多名爱国人士被捕。；推行伪满‘保甲连坐’制度，强迫村民报告抗日分子行踪，并贪污勒索百姓，为日军征收军粮。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ae439c952b755ce79276f3910133a3a2', '孟兴富', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '太谷县伪保安队队长、晋中地区伪警备队副队长', '1938-1945', '', '率伪保安队配合日军扫荡抗日根据地，抓捕抗日干部和群众，制造多起惨案。；在太谷、祁县一带活动，多次带伪军袭击八路军游击队，杀害抗日干部，抢夺物资。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
