REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('339f46e7579656509d15816c94529804', '宋占魁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪屯留县特务队队长、伪曲周县第二区区长', '1940-1945', '', '专门刺探八路军情报，带领特务队突袭抗日村庄，逮捕并杀害抗日积极分子。；在曲周县第二区（今河南疃一带）为日军效力，强抓壮丁补充伪军，并强迫村民报告八路军行踪，致使多名游击队员牺牲。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
