REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2710b9044e6f55db81b6f17fdc6bd2f6', '宋文彬', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '壶关县伪情报组组长', '1940-1945', '', '专门刺探八路军和抗日政府情报，多次向日军告密，导致抗日人员被捕牺牲。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('57214b348cec5d359040630a87a35553', '宋殿元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪任县特务队队长、伪广灵县特务队队长、伪张北县知事、冀县（今属衡水）伪警备队队长、枣强县伪自卫团团长、隆平县伪税务局局长', '1938-1945', '', '专门负责刺探八路军情报，带领特务队破坏抗日交通线，曾抓捕并杀害抗日村长数人，其特务队以手段残忍著称。；原为张北县劣绅，投日后任伪知事，在察北地区推行日伪“治安强化运动”，强征壮丁，搜刮民财。；率自卫团配合日军‘铁壁合围’，在枣强南部多次袭击抗日游击队，杀害多名抗日战士。；组织伪自卫团，配合日军“铁壁合围”，袭击抗日武装，残害抗日家属。；在冀县及周边地区抓捕抗日军民，提供情报给日军，参与杀害抗日干部，民愤极大。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('be7d76df9e2759f39ebc33743a83dba0', '宋澈', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪山西省财政厅厅长', '1938-1943', '', '负责伪省财政，为日军搜刮民财，发行伪币，控制经济命脉。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ebd8c2759c7f5b8eb6616cc20bf49456', '宋维周', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪赤城县知事（县长）', '1938-1943', '', '在赤城任伪县长期间，强征民夫修炮楼、修公路，为日军提供粮食和情报，镇压抗日活动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
