REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('57b3f7e086c05324a1fbd81a9797e6b8', '崔培德', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪潞城县新民会会长、伪获鹿县维持会会长、伪长治县知事（兼管长子部分区域）、伪霸县警备大队长、伪高碑店新民会会长', '1937-1945', '', '推行奴化教育，组织“新民会”宣传“中日亲善”，诱骗青年参加伪军，破坏抗日宣传。；在长治、长子交界地区推行“连坐法”，强迫百姓报告八路军行踪，导致多名抗日群众被日军杀害。；负责在占领区推行奴化教育，组织“新民会”宣传“中日亲善”，刺探抗日情报，协助日军抓壮丁。；率警备队多次突袭抗日村庄，活埋抗日军属，并强迫青年加入伪军。；日军占领获鹿初期，组织维持会，为日军带路搜捕抗日分子，强征民夫修炮楼。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d34e7c17c41559c79a3fd4e024c4b7e6', '崔培成', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪上党地区剿共司令、伪晋城县保安队副队长、伪潞城县保安队队长、伪长治县保安队大队长、伪长治县维持会会长、伪高平县新民会会长、伪高平县知事', '1938-1945', '', '在高平组织“新民会”分会，煽动民众脱离抗日阵营，为日军提供劳役。；参与制造“晋城大屠杀”事件，率伪军烧毁村庄，杀害无辜百姓。；组织维持会为日军筹粮派款，强迫百姓领取“良民证”，告密导致多名抗日群众被捕牺牲。；组织伪军专门围剿八路军游击队，制造多起惨案，杀害抗日群众。；率部投敌，担任伪保安队长，多次配合日军袭击八路军游击队，在潞城、长治一带烧杀抢掠，民愤极大。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('83172481bfd9558ca6bef6cdd50f35df', '崔子明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪三河县保安队副队长', '1942-1945', '', '协助日军在泃河沿岸设立据点，抓捕抗日群众，严刑逼供，并参与“无人区”制造行动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
