REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f755416a4e3a5db7bd2d187663706fd1', '巴图巴雅尔', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪乌拉特后旗旗长（日伪任命）、伪达拉特旗扎萨克（旗长）', '1937-1945', '', '在日伪统治下担任旗长，推行‘保甲制度’，强迫牧民供粮供畜，配合日军‘治安肃正’。；投靠日军，在达拉特旗推行“保甲制度”，强征壮丁补充伪军，并配合日军对黄河以南地区进行经济封锁。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
