REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6b5fb4ffaaaf5d6baf9d53a79ad37110', '巴布扎布', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪兴安南省警备军司令', '1933-1945', '', '科尔沁左翼后旗人，蒙古族。投靠日军后任伪警备军司令，多次率伪军袭击抗日武装，协助日军建立“集团部落”，制造无人区，强征牧民从军。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
