REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('800c27d2c31954e785359168edd38e70', '巴雅尔', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪兴安北省参事官、伪满洲国兴安东省莫力达瓦旗旗长', '1932-1945', '', '作为日伪政权在呼伦贝尔的蒙古族官员，积极推行“日蒙亲善”宣传，协助日军收编地方武装，破坏抗日联军活动。；在莫力达瓦地区任伪旗长，强制征收粮食和牲畜，为日军提供物资，镇压当地达斡尔族抗日活动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
