REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('82c58542799b5680a1203da303a728ce', '常守陈', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满本溪县警务科科长、伪满本溪湖警察署署长', '1933-1945', '', '在本溪、南芬地区任伪警察署长，多次率伪警配合日军“讨伐”抗联，抓捕并杀害抗日群众，制造多起惨案。；本溪县汉奸，负责指挥伪警察和特务，多次带队袭击抗联小分队，抓捕并杀害抗日群众，在桓仁与本溪交界地区活动频繁。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0ec2ee6fed265ec5991932a6ff128192', '庞炳勋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北', '天津、河北', '[]', '伪“冀察战区”总司令（投敌后驻邢台）、伪冀察战区总司令（投敌后）、伪华北治安军第二集团军司令（活动于冀东）、伪河北省保安司令（兼涉沧州地区）、伪河北省保安司令（兼驻石家庄）、伪河北省保安司令（名义上管辖涞源）、伪河北省保安司令（曾涉元氏地区）、伪河北省保安司令（曾督战邢台、平乡地区）、伪河北省保安司令（曾辖保定地区）、伪河北省保安司令（管辖衡水地区）、伪河北省保安司令（驻石家庄）、伪第24集团军总司令（后投日）、伪第24集团军总司令（曾辖保定地区伪军）、伪第24集团军总司令（活动范围含满城）、伪第二十四集团军总司令（投敌）、伪第二十四集团军总司令（活动涉及天津周边）、伪第二十四集团军总司令（活动涉及邯郸地区）、伪第五方面军总司令（1943年投敌后）、伪第五方面军总司令（名义上辖冀中）、伪第五方面军总司令（后投日）、伪第五方面军总司令（投日后）、伪第五方面军总司令（投日）、伪第五方面军总司令（曾辖冀东）、伪第五方面军总司令（曾驻邢台）、伪第五方面军总司令（曾驻防石家庄地区，影响赵县）、伪第五方面军总司令（活动于邯郸、武安地区）、伪第五方面军总司令（活动于邯郸南部）、伪第五方面军总司令（活动范围含冀南）、伪第五方面军总司令（活动范围含唐山）、伪第五方面军总司令（涉冀中活动）、伪第五方面军总司令（涉衡水地区）', '1943-1945', '', '投敌后参与对天津周边抗日力量的围剿，在武清设有据点。；原国民党第24集团军总司令，1943年在太行山被俘投日，其部队活动范围涉及河北南部，协助日军进攻冀鲁豫根据地。；投敌后任伪职，其部队在保定、徐水等地配合日军清剿抗日力量，参与“无人区”建设。；投敌后任伪职，其势力范围名义上包括冀中，但实际未直接驻军望都，仅通过伪政权间接控制。；1943年投降日军后任伪职，其势力范围波及保定西部山区，曾派伪军协助日军对涞源根据地进行“扫荡”，但本人未常驻涞源。……（共涉及31个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
