REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('340adba25424535985417eba5e18abbe', '张仁蠡', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、河北', '北京、天津、河北', '[]', '伪冀东道尹、伪冀东道尹、伪唐山市长、伪冀东道尹、伪河北省公署顾问、伪冀东道尹、伪河北省政府顾问、伪冀东道尹公署道尹（辖唐山）、伪冀东道尹（继任）、伪冀东道尹（驻唐山）、伪冀东防共自治政府民政厅厅长、伪冀东防共自治政府民政厅长、伪河北省民政厅长、伪冀东防共自治政府民政厅长（曾管辖卢龙地区）、伪冀东防共自治政府民政厅长（曾驻秦皇岛）、伪冀东防共自治政府财政厅厅长、伪冀东防共自治政府财政厅长、伪冀东防共自治政府财政厅长、伪华北政务委员会委员、伪北平市工务局局长、伪北平市市长、伪北平市市长（1943-1945）、伪北平特别市市长（1943-1944年）、伪北平特别市市长（后任伪华北政务委员会实业总署督办）、伪北平特别市警察局督察长（分管郊区）、伪华北政务委员会唐山专员、伪唐山市长、伪天津市地方法院院长、伪天津市市长、伪天津市市长、伪河北省省长、伪天津市市长（1943-1945）、伪天津市警察局局长、伪天津市长（后期）、伪天津特别市公署参事、伪河北省公署厅长、伪天津特别市公署秘书长、伪天津特别市公署秘书长、伪河北省长、伪天津特别市公署财政局局长、伪天津特别市市长、伪天津特别市市长（1943-1945）、伪宝坻县知事、伪怀柔县知事、伪昌黎县新民会会长、伪河北省公署参事、伪河北省公署参事（分管石家庄）、伪河北省公署民政厅厅长、伪燕京道尹、伪河北省政府教育厅长、伪华北政务委员会教育总署督办、伪河北省省长（驻天津）、伪河北省长（驻保定，管辖石家庄）、伪滦县知事、伪石家庄商会会长、伪石家庄市市长、伪顺义县知事（县长）、冀东防共自治政府民政厅长、冀东防共自治政府财政厅长', '1931-1945', '', '投日后任伪北平市长，管辖包括丰台在内的北平地区，推行日伪法令，强征物资。；专门负责大兴、宛平等郊县“剿共”，指挥伪军警突袭村庄，逮捕抗日家属。；投靠日伪政权，任怀柔县知事，协助日军推行保甲制度，强征民夫，搜刮粮食，镇压抗日活动。；在任期间推行日伪统治政策，协助日军征粮、强征劳工，镇压抗日活动。；原北洋官僚，投日后任伪北平市长，管辖包括昌平在内的北平郊区，配合日军征粮、抓夫和“治安强化”运动。……（共涉及75个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8d44c641d282550ba82bc5cc430bd204', '张仁蠡（重复？不，另列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪河北省公署参事', '1940-1945', '', '参与策划廊坊地区“治安强化”具体措施，并督导各县伪政权执行。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('df76bd35c1da5cac8084efee90ca5b9e', '张从虞', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪泽州县知事（日占时期）', '1940-1945', '', '充当日军傀儡，推行保甲制度，强征粮税，抓捕抗日军民。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('abfbfc55b2075575b7abe7d534e7196d', '张从龙', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '乡宁县伪县长、伪临汾县维持会副会长、伪古县维持会会长、伪壶关县知事、伪泽州县保安队队长、伪潞安府（长治）警备司令、伪翼城县维持会会长、伪阳城县保安队大队长、浮山县伪县长、蒲县维持会会长', '1938-1945', '', '协助日军建立伪政权，为日军筹集粮款，强迫百姓领取“良民证”，举报抗日群众。；任日伪乡宁县县长期间，协助日军推行“治安强化”运动，强征民夫修筑碉堡公路，搜刮粮食资敌，镇压抗日群众。；在古县地区组织维持会，协助日军征粮派款，出卖抗日积极分子，破坏地下抗日组织，导致多名群众被捕遇害。；任浮山县伪县长期间，积极推行日伪政权各项政策，组织维持会，协助日军征粮派款，镇压抗日民众，破坏地下抗日组织。；任浮山县伪县长期间，积极推行日伪政权，组织维持会，协助日军扫荡抗日根据地，强征民夫粮食，镇压抗日群众。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2263cc4d807b589b840da11fa34004e0', '张仲权', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '井陉县伪保安联队队长、井陉矿伪矿长、伪井陉县知事', '1938-1945', '', '组织伪保安队配合日军扫荡抗日根据地，多次袭击八路军游击队，杀害抗日干部和群众。；充当日军控制的井陉煤矿伪矿长，为日军掠夺煤炭资源服务，迫害矿工，破坏抗日活动。；在井陉县（含矿区）推行日伪法令，强征民夫修路筑堡，协助日军封锁抗日根据地。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f474844398ef565e831bb9e00cf88467', '张仲瀚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪博野县知事、博野县伪县长（后投敌）', '1939-1942', '', '投靠日军，任伪博野县知事，推行保甲制度，强征粮税，镇压抗日群众，提供情报给日军。；原国民党地方官员，日军占领博野后投敌任伪县长，协助日军推行保甲制度，强征粮款，镇压抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('640820bdaeb25863af8821fd34a2e654', '张仲直', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京', '北京', '[]', '伪北平市卫生局局长、伪北平市财政局局长', '1938-1945', '', '在北平（含昌平）推行防疫政策，实际为日军细菌战研究提供掩护。；为伪政权征收苛捐杂税，搜刮民脂民膏。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0a8c29b827d05c028af1cca7216bfdda', '张体乾', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪山西省新民会总务部长', '1939-1945', '', '推行新民会奴化宣传，组织“青少年团”洗脑，破坏抗日群众组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d0e664126d8a5ba2b536d423f7ba306e', '张体仁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪太原市建设局局长、伪清源县知事（太原属县）', '1939-1945', '', '在清源县（今清徐）为日军征粮派夫，镇压当地抗日活动。；主持扩建日军机场、兵营，强拆民房，征用土地，造成大量平民流离失所。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('cae7ed07fd9a53f5a770fcacdd2a6df2', '张体安', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪大名县新民会会长', '1941-1945', '', '推行奴化教育，宣传‘中日亲善’，强迫民众参加新民会，搜集抗日情报。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2a816e97326c5210bdec3a2c3af8c214', '张作相', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满兴城（今属葫芦岛市）维持会长、伪满参议府参议（曾涉辽宁地区）、伪满洲国顾问（名义）、伪满盘山县协和会会长、伪满铁岭地区维持会会长', '1931-1945', '', '盘山士绅，投靠日伪后任协和会会长，宣传“日满亲善”，组织青少年奴化训练，破坏抗日地下组织。；九一八后短暂组织地方维持会投靠日军，后因内部矛盾被撤换，但初期协助日军稳定占领秩序。；虽未任实职，但公开支持伪满，其旧部在辽宁绥中地区协助日军维持秩序。；原铁岭县士绅，九一八后组织维持会迎接日军，后任伪职，为日军征粮派款，协助稳定伪政权。；原奉系将领，虽名义上未任伪职，但实际与日伪合作，其旧部在鞍山、岫岩地区组织伪军，间接助敌。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('cf3c9b6e24695f41a0a08a27ad3fe1ad', '张作相（投敌后改名张辅臣）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪锦州协和会会长', '1934-1945', '', '利用协和会组织在锦州、北镇地区进行奴化宣传，强迫民众参加“日满亲善”活动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
