REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2d3f1049f4d652d2bf080a28051212d4', '张俊杰', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北、辽宁', '河北、辽宁', '[]', '伪冀东防共自治政府滦州新民会会长、伪满凤城县协和会分会长', '1935-1945', '', '在滦州组织新民会，推行奴化运动，破坏抗日统一战线。；原凤城商人，投日后任伪满凤城县协和会分会长，在凤城地区组织汉奸宣传队，为日军募集物资和慰劳品。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fa4ea0e602c55a969e3994a7004dc4ce', '张俊杰（同名）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府滦州宣抚班长', '1935-1938', '', '在滦州农村进行“宣抚”，欺骗农民归顺日伪。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('379eda215a9d5db19255e34763805522', '张允恺', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津', '北京、天津', '[]', '伪塘沽特别区行政长官、伪天津市财政局局长、伪昌平县保安队队长、伪通州新民会会长', '1938-1945', '', '率伪保安队配合日军“扫荡”昌平西山抗日根据地，杀害无辜百姓。；组织新民会宣传“中日亲善”，刺探抗日情报，协助日军进行思想控制。；为日军搜刮民财，发行伪币，控制天津金融，掠夺资源支持侵华战争。；管辖塘沽（今滨海新区核心区），为日军控制塘沽港口，协助转运军需物资，强征码头工人，镇压劳工反抗', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6b71c1f8a88e55d88a22726eee2c52e9', '张允荣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北', '天津、河北', '[]', '伪冀东道尹公署参议（活动于唐山地区）、伪冀东防共自治政府天津办事处主任、伪天津特别市公署财政局局长、伪天津特别市社会局局长、伪天津特别市警察局局长', '1935-1945', '', '在天津及东丽地区建立特务网络，抓捕抗日志士，协助日军宪兵队进行残酷镇压。；在天津为伪冀东政权服务，协助日军控制天津地区，破坏抗日活动。；为伪政权征收苛捐杂税，搜刮民财，资助日军战争。；控制社会团体，强制推行“治安维持会”制度，迫害进步工人和市民。；参与冀东伪政权决策，在玉田等地推行“保甲连坐”制度。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('69700836f44b5c3fb8c16533fdb1ffa6', '张全有', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪左权县密探', '1943-1943', '', '跟踪八路军通信员，导致信件被截，两名通信员牺牲。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c8a9c29e369f57e68813df6578a00af4', '张冠英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪唐山特别市公署市长', '1938-1941', '', '1938年唐山设市后任伪市长，全面推行日伪统治，控制工商业，强征劳工，为日军提供煤炭等战略物资。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('267c4c0541f451f4b0161af4599ddaee', '张凤阁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪承德县保安队副队长、伪海兴县知事、伪青龙县警务科科长', '1935-1945', '', '在鹰手营子矿区一带设卡盘查，抓捕抗日交通员，参与多次突袭抗日根据地的行动。；在海兴县为日军效命，组织伪军封锁沿海，破坏抗日交通线。；指挥伪警察队配合日军“扫荡”抗日根据地，抓捕并杀害抗日干部和群众，破坏中共地下组织，参与制造多起惨案。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7e667a99334858eea8a000540b9ebeaf', '张凤鸣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪榆社县警备队副队长、伪获鹿县保安联队队长、无极县伪保安联队队长、沁县伪维持会会长', '1938-1945', '', '充当日军走狗，参与多次清乡行动，杀害抗日干部和群众，抢劫民财。；日军初占沁县时出任维持会长，为日军筹集粮款，强迫百姓‘欢迎皇军’，并告密抗日活动。；率伪军多次配合日军袭击无极县抗日武装，杀害抗日干部和群众，参与制造多起惨案。；率伪军多次扫荡抗日根据地，杀害抗日干部和群众，烧毁村庄，为日军提供情报，是当地罪大恶极的汉奸武装头目。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('98f434e5c4be544dbf5b4ac887efc5c9', '张化南', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北', '天津、河北', '[]', '伪三河县知事、伪冀东道尹（驻廊坊）、伪北戴河海滨自治区区长、伪宝坻县新民会会长、伪沧州警察局局长、伪获鹿县（今鹿泉区）知事、广平县伪保安联队队长、成安县伪保安联队队长、涞水县伪保安联队长', '1938-1945', '', '推行新民会奴化宣传，组织青少年训练，搜集抗日情报，破坏抗日群众组织。；组织伪保安队，配合日军扫荡抗日根据地，多次袭击八路军游击队，杀害抗日干部和群众。；在三河县推行“粮食统制”，搜刮民财，并组织汉奸武装“反共自卫团”袭击游击队。；管辖廊坊及周边县份，推行保甲制度，组织“反共自卫团”，协助日军封锁抗日根据地。；指挥伪警察抓捕抗日群众，严刑逼供，破坏地下交通线。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('12d5865ea83d5413ac977e2f3894dcf5', '张十五', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪左权县密探', '1944-1944', '', '侦察八路军骑兵队动向，导致骑兵队遭伏击，损失战马。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2fda53d745ef5b628faa09b1bf9d87a3', '张十斤', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪左权县密探', '1943-1943', '', '报告八路军开会地点，导致会议被袭，3名干部牺牲。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2bfd7cea97c4576bb7e91c332d0275e3', '张占元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北、辽宁', '河北、辽宁', '[]', '伪满洲国兴城地区自卫团团长、伪获鹿县保安团团长、伪高阳维持会会长、晋县伪税务局长', '1933-1945', '', '日军占领高阳后出任维持会长，为日军征粮派夫，协助建立伪政权。；为日伪征收苛捐杂税，盘剥农民，逼交“治安费”，导致多户农民破产。；率伪保安团在鹿泉山区多次袭击抗日武装，烧毁村庄，杀害抗日军属。；兴城本地地主，组织伪自卫团，为日军提供情报，参与抓捕抗日地下人员，强征壮丁。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('dd16228ed77d5347a9db49d43cc1ddae', '张启祥', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪兴和县警察署署长、伪包头商会会长、伪包头维持会会长、伪卓资县维持会会长、伪商都县警察署署长、伪归绥市警察局局长', '1937-1945', '', '在兴和县任伪警察署长，抓捕抗日军民，严刑逼供，直接参与多起屠杀事件。；日军占领卓资后出任维持会长，为日军征粮派款，组织伪保甲制度，协助日军“扫荡”周边村庄。；充当日军爪牙，在商都地区抓捕抗日志士，破坏地下组织，协助日军进行“清乡”行动。；日军占领包头初期，主动出任维持会长，为日军筹集物资，组织汉奸队伍，协助日军建立伪政权。；为日军筹措军费，垄断白云鄂博矿石运输，向日本军方提供经济支持，剥削当地商民。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ddd9ed2fe3715ecba59595c0c631a33f', '张嘉琳', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪山西省保安司令部副司令、伪山西省教育厅厅长', '1938-1945', '', '主管伪教育，推行奴化教育，强制学校教授日语，篡改历史教材。；指挥伪保安队配合日军“扫荡”，围剿八路军游击队，残害抗日军民。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
