REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('735f2c7287ba53d5b95c7305e345236b', '张子元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪东光县保安联队队长、伪衡水县知事、冀县伪县长、安平县伪县长、枣强县伪县长、武强县伪县长、武邑县伪县长、深县伪县长、阜城县伪县长、饶阳县伪县长', '1937-1945', '', '组织伪保安队配合日军扫荡，捕杀抗日干部和群众，制造多起惨案。；任冀县伪县长期间，积极推行日伪政权，协助日军征粮派款，镇压抗日群众，破坏抗日组织。；投靠日军，任安平县伪县长，协助日军推行“治安强化运动”，镇压抗日群众，征收苛捐杂税，提供情报给日军。；投靠日军，任安平县伪县长，协助日军推行“治安强化运动”，镇压抗日群众，征收苛捐杂税，为日军提供粮食物资。；投靠日军，任枣强县伪县长，协助日军推行‘治安强化运动’，强征民夫，搜刮粮食，镇压抗日群众。……（共涉及14个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c36ed77fe8ef552bb6bb631a999ac31f', '张子奇', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪保德县保安队队长、伪太原市商会会长（古交籍）、伪山西省政府建设厅厅长（涉及吕梁）、伪清徐县警察所所长、伪石楼县警备队长、伪运城警备司令、河津县伪县长', '1938-1945', '', '在石楼县（今吕梁石楼县）率伪军抢劫百姓，配合日军扫荡。；在吕梁地区推行日军资源掠夺政策，强占煤矿铁矿，强迫劳工开采，并克扣劳工口粮。；为日军收购古交地区煤炭和铁矿，资助伪军，从中牟利。；指挥伪警察抓捕抗日干部，破坏地下交通线，参与“清乡”行动。；组织伪保安队，多次袭击八路军游击队，抓捕抗日群众并送交日军宪兵队，参与杀害抗日干部。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
