REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d844b2aa7baa5a3288f89eb4dd6f9a99', '张子良', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪冀东防共自治政府滦州卫生局长、伪南皮县保安联队副队长、伪吴桥县保安联队队长、伪文安县知事、伪沧县知事、伪河间县知事、伪渤海盐务缉私队长、伪盐山县知事、伪盐山县维持会会长、伪盐山（含海兴）警备大队长、伪青县维持会会长、冀南道伪军司令、方山县伪保安队队长、枣强县伪县长', '1935-1945', '', '率伪保安队多次配合日军扫荡方山抗日根据地，杀害抗日干部和群众，烧毁村庄，抢夺粮食牲畜。；配合日军在滦州进行细菌实验，掩盖日军暴行。；在文安洼地区配合日军水陆扫荡，破坏抗日苇塘根据地，杀害多名区干部。；在盐山地区积极效忠日军，组织伪警察队，参与“清乡”行动，掠夺民间财物。；日军占领盐山后率先组织维持会，为日军筹粮派款，强拉壮丁充实伪军，并指使汉奸特务破坏抗日地下组织。……（共涉及15个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b15a3c6d25775cc6ac5a88c09fc3f501', '张子良（同名）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府滦州医院院长', '1935-1938', '', '在滦州医院为日军提供伤员治疗，拒绝救治抗日伤员。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4b44196ebbb85fbb8636127b445d8f1c', '张子英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪吕梁山区剿共司令、伪永和县保安队队长、伪神池县保安队队长、定襄县伪警察所所长', '1939-1945', '', '率伪保安队配合日军扫荡永和及周边地区，多次袭击抗日游击队，抓捕并杀害抗日军民，掠夺粮食资敌。；率伪军配合日军在吕梁山区多次围剿八路军，杀害抗日军民。；为日军搜集情报，破坏地下抗日组织，参与屠杀抗日志士。；率伪保安队多次配合日军扫荡抗日根据地，抓捕抗日干部和群众，杀害八路军伤员，抢劫百姓财物。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9df111dbb24a5363a5c0158aaba434ae', '张子谦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '临县伪维持会会长、五寨县伪警察局局长、伪猗氏县知事、伪祁县警备队大队长、忻州伪公署顾问', '1939-1945', '', '组织维持会为日军筹集粮款，强迫村民领取“良民证”，告密抗日活动，导致多名群众被捕。；任伪警察局长，为日军搜集情报，破坏抗日地下组织，参与‘清乡’行动。；原为忻州士绅，后投敌任伪公署顾问，为日军出谋划策，推行“治安强化”运动，破坏抗日地下组织。；率警备队袭击祁县抗日区公所，抓捕抗日家属，勒索钱财，民愤极大。；任伪猗氏县知事期间，为日军提供粮秣情报，参与‘清乡’行动，抓捕抗日干部及家属，并强迫百姓领取‘良民证’。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f062d56b5e5956c1bc3c8c7712a08093', '张孤', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津', '天津', '[]', '伪华北政务委员会天津办事处主任、伪天津特别市财政局局长', '1938-1945', '', '负责协调伪政权与日军关系，推行“治安强化运动”，协助日军征粮和劳役。；负责协调日伪在天津的行政事务，推行“治安强化运动”。；负责为日伪政权搜刮天津财税，发行伪币，掠夺民间财富，支持日军战争经济。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('61b56ec28fc8552bbb96bcd0bb9dd4c1', '张守义', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪临汾县粮秣征收处主任、伪临汾县警察局局长、伪平顺县保安队队长、伪沁县警察所所长、伪沁源县警备队副队长、伪潞城县警察所所长、伪芮城县保安队队长、伪长治县保安团副团长、伪长治县警备队副队长、伪阳高县警察局局长、壶关县伪警察局局长', '1938-1945', '', '指挥伪警察，搜捕地下党员，严刑逼供，杀害抗日志士。；负责为日军征收粮食，在翼城、临汾交界地区强征暴敛，导致百姓饥荒。；效忠日军，指挥伪警察抓捕抗日军民，参与多次“清乡”行动，残害无辜百姓。；率伪军配合日军扫荡抗日根据地，抓捕并杀害抗日军民，抢劫百姓财物。；效忠日伪政权，负责搜捕抗日地下党员，严刑逼供，破坏抗日组织，并参与“清乡”行动。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f0baa384725151ad9fb99cef1a20fe7c', '张守仁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪平遥县警察所所长、伪荣河县知事', '1939-1945', '', '效忠日军，破坏地下抗日组织，逮捕并刑讯逼供抗日志士，提供情报协助日军突袭。；在荣河县（今属万荣）任伪县长期间，配合日军“扫荡”抗日根据地，组织伪警备队抓捕抗日军民，并推行保甲连坐制度。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5635de6ec8b954938e4177b1f1011954', '张守信', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪朔县保安大队长、伪浑源县保安队队长', '1938-1945', '', '率领伪保安队配合日军扫荡抗日根据地，多次袭击八路军游击队，杀害抗日干部和家属，并参与“清乡”行动。；在朔县、怀仁交界地带活动，率伪军多次袭击八路军武工队，杀害抗日家属，抢劫群众财物，充当日军“扫荡”帮凶。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('762e0b9ffb6359e2a7ffa4a6cc071aa0', '张宗援', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北、辽宁', '河北、辽宁', '[]', '伪冀东防共自治政府保安队头目/伪军头目、伪冀东防共自治政府保安队头目（活动于沧州一带）、伪冀东防共自治政府保安队头目（活动于盐山一带）、伪冀东防共自治政府沧州地区顾问、伪华北治安军独立旅旅长、伪满凤城县（今凤城市）县长、伪满安东省协和会会长、伪满洲国大连宪兵队翻译官、伪满洲国安东省（今丹东）省长（原辽宁籍）、伪满洲国旅顺要塞司令、伪满锦州省宪兵队队长', '1931-1945', '', '原为土匪，后投靠日军，在沧州、孟村一带组织伪军，多次参与对回民支队和抗日根据地的“围剿”，烧杀抢掠，残害抗日军民。；驻防沧州及渤海湾，配合日军扫荡，强征民粮，杀害抗日家属。；原为土匪，后投靠日军，在盐山、庆云等地组织伪军，袭扰抗日武装，制造多起惨案。；原名伊达顺之助，日本浪人，后改华名，在沧州、盐山地区组织伪军，配合日军进攻抗日武装，残害百姓。；协助日军在沧州推行“治安强化运动”，建立伪保甲制度，强征民夫修筑炮楼。……（共涉及12个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3a45ae481bcf5efd8ec8b12228da26e3', '张宗援（伊达顺之助）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满洲国“奉天地区”日籍顾问兼伪军头目', '1931-1945', '', '日本浪人，加入伪满军队，在辽宁锦州、兴城一带指挥伪军“讨伐”抗日武装，手段残忍，制造多起血案。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b2e08518b85d5648aa0d76e9f152d677', '张岚峰', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北', '天津、河北', '[]', '伪“和平救国军”第一军军长（活动于冀南）、伪冀东保安司令（后期）、伪冀南道尹、伪临清县知事、伪华北绥靖军第一军军长（辖区含沧州）、伪和平救国军第1军军长、伪和平救国军第一军军长（曾驻衡水）、伪和平救国军第一军军长（曾驻防冀南）、伪和平救国军第一军军长（活动于冀南）、伪第1军军长（豫皖鲁冀边区）、伪第二集团军司令（曾驻保定）、伪第二集团军司令（涉衡水地区）、伪第二集团军总司令（活动区域含邢台）、伪第四方面军总司令（后投日）、伪第四方面军总司令（投日后）、伪第四方面军总司令（曾涉冀东）、伪第四方面军总司令（活动于冀南）', '1938-1945', '', '原西北军将领，投日后在河北、河南边界驻防，协助日军封锁抗日根据地。；率伪军驻扎保定地区，配合日军对蠡县进行军事清剿，强征民夫修筑工事。；在唐山地区扩充伪军，镇压抗日力量，直至日本投降。；虽主要驻河南，但所部曾北调冀东，参与“扫荡”行动。；其部队曾短暂驻防廊坊南部，参与对冀中十分区的“扫荡”。……（共涉及16个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('98a979b60b205b51b0b190c9d2df01d1', '张岚峰（注：此人为豫东伪军，不涉及晋中，不列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '', '', '', '', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
