REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('99afd279f9bb50b2b65b52b289c8e71d', '张庆余', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、河北', '北京、天津、河北', '[]', '伪冀东保安队副司令（后反正）、伪冀东保安队司令、伪冀东保安队第一总队长、伪冀东保安队第一总队长（曾驻昌黎）、伪冀东保安队第一总队队长、伪冀东保安队第一总队队长（后反正）、伪冀东保安队第一总队队长（驻唐山）、伪冀东保安队第一总队队长（驻密云）、伪冀东保安队第三总队队长（后反正）、伪冀东保安队第三总队队长（后投日，活动于三河周边）、伪冀东保安队第二总队队长（后反正）、伪冀东保安队第四总队队长（后反正）、伪冀东防共自治政府保安队第一总队总队长、伪冀东防共自治政府保安队第一总队长、伪冀东防共自治政府保安队第一总队队长、伪沧州自卫团团长、冀东保安队第一总队队长、冀东保安队第一总队队长（后反正）、冀东保安队第三总队队长、冀东保安队第三总队队长（后反正）、冀东保安队第二总队队长、冀东保安队第二总队队长（后反正）', '1935-1945', '', '初期为殷汝耕效力，在密云镇压抗日活动，后反正但影响有限。；在密云地区协助日军维持治安，镇压抗日活动，参与冀东伪政权的军事行动。；1935年参与殷汝耕成立的伪冀东防共自治政府，驻防平谷、密云一带，协助日军维持治安，镇压抗日活动。1938年反正后投靠国民党，但此前已造成抗日力量损失。；原为冀东伪军头目，1937年7月通州事变中率部反正，杀死日军和汉奸，但此前曾为伪政权效力。；初期为殷汝耕效力，但1937年7月29日率部发动通州起义，杀死日军和汉奸数百人，后反正抗日，故其前期行为属被迫附逆。……（共涉及31个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('09f54acde6ce519fbaaea9f6ea738d9b', '张廷秀', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪永济县知事（县长）', '1939-1943', '', '任伪永济县知事期间，推行日伪“治安强化”运动，强征民夫修筑碉堡公路，配合日军扫荡中条山抗日根据地，并强迫百姓领取“良民证”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('70293c50cd725cb38ef99350d6b74fbf', '张德义', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津', '天津', '[]', '伪天津警察局特高课课长', '1938-1945', '', '投日后在天津警察局特高课任职，专门破坏中共地下组织，逮捕多名抗日志士。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('de73f01a77d651babbad6066d55760f1', '张德全', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪易县特务队队长', '1942-1945', '', '专门刺探八路军情报，带领特务队破坏抗日交通线，多次告密导致游击队损失。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('75a026b71c4a5c8885feb655eb0aae6c', '张德功', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪涿县新民会会长', '1939-1945', '', '负责在涿州推行奴化教育，宣传“中日亲善”，强迫民众参加反共集会，收集抗日情报供日军使用。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4de5af157ba75f47b2ca9a19b2691125', '张德林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪涞水县警察所所长', '1939-1945', '', '指挥伪警察特务，侦缉抗日活动，逮捕进步人士，刑讯逼供，向日军提供情报，参与“清乡”行动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('316cc483865057089895b48829218edb', '张德润', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪满城县警察局局长、伪雄县新民会会长、伪雄县警备大队长、房山县伪保安队队长', '1938-1945', '', '率伪保安队多次配合日军扫荡房山抗日根据地，杀害抗日干部和群众，抢劫财物。；指挥伪警察搜捕抗日家属，严刑逼供，破坏地下交通站，导致多名抗日干部牺牲。；率伪警备队多次袭击八路军游击队，破坏抗日组织，勒索百姓，民愤极大。；推行日伪奴化教育，组织汉奸宣传队，强迫群众参加“反共”集会，搜集抗日情报提供给日军。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e8903b9574bc5840894682024ec4319d', '张德胜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪太原县保安队副队长、伪长治县警察局局长、伪黎城县合作社主任', '1941-1945', '', '率伪保安队配合日军袭击小店周边抗日游击队，杀害抗日军属。；严酷镇压抗日运动，设立集中营，关押审讯抗日群众。；控制物资配给，强征粮食，为日军经济掠夺服务。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bd865564d6b95ee985f5179eaef0dc9e', '张德顺', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '唐山伪保安队队长', '1940-1945', '', '率伪军多次扫荡冀东抗日根据地，杀害抗日干部和群众，烧毁村庄。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b54c770d2bd754c79a6f91b65faed029', '张怀信', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪邯郸县保安联队队长、伪魏县维持会会长', '1937-1945', '', '率伪军多次袭击冀南抗日根据地，在邯郸周边村庄烧杀抢掠，杀害抗日军属，并协助日军清乡；日军占领魏县后率先组织维持会，为日军提供粮秣、民夫情报，协助建立伪政权。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('de51473be6265f10b54eec7061d19b8a', '张怀斌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京', '北京', '[]', '伪平谷县警察局局长', '1938-1943', '', '指挥伪警察搜捕抗日人员，严刑逼供，并协助日军建立“人圈”隔离区，导致大量平民死亡。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('30baf331012c585189c2c57b3f3a8326', '张惠民', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪包头商会会长', '1938-1945', '', '投靠日军后控制包头商会，为日军筹集军饷和物资，强迫商户缴纳各种捐税，从中牟利。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7987b939a2f5512296c45c13c7af807a', '张慕陶', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪上党道尹公署顾问、伪临汾县知事、伪临汾县知事（县长）、伪吉县知事、伪吉县维持会会长、伪孝义县维持会头目、伪山西新民会会长（活动于长治）、伪山西晋北自治政府顾问、伪山西省公署顾问、伪山西省公署顾问（曾活动于临汾、隰县一带）、伪山西省政府顾问、伪晋中道尹公署参议、伪晋中道尹（驻榆次，管辖祁县）、伪晋南道尹、伪晋南道尹（驻临汾）、伪曲沃县知事、伪榆次县维持会会长、伪阳曲县知事', '1937-1945', '', '曾任中共早期党员，后叛变投敌，在临汾、乡宁一带为日军搜集情报，策反抗日力量，协助日军扫荡根据地。；在临汾县推行保甲制度，强征民夫修筑公路碉堡，配合日军扫荡，残害抗日军民。；投靠日军后任临汾伪县长，强征民夫修筑碉堡公路，搜捕抗日军民，向日军提供情报。；任伪吉县知事期间，强征民夫修筑日军碉堡，强迫百姓领取“良民证”，并配合日军扫荡抗日根据地。；在吉县组织维持会，为日军征粮派款，出卖抗日志士，导致多名地下党员被捕牺牲。……（共涉及22个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2dc7e59d1bd35e5d892c489672168b09', '张慕陶（注：曾在太原活动，后因托派问题被处决，非典型汉奸）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '无', '', '', '无', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3ecfae9ff43c5029ab1679ba2722a82a', '张成义', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪原平维持会会长、伪孝义县警备队队长、伪定襄县知事、伪平鲁县维持会会长、伪忻县保安大队长、伪朔县保安队队长', '1937-1945', '', '组织伪警备队，为日军提供情报，参与多次对孝义抗日根据地的“扫荡”，杀害抗日干部和群众数十人。；在定襄县为日军征夫派款，破坏抗日根据地，多次带日伪军偷袭八路军后方。；日军占领原平后出任维持会长，为日军提供情报，组织伪自卫团镇压抗日活动。；组织伪保安队，在忻州、岢岚边界多次袭击八路军游击队，杀害抗日干部，抢劫群众财物。；在平鲁县城组织维持会，为日军征粮派款，提供情报，破坏抗日地下组织。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('27c84878572e5361a427d9981c30abbf', '张成德', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪云冈维持会会长、伪大同保安队队长、伪大同省保安队司令、伪大同省公署警务厅厅长、伪大同警务段段长、伪大同警务段长/汉奸特务、伪天镇县知事（县长）、伪左云县保安队队长、伪广灵县保安队队长、伪朔县保安队队长、伪浑源县保安队队长、应县伪警察所所长、灵丘县伪警察署署长', '1937-1945', '', '统领伪警察，协助日军抓捕抗日地下人员，破坏中共大同地下组织，参与屠杀无辜百姓。；在云冈地区组织伪维持会，为日军提供情报，协助日军控制云冈石窟周边区域，破坏文物保护活动。；在大同地区担任伪警务职务，为日军搜集情报，抓捕抗日志士，参与“清乡”行动，残害当地群众。；负责伪大同省警察系统，抓捕抗日地下人员，严刑逼供，破坏中共地下组织，为日军提供情报。；率伪保安队配合日军扫荡大同周边抗日根据地，杀害抗日干部，抢劫民财，多次参与“清乡”行动。……（共涉及15个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c56bab352a0654668e3124574eabd6cf', '张成箕', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪抚顺市公署市长（伪满时期）、伪新民县县长、伪满辽中县县长', '1932-1941', '', '在抚顺推行日伪殖民政策，组织“勤劳奉仕”强征劳工，为日军提供煤炭资源。；在新民县推行保甲制度，强征劳工，配合日军“清乡”行动，迫害抗日家属。；在辽中县任伪县长期间，配合日军“清乡”行动，抓捕抗日志士，强征劳工，推行“归屯并户”政策。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5220106099c25b7984d80c869672323e', '张承德', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪大同省公署顾问、伪广灵县保安队队长、伪灵丘县保安队队长', '1938-1945', '', '作为伪蒙疆政府派驻大同的代表，配合日军实施“以华制华”政策，参与组建伪警察队，镇压抗日活动，并协助日伪军清乡。；原为地方土匪，后投降日军任伪保安队队长，率部多次袭击八路军游击队，杀害抗日干部和军属，并参与日军在广灵县西加斗、南村等地的“清乡”行动。；率伪保安队多次配合日军扫荡抗日根据地，抓捕抗日干部和群众，并参与制造多起惨案，如“刘庄惨案”中充当向导。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fa8ea38f197c5a55b924738bce14b4f0', '张拱辰', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府警务处长', '1935-1938', '', '在唐山地区组建伪警察，协助日军搜捕抗日分子。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6ab51f9d619f58a2ae6df0b419806eb9', '张振凯', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '广宗县伪保安联队队长', '1940-1945', '', '率伪军多次扫荡广宗抗日村庄，杀害抗日干部和群众，烧毁民房，抢夺物资，是日军在广宗的重要帮凶。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bb640cda2098539fb0e4e975ca83a94f', '张振声', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪兴隆县警察署署长、伪新乐县知事', '1939-1945', '', '指挥伪警察多次突袭抗日村庄，逮捕并严刑拷打抗日群众，参与制造多起惨案，如‘狗背岭惨案’。；在新乐县任伪知事，协助日军修建平汉铁路封锁线，破坏抗日交通。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b91479b13e4a5541a49458477ab8b061', '张振海', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '临城县伪县长、伪邯郸县河务局局长', '1937-1945', '', '投靠日军，任临城县伪县长，协助日军推行保甲制度，强征民夫，搜刮粮食，镇压抗日群众。；负责漳河、滏阳河河务，为日军运输物资提供水路保障，同时向沿河村庄强征船工和物资。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6cf10d4aa7945cc0b66d83616709e0c5', '张效忠', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪五台县保安队队长、伪偏关县保安队队长、伪怀安县保安队队长、伪静乐县保安队队长', '1938-1945', '', '率伪保安队配合日军“扫荡”五台山抗日根据地，杀害抗日干部和群众，烧毁村庄，抢劫财物。；率保安队多次配合日军扫荡偏关抗日根据地，抓捕并杀害抗日干部和军属，抢劫粮食资敌。；率伪保安队多次配合日军扫荡静乐抗日根据地，杀害抗日干部和群众，抢劫粮食，烧毁村庄，罪行累累。；带领伪保安队配合日军扫荡怀安抗日根据地，杀害抗日干部和群众，抢劫财物。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('737529efae90581dbb63ec770ab8f6c3', '张效良', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪五台县知事、伪宁武县新民会会长、寿阳县伪警察局局长、文水县伪保安队队长、静乐县伪新民会会长', '1938-1945', '', '率伪保安队多次配合日军扫荡文水山区抗日根据地，抓捕抗日干部，烧毁村庄，杀害无辜百姓。；在日军占领五台期间，组织维持会，协助日军推行“治安强化”运动，强征民夫修筑炮楼和公路，并配合日军扫荡抗日根据地，残害抗日军民。；负责在宁武推行奴化教育，宣传‘中日亲善’，组织汉奸团体刺探抗日情报，并协助日军建立保甲制度，强化殖民统治。；在静乐推行奴化教育，组织“新民会”宣传“中日亲善”，强迫民众参加反共集会，收集抗日情报提供给日军特务机关。；任伪警察局长期间，协助日军建立情报网，侦捕地下党员，参与制造多起屠杀事件，强征劳工送往东北。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4fc078bb6abd52efaab226d2d53038c6', '张敬尧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津', '北京、天津', '[]', '伪冀东防共自治政府保安司令、伪华北绥靖军总参议（未及就任被刺杀）', '1933-1937', '', '在密云地区协助日军镇压抗日武装，推行“治安肃正”，残害抗日军民。；原北洋皖系军阀，1933年受日军指使在天津、河北策划华北自治，被军统刺杀于北平六国饭店。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d9e409ddc0b451d39ae4e7808a8ae88c', '张星五', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪中山区公署参事、伪满复县（今瓦房店）警察局长', '1933-1945', '', '在中山区协助日军推行粮食统制，强征居民粮食，导致民众饥荒。；在瓦房店地区为日军效力，抓捕抗日地下党员，破坏抗日组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fef4d7f142665d61aaea0740e97b27c5', '张星南', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满洲国奉天市银行行长', '1932-1945', '', '管理伪满银行沈阳分行，发行伪币，掠夺民间财富。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
