REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4695398eb4bf5cecab8de410c14caab0', '张星逸', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪山西省建设厅厅长', '1938-1945', '', '主管伪省建设，组织劳工为日军修路筑堡，掠夺矿产资源。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5af5570ba011572f971eab206ca84a58', '张景岳', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北', '天津、河北', '[]', '伪唐山商会会长、伪开平区区长、伪葛沽镇维持会会长', '1937-1945', '', '投靠日军后，在葛沽地区建立伪政权，协助日军清乡，迫害抗日家属。；充当日伪经济汉奸，为日军统制唐山、丰南商业，强制收购粮食和物资，压榨商户。；在开平推行“保甲连坐”，强抓壮丁送日军当苦力，克扣抗日家属救济粮。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e605798af81b50b78e159caff3e3acc7', '张景惠', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、吉林、山西、河北、辽宁', '北京、吉林、山西、河北、辽宁', '[]', '伪冀东防共自治政府顾问（后任伪满要职）、伪满国务总理大臣、伪满国务总理大臣、汉奸、伪满国务总理大臣（原奉系将领）、伪满国务总理大臣（曾任伪奉天省长）、伪满国务总理大臣（曾任奉天地区军事要职）、伪满国务总理大臣（曾任奉天省省长）、伪满国务总理大臣（曾任奉天省长）、伪满国务总理大臣（曾兼任奉天地区职务）、伪满国务总理大臣（曾兼锦州地区军事顾问）、伪满国务总理大臣（曾参与铁岭地区殖民统治决策）、伪满国务总理大臣（曾多次巡视鞍山钢铁生产）、伪满国务总理大臣（曾巡视营口）、伪满国务总理大臣（曾涉安东地区）、伪满国务总理大臣（曾涉阜新）、伪满国务总理大臣（曾管辖本溪地区）、伪满国务总理大臣（曾管辖热河）、伪满国务总理大臣（曾管辖辽宁地区）、伪满国务总理大臣（曾管辖锦州地区）、伪满国务总理大臣（涉及热河地区）、伪满国务总理大臣（涉及热河省）、伪满国务总理大臣（统辖阜新、彰武地区）、伪满国务总理大臣（继任）、伪满洲国国务总理大臣、伪满洲国国务总理大臣（关联盘锦地区活动）、伪满洲国国务总理大臣（原籍辽宁台安，活动于锦州地区）、伪满洲国国务总理大臣（吉林籍，活动于长春）、伪满洲国国务总理大臣（名义上管辖阜新地区）、伪满洲国国务总理大臣（名义管辖营口）、伪满洲国国务总理大臣（曾任东省特别区长官）、伪满洲国国务总理大臣（曾任伪吉林省长官）、伪满洲国国务总理大臣（曾任吉林地区伪职）、伪满洲国国务总理大臣（曾任吉林地区军事要职）、伪满洲国国务总理大臣（曾任吉林地区军政职务）、伪满洲国国务总理大臣（曾兼热河省相关职务）、伪满洲国国务总理大臣（曾涉足大同地区）、伪满洲国国务总理大臣（曾管辖锦州地区）、伪满洲国国务总理大臣（涉及热河省）、伪满洲国国务总理大臣（管辖热河省）、伪满洲国国务总理大臣（长春）、伪满洲国国务总理（曾管辖热河省）、伪满洲国国务总理（涉热河地区政策）、伪满洲国总理（未直接管北平，但曾参与华北事务）', '1931-1945', '', '虽以伪满为主，但曾协助日军协调华北伪政权，影响北平昌平地区。；原东北军将领，后投敌，历任伪参议府议长、军政部总长、国务总理，在吉林地区协助日军清剿抗日武装。；原东北军将领，投日后在四平地区协助日军“清乡”，后任伪满总理，全面配合日本侵略政策。；原东北军将领，九一八事变后投敌，曾任伪满军政部总长，后任伪满国务总理，全面协助日本统治东北，其势力范围涵盖吉林、四平、伊通等地。；原东北军将领，投日后任伪满总理，虽主要活动于新京，但其政策覆盖吉林、四平、梨树，支持日军殖民统治。……（共涉及106个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d7a6f18ab79d56c69b34b55c60ec2dcb', '张景惠（于洪地区相关）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满洲国协和会会长', '1936-1945', '', '虽出生于台安，但长期在沈阳及于洪地区活动，任伪满协和会会长，组织汉奸团体进行思想宣传。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
