REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6958e0038a495e9d8c7947a02ce6e174', '张有才', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪左权县维持会副会长', '1941-1941', '', '协助日军建立“爱护村”，强迫村民挂日本旗，违者遭毒打。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7afeeb75fc46530b9c3d818f463691f9', '张本政', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪大连商会会长、伪大连商会会长、日本殖民当局顾问、伪大连商会会长、汉奸商人、伪大连市参事会会长、伪满大连商会会长、汉奸商人、伪满洲国大连商会会长、关东州厅参事、大连商会会长、日本殖民当局御用商人、大连地区汉奸头目、伪大连商会会长', '1931-1945', '', '大连巨商，投靠日本，任伪商会会长，为日军筹集军费，垄断港口贸易。；在大连地区为日军提供物资和资金，协助日本控制港口和航运，迫害抗日人士。；大连巨商，长期为日本殖民当局服务，资助日军侵略，参与经济掠夺。；大连巨商，长期为日本关东军提供物资和情报，任伪商会会长，协助日本掠夺大连资源。；辽宁大连人，日本殖民时期大连最大买办，为日军提供物资和情报，协助镇压抗日活动。……（共涉及10个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
