REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('db31b6c2dcf0567288e3afa976caf250', '张林阁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '威县伪保安联队队长', '1939-1945', '', '组建伪保安武装，配合日军扫荡抗日根据地，抓捕抗日干部和群众，多次参与屠杀和烧村行动，罪行累累。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
