REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('42c3d62724cd518993e6dfbbc641f2d3', '张树帜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪大同县知事（县长）、伪大同警务厅长、伪太原绥靖公署主任（名义）、伪山西省财政厅厅长', '1937-1945', '', '负责伪大同地区警察系统，协助日军特务机关侦捕抗日分子，镇压群众反抗，多次参与屠杀平民事件。；出任伪大同县知事，为日军征夫派粮，镇压抗日活动，破坏地下组织。；太原沦陷初期投敌，任伪绥靖公署主任，协助日军维持治安，后调任他职。；负责为日伪政权征收苛捐杂税，发行伪币，搜刮民财以充日军军费。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('721d15ca90f05851bedb343987631dee', '张桐冈', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '赞皇县伪县长', '1938-1945', '', '任赞皇县伪县长期间，推行日伪政权各项政策，组织维持会，协助日军清乡、征粮，镇压抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6f99d6e8396d5a1e86cb7f780cd0660c', '张桐岗', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '高邑县伪县长', '1937-1945', '', '投靠日军，任高邑县伪县长，协助日军推行保甲制度，强征民夫，搜刮粮食物资，镇压抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5be08c100d06553796f244b98545bd92', '张桐轩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '任县伪县长、伪临清县知事（临西县原属临清）、伪冀南剿共军司令、伪冀南道保安司令部副司令、伪冀南道公署参议兼邯郸维持会会长、伪冀南道公署顾问、伪南宫县知事、伪复兴区维持会会长、伪承德地区保安队总队长、伪沙河县知事、伪沙河县知事/县长、伪清河县知事、伪热河省协和会会长、伪邢台县知事、伪邢台县警备队中队长、伪邯郸县保安联队队长、伪邯郸县维持会会长、伪邯郸县警察局局长、伪隆平县县长、伪顺德道尹、伪馆陶县新民会会长、巨鹿县伪县长、衡水县伪保安大队副大队长', '1935-1945', '', '组织汉奸保安队，配合日军在丰宁、隆化一带进行“大扫荡”，实行“连坐法”，强迫村民报告抗日活动，杀害无辜群众数十人。；在承德、隆化组织协和会，宣传“日满亲善”，刺探抗日情报，协助日军进行经济掠夺。；率伪军参与对阜城、武邑等地的军事‘讨伐’，杀害抗日军民多人。；任伪顺德道（邢台地区）道尹，积极推行日伪政权统治，协助日军征粮、抓夫、建立保甲制度，镇压抗日力量。；任伪临清县知事期间，积极推行日伪政权各项政策，协助日军征粮派款，镇压抗日民众，破坏中共地下组织。……（共涉及25个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f4cbb4d6738f582bb49d249f7dc44025', '张步云', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪华北治安军第2集团军司令、伪山东保安第三旅旅长、伪皇协军司令', '1938-1945', '', '在沧州地区为日军效力，参与围剿八路军和抗日游击队，强征民夫，掠夺物资。；活动于沧州东南部及海兴、无棣交界地区，多次配合日军进攻八路军根据地，抢掠民财，杀害抗日干部。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bd5818c72a625952af1ff65a5172e89f', '张殿元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪临西地区‘剿共’司令', '1942-1945', '', '率伪军多次突袭临西抗日村庄，杀害村干部，抢夺牲畜粮食。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
