REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('df4297e5caa653e1957eb4a3ce24de44', '张永德', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京', '北京', '[]', '伪延庆县财政科科长', '1939-1939', '', '负责为日军征收田赋和苛捐杂税，在延庆地区强征“治安费”，中饱私囊，导致农民破产。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('13eccdb6f0595f81947dccdbfe741f1f', '张永清', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、山西', '北京、山西', '[]', '伪沁源县维持会情报员、伪顺义县新民会会长', '1940-1945', '', '推行奴化宣传，组织“新民会”分会，强迫百姓参加反共集会，收集抗日情报。；化装成商人刺探八路军情报，导致多次伏击失败。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a206a38f9d755a038454d91ce5a03271', '张永福', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪冀东防共自治政府滦州水利局长、伪沁源县警察局副局长、伪热河省滦平县新民会会长', '1935-1945', '', '协助局长搜捕地下党员，刑讯逼供，导致多名抗日志士牺牲。；在滦州破坏水利设施，制造水患，转移抗日力量。；推行新民会奴化活动，组织“反共救国会”，协助日军进行思想控制。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('cb2537357764589280a7d2b2b0f66b63', '张永福（同名）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府滦州工头', '1935-1938', '', '在滦州为日军招募劳工，克扣工钱。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
