REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7d8cfba1792a542da4df53d179b12578', '张海鹏（重复？）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满热河省省长（曾率军至岫岩）', '1931-1945', '', '已列，但需补充其曾派伪军到岫岩地区“清剿”抗日义勇军。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('85aa2fd10d9c5918aff4e588d092ec71', '张焕相', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪义县协和会会长、伪满参议、奉天省咨议、伪满吉林地区保安局长、伪满奉天省参事、伪满奉天省警务厅长、汉奸、伪满抚顺地区保安队队长、伪满法库县县长、伪满洲国司法部大臣、伪满洲国司法部大臣（曾参与锦州司法事务）、伪满洲国吉林省高等法院院长、伪满洲国奉天省警务厅厅长、伪满锦州地区维持会会长（初期）、伪满锦州省参事官、伪满鞍山地区“靖安军”顾问', '1931-1945', '', '审判抗日志士，判处死刑或重刑，维护日伪统治。；组织保安队配合日军“讨伐”，烧毁村庄。；率伪保安队配合日军扫荡新抚地区抗日游击队，杀害多名抗日群众。；负责伪奉天省警务，残酷镇压抗日军民，多次参与“讨伐”行动。；原东北军将领，投日后为伪满出谋划策，在沈阳地区动员地方士绅支持日军统治。……（共涉及14个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5e4ae6e524305885be6f33f0be6cd934', '张燕卿', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、吉林、河北、辽宁', '北京、吉林、河北、辽宁', '[]', '伪冀东防共自治政府外交处长（涉及秦皇岛涉外事务）、伪华北政务委员会教育总署督办、伪吉林省教育厅长、伪满外交部大臣、伪满外交部大臣（曾参与吉林事务）、伪满外交部大臣（曾活动于长春）、伪满外交部大臣（沈阳活动）、伪满奉天省民政厅长、伪满洲国交通部大臣（曾任伪吉林省实业厅长）、伪满洲国司法部大臣（在长春任职）、伪满洲国吉林省伪教育厅长、伪满洲国吉林省伪省长、外交部大臣、伪满洲国吉林省实业厅长、伪满洲国吉林省教育厅长（后任外交部大臣）、伪满洲国外交部大臣、伪满洲国外交部大臣（原辽宁籍）、伪满洲国外交部大臣（曾任吉林交涉员）、伪满洲国外交部大臣（曾任吉林地区伪职）、伪满洲国外交部大臣（曾在长春任职）、伪满洲国外交部大臣（涉及热河边界事务）、伪满洲国外交部大臣（辽宁籍）、伪满洲国外交部大臣（长春）、伪满洲国奉天省外交处处长', '1931-1945', '', '在北平推行奴化教育，修改教科书，鼓吹“中日亲善”，压制师生抗日思想。；在北平推行奴化教育，其管辖学校包括石景山地区的小学和中学，强制推行日语教学和“中日亲善”宣传。；协助日本掠夺吉林森林、矿产等资源，组织劳工为日军服务。；推行奴化教育，强制学校教授日语，篡改历史，灌输“日满亲善”思想。；代表伪满与日本签订不平等条约，出卖东北权益，间接影响船营地区资源控制。……（共涉及31个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bccb7f94a5e8570cb977ed0c1c7a9011', '张狗儿', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪左权县保长（投敌）', '1943-1943', '', '强迫村民向日军交粮，举报藏粮户，导致3户农民被杀害。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d941126e8c785a22a9720c46c6bd1778', '张璧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津', '北京、天津', '[]', '伪北平市社会局局长、伪华北政务委员会教育总署督办、伪北平维持会会长、伪北平维持会会长（1937年短暂）、伪北平维持会会长（1937年）、伪北平维持会会长（初期）、伪华北政务委员会治安总署督办、伪天津特务机关顾问', '1937-1945', '', '曾任伪华北治安军高级将领，参与指挥伪军在北平东城及周边地区镇压抗日力量。；七七事变后率先组织北平地方维持会，迎接日军进城，协助维持治安，后因权力斗争失势，但前期对大兴地区伪政权建立有直接影响。；七七事变后率先组织维持会，迎接日军入城，协助建立伪政权，为日军征粮派款。；七七事变后率先投敌，组织北平维持会，为日军提供粮食、劳力和情报，协助建立伪政权。；原北洋将领，北平沦陷初期组织伪维持会，为日军稳定昌平等郊区秩序服务。……（共涉及10个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('603fa7ec91b75ef791d4b53083ee1be5', '张盛', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪榆次县维持会会长', '1938-1938', '', '日军占领榆次后率先组织维持会，为日军提供粮食、情报，强迫百姓领取“良民证”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('cbf51e619442501987295265d484d416', '张盛林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪大同警察局局长、伪左权县（原辽县）维持会会长', '1938-1945', '', '任伪大同警察局长期间，积极搜捕抗日地下人员，破坏中共平城地下组织，协助日军推行“三光政策”。；在左权县城组织维持会，为日军征粮派款，提供情报，导致多名抗日干部被捕牺牲。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6f9c44c820815521b2d42b6fcc7b005d', '张砚田', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪冀东保安队改编后任伪军团长、伪冀东保安队第二总队队长、伪冀东保安队第二总队队长（后反正）、伪冀东保安队第四总队长、伪冀东保安队第四总队队长、伪冀东保安队第四总队队长（后反正）、伪冀东防共自治政府昌黎县县长、冀东保安队第三总队队长、冀东保安队第三总队队长（后反正）、冀东保安队第二总队队长（后反正）、冀东保安队第四总队队长', '1935-1945', '', '与张庆余共同参与通州事变，但事变前长期担任伪军职务，参与镇压抗日活动。；与张庆余一同参与通州起义，但起义前曾执行伪政权命令，参与镇压抗日民众。；驻防唐山、丰润一带，执行伪政府命令，协助日军强征民夫、粮食，破坏抗日组织。；与张庆余类似，投日期间在唐山、芦台地区参与伪政权军事活动，后反正。；伪冀东保安队军官，驻防冀东地区，参与维持伪政权统治，后随通州事变反正。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('1dbffbc715a15493bcf55f10a8e2143a', '张福元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪榆社县维持会会长、伪遵化县保安队队长、兴隆县伪警察署署长', '1938-1945', '', '为日军提供榆社抗日政府活动情报，导致多次袭击，损失惨重。；率伪保安队多次袭击遵化境内的抗日游击队，杀害抗日群众，烧毁村庄。；率伪警察配合日军“扫荡”，抓捕抗日军民，破坏地下组织，参与制造多起惨案。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
