REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('1b401255ce0b5c2e93bdbe76ada4c72f', '张老梦（张梦九）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪峰峰矿警队队长、磁县伪维持会会长', '1937-1945', '', '率矿警队为日军护矿，多次镇压矿工罢工，抓捕并杀害抗日积极分子，参与“治安强化”行动。；日军占领磁县后率先组织维持会，为日军筹粮派款，强迫百姓“欢迎皇军”，协助日军建立伪政权。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('199710bc8f1e5a34b6cbbce6003dac9e', '张老黑（张黑子）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪曲阳县便衣队队长', '1942-1945', '', '带领便衣汉奸队专门暗杀抗日干部和积极分子，多次袭击区小队，破坏抗日组织，罪行累累。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3c1fc36e2bc85687a459238af2c4584e', '张联文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪吉林省延吉地区行政专员', '1932-1945', '', '在延边地区推行“间岛”政策，镇压朝鲜族抗日武装。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('05024b123cc45ed8ac41b71c1d26adcb', '张联桂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪满舒兰县县长', '1932-1945', '', '投日后任伪舒兰县长，推行保甲制度，强征粮食，协助日军建立“集团部落”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('169aff2a53fc5001842ff0524a54753e', '张联第', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、河北', '吉林、河北', '[]', '伪双阳县警务科长、伪吉林省公署总务厅长、伪吉林省高等法院院长、伪满吉林省公署参事、伪满德惠县县长、伪热河省警察署署长、伪长春协和会会长、伪长春县县长（今长春净月区一带属长春县）、伪长春县县长（绿园地区属长春县）', '1931-1945', '', '原吉林省政府官员，投日后任伪满吉林省公署参事，参与策划对吉林、四平地区抗日武装的围剿，并协助日军建立“集团部落”。；审判抗日人士，判处大量爱国者死刑或重刑；指挥伪警察在双阳山区围剿抗联小分队，杀害多名游击队员。；在长春及宽城地区组织协和会，收集情报，破坏抗日组织。；在德惠县任伪县长，组织伪警察配合日军清乡，强征粮食和壮丁。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7a4d595c479e5af792f43dfe435fb25b', '张联魁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪临汾保安队队长、伪临汾县知事、伪临汾县知事（县长）、伪太原市市长、伪太原市市长（继任）、伪太原市警察局局长、伪太原绥靖公署主任、伪山西省保安司令、伪山西省公署教育厅厅长（涉及晋城）、伪山西省公署警务厅长、伪山西省教育厅厅长、伪山西省警务厅厅长、伪山西省警务厅长、伪晋中保安司令、伪晋南道尹、伪曲沃县维持会会长、伪榆次县保安队队长、伪清源县知事（清徐地区）、伪隰县维持会会长', '1938-1945', '', '任伪晋南道尹（驻临汾），统辖临汾、运城等地伪政权，配合日军“治安强化运动”，推行保甲制度，搜刮粮食资敌。；任伪晋南道（辖临汾等地）道尹，负责推行日伪“以华制华”政策，组织伪警察和保甲制度，配合日军扫荡抗日根据地。；组织伪保安队，配合日军扫荡尧都区周边村庄，杀害抗日军民。；组织维持会，为日军提供情报，协助清乡，残害抗日群众。；在临汾县推行伪政权，强征民夫修筑公路和碉堡，向日军提供粮食和情报，镇压抗日活动。……（共涉及34个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('76c12ec1765c52da9979871bc7873502', '张良臣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '万泉县伪县长、伪运城保安队队长、伪运城维持会会长、垣曲县伪县长、夏县伪县长、平陆县伪县长、平陆县维持会会长、稷山县伪县长、绛县伪县长、闻喜县伪县长', '1938-1945', '', '协助日军维持运城治安，参与清乡扫荡，捕杀抗日军民，强征民夫修建碉堡工事。；投靠日军，任万泉县维持会会长及伪县长，协助日军推行“治安强化运动”，强征民夫，搜刮粮食，镇压抗日群众。；投靠日军后出任垣曲县维持会会长及伪县长，协助日军建立伪政权，强征民夫修筑碉堡，搜刮粮食供给日军，并参与诱捕抗日军民。；投靠日军后任垣曲县维持会会长及伪县长，协助日军建立伪政权，强征民夫修筑碉堡公路，并组织伪警备队配合日军扫荡抗日根据地，残害抗日军民。；投靠日军，任夏县伪县长，协助日军推行“治安强化运动”，强征民夫，搜刮粮食，镇压抗日群众。……（共涉及14个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ea5fc95149e5572c84e089b03f96040c', '张英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪察哈尔省保安队司令、伪新乐县知事、伪正定县知事、伪河北省保安队副司令、伪石家庄市市长、伪辛集县知事、伪高邑县县长、晋县伪县长、栾城县伪县长、正定县伪县长、灵寿县伪县长、藁城县伪县长、赵县伪县长', '1937-1945', '', '指挥伪保安队协助日军扫荡抗日根据地，在张家口周边地区制造多起屠杀事件。；投靠日军，任伪新乐县知事，协助日军推行“治安强化运动”，强征民夫，搜刮粮食，镇压抗日群众。；在石家庄及周边地区协助日军维持治安，镇压抗日武装，参与清乡扫荡行动。；任晋县伪县长期间，推行日伪政权法令，强征民夫，搜刮粮食，协助日军清乡扫荡，镇压抗日群众。；任晋县伪县长期间，积极推行日伪政权各项政策，组织伪保安队配合日军扫荡抗日根据地，强征粮税，镇压抗日群众。……（共涉及17个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('53e71ec04f6057348dadc54a228588ab', '张英华', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北、辽宁', '河北、辽宁', '[]', '伪岫岩县商会会长、伪河北省省长（1940-1943）、伪河北省警务厅厅长', '1933-1945', '', '投日后主管伪省警务，在保定设立特务机构，破坏地下抗日组织，逮捕进步学生和爱国人士，施以酷刑。；在石家庄及河北地区推行日伪政权政策，协助日军进行经济掠夺和治安维持，镇压抗日力量。；岫岩大商户，投日后任伪商会会长，为日军筹集物资，并强迫商户“献金”，资助伪军购买武器。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8e2831609b485f6fa507714d3917f099', '张英华（重复？）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪岫岩县商会会长', '1933-1945', '', '已列，补充其曾垄断粮食贸易。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0f9718e2185859ad9a2919936bdc4e66', '张英武', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪保定县知事、伪保定市市长、伪武安县税务局局长、伪河北省保安司令、伪河北省保安司令、伪华北治安军第1集团军司令、伪河北省保安队司令、伪清苑县知事（县长）、伪石家庄市公署市长、伪石家庄市市长、伪藁城县保安联队副队长、伪行唐县知事、伪辛集县知事、伪高碑店维持会会长、伪高邑县知事、元氏县伪县长、成安县伪税务局局长、栾城县伪县长、深泽县伪县长、行唐县伪县长', '1937-1945', '', '任伪清苑县长期间，推行保甲制度，强征粮款，协助日军建立伪政权，镇压抗日活动。；任伪保定县知事期间，为日军提供情报，组织伪警察抓捕抗日地下党员，强征劳工送往东北。；任伪保定市长期间，推行日伪统治政策，强征民夫，搜刮物资供日军使用。；日军占领高碑店后率先组织维持会，为日军征粮派款，提供情报，帮助日军建立伪政权。；投靠日军，任元氏县伪县长，协助日军推行‘治安强化运动’，强征民夫、粮食，镇压抗日群众。……（共涉及20个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('30c226a49bd95878abe4a57218e8149e', '张荣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪满梨树县县长', '1932-1945', '', '在梨树县（今属四平）推行伪满苛政，强征粮食，镇压农民反抗。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('33d8f2591a01592ba837d8f3ab04f5f0', '张荣久', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满抚顺地区“自卫团”团长、伪满抚顺地区自卫团团长、伪满本溪湖保安队队长', '1932-1945', '', '组织地方汉奸武装，配合日军巡逻抚顺矿区及周边乡村，多次参与搜捕抗联和抗日群众，掠夺民财。；组织地方汉奸武装，配合日军“扫荡”抚顺东部山区，参与制造“平顶山惨案”的辅助行动。；率保安队在本溪、南芬一带巡逻，协助日军“清乡”，抓捕抗联伤员和群众，烧毁村庄。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('87a3057a3ff750998be4ee6e5d9b2730', '张荫堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪敖汉旗教育督学', '1940-1945', '', '推行奴化教育，强制学校使用日语教材，宣扬“日满亲善”，迫害有爱国倾向的教师和学生。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ad0c9f9af10054c68d58a879c97add74', '张荫梧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪保定道尹（曾任）、伪冀东剿共军第一路司令（活动范围含三河）、伪冀东防共自治政府保安处长（后投敌）、伪冀中保安司令（后投敌）、伪冀中剿共军司令（后投敌）、伪冀中剿共总司令（后投敌）、伪冀中道尹（驻沧州）、伪冀南保安队副司令（驻邯郸）、伪冀察战区挺进司令（后投敌）、伪冀察战区挺进第4纵队司令（后投敌）、伪华北“剿共”军指挥官（曾活动于密云）、伪华北政务委员会下属伪军头目（后反正）、伪华北政务委员会保定办事处主任、伪华北政务委员会参议（行唐籍）、伪华北政务委员会教育总署督办（早年反共，后投敌）、伪华北政务委员会绥靖总署督办（后投敌）、伪河北省保安司令（名义上，实际活动于冀中）、伪河北省保安司令（后投敌）、伪河北省保安司令（后投敌，曾活动于冀中地区）、伪河北省保安司令（后投敌，活动涉及保定地区）、伪河北省保安司令（后期投敌）、伪河北省保安司令（活动于衡水一带）、伪河北省政府民政厅长（后投敌）、伪河北省政府民政厅长（后投敌）、河北民军总指挥（叛变前）、冀中‘剿共’总司令（后投敌）、冀中保安司令、冀中保安司令、国民党河北民军总指挥、冀中保安司令、国民党河北民军总指挥（后投日）、冀中保安司令、河北省保安司令、冀中保安司令、河北省保安处处长、冀中保安司令、河北省政府委员、冀南地区伪军头目（活动于邯郸周边）、冀察战区游击司令、国民党河北民军总指挥、冀察战区游击司令、国民党河北省政府民政厅长（后投日）、冀察战区游击司令、河北省保安司令、冀察战区游击总司令（后投敌）、冀察战区游击总司令（后投日）、国民党河北民军总指挥（后投敌）、国民党河北民军总指挥（后投日）、河北民军总指挥、国民党河北省政府民政厅长、河北民军总指挥（后投敌）、河北民军总指挥（后投日）', '1935-1945', '', '率伪军配合日军“铁壁合围”，在密云云蒙山区烧毁村庄数十个。；原国民党将领，后与日军勾结，在保定地区组织伪军，协助日军清剿抗日武装。；原国民党河北省民政厅长，投日后负责保定地区伪政权行政事务，协助日军强征粮食、劳工，在白沟新城一带破坏抗日地道。；原国民党将领，抗战初期在河北组织民军，后与日军勾结，在保定地区协助日伪清剿抗日武装。；原国民党将领，后与日军勾结，任伪河北省保安司令，在保定地区组织伪军袭扰抗日武装。……（共涉及70个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
