REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b0f4d279a7185c07a07bc0b51ee6ecd0', '张鸿恩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪临汾县知事（兼安泽部分地区）、伪屯留县新民会会长、陵川县伪保安队大队长', '1938-1945', '', '在临汾及周边地区（含安泽西部）任伪职，为日军提供情报，强征捐税，并参与建立伪自卫团，镇压抗日活动。；率伪保安队配合日军“清乡”，烧杀抢掠，袭击抗日游击队，杀害多名抗日干部。；宣传奴化思想，推行‘中日亲善’，诱骗青年参加伪军，破坏抗日宣传。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('353c8cfa41425366aac026ee84be9d09', '张鸿惠', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪晋城县维持会会长、伪沁水县保安队队长、伪沁水县知事（县长）、伪阳城县保安队大队长、伪高平县知事、晋城县伪保安队大队长、晋城县伪县长', '1938-1945', '', '日军首次侵占晋城时组织维持会，为日军带路清乡，指认抗日家属，勒索商民钱财，后随日军撤退而逃亡。；组建伪保安队，配合日军扫荡晋城周边抗日根据地，多次带队袭击八路军游击队，杀害抗日干部和群众，掠夺物资。；率伪军配合日军进攻抗日根据地，抓捕并杀害抗日干部和群众。；投靠日军，任伪沁水县知事，推行保甲制度，组织伪警备队，配合日军扫荡抗日根据地，杀害多名抗日干部和群众。；率伪军多次配合日军扫荡抗日根据地，捕杀抗日干部和群众，制造多起惨案。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('40763cd48b925562b705c0efe0152e7d', '张鸿渐', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪吕梁保安队副队长、伪唐山中学日语教员（奴化教育推行者）、伪孝义县保安团长、伪山海关特务机关翻译、伪山西省公署警务厅厅长（涉及太原及娄烦）、伪晋城县知事（继任）、伪灵石县保安队队长、伪长治县维持会会长、伪阳泉保安队队长', '1933-1945', '', '在孝义县配合日军修建碉堡，强拆民房，迫害百姓。；率伪保安队驻守交口川口一带，参与日军“三光”政策行动，烧毁村庄十余个，抢劫牲畜粮食。；指挥伪警察协助日军在太原、娄烦等地搜捕抗日分子，破坏地下组织。；率伪保安队多次袭击灵石东部山区抗日游击队，抓捕抗日干部及家属，并参与日军‘三光’政策行动，烧毁村庄多处。；在任期间推行“保甲连坐”，多次配合日军扫荡晋城山区，杀害抗日家属。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
