REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('79e7e646fe015498957dfd5a81770d62', '德王（德穆楚克栋鲁普）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪蒙疆联合自治政府主席（曾到长春）', '1939-1945', '', '多次赴长春（新京）与伪满高层会晤，配合日本分裂中国，间接影响吉林地区。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('03751651c36952668c9b65b923b9c221', '德穆楚克栋鲁普（德王）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、北京、天津、山西、河北', '内蒙古、北京、天津、山西、河北', '[]', '伪蒙古军政府总裁、伪蒙古联合自治政府主席、伪蒙古联合自治政府主席、伪蒙古联盟自治政府主席、伪蒙古联盟自治政府主席、伪蒙古联合自治政府主席、伪蒙古联盟自治政府主席、伪蒙疆联合自治政府主席、伪蒙疆联合自治政府主席、伪蒙疆联合自治政府主席、伪蒙古军总司令、伪蒙疆联合自治政府主席（影响通辽地区）、伪蒙疆联合自治政府主席（辖大同）、蒙疆联合自治政府主席、蒙疆联合自治政府主席、伪蒙古军总司令', '1933-1945', '', '蒙古王公，长期与日本关东军勾结，在乌兰察布地区推行“蒙古自治”，建立伪政权，为日军提供兵员和情报，协助统治当地。；蒙古王公，长期策划“蒙古独立”，1936年成立伪蒙古军政府，1939年任伪蒙疆政府主席，其势力覆盖乌兰察布、兴和地区，为日军提供兵员和情报，镇压抗日活动。；蒙古王公，投靠日本，建立伪蒙政权，其势力范围包括乌兰察布盟及凉城一带，配合日军“治安肃正”，征粮抓丁，迫害抗日军民。；在化德（当时称嘉卜寺）建立伪蒙古军政府，后任蒙疆联合自治政府主席，积极投靠日本，组织伪蒙古军配合日军进攻绥远等地。；蒙古族王公，组织伪蒙疆政权，与日军合作，在乌兰察布、卓资一带推行殖民统治，征粮征兵，协助日军清剿抗日武装。……（共涉及85个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
