REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d8e3752c5dc55e6c9c94ad8656294399', '曲秉善', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪满四平省次长（实际掌权者，日系官员）、伪满四平省警务厅厅长', '1941-1945', '', '日本关东军指派，实际控制四平省政务，实施经济统制，抓捕抗日分子，强征慰安妇。；原伪满警察，投日后任四平省警务厅厅长，在四平、伊通地区建立情报网，多次破坏抗日地下组织，逮捕爱国人士。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6dbfe760db385190b48f318c9807b9cc', '曹仲参', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满洲国锦州省兴城县县长', '1932-1945', '', '原兴城地方士绅，投日后任伪兴城县县长，强征粮税，组织伪县公署配合日军“扫荡”，迫害抗日家属。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3de6f584b1b75a69a535180aca36f08a', '曹承宗', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪安东县（今丹东市）县长、伪宽甸县县长、伪普兰店地区保安队队长、伪满东边道保安司令、伪满凤城县县长、伪满安东市市长、伪满安东市市长（今丹东市区）、伪满昌图县县长、伪满沈阳县县长、伪满洲国奉天市副市长、伪满辽阳地区宪兵队翻译官、伪满鞍山宪兵队翻译官、伪满鞍山警察署署长、伪辽阳警务处长', '1932-1945', '', '任伪安东市（今丹东）市长，推行日伪经济统制，强征劳工，协助日军建立治安维持会，镇压市民反抗。；活动于东港、凤城一带，率伪军配合日军围剿抗日义勇军，烧毁村庄，残害百姓。；原凤城县地方士绅，投日后任伪满凤城县县长，在凤城地区推行保甲制度，强征劳工，镇压抗日义勇军。；首任伪宽甸县长，协助日军建立伪政权，强征民夫修建警备道路和碉堡，镇压当地抗日义勇军。；任伪安东市长期间，推行日伪经济统制，强征劳工，镇压市区抗日活动。……（共涉及14个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('623d392eb5a05d4cac7b4f9ccb0a1da6', '曹汝霖', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、河北', '北京、天津、河北', '[]', '伪华北政务委员会咨询委员、伪华北政务委员会咨询委员（天津活动）、伪华北政务委员会咨询委员（居天津）、伪华北政务委员会咨询委员（晚年居天津活动）、伪华北政务委员会咨询委员（未实际任职但参与活动）、伪华北政务委员会咨询委员（未实际就任但参与活动）、伪华北政务委员会咨询委员（未正式就任但参与活动）', '1937-1945', '', '北洋时期政客，北平沦陷后接受伪职，虽未直接掌权，但利用旧关系为日伪政权笼络人心。；原亲日政客，虽未任实职，但为日伪在北平及昌平的活动提供政治支持。；虽未任实职，但在北平与日伪高层往来，为日伪政权提供政治咨询，影响海淀地区亲日势力；北洋政客，投靠日伪，为伪政权出谋划策。；虽为咨询委员，但多次在天津活动，利用旧关系为日伪拉拢社会人士。……（共涉及10个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
