REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8311bd43c1a4556b92f1cef846b178b6', '李二狗', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪左权县密探、古冶伪警察所巡官', '1938-1945', '', '向日军报告八路军医院位置，导致医院被袭，多名伤员被杀。；带领伪警察搜查抗日地下联络点，参与镇压古冶矿区工人罢工，迫害进步矿工。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('86914728d0fc5a8691ce53474d3719f7', '李二虎', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪平乡县保安队长（今属邢台）', '1940-1945', '', '率保安队多次围剿平乡县抗日游击队，杀害群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5ae0b0684cc4589db47453bfb3b3708c', '李仲三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪保定道尹公署顾问、伪定兴县新民会会长、伪定县维持会会长、伪徐水县警察局局长、伪涿县新民会会长、伪涿鹿县维持会会长、伪蒙疆政府张家口地区保安队队长、房山县伪县长', '1937-1945', '', '投靠日军，任房山县伪县长，协助日军推行保甲制度，强征民夫，搜刮粮食，镇压抗日活动。；负责日伪宣传和奴化教育，组织‘新民会’搜集抗日情报，强迫民众参加反共集会。；日军占领定县后，出任维持会长，为日军筹集物资，强征民夫，协助建立伪县署。；指挥伪警察搜捕抗日地下党员，破坏中共地下组织，多次带队袭击徐水周边村庄。；主持新民会涿县分会，推行奴化教育，组织“反共救国会”，搜集抗日情报，协助日军抓捕进步青年。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3f9b986d40525a7784eb5032a6b5d8eb', '李仲允', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪顺平县（完县）知事', '1938-1943', '', '任伪完县县长期间，推行保甲制度，强征粮饷，协助日军建立据点，抓捕抗日干部，破坏地下组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7caaf63588be5c8ca34ab9ae8bd818bb', '李仲平', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪曲阳县知事、伪望都县维持会会长、涞水县伪县长', '1937-1945', '', '投靠日军，任曲阳县伪政权首脑，协助日军推行‘治安强化运动’，强征民夫修筑炮楼据点，镇压抗日群众。；日军占领望都后，率先组织维持会，为日军提供粮秣、民夫情报，协助建立伪政权，并参与诱降抗日分子，破坏当地地下党组织。；投靠日军，任涞水县伪县长，协助日军推行“治安强化运动”，强征民夫、粮食，镇压抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('316ac7ce2af5541e82177cfb3eec52dd', '李仲章', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪保定市市长、伪保定道尹公署道尹、伪唐县维持会会长、伪容城县警察局局长', '1937-1945', '', '任伪保定地区行政长官，推行日伪保甲制度，强征粮食，镇压抗日活动。；日军占领唐县后出任维持会长，为日军征粮派夫，出卖抗日积极分子。；组织伪警察配合日军清乡，抓捕地下党员，破坏交通线，参与“治安强化运动”。；任伪保定市市长期间，积极推行日伪政权各项政策，强征民夫，搜刮粮食，协助日军建立保甲制度，镇压抗日活动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5a987d9102265eba9baf4a023d34f9ae', '李体仁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪平山县县长、伪正定县知事、伪石家庄地区保安司令、伪石家庄市公署市长、伪石家庄市市长、伪石家庄市市长（1940-1944）、伪石门市警察局局长、伪获鹿县知事、伪获鹿县（今鹿泉区）知事', '1938-1945', '', '在正定县（今属石家庄）任伪知事，残酷镇压正定教堂惨案后的抗日活动，协助日军屠杀平民。；首任伪平山县长，组建伪县公署和伪警察所，多次带日伪军袭击平山抗日根据地，杀害村干部。；任伪市长期间，推行日伪政权政策，强征民夫修建军事设施，配合日军经济掠夺。；负责伪石门市（今石家庄）治安，协助日军特务机关搜捕抗日地下人员，实施保甲连坐制度，镇压市民反抗。；组织伪保安队配合日军扫荡，抓捕抗日军民，破坏地下组织。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
