REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('13f640997bf957c680c3a89ec672b307', '李允声', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东保安队第四总队队长、伪唐山矿区矿警队长、伪治安军第三集团军司令、冀东伪军第二师师长', '1935-1945', '', '镇压矿工罢工，为日军护矿，迫害进步工人。；驻防唐山地区，协助日军收缴民间武器，强征壮丁，破坏抗日组织。；驻防唐山地区，协助日军“治安肃正”，抓捕抗日地下工作者。；率伪治安军驻冀东，参与1942年“五一大扫荡”在路南地区的行动，烧杀抢掠。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3f227cbbf3cf5ad685e893c899c0087f', '李元亨', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府迁安县县长、伪安次县知事、伪玉田县警察局局长、伪秦皇岛商会会长、伪芦台镇维持会会长、伪迁安县新民会会长、伪迁西县保安队队长', '1935-1945', '', '在芦台镇（今芦台经开区一带）组织维持会，为日军提供粮食、劳力和情报，协助镇压当地抗日武装。；在迁安（今属唐山）配合日军进攻冀东抗日根据地。；指挥伪警察在玉田县内搜捕抗日地下党员，破坏抗日组织。；在迁安推行新民会奴化宣传，组织青少年接受日伪教育，收集抗日情报，协助日军“宣抚”工作。；率伪保安队常驻迁西金厂峪一带，为日军护矿，镇压矿工反抗，杀害抗日游击队员。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
