REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('149dcf8873e359459d3e861031b92afc', '李凤山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府唐山保安团长、伪冀县维持会会长、伪冀县（今冀州区，属衡水）保安联队副、伪宽城维持会会长、伪捷地镇自卫团团长、伪新乐县保安队队长、伪曲阳县新民会会长、伪束鹿县保安队队长、伪桃城区（原衡水县城关）维持会会长、伪清河县警察所所长、伪热河省承德县保安队队长、伪献县警察局局长、伪辛集县保安队队长、伪高邑县保安联队队长、冀县（今冀州区）伪自卫团团长、威县伪维持会会长、巨鹿县伪新民会会长、广宗县伪新民会会长、新河县伪保安联队队长、晋县伪保安联队队长、栾城县伪保安联队队长、栾城县伪新民会会长、武邑县伪保安联队队长、深泽县伪新民会会长、灵寿县伪新民会会长、衡水县伪保安大队长、赵县伪保安联队队长、邢台县伪维持会会长、饶阳县伪保安联队队长、饶阳县伪警察所所长、高邑县伪保安联队队长', '1933-1945', '', '为日军宣传奴化思想，组织汉奸情报网，刺探抗日军情，协助日军搜捕抗日分子。；在唐山市区维持伪秩序，协助日军宪兵队镇压反抗。；日军占领宽城后出任维持会长，为日军征粮派夫，协助建立伪政权，镇压抗日活动，民愤极大。；投靠日伪，任承德县保安队长，率伪军配合日军扫荡滦平、承德山区，杀害抗日军民。；效忠日寇，负责情报搜集，破坏地下党组织，逮捕并刑讯抗日志士。……（共涉及32个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('74e3d6eb4c6c5e94abb098c1227ebe40', '李凤阁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '景县伪警察所所长', '1940-1945', '', '负责景县日伪警察机构，搜捕抗日地下党员和进步人士，严刑逼供，破坏抗日组织，协助日军推行保甲制度。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6f751e18423658f9ab3bd9eec482adb9', '李凤鸣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北、辽宁', '山西、河北、辽宁', '[]', '伪东光县新民会会长、伪东光县知事、伪保德县维持会会长、伪冀南道宣传室主任、伪吴桥县新民会会长、伪忻县维持会会长、伪忻县警察局局长、伪永和县维持会会长、伪海兴县新民会会长、伪满安东省税务局局长、伪行唐县警察所所长、伪赵县知事、伪阳泉区维持会会长、伪阳泉矿警队队长、伪静乐县警察所所长、晋县伪保安队大队长、柏乡县伪新民会会长、灵寿县伪警察所所长', '1932-1945', '', '组织维持会为日军征粮派款，提供情报，并强迫百姓悬挂日伪旗帜，破坏抗日组织地下活动。；充当日军走狗，负责为日军筹粮派款，强迫百姓领取“良民证”，并告密导致多名地下党员被捕牺牲。；为日军筹粮派款，强迫百姓“欢迎皇军”，提供情报，协助日军建立伪政权。；任伪警察局长，执行日伪法令，搜捕抗日地下党员，参与“治安强化运动”。；为日军搜集抗日情报，抓捕地下党员和进步群众，严刑逼供，并参与“清乡”行动，破坏抗日组织。……（共涉及18个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
