REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ea312516ba1e5a3986ae8764f54687ab', '李宝森', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪沁县知事、伪潞城县保安队队长', '1939-1942', '', '为日军提供沁县抗日武装活动情报，导致八路军多次遭袭，损失惨重。；率伪保安队多次配合日军扫荡抗日根据地，抓捕抗日干部和群众，烧毁村庄，抢劫财物。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bc02e3f1a58b5e9c81c09582d1fabde8', '李宝楚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津', '天津', '[]', '伪天津特别市公署教育局长', '1938-1945', '', '推行奴化教育，强制学校教授日语，删除抗日内容。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('856aecc2ad89591db14877291eb6613c', '李宝珍', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪冀东特别区保安司令、伪唐山警察局局长、伪通县警察署署长、伪顺义县警察局局长', '1938-1945', '', '执行日伪“连坐”制度，逮捕大量抗日嫌疑人员，严刑逼供，致多人死亡。；协助日军搜捕抗日分子，严刑拷打被捕人员，提供情报给日军。；指挥伪警察在唐山市区搜捕抗日分子，破坏地下组织。；统辖伪军警，在路南地区实行“连坐清乡”，破坏抗日根据地。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c1c1ed0add425f0aa51eb37da604b7bd', '李宝荣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津', '天津', '[]', '伪天津县知事、伪天津河东区警察署署长、伪天津特别市第六区（红桥部分）区长', '1939-1945', '', '负责伪天津县行政，对东丽地区实施粮食统制，强征物资，并组织汉奸武装配合日军扫荡。；在河东区警察署任职期间，积极协助日军清剿抗日武装，逮捕爱国群众，破坏地下抗日组织。；在红桥西沽、丁字沽一带推行日伪“米谷统制”，导致百姓饿殍，并协助日军强拆民房建工事。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d02f2f9296a7509fa051c8ebe09107a2', '李宣倜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京', '北京', '[]', '伪华北政务委员会总务厅厅长、伪华北政务委员会教育总署督办（继张璧后）、伪大兴县知事（继任）', '1940-1945', '', '任内推行“保甲连坐”，在大兴各村设立伪保长，搜捕抗日干部，向日军提供粮食和情报。；在北平主持伪政权日常行政，协调昌平地区伪县署工作。；在北平（含海淀）推行日本化教育，强制学生学日语，迫害拒绝合作的教师学生', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e64ea89ff82b5c2ea3b15879d8539fbb', '李宪文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪晋源县（今太原晋源区）知事', '1938-1940', '', '在晋源地区推行日伪政权，征收苛捐杂税，强迫民众劳役。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f13fea3281b35a0ea71eb3863d7d53f7', '李寿山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪义县县长、伪大连港务局局长、伪安东地区警察署长、汉奸武装头目、伪岫岩县县长、伪抚顺矿务局总办（汉奸矿主）、伪满台安县县长、伪满奉天省警务厅厅长、伪满安东省协和会会长、伪满安东省警务厅厅长、伪满安东省警务厅长、伪满开原县县长、伪满彰武县县长（1933-1938）、伪满抚顺宪兵队翻译官、伪满昌图地区保安队队长、伪满朝阳地区保安队队长、伪满本溪湖市市长、伪满本溪湖市市长（本溪湖为今本溪市前身）、伪满本溪湖警察署署长、伪满桓仁县县长、伪满梨树县警务科长、伪满洲国军旅长、盘山地区伪保安队长、伪满洲国大连地区警察署长、伪满洲国大连宪兵队翻译官、伪满洲国奉天省保安局局长、伪满洲国奉天省辽阳县县长、伪满洲国盘山县县长、伪满洲国盘山县县长（今盘锦市大洼区一带）、伪满洲国绥中县县长、伪满洲国营口地区保安队队长、伪满洲国锦州省省长、伪满洲国阜新市协和会会长、伪满海城县县长、伪满清原县县长、伪满盖平县警务科科长、伪满盘山县警务科长、伪满立山地区维持会会长、伪满营口县保安队队长、伪满营口警察局局长、伪满西安县保安队队长、伪满西安县（今辽源）警务局长、伪满辽中县警务科长、伪满辽宁地区保安队头目（活动于沈阳周边）、伪满辽源县县长、伪满辽源县（今辽源市）县长、伪满辽阳县县长、伪满辽阳县长、伪满铁岭保安队队长、伪满铁岭县县长、伪满铁岭县清河城子警察署署长、伪满铁西区区长、伪满银州地区警察署署长、伪满锦州地区保安队头目、伪满锦州省协和会会长、伪满锦州省警务厅长、伪满锦西县（今葫芦岛市连山区）县长、伪满阜新地区警察署长、伪满鞍山地区保安队队长、汉奸、伪满鞍山铁东区区长、伪满鸭绿江地区“讨伐”司令、伪满黑山县县长、伪热河省朝阳县县长、伪磐石县警察署署长、伪辽阳县长、汉奸、伪辽阳地区保安队队长、伪辽阳地方维持会会长、伪锦州省保安队司令、伪锦州省警务厅厅长、伪鞍山保安队队长、蛟河伪保安队队长', '1931-1945', '', '梨树县伪警务负责人，直接指挥警察特务搜捕地下抗日组织，多次参与屠杀抗日群众。；积极推行“归屯并户”，切断抗日武装与群众联系，多次率警察袭击磐石抗日游击队营地，并实施“连坐”政策。；充当日军走狗，带领保安队抓捕抗日军民，破坏地下组织，强征民夫修筑军事工事。；在辽源地区任伪县长，积极执行日伪“治安肃正”政策，协助日军建立“集团部落”，迫害抗日家属。；九一八后投敌，任伪警务局长，组织伪警察配合日军清乡，逮捕抗日志士，并参与“讨伐”活动。……（共涉及74个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
