REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f145c20197cc5cebbd6f995535fc8252', '李幼卿', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪滦县知事', '1939-1943', '', '在滦县（今属唐山市）任伪县长，积极为日军提供粮食和情报，参与“治安强化运动”，杀害多名抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5b3035771bcb5af296de74b244a40123', '李广谦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪潞城县知事', '1939-1945', '', '充当日军傀儡，在潞城地区建立伪政权，征收苛捐杂税，配合日军‘扫荡’，逮捕抗日军民，并参与诱降活动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
