REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0f049069cc8c5406a9bd916729197bba', '李廷俊', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '临县伪区公所区长、岚县伪警察所所长、繁峙县伪新民会会长', '1939-1945', '', '在临县多个伪区公所任职，强征壮丁和物资，协助日军建立据点，欺压百姓。；充当日军爪牙，负责岚县县城治安，多次带队搜捕地下党员，刑讯逼供抗日志士。；主持伪新民会，宣传“中日亲善”，强迫民众参加反共集会，收集抗日活动情报。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5c3741669af15a6e9889a80ed6b45794', '李廷玉', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、山西、河北', '天津、山西、河北', '[]', '伪天津县知事（县长）、伪天津特别市保安队司令、伪天津特别市公署卫生局局长、伪晋城县财政科科长、定襄县伪警察局局长、文水县伪警察所所长、无极县伪县长、浮山县伪保安队队长', '1938-1945', '', '配合日军731部队相关实验，在南开区设立“防疫所”，以体检为名抽取平民血液，参与细菌战人体试验辅助工作。；指挥伪保安队协助日军清剿抗日武装，在河西地区及周边进行“扫荡”，残害百姓。；在天津县推行日伪保甲制，强征民夫修建日军工事，勒索百姓，协助日军扫荡郊区抗日武装；率伪保安队多次配合日军袭击浮山抗日游击队，杀害抗日干部和群众，烧毁村庄，掠夺财物。；为日军搜集抗日情报，逮捕抗日军民，严刑逼供，参与制造多起惨案。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
