REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f1b0a9df69ed5e799898751cff97e28e', '李律阁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津', '天津', '[]', '伪天津市财政局局长', '1938-1945', '', '为日伪政权征收苛捐杂税，发行伪币，掠夺民间财富，支持日军战争开支。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
