REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bfd40f1709945a61b3282a776d9a8a61', '李德懋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪山西新民会吕梁分会主任、伪平顺县知事、伪平顺县维持会会长、伪晋中道尹（驻榆次，管辖灵石等县）、伪晋城商会会长、伪沁县保安队队长、伪长治县知事（县长）', '1938-1945', '', '在交口、孝义等地推行奴化教育，组织“新民会”宣传“中日亲善”，强迫民众悬挂日伪旗，破坏抗日群众组织。；作为伪晋中道最高行政长官，督导灵石等县伪政权推行保甲制度，强征粮食棉花供日军军需，并协助日军建立情报网，破坏抗日地下组织。；为日军统制物资，强迫商户捐献，为伪军代购军粮，从中牟利。；1938年日军侵占平顺后出任伪县知事，协助日军建立维持会，强征民夫修筑碉堡公路，搜刮粮食供给日军，并组织伪警备队镇压抗日群众。；日军首次侵占平顺时组织维持会，为日军带路清乡，指认抗日家属，强迫百姓领取“良民证”，并参与诱降抗日干部。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a395a48f8aa0596da4adb5c008740758', '李德盛', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪武乡县保安队队长', '1940-1945', '', '任伪保安队长，率伪军协助日军袭击八路军后方机关，在武乡东部地区烧杀抢掠，杀害抗日军属多名。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5c921e3d243b56ecb74f90581038ff0d', '李德胜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '交城县伪维持会会长、伪垣曲县警察局局长、伪娄烦县保安队队长、伪屯留县保安队队长、伪榆社县新民会会长、伪沁水县新民会会长、伪沁源县保安队队长、伪沁源县维持会会长、伪黎城县保安队队长、垣曲县伪警察局长、壶关县伪保安队队长、沁县伪警察局局长、襄垣县伪保安队队长', '1937-1945', '', '日军占领交城后率先组织维持会，为日军筹粮派款，强迫百姓领取“良民证”。；率保安队配合日军扫荡抗日根据地，抓捕抗日干部和群众，抢掠物资。；推行奴化教育，宣传“中日亲善”，诱骗青年参加伪军，破坏抗日统一战线。；在沁水组织“青年训练班”，灌输亲日思想，为日军输送伪军人员。；在日军占领期间任伪警察局长，负责侦缉抗日地下人员，严刑拷打被捕者，并协助日军推行“治安强化运动”。……（共涉及12个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
