REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f7f8040dcded5eeda38e25c365225d63', '李振声', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪安国县保安联队队长、伪易县警察所所长、伪望都县警察所所长、伪涞源县警察所所长、伪满城县新民会会长、伪邯郸县建设科科长', '1938-1945', '', '组织伪保安队，配合日军扫荡安国抗日根据地，多次带队袭击八路军游击队，杀害抗日干部和群众。；率伪警察配合日军“清乡”，逮捕抗日群众，严刑逼供，并参与屠杀狼牙山地区村民。；在望都县城内建立特务情报网，侦捕抗日地下党员，严刑逼供，导致多名抗日人员牺牲或被捕。；任伪警察所长期间，指挥伪警搜捕抗日家属，破坏交通线，多次带队突袭村庄，抢劫财物，并参与杀害被俘的八路军伤员。；负责在满城推行奴化教育，组织“新民会”宣传亲日思想，强迫民众参加反共集会。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0251c8ba9750503f8cd710ef6daac795', '李效民', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪中阳县保安队长、伪离石县新民会会长、晋城县伪县长、陵川县维持会会长', '1938-1945', '', '率伪军在中阳、石楼一带袭击八路军游击队，杀害群众。；负责在离石推行奴化教育，宣传“中日亲善”，强迫民众参加反共集会，并收集抗日情报供日军。；投靠日军后出任晋城县维持会会长及伪县长，协助日军推行“治安强化运动”，强征民夫、粮食，镇压抗日群众，破坏地下抗日组织。；投靠日军，组织维持会，为日军征粮派款，协助日军建立伪政权，镇压抗日群众。；组织伪维持会，为日军征粮派款，协助日军建立伪政权，镇压抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
