REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('1aadec610c17599bb555d2d02824acf3', '李春芳', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北、辽宁', '山西、河北、辽宁', '[]', '伪临县警备队长、伪冀东防共自治政府唐山税务局长、伪昔阳县维持会会长、伪沁源县警察局局长、伪热河省建昌县保安队队长、伪石家庄商会会长（汉奸商人）、伪翼城县情报室主任、伪邢台县维持会会长', '1935-1945', '', '专门收集八路军和游击队活动情报，多次引导日军突袭翼城抗日村庄。；在临县率伪军袭击八路军后方医院，杀害伤员。；出卖昔阳抗日村长名单，导致7名村长被日军杀害。；指挥伪警察搜捕抗日分子，严刑逼供，破坏抗日地下交通线。；在唐山地区横征暴敛，导致商户破产，民怨沸腾。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
