REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('de1c90ae87515e0d92d96d597d4ef98a', '李春荣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府唐山土地局长、伪满洲国承德县警务科科长', '1935-1943', '', '在唐山郊区掠夺土地，导致农民流离失所。；在承德、宽城交界地区指挥伪警察队，多次袭击抗日根据地，杀害抗日干部和群众，并参与制造“无人区”行动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a57c8933c51552e5b69feda6eb2411f0', '李春荣（同名）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府唐山地主', '1935-1938', '', '在唐山郊区为日军提供粮食，欺压佃农。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a5db6ac48f775b13b780a694d8dec4d1', '李景和', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪井陉县知事、伪井陉矿警备队队长、伪沙河县警备队大队长', '1938-1945', '', '投日汉奸，任伪井陉县知事，在井陉矿区推行日伪政权，强征粮食和劳工，协助日军建立“爱护村”以隔离抗日武装。；充当日军爪牙，负责井陉煤矿的警戒，镇压矿工反抗，抓捕并杀害抗日地下工作者。；率伪警备队多次配合日军扫荡抗日根据地，杀害抗日干部和群众，烧毁村庄，抢劫财物。；率伪警备队多次袭击抗日村庄，抓捕并杀害抗日干部和群众，烧毁民房，民愤极大。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3d749df4036853df9ae3fcfecd4a76ae', '李景文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪南宫县保安联队队长、伪孟村维持会会长、伪巨鹿县新民会会长、伪武安县新民会会长、伪武安县（今属邯郸）知事、伪沧县（含今黄骅部分区域）警备大队长、伪邢台县维持会会长、伪邯郸县监狱典狱长、伪阳泉矿区维持会会长、伪高邑县保安联队队长、元氏县伪保安联队队长、宁晋县伪保安联队长、平乡县伪保安联队队长、永年县伪情报股长、赞皇县伪警察所所长', '1937-1945', '', '日军占领阳泉后首任维持会长，组织矿工为日军无偿劳动，克扣矿工口粮，协助日军掠夺煤炭资源，迫害反抗矿工。；在孟村成立伪维持会，为日军征集粮饷、抓派民夫，破坏抗日组织，曾指认并抓捕多名抗日地下工作人员。；长期盘踞沧县东部及黄骅沿海地区，为日军运输物资、封锁港口，抓捕抗日志士，并强征民夫修建炮楼和封锁沟。；率伪军多次扫荡抗日根据地，杀害抗日干部和群众，制造多起惨案。；率伪军配合日军“扫荡”抗日根据地，杀害抗日干部和群众，破坏抗日组织，烧毁村庄。……（共涉及16个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3720970371315007b5ae28dc02cc15c3', '李景明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪丰润县知事（县长）、伪冀东防共自治政府教育厅长、伪延庆县知事（县长）', '1935-1943', '', '在延庆县任伪县长期间，强征民夫修筑炮楼和公路，组织伪自卫团，配合日军对南山（平北根据地）进行“蚕食”。；在丰润县任伪职期间，积极推行日伪“治安强化运动”，组织伪警察和保甲武装，配合日军扫荡抗日根据地，残害抗日军民。；推行奴化教育，在唐山、汉沽等地学校强制教授日语，删改历史教材，灌输“中日亲善”思想。；推行奴化教育，在唐山等地学校强制灌输亲日思想。；推行奴化教育，在秦皇岛、北戴河等地学校强制灌输亲日思想，破坏中国教育体系。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('caabca1e295359f2ace056f707097122', '李景春', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '临城县伪新民会会长、临城县伪维持会会长、伪任县新民会会长、伪大同省公署参事、伪忻州道公署顾问（兼宁武事务）、伪邢台县新民会会长、伪邱县保安联队队长、伪阳泉矿区区长、内丘县伪新民会会长、尧山县（今属隆尧）伪维持会会长、平乡县伪保安联队队长、成安县伪教育科科长、阜城县伪自卫团团长', '1937-1945', '', '原为晋系地方官员，投日后任伪大同省参事，参与策划对阳高、大同地区的经济掠夺和奴化教育。；作为伪忻州道顾问，参与策划对宁武抗日根据地的经济封锁，指使伪军抢掠百姓财物，并参与诱降抗日人员，破坏地下抗日组织。；在日军扶植下担任伪区长，推行保甲制度，强征劳工，搜刮民财，为日军提供情报，协助日军扫荡抗日根据地。；组织伪自卫团协助日军驻守据点，袭击八路军游击队，抢劫百姓财物。；日军占领临城后率先组织维持会，为日军征粮派款，充当汉奸走狗。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a3eb8307fd6a5cd5a48713eabac55d34', '李景林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北、辽宁', '天津、河北、辽宁', '[]', '井陉县伪县长、伪临城县知事（今属邢台）、伪保定地区清乡督察专员、伪保定绥靖军第3集团军第6旅旅长、伪兴隆县自卫团总团长、伪冀中道尹（驻沧州）、伪冀中道尹（驻衡水）、伪冀南道公署参议、伪冀南道尹（辖石家庄部分县）、伪冀南道特务队长、伪吴桥县警察所所长、伪天津地区剿共司令、伪孟村维持会会长、伪平山县维持会会长、伪永清县自卫团总团长、伪沧县保安队队长、伪沧县知事、伪沧县知事（县长）、伪沧州保安队队长、伪沧州警备队大队长、伪沧州道公署顾问、伪沧州道尹、伪沧州道尹公署道尹、伪沧州道尹公署顾问、伪沧州道尹公署顾问（盐山籍）、伪渤海道尹、伪渤海道尹公署顾问、伪满盘山县司法科审判官、伪献县知事（县长）、伪衡水县保安联队队长、伪赞皇县知事、伪邢台县保安联队长、伪邢台县财政科长、冀南道伪道尹（辖衡水、枣强等县）、安平县伪保安联队队长、深县伪警察所所长', '1937-1945', '', '统率伪军多次对静海、大港等地区进行“清乡”，烧杀抢掠，制造无人区。；原地方军阀余部，投日后负责清乡，在莲池周边多次组织“扫荡”，杀害抗日干部，抢劫民财，纵容部下奸淫妇女。；率伪军驻防保定及高碑店一带，多次参与对八路军冀中根据地的进攻，烧杀抢掠，民愤极大。；组织地方自卫团，配合日军“扫荡”，在永清西部村庄烧杀抢掠，杀害多名八路军伤员。；组织自卫团协助日军封锁山区，切断抗日武装补给线，并亲自带队搜捕抗日游击队员，杀害多名伤员。……（共涉及42个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8faf63f4b2be5d7587e5fe74340a691f', '李景铭', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津', '北京、天津', '[]', '伪北平市财政局局长、伪昌平县知事（约1941-1943）、伪津海道尹（辖津南地区）', '1938-1945', '', '在昌平推行“治安强化”政策，组织伪自卫团，配合日军扫荡。；负责为日伪在门头沟征收苛捐杂税，勒索矿商，导致民生凋敝，间接削弱抗日力量。；管辖津南各县伪政权，强征粮食、壮丁，支持日军在津南的军事行动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('74939f2eb4a25a24b630d7c5cf8f1ac0', '李景阳', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪蒙疆政府驻赤城特务机关长', '1942-1945', '', '负责赤城地区特务情报工作，策反抗日人员，破坏中共地下交通线。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('1e1686faacd95d618346c5a3cd2821c2', '李景韩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪阳城县保安队分队长', '1940-1940', '', '率伪军袭击抗日区公所，杀害区长及通讯员，抢劫公粮。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
