REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a101512bf69455ea94f0a94fa807662e', '李润生', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪冀东防共自治政府唐山银行经理、伪太谷县维持会会长、伪山西剿共军团长（活动于古交山区）、伪新荣区维持会会长、寿阳县伪保安队队长', '1935-1945', '', '在新荣地区（今新荣区）组织维持会，为日军征收粮税，提供情报，强迫村民修炮楼、修公路，多次带领日军袭击八路军小分队。；率伪军参与对古交抗日根据地的“铁壁合围”，烧毁村庄，屠杀民众。；组建伪保安队，多次配合日军袭击寿阳抗日游击队，抓捕抗日干部，并参与“清乡”行动，残害百姓。；向日军报告八路军动向，导致太谷南山根据地多次遭袭，多名民兵被杀。；在唐山操纵金融，为日军侵华战争提供资金。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d8e21398f82d5a1f899ad13d36a25c6e', '李润生（同名）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府唐山钱庄老板', '1935-1938', '', '在唐山为日军洗钱，资助侵华战争。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
