REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5ddb13935d765e6f8714d41d4654e1c7', '李福和', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪临漳县县长、伪临漳县知事、伪冀东防共自治政府保安队头目（后调任石家庄地区伪军头目）、伪冀东防共自治政府保安队队长、伪满军旅长、伪冀南剿共军司令（活动于衡水）、伪冀南剿共军司令（活动于邯郸地区）、伪冀南道尹、伪大名县知事、伪冀南道尹、伪邯郸县知事、伪冀南道尹公署道尹、伪冀南道尹公署道尹、伪邯郸县知事、伪冀南道尹公署顾问、伪冀南道尹兼保安司令、伪冀南道尹（涉县属其辖区）、伪冀南道尹（管辖邯郸地区）、伪山西剿共军第5师师长（活动涉及晋东南）、伪皇协军第一军军长（活动于石家庄西部山区）', '1931-1945', '', '率部在晋中、左权边缘地区骚扰，配合日军抢粮，杀害抗日群众。；原为东北军军官，后投靠日军，在冀中地区协助日军清剿抗日武装，1938年因内部矛盾被处决。；率伪军在井陉、平山一带配合日军进攻八路军，屠杀抗日群众，后因内讧被日军处决。；原国民党军官，投日后在冀东及石家庄周边组织伪军，参与对正太铁路沿线抗日游击队的围剿，后因内讧被日军处决。；组织伪剿共军，专门搜捕抗日地下党员，在安平、衡水交界处设立集中营，残害抗日志士。……（共涉及23个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2dcd18836ea45c57a14477ff149cfe31', '李紫云', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪唐山妇女会会长', '1938-1945', '', '组织妇女为日军服务，劝降抗日家属，协助日伪宣传。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8971710d07f853e88929efbf675bcaed', '李纯华', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北、辽宁', '河北、辽宁', '[]', '伪冀东“反共救国军”司令（活动于唐山沿海地区）、伪满鞍山地区“自卫团”总团长', '1934-1945', '', '在唐山海港经开区（今京唐港一带）沿海地区袭扰抗日武装，为日军运输护航。；鞍山郊区地主，投日后组织“自卫团”，配合日军封锁山区，切断抗联补给线，并参与屠杀抗日家属。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
