REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('cae0976306a25ae3b88eccc801122af9', '李老四', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪左权县甲长', '1944-1944', '', '协助日军抓壮丁，强征民夫修炮楼，虐待劳工。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3a42ee50b7225b4cbbd6037e4f9b5daf', '李老恒', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '磁县彭城伪镇长', '1938-1945', '', '在彭城镇（磁县辖）为日军控制陶瓷和煤炭生产，强迫工人为日军做工，克扣工钱，告密抓捕抗日工人。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('97250d2e4dcd5504bc7cc477d65ff0d9', '李老梦（李梦庚）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪隆平县维持会会长', '1937-1939', '', '日军侵占隆平后率先出任维持会长，为日军筹粮派夫，组织“宣抚班”诱降抗日人员，后调任伪县公署顾问。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('20c077ec34715edda1d6baadaca29d16', '李聘三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪大名县知事、伪峰峰矿区维持会会长、伪文安县维持会会长、伪曲周县知事、伪武安县县长、伪武安县知事、伪邢台道尹（管辖临西地区）、伪邯郸县知事、伪邯郸县税务局局长、伪邯郸县维持会会长、伪邯郸县警察局局长、广平县伪县长、成安县伪县长、曲周县伪县长、永年县伪县长、磁县伪县长、肥乡县伪县长、馆陶县伪县长、鸡泽县伪县长', '1937-1945', '', '日军占领文安后率先组织维持会，为日军提供情报，协助建立伪政权，强征民夫修筑据点。；推行保甲制度，强抓壮丁，为日军提供劳力和军粮，镇压抗日活动。；日军侵占邯郸后率先组织维持会，为日军筹粮派款，引导日军搜查抗日物资。；投靠日军，任伪大名县知事，协助日军推行‘治安强化运动’，强征粮税，镇压抗日群众。；日军占领峰峰后，组织维持会，协助日军征粮、拉夫，镇压矿工反抗，出卖抗日人员情报。……（共涉及23个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('35a743f74f555374877586b4f148f9bf', '李聘卿', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪大城县知事、伪安新县维持会会长', '1937-1942', '', '日军占领安新后，率先组织维持会，为日军提供粮草和情报，协助建立伪政权，迫害抗日积极分子。；投日任大城县伪县长，推行保甲制度，强征粮食，配合日军“清乡”，多次率伪警备队袭击抗日游击队。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ea55418bb64358919749be99b10c7957', '李英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀南道保安队大队长、伪冀南道尹公署顾问、伪冀南道尹（管辖邯郸、馆陶等县）、伪察南保安队队长、伪察哈尔省宣化县知事、伪张家口经济统制委员会委员、伪涉县县长、伪邢台县知事', '1937-1945', '', '在宣化（今属张家口）推行日伪统治，强征劳工，搜刮粮食，镇压当地抗日群众。；率伪保安队驻守下花园矿区，镇压矿工反抗，为日军掠夺煤炭资源充当打手。；协助日军实行经济统制，垄断张家口粮食、食盐等物资，导致民众饥荒。；在邢台县推行伪政权，强征民夫修路筑堡，残害抗日家属。；在邯郸、永年、肥乡一带活动，多次袭击抗日县区武装，杀害抗日家属，抢掠牲畜粮食。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0ee6551492325c6698194a09aad3f702', '李茂斋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪盐湖区区长、伪芮城县警察局局长、伪运城维持会会长、绛县伪警察局局长、绛县伪警察所所长', '1938-1945', '', '日军侵占运城后率先投敌，组织维持会，为日军筹措物资，协助建立伪政权，并出卖抗日地下工作者名单。；在日军扶植下担任伪区长，推行保甲制度，强征壮丁，搜刮民财，迫害抗日家属。；效忠日军，负责绛县县城及周边治安，大肆搜捕抗日地下党员和进步人士，严刑逼供后移交日军，导致多名抗日志士牺牲。；效忠日军，建立伪警察体系，搜捕地下党员和抗日积极分子，严刑逼供，破坏抗日地下组织。；效忠日军，负责维持县城治安，搜捕抗日地下人员，迫害爱国群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9a175367a3b559f0a73d283977699a9f', '李茂林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪代县警察局局长、伪偏关县新民会会长、伪小店区维持会长、伪神池县警察所所长、蒲县伪警察所所长、运城伪警察局局长、运城（安邑）伪知事', '1939-1945', '', '在蒲县县城设立伪警察所，搜捕抗日地下人员，严刑拷打抗日志士，为日军提供情报。；组织维持会为日军提供物资，强迫村民修炮楼，协助日军“扫荡”。；效忠日伪政权，负责搜捕抗日地下党员，严刑逼供，破坏抗日组织，协助日军建立情报网。；在偏关推行奴化教育，组织“新民小学”强迫儿童学习日语，并搜集抗日情报提供给日军宪兵队。；效忠日军，负责维持伪政权治安，侦捕抗日地下人员，严刑逼供，破坏抗日组织。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c7d6d28aad9852619a0a2e25052358c7', '李茂荣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪永济县保安队大队长、闻喜县伪保安队队长', '1939-1945', '', '率伪保安队多次配合日军袭击抗日游击队，在永济、虞乡一带抓捕抗日军民，并参与屠杀被俘人员，劫掠村庄物资。；组织伪保安队，配合日军扫荡抗日根据地，多次抓捕、杀害抗日军民，抢劫百姓财物。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a5ec41c2726c5fe9bff656e79b516125', '李范益', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪吉林省间岛省警务厅长', '1934-1945', '', '在延边地区大肆逮捕抗日志士，破坏抗联地下交通线。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4952c9b8362456ca913789f6976c145d', '李荫坡', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪丰润县知事（继任）、伪临榆县保安团长、伪冀东道公署顾问、伪冀东防共自治政府唐山矿区警察署长、伪怀柔县警察局局长、伪玉田县保安团团长、伪秦皇岛警察署署长（管辖昌黎沿海）', '1935-1945', '', '组织伪警察协助日军搜捕地下党员，破坏抗日组织，强征捐税。；在丰润县实施“连坐法”，组织汉奸特务队，破坏中共地下组织，杀害多名抗日干部。；在唐山开滦矿区镇压矿工抗日活动，为日军保护煤炭生产。；率伪保安团在玉田境内多次围剿八路军游击队，杀害抗日干部。；日本顾问的华人帮办，参与策划“治安强化运动”，协助日军在路南地区建立情报网。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('39d432c291145512a4678090a21e497d', '李荫堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪冀东防共自治政府唐山教育局长、伪张家口宣化县知事（兼蔚县督导）、伪承德省兴隆县保安队队长、伪涞水县维持会会长、阳泉伪商会会长', '1935-1945', '', '为日军统制煤炭物资，强迫商户‘献金’，资助伪军，并出卖抗日情报。；日军占领涞水初期，组织维持会，为日军筹粮筹款，强征民夫修路筑堡，协助建立伪政权。；在唐山各学校删除历史课中的爱国内容，灌输奴化思想。；在宣化、蔚县一带督导伪政权，强征粮食，组织“自卫团”，配合日军“治安强化运动”，破坏抗日根据地。；率保安队多次袭击八路军游击队，杀害抗日干部，烧毁村庄，为日军充当鹰犬。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d194d071ceee5e10aa963999c5d5b2d8', '李荫堂（同名）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府唐山学校校长', '1935-1938', '', '在唐山学校开除进步教师，推行奴化课程。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a25f3a2741a35f898c5bd47dbee6501d', '李荫春', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满洲国于洪区警察署署长、伪满洲国康平县警务科长、伪满铁岭县协和会事务长、伪辽阳警务局长', '1931-1945', '', '沈阳于洪地区人，任伪于洪区警察署署长，抓捕抗日分子，为日军提供情报。；辽宁康平人，任伪康平县警务科长，抓捕抗日分子，为日军提供情报，参与制造多起屠杀事件。；任伪辽阳警务局长，协助日军搜捕抗日志士，破坏地下抗日组织，残害百姓。；原铁岭县商人，投日后任协和会事务长，组织“青少年团”，灌输军国主义思想，协助日军征兵。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d656f48cf2d85497b35b891007639db9', '李荫棠', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪卢龙县警务科长、伪固安县维持会会长（初期）、伪晋县（今晋州市）知事、伪正定县保安联队队长、伪秦皇岛区区长、正定县伪保安队队长', '1933-1945', '', '日军占领固安后率先组织维持会，为日军筹粮派夫，协助建立伪政权，镇压抗日活动。；在晋县任伪知事，组织“清乡队”，杀害抗日村长数十人。；率伪保安队配合日军扫荡，抓捕抗日军民，参与制造多起惨案。；率伪军多次配合日军扫荡正定、灵寿一带抗日根据地，抓捕抗日干部和群众，并参与制造多起惨案。；组织伪警察队，多次配合日军“扫荡”卢龙北部山区，抓捕抗日干部和群众，参与制造多起惨案，勒索百姓财物。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fc12731bbe6a5d148de0b75c1c114683', '李逢春', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪荣河县警备队队长、伪高平警备队中队长、荣河县伪县长', '1938-1945', '', '率警备队驻守高平各据点，参与“三光”扫荡，亲手杀害抗日村长数人。；任荣河县伪县长，为日军征收粮款，强抓壮丁，破坏地下抗日组织，曾指使汉奸告密导致多名抗日人员被捕牺牲。；率伪军多次参与对抗日游击队的围剿，杀害多名抗日干部，并强征百姓粮食供应日军。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
