REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('1b2a74c9131c529189abbe38ef160927', '李郁文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪大同县维持会会长、伪浑源县教育科长', '1937-1945', '', '日军初占大同后组织维持会，为日军征夫派款，提供慰安妇，协助建立伪政权。；推行奴化教育，强迫学校使用日伪教材，宣扬‘中日亲善’，破坏抗日宣传。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fe417281717f53fcb1eebd0f820af04b', '李铁生', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪唐山警察局局长', '1938-1943', '', '在唐山市区任伪警察局长，残酷镇压工人罢工和学生运动，逮捕并刑讯抗日地下工作者。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b8852f66fd825aae828fc4475d35392f', '李铭书', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪农安县警务科长、伪吉林市商会会长、伪吉林省协和会本部副本部长、伪吉林省教育厅厅长、伪吉林省高等法院院长、伪永吉县协和会副会长、伪满伊通县县长、伪满吉林市丰满区协和会会长、伪满吉林省警务厅长、伪满四平市市长、伪满洲国吉林省伪民政厅长、伪满洲国吉林省高等法院院长、伪满洲国吉林高等法院院长、伪满洲国长春地区伪警察总监、伪满洲国长春市长（伪新京特别市市长）、伪满洲国长春特别市市长、伪满辽源地区警备司令、伪满长春市市长（新京特别市市长）、伪满长春市长、伪长春县县长、伪长春县警务局长、伪长春市市长（新京特别市市长）、伪长春市市长（新京特别市长）、伪长春特别市市长', '1931-1945', '', '在吉林地区组织协和会，进行反动宣传，搜集抗日情报。；组织协和会分会，为日军募集物资，监视居民言行，举报抗日嫌疑人员，协助日军强征丰满水电站劳工。；伪满四平市（今四平市）市长，配合日军建立“集团部落”，制造无人区，迫害抗日群众。；原伊通地方士绅，投日后任伪满伊通县县长，推行保甲制度，组织汉奸武装，协助日军在伊通地区“清乡”，迫害抗日群众。；协助日军进行思想控制，举报抗日群众，参与“治安肃正”行动。……（共涉及25个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
