REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5b560385786f5ebc9f8f38276f67ad6f', '杜锡钧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、山西、河北', '北京、山西、河北', '[]', '伪保定绥靖公署主任、伪河北省保安司令、伪保定道尹（道公署驻清苑，辖莲池周边）、伪冀东保安司令、伪冀东保安司令部副司令、伪冀东保安队指挥官、伪冀东保安队指挥官（驻唐山）、伪冀东道尹、伪冀东道尹（后改称冀东特别区行政长官）、伪冀东道尹（管辖昌黎县）、伪冀东道尹（管辖秦皇岛一带）、伪冀东道尹（驻唐山）、伪冀南道保安司令（驻邢台）、伪冀南道尹（辖邯郸、磁县）、伪华北政务委员会石家庄办事处主任、伪华北治安军副总司令、伪华北治安军副总司令兼第一集团军司令、伪华北治安军第1集团军司令（活动涉及晋北）、伪华北治安军第一集团军司令、伪华北治安军第二集团军司令（驻防唐山）、伪河北省保安司令、伪河北省保安司令、伪冀东保安队头目、伪河北省保安司令、伪华北治安军第一集团军司令、伪河北省保安司令（驻石家庄）、伪河北省公署警务厅厅长、伪顺义县知事（曾任）、伪河北省省长、伪河北省省长、伪冀东防共自治政府委员、伪河北省省长、伪华北政务委员会常委、伪河北省省长（省会保定，但管辖石家庄地区）、伪河北省长（1940-1943）、伪河北省长（省会曾驻石家庄）、伪河北省长（管辖河间地区）、河北省伪保安司令（驻保定，指挥石家庄伪军）', '1933-1945', '', '驻通州指挥伪军，配合日军“铁壁合围”，破坏抗日根据地，犯下累累罪行。；在顺义任职期间，强征民夫修筑炮楼公路，搜刮民财，逮捕抗日家属。；派部队配合日军进攻晋中根据地，在寿阳、盂县一带制造惨案。；在保定一带组织伪保安队，协助日军抓捕抗日志士，破坏地下组织。；原北洋军官，投日后在保定组织伪军，参与围剿八路军冀中根据地，残害抗日军民。……（共涉及41个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
