REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('da4bf1ddb0f352dbb8cba684b927ab9a', '杨茂斋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '万泉县伪维持会副会长、伪河津县警察所所长、日伪河津县维持会会长', '1938-1943', '', '协助日军建立伪政权，为日军提供情报，强迫村民领取“良民证”，并克扣赈济物资中饱私囊。；带领伪警察抓捕抗日群众，严刑逼供，协助日军屠杀无辜百姓。；日军侵占初期出任维持会长，为日军筹措粮款，强征民夫，并组织汉奸团体“新民会”宣传奴化思想，破坏抗日组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6be2c737b9c856c88bdfbbf92df75721', '杨茂林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、山西', '内蒙古、山西', '[]', '伪伊克昭盟保安司令部参谋长、伪太原县合作社主任（古交分社）、伪安泽县警备队中队长、伪忻县税务局局长、伪盂县保安团团长、伪运城剿共自卫团团长、保德县伪保安队队长、原平伪商会会长、岚县伪新民会会长、繁峙县伪警察所所长', '1938-1945', '', '参与策划对东胜地区抗日游击队的围剿，协助日军建立情报网，破坏抗日组织。；率警备队驻守安泽县城，多次参与“清乡”行动，杀害抗日军属，并抢劫民间财物。；宣传奴化思想，组织“新民会”胁迫群众参加日军庆典，破坏抗日宣传，提供情报给日军。；垄断古交粮食和食盐配给，克扣民食，逼使百姓饿死。；组织伪保安队，配合日军扫荡抗日根据地，抓捕抗日干部，杀害无辜百姓，抢劫财物。……（共涉及10个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('995d97d5ab36539093351888246ac8fe', '杨藩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京', '北京', '[]', '伪延庆县知事（县长）', '1939-1943', '', '任伪延庆县知事期间，推行日伪保甲制度，强征民夫修筑据点，配合日军“治安强化运动”，抓捕抗日干部和群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('04ee0b0ea19655c4985894a5e3f3dd4a', '杨诚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪五台县保安队大队长、伪山西保安队副司令、伪山西剿共军第1师师长、伪山西省政府警务厅厅长（管辖长治、长子）、伪怀仁县知事', '1939-1945', '', '率伪军师在太原周边及晋中地区袭击抗日武装，抢夺物资。；率伪保安队多次配合日军袭击八路军游击队，杀害抗日干部，烧毁村庄，抢劫民财，民愤极大。；组织伪保安队协助日军“清乡”，在晋中、左权一带搜捕抗日分子，烧毁村庄。；任伪怀仁县知事期间，为日军征粮派款，组织伪警察抓捕抗日分子，破坏地下党组织，协助日军修建碉堡和封锁沟。；负责晋东南伪警体系，在长子县设立多个伪警察所，协助日军搜捕地下党员，破坏抗日组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
