REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f0a05b45394f5fcf9e2d9b7b4cbf4e5d', '梁上椿', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪太原市市长、伪山西公署顾问/汉奸、伪山西省公署财政厅厅长、伪山西省公署财政厅厅长（涉及晋城）、伪山西省公署财政厅长、伪山西省公署顾问、伪太原市长、伪山西省公署顾问（兼管晋东南）、伪山西省公署顾问（太原及娄烦活动）、伪山西省公署顾问（晋城籍）、伪山西省建设厅厅长、伪山西省财政厅厅长、伪山西省财政厅长、伪晋北自治政府主席、伪晋北自治政府最高委员、伪晋源县知事（晋源地区）、伪榆次县知事（县长）、伪长治地区警备队长', '1937-1945', '', '为日军搜刮山西财政资源，征收苛捐杂税，支持侵华战争。；日军占领太原后出任伪太原市市长，协助日军维持治安，推行保甲制度，镇压抗日活动。；为日军搜刮民财，发行伪币，控制山西经济命脉。；为日军出谋划策，参与制定对娄烦山区的“三光”政策，迫害抗日家属。；在伪山西省公署任职期间，负责为日军筹措军费，强征捐税，搜刮民财。……（共涉及23个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7d1cf2dd80e35b6688633dfcb3f7f3d8', '梁化之', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪山西省公署顾问（晋中地区活动）、伪山西省政府顾问（晋城籍）、伪山西省警务厅厅长（兼管晋中）', '1938-1945', '', '原阎锡山部属，投日后主管伪警务，在晋中平遥设立多个特务据点，指挥伪警宪特搜捕抗日分子，制造多起惨案。；作为阎锡山旧部投靠日军，在晋中一带参与清乡扫荡，提供抗日组织情报，导致多名地下党员被捕。；晋城籍汉奸文人，在太原伪政府任职，撰写反共文章，为日军侵略辩护。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2533453a1931526b9326f076cbf651f5', '梁培璜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪临汾警备司令、伪汾城县保安团副团长、伪阳曲县维持会会长、伪霍县保安大队长', '1938-1943', '', '在临汾城内设立特务机构，抓捕抗日志士，并配合日军实施经济封锁。；协助日军在汾城（今襄汾）实施“三光政策”，率部袭击抗日村庄，掠夺牲畜粮食，杀害抗日家属。；在霍州组织伪保安队，抓捕抗日群众，为日军提供情报。；组织维持会为日军征粮派款，提供妇女充当“慰安妇”，民愤极大。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d585c19d0961592c853d07c9287ae299', '梁子明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '平定县伪教育科长', '1940-1945', '', '推行奴化教育，强迫学校使用日伪教材，告发进步教师，破坏抗日宣传。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8ceacb22421e51f7a823bced3b9efe98', '梁永福', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪阳泉矿区保安队队长', '1938-1945', '', '率伪军多次配合日军扫荡矿区周边村庄，抓捕抗日军民，烧毁民房，抢夺物资，并参与杀害八路军侦察员3名。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3f78c06af8dc5b588e032beca890c683', '森盖林沁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪伊克昭盟副盟长、伪蒙古军第3师师长、伪杭锦旗协理、伪蒙古军第9师军官、伪达拉特旗保安司令', '1937-1945', '', '在杭锦旗为日军征收牲畜和皮毛，参与围剿中共领导的桃力民抗日游击队。；在鄂尔多斯地区组织伪蒙古军，配合日军扫荡东胜周边，残害抗日军民，强征民夫修筑工事。；投靠日军，任伪伊克昭盟达拉特旗保安司令，协助日军镇压抗日力量，强征民夫修建军事设施。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b62352fbc8f85eb6b40ef0dc25685166', '正珠尔扎布', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪兴安军军官、伪兴安军军官、伪满第十军管区参谋长、伪兴安军总参谋长、伪满洲国陆军少将、伪兴安军第2师师长、伪兴安军高级军官、伪兴安南省民政厅长', '1931-1945', '', '在乌兰浩特地区协助日军进行“特别治安”行动，逮捕并杀害抗联地下工作者。；甘珠尔扎布之弟，任伪兴安军要职，在兴安盟地区协助日军进行军事行动，镇压当地抗日活动。；蒙古族贵族出身，投靠日本后任伪兴安军军官，参与围剿东北抗日联军在呼伦贝尔的游击活动。；在呼伦贝尔地区统领伪兴安军，配合日军进攻苏联边境及抗日武装；甘珠尔扎布之弟，积极推行日满蒙一体化政策，协助日军在通辽地区实施殖民统治。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ca7f471910f55c55834ebaba352b1333', '武耀星', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '文水县伪区公所区长（三区）', '1943-1945', '', '勾结日军，在文水三区抢掠民财，抓捕抗日家属，逼供抗日组织名单。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ac23691e1eff574daa6c8b6dd43285c7', '段子荣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '静乐县伪维持会副会长', '1938-1940', '', '日军初占静乐时率先投敌，协助日军建立维持会，为日军带路寻找抗日武装藏身点，致使多处秘密粮仓被毁。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('59d91b8ba10d579195d981a5f7f48475', '段树华', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪临汾县知事、伪临汾商会会长、伪山西保安队副司令', '1938-1945', '', '为日军筹措物资，控制临汾商业，协助日伪经济掠夺。；在临汾县推行日伪“治安强化运动”，建立伪乡村政权，强迫民众领取“良民证”，多次向日军报告抗日活动，导致多名地下党员被捕。；率伪保安队驻防长治地区，多次配合日军对武乡砖壁、王家峪等八路军总部驻地周边进行“铁壁合围”，屠杀抗日军民。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('062751f88bf45488abeca9b133d926b3', '段炳昌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪临汾保安队副队长、伪山西剿共军第2师师长、伪山西剿共军第3师师长、伪襄陵县新民会会长、忻县伪保安团副团长、浮山县伪维持会会长', '1938-1945', '', '率伪保安队多次配合日军突袭抗日根据地，杀害抗日干部，抢劫民财。；日军占领浮山后率先投敌，组织维持会，为日军筹粮派款，提供抗日武装活动情报，导致多处抗日据点被破坏。；推行奴化教育，强迫民众参加“新民会”活动，搜集抗日言论，向日军告密，导致多名群众被杀害。；率部驻防太原以南，配合日军封锁抗日根据地，参与“三光”政策。；率伪军参与“铁滚扫荡”，在忻口、奇村一带烧杀抢掠，杀害抗日干部家属。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a27c665493d5572aad2a29c6686e1611', '殷体新', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪冀东防共自治政府警务厅长、伪冀东防共自治政府警务处长', '1935-1938', '', '负责伪政权警察系统，抓捕抗日志士，破坏地下组织，为日军特务机关服务。；组建伪警察系统，在唐山、滦州大肆搜捕抗日分子，实施白色恐怖。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d88feff2fed55e8c90f24442be17d7e4', '殷汝耕', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、河北', '北京、天津、河北', '[]', '伪冀东防共自治政府主席、伪冀东防共自治政府主席（影响石家庄东部）、伪冀东防共自治政府主席（影响石家庄地区）、伪冀东防共自治政府主席（影响静海）、伪冀东防共自治政府主席（活动涉及武清）、伪冀东防共自治政府委员长、伪冀东防共自治政府委员长（后任伪华北政务委员会顾问）、伪冀东防共自治政府委员长（后并入伪华北政权）、伪冀东防共自治政府委员长（后并入北平伪政权）、伪冀东防共自治政府委员长（后并入华北伪政权）、伪冀东防共自治政府委员长（曾辖丰台地区）、伪冀东防共自治政府委员长（活动范围含唐山）、伪冀东防共自治政府委员长（管辖唐山、玉田等地）、伪冀东防共自治政府委员长（管辖昌黎、秦皇岛）、伪冀东防共自治政府委员长（辖区含卢龙）、伪冀东防共自治政府委员长（辖区含秦皇岛）、伪冀东防共自治政府政务长官、伪冀东防共自治政府政务长官（后并入伪华北政权）、伪冀东防共自治政府政务长官（后并入北平伪政权）、伪冀东防共自治政府政务长官（管辖密云）、伪冀东防共自治政府政务长官（辖宁河、塘沽等地）、伪冀东防共自治政府政务长官（首脑）、伪冀东防共自治政府顾问（活动于天津）、伪冀东防共自治政府首脑（影响天津）、冀东防共自治政府主席、冀东防共自治政府政务长官', '1935-1945', '', '1935年成立伪冀东防共自治政府，管辖包括北平东部地区，后并入伪中华民国临时政府，长期为日本侵略服务。；早年在冀东成立伪政权，其势力范围曾涉及北平近郊及丰台一带，为日军提供情报和后勤支持。；在冀东（含丰台周边）成立伪政权，脱离国民政府，为日军提供后勤与情报支持。；早年在冀东成立伪政权，后活动于北平，协助日军控制平津地区，参与对大兴等县的伪化统治，推行保甲制度。；在冀东及北平周边地区建立伪政权，为日军提供情报和后勤支持，协助日军控制平津地区。……（共涉及83个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9f1a0f52633b5fc6bc86e97ffb54129a', '毕泽宇', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪“冀南剿共军”司令', '1941-1945', '', '率伪军驻邢台，参与多次大扫荡，制造“无人区”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('21cc4aaf640b5ed887e72b8e95768412', '江朝宗', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪北平维持会会长、伪北平维持会会长、伪北平市市长、伪北平维持会会长（1937年短暂）、伪北平维持会会长（曾涉廊坊）、伪北平维持会副会长、伪北平维持会副会长（1937）', '1937-1938', '', '1937年北平沦陷后率先组织伪北平维持会，迎接日军进城，后任伪临时政府顾问，是东城地区早期汉奸头目。；原北洋将领，北平沦陷后任伪维持会副会长，协助日军接管昌平。；北洋遗老，北平沦陷初期出任伪维持会会长，为日军在朝阳地区建立秩序提供协助。；七七事变后出任伪北平维持会会长，后任伪北平市长，协助日军维持北平（含海淀）秩序，镇压抗日民众；七七事变后率先投敌，组织北平维持会，为日军提供后勤支持，协助建立伪政权。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9c03f1876af755259e718cf4dd6cc344', '江朝宗（重复？不，另列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪北平维持会会长（曾涉廊坊）', '1937-1938', '', '初期在北平及周边（含廊坊北）组织维持会，为日军建立秩序。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
