REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('aa7913ec446c597faf6a8833076cf708', '王佐才', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北、辽宁', '山西、河北、辽宁', '[]', '临县伪自卫团团长、临汾伪道尹公署顾问、临汾县伪知事（后任伪县长）、伪临汾县保安队副队长、伪云州宣抚班班长、伪唐山电报局局长、伪沁水县维持会会长、伪满盘山县教育长、伪芮城县税务局局长、伪运城县政府知事、元氏县伪警察所所长、浮山县伪区公所区长（二区）、运城伪商会会长、运城伪警备队副队长', '1936-1945', '', '原阎锡山部军官，投日后任临汾伪道尹公署顾问，参与策划对临汾、乡宁地区的“清剿”行动，诱降抗日干部。；在浮山二区推行保甲制度，清查抗日家属，向日军报告八路军活动情报，导致多次袭击事件。；在临汾县城任伪职期间，为日军提供情报，组织伪警察所，抓捕抗日分子，强征粮税，破坏地下抗日组织。；原为地方民团头目，投日后任伪保安队副队长，在临汾、蒲县交界地带多次袭击八路军游击队，杀害抗日家属，抢劫物资。；组织伪自卫团，配合日军巡逻和清乡，杀害抗日军属，抢劫民财。……（共涉及17个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('32534af42c045828a42001b5e5dc7cc0', '王俊杰', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '定襄县伪县长', '1938-1945', '', '投靠日军，出任定襄县伪县长，协助日军推行‘治安强化运动’，强征民夫，搜刮粮食，镇压抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4d2d3d155bb454339a738c1c49764a53', '王克敏', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、河北', '北京、天津、河北', '[]', '伪中华民国临时政府行政委员会委员长、伪中华民国临时政府行政委员会委员长、伪华北政务委员会委员长、伪中华民国临时政府行政委员会委员长（北平）、伪中华民国临时政府行政委员会委员长（在天津设立分支机构）、伪中华民国临时政府行政委员会委员长（在津活动）、伪中华民国临时政府行政委员会委员长（影响河北及秦皇岛地区）、伪中华民国临时政府行政委员会委员长（影响秦皇岛地区）、伪中华民国临时政府行政委员会委员长（管辖河北含昌黎）、伪中华民国临时政府行政委员会委员长（辖河北）、伪中华民国临时政府（北平）委员兼唐山办事处主任、伪华北政务委员会委员长、伪华北政务委员会委员长（1937-1940年）、伪华北政务委员会委员长（1937-1940）、伪华北政务委员会委员长（原籍浙江，但活动范围含河北）、伪华北政务委员会委员长（影响河北地区）、伪华北政务委员会委员长（管辖河北含秦皇岛）、伪华北政务委员会委员长（管辖热河西部）、伪华北政务委员会委员长（管辖石家庄地区）、伪华北政务委员会委员长（首任）', '1937-1945', '', '1937年北平沦陷后出任伪中华民国临时政府行政委员会委员长，后任伪华北政务委员会委员长，积极推行日本殖民统治，镇压抗日活动。；原北洋政客，投日后主持伪华北政权，管辖北平及丰台，组织伪军和警察协助日军。；在北平建立伪政权，推行奴化政策，为日军搜刮物资，配合“治安强化运动”。；伪华北最高傀儡头目，在北平设立伪政权，统辖大兴等县，推行“新民会”奴化宣传，配合日军“三光”政策。；原北洋财政官僚，投日后任伪华北政务委员会委员长，在北平及延庆地区全面推行日伪统治，组织“新民会”进行奴化宣传。……（共涉及32个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3ddd8e868ff95d568ccc3afab761746f', '王克敏（重复？不，另列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪中华民国临时政府行政委员会委员长', '1937-1940', '', '华北伪政权首脑，其统治覆盖廊坊全境，推动“新民会”在基层建立汉奸组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
