REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e6b8425fe2a75f1390d3cc8927ce0ae7', '王兹栋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪吉林市市长、伪吉林省警务厅厅长、伪大连地区特务机关情报员、伪奉天市警察局局长、伪抚顺县县长、伪永吉县县长、伪满奉天省教育厅长、伪满奉天省警务厅厅长、伪满洲国公主岭地区维持会会长、伪满洲国吉林省实业厅长、伪满洲国大连市长、伪满洲国大连警察署署长、伪满洲国奉天市市长、伪满洲国奉天市警察局局长、伪满洲国奉天省实业厅厅长、伪满洲国奉天省警务厅厅长、伪满洲国康平县县长、伪满洲国长春市市长、伪满苏家屯地区维持会会长、伪满辽源县县长（今辽源市）、伪满辽阳协和会会长、伪满铁岭县警察署署长、伪满铁西区区长', '1931-1945', '', '任伪吉林市长期间，推行日伪市政管理，镇压反满抗日活动。；任伪永吉县长期间，强征劳工，为日军修建军事设施，镇压当地抗日活动。；原辽源县地方士绅，日军占领后出任伪县长，为日军征粮派款，组织伪自卫团，镇压辽源地区抗日民众运动。；九一八后组织地方维持会，迎接日军进驻公主岭，协助建立伪政权，强征民夫修建军事设施。；指挥伪警察协助日军搜捕抗日分子，破坏地下组织，参与“讨伐”抗联部队。……（共涉及25个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('68fe8880cf4f51d3a12dd678eeba1d64', '王冠英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀南道尹公署参议（南宫籍）、伪邯郸县保安联队队长、伪邯郸县维持会会长、伪县知事', '1937-1945', '', '为日军充当顾问，参与策划对南宫、巨鹿等地的‘铁壁合围’，提供抗日武装情报。；组织伪保安队，配合日军扫荡丛台周边村庄，杀害抗日干部和群众，抢劫物资。；日军占领邯郸后率先组织维持会，为日军筹粮派款，提供情报，并参与建立伪县政权，迫害抗日家属，破坏地下抗日组织。；率伪军多次扫荡邯山周边村庄，制造多起惨案，抢劫物资并配合日军清剿游击队。；率伪军多次袭击冀南抗日游击队，杀害抗日军民，抢劫物资，破坏地下交通线。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
