REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b7e4f249f0ca50b586b5b18536b362ef', '王凤岗（重复？不，另列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪大厂县保安大队长（大厂当时属三河）', '1941-1945', '', '在大厂地区组织“反共自卫团”，袭击回民支队，破坏民族团结抗日。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
