REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9d2ac1a897675bf4a8846dc992d4d0f2', '王庆林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '临城县伪警察所所长、邢台县伪警备队大队长', '1938-1945', '', '效忠日军，负责临城伪警察系统，抓捕抗日地下工作者，破坏中共地下组织，参与“清乡”行动。；在邢台地区为日军效力，率伪警备队多次进攻抗日游击队，残害抗日家属。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('68aa595e7cd45c77aa868eb61d84a100', '王庆璋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪吉林省公署参事官（负责净月地区事务）、伪满大连警察署署长、伪满奉天市市长、伪满奉天市市长（沈阳）、伪满奉天市警察局局长、伪满奉天省保安局局长、伪满奉天省警务厅厅长、伪满安东省经济警察、伪满洲国大连市市长、伪满洲国奉天市警察局局长、伪满洲国奉天省教育厅厅长、伪满洲国奉天省警务厅厅长、伪长春市警察局长', '1931-1945', '', '在长春市区残酷镇压抗日活动，逮捕爱国人士。；参与净月地区“归屯并户”，制造无人区，切断抗日联军与群众联系。；原安东商人，投日后任伪满安东省经济警察，在丹东、凤城地区协助日军统制粮食、棉花等物资，欺压百姓。；曾任大连商会会长，投日后任伪大连市市长，协助日本控制大连港及殖民经济。；辽宁大连人，投靠日本殖民当局，任伪大连市长，管理港口及殖民事务。……（共涉及14个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
