REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('71f249296df65e7d8a9b6fbff4d7d7c3', '王振声', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪冀东盐务局局长、伪冀东防共自治政府滦州银行经理、伪屯留县保安队队长、伪新华镇维持会会长、伪晋城县合作社联合社理事长、伪晋城县知事、伪晋城维持会会长、伪沁水县保安队副队长、伪沁水县知事（县长）、伪沧县维持会会长、伪沧州维持会会长、伪渤海区宣抚班长、伪盐山县保安联队队长、伪襄垣县保安队队长、伪阳城县维持会会长、晋城县伪维持会会长', '1935-1945', '', '控制全县粮食及食盐配给，强制低价收购农民粮食供应日军，从中贪污牟利，导致民众饥荒。；日军占领晋城初期出任维持会长，为日军筹粮派款、拉夫修路，强迫商户“欢迎皇军”，并告密导致多名抗日积极分子被捕牺牲。；推行日伪政权法令，强征民夫修筑碉堡公路，搜刮民财。；充当日军爪牙，率伪保安队多次袭击抗日游击队，抓捕并刑讯抗日人员，参与制造多起惨案。；日军占领晋城后组织维持会，为日军提供情报，强征粮款，迫害抗日家属。……（共涉及17个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('1f8caffeabd45507b3fe74b6e4691732', '王振声（同名）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府滦州钱庄老板', '1935-1938', '', '在滦州为伪政权兑换军票，剥削百姓。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ddb23c0430b05c31ba42342c0fe96e71', '王振山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪兴隆县协和会会长、伪曲阳县警备大队长、伪沧州保安队中队长、伪沧州保安队队长、伪泊头保安队队长、伪海兴县保安队队长、景县伪保安联队队长', '1938-1945', '', '率伪警备队多次参与对抗日村庄的围剿，抓捕并杀害抗日军民，抢劫财物，烧毁房屋，民愤极大。；宣传“中日亲善”，组织奴化教育，搜集抗日情报，协助日军推行“集家并村”政策，制造无人区。；率伪保安队多次袭击抗日武装，抓捕抗日群众，烧毁村庄。；率伪军驻防沧县、孟村一带，多次配合日军“清乡”，杀害抗日干部和群众，抢劫财物，并强迫青壮年加入伪军。；率伪军驻守泊头，多次参与日军对交河、献县等地的扫荡，抓捕抗日干部，抢劫民财。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7fc406b6c9185213a6a635dbf6786d6a', '王振恩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '代县伪县长、定襄县伪县长', '1937-1945', '', '日军侵占代县后出任伪县长，协助日军推行“治安强化运动”，强征粮税，镇压抗日群众。；投靠日军，任定襄县伪县长，协助日军推行“治安强化运动”，强征民夫、粮食，镇压抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('93d0d38c28935b629f284680f115a6c9', '王振武', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪沧县（今沧州）保安联队副队长（活动涉及盐山）、伪海兴县保安队队长', '1939-1945', '', '率伪保安队配合日军“清乡”，在苏基、辛集等地多次袭击八路军游击队，抓捕并杀害抗日军民，烧毁村庄。；在沧州、盐山交界地带协助日军‘清乡’，强征民夫，破坏抗日组织，参与屠杀抗日军民。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5c862efb2ab252778f412feaa14c9357', '王振海', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪曲周县警察所所长、伪石家庄道公署顾问、伪邢台县保安联队副队长（活动于任泽边界）、伪隆平县保安联队副、内丘县伪警察所所长、平乡县伪警察所所长、新河县伪自卫团团长、灵寿县伪自卫团团长、肥乡县伪警察所长、衡水县伪警察局长、赵县伪警察所所长、鸡泽县伪警察所所长', '1939-1945', '', '组织伪自卫团协助日军封锁抗日根据地，参与“清乡”行动，烧毁村庄，抢掠财物。；效忠日军，负责伪警察事务，搜捕抗日分子，破坏地下组织，参与“清乡”行动。；为日军提供石家庄及周边地区情报，参与策划“治安强化运动”。；在衡水县城内为日军效力，负责伪警察特务工作，搜捕抗日分子，破坏地下党组织。；在任泽与邢台交界地带活动，率伪军配合日军“清剿”八路军游击队，杀害多名抗日群众。……（共涉及12个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
