REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0c6268d47d1656aeaa4e03096f2d60ea', '王振纲', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、山西、河北', '北京、山西、河北', '[]', '五寨县伪县长、伪丰润县知事（县长）、伪临汾县新民会会长、伪五台县保安队队长、伪冀南道保安队司令、伪唐山地区“剿共”司令、伪密云县保安团团长、伪开滦煤矿矿警队队长（唐山）、伪正定县知事、伪沧县保安队队长、伪津海道（沧州属）保安队司令、伪玉田县特务队队长、伪玉田县知事、伪赤城县保安队队长、伪运河区维持会会长、伪长子县保安队大队长、伪顺德道尹（邢台地区）、伪顺德道警察局局长、隆平县伪保安联队队长', '1937-1945', '', '率保安团配合日军扫荡密云山区，围捕八路军游击队，杀害抗日干部及群众。；在临汾推行奴化教育，组织“新民会”宣传“中日亲善”，诱骗青年参加伪军。；率领伪军多次袭击八路军游击队，抓捕并杀害抗日干部和群众，参与日军“三光”政策行动，烧毁村庄，掠夺粮食。；投靠日军，任五寨县伪县长，协助日军推行‘治安强化运动’，强征粮税，镇压抗日群众。；率伪保安队配合日军在长子县丹朱镇、色头镇等地扫荡，杀害抗日民兵，烧毁民房，民愤极大。……（共涉及19个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8edba735e5835b9ca5a0ac5b125e9326', '王振邦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '交城县伪保安队队长、伪唐山特别市公署市长、伪唐山特别市公署市长（后期）', '1938-1945', '', '率伪保安队多次配合日军扫荡交城山区抗日根据地，杀害抗日干部和群众，烧毁村庄。；在日占唐山期间任伪市长，推行奴化教育，组织劳工输出，为日军提供物资。；1938年伪冀东政府改为伪河北省后，任伪唐山市长，推行日伪经济统制，强征粮食煤炭，为日军提供战争物资。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('87d82ea6479f552ba7c9f02475db9108', '王振铎', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '景县伪保安联队队长', '1940-1945', '', '率伪军多次扫荡景县抗日根据地，杀害抗日干部和群众，烧毁村庄，罪行累累。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f507817e989158b6a3fd828c617b43cd', '王揖唐', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、吉林、天津、河北', '北京、吉林、天津、河北', '[]', '伪中华民国临时政府议政委员会委员长、伪华北政务委员会内政总署督办、伪华北政务委员会内务总署督办、伪华北政务委员会委员长、伪华北政务委员会内务总署督办、伪华北治安军总司令、伪华北政务委员会内务总署督办（天津活动）、伪华北政务委员会内政总署督办、伪中华民国临时政府议政委员会常务委员、伪华北政务委员会内政总署督办、伪华北政务委员会委员长、伪华北政务委员会内政总署督办、伪华北防共委员会会长、伪华北政务委员会内政总署督办、伪国民政府考试院院长、伪华北政务委员会内政总署督办、伪河北省长、伪华北政务委员会内政总署督办（在天津设办公处）、伪华北政务委员会内政总署督办（曾管辖冀东地区）、伪华北政务委员会内政总署督办（曾驻保定活动）、伪华北政务委员会内政总署督办（曾驻保定）、伪华北政务委员会内政总署督办（曾驻北平）、伪华北政务委员会内政部长（曾管辖唐山地区）、伪华北政务委员会委员长、伪华北政务委员会委员长（1940-1943）、伪华北政务委员会委员长（原籍安徽，但活动范围含冀东）、伪华北政务委员会委员长（常驻天津）、伪华北政务委员会委员长（影响天津）、伪华北政务委员会委员长（影响秦皇岛）、伪华北政务委员会委员长（曾兼保定地区事务）、伪华北政务委员会委员长（曾活动于长春）、伪华北政务委员会委员长（曾管辖通州）、伪华北政务委员会委员长（曾驻保定活动）、伪华北政务委员会委员长（曾驻石家庄活动）、伪华北政务委员会委员长（活动涉及天津）、伪华北政务委员会委员长（涉及唐山地区）、伪华北政务委员会委员长（涉及沧县）、伪华北政务委员会委员长（涉及河北）、伪华北政务委员会委员长（管辖冀东）、伪华北政务委员会委员长（管辖天津）、伪华北政务委员会委员长（管辖密云）、伪华北政务委员会委员长（管辖石家庄）、华北政务委员会内政总署督办、伪河北省省长、华北政务委员会委员长（管辖河北含石家庄）', '1937-1945', '', '曾任伪中华民国临时政府议政委员会常务委员，后任伪华北政务委员会内政总署督办，协助日军在北平及华北地区推行治安强化运动。；原北洋政客，投日后任伪华北政务委员会要职，在北平（今北京）及丰台地区推行日伪统治，协助日军征粮、镇压抗日活动。；原北洋政客，七七事变后投敌，在北平组织伪政权，任伪华北政务委员会要职，推行奴化教育，协助日军经济掠夺，镇压抗日力量。；在北平（今北京）积极投靠日本，主持伪华北政权，推行奴化教育，镇压抗日活动，协助日军经济掠夺。；在密云地区推行保甲制度，组织伪军配合日军扫荡八路军根据地。……（共涉及53个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
