REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d4e3306af4f458f794f2ae592a42473d', '王永恩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪吉林省保安队队长、伪满吉林宪兵队队长', '1932-1945', '', '率伪保安队多次进攻抗联根据地，烧毁村庄，屠杀百姓。；在昌邑一带残害抗日军民，参与制造多起屠杀事件，协助日军“讨伐”抗联。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
