REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('1c5a7c0239a3585ba753fb5dd8066643', '王永江', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、山西、河北、辽宁', '吉林、山西、河北、辽宁', '[]', '伪兴隆县警务科长、伪冀东防共自治政府顾问、伪北镇县县长、伪复县警察局局长、伪太原警察局局长、伪奉天市市长（注：非历史人物，此处为虚构，实际无此人）、伪岫岩县财务局长、伪承德县县长、伪清徐县知事、伪满东边道保安司令、伪满吉林协和会会长、伪满吉林省警务厅长、伪满四平省省长（伪满后期设四平省）、伪满四平街市市长、伪满大连民政署署长、伪满奉天省警务厅厅长、汉奸、伪满奉天省警务厅长（原籍铁岭）、伪满奉天省财政厅厅长、伪满奉天省财政厅长（早期）、伪满安东省实业厅长、伪满安东省（今丹东地区）省长、伪满朝阳县县长、伪满洲国交通部大臣、伪满洲国交通部大臣（注：其早逝，但曾为奉系要员，需核实）、伪满洲国奉天省实业厅厅长、伪满洲国奉天省省长（曾管辖大连周边）、伪满洲国奉天省省长（未就任）、伪满洲国奉天省警务厅长、伪满洲国奉天省财政厅长、伪满洲国奉天省财政厅长（后投敌）、伪满洲国奉天省财政厅长（注：实际为早期投日者）、伪满洲国热河省朝阳县伪县长、伪满洲国绥中县协和会分会长、伪满洲国财政部总长（未就任，但曾为奉系要员）、伪满洲国锦州省省长、伪满洲国锦州省省长（后改任）、伪满洲国阜新矿务局总办（海州矿区实际管理者）、伪满盘山县县长（首任）、伪满辽阳地区维持会会长、伪满铁岭县县长、伪满锦州省民生厅长、伪满锦州省省长、伪满锦州省警务厅厅长、伪满阜新县县长、伪满阜新县县长（1933-1937）、伪满鞍山地方维持会会长、伪热河省协和会会长、伪辽阳县县长（后任伪奉天省民政厅长）、伪辽阳县维持会会长、伪辽阳县维持会会长（注：其活动主要在辽阳地区）、伪锦州省警务厅厅长、伪隆化县县长', '1931-1945', '', '伪满四平省（辖今四平、梨树、双辽等地）首任省长，推行粮食“出荷”政策，强征劳工，协助日军“讨伐”抗联。；原地方官僚，投日后任伪满四平街市（今四平市）市长，推行日伪奴化教育，协助日军征粮征税，镇压当地反抗。；在吉林地区宣传“日满亲善”，组织汉奸团体，破坏抗日统一战线。；原土匪武装头目，投日后被委任为东边道（含今辽源、东辽一带）保安司令，多次率伪军袭击抗日游击队，残害百姓。；在吉林、辽源地区组织伪警察，协助日军搜捕抗日志士，镇压民众反抗。……（共涉及58个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
