REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bd9f9f87c6ae5466b0b61cbd65e84d14', '王永泉', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、山西、河北', '北京、山西、河北', '[]', '伪冀东保安队第二总队队长、伪冀东道尹（驻通州）、伪冀东防共自治政府保安处长（后调任石家庄）、伪冀东防共自治政府保安队指挥官（后调任石家庄）、伪冀南道尹兼保安司令、伪华北治安军第1集团军司令（驻防平郊）、伪大同县知事（县长）、伪太原市长、伪阳泉矿区维持会会长', '1935-1944', '', '所部驻大兴黄村、南苑等地，参与“扫荡”平南根据地，制造多起惨案。；管辖通州等冀东地区，积极推行日伪“新民会”活动，组织汉奸武装，协助日军扫荡。；日军占领大同后出任伪县长，推行保甲制度，组织伪警察协助日军清乡，抓捕抗日军民，征收苛捐杂税。；任伪太原市长期间，推行日伪市政管理，强拆民房，为日军建立兵营和仓库。；日军占领阳泉后，主动投靠日寇，组织维持会，为日军征调矿工、强征民夫，协助日军掠夺煤炭资源，镇压矿工反抗。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3c0cec769a465f2da5d9587d32cf51f4', '王永清', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、吉林、山西、河北、辽宁', '内蒙古、吉林、山西、河北、辽宁', '[]', '伪丰宁县警务科科长、伪元宝山维持会会长、伪兴隆县保安团长、伪冀东防共自治政府滦州清乡主任、伪双桥区警察署署长、伪喀喇沁左旗旗长、伪围场县协和会会长、伪大同县知事、伪大同宪兵队翻译兼密探、伪天镇县知事、伪安东省地方保安局局长、伪山西省合作社联合会理事长、伪平泉县警察署署长、伪广灵县县长、伪广灵县知事、伪建昌县县长、伪张家口市商会会长、伪承德县警察署署长、伪敖汉旗保安队队长、伪朔县县长、伪朝阳地区保安队队长、伪桦甸县警务科科长、伪浑源县县长、伪满凌源县县长、伪满抚顺县保安队队长、伪满梨树县县长、伪满洲国热河省警备军旅长、伪满洲国锦州省警察讨伐队队长、伪满西安县（今辽源市）县长、伪满铁岭地区警察署长、伪灵丘县知事、伪热河省协和会丰宁分会会长、伪热河省滦平县县长、伪热河省警务厅厅长、伪热河省警务厅长、伪磐石县保安队队长、伪蒙古军第6师师长、伪蒙古军骑兵第5团团长、伪赤峰警察局局长、伪通辽县警察署署长、伪通辽地区保安队队长、伪金州警察局局长、伪阳高县县长、应县伪县长、蛟河县伪县长', '1932-1945', '', '在呼和浩特、托克托地区驻防，多次率部进攻八路军大青山支队，杀害抗日干部和群众。；长期在巴彦淖尔地区活动，率部袭击抗日游击队，抢劫村庄，并参与日军“扫荡”行动，杀害无辜百姓。；效忠日伪当局，指挥警察抓捕抗日志士，参与“治安肃正”行动，迫害无辜百姓。；在元宝山矿区组织伪维持会，为日军提供煤炭资源情报，强迫矿工为日军服务，镇压矿工反抗。；率保安队协助日军“扫荡”，在敖汉旗南部山区多次袭击抗日游击队，杀害多名抗日人员及群众。……（共涉及50个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
