REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('663db8b222185e65916a5b94545a578e', '王永魁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪大同省警务厅长、伪左云县知事（县长）、伪阳泉警察局局长', '1938-1945', '', '任伪左云县知事期间，配合日军“扫荡”，建立伪村公所，强征民夫修筑碉堡公路，搜捕抗日干部，向日军提供左云抗日武装情报。；负责伪大同省警察系统，协助日军建立特务情报网，在新荣区及周边村庄抓捕抗日干部和群众，刑讯逼供，杀害多名抗日志士。；在任期间，协助日军建立特务情报网，破坏地下抗日组织，逮捕多名地下党员，并严刑逼供。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
