REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7eaa90ba217050158dd164b88dd7ca7f', '王竹林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、河北', '北京、天津、河北', '[]', '伪冀东道公署教育科长、伪天津县知事/县长、伪天津商会会长、伪天津商会会长、伪华北工商协会会长、伪天津市商会会长、伪天津市商会会长、伪天津特别市公署参事、伪天津市治安维持会委员、伪天津特别市公署警察局局长、伪天津特别市商会会长（1938-1945）、伪天津特别市市长、伪宁河县知事、伪通州保安团长、伪静海县保安队队长、天津商会会长、伪天津市治安维持会委员、天津治安维持会会长、伪天津市市长', '1937-1945', '', '率领伪保安团参与“清乡”，杀害抗日干部，强抓壮丁补充伪军。；作为伪天津县行政长官，管辖包括东丽在内的区域，配合日军清乡，强征民夫，实施保甲制度。；曾任伪天津市治安维持会委员长，后任伪天津特别市市长，积极推行日伪政权统治，镇压抗日活动。；充当日伪经济汉奸，为日军征调物资，强迫商户捐款。；投靠日军，组织伪商会，为日军筹款征粮，协助日伪政权控制天津经济命脉，镇压抗日商民运动。……（共涉及22个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('402ca43b97e252b0addf0004f0c5b4db', '王竹林（同名？）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津', '天津', '[]', '伪津南维持会会长（小站地区）', '1937-1938', '', '在小站地区组织维持会，迎接日军，协助建立伪政权，欺压百姓。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7d83da19164056e89585bf2075e4c39a', '王绍先', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、河北', '吉林、河北', '[]', '伪冀东道公署参议、伪冀南道尹公署顾问、伪唐山矿区警察署长、伪唐山警察局局长、伪河北省冀东道尹（驻石门）、伪满德惠县警务科长、伪石家庄商会会长、伪邯郸县公署知事', '1933-1945', '', '在德惠地区抓捕抗日地下工作者，破坏抗联联络点。；在唐山矿区镇压矿工反抗，强迫矿工为日军开采煤炭。；指挥伪警察搜捕抗日地下工作者，多次参与“清乡”行动，残害百姓。；在石家庄桥西一带推行保甲制度，强征壮丁，为日军提供劳役和情报。；强迫商户向日军捐献物资，控制粮食配给，从中牟利，资助伪军。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2307c9b62e84544eb9cffe1d95846ae0', '王绍文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '寿阳县伪县长', '1937-1945', '', '投靠日军，任寿阳县维持会会长及伪县长，协助日军推行“治安强化”运动，强征民夫，搜刮粮食，镇压抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f4575ccf91a355f3b296f9c9ce9b70df', '王绍曾', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪丰南稻地镇自卫团团长、伪冀东政府唐山市长（或唐山地区伪行政长官）、伪冀东银行山海关分行经理、伪冀东防共自治政府唐山商会会长、伪玉田县新民会会长', '1935-1945', '', '在丰南稻地镇组织汉奸自卫团，配合日军巡逻，袭击抗日游击队，残害百姓。；协助日军控制唐山工商业，为伪军提供经费。；在玉田推行奴化宣传，组织“反共”团体，收集抗日情报。；在唐山市区任伪职，管理日占区民政，协助日军实行经济统制，掠夺开滦煤矿资源，镇压工人罢工。；为日伪发行军用票，扰乱金融，掠夺当地财富', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4c37e59668c1598c804bf86b8f98051c', '王绍武', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪滦县知事、伪石家庄地区特务队长、伪邢台宪兵队翻译官、伪邯郸县新民会会长、伪邯郸县知事', '1938-1945', '', '滦县（路南核心）伪县长，强征粮食、劳工，为日军修建碉堡，镇压滦河两岸抗日武装。；专门搜集抗日情报，抓捕地下党员，酷刑审讯，导致多个抗日组织被破坏。；协助日军宪兵队刑讯逼供，残害抗日志士。；充当日军傀儡，在邯郸县城及周边乡村建立伪保甲制度，强征民夫修筑碉堡公路，配合日军‘扫荡’，残害抗日军民。；组织新民会，开展‘宣抚’活动，诱骗青年参加伪军，收集抗日情报，破坏群众抗日团体。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('77b3e5f877bc5245b2b68373f7c53f58', '王继尧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '太谷县伪维持会会长', '1937-1939', '', '日军初占太谷时组织维持会，为日军筹集粮款，提供情报，帮助建立伪政权。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('93d8db91ae0b5db68c9847f1bbe19829', '王绪', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津', '天津', '[]', '伪天津市市长（1943-1945）', '1943-1945', '', '任伪天津市市长期间，推行日伪统治政策，协助日军征粮、镇压抗日活动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d2ee8f86e2bb5c469998afa9e90425f7', '王绪高', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北', '天津、河北', '[]', '伪冀东道保安队指挥官、伪冀东道尹（驻唐山）、伪天津县知事（辖北辰地区）、伪天津地方法院院长、伪天津特别市教育局长、伪天津特别市第三区（红桥一带）区长、伪天津特别市警察局局长、伪天津警察局局长、伪蓟县县长、伪西青地区维持会会长', '1937-1945', '', '作为伪天津县行政长官，管辖北辰一带，强征粮税，协助日军建立保甲制度。；利用司法权力迫害抗日人士，判处多名南开区地下党员及爱国师生重刑，为日军“军法会审”提供法律掩护。；掌管伪天津警察机构，配合日军搜捕抗日地下人员，破坏抗日组织，实施白色恐怖统治。；任伪天津警察局长，协助日军搜捕抗日分子，镇压民众反抗，参与制造多起血腥事件。；推行奴化教育，强制学校教授日语和“中日亲善”课程，压制抗日思想传播。……（共涉及15个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
