REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0518f249e38156f7b288c3fe0f62f301', '王老四（王振海）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '栾城县伪警察所所长、高邑县伪警察所所长', '1939-1945', '', '效忠日军，负责栾城县城治安，严查抗日嫌疑人员，多次带队搜捕地下党员，刑讯逼供，致多名抗日志士牺牲。；任伪警察所长，负责高邑县城治安，协助日军清查抗日分子，多次带队突袭村庄，掠夺财物。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c077e5f0d3ec5a70b845dd6f673a4e3d', '王老振', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '宁晋县伪自卫团长、平乡县伪警察所所长', '1940-1945', '', '组织伪自卫团，协助日军在宁晋县东部地区设卡盘查，抓捕抗日军民，强征壮丁，欺压百姓。；充当日军耳目，抓捕抗日地下党员，破坏地下交通站，勒索百姓。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('cf0902688dc95e0c8616a3e715c3b6a5', '王老昆', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '安平县伪自卫团团长、晋县伪新民会会长', '1941-1945', '', '在晋县推行奴化教育，组织“新民会”宣传亲日思想，强迫民众参加反共集会，协助日军建立保甲制度。；组织伪自卫团，为日军站岗放哨，带路扫荡，抢劫百姓财物，杀害抗日军属。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b84d2d138cd956bbb3bb86a1cfc6aafd', '王老黑', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪束鹿县（今辛集）新民会会长、晋县伪自卫团团长、深泽县伪自卫团团长、饶阳县伪警察所所长', '1940-1945', '', '组织伪自卫团，协助日军封锁交通，参与“治安强化运动”，残害抗日军属。；组织伪自卫团，在深泽县各村设岗放哨，监视抗日活动，抓捕八路军交通员，配合日军“铁壁合围”扫荡。；积极推行奴化教育，组织“新民会”宣传“中日亲善”，诱骗青年参加伪军，破坏抗日组织。；充当日军耳目，破坏地下党组织，严刑拷打抗日家属，勒索百姓财物。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fbc7cbbcbd6d5095a20261e001fe0f59', '王自全', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪临漳县警备队大队长、伪广平县知事、伪邯郸县自卫团团长、伪邯郸县警备队大队长、伪魏县警备队大队长、伪县长', '1938-1945', '', '组织地主武装投靠日军，在邯郸东部村庄建立‘爱护村’，强迫村民报告八路军动向。；率部投敌，充当日军爪牙，多次配合日军扫荡临漳抗日根据地，杀害抗日干部和群众，抢劫财物。；在邯郸地区为日军效力，负责维持伪秩序，参与抓捕抗日分子，并勒索百姓，扩充私人武装。；在广平县建立伪政权，配合日军‘扫荡’，抓捕抗日干部，强征民夫修筑炮楼和公路，并参与掠夺粮食资源；投靠日军，任伪魏县县长，强征粮税，抓捕抗日家属，破坏地下党组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('47be125cd0de5ba8a8cf8e8e51fdcc18', '王自新', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '磁县伪保安联队长', '1938-1945', '', '组织伪保安队，配合日军扫荡抗日根据地，杀害抗日干部和群众，制造多起惨案。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2b5378ecc56d5f4f84f06756e495b505', '王英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、北京、天津、山西、河北', '内蒙古、北京、天津、山西、河北', '[]', '万泉县伪保安队队长、伪“大汉义军”总司令、伪绥西联军司令、伪“大汉义军”总司令、伪蒙疆骑兵师长、伪万泉县知事、伪东亚同盟军总司令、伪东亚同盟军总司令、伪绥西联军司令、伪东亚同盟军总司令、绥西自治联军总司令、伪东亚同盟军总司令（曾扰冀东）、伪东亚同盟军总司令（活动于冀中）、伪东亚同盟军总司令（活动于冀南）、伪东亚同盟军总司令（活动于察哈尔地区）、伪东亚同盟军总司令（活动于山西北部）、伪东亚同盟军总司令（活动于晋冀豫边区）、伪东亚同盟军总司令（活动于晋西）、伪临晋县知事、伪临汾县新民会会长、伪临汾县警察局局长、伪临汾道尹公署顾问、伪偏关县知事、伪兴县警备队长、伪冀南道保安队指挥官（活动于邢台地区）、伪冀南道剿共总司令、伪冀南道尹（兼辖南宫）、伪垣曲县保安大队长、伪垣曲县保安队队长、伪大汉义军司令（曾活动于冀东）、伪大汉义军总司令、伪察哈尔省保安司令、伪屯留县知事、伪山西剿共军第2师师长（活动于晋中）、伪山西省保安司令部顾问、伪运城地区维持会会长、伪山西省公署顾问、伪晋中道尹、伪山西省公署顾问、伪长治县知事、伪山西省政府顾问、长治维持会会长、伪平遥县知事、伪平顺县知事、伪昔阳县知事、伪晋南剿共军司令、伪汾阳县知事、伪沁县县长、伪渤海骑兵师师长、伪潞城县知事、伪灵石县知事、伪盐湖保安队队长、伪祁县县长、伪祁县维持会会长、伪绥西联军司令、伪绥西联军司令、伪大同地区保安司令、伪绥西联军司令、大同周边伪军头目、伪绥西联军司令、晋南伪军顾问、伪绥西联军司令（在河北北部活动）、伪绥西联军司令（曾窜扰晋东南）、伪绥西联军司令（活动于察哈尔）、伪绥西联军司令（活动于晋西北）、伪绥西联军总司令、伪东亚同盟军总司令、伪绥西联军总司令（活动涉及晋西）、伪绥西自治联军司令、伪绥西自治联军司令（涉晋西北）、伪绥西自治联军总司令、伪绥西自治联军总司令、伪东亚同盟军总司令、伪绥西自治联军总司令、伪大同地区宣抚使、伪绥西自治联军总司令、天镇地区伪军头目、伪绥西自治联军总司令（曾窜扰晋城地区）、伪绥西自治联军总司令（曾窜扰晋城）、伪绥西自治联军总司令（活动于冀南）、伪绥西自治联军总司令（活动于晋西）、伪芮城县维持会会长、伪蒙古军副总司令、伪大同省省长、伪蒙古军总司令、伪蒙古军总司令（活动于邢台周边）、伪蒙古军第1军军长、伪绥西自治联军总司令、伪蒙古军第1军军长、绥西自治联军总司令、伪蒙古联合自治政府大同省省长、伪蒙疆自治军第一师师长、伪蒙疆自治政府副主席、伪绥西联军总司令、伪黎城县知事、壶关县伪县长、绛县伪保安队队长、襄垣县伪县长、闻喜县伪保安队队长', '1933-1945', '', '原土匪出身，投日后在乌兰察布、丰镇一带活动，率伪军配合日军进攻大青山抗日根据地，劫掠民众，罪行累累。；原绥远地方土匪/军阀，1937年投日，在乌兰察布、兴和及绥远地区组织伪军，配合日军扫荡抗日根据地，残害百姓，后任伪绥西联军司令。；绥远土匪出身，投日后率伪军多次进犯凉城、蛮汉山一带，配合日军扫荡八路军大青山支队，烧杀抢掠。；绥远土匪出身，投日后任伪绥西自治联军总司令，活动于绥远中东部（含卓资、乌兰察布），多次配合日军进攻抗日根据地，残害百姓。；原土匪出身，投日后任伪绥西联军司令，活动于乌兰察布南部及商都一带，配合日军袭击抗日游击队。……（共涉及130个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('30d726619dfd507f871bf6220b3aa8e2', '王英（重复，不列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '', '', '', '', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0af6ba7053d65d28a6a658e260fef4aa', '王荆山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪大连市公署参事、伪满洲国吉林省伪参事官（二道地区）、伪满洲国奉天市商会会长、伪满洲国辽阳县商会会长、伪满洲国长春市商会会长、伪满锦州省商会会长、伪满长春地区商会会长', '1931-1945', '', '在二道河子地区（今二道区）协助日军建立“集团部落”，制造无人区；在长春汽车经开区一带为日军筹措物资，强迫商户“献金”，协助经济掠夺。；长春大商人，投日后任伪商会会长，在长春经开区一带为日军筹措物资，强迫商户捐款。；大连地方士绅，投日后任伪市公署参事，协助日伪推行“治安强化”运动。；控制沈阳商业，为日军筹集物资，强迫商户捐献“国防献金”。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2871fc7ce975500c921280aaeed107db', '王荫堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪平定县公署顾问', '1939-1945', '', '日本特务机关培植的汉奸，参与策划“治安强化运动”，在阳泉矿区设立情报点，向日军报告八路军活动，导致多次抗日行动失败。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('755adf10c2775724918cf086a9a4e5a7', '王荫棠', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪交河县维持会顾问', '1937-1942', '', '为日军出谋划策，策划对运河渡口的封锁，导致抗日物资运输中断，并出卖地下党员名单。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('95ff7846d44f5084991c9d5d1c60db78', '王荫泰', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北、辽宁', '北京、河北、辽宁', '[]', '伪华北政务委员会外交总署督办、伪华北政务委员会委员长（后期）、伪华北政务委员会实业总署督办、伪华北政务委员会实业总署督办（管辖秦皇岛工业）、伪华北政务委员会常务委员、伪外交总署督办、伪满司法部大臣（涉辽宁）', '1932-1945', '', '负责伪华北政权对外事务，协助日本控制北平外交资源，镇压抗日外交活动。；在北平参与伪政权外交事务，协助日本与汪伪政权协调，在延庆等县推行“中日亲善”宣传。；在北平处理伪政权外交，协助日军与伪满等傀儡政权协调，影响昌平边境事务。；在北平主持伪华北政务委员会，继续配合日军“治安强化”，镇压海淀及周边抗日力量；协助日本掠夺华北资源，控制工矿企业。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
