REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('86b128d643ea53eaab6f28c94a4ac65a', '王葆华', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪九台县警察署署长、伪满四平省省长', '1932-1945', '', '原伪满地方官员，后任伪满四平省省长，管辖四平、伊通等县，积极推行日伪“粮谷出荷”政策，强征农民粮食，镇压抗日活动。；率伪警配合日军扫荡，抓捕抗联联络员，烧毁村庄', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d69993c601615115a153d8b3790f47de', '王裕文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪庄河县保安队长', '1933-1945', '', '率伪保安队配合日军围剿庄河地区抗日武装，烧毁村庄，残害百姓。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('893a5a0c549b5d46a9901248f7c35e96', '王谦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪古交区情报站长、伪大同商会会长、伪大同省公署参事（分管浑源）、伪娄烦县维持会会长、伪山西省教育厅长、伪平遥县知事（县长）、灵石县伪县长', '1937-1945', '', '充当日军经济汉奸，组织商会为日军筹集军费，垄断煤炭贸易，压低矿工工资，从中牟利。；在伪大同省任职期间，多次到浑源督导‘治安肃正’，组织伪军配合日军进攻八路军游击队。；建立汉奸情报网，向日军报告古交抗日武装动向，导致多名游击队员被捕。；组织维持会为日军征粮派款，协助日军建立伪政权，镇压抗日群众。；推行日伪奴化教育，在太原各学校强制教授日语，篡改历史教材，迫害爱国师生。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b9b9281a3905508ebeb502d258ef0155', '王谦（注：与八路军将领王谦同名，此处为伪职人员）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪太原县（今晋源区）新民会会长', '1940-1945', '', '负责新民会宣传，组织汉奸团体，破坏抗日群众组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
