REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2a9f51e2c3a35c1b9d6524a11df3762c', '王贤宾', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪新民县警务科科长、伪满抚顺县警务科长', '1933-1945', '', '指挥伪警察抓捕抗日分子，协助日军实施“归屯并户”，制造无人区。；指挥伪警察在新民地区抓捕抗日游击队员，破坏地下组织，多次参与“讨伐”行动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7037a12edcf455768f6b525f8ae7ba4e', '王贯一', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满洲国大连市副市长', '1931-1945', '', '投日后任伪大连副市长，协助日本管理大连租界，参与经济掠夺。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('cacf896855c95a028ba36bc74aacdcc3', '王连波', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪沧县保安联队队长', '1940-1945', '', '组织汉奸武装，在沧州渤海地区多次袭击八路军游击队，抓捕抗日群众并移交日军宪兵队。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a35aea7f619b5cd3901ef4ffb2366d22', '王连璧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪南皮县保安联队队长、伪沧县保安队大队长、伪献县保安联队队长', '1939-1945', '', '率伪保安队驻守南皮各据点，多次随日军“清乡”，抓捕抗日干部，抢掠百姓财物，并参与杀害八路军侦察员。；率伪保安队多次袭击孟村、盐山交界处的抗日武装，杀害抗日战士，抢劫百姓财物，充当日军鹰犬。；组织汉奸武装，多次袭击县抗日政府，杀害抗日干部，参与制造多起惨案。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
