REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f96eb25635db5849be6e4006313a7532', '王逆（王振华）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津', '天津', '[]', '伪蓟县新民会会长', '1941-1945', '', '在蓟县推行奴化宣传，组织汉奸情报网，向日军报告抗日活动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('51a74a29fb96567db19c03bca49f973a', '王金堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪磁县（含峰峰）保安联队副队长、伪长治县警备队中队长、威县伪维持会会长（初期）、威县伪警察所长、巨鹿县伪警察所所长、广宗县伪警察所所长、邢台县伪保安队副队长（活动于任泽一带）', '1937-1945', '', '率队参与“铁壁合围”扫荡，屠杀无辜村民，烧毁房屋。；在任泽边界地区协助日军建立伪据点，参与“清乡”行动，残害抗日家属，勒索乡民。；效忠日军，管理伪警察，搜捕抗日分子，严刑逼供，为日军提供情报，参与“三光”政策下的烧杀行动。；日军占领威县后率先组织维持会，为日军筹粮派款，提供劳役，帮助日军稳定占领秩序，后转任伪县公署顾问。；效忠日军，负责搜捕抗日分子，严刑拷打被捕人员，破坏地下抗日组织。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6f0343aa422a587fa206500f7a5d85ec', '王金声', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪吴桥县警察所所长、伪沧县（今沧州）警备队副队长、伪深县保安联队长、伪清河县保安联队队长、伪衡水县警备大队长、枣强县伪警察所所长、衡水县伪县长', '1938-1945', '', '在沧县及东光交界地区协助日军清乡，残害抗日家属，抢劫民财。；效忠日军，负责伪警察系统，搜捕抗日地下人员，破坏中共地下组织，参与“清乡”行动。；在深县地区协助日军建立据点，围剿抗日武装，强征民夫修筑炮楼。；在衡水推行日伪统治，设立伪警察所，强征劳工，协助日军修建碉堡和封锁沟。；为日军搜集情报，抓捕抗日地下人员，参与‘清乡’行动，迫害抗日家属。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3a4a73a4579e5c0f9fcc489015d4071f', '王金栋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪衡水县警察所所长', '1940-1945', '', '在伪警察所任职期间，大肆搜捕抗日地下工作者，严刑逼供，破坏抗日组织，为日军提供情报。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('cd0c4268057758a6ad2607398a6260c5', '王金铭', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀县（今冀州区）知事、伪威县知事（今属邢台）', '1939-1945', '', '在冀县（现属衡水市）为日军效劳，推行保甲制度，强征捐税，破坏抗日组织。；在冀县推行日伪奴化教育，强征民夫修筑炮楼和公路，向日军提供抗日武装情报，导致多起抗日人员被捕牺牲。；在威县推行伪化统治，强征壮丁，破坏抗日组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8ce20018fb64587684782dc67f69ba02', '王铁珊', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪任丘县保安联队队长', '1940-1945', '', '率伪军多次袭击任丘周边抗日武装，杀害抗日干部，烧毁村庄，强抓壮丁补充伪军。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bc18fe5ce9665dd19c23a3c03acad179', '王铁相', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪丰润县知事（唐山属县）、伪冀东保安队第三总队队长、伪冀东剿共军副司令、伪冀东道公署道尹、伪冀东道尹公署道尹、伪冀东道尹公署道尹（驻唐山）、伪冀东防共自治政府保安队总队长、伪冀东防共自治政府保安队第六总队长、伪华北治安军第12集团司令、伪唐山保安队副队长、伪唐山特别市公署市长（1940年后）、伪唐山特别市市长（日占时期）、伪山西剿共军第7师师长、伪沧县保安队队长、伪沧县知事、伪沧州道尹公署道尹、伪治安军第五集团军司令、伪玉田县知事（县长）、伪蠡县警察局局长、伪遵化县知事', '1935-1945', '', '在晋中地区强抓壮丁，扩充伪军，参与对左权县抗日根据地的进攻。；负责伪警察系统，搜捕抗日地下党员，破坏交通联络站，多次带队突袭村庄。；在丰润县推行日伪统治，强征民夫修筑碉堡，镇压抗日活动。；作为伪冀东道最高行政长官，管理唐山及周边县市，推行保甲制度，强征捐税，配合日军“扫荡”。；驻防唐山周边，参与围剿抗日游击队，残害百姓，掠夺财物。……（共涉及20个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7c641f3f44ff573288d2c871bd9e203f', '王锁柱', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪左权县警备队队员', '1943-1943', '', '参与抓捕左权县抗日妇女干部，施以酷刑，致其残废。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('19fb47a898685fbb9631c8b660b6a8f2', '王锡三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪冀东防共自治政府滦州教育局长、伪安国县新民会会长、伪怀柔县新民会会长、伪曲阳县保安联队队长、伪望都县保安联队队长、伪深泽县知事、宁晋县伪保安联队队长、广宗县伪警察所所长、广平县伪警察所所长、衡水县伪县长', '1935-1945', '', '主持怀柔新民会，推行奴化教育，组织“反共宣传”，强迫民众参加日伪集会，为日军收集情报。；负责日伪‘新民会’在安国的宣传与奴化教育，强迫民众参加反共集会，搜集抗日情报供日军使用。；组织伪保安队配合日军扫荡曲阳抗日根据地，多次带队袭击村庄，杀害抗日干部和群众，抢劫粮食资敌。；率伪军驻守望都各据点，多次参与对抗日根据地的“扫荡”，烧毁村庄，抢劫粮食，并杀害多名八路军侦察员。；在滦州学校强制推行日语教学，开除抗日教师。……（共涉及10个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4dc8c4132bfb541db57b7e62043498a7', '王锡三（同名）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府滦州学校校长', '1935-1938', '', '在滦州学校强制学生唱日本国歌，体罚抗日学生。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
