REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2c8264f7340c53c7b55fd332468d7b4c', '王锡朋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪香河县保安团长', '1938-1945', '', '带领伪保安团协助日军“扫荡”，杀害多名抗日群众，掠夺粮食资敌。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b48ca46c920c5d86815e7d749a4acc2c', '王锡符', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京', '北京', '[]', '伪宛平县警察所所长、伪怀柔县保安队队长、伪顺义县保安队队长、伪顺义县知事（1941-1943）', '1939-1945', '', '率伪军配合日军扫荡抗日根据地，抓捕抗日军民，参与制造多起惨案。；率伪警在门头沟斋堂、清水一带搜捕抗日干部，破坏地下党组织。；配合日军“治安强化运动”，在顺义各乡建立伪自卫团，抓捕抗日干部。；率伪军多次配合日军围剿八路军游击队，在顺义西部村庄烧杀抢掠，抓捕并杀害抗日干部。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e561c74c32095cd8ba9bd5823d42686c', '王锡钧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪临榆县知事、伪昌平县知事（约1943-1945）', '1940-1945', '', '任内强征民夫修筑工事，搜刮粮食，协助日军控制昌平山区。；在山海关推行日伪“治安强化”运动，强迫民众参加反共集会', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f223b1b5966f5fcba005351202deb598', '王靖国', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪“山西剿共军”指挥官（争议）、伪山西保安副司令、伪山西保安司令部副司令（投敌后）、伪山西剿共军副总司令（曾指挥部队在隰县、临汾作战）、伪山西剿共军第1军军长（投敌后）、伪山西剿共军第一军军长、伪山西和平救国军总司令、伪山西省公署顾问、伪山西省公署顾问、伪五台县维持会会长、伪山西省剿共军司令、伪晋西地区保安副司令、伪晋西地区保安司令（一说为阎锡山部，但曾与日军秘密合作）、伪静乐县知事', '1937-1945', '', '在吉县、蒲县等地组织伪保安团，协助日军镇压民众反抗，参与“三光”政策下的破坏行动。；原阎锡山部将领，后投靠日军，在汾西、临汾一带组建伪军，参与对抗日根据地的进攻，杀害抗日军民。；原阎锡山部将领，后投靠日军，在晋西地区参与围剿八路军和抗日游击队，制造多起惨案。；原阎锡山部军长，投日后任伪军总司令，在临汾地区驻防，参与“扫荡”太岳根据地。；在交口、隰县一带活动，与日军达成局部停战协议，默许日军通过其防区进攻八路军，并向日军提供情报。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3f68c596849c5d5c85302b26600063bb', '王靖国（注：此人为阎锡山部将，未投日，不列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '', '', '', '', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9d9a0add0c285a94840c9d63f7e0641c', '王静修', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪吉林市市长、伪吉林市警察局长、伪吉林省教育厅长、伪吉林省警务厅厅长、伪吉林省警务厅督察长、伪吉林省警务厅长、伪满东丰县县长、伪满吉林市市长、伪满吉林市警察局局长、伪满洲国军政部次长（辽宁籍）、伪满洲国吉林市市长、伪满洲国吉林省伪警务厅长、伪满洲国吉林省警务厅长、伪满洲国奉天省监狱长、伪满洲国长春市市长、伪满铁岭地区警务处处长、伪长春特别市市长（新京特别市长）、伪长春（新京）特别市市长', '1931-1945', '', '投日后任伪吉林市长，推行奴化教育，强征物资。；指挥警察在船营地区搜捕地下抗日分子，破坏抗日组织，协助日军进行“思想矫正”。；在东丰县任伪县长期间，推行日伪“保甲制度”，组织自卫团，配合日军清乡，抓捕抗日群众，强征壮丁。；在长春（新京）担任伪市长，协助日本进行城市规划和殖民管理，强制推行保甲制度。；负责伪吉林警察机构，搜捕抗日分子，破坏地下组织，协助日军讨伐……（共涉及22个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('df85b9e8c1b05cedba1173db2a702e1b', '王静轩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪大连市副市长（1942-1945）、伪岫岩县警察大队大队长、伪满吉林市市长（丰满地区属吉林市管辖）、伪满奉天市警察局副局长、伪满开原县法院院长、伪满洲国吉林省公署参事官、伪满洲国奉天省民政厅厅长、伪满洲国康平县维持会会长、伪满洲国绥中县副县长、伪满洲国长春地区宪兵队翻译官、伪满苏家屯警察署署长、伪辽阳县长', '1931-1945', '', '任伪吉林市市长期间，配合日军修建丰满水电站，强征劳工，造成大量劳工死亡，并协助日军推行“治安肃正”政策。；为日军宪兵队充当翻译，参与刑讯逼供抗日人士，罪行累累。；原吉林省官员，投日后在吉林市伪省公署任职，参与推行保甲制度。；辽宁大连人，任伪副市长，协助日本市长管理市政，推行粮食配给制，导致大连民众饥荒。；协助日伪警察镇压抗日活动，参与抓捕地下党员。……（共涉及12个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('13763c05013c5be59bc67649e34cc6af', '王静轩（重复？）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪岫岩县警察大队大队长', '1934-1945', '', '已列，补充其曾参与“大讨伐”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('decde3a9e5125b99a93cb5e72fc89072', '王风岗', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪满城县知事（县长）', '1938-1943', '', '任伪满城县知事期间，推行日伪保甲制度，强征粮食和民夫，配合日军“治安强化运动”，镇压抗日活动，破坏地下党组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('639800ac767a553e8cb106c6e62d7186', '王骥', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪武乡县知事', '1939-1943', '', '1939年出任伪武乡县知事，组织伪县署，强征民夫修筑公路和碉堡，配合日军多次清乡，抓捕抗日干部和群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2b38113bed725cedaecdd9dc8d6365ec', '王骧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪上党道尹、伪上党道尹公署道尹、伪临汾县知事、伪临汾县知事/伪县长、伪临汾县知事/县长、伪临汾县知事/维持会会长、伪临汾道尹（伪临汾地区行政长官）、伪大同县知事/伪大同公署官员、伪太原市市长、伪太原绥靖公署参议（涉及娄烦）、伪山西省公署教育厅厅长、伪山西省公署教育厅长、伪山西省公署警务厅厅长、伪山西省公署警务厅厅长（涉及晋城）、伪山西省公署顾问、伪山西省公署顾问/伪太原市长、伪山西省公署顾问、伪太原市市长、伪山西省公署顾问、伪榆次县知事、伪山西省公署顾问兼临汾地区伪职、伪山西省公署顾问兼临汾地区维持会会长、伪山西省公署顾问兼临汾地区维持会头目、伪山西省公署顾问兼太原维持会会长、伪山西省公署顾问兼晋中地区伪职、伪山西省公署顾问兼警务厅长、伪山西省警务厅厅长、伪晋中道尹、伪长治县知事、伪长治县知事/县长、伪长治县知事/维持会会长、伪长治县知事（县长）', '1937-1945', '', '日军占领临汾后出任伪维持会会长，后任伪临汾县知事，为日军提供情报，强征民夫修筑工事，迫害抗日家属。；日军占领临汾后出任伪县长，组织维持会，为日军征粮派夫，镇压抗日活动，协助建立伪政权基层机构。；在临汾组织维持会，为日军征粮派夫，破坏抗日组织，协助建立伪政权。；在临汾地区组织伪维持会，为日军征粮派夫，破坏抗日组织，协助日军扫荡。；日军占领临汾后出任伪县长，组织维持会，为日军提供情报，强迫民众修路筑堡，参与清乡扫荡，残害抗日军民。……（共涉及60个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('34b897a4511c56d49d74e54f1a0c3a96', '王麻子', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪临西县（今属邢台）警备队长、伪左权县特务、唐山伪商会会长', '1939-1945', '', '跟踪八路军干部，提供行踪，导致左权县一名区委书记牺牲。；为日军统制物资，强迫商户捐献钱财，帮助日军收购钢铁等战略物资。；在临西地区残害抗日干部，参与“无人区”制造。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e9d6895d49625d10aff374a3c26c6105', '玛尼巴达喇', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪兴安西省省长', '1932-1945', '', '在兴安盟西部及乌兰浩特周边配合日军清乡，组织伪警察队，参与围剿东北抗联部队。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ff5fde10ac305a6ea3e4ca46eefe3ca6', '甄洛黑', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '无极县东侯坊乡伪乡长', '1941-1944', '', '为日军催粮逼款，强抓壮丁补充伪军，多次带领日军包围村庄搜捕八路军伤员，致使伤员被俘遇害。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0783da7f980d5f62939afcf55f8baaa9', '甘珠尔扎布', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪兴安军将领、伪满第九军管区司令、伪兴安军指挥官、伪兴安南省省长、伪满洲国陆军中将、伪兴安南省警备军司令', '1931-1945', '', '日本关东军扶植的蒙古族汉奸，参与组建伪兴安军，在兴安、阿尔山一带协助日军维持治安，围剿抗日武装。；蒙古族投日分子，参与组建伪兴安军，镇压抗日力量，协助日军统治通辽地区。；蒙古族贵族出身，投靠日本关东军，参与组建伪兴安军，在通辽、奈曼旗一带镇压抗日武装，协助日军推行“治安肃正”计划。；科尔沁左翼中旗人，蒙古族。九一八事变后投靠日本关东军，参与组建伪兴安军，任伪兴安南省省长，协助日军镇压蒙古族抗日武装，推行奴化教育，强征劳工，为日军提供物资和情报。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bfd6fa60d8cd5c2bb50d740bab79faab', '申怀仁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪襄垣县新民会会长', '1939-1944', '', '宣传奴化思想，推行“中日亲善”谎言，组织青年参加伪军训练，破坏抗日群众组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('488fe9093e515586a4a3e608494f4f7f', '申怀珍', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪潞城县警备队队长', '1941-1945', '', '充当日军爪牙，在潞城、微子镇一带搜捕抗日分子，严刑逼供，并参与‘清乡’行动，烧毁村庄，抢夺财物。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('35b6332b3e3557d8b4a4066eb5b74619', '申文魁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪长治县（今长治市辖区）警备队副队长', '1939-1944', '', '在长治、潞城交界地带频繁袭击抗日游击队，杀害抗日战士，抢夺武器物资。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
