REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7919fe83935950c484b84fc165626e11', '白凤翔', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、河北、辽宁', '内蒙古、河北、辽宁', '[]', '伪东亚同盟军副司令、伪东亚同盟军副总司令、伪东亚同盟军总司令、伪东亚同盟军总司令（后反正）、伪东亚同盟军第1军军长、伪冀中剿共军司令、伪察北保安司令、伪察哈尔省保安团团长、伪察哈尔省保安队队长、伪察哈尔省警备司令（驻宣化）、伪平山县洪子店维持会会长、伪朝阳县县长、伪热河省警备军旅长、伪绥西联军副司令（后反正）、伪绥西自治联军副司令、伪蒙古军第1师师长、伪蒙古军第3军军长、伪蒙古军第3军军长（后反正）、伪蒙古军第3师师长', '1932-1945', '', '原国民党将领，投敌后在乌兰察布地区组织伪军，参与对抗日武装的“讨伐”，后因内部矛盾被日军处决。；原东北军将领，后投靠日军，在绥东（含兴和、乌兰察布）一带协助日军围剿八路军游击队，参与“治安肃正”行动。；原东北军将领，投日后在绥东、凉城一带收编土匪，配合日军进攻大青山抗日游击根据地。；投日后任伪东亚同盟军总司令，在内蒙古西部及绥远地区配合日军作战，围剿抗日武装。；原东北军将领，叛变投日后在包头地区组织伪军，参与日军对河套地区的扫荡，后因内部矛盾被日军处决。……（共涉及27个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('de8250ebfaaa563f81144b0512538c75', '白凤翔（白三阎王）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪绥西自治联军副司令', '1938-1945', '', '随王英在乌拉特中旗一带活动，参与“清乡”行动，搜捕抗日分子，强征民夫，掠夺物资。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
