REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('177c76103c835ba897fcc48ea9d8b906', '白坚武', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪华北自治联军头目', '1935-1937', '', '1935年参与“华北自治”阴谋，组织伪军骚扰冀东，后为日军效力。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('26bc6327b99951a39c4ac15c7d966a86', '白太冲', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '太谷县伪县长', '1937-1945', '', '投靠日军，任太谷县维持会会长及伪县长，协助日军推行“治安强化运动”，强征粮税，镇压抗日群众。；日军占领太谷后出任伪县长，协助日军推行“治安强化”运动，强征粮税，镇压抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fd0e81b6bf6c52f2999b8497dbaf0a27', '白志文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪大同县知事（县长）', '1937-1940', '', '日军侵占大同后出任伪县长，推行保甲制度，强征粮税，协助日军建立维持会，镇压抗日群众。；日军侵占大同后出任伪大同县知事，推行保甲制度，强征粮食劳役，协助日军镇压抗日活动，迫害爱国群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('23f501dac7075660a40e35f451c085d6', '白志沂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪大同县知事（曾兼左云县伪职）、伪宁武县警备大队长、伪山西省保安司令部副司令（太原及娄烦）、伪山西省公署民政厅长、伪阳泉维持会顾问、伪山西省建设厅厅长、伪山西省第十专区专员（后投敌）、伪晋北政厅厅长（驻大同）、伪晋西北剿共军司令、伪阳泉县知事、伪阳泉矿区维持会会长', '1937-1945', '', '原阎锡山部军官，投日后在吕梁山区组织伪军，专门袭击八路军后方。；任伪晋北政厅厅长，管理大同、云州等县，推行日伪法令，强征粮税，协助日军建立维持会。；任伪晋北自治政府要职，后任伪晋北政厅厅长，管理大同及周边县份，配合日军“治安强化运动”，奴化教育民众。；在左云、大同地区组织伪警察队，配合日军“清乡”，杀害抗日家属，强征苛捐杂税，破坏地下党组织。；指挥伪保安队在娄烦山区“清剿”，杀害抗日村长和民兵数十人。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('30b058ec06b95daca652f89cdc341679', '白文蔚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪离石县知事（柳林属离石）', '1939-1942', '', '在离石、柳林地区为日军征粮抓夫，镇压抗日武装，提供情报。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('46e5733fa31a5c5c9edb94951e479fcd', '白瑞生', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪邯郸道保安队曲周中队中队长、伪高阳县警察所所长', '1941-1945', '', '指挥伪警察特务，破坏高阳地下交通站，逮捕并严刑拷打抗日群众，向日军提供情报，致使多名游击队员牺牲。；率伪军中队驻守曲周县城，多次参与对冀南军区部队的作战，并杀害被俘的抗日战士，罪行累累。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
