REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('44d69fc62af8517382710ef1c1b4dd53', '石印堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪阳泉情报组组长', '1942-1945', '', '为日军搜集八路军和游击队活动情报，多次导致抗日武装遭袭，并参与抓捕抗日干部。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('08a1ec477255562bb8a0e3fe6556bf8f', '石友三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北', '天津、河北', '[]', '伪“冀察战区”副总司令（投敌后活动于邢台）、伪冀察战区副总指挥（后投敌）、伪冀察战区副总指挥（投敌）、伪冀察战区副总指挥（投日未遂被处决）、伪华北治安军第1集团军总司令（曾驻防保定满城地区）、冀察战区游击司令（后投敌）、冀察战区游击司令（后投敌，活动于邢台周边）、冀察战区游击司令（后投敌，活动涉及赵县）', '1938-1945', '', '原西北军将领，在河北南部与日军秘密勾结，企图投敌，被高树勋处决，未及正式投日。；反复无常，最终投日，其部队在保定、满城一带参与“治安强化运动”，围剿八路军。；1940年投敌，其部队在冀东地区活动，虽未长期驻留，但曾参与反共摩擦。；在赵县一带反复无常，最终投靠日军，其部队曾协助日军袭击抗日游击队。；反复无常，最终投敌，在邢台东部地区袭击八路军，残害百姓。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
