REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5d539abf99b357b2867c31ebe6513848', '石振山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪满城县新民会会长', '1940-1945', '', '为日伪宣传效劳，组织“新民会”进行奴化教育，诱骗青年参加伪军，搜集抗日情报提供给日军。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
