REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('406a78c4154f5d6a9f1dc81bb7c4bf31', '福龄', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪兴安北省参事官、伪兴安北省警务厅长、伪满洲国兴安北省警务厅厅长、伪满洲国兴安北省警务厅长', '1932-1945', '', '作为日本驻伪兴安北省参事官（实际为日本人，但此处按历史记录列入），协助日军控制呼伦贝尔行政和军事，镇压抗联三进呼伦贝尔的行动。；掌管伪兴安北省警察机构，协助日本宪兵队搜捕抗日地下人员，参与镇压海拉尔地区反满抗日活动。；在呼伦贝尔地区指挥伪警察，协助日军搜捕抗日分子，参与‘讨伐’抗联；在呼伦贝尔地区担任伪警务厅长，协助日本宪兵队搜捕抗日分子，镇压牧民反抗。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a00d44ca2e8b5e7fae32bec0caaf4670', '秦绍观', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪晋城“剿共”便衣队队长、伪黎城县知事', '1941-1945', '', '化装潜入抗日村庄，刺探情报，抓捕地下党员，多次带队突袭抗日区政府。；在黎城推行奴化教育，强迫学生学日语，并协助日军搜捕八路军伤员。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5add00735cda57e18d23a44f4cf685a0', '程子谦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '晋中伪保安司令部参谋', '1943-1945', '', '参与策划对太谷南山抗日根据地的“铁壁合围”，提供兵力部署建议，导致多名抗日战士牺牲。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7085cdcd9bb25b4e82a778bc43c30790', '程希孟', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀南道公署参议（驻邯郸）、伪广平县警备大队长、广平县伪维持会会长', '1937-1945', '', '原国民党地方官员，投日后任伪参议，为日军推行“治安强化运动”出谋划策，协助建立伪组织。；率警备队驻守广平各据点，参与日军‘蚕食’根据地行动，抓捕抗日群众送交日军宪兵队，并抢劫民间财物；日军占领广平后率先组织维持会，为日军筹粮派款，提供情报，协助建立伪政权。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
