REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d20dc98a469e5262ac91c570963efebd', '穆克登宝', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、河北', '内蒙古、河北', '[]', '伪察哈尔右翼前旗旗长、伪察哈尔盟保安队指挥官、伪察哈尔盟副盟长、伪蒙古军师长、伪察哈尔盟副盟长兼保安队队长、伪察哈尔盟警务厅长、伪蒙古军第2军军长、伪蒙古军第3师师长、伪蒙古军第4军军长、伪蒙疆政府察哈尔盟盟长', '1936-1945', '', '伪蒙古军高级军官，活动于绥远东部（含兴和、商都、化德一带），配合日军进攻大青山抗日游击队，参与“清乡”屠杀。；在乌兰察布地区活动，参与围剿抗日武装，为日军提供情报。；直接管理察哈尔右翼前旗日伪政权，向日军提供当地抗日活动情报，强征壮丁和牲畜，实施保甲连坐制度，镇压反抗民众。；在绥远地区率伪军参与对抗日根据地的围剿，曾在托克托县境内烧杀抢掠，破坏地下抗日组织。；原察哈尔部总管，投日后任伪察哈尔盟盟长，管辖苏尼特左旗等地区，推行日伪保甲制度，搜刮民财。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e9dcbc06f7da51b491b08b0a854afc6e', '章宗祥', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、河北', '北京、天津、河北', '[]', '伪华北政务委员会咨询委员、伪华北政务委员会天津分会委员、伪华北政务委员会法制顾问、伪华北政务委员会顾问、伪华北政务委员会顾问（居天津）', '1937-1945', '', '北洋政府前官员，北平沦陷后出任伪职，为日伪政权提供政治咨询，协助维持殖民秩序。；原亲日官僚，投日后在北平为日伪出谋划策，涉及昌平地区资源控制。；参与伪政权，为日本侵华政策辩护。；在天津分会任职，参与处理伪政权事务，支持日军侵略政策。；为日伪政权出谋划策，参与起草奴化政策文件，影响天津伪政府决策。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
