REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('17707e5071b3564ca8a6f70582f134ef', '管相齐', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪石家庄市市长（1944-1945）', '1944-1945', '', '在任期间继续为日军征粮征税，镇压市民反日情绪，提供情报给日军宪兵队。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ae5e62ce9181549e82e0d8ae0327fbba', '管翼贤', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪《新民报》社长、伪华北宣传联盟负责人、伪北平市宣传处处长、伪《新民报》社长、伪北平市新闻检查所所长、伪石家庄市市长、伪石家庄市市长（继任）', '1937-1945', '', '控制北平及丰台地区报刊舆论，查禁抗日言论，为日伪宣传服务。；在北平控制舆论，在大兴地区散发汉奸报纸，美化日军侵略，污蔑抗日军民。；在北平（含海淀）控制舆论，宣传“大东亚共荣”，为日伪张目，污蔑抗日活动；原新闻界人士，投日后任伪石家庄市市长，在井陉矿区强化治安，组织伪警察镇压矿工反抗，为日军提供煤炭资源。；继任伪石家庄市长，协助日军控制交通线，在平山地区强征民夫修筑碉堡和封锁沟。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
