REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9936be12436c5a11a69f204e19719f20', '罗振玉', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪满洲国参议府参议、伪满洲国参议（吉林籍，活动于长春）、伪满洲国监察院院长（后任，在长春活动）、伪满监察院院长、伪满参议府参议、伪满监察院院长（长春）', '1931-1945', '', '原清朝遗老，积极参与伪满建国，在四平地区活动，为日本侵略提供“历史依据”和意识形态支持。；积极鼓吹复辟，协助溥仪建立伪满，在长春参与伪满政治活动。；在长春（新京）任职，积极鼓吹“王道乐土”，为日本侵略辩护。；清朝遗老，积极推动溥仪出任伪满皇帝，在长春参与伪满政治活动，为日本侵略张目。；原清朝遗老，投靠日本后任伪满监察院院长，在长春积极鼓吹“王道乐土”，协助日本进行文化奴役。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('1dfa2e56c73a5f21b364cddcacef0519', '罗振邦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪南关区区长（新京南关区）、伪满吉林市协和会会长、伪满吉林警察厅厅长、伪满洲国吉林协和会会长、伪满洲国吉林市市长、伪长春市市长（新京特别市市长）', '1932-1945', '', '在吉林昌邑地区组织特务警察，抓捕抗日地下工作者，破坏抗联联络站。；在吉林市推行奴化教育，镇压反满抗日活动，配合日军“治安肃正”。；在南关区推行“连坐制”，强征捐税，协助日军搜捕抗日分子。；伪满洲国首都“新京”（今长春）市长，执行日本城市规划，强拆民居，建立殖民统治秩序。；投日后任伪吉林协和会头目，宣传“王道乐土”，组织奴化活动。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d0dc35dc2ec1562c9fed6773147f420d', '胡毓坤', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北', '天津、河北', '[]', '伪华北治安军副总司令、伪华北绥靖军参谋长', '1938-1945', '', '原东北军将领，投日后任伪华北绥靖军参谋长，参与策划对河北抗日根据地的军事行动。；协助齐燮元指挥伪军在廊坊地区进行“梳篦式”扫荡，屠杀抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
