REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c9a7e52fd0eb523bb7dc27de493f596e', '苏体仁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、山西、河北', '北京、山西、河北', '[]', '伪华北政务委员会实业总署督办、伪华北政务委员会教育总署督办、伪山西省省长、伪山西省省长（1938-1943）、伪山西省省长（大同籍）、伪山西省省长（曾涉华北）、伪山西省省长（管辖临汾地区）、伪山西省省长（管辖太原及娄烦）、伪山西省省长（管辖晋城地区）、伪山西省省长（管辖晋城高平）、伪山西省省长（管辖长治、长子地区）、伪山西省长（后调北平伪华北政务委员会任职）、伪山西省长（曾兼北平伪职）、伪山西省长（曾兼管平西部分地区）', '1937-1945', '', '在北平及丰台推行奴化教育，控制学校，强迫学生参加日伪活动。；虽主政山西，但后期在北平参与伪华北政务，曾到大兴视察“治安强化”成果，支持日军建立“模范村”。；虽主政山西，但曾参与北平伪政权高层会议，其势力范围涉及延庆西部山区，协助日军封锁抗日根据地。；在北平及海淀地区掠夺工农业资源，强征劳工，服务于日军战争需求；负责华北工矿资源统制，直接管理石景山制铁所的生产计划，强迫中国工人劳动，为日军提供军工原料。……（共涉及71个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
