REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4521f356ec205b2c8a2e82a1253b1d13', '苏尼特·补英达赖', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪蒙古军副司令、伪蒙古军第1军军长、伪蒙疆政府参议、伪巴彦塔拉盟盟长、伪蒙疆政府要员/伪锡林郭勒盟盟长', '1936-1945', '', '蒙古族上层，投靠德王和日军，率伪蒙古军在乌兰察布北部及兴和地区驻防，协助日军镇压抗日民众，征收粮草。；在德王政权中任职，协助日军控制乌兰察布北部牧区，征粮派款，镇压牧民反抗。；在呼和浩特新城地区协助日军管理民政，推行保甲制度，强迫民众领取“良民证”，举报抗日分子。；在武川、四子王旗等地协助日军建立伪政权，组织伪警察队，抓捕抗日地下工作者，强征牲畜粮食供给日军。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9ca78ea19f3f58189e90d8eaa6f68a75', '苏尼特·达理扎雅', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪蒙疆政府包头市市长', '1939-1945', '', '蒙古贵族，任伪包头市长期间，推行日伪法令，强征劳工，协助日军控制包头及东河地区经济命脉。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
