REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('52e76e3de571564cb8221d313b3064e0', '范老五', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '荣河县日伪便衣队队长', '1942-1945', '', '带领便衣队刺探抗日军情，多次引导日军突袭村庄，杀害抗日家属，罪行累累。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('eca6f1c850fc545c81553cc0cd3dc1fa', '荆耀南', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪临晋县警备大队长', '1941-1945', '', '指挥伪警备队配合日军突袭抗日村庄，放火烧毁民房，并亲自拷打被俘的抗日军民，致多人死亡。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('581b3709952c5c81bc3860d3c62dff90', '荣厚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪吉林省实业厅长、伪吉林省民政厅厅长、伪吉林省省长（后期）、伪吉林省省长（继熙洽后）、伪吉林省警务厅长、伪吉林省财政厅长、伪吉林省财政厅长、伪吉林省长、伪满中央银行副总裁（沈阳分行）、伪满中央银行总裁、伪满中央银行总裁（曾负责辽宁金融）、伪满吉林省财政厅厅长、伪满吉林省财政厅长、伪满吉林省财政厅长、伪满中央银行副总裁、伪满奉天省实业厅长、伪满奉天省教育厅长、伪满奉天省省长、伪满奉天省省长（阜新、彰武曾属奉天省）、伪满奉天省警务厅长、伪满奉天省高等法院院长、伪满洲国中央银行总裁、伪满洲国司法部大臣、伪满洲国吉林省伪省长、伪满洲国吉林省参事官、伪满洲国吉林省实业厅长、伪满洲国吉林省民政厅长、伪满洲国吉林省财政厅长、伪满洲国奉天市市长、伪满洲国奉天省民政厅厅长、伪满洲国奉天省省长、伪满洲国奉天省警务厅长、伪满洲国奉天省警务厅长（管辖鞍山地区）、伪满洲国热河省省长（曾任奉天省警务厅长）、伪满洲国锦州省高等法院院长、伪满洲国长春市伪市长（首任）、伪满洲国黑龙江省省长、伪满西丰县警务科科长、伪满锦州省省长、伪锦州省协和会会长', '1931-1945', '', '推行保甲制度，强化殖民统治，协助日军建立“集团部落”以隔离抗联。；原吉林地方官员，投日后任伪满吉林省财政厅厅长，负责为日军搜刮吉林、四平、伊通地区的粮食和物资，支持侵略战争。；投靠日本，任伪吉林省财政厅长及省长，协助日军搜刮资源，推行奴化教育。；协助日本财阀在船营地区开采矿产、掠夺森林资源，强征当地农民为矿工。；原吉林官银号总办，投日后负责伪满在吉林、辽源地区的财政搜刮，发行伪币，掠夺粮食和物资，支持日军战争。……（共涉及47个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7c51a2464caa5e18aaf829b24f6c43bc', '荣臻', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、河北、辽宁', '北京、天津、河北、辽宁', '[]', '伪华北政务委员会治安总署督办、伪华北政务委员会绥靖总署督办、伪华北治安军总司令、伪华北治安军总司令（涉冀中）、伪河北省保安司令、伪河北省保安司令、伪华北绥靖军第1军军长、伪河北省省长、伪河北省省长（后期）、伪河北省长（后期）、伪满军事部次长（涉辽宁）、伪满军政部总长、汉奸（曾驻辽阳）、伪满洲国军政部总长（曾任东北边防军参谋长）', '1931-1945', '', '在北平任职期间，负责伪军整编和“剿共”军事行动，对东城地区的地下抗日组织进行破坏。；原东北军将领，投日后在河北组织伪保安队，多次参与对冀中、冀西抗日根据地的进攻。；负责华北伪军整编，在廊坊一带部署伪军据点，配合日军对大清河、永定河流域的扫荡。；指挥治安军在廊坊、大厂等地反复清乡，杀害抗日干部，制造多起惨案。；在河间地区推行“新国民运动”，配合日军进行最后挣扎。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
