REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4dc1ca7c2e5d59e298c97f16fa6e4303', '蔡雄飞', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪山西剿共军副总司令、伪山西剿共军第1师师长', '1941-1945', '', '协助赵承绶指挥伪军，多次参与对晋西北抗日根据地的“扫荡”。；率伪军驻防晋中，多次进攻左权县抗日根据地，参与“铁壁合围”大扫荡，杀害八路军伤员。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('eaa98601735151758eb8003f30e945e6', '薛东藩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北', '天津、河北', '[]', '伪保定道尹、伪真定道尹（石家庄地区）、磁县伪保安联队长', '1938-1945', '', '投日后任伪保定道尹，在冀中地区建立伪组织，强征民夫修筑碉堡公路，协助日军封锁抗日根据地。；伪真定道（驻石家庄）最高行政长官，直接管理石家庄及周边各县，推行“治安肃正”，强征劳工。；率伪保安队配合日军在磁县山区‘扫荡’，抓捕抗日干部，烧毁村庄，民愤极大。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a885927cd073551fabc84253bbb152f3', '薛仁甫', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪永济县维持会副会长、日伪合作社社长、闻喜县伪教育科长', '1938-1945', '', '为日军征购粮食、棉花等战略物资，垄断食盐贸易，从中牟利，并强迫农民种植鸦片，导致当地民生凋敝。；强制推行奴化教育，删改教材，强迫学生参加日军庆典，宣扬“皇军必胜”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('81efd44528465ef987c1886265b3a5d0', '薛兴甫', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪邯郸县知事、伪高邑县教育科长、伪高邑县知事、石家庄伪市长（石门市）', '1938-1945', '', '在高邑县为日军强征军粮，建立伪警察所，多次带队突袭抗日村庄，杀害无辜百姓。；强制学校使用日伪教材，推行奴化教育，解散抗日小学，迫害爱国教师，组织学生为日军“祝捷”活动。；任伪石门市市长，协助日军建立殖民统治，推行奴化教育，强征劳工，为日军提供后勤支持。；任伪邯郸县知事期间，为日军提供情报，组织伪警察抓捕抗日干部，参与‘治安强化运动’。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('78b2a6e1f036599aa2ec811a194ae25d', '薛凤山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀南道公署参议兼武安办事处主任', '1942-1945', '', '为日军推行“以华制华”政策，在武安地区组织伪政权，协助日军掠夺铁矿资源，并诱降部分抗日意志不坚定者。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3bf67686c57252e08e39d6f5d301f744', '薛士选', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪万泉县维持会会长、闻喜县伪警备队副队长', '1938-1945', '', '日军初占万泉时组织维持会，为日军提供当地抗日武装情报，并强迫百姓欢迎日军，后被抗日武装处决。；充当日军耳目，多次带队搜捕抗日家属，严刑逼供地下党员，并参与杀害抗日村长和民兵，罪行累累。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6c315e526acf5688be33ab1eee2c6a0c', '薛子厚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪安邑县警备队副队长、伪运城保安队副队长、荣河县伪警察局局长、运城伪警察局局长', '1940-1945', '', '率警备队袭击抗日游击队，抓捕并刑讯抗日群众，参与日军“治安强化运动”。；充当日军耳目，指挥伪警察搜捕抗日分子，严刑拷打进步群众，并参与日军“清乡”行动，抢劫民财。；率部充当日军爪牙，多次参与‘扫荡’临猗、万泉一带，杀害抗日游击队员，并抢劫百姓财物。；效忠日军，指挥伪警察搜捕地下党员，破坏抗日组织，参与“清乡”行动，残害百姓。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
