REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fd63f4ed22d358a2a90ffc8e7a392435', '薛维藩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '临县伪警察局局长', '1941-1945', '', '负责临县日伪警察事务，搜捕抗日分子，破坏地下党组织，向日军提供情报。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('66f4a5c280815acc8e8258aae4d43407', '补英达赖', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、河北', '内蒙古、河北', '[]', '伪察哈尔盟公署参议、伪张家口市维持会会长、伪察哈尔盟副盟长、伪张家口市市长、伪察哈尔盟盟长、伪蒙疆政府参议、伪蒙古军副司令、伪蒙疆政府参议、伪蒙古军政府秘书长、伪蒙疆政府参议、伪蒙古军政府财政部长、伪蒙疆政府经济部长、伪蒙古联盟自治政府司法部长、伪蒙疆政府兴蒙委员会委员长、伪蒙疆政府副主席、伪蒙疆政府参议、伪蒙疆政府参议、苏尼特左旗伪旗长、伪蒙疆政府参议、锡林郭勒盟盟长、伪蒙疆政府司法厅长、伪蒙疆政府民政部长', '1936-1945', '', '在化德地区推行“蒙地奉上”政策，为日军征粮派夫，压榨当地牧民。；原察哈尔蒙古族上层，投日后任伪蒙古军副司令，在商都、化德一带组织伪军，配合日军进攻抗日根据地。；参与伪蒙疆政权活动，在乌兰察布地区为日军搜集情报，破坏抗日地下组织。；在察哈尔右翼前旗一带为日军效劳，参与建立伪旗公署，强迫当地民众“归顺”日伪，并协助日军围剿八路军游击队。；蒙古族上层，投靠日本，在包头及乌兰察布一带协助日军维持治安，参与镇压抗日活动。……（共涉及16个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('15ef219b10c051a8bcfd48cd785f8dd5', '袁全印', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '曲周县伪保安联队副队长', '1940-1940', '', '充当日军耳目，提供抗日武装情报，参与“清乡”行动，杀害多名抗日民兵和群众，后随日军投降。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8323526fca8158adb7e5b5c41b4968f9', '袁庆增', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北、辽宁', '河北、辽宁', '[]', '伪大连市市长、伪平泉县税务局局长、伪热河省协和会会长、伪热河省财政厅厅长', '1933-1945', '', '在承德地区组织协和会，宣传“日满亲善”，瓦解民众抗日意志，收集情报供日军使用。；强征各种苛捐杂税，为日军和伪政权筹集军费，逼死多名抗税百姓。；为日军搜刮民财，征收高额捐税，导致承德地区经济凋敝。；在任期间全面配合日本殖民统治，强制推行保甲制度，协助日军强征劳工，迫害沙河口地区中国居民。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('af224963fb455c99a96bee0aadf29f89', '袁庆濂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪满吉林省警务厅厅长、伪满安东省实业厅厅长、伪满本溪湖警察署署长、伪满洲国锦州省警务厅长、伪满营口商会会长、伪满营口市商会会长、伪满锦州省警务厅长', '1931-1945', '', '原吉林警察厅官员，投日后任伪省警务厅长，在龙潭区设立多个警察分所，残酷镇压抗日群众。；在东港地区强占土地，掠夺矿产和农产品，为日军提供战争物资。；直接指挥本溪地区伪警察，搜捕地下党员和抗联交通员，参与“集团部落”建设，迫害百姓。；充当日本经济侵略代理人，强制商户为日军提供物资，协助日伪掠夺营口港资源，迫害爱国商人。；在营口西市地区为日军筹集军饷，强迫商户捐献物资，向日伪当局举报抗日商人，协助经济统制。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('14adcfc6021c513888a19263f1acb12f', '袁文会', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北', '天津、河北', '[]', '伪冀东保安队头目、汉奸武装首领、伪天津青帮头目/汉奸特务、伪天津青帮头目、特务、伪昌黎县商会会长（汉奸商人）、天津青帮头目/汉奸、天津青帮头目、日伪特务外围组织头领', '1933-1945', '', '在天津东丽一带经营赌场烟馆，为日军搜集情报，参与迫害抗日群众，是地方恶霸型汉奸。；投靠日军，组织汉奸武装，为日军充当特务，绑架勒索抗日人士，控制码头和烟馆，为日军提供情报。；天津青帮头子，投靠日军，在天津开设赌场烟馆，协助日本宪兵队抓捕抗日分子，参与“治安维持会”。；在天津及滨海地区（塘沽、大沽）控制码头和烟馆，为日军充当爪牙，绑架、暗杀抗日人士。；在山海关、秦皇岛一带组织汉奸武装，协助日军维持治安，残害百姓……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('642735990800563ca60f2c3175df9282', '袁良', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、河北', '天津、河北', '[]', '伪冀东防共自治政府参议、伪天津市工务局局长', '1935-1943', '', '负责为日军修建军事设施和兵营，强征民工，破坏天津城市设施。；参与伪政权行政事务，在唐山地区协助日伪军扫荡。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a2f31a9be59d5a89b0426ae789e7bef9', '袁金铠', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、河北、辽宁', '吉林、河北、辽宁', '[]', '伪满参议府参议、伪满参议府参议、伪满尚书府大臣、伪满参议府议长、伪满参议府议长、伪满奉天省省长、伪满参议府议长、伪满奉天省省长（继任）、伪满参议府议长、伪满尚书府大臣、伪满参议府议长、奉天地方维持会会长、伪满参议府议长、汉奸、伪满参议府议长（原籍辽阳，活动于铁岭）、伪满参议府议长（吉林籍）、伪满参议府议长（曾任奉天省维持会会长）、伪满参议府议长（曾活动于辽西）、伪满参议府议长（曾活动于长春）、伪满参议府议长（曾涉阜新）、伪满参议府议长（辽宁籍）、伪满奉天省参议、伪满尚书府大臣、伪满奉天省省长、伪满奉天省省长、伪满参议府议长、伪满奉天省省长、伪满尚书府大臣、伪满奉天省省长、伪满锦州省高等法院院长、伪满奉天省省长（后任伪满尚书府大臣）、伪满奉天省省长（早期）、伪满奉天省省长（早期）、伪满参议府议长、伪满奉天省省长（曾辖阜新）、伪满洲国参议府参议、伪满洲国参议府参议、奉天地方维持会会长、伪满洲国参议府参议、奉天省伪省长、伪满洲国参议府参议（长春）、伪满洲国参议府议长、伪满洲国参议府议长、伪奉天省省长、伪满洲国参议府议长、伪锦州省参事、伪满洲国参议府议长（曾活动于长春）、伪满洲国参议府议长（辽宁籍，曾参与辽南政务）、伪满洲国尚书府大臣、伪满洲国尚书府大臣、奉天地方维持会会长、伪满洲国尚书府大臣、奉天省省长、伪满洲国尚书府大臣（吉林籍，活动于长春）、伪满洲国尚书府大臣（曾任吉林地区伪职）', '1931-1945', '', '原奉系官僚，在四平地区参与伪政权建设，协助日军推行“治安肃正”计划。；原奉系政客，投日后任伪满参议府议长，在吉林、四平一带鼓吹“日满亲善”，协助日军稳定殖民秩序。；原奉系官僚，投日后在伪满中枢任职，参与起草和推行奴化政策，活跃于长春政治圈。；虽主要任奉天职务，但多次在长春参与伪满中央政务，积极推动东北傀儡化；在伪满中央任职，参与起草诏书和礼仪制度，为傀儡政权服务。……（共涉及67个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7ad2992b4e32522880aa14559fb49a2b', '裴子明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪临晋县维持会副会长、绛县伪区公所区长（横水区）、荣河县伪保安团副团长', '1938-1945', '', '率伪军多次袭击抗日游击队，杀害抗日战士，并参与日军在汾河沿岸的封锁行动，阻断抗日物资运输。；为日军带路搜捕抗日家属，参与建立‘爱护村’，强迫村民报告八路军动向，并杀害两名抗日交通员。；在横水镇一带为日军强征壮丁和粮食，欺压百姓，并多次向日军报告抗日武装动向，致使游击队多次遭袭。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8c03960ff5a75b39895d4f9cc446e383', '裴昌会', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪山西省公署参事、伪河东道尹（运城地区）、晋南伪军顾问（投敌后）', '1941-1945', '', '原国民党军官，后投敌任晋南伪军顾问，参与策划对绛县、垣曲等地的‘扫荡’，为日军提供情报。；在太原伪省府任职，参与制定针对晋南地区的“治安强化”措施，协助日军清乡。；投敌后任伪河东道尹，管辖运城、临晋、猗氏等县，推行日伪“新民会”奴化教育，强征劳工送往东北和日本，并组织伪军配合日军“扫荡”中条山抗日武装。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b5cce75bad6f5096911e0e1add680e09', '解宝田', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '运城伪保安司令', '1939-1945', '', '统领运城伪军，配合日军对中条山抗日根据地多次‘清剿’，杀害抗日军民，烧毁村庄。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
