REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ae8bd48eee0359c0aaae313d5b588d6f', '许修直', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京', '北京', '[]', '伪北平市市长（末任）', '1944-1945', '', '抗战末期任伪北平市长，在丰台地区继续维持日伪秩序，直至日本投降。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
