REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8a7a45fe99d85e49834322508875f581', '谢介石', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪满洲国司法部大臣（长春）、伪满洲国驻日大使（曾任吉林伪官吏）、伪满洲国驻日大使（曾任吉林省交涉署长）、伪满洲国驻日大使（曾在长春任职）', '1932-1945', '', '早年投靠日本，在吉林地区参与对日交涉，后任伪满驻日大使，积极为日本侵华辩护。；在长春制定伪法律，镇压抗日活动，迫害爱国人士，维护日本殖民秩序。；在吉林任职期间协助日军稳定统治，后调任伪满外交系统，为日本服务。；原台湾籍官僚，投日后任伪满驻日大使，在长春和东京间活动，为日本侵略政策辩护。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6843669ab9e8509db0b4e583670887ae', '谢吕佐', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津', '天津', '[]', '伪静海县知事', '1938-1942', '', '在静海县任伪知事，为日军征粮、抓夫，建立伪乡村政权，镇压抗日游击队。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5f6d81998a9751eaa7c1fc2f15c493ec', '贡布扎布', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪乌审旗公署翻译官兼情报员、伪札萨克旗（今属伊金霍洛旗）保安队长', '1939-1945', '', '率伪保安队配合日军“扫荡”札萨克旗南部，抓捕并杀害抗日地下交通员。；为日军及伪蒙疆政府担任翻译，刺探中共伊克昭盟工委及陕北根据地的军事动向，多次引导日军袭击乌审旗边境的抗日武装。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('189448210b205b43bdb9d8f7dfc4159a', '贡楚克扎布', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪化德保安队队长', '1939-1945', '', '率保安队协助日军维持化德治安，抓捕抗日地下工作者。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0b5dc00f69d853ca9746c8bfb7d3305f', '贺秉温', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪包头警察局局长、伪归绥市公署市长（旧城区域）、伪归绥市市长、伪托克托县县长、伪集宁县知事（县长）', '1937-1945', '', '在集宁县城为日军征粮、征夫，推行奴化教育，镇压抗日活动。；在包头、东河地区充当日军鹰犬，搜捕抗日地下工作者，镇压民众反抗，参与“特别治安”行动。；投靠日军，任伪归绥（今呼和浩特）市长，推行日伪政令，强征劳工，搜刮民财。；投靠日军任伪县长，在托克托县推行日伪法令，强征苛捐杂税，出卖抗日分子，协助日军建立维持会。；任伪归绥市市长期间，管理旧城（玉泉区）行政事务，执行日伪“治安肃正”计划，强制居民领取“良民证”，并参与奴化宣传。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('08448280f4165cd383749b86036722e2', '贾世昌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪武乡县维持会会长、伪泽州宣抚班班长、伪长治县（今长治市辖区）维持会副会长、定襄县伪合作社社长、运城伪税务局局长', '1938-1945', '', '垄断粮食和食盐配给，克扣百姓口粮，将物资优先供应日军，并低价强购农民粮食。；随日军宣抚班活动，诱降抗日人员，破坏抗日统一战线，参与建立伪乡村政权。；为日军征收各种附加税，盘剥商户和农民，将大量税款上交日军，支持侵略战争。；日军占领武乡县城后任维持会长，为日军筹集粮款，强迫村民‘欢迎皇军’，并告密导致多名抗日村长被杀。；在长治、潞城一带为日军摊派捐税，强抓壮丁补充伪军，并参与屠杀抗日俘虏。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
