REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('545c158e54c85ee9989514ff928c66a0', '贾宣宗', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪太原县知事（太原县属今太原市晋源区一带）', '1938-1941', '', '在太原县推行日伪保甲制度，强征民夫修筑碉堡公路，为日军提供情报。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
