REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9ad08b4c2f645552953d925fcede69b0', '贾德润', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪云冈矿区矿警队长', '1940-1945', '', '任伪云冈矿区矿警队长，镇压矿工反抗，为日军掠夺煤炭资源，强迫矿工超时劳动，致多人死亡。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e345f27d716a5d1990819e80016498f3', '贾德胜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪沁水县自卫团团长、伪盐湖自卫团团长、伪运城税务局局长、伪高邑县特务队队长、阳泉伪税务局长', '1938-1945', '', '组织自卫团协助日军防守据点，参与围剿八路军游击队。；为日军征收各种苛捐杂税，强征田赋，导致民众负担沉重；组织自卫团为日军站岗放哨，参与清乡行动，烧毁村庄，抢夺粮食，杀害无辜百姓。；为日军征收苛捐杂税，盘剥商户，将所得款项用于伪军军饷，并克扣赈灾粮。；专门刺探八路军和游击队情报，多次带领特务队夜袭抗日村庄，逮捕并杀害抗日干部，罪行累累。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
