REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('261b7ca33db35e75b6c6bec87bed70f9', '贾文林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪石家庄地区剿共军司令', '1942-1945', '', '率伪剿共军驻石家庄，在平山、灵寿边界进行“清剿”，烧毁抗日村庄十余个。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f93f7b7b4d9f5cdf8284d8c9b5cf12d7', '贾文魁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '垣曲县伪区公所区长', '1939-1944', '', '在辖区强制推行“良民证”，抓捕抗日嫌疑人员，并配合日军“扫荡”，提供当地地形和人员情报。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('153310fe23185f0ca1018c325e83762c', '贾景德', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪华北政务委员会委员（山西代表）、伪华北政务委员会顾问（晋城籍）、伪华北政务委员会顾问（阳城籍）、伪山西省参议会议长、伪山西省政府参议（兼临汾地区特务）、伪山西省政府顾问（原阎锡山幕僚）、伪山西省政府顾问（长治籍）、伪山西省教育厅厅长、伪山西省财政厅厅长、伪山西省财政厅厅长（兼临汾办事处）、伪山西省财政厅厅长（管辖娄烦）、伪山西省财政厅长、伪曲沃县知事、伪长治地区警备司令', '1938-1945', '', '负责为日军搜刮临汾地区粮食和物资，强征苛捐杂税。；推行保甲制度，强征壮丁，为日军修建据点，镇压反抗。；原为地方士绅，投日后充当日军特务，在临汾、襄汾交界处建立情报网，多次引导日军突袭抗日游击队驻地。；虽名义为顾问，但实际参与伪省府对临汾、襄汾地区的“宣抚”工作，协助日军分化抗日力量，劝降地方武装。；作为山西籍汉奸代表，在北平伪政权中为日军服务，参与协调山西日伪事务。……（共涉及17个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
