REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6d14480f5bca547fa9137df86eeef232', '赵仲仁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪北票县县长、伪热河省建平县县长', '1933-1937', '', '投靠日军后任伪北票县长，强征民夫开采煤矿，为日军提供战争资源，镇压矿工反抗。；投靠日军后任建平县伪县长，强征民夫修建公路和碉堡，协助日军清乡。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('454376dfd63b51ceb233d45b1b5d7669', '赵会鹏', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪满双辽县县长', '1933-1945', '', '在双辽（今属四平）协助日军建立“治安维持会”，参与杀害抗联伤员。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('48059497bf3e51e88aa9813abb33d49a', '赵伯纯', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京', '北京', '[]', '伪冀东道公署参事', '1942-1945', '', '参与策划“治安强化运动”，为日军提供通州地区抗日武装情报。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('50614ecb554b5c44bbb0f628b799ea2d', '赵侗', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、山西、河北', '天津、山西、河北', '[]', '伪冀东保安队指挥官（活动于保定周边）、伪华北“剿共”军第一路司令、伪华北民众自治军司令（后抗日）、伪华北民众自治军总司令（后反正）、伪华北治安军总司令（曾在晋东南作战）、伪华北治安军第一集团军司令（驻石家庄）、伪华北绥靖军保定支队司令、伪华北绥靖军渤海支队司令、伪安国县县长、伪定县县长、伪石家庄特务机关长（日本特务机关华人助手）、华北自治联军司令', '1935-1945', '', '原抗日武装首领，一度被日军收编在河北活动，后反正抗日，但初期有投敌行为。；率伪治安军多次进剿高平、晋城抗日游击队，制造多起惨案。；原抗日武装叛变投日，在保定西部山区袭击八路军游击队。；原抗日武装首领，后叛变投日，在保定、唐县一带组建伪军，协助日军清剿抗日根据地。；投靠日军，任安国县伪县长，协助日军推行‘治安强化运动’，镇压抗日民众，征收苛捐杂税，抓捕抗日家属。……（共涉及12个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b08bb2d234815d01ac53f25a4d0e2177', '赵俊卿', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪河北省会警察署署长（驻石家庄）', '1939-1943', '', '指挥伪警察搜捕抗日地下工作者，破坏中共地下组织，实施白色恐怖。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
