REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5d3edf28522a543e9c4bac71d127cce4', '赵四喜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪左权县便衣特务', '1943-1943', '', '混入抗日群众集会，指认地下党员，导致5人被捕牺牲。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
