REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c2cfe725298253b890880b903ee8707d', '赵大胡子', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府保安队队长、古冶地区伪保长', '1935-1945', '', '为日军征粮派夫，协助抓捕抗日群众，多次向日军报告八路军活动情报。；在唐山路北一带协助日军清乡，抓捕抗日志士，镇压群众反抗。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('aae2ba480b10558f9d3fc16c6df77331', '赵子丰', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪兴隆县特务队长、伪冀东剿共军第一路司令（活动于唐山）、伪冀东防共自治政府唐山警察局长、伪宁河县知事、伪邢台县警察局局长', '1935-1945', '', '在唐山市区实施宵禁，镇压工人和学生抗日示威。；率伪军在玉田、遵化边界地区袭击八路军，烧毁村庄。；宁河（部分属路南）伪县长，控制蓟运河交通，盘查抗日物资。；充当日军特务，打入抗日组织内部，策反叛徒，导致兴隆地区多个地下联络站被破坏，数十名抗日人员牺牲。；效忠日军，指挥伪警察抓捕抗日志士，破坏地下党组织，参与“清乡”行动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('670555e204c055cd90041cdd7d49d5b5', '赵子厚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '临城县伪保安联队队长、伪交河县知事、伪南宫县警察所所长、伪尧山县（今隆尧部分）警备队大队长、伪清河县新民会会长、伪滦县县长（管辖今海港经开区部分区域）、伪邢台保安联队队长、伪邢台县保安联队队长、伪邢台县维持会会长、伪邢台道公署顾问、伪邯郸县维持会会长、伪邯郸县警察局局长、伪邱县警察所所长、南和县伪县长、成安县伪维持会会长、景县伪维持会会长、赞皇县伪区公所区长（第一区）、鸡泽县伪保安联队队长', '1937-1945', '', '在滦县及沿海地区强征粮税，配合日军“扫荡”，镇压当地抗日游击队。；在交河县（今泊头部分）为日军服务，强征壮丁，参与“铁壁合围”扫荡。；在赞皇第一区（城关一带）为日军征粮派夫，告密抗日积极分子，导致多名群众被捕。；日军占领景县初期，出任维持会长，为日军筹粮派款，组织伪政权，协助日军建立统治秩序。；率伪保安队多次袭击抗日根据地，杀害抗日干部和群众，参与“治安强化运动”，搜捕地下党员。……（共涉及19个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fb27aaf6884955bcb9a4bbbd0543cda2', '赵子安', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪邯郸县警察所所长', '1940-1940', '', '效忠日军，负责维持伪政权治安，搜捕抗日地下人员，严刑逼供，破坏地下组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
