REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('eec2c533207f505a9cee190adb48cd37', '赵子恒', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪石家庄警察局局长、景县伪维持会会长、深县（今深州市）伪维持会会长', '1938-1945', '', '管理伪警察，协助日军进行户口清查，抓捕地下党员。；日军占领景县初期任维持会长，为日军筹粮筹款，组织伪政权，强迫百姓领取“良民证”，告密抗日活动。；日军占领深县后出任维持会长，为日军筹粮派款，提供抗日武装活动情报，导致多处秘密联络点被破坏。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7861f29e570d5741be744e5a54a67c68', '赵子新', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府警务厅厅长、伪唐山地区清乡委员会主任、伪唐山粮食统制委员会主任、伪热河省承德县警务科科长', '1935-1945', '', '强征唐山地区粮食供应日军，导致百姓饥荒。；组织清乡队，在唐山、汉沽农村搜查八路军物资，逮捕抗日家属，实行“连坐”政策。；负责承德地区伪警察特务工作，抓捕抗日地下党员，破坏抗日组织。；在冀东地区协助日军维持治安，镇压抗日活动，参与组建伪警察体系。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e49109a962a75e0e938a15474b1ad695', '赵子明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北、辽宁', '山西、河北、辽宁', '[]', '伪内丘县知事（今属邢台）、伪满凌源县警察署长、伪满阜新地区保安队队长、伪长治县保安队副队长', '1934-1945', '', '参与多次“清乡”行动，烧毁村庄，掠夺财物，杀害抗日军民。；协助日军在内丘山区“扫荡”，烧毁村庄多处。；在凌源县任伪警察署长，协助日军搜捕抗日地下人员，参与“归屯并户”行动。；率保安队协助日军“清乡”，烧杀抢掠，镇压抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a5fbda2b4e6b55e48a2a568628bd3b8d', '赵子立', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府警务厅厅长', '1935-1938', '', '协助日军在冀东地区建立伪政权，镇压抗日活动，抓捕抗日志士。；在秦皇岛、海港一带协助日军镇压抗日活动，推行保甲制度，抓捕抗日志士。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('805dcb001bbe5f8782dcde83d247d210', '赵子谦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '井陉县伪警察局局长、伪井陉县知事、伪冀中区剿共军司令、伪平山县保安联队队长、伪新城县知事（县长）、伪晋城县教育科科长、伪正定县县长、伪正定县新民会会长、伪河东道尹公署顾问、伪石家庄商会会长、伪藁城县知事、伪行唐县保安联队队长、伪运城道尹公署警务科长、伪陵川县新民会会长、伪高各庄（今属唐山高地区）维持会会长、伪高邑县新民会会长、元氏县伪新民会会长、夏县维持会会长、晋南伪“剿共”司令、晋县伪警察所所长、晋县伪警察所长、栾城县伪保安联队队长、深泽县伪保安联队队长、灵寿县伪保安联队队长、石家庄伪商会会长、石家庄伪警察局局长、石家庄地区伪“剿共”自卫团团长、绛县伪新民会会长、藁城县伪警察所所长、行唐县伪保安联队队长、赵县伪维持会会长、运城伪警察局局长、运城（安邑）伪县长、闻喜县伪新民会会长', '1937-1945', '', '在陵川推行奴化教育，查禁抗日书刊，协助日军搜捕抗日学生。；推行奴化教育，强制学校使用日伪教材，宣传“中日亲善”，迫害拒绝任教的中国教师。；为日军出谋划策，参与策划清乡行动，迫害抗日家属；组织维持会为日军提供粮秣情报，强迫村民领取“良民证”，并告密导致多名抗日家属被捕。；效忠日军，指挥伪警抓捕抗日志士，严刑逼供，协助日军推行“治安强化运动”，残害百姓。……（共涉及38个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
