REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('961d2694d48e5ce6b837f663d7237c2a', '赵子青', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪临漳县维持会会长、伪冀南道保安司令部副司令、伪武安县警察局局长、伪邯郸县知事（兼管峰峰矿区行政）、伪邯郸县知事（继任）、伪邯郸县维持会会长、伪邯郸县警察局长', '1937-1945', '', '协助日军在邯郸、磁县、成安等地建立伪军据点，参与‘清乡’行动，掠夺物资。；日军占领临漳后率先组织维持会，为日军征粮派款，提供劳役，并出卖抗日积极分子。；协助日军搜捕抗日志士，破坏地下组织，实施白色恐怖。；推行保甲制度，强征民夫修筑炮楼，配合日军“清乡”，在峰峰地区强征粮食。；效忠日军，建立伪警察体系，抓捕抗日地下工作者，破坏抗日组织。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('613b305324ea5706a1ce5406bd618a72', '赵宗培', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京', '北京', '[]', '伪密云县警察局局长、伪顺义县保安队队长', '1940-1945', '', '在密云县城及周边地区搜捕抗日分子，破坏地下组织，向日军提供情报。；率伪保安队多次袭击顺义抗日游击队，杀害多名抗日战士，烧毁村庄。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b507e0af05415e5a9319eea3243e9a6b', '赵宝山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪磐石县协和会会长', '1935-1945', '', '组织汉奸宣传队，鼓吹“日满亲善”，搜集抗日情报提供给日军，并强迫百姓捐献物资支援伪军“讨伐”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c1ac24d6c49b585d8d0833be2396b223', '赵尊岳', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京', '北京', '[]', '伪华北政务委员会教育总署督办', '1940-1945', '', '在门头沟各学校推行日语教育和“中日亲善”宣传，毒化青少年思想。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('091187ee16085ccea2e4606033830c16', '赵广礼', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、河北', '吉林、河北', '[]', '伪满吉林宪兵队翻译官、兴隆县伪县长', '1933-1945', '', '在吉林、舒兰地区协助日军宪兵队审讯、拷打抗日军民，提供情报。；任伪兴隆县县长期间，积极推行日伪“治安肃正”政策，组织保甲制度，协助日军镇压抗日武装，强征劳工，掠夺资源。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4ea9ea8e448c5b6c81e9d15eefdba552', '赵廷珍', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪临榆县警察局长、伪冀东防共自治政府玉田县县长', '1935-1945', '', '在玉田（邻近唐山）为日军提供情报，协助围剿抗日游击队。；在海港区抓捕抗日志士，为日军提供情报，参与镇压码头工人罢工。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2afacc26d5e95d5f89e96f3404f7e387', '赵廷璧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北、辽宁', '山西、河北、辽宁', '[]', '伪冀东防共自治政府驻唐山办事处处长、伪大同省公署参事兼广灵县联络员、伪宁武县保安队队长、伪忻县维持会会长、伪忻县警察局局长、伪沁源县维持会会长、伪满洲国绥中县保安队队长、伪灵丘县警察所所长、伪秦皇岛维持会会长、伪长治县保安队大队长、伪高平县保安大队长、沁县伪县长', '1935-1945', '', '作为日伪大同省与广灵之间的联络人，参与策划“铁壁合围”扫荡，并协助日伪军建立保甲制度，实行连坐。；指挥伪警察搜捕抗日情报员，严刑逼供，杀害多名八路军侦察员，并协助日军建立“爱护村”保甲制度。；率伪保安队多次袭击抗日游击队，抓捕并杀害抗日干部及家属，参与日军‘三光’政策行动，烧毁村庄多处，并强迫青壮年加入伪军。；效忠日军，组织伪警察搜捕抗日地下人员，破坏抗日组织。；日军占领忻县后率先组织维持会，为日军筹集物资，提供情报，协助建立伪政权。……（共涉及12个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2cda19c09a3350328c36094e11f5c8f5', '赵廷英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪长治县知事、伪阳曲县知事（县长）', '1938-1940', '', '出任伪阳曲县知事，为日军征收粮款，组织伪自卫团，破坏抗日根据地。；投靠日军任伪长治县知事，组织维持会，协助日军清乡，残害抗日军民。；任伪长治县知事，推行保甲制度，建立伪乡村政权，协助日军抓捕抗日军民，征收苛捐杂税。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2e442b3625a45f949cb23fe50b228fe5', '赵廷选', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪承德地区保安队队长、伪热河省警务厅厅长、伪热河省警务厅特务科长', '1933-1945', '', '率伪军配合日军扫荡，屠杀承德周边村庄百姓，烧毁民房。；在承德地区推行日伪治安肃正，镇压抗日民众，协助日军建立保甲制度，抓捕抗日志士。；在承德地区（含鹰手营子矿区）组织特务网，抓捕抗日地下工作者，破坏抗日组织，多次参与“讨伐”行动，罪行累累。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('00da4cdb13e0505b807a77beedfc845f', '赵德元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪晋城县知事、伪晋城（晋城县）维持会会长、伪沁水县警备队副队长、伪高平县保安队队长、陵川县伪警察局长', '1938-1945', '', '参与多次清乡行动，烧毁村庄，抢劫物资，迫害抗日家属。；日军占领晋城后，出任维持会长，为日军筹粮派款，强拉壮丁，破坏抗日组织，后随日军撤退。；在晋城推行伪政权，协助日军建立保甲制度，强征壮丁，镇压抗日活动。；任伪警察局长，抓捕抗日地下工作者，刑讯逼供，破坏抗日组织，为日军提供情报。；率伪保安队多次袭击抗日游击队，抓捕并杀害抗日干部，烧毁村庄，民愤极大。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('49ab8856801950ea88b58d9b7f1cd9a5', '赵德全', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪复兴区（今邯郸市复兴区一带）维持会会长', '1939-1945', '', '在复兴地区组织维持会，为日军筹集粮饷，强迫村民‘自首’抗日分子，多次带领日军突袭抗日游击队驻地。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fa58d7b9f7345496b48453a011357c36', '赵德山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪永清县新民会会长', '1941-1945', '', '推行奴化教育，组织“新民会”宣传亲日思想，搜集抗日情报，协助日军进行经济封锁。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6287c6f9060c56a8996f474a62278a73', '赵德胜', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪吴桥县剿共自卫团团长、伪孟村区区长、伪峰峰煤矿把头（工头）、伪左权县保安队副队长、伪新乐县警察所所长、伪沁源县警备队分队长、伪沧县维持会会长、伪沧州警察局局长、伪泊镇警备队队长、伪泽州警备队副队长、伪海兴县新民会会长、伪渤海区盐警大队长、伪盐山县警察局局长、伪盐山（今属沧州）警备队大队长、伪阳泉煤矿株式会社翻译兼稽查、伪阳泉矿警队队长、伪青县新民会会长、伪香河县保安大队长、浮山县伪维持会会长、赵县伪维持会会长', '1937-1945', '', '日军占领浮山后率先投敌，组织维持会，为日军筹集粮饷，强征民夫修筑碉堡公路，并劝降抗日人员。；参与“扫荡”左权县麻田镇，杀害八路军伤病员及群众20余人。；协助日军在泽州地区建立伪警备体系，参与“清乡”行动，抓捕抗日分子，烧毁村庄。；参与“三光”政策，烧杀抢掠，无恶不作。；在阳泉煤矿为日军效力，镇压矿工反抗，克扣矿工口粮，并协助日军强征劳工送往东北或日本。……（共涉及21个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c4b5aac8377f51f28b388173b5000afc', '赵德胜（重复？不，另列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪香河县保安大队长', '1938-1943', '', '在香河县北部山区搜捕抗日武装，并强征民夫修建炮楼。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4316b904cbf55c85a865a154b7f60e1b', '赵德谦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津', '天津', '[]', '伪天津县知事（辖津南地区）、伪天津市警察局特务科科长、伪静海县警察所所长', '1938-1945', '', '专门侦缉抗日地下组织，逮捕并刑讯爱国志士，向日军提供情报，导致多人牺牲。；在津南推行伪保甲制度，强征苛捐杂税，向日军提供抗日武装活动情报。；指挥伪警察搜捕地下党员，破坏静海地区抗日联络站，参与刑讯逼供。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a58cb96088d85d5893faba30b3d9c994', '赵戴文', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪太原维持会会长（早期）、伪山西省保安司令部顾问、伪山西省公署顾问（名义）、伪山西省维持会会长（初期）、伪山西省维持会会长（早期）', '1937-1943', '', '太原沦陷初期参与组织维持会，为日军提供物资和情报，后因内部矛盾被日军弃用。；太原沦陷后参与组织维持会，为日军提供粮食和劳役，协助建立伪政权。；太原沦陷后一度出任伪维持会会长，为日军占领太原提供行政支持，后因内部矛盾被撤换。；太原沦陷后投敌，组织维持会，为日军征粮派款，协助建立伪政权，后因内部矛盾被撤换。；太原沦陷初期，曾参与组织维持会，为日军提供地方秩序管理支持，后因内部矛盾被撤换。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6d28fbfd66395db4b3f97f0d965b4462', '赵戴文（投敌争议，但据史料有附逆行为）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪山西省保安司令部顾问', '1938-1943', '', '虽曾为国民党元老，太原失守后接受伪职，为日军出谋划策，协助组建伪保安队。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
