REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6c5f9da480975727b0a8465fb96d549f', '赵文奎', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、河北', '内蒙古、河北', '[]', '伪沧州特务机关情报员、伪赤峰税务局局长', '1934-1945', '', '为日伪征收苛捐杂税，强征粮食、牲畜，导致百姓负担沉重，间接支持日军战争经济。；化装成商人沿运河搜集抗日情报，多次导致八路军交通站被破坏，并诱捕抗日干部。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
