REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0e3cb744f8ba581bb4073554347ef113', '赵明远', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪宽甸县警察署署长、伪满锦州省教育局长、伪满鞍山宪兵队翻译官', '1933-1945', '', '长期担任宽甸警察头目，直接指挥“讨伐队”，多次袭击抗联密营，杀害抗日群众。；在锦州、凌海学校推行日语教育和“王道乐土”宣传，篡改历史，毒化青少年思想。；鞍山人，精通日语，任日军宪兵队翻译，参与审讯和刑讯抗日人士，直接导致多名地下党员牺牲。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0a245e20ab6953689d2e7d823ddbe9b6', '赵明远（重复？）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满鞍山宪兵队翻译官', '1935-1945', '', '已列，补充其曾诱捕地下党。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ba734f891f3554b5a6c02f562508e225', '赵星三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪邯郸县保安联队队长', '1938-1945', '', '统领伪保安武装，多次配合日军在丛台及周边村庄进行“扫荡”，抓捕抗日干部，抢劫民财，并参与修筑封锁沟和碉堡。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b4ca8ec56bbf58a48d9ffd649d755223', '赵星五', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀南道公署顾问、永年县伪保安联队队长', '1938-1945', '', '为日军出谋划策，参与建立伪警察所和特务组织，破坏地下抗日组织。；组织伪保安队，配合日军扫荡抗日根据地，杀害抗日干部和群众，制造多起惨案。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('03b3ecf4f2f750d49a27d274d2bc8839', '赵晋三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '临汾县伪警察局局长、伪安泽县保安队队长、伪安泽县维持会会长、伪晋城县教育科长、伪河津县财政科科长', '1938-1945', '', '日军初占安泽时，率先组织维持会，为日军筹集粮款，并劝诱乡绅投敌，破坏抗日统一战线。；任伪安泽县保安队队长，率伪军多次“清乡”，在安泽山区搜捕抗日军民，杀害多名八路军伤员和村干部。；主持伪警察局，协助日军进行“治安强化运动”，搜捕抗日军民，实施“连坐”制度，残害无辜百姓。；强制学校改用日伪教材，强迫学生参加日军庆典，检举抗日教师。；为日军征收苛捐杂税，贪污抗日物资，逼迫农民交出粮食支援日军。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
