REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('469663dcf9c45273982bd02b6777f23f', '赵玉昆', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪保定保安队队长、伪保定道尹公署顾问、伪保定道尹公署顾问、伪清苑县维持会会长、伪冀东保安队司令、伪保定道尹、伪冀中保安队司令、伪冀中剿共军司令、伪冀中剿共军第一师师长、伪冀中剿共军第一路司令、伪华北治安军独立团长（活动于雄县一带）、伪华北治安军第18团团长、伪华北治安军第1集团军司令、伪华北治安军第20团团长（原冀中军区第6军分区司令员，后叛变）、伪华北自治联军保定地区司令、伪安新县保安联队队长、伪定兴县警备队大队长、伪定县警备队队长、伪徐水县自卫团团长、伪易县保安联队队长、伪华北治安军第20团团长、伪易县警备队大队长、伪曲阳县保安联队队长、伪河北省保安队司令、伪保定道尹、伪涞水县保安联队队长、伪涞源县保安联队队长、伪华北治安军第3集团军第6团团长、伪满城县保安联队队长、伪满城县保安联队队长、伪满城县政府顾问、伪蠡县警备队队长、伪阜平县保安联队队长、伪阜平县政府顾问、伪雄县自卫团团长', '1937-1945', '', '原为八路军冀中军区第10军分区司令员，1939年叛变投敌，在保定地区组建伪军，多次配合日军扫荡白沟新城及周边抗日根据地，杀害抗日军民数百人。；原为土匪，后投靠日军，任保定伪保安队队长，协助日军扫荡抗日根据地，残害抗日军民。；原为地方武装头目，投日后任伪军司令，在保定高阳一带协助日军扫荡，残害抗日军民。；原为土匪，后投日，在安新、容城一带袭击县区游击队，杀害多名抗日烈士。；原为抗日武装首领，后投敌叛变，任伪安新县保安联队队长，多次率部袭击抗日根据地，捕杀抗日干部和群众，制造多起惨案。……（共涉及31个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
