REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e35e1c019e055ef28d200c0e185a058f', '赵甲荣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪古交维持会会长、伪太原县知事/伪晋中道尹、伪太原市市长', '1938-1945', '', '任伪太原市市长期间，推行日伪市政管理，强征劳工，为日军提供物资。；在古交地区（今太原古交市）组织维持会，为日军提供粮食和民夫，告密抗日游击队行踪，导致多名地下党员被捕牺牲。；在太原及晋中地区推行日伪法令，强征民夫修筑工事，为日军提供物资。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fd1b73ce53cc56f7a10e0c032e192535', '赵登科', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪下花园警察署署长、伪平泉县保安队队长、伪张家口商会会长、伪张家口特别市警察局局长、伪怀安县警察局局长、伪怀来县新民会会长、伪涿鹿县警察局局长、伪热河省滦平县警察署署长', '1935-1945', '', '负责张家口城区治安，多次组织抓捕地下抗日分子，破坏中共地下组织。；效忠日军，指挥伪警察在下花园地区设卡盘查，破坏地下抗日组织，参与“治安强化运动”。；指挥伪警察抓捕抗日地下党员，破坏抗日组织，参与“清乡”行动。；推行奴化宣传，组织“新民会”胁迫群众参加反共集会，为日军收集抗日情报。；指挥伪警察抓捕抗日地下党员，破坏抗日组织，严刑拷打群众。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
