REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('60d0b41e134b5ab0b4b6980521fec99b', '赵锡三', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪东光县警察所所长、伪南皮县新民会会长、伪大名县维持会会长、伪沧县知事（沧州）、伪沧县（含今海兴部分区域）警备大队长、伪沧州道尹公署顾问（献县籍）、伪黄骅县警察所所长、内丘县伪警备队大队长、宁晋县伪警察所长、衡水县伪保安大队大队长、衡水县伪警察局局长', '1937-1945', '', '指挥伪警察抓捕地下党员，严刑逼供，破坏抗日组织。；负责在南皮推行奴化教育，组织“新民会”宣传“中日亲善”，强迫群众悬挂日伪旗，并密报抗日积极分子名单给日军宪兵队。；任伪沧县知事期间，推行保甲制度，强征壮丁，配合日军清乡，破坏中共地下组织。；在沧县东部及海兴一带设卡盘查，截断抗日物资运输，参与制造“旧城惨案”，残害抗日群众。；为日军出谋划策，参与“治安强化运动”，在献县推行奴化教育，强迫民众“归顺”。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a40ba5601ad25ab1b1616a9e7ec8e7c0', '赵锡九', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪涞源县新民会会长、伪深县（今深州市）保安大队副大队长、冀南道伪公署参议（衡水一带）、安平县伪警察所所长、枣强县伪新民会会长、衡水伪商会会长、衡水县伪县长（兼辖阜城一带）、馆陶县伪自卫团总团长', '1938-1945', '', '为日军推行奴化教育，组织“新民会”宣传“中日亲善”，诱骗青年参加伪军，搜集抗日情报，破坏群众抗日组织。；任伪警察所长，协助日军搜捕抗日分子，破坏地下交通站，参与“清乡”行动。；宣传奴化思想，组织‘新民会’活动，诱骗青年参加伪军，破坏抗日统一战线。；参与伪冀南道政务，为日军提供地方情报，协助推行保甲制度，压迫百姓。；协助日军在深县实施“治安强化运动”，组织伪军袭击抗日游击队，杀害抗日军属，并参与掠夺当地粮食资源。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('aa0c8ac73f1156599f0925edb288e06a', '赵锡田', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪丰润县保安联队长、伪兴隆县县长、伪冀东防共自治政府保安队队长、伪华北政务委员会沧州办事处主任、伪卢龙县知事、伪唐山特别市市长（日占时期）、伪安次县新民会会长、伪廊坊地区维持会会长、伪廊坊地区警备司令、伪廊坊特别区公署署长、伪文安县警察局局长、伪沧州保安司令、伪献县新民会会长、伪青龙县县长、冀县伪维持会会长', '1933-1945', '', '在唐山市区为日军服务，管理伪市政，强制推行经济统制，掠夺唐山煤炭等资源，镇压工人罢工和抗日地下活动。；在丰润路南地区烧毁村庄，抢掠百姓，配合日军“剔抉”战术。；负责廊坊及周边地区治安，镇压抗日活动，多次率伪军袭击抗日武装，杀害抗日人员。；日军占领廊坊后出任维持会会长，为日军筹集物资，提供情报，协助建立伪政权，后调任伪河北省参事。；推行奴化教育，组织“新民会”宣传“中日亲善”，诱骗青年参加伪军，并举报抗日积极分子。……（共涉及17个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e15e77a36ce05b81af45f0e63a2a526e', '赵锡章', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪沧州维持会会长、伪河间县警备大队长、伪深县（今深州市）知事、深县伪维持会会长', '1937-1945', '', '日军占领沧州后出任维持会长，为日军筹粮筹款，强迫商户‘献金’，协助建立伪政权。；充当日军爪牙，负责河间县城及周边据点防务，参与‘清乡’行动，杀害抗日家属，强征民夫修筑炮楼。；日军占领深县后率先组织维持会，为日军筹粮筹款，强迫民众欢迎日军，协助建立伪政权。；任伪深县知事，协助日军建立伪政权，多次带路“清乡”，残害抗日军属。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
