REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('19e984de1b5450e698cb26691a29a327', '那木海扎布', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪科尔沁左翼后旗旗长', '1938-1945', '', '积极执行日本“开拓团”移民政策，强占牧民草场，组织伪旗公署武装配合日军“讨伐”，杀害抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2b916287eb355472aa494ce7ca93f994', '那森德勒格尔', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪商都县县长（化德邻近地区）、伪蒙疆政府驻乌兰察布办事处主任', '1938-1945', '', '在乌兰察布东部地区配合日军“扫荡”，搜刮民财，迫害抗日群众。；负责协调日伪军与地方汉奸势力，在察哈尔右翼前旗推行“以华制华”政策，组织汉奸武装“自卫团”袭扰抗日根据地。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2884a5b2437357d1ba101dd6841dde4f', '邵尚俭', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪庄河县县长、伪满洲国大连地区宪兵队队长、伪甘井子区区长（具体任期不详）、伪长海县县长', '1932-1945', '', '在庄河地区任伪县长，协助日军清乡，镇压庄河抗日义勇军和民众反抗。；辽宁大连甘井子人，在日本殖民统治下任甘井子区长，协助日本推行保甲制度，强征劳工，镇压当地反抗。；辽宁大连人，曾任伪大连宪兵队队长，残酷镇压西岗区及周边抗日地下组织。；在长海县（今属大连）推行日伪统治，强征渔民劳役，镇压渔民反抗。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('823b8dad3f7f5dd7b1c5516a2d466f3d', '邵尚勤', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪中山区区长、伪满洲国复县（今普兰店）县长、伪满洲国大连宪兵队翻译官', '1932-1945', '', '大连汉奸，任宪兵队翻译，参与审讯和迫害抗日地下工作者，罪行累累。；在大连中山区推行保甲制度，协助日军清查抗日分子，强征劳工。；辽宁复县人，投日后任伪复县县长，强征粮税，配合日军“讨伐”抗日游击队。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('db68b41f435058b1af39b05829f9fb19', '邵本良', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满东边道“讨伐”司令', '1933-1938', '', '原东北军军官，投敌后长期在抚顺、新宾、通化一带追击杨靖宇抗联部队，多次设伏偷袭，是抗联在辽东最凶恶的敌人之一。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d11a631644dd547b9c229fb734e07274', '邵鸿基', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪衡水县长', '1939-1943', '', '任伪县长期间，推行保甲制度，强征粮款，抓捕抗日人员，破坏地下组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('1e54aa620f8857b2bbddf71bf2d6391c', '邹泉荪', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪北平市社会局局长、伪华北政务委员会实业总署督办、伪华北经济总署督办', '1938-1945', '', '在北平主管伪实业部门，推动华北资源对日输出，参与对东城工商业的统制。；在北平主管实业，控制昌平矿产和农产品，为日军提供战略物资。；推行日伪社会政策，镇压民众反抗。；在廊坊地区推行“经济封锁”，禁止粮食、药品流入抗日根据地。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bb4057c620ce5f25bad8ae853cc1abcb', '邹泉荪（重复？不，另列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪华北经济总署督办', '1941-1945', '', '在廊坊地区推行“经济封锁”，禁止粮食、药品流入抗日根据地。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c7279ab268675a569f28de54785ae734', '郑国栋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪青龙县教育科督学', '1936-1945', '', '推行日语教育和奴化课程，强迫学校悬挂日本国旗，检举有抗日思想的教师和学生，破坏当地教育体系。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('013c82db459e55769cfebd7525d6ccb7', '郑孝胥', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪满国务总理大臣、伪满国务总理大臣（长春，前期）、伪满洲国国务总理大臣、伪满洲国国务总理大臣（首任）、伪满洲国国务总理大臣（首任，在长春活动）、伪满洲国国务总理大臣（首任，活动于长春）', '1931-1935', '', '原清朝遗老，伪满首任总理，在四平、吉林等地推行奴化教育，协助日本殖民统治。；在长春主持伪满初期国务，签订卖国条约，承认日本在东北的特权。；在长春主持伪满政府，协助溥仪登基，推行奴化政策。；在长春（新京）任伪满首任总理，签订卖国条约，协助日本建立殖民统治体系。；原清朝遗臣，投日后任伪满首任国务总理，在长春签署多项卖国条约，协助日本建立伪满政权。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8016740ed41c5e2091c997bae7a87402', '郑永福', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪满辽源县自卫团团长', '1937-1945', '', '在辽源县（今双辽市）组织自卫团，为日军提供劳力和情报，参与破坏抗联地下交通线，曾率团袭击抗联小分队，抢掠群众财物，并强征青年充当伪军。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c55257f2171f51068635927ef807dd2a', '郑海楼', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪河间县新民会顾问', '1939-1945', '', '在河间运河支流地区推行“中日亲善”宣传，组织汉奸青年团，破坏抗日小学，强迫儿童学日语。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('63f07b3396c152cd94c6e025472fcd2e', '郑禹', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满奉天市市长、伪满奉天市市长（沈阳）、伪满洲国奉天市市长', '1937-1945', '', '继任伪奉天市长，积极执行日本“满洲国”政策，奴役市民。；伪满总理郑孝胥之子，任伪奉天市长，协助日军搜刮战略物资，强征劳工。；伪满末期沈阳市长，协助日军实行“战时体制”，强征金属、粮食，镇压地下抗日活动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5ce1c02ef79359899d18ca6eb9d942cd', '郑维屏', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪卢龙县自卫团团长', '1942-1942', '', '组织地主武装自卫团，配合日军封锁山区，盘查过往行人，多次伏击八路军运输队，杀害掉队伤员。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0406d7559c4d59678de863e31fb2d04c', '郑荫人', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪安新县财政科长', '1939-1944', '', '为日军强征苛捐杂税，侵吞抗日物资，逼死多名抗属。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
