REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('16862e93677853ef9466c51633c23461', '郝梦龄（非抗日将领，同名汉奸）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪石家庄地区“剿共”司令', '1942-1945', '', '在石家庄东部地区组织伪军“剿共”队，专门搜捕八路军交通员。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('693df945d40654dfa00299fbacb50c58', '郝步青', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪太原绥靖公署参议（古交籍）、伪山西新民会总务部长、伪晋中道尹（伪冀宁道）、伪晋中道尹（榆次属晋中道）、伪祁县新民会会长', '1938-1945', '', '充当日军间谍，搜集古交山区抗日武装情报，导致多次袭击失败。；负责在太原及周边推行奴化教育，组织新民会活动，宣传“中日亲善”，破坏抗日民众组织。；任伪晋中道尹期间，管辖榆次等县，推行“治安强化运动”，强征劳工，协助日军建立情报网。；管辖榆次等晋中各县，推行日军“治安强化”运动，组织伪自卫团，配合日军扫荡抗日根据地。；推行奴化教育，宣传“中日亲善”，强迫民众参加反共集会，告发抗日家属。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('65b73a139ec85aa8978aedaf6a6787c3', '郝永昌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪襄垣县警备队副队长', '1941-1945', '', '率警备队参与日军“铁壁合围”扫荡，烧毁村庄，抢劫财物，杀害抗日军属。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('26f91554f5d75fd4ab63fd50c1ced47e', '郝耀庭', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪太原县知事（辖万柏林部分地区）、伪昔阳县维持会会长、伪晋中剿共自卫团团长、忻县伪区公所区长（奇村一带）', '1938-1945', '', '推行保甲制度，强迫村民领取“良民证”，为日军提供情报，参与屠杀抗日家属。；在日伪统治下，强征壮丁，催缴粮款，告密抗日活动，导致多名村民被日军杀害。；组建自卫团，在平遥、祁县交界处设卡盘查，多次伏击抗日运输队，将抓获的抗日人员押送日军太原工程队。；日军占领昔阳后出任维持会长，为日军筹集粮款，强征劳役，并告密导致多名抗日群众被捕。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('da83ec643f5f58cbb27980c961a09672', '郝老连', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '内丘县伪维持会会长', '1937-1940', '', '日军占领内丘后率先组织维持会，为日军筹粮派款，强迫百姓‘欢迎皇军’，破坏抗日组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c29a77462258517197a08c5c51019c50', '郝贵堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪尖草坪保安队队长', '1942-1942', '', '组建伪保安队，配合日军扫荡，在尖草坪一带抓捕抗日军民，抢夺财物。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('58966c334b6350e9906938b4e1e222b2', '郝鹏举', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、山西、河北', '天津、山西、河北', '[]', '伪“淮海省”省长（早年活动于邢台）、伪华北治安军第2集团军司令（涉忻州）、伪淮海省省长（原在河北活动）、伪淮海省省长（曾驻冀东）、伪淮海省省长（曾驻华北）、伪第一方面军总司令（1944年调驻邯郸附近）', '1938-1945', '', '原国民党军官，投日后曾在华北（含河北）任职，后调任淮海，在河北期间参与反共活动。；所部在忻州、岢岚一带驻防，参与“铁壁合围”战术，围剿八路军晋绥军区部队。；早年曾在冀东伪军任职，后调任他处，但早期在唐山地区有助敌行为。；在华北任职期间，曾到廊坊地区视察伪军防务，推动“反共”措施。；曾任伪冀南道参事，在邢台推行奴化教育，搜集抗日情报。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('97f5bfd84d2d5f5c821736dd326b14b1', '郝鹏举（注：主要在山西活动，后投汪伪，但非太原小店本地）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪淮海省省长（后）', '1941-1945', '', '曾任阎锡山部军官，后投靠日军，在山西参与清乡，后转投汪伪政权。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('51f7cbc9b24f5f7f91797a264a85aeed', '郝鹏举（注：此人为伪淮海省省长，不涉及山西，不列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '', '', '', '', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
