REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f713b495ff1c51a89f0c1c9fa379e895', '郭世昌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '吕梁地区伪军独立营营长、壶关县伪区公所区长（驻树掌镇）', '1942-1945', '', '率伪军驻守交城至离石公路沿线，袭击抗日运输队，抢劫物资，杀害护送人员。；在日军占领区设立伪区公所，摊派苛捐杂税，强抓壮丁，为日军提供粮食和劳役，迫害抗日家属。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('66668044bdf65149a9f1ccfd17fabcaf', '郭世英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪偏关县维持会副会长', '1938-1939', '', '日军首次占领偏关时主动投靠，协助日军建立维持会，为日军提供当地抗日武装活动情报，导致多名游击队员被捕牺牲。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bacfbb3e0b29576fa99026b1dc526ad3', '郭光堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪包头教育督学', '1942-1945', '', '推行奴化教育，强制学校教授日语，删除中国历史内容，迫害爱国教师。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2a6166ea48d15ae9bcb55e7da428745f', '郭光汉', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪归绥县知事、伪托克托县警察署署长', '1938-1945', '', '任伪归绥县知事期间，强征民夫、粮食供日军使用，推行保甲制度，迫害抗日家属。；在托克托县任伪警察署长，抓捕抗日地下工作者，严刑逼供，并参与日军对农村的扫荡。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5313b07789c9588f8f61d38302ff1dd7', '郭全保', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪沁水县便衣队队长、沁县伪区公所区长（城关区）', '1941-1945', '', '带领便衣队暗杀抗日积极分子，破坏地下交通线。；在城关区为日军征夫派差，强征民粮，并参与诱降抗日游击队员。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('25b3d62c3e0655e6b96a19da1ecaec52', '郭全忠', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪泽州警察局局长', '1940-1944', '', '任伪警察局长期间，大肆搜捕抗日地下工作者，严刑逼供，破坏抗日组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d3fa4075cb105ad4ae1633cb73ba5421', '郭凤山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '五寨县伪维持会会长、定襄县伪维持会会长、浮山县伪税务局局长、繁峙县伪区公所区长（砂河镇）', '1937-1945', '', '为日军征收各种苛捐杂税，强抢民间粮食和物资，导致浮山百姓生活极度困难。；日军占领五寨后出任维持会长，为日军征派民夫、物资，欺压百姓。；日军占领定襄后率先组织维持会，为日军筹粮派款，提供情报，帮助日军建立伪政权。；在砂河镇为日军征粮派款，告密杀害抗日交通员，协助日军建立据点。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('444bd58aeba4574ab1f946b71e84282f', '郭化民', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪邯郸县特务队队长', '1940-1945', '', '率特务队专门刺探八路军情报，抓捕抗日积极分子，在邯郸城内实施白色恐怖，严刑拷打被捕人员。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c1b1c603b33255eb89e6a49f50326e0a', '郭占元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪临汾道公署参事（兼管安泽事务）', '1939-1943', '', '作为伪临汾道官员，参与策划对安泽抗日根据地的经济封锁，并协助日军建立情报网。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ae5556612a955d3bbb0ec62284038da2', '郭占鳌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪大同县保安团团长、伪盐湖税务所所长、运城伪河东道尹公署顾问', '1938-1945', '', '率伪保安团驻守新荣一带，参与“清乡”行动，杀害抗日军属，抢劫民财，强抓民夫，罪行累累。；为日军征收各种苛捐杂税，盘剥百姓，私吞税款，并协助日军控制盐湖盐业资源。；作为日军顾问参与运城地区伪政权决策，协助日军推行‘以华制华’政策，在绛县、安邑等县督导征粮和劳役，民愤极大。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
