REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('33cd71fd76775d74b6d045885ac62fc5', '郭培兰', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪长治县维持会会长', '1938-1940', '', '日军占领长治后率先组织维持会，为日军提供情报，强征民夫修路筑堡，并强迫商户‘捐献’物资，民愤极大。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ed043f824f5853409ef116be4f8ae061', '郭子俊', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '岢岚县伪警察所所长', '1941-1945', '', '在日军占领期间任伪警察所长，负责清查抗日分子，多次带队突袭村庄，搜捕地下党员，并勒索百姓财物。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('068a2fb66df658e086387e0c265ca6bc', '郭子明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '临汾伪商会会长、伪山西剿共军第二师师长（驻长治地区）、伪忻县新民会会长、伪邱县财政科科长、伪长治县警备大队副大队长（活动于屯留一带）、伪阳泉区公署顾问、伪阳泉县财政科科长、闻喜县伪区公所区长（第三区）', '1939-1945', '', '为日军统制临汾及乡宁物资，垄断粮食、棉花贸易，向抗日根据地走私毒品，破坏抗日经济。；推行奴化教育，宣传“中日亲善”，诱骗青年参加伪军，破坏抗日宣传。；在辖区推行保甲制度，强派捐税，向日军报告抗日武装动向，导致多次袭击失败。；率伪军驻防屯留边境，多次参与‘清乡’行动，抢劫百姓财物，并协助日军建立情报网。；率伪剿共军驻防长治、武乡一线，多次参与对太行根据地的进攻，在武乡蟠龙镇一带制造多起惨案。……（共涉及8个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0ddb00faaf79530da6011753a2589a9b', '郭守信', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '忻县伪保安联队副队长、文水县伪区公所区长（一区）', '1939-1945', '', '在文水一区为日军征粮派夫，协助日军建立“维持会”，镇压当地抗日活动。；率伪军多次进攻忻口、奇村等抗日根据地，烧杀抢掠，参与制造多起惨案。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('36291946c2a055ef95a843efb1461a1b', '郭宗汾', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪临汾地区宣抚班班长、伪临汾绥靖公署参议、伪太原绥靖公署参议、伪山西保安副司令（驻临汾）、伪山西剿共军第1师师长、伪晋城县维持会副会长', '1938-1945', '', '投日后任伪山西保安副司令，在临汾地区扩充伪军，配合日军“扫荡”，杀害抗日军民。；为日军出谋划策，参与策划对临汾抗日武装的围剿，并劝降部分国民党游击队。；率伪军驻防吉县一带，参与日军“铁滚扫荡”，烧毁村庄，掠夺物资，杀害抗日群众。；负责在临汾、隰县农村进行“宣抚”活动，诱骗民众领取“良民证”，并告发抗日分子，导致多人被捕。；率伪军在霍州、洪洞一带与日军协同作战，袭击八路军游击队。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('dfdbd57fc3f1531e8cc960507c5d03cf', '郭宝山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪满西安县“讨伐队”队长', '1940-1945', '', '在西安县（今辽源市）率“讨伐队”多次进山搜剿抗联残部，曾于1941年在东辽河沿岸伏击抗联小分队，杀害抗联战士5人，并割下首级向日军邀功。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('134a468110c453179cacdb43defe2378', '郭尔卓尔扎布', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪蒙古军师长', '1937-1945', '', '率伪军驻呼和浩特周边，协助日军清乡，杀害抗日群众。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d23b605c327f5958a1ce4e4e8443ceb1', '郭廷相', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪大同省警务厅特务科科长', '1941-1945', '', '负责大同、左云地区特务工作，建立情报网，破坏抗日组织，亲自审讯并酷刑折磨被捕的抗日志士。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6b4a1d5f5396534281549e81177d8216', '郭怀义', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪屯留县税务局长', '1939-1944', '', '为日军征收苛捐杂税，强征田赋，逼死多名农民，资助日军军费。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('24c16892eb3e52b694bd59cfe62e1662', '郭怀仁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪保德县新民会主任', '1941-1944', '', '推行奴化教育，组织“新民会”宣传“中日亲善”，强迫青年参加伪军训练，并协助日军清乡。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
