REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5e07c4ed1fc75823aa9f6bfb5f953ed4', '郭振山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪潞州区（原长治县）维持会副会长、伪长治县新民会会长', '1938-1944', '', '协助日军建立伪政权，负责摊派粮款，欺压百姓，曾向日军告密导致抗日村长被杀。；宣传“中日亲善”，组织奴化教育，强迫青年参加伪军训练，破坏抗日宣传。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5225860aaf12514ca4cc14c7697b93ca', '郭振海', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '隆平县伪警备队中队长', '1942-1945', '', '率伪军参与多次扫荡，在隆尧一带杀害抗日战士，抢夺物资，民愤极大。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2fae5c65dd395f52a2183aabf63f814d', '郭文林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪兴安军第10团团长（后反正）、伪兴安军第1师师长、伪兴安军第2师师长、伪满洲国兴安军第9团团长', '1938-1945', '', '率伪军在兴安盟、乌兰浩特一带执行“讨伐”任务，制造多起惨案，强征民夫修筑军事工事。；曾任伪兴安军军官，初期效忠日伪，参与镇压抗日武装，1944年率部起义反正，但此前有助纣为虐行为。；驻守呼伦贝尔地区，参与日军对苏作战准备，镇压当地抗日力量；呼伦贝尔籍达斡尔族军官，率伪兴安军驻防额尔古纳地区，参与对苏边境侦察及镇压当地抗联小分队，后于1945年反正。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8988d5f913ca5e618b9be05a96f60316', '郭文通', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪满洲国莫力达瓦旗公署财务科长', '1935-1945', '', '负责为日伪政权征收苛捐杂税，强征劳工，导致当地民众负担沉重。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('706f573e84a55602b5524be304cca94e', '郭映淮', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '岚县伪区公所区长、静乐县伪教育科长', '1941-1945', '', '在岚县东村一带设立伪区公所，为日军征收粮款，告密抗日活动，导致多名群众被捕。；强制推行日伪教材，删除中国历史内容，强迫学校悬挂日本国旗，并检举有爱国言论的教师，导致多名教师被捕。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bc49968f9ce0546fa6660e98ad4ad066', '郭景汾', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '晋城（泽州）伪县长', '1939-1943', '', '任晋城日伪县长，推行奴化教育，强征劳工，协助日军建立碉堡封锁线，迫害抗日家属。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c73fd813480653559ada941382fd4b24', '郭步云', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪天镇县保安团团长、伪怀仁县警备大队长、伪昔阳县警备队副队长', '1939-1945', '', '组织地方伪保安团，配合日军“扫荡”天镇南山抗日游击队，杀害多名抗日群众，烧毁村庄。；率警备队配合日军‘铁壁合围’，在昔阳东部山区烧毁村庄，抢掠物资，杀害抗日军属。；投靠日军，任怀仁县警备大队长，参与“扫荡”朔州西部抗日根据地，杀害多名游击队员。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('22fde5e66c0a54c4bf7b7c6c958c419d', '郭步青', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪平定县知事（县长）', '1938-1940', '', '在阳泉（原平定县辖区）任伪知事期间，为日军征粮派款，组织伪警察队，破坏抗日地下组织，抓捕抗日军民。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('05b30d336bd85287a3148c07f0f2bd34', '郭殿臣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪大同警察局局长', '1938-1945', '', '任伪大同警察局局长，指挥伪警抓捕抗日地下党员，严刑逼供，破坏中共平城地下交通站。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c519ae0e253d5f0a8970efc34285a045', '郭殿邦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪大同矿区警察署署长、伪襄垣县知事', '1938-1945', '', '管理大同煤矿矿区，残酷压榨矿工，迫害反抗劳工，为日军掠夺煤炭资源提供武力保障。；投敌后任伪襄垣县知事，出卖抗日情报，导致多名地下党员被捕牺牲。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b2cb3b9447ff5e6fb64795a71c198872', '郭永清', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪垣曲县合作社理事长、伪平顺县警察所所长、伪神池县翻译官、伪黎城县警备队副队长、方山县伪教育督学', '1939-1945', '', '推行日伪奴化教育，强迫学校使用伪满教材，禁止讲授中国历史，迫害爱国教师。；为日军充当翻译，参与审讯抗日志士，歪曲口供，助纣为虐，并勒索百姓钱财。；垄断食盐、布匹等物资配给，克扣百姓配额，高价转卖，并利用合作社为日军收集战略物资。；带领伪警察搜捕抗日分子，严刑拷打被捕人员，并参与日军“清乡”行动，杀害多名抗日群众。；参与多次“扫荡”，在黎城北部烧毁村庄，抢劫民财。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('717335c4dfa55523a2ab8c89e46c6892', '郭永禄', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪长治县警备队大队长（活动于平顺边境）', '1941-1945', '', '长期在平顺、长治交界地带活动，为日军搜集八路军情报，多次带队突袭平顺抗日村庄，抢劫粮食牲畜，并强迫青年加入伪军。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
