REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('63d72c059de65adb9b3f8d6a41f47f49', '郭采芹', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀南道公署顾问、伪邯郸县教育科长、伪邯郸县知事、伪邯郸县知事（县长）、伪邯郸县知事（继任）、伪邯郸县警察局局长、伪馆陶县知事、曲周县伪警备队大队长', '1938-1945', '', '指挥伪警察搜捕抗日地下党员，破坏地下交通线，刑讯逼供抗日志士。；长期担任伪邯郸县知事，推行保甲制度，强征劳工，为日军提供情报，参与“治安强化运动”。；在丛台地区推行奴化教育，强制学校使用日伪教材，组织学生参加“中日亲善”活动，并检举有抗日思想的师生。；充当日军傀儡，征收苛捐杂税，强征民夫，配合日军扫荡。；组建伪警备队，配合日军扫荡抗日根据地，多次带队抓捕抗日干部和家属，烧毁村庄，抢劫民财，民愤极大。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
