REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('06c1ecca7c3f5240b6bf4a99f59beae0', '金名世', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、河北、辽宁', '吉林、河北、辽宁', '[]', '伪吉林省省长、伪吉林省省长、伪满民生部大臣、伪吉林省省长、伪满洲国司法部大臣、伪吉林省省长（后期）、伪吉林省警务厅厅长、伪吉林省警务厅长、伪吉林省警务厅长、伪吉林市市长、伪吉林省警务厅长、伪吉林省长、伪满凌源县参事官、伪满吉林市市长、伪满民生部大臣、伪满吉林省民政厅长、伪满吉林省省长、伪满吉林省警务厅厅长、伪满吉林省警务厅长、伪满奉天省省长、伪满吉林省警务厅长、伪满热河省省长、伪满洲国吉林省伪省长、伪满洲国吉林省伪省长（后期）、伪满洲国吉林省省长、伪满洲国吉林省警务厅长、伪满洲国热河省高等法院院长、伪满鞍山地方检察厅厅长、伪热河省公署参事官、伪热河省教育厅长', '1931-1945', '', '负责吉林地区伪警察系统，搜捕抗日分子，协助日军实施“治安肃正”。；原吉林警察机构官员，投日后任伪吉林省警务厅长，组织警察特务搜捕抗日分子，破坏地下组织，在丰满地区实施高压统治。；原吉林警察头目，投日后任伪满吉林省警务厅厅长，组织警察特务，在四平、伊通等地搜捕抗日志士，破坏地下组织。；原吉林省政府官员，投日后任伪吉林省长，管辖四平、梨树等地，推行“粮谷出荷”和“勤劳奉仕”制度。；满族亲日分子，在吉林市及昌邑区实施奴化教育，强征劳工，镇压反满抗日活动。……（共涉及30个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9ecee7f0ddf659e583819e721e164c94', '金壁东', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、河北、辽宁', '吉林、河北、辽宁', '[]', '伪吉林省省长（后期）、伪吉林省省长（末任）、伪满奉天省警务厅长、伪满新京特别市市长、伪满新京特别市市长、伪满交通部大臣、伪满洲国奉天市长、伪满洲国新京特别市市长、伪满洲国热河省民生厅厅长、伪满热河省次长（实际掌权者）、伪满铁道守备队司令（活动于铁岭）、伪满鞍山地区“铁路护路队”队长、伪热河省实业厅长', '1931-1945', '', '清肃亲王善耆之子，投日后在四平、长春一带协助日军管理铁路与城市，镇压反满抗日活动。；熙洽之后继任伪吉林省长，推行日本移民政策，强征劳工，镇压反满抗日活动。；在任期间配合日本“决战体制”，强征物资和兵员，迫害抗日志士。；清皇室后裔，投日后任伪新京（长春）市长，管理伪都，镇压抗日活动。；清肃亲王善耆之子，投靠日本后历任伪满要职，在吉林龙潭地区推行殖民政策，协助日军镇压抗联。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
