REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5dc435eefa0b5af4941c63fafe2dcd4d', '金铭', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪建昌县司法科科长', '1937-1945', '', '主持伪司法审判，以“反满抗日”罪名判处多名爱国人士死刑或长期监禁，协助日伪维持殖民秩序。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
