REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9cc8abde983e5319b2c80645c3730535', '金铭世', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪北票炭矿株式会社理事、伪桦甸县县长、伪满文圣区维持会会长、伪热河省朝阳县警务科长', '1931-1945', '', '在任期间强征劳工修建警备道路和碉堡，为日军提供粮食和物资，并组织汉奸情报网，破坏抗日地下组织。；协助日军管理北票煤矿，强迫中国矿工劳动，虐待致死无数，提供煤炭支持侵华战争。；在朝阳县推行“治安肃正”，组织汉奸特务队，残害抗日群众。；在辽阳文圣区组织维持会，协助日军建立秩序，强征民夫修筑军事工事，并告密抗日活动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9a5a1ebde04057d5a145d3ac6bf8014c', '门炳岳（投日时期）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪绥远省防共自治军头目', '1938-1940', '', '原国民党军官，投日后在凉城、和林格尔一带组织伪军，协助日军建立据点，破坏抗日交通线。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3befe943cf1459409f0122ad62f31e23', '门致中', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、山西、河北', '天津、山西、河北', '[]', '伪冀东保安队改编后指挥官、伪华北政务委员会绥靖总署督办、伪华北治安军总司令（名义上管辖山西）、伪华北绥靖军第1军军长（驻石家庄）、伪华北绥靖军第2军军长', '1938-1945', '', '原西北军将领，投日后在河北保定、石家庄一带驻防，多次率伪军进攻冀中根据地。；指挥华北伪军配合日军“扫荡”，其下属部队在晋中地区犯下罪行。；负责华北伪绥靖军，在廊坊各县设立“剿共”办事处，破坏地下交通站。；率伪军驻守石家庄，配合日军“铁壁合围”，在束鹿、晋县等地烧杀抢掠，并强抓民夫修建碉堡。；在冀东地区（含秦皇岛、北戴河）指挥伪军，配合日军进行“治安强化运动”，残害百姓。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e9b41353cfd35f4a9d3971b6e5fcad19', '阎世英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪阳城县警备队中队长', '1942-1942', '', '率部驻守阳城据点，多次伏击抗日游击队，杀害抗日村长和民兵。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3083c32dac1e5182a8f6e46300335aa7', '阎传绂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪吉林省实业厅长、伪吉林省教育厅长、伪吉林省民政厅长、伪吉林省长、伪吉林省民政厅长、伪满司法部大臣、伪吉林省省长、伪吉林省省长、伪满司法部大臣、伪吉林省高等法院院长、伪满司法部大臣（本溪法院系统）、伪满吉林省教育厅长、伪满四平省省长、伪满洲国司法部大臣、伪满洲国吉林省伪省长、伪满洲国吉林省伪省长（中期）、伪满洲国吉林省警务厅长、伪满洲国奉天省教育厅厅长', '1931-1945', '', '利用司法系统迫害抗日人士，判处大量爱国者死刑或长期监禁。；推行奴化教育，在丰满及吉林地区学校强制灌输“日满亲善”，禁止使用中文教材，迫害爱国教师。；伪满四平省（辖四平、梨树等县）省长，配合日军“讨伐”抗联，强征民夫修筑战备工事。；在昌邑地区推行日语教育，篡改历史教材，强迫学生效忠日本天皇。；投敌后任伪省民政厅长，推行保甲制度，协助日军清乡，迫害抗日家属。……（共涉及20个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
