REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('318089c2a3375e67b7c33f0820381332', '阮振铎', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪满交通部大臣、伪满奉天省省长、伪满交通部大臣（曾任奉天省教育厅长）、伪满交通部大臣（本溪铁路监管）、伪满交通部大臣（长春）、伪满外交大臣、伪满驻日大使、伪满外交部大臣（曾处理阜新地区外交事务）、伪满奉天市市长、伪满奉天省交通厅长、伪满奉天省教育厅厅长、伪满奉天省教育厅长、伪满奉天省次长（实际掌权者）、伪满奉天省省长、伪满奉天省省长（继于芷山后）、伪满奉天省警务厅长、伪满文教部大臣、奉天省教育厅长、伪满文教部大臣（曾活动于长春）、伪满洲国交通部大臣、伪满洲国交通部大臣、奉天省省长、伪满洲国交通部大臣（曾在长春任职）、伪满洲国奉天市市长、伪满洲国奉天省实业厅厅长、伪满洲国奉天省教育厅长、伪满洲国奉天省民生厅厅长、伪满洲国奉天省省长（后期）、伪满洲国文教部大臣、伪满洲国文教部大臣（在长春推动奴化教育）、伪满洲国文教部大臣（曾任吉林伪教育厅长）、伪满洲国文教部大臣（长春）、伪满洲国经济部大臣（主管阜新矿业开发）、伪满锦州省次长（实际掌权者）', '1931-1945', '', '推行日语教育和“王道乐土”宣传，抹杀东北人民民族意识。；在长春推行奴化教育，强制学习日语，抹杀中国民族意识。；推行奴化教育，篡改历史，在长春及吉林各地学校强制灌输“王道乐土”思想。；在长春负责伪满交通建设，为日军运输军需，协助“讨伐”抗联。；在吉林、长春推行文化专制，查禁抗日书刊，强制推行“王道乐土”宣传。……（共涉及36个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ff0f89e65f4950a6809413d19bf70e97', '阿思根', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪兴安南省警备军团长（后反正）', '1939-1945', '', '科尔沁左翼中旗人。早期在伪军中任职，参与镇压抗日活动，但后期于1945年8月率部反正，故仅列其投敌时期行为。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('727b4e4be11055f4aa12b2612d4f056c', '阿拉坦敖其尔', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪伊克昭盟副盟长、伪鄂尔多斯保安队指挥官、伪蒙古军第6师师长', '1937-1945', '', '率部在化德、镶黄旗一带活动，多次袭击八路军游击队。；协助日军在鄂尔多斯建立伪保安队，参与抓捕抗日志士，为日军提供劳役和粮食。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('039316d8598c556597a95c9463c40d88', '阿拉腾敖其尔', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪伊克昭盟乌审旗警察署署长', '1941-1945', '', '效忠伪蒙疆政权，在乌审旗建立伪警察体系，搜捕抗日地下工作者，向日军提供情报，参与镇压“独贵龙”运动余部。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('47c2a5c483015a58bd37abc52be5e3fe', '陆宗舆', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、河北', '北京、天津、河北', '[]', '伪华北政务委员会经济顾问、伪华北政务委员会经济顾问（在天津活动）、伪华北政务委员会顾问、伪天津中日文化协会会长、伪天津市银行联合会会长', '1937-1945', '', '曾任北洋政府官员，后投靠日伪，在北平担任顾问，参与策划经济统制政策。；原亲日外交官，投日后任伪顾问，参与对北平及昌平地区的殖民政策制定。；在北平担任日伪顾问，参与策划奴化政策，涉及海淀地区学校和文化机构；亲日派人物，参与伪政权活动，协助日本经济掠夺。；在天津组织亲日文化活动，宣传“中日亲善”，麻痹民众抗日意识。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('71ae99e132c6587fba9f327c83617f04', '陆宗舆（重复？不，另列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪华北政务委员会顾问', '1938-1941', '', '参与日伪对冀中地区的经济掠夺，支持“以战养战”政策。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('55e9efd9a3f050558f001008cfa8a35a', '陈万禄', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '景县伪情报站长', '1940-1945', '', '专门搜集景县抗日武装和八路军活动情报，多次导致抗日人员被捕牺牲，破坏地下交通线。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2a0f22ec2f6c5bf38404607a0e8cf2cf', '陈三狗', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪左权县保安队班长', '1943-1943', '', '率班在左权县石匣乡抓捕抗日民兵，杀害2人，烧毁房屋。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f4fb221247765ec88ca4a9de794c1c2a', '陈世昌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪神池县合作社主任、蒲县伪合作社主任', '1942-1945', '', '为日军统制经济服务，低价强购粮食、棉花等物资，供应日军军需，导致当地百姓饥荒。；控制物资配给，垄断食盐、布匹等生活必需品，高价配给百姓，克扣物资中饱私囊，并协助日军掠夺战略物资。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('048718df0a8f5b4f87ffcb385f5b35ab', '陈中孚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津', '北京、天津', '[]', '伪华北政务委员会教育总署督办、伪天津市保安队队长', '1938-1945', '', '在北平推行奴化教育，修改教科书，强制学校教授日语，破坏东城地区教育体系。；推行奴化教育，在大兴各中小学强制使用日伪教材，删除中国历史内容，强迫学生参加“新民会”活动。；指挥伪保安队协助日军巡逻，搜捕抗日地下工作者，参与“治安强化”行动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('39dc94a553945f8689bca968bac0614a', '陈国华', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、辽宁', '山西、辽宁', '[]', '伪临汾县警备队大队长、伪兴县维持会副会长、伪和顺县警备队队长、伪满凌源县警务科长、伪长治县新民会组织股长、伪长治县警察局局长', '1936-1945', '', '率领伪警备队驻守临汾，多次配合日军突袭翼城边界村庄，抢劫财物，抓捕壮丁。；在兴县为日军征收军粮，并告密导致多名抗日人员被捕。；在和顺、左权交界处设卡盘查，抓捕过路抗日人员，多次参与“扫荡”。；发展汉奸会员，建立情报网络，向日军提供抗日名单。；指挥伪警察搜捕抗日人员，严刑逼供，破坏地下交通站。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('74b3d89692df5373bc16b96697f2b4d6', '陈国权', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、河北、辽宁', '吉林、河北、辽宁', '[]', '伪喀喇沁左旗协和会会长、伪平泉县县长、伪满长春宪兵队队长', '1933-1945', '', '在长春（新京）宪兵队任职，严刑拷打抗日嫌疑犯，执行“思想矫正”。；在平泉县推行伪满法令，强征粮税，协助日军建立保甲制度，迫害抗日家属。；积极推行奴化教育，组织“协和会”宣传亲日思想，强迫民众参加日伪活动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e60d0335f96157edb58448797cda6ce0', '陈国栋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、吉林、山西、河北、辽宁', '北京、吉林、山西、河北、辽宁', '[]', '临县伪教育科科长、临城县伪新民会会长、伪代县合作社理事长、伪保德县宣抚班班长、伪偏关县宣抚班班长、伪卢龙县保安队大队长、伪大同教育督学、伪安国县警察所所长、伪尧山县新民会会长、伪山西省教育厅督学（古交籍）、伪峰峰矿区区长、伪忻县合作社理事长、伪故城县知事、伪晋城县政府顾问、伪晋城县新民会会长、伪曲阳县警察局局长、伪朔县情报组组长、伪沁水县新民会会长、伪沧州宪兵队翻译、伪涞水县财政科科长、伪满洲国奉天省于洪区区长、伪磐石县教育会会长、伪行唐县财政科科长、伪襄垣县情报组长、伪运城商会会长、伪邢台县知事（兼辖沙河部分区域）、伪邢台县维持会会长、伪邯郸县知事、伪邱县维持会会长、伪长治县知事、伪陵川县警察局局长、伪高邑县第二区区长、伪黎城县新民会会长、元氏县伪区长（城关区）、古冶矿警队队长、吕梁地区伪警备队副队长、宁武县伪新民会会长、定襄县伪区公所区长（第三区）、平陆县伪维持会副会长、广宗县伪税务局局长、成安县伪区公所区长（第二区）、晋县伪商会会长、枣强县伪教育科长、栾城县伪税务局局长、深泽县伪教育科长、良乡县伪县长（房山邻县，但辖区涉及房山部分地区）、运城伪商会会长、运城伪教育督学、邢台地区伪冀南道尹公署参事、邯郸县伪县长（兼辖鸡泽部分地区）、隆平县伪新民会会长', '1936-1945', '', '在良乡及房山交界地区推行日伪统治，强征粮食，组织伪军配合日军“清乡”。；推行奴化教育，强制学校教授日语和“满洲国”历史，检举爱国教师，并组织学生为日军“献金”活动。；推行奴化教育，强迫学校使用日伪教材，宣传“中日亲善”，破坏抗日宣传教育。；在吕梁山区多次率伪军袭击八路军游击队，杀害抗日家属，破坏地下交通线。；任伪大同教育督学，推行奴化教育，强制学校教授日语，篡改历史教材，宣扬“中日亲善”。……（共涉及52个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4b74de49fe295d089c7808ac8eae8402', '陈国瑞', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪丰宁县县长、伪南宫县知事（今属邢台）、伪围场县警察署署长、伪定兴县税务局长、伪承德县县长、伪承德县警务科长、伪热河省协和会兴隆分会主任、伪热河省警察讨伐队队长', '1934-1945', '', '为日军征收苛捐杂税，强抢民间物资，导致百姓负担沉重，部分农户破产。；在丰宁推行日伪“治安肃正”政策，组织汉奸自卫团，强征粮食，配合日军“三光”政策，迫害抗日家属，破坏地下抗日组织。；在承德地区组织伪警察特务，搜捕抗日地下人员，破坏抗日组织，多次带队“清乡”残害百姓。；积极宣传‘日满亲善’，推行奴化教育，搜集抗日情报，协助日军实施‘三光政策’，在兴隆地区犯下罪行。；任伪承德县县长期间，推行保甲制度，强征粮税，协助日军建立“无人区”，迫害百姓，破坏抗日根据地。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('44196d928e4856589a333de83b1cae68', '陈国良', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、山西', '内蒙古、山西', '[]', '伪克什克腾旗旗长、伪大同省天镇县税务局长、伪赤峰警察局局长', '1933-1945', '', '在赤峰及元宝山地区建立特务网络，抓捕抗日地下工作者，协助日军进行“大检举”行动。；投靠日军，任伪旗长，协助日伪推行殖民统治，强征民夫、粮食，镇压抗日活动。；为日军征收各种苛捐杂税，强抢粮食，导致天镇百姓饥荒，并贪污勒索，民愤极大。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7857074a30365b12bcc507046a476333', '陈国钧', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪长春县县长', '1932-1940', '', '在长春县（今长春郊区）强征壮丁，推行“连坐”制度，镇压农民反抗。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('231861bd037c500b9f6574030d28a4af', '陈子厚', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪垣曲县教育科长、伪大同省教育厅督学（负责阳高教育）、伪平定县新民会会长、伪盐湖商会会长、伪运城宣抚班班长、原平伪警备队中队长、威县伪教育科长', '1938-1945', '', '推行奴化教育，强制学校使用日伪教材，宣扬“中日亲善”，迫害爱国教师。；多次带队袭击抗日游击队，在崞县（今原平）一带制造“无人区”，杀害无辜百姓。；随日军宣抚班到临猗各村演讲，诱骗百姓归顺，并收集地方武装情报，导致多支抗日小分队遭伏击。；推行奴化教育，强迫学校使用日伪教材，宣扬“中日亲善”，并告发多名爱国教师，致其被捕或失踪。；为日军筹措军饷，控制盐业贸易，强迫商户向日军献金，从中牟利，并告发抗日商人。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8c52a2d114655375bd9ebee7a8983881', '陈子敬', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪冀南道保安副司令、伪安泽县警察所所长、伪山西省政府参议（晋城籍）', '1940-1945', '', '指挥伪警察抓捕抗日地下党员和进步群众，严刑逼供，导致多人牺牲，并协助日军推行“保甲制度”。；在太原伪省府任职，为日军“治安强化”运动出谋划策，并回乡劝降抗日武装。；协助李福和整编伪军，参与“铁壁合围”扫荡，杀害抗日家属。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3ca9d6590d3c5b6688de03e0b2cf0b9e', '陈子斌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪南宫县维持会会长、伪大名县自卫团团长', '1938-1945', '', '日军占领南宫初期，组织维持会，为日军筹粮派款，引导日军搜捕抗日人士。；组织自卫团协助日军防守据点，参与‘清乡’行动，残害抗日积极分子。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('05d72939614156a89c18bb736835b10c', '陈子明', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪冀南道教育科长、伪运城特务队队长、伪长治县（含屯留部分）维持会会长', '1938-1945', '', '专门刺探抗日军情，抓捕地下党员，刑讯逼供，制造多起惨案。；组织维持会为日军筹粮派款，提供情报，协助日军建立伪政权。；推行奴化教育，在邯郸各学校强制教授日语，灌输‘中日亲善’思想，压制师生抗日情绪。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('25e59baf651353e2b38dfc322fb650ec', '陈子良', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪临汾保安队队长、伪昔阳县新民会会长、伪晋城县维持会会长、伪榆社县合作社主任、晋城伪军独立团团长、沁县伪合作社主任、浮山县伪警察局局长', '1938-1945', '', '率伪保安队配合日军“扫荡”临汾周边村庄，烧杀抢掠，杀害抗日干部。；负责浮山县城日伪治安，设立情报网，侦捕抗日地下工作者，严刑逼供，致使多名抗日志士牺牲。；负责在昔阳推行奴化教育，组织‘新民会’宣传亲日思想，强迫群众参加反共集会。；为日军统制经济服务，强征粮食棉花，垄断物资，剥削百姓。；为日军筹粮筹款，强迫百姓领取“良民证”，出卖抗日积极分子。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4006f2ad2dee53ab8795fa42d9aece6b', '陈子衡', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪河北省公署参议（驻石门）、伪邯郸县商会会长', '1938-1945', '', '参与制定伪省“治安肃正”计划，在石家庄桥西推行“连坐法”，迫害平民。；为日军筹集军饷，强迫商户捐款，垄断食盐和布匹贸易，从中牟利，资助伪政权。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f3ce8c42e6fb5d28bbb9637d52100dc8', '陈子谦', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪高平县警备队长、陵川日伪情报站站长', '1941-1945', '', '率伪警备队驻守高平，抓捕抗日地下党员，刑讯逼供，手段残忍。；建立日伪情报网，刺探八路军和抗日政府情报，导致多次抗日行动失败，多名地下党员被捕牺牲。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('72ff70842aed5327ae57a9ccc7bf806b', '陈宝仓', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪保定绥靖公署参议（涉涿州）、伪华北政务委员会参议（驻石家庄）、伪望都县新民会会长', '1940-1945', '', '利用新民会宣传奴化思想，组织“青少年团”为日军搜集情报，并强迫民众参加“庆祝会”欢迎日军。；原国民党军官，投敌后参与策划对涿州、新城等地的“铁壁合围”，为日军提供当地抗日武装情报。；参与策划对石家庄周边抗日根据地的经济封锁，协助日军推行“治安强化运动”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
