REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fd8ec7c6dfd259f2bfc0c4a8ab7723d2', '陈殿元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪曲周县特务队队长、伪清河县警备队中队长', '1940-1945', '', '率警备队多次突袭抗日村庄，烧毁民房，杀害抗日家属，抢夺牲畜。；专门刺探八路军情报，带领特务队破坏地下交通站，逮捕并严刑拷打抗日群众，多次导致抗日组织被破坏。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2cec24d66b2d566a999ae5ce40c5654a', '陈永寿', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '乡宁县伪区公所区长、伪临汾警察局局长', '1939-1945', '', '在乡宁西坡镇等日占区任伪区长，强迫村民领取“良民证”，举报抗日家属，致使多人被日军杀害。；指挥伪警察搜捕抗日地下党员，参与制造多起屠杀事件。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c3479bfa70b05831b77dbb675d5ad7e4', '陈永福', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪沁源县合作社主任', '1942-1945', '', '控制物资配给，垄断粮食，为日军提供军需，剥削百姓。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('7bc3eef01d9e5b2cb727ec3a74bf20dc', '陈洛绪', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪藁城县商会会长', '1938-1945', '', '为日军筹集物资，强迫商户“献金”，从中贪污，资敌卖国。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('058e87da8cef557cac4bdba061ee67ca', '陈玉堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '馆陶县伪区公所区长（某区）', '1940-1945', '', '强迫村民修炮楼、挖封锁沟，向抗日家属勒索钱财，告密导致多名抗日人员被捕。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('55d3b99318925ce6af39f4b5afc2606d', '陈玉山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪临西区（今临西县境）维持会会长、伪康保县警察局长', '1938-1945', '', '为日军搜集情报，逮捕抗日地下工作者，严刑逼供，破坏抗日组织。；为日军筹粮派款，提供抗日武装活动情报，导致多个村庄被烧杀。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('100903e3ba7f50fe91ce116eab66b33a', '陈玉甲', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、河北', '内蒙古、河北', '[]', '伪包头市警察局长、伪土默特左旗公署参事、伪归绥市警察局局长、伪绥远省公署警务厅长、伪蒙古军第3师师长', '1937-1945', '', '原为包头地方势力，日军占领后投敌，任伪警察局长，协助日军搜捕抗日地下人员，残害百姓。；原绥远警察头目，投日后任伪警务厅长，协助日军搜捕抗日人士，镇压民众反抗。；在呼和浩特（归绥）任伪警察局长，专门搜捕抗日分子，在回民区设立特务据点，多次逮捕并刑讯回民爱国人士。；协助日军推行保甲制度，强迫村民报告八路军行踪，导致多名地下党员被捕牺牲。；率伪蒙古军驻防沽源、宝昌一带，配合日军“治安肃正”，烧杀抢掠。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('ddcfb16d41be52418ca83c43624dca1c', '陈玉铭', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪承德县县长、伪承德县警务科长、伪阳原县维持会会长', '1937-1945', '', '日军占领阳原后率先组织维持会，为日军筹粮派款，出卖抗日积极分子。；在承德县推行伪满“街村制”，强征劳工，搜刮粮食，协助日军建立“无人区”，迫害抗日群众。；在承德地区任伪警务科长，组织特务情报网，多次抓捕抗日地下工作者，参与制造多起屠杀事件。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('816af17b0eb75cd2af61c252b0bc97f8', '陈秉义', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪凉城县县长、伪包头商会会长、伪包头市公署市长、伪包头市市长、伪包头市警察局局长、伪固阳县县长、伪归绥县知事（县长）、伪绥东保安队队长、伪绥西自治联军副司令、伪蒙古军第2师师长、伪蒙古军第5师师长、伪蒙古军第9师师长', '1938-1945', '', '率部驻防丰镇周边，多次袭击抗日游击队，杀害抗日干部，强征民夫修筑日军工事。；任伪凉城县长期间，为日军征粮派款，组织伪警察抓捕抗日地下人员，破坏中共凉城抗日根据地。；原为地方民团头目，投日后任伪绥东保安队队长，在卓资、旗下营一带为日军搜集情报，抓捕抗日人员，欺压乡民。；率伪军驻扎商都、化德地区，参与日军“治安强化”运动，屠杀抗日群众。；协助王英统领伪军，在乌海、海南周边地区设卡收税，强征民夫，为日军修筑工事。……（共涉及16个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('782458db75cd520a8d6076faf8457826', '陈维藩', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东新民会会长、伪唐山市长、伪开平区维持会会长', '1937-1945', '', '日军占领开平后组织维持会，为日军征粮派款，提供情报，协助建立伪区公所。；任伪唐山市公署市长，管理唐山市区，配合日军经济掠夺，控制煤炭、钢铁资源。；在唐山、迁西地区组织新民会，进行奴化宣传，搜集抗日情报，协助日军“宣抚”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('670e0ba2862c5e24b8524fd639490d98', '陈耀堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪冀南道公署建设科科长、晋南伪军独立旅旅长', '1941-1945', '', '原国民党军官，后率部投敌，改编为伪军独立旅，驻防平陆、运城一带，参与日军“扫荡”中条山抗日游击队，烧杀抢掠。；主持修建日军军用公路和碉堡，强拆民房，征用大量土地，致使邯山农民流离失所。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
