REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fa510168433c55bd8e941a5d02a6231a', '陈锡九', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪邯郸县教育科科长、伪魏县新民会会长、磁县伪税务局长', '1938-1945', '', '为日军征收各种苛捐杂税，强征棉花、铁矿石等战略物资，中饱私囊，民愤极大。；推行奴化教育，删改教材，强制学校教授日语，灌输“大东亚共荣”思想，迫害爱国教师。；推行奴化教育，组织“新民会”胁迫群众参加日军庆功会，搜集抗日情报。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3fbf1154caed5e6491d769fb56464132', '陈长捷', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、山西', '内蒙古、山西', '[]', '伪包头市公署市长（投日后）、伪太原绥靖公署副官长、伪绥东保安司令（后投日）、伪绥远省公署顾问（后投日）', '1940-1945', '', '原国民党军官，1940年投日，在乌兰察布东部（兴和、丰镇）组织伪保安队，配合日军“蚕食”抗日根据地。；原国民党军官，被俘后投敌，任伪包头市长，推行日伪法令，组织汉奸商会，为日军筹集物资，迫害爱国人士。；原国民党将领，被俘后变节，在归绥新城为日军出谋划策，参与策划对抗日武装的围剿行动。；负责日伪军后勤，贪污军需物资，间接导致伪军战斗力低下，但助纣为虐。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('e925dd52f9355556b46352422eafe49a', '陈长捷（注：此人为国民党将领，但曾与日伪有暧昧，需谨慎）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '（不列入，因非汉奸）', '', '', '', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f3baedeec5d9550c9fe76ccba55e98b1', '陶克陶', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、河北', '内蒙古、河北', '[]', '伪乌拉特中旗旗长、伪兴安北省省长（呼伦贝尔地区）、伪兴安总省省长、伪察哈尔盟盟长、伪蒙古军团长、伪蒙古军师长、伪蒙古军第1军军长、伪蒙古军第1师师长、伪蒙古军第1师师长、伪蒙疆政府军事部长、伪蒙古军第1师师长、伪蒙疆政府军事顾问、伪蒙古军第9师师长、伪蒙古军第一军军长、伪蒙疆政府保安部长、伪蒙疆政府司法部长、伪蒙疆政府司法部长（活动于张家口）', '1932-1945', '', '率伪蒙古军驻扎化德、商都一带，配合日军“扫荡”抗日游击队，残害当地民众。；在四子王旗边境地区袭击抗日武装，杀害抗日军民，抢劫牲畜和财物。；率伪蒙古军驻防绥西地区，多次配合日军扫荡包头、固阳、白云鄂博周边抗日游击队，掠夺牲畜和矿产。；在日本关东军扶植下出任伪兴安北省（今呼伦贝尔大部）省长，推行殖民政策，强制收缴民间枪支，组织伪警察镇压抗联和民众反抗。；任伪兴安总省（辖呼伦贝尔地区）省长，推行日本殖民政策，组织伪警察镇压抗日活动……（共涉及22个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c1ba15e6cdf55fd7891106db4277da0d', '陶尚铭', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪冀东防共自治政府唐山办事处主任、伪冀东防共自治政府外交处长、伪冀东防共自治政府外交处长、伪唐山专员、伪冀东防共自治政府外交处长、伪唐山市长、伪冀东防共自治政府民政厅长、伪冀东防共自治政府秘书长、伪唐山地区行政督察专员、冀东伪政府唐山办事处主任、冀东防共自治政府外交处长、冀东防共自治政府民政厅长', '1935-1945', '', '参与冀东伪政权外交事务，后任伪唐山地区专员，为日军征粮派夫。；主管民政事务，在丰南、唐山一带组织伪警察和自卫团，协助日军抓捕抗日军民。；负责唐山地区伪政权日常事务，配合日军清乡，强征民夫修筑工事。；代表伪政权与日本交涉，协助日军在冀东地区建立军事据点。；在唐山地区为日军征粮派款，破坏抗日组织，协助日军控制唐山、古冶矿区。……（共涉及20个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('10cf9499b86c5eb48e46960674ae33ce', '雄诺敦都布', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古', '内蒙古', '[]', '伪乌拉特前旗旗长、伪伊克昭盟盟长（后任）、伪四子王旗札萨克（旗长）、伪蒙古军第2师师长、伪蒙古军第3军军长、伪蒙古军第5军军长、伪蒙古军第5师师长、伪蒙古军第三军军长、伪蒙疆政府内政部长、伪锡林郭勒盟副盟长', '1936-1945', '', '伪蒙古军将领，在乌兰察布、兴和地区参与“扫荡”，强征民夫修筑公路和碉堡，配合日军推行“保甲制”。；率部在化德、张北一带协助日军维持治安，镇压抗日民众。；投靠日伪政权，在旗内推行奴化教育，强迫牧民献粮献畜，协助日军维持殖民统治。；在包头、萨拉齐一带活动，协助日军建立伪保甲制度，强征民夫修筑工事，镇压民众反抗。；德王亲信，率伪蒙古军驻守绥东地区，参与多次扫荡行动。……（共涉及10个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
