REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('4bd9cd1ed4f65f568f7afde7603fda36', '韩凤楼', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '内蒙古、山西、河北', '内蒙古、山西、河北', '[]', '伪乌兰察布盟盟长、伪包头市市长、伪宣化县知事、伪察南自治政府副主席、伪察哈尔省保安司令、伪察哈尔省保安司令、伪张家口地区警备队长、伪察哈尔省公署民政厅长、伪察哈尔省警务厅厅长、伪平城维持会会长、伪张北县知事、伪张家口特别市公署市长、伪张家口警察局局长、伪涿鹿县知事（县长）、伪绥远省公署民政厅长、伪绥远省公署警务厅长、伪赤城县知事（县长）', '1937-1945', '', '投靠日伪，任伪盟长期间，推行奴化教育，组织伪警察镇压抗日活动，为日军提供物资和劳役。；日本占领包头后任伪市长，负责推行日伪市政管理，组织劳工为日军开采白云鄂博铁矿，强征粮食和物资。；投日后管理伪绥远民政，推行日伪保甲连坐制度，迫害百姓。；在呼和浩特任伪警务要职，组织伪警察协助日军搜捕抗日地下党员，镇压学生和民众反日运动。；日军占领平城后首任维持会会长，为日军筹集粮饷，强迫商户“献金”，协助日军建立治安秩序。……（共涉及16个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5ecdb6b22c615e368ffe537daaadad8f', '韩则信', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、河北', '北京、天津、河北', '[]', '伪临榆县知事（二次任职）、伪临榆县（山海关）知事、伪冀东政府唐山办事处主任、伪冀东政府迁安县长、伪冀东道公署顾问、伪冀东防共自治政府实业厅厅长、伪冀东防共自治政府滦县县长、伪冀南道尹、伪唐山地区“剿共”自卫团团长、伪唐山矿区保安大队长、伪大厂县警察局长、伪昌黎县维持会会长、伪迁安县公署顾问、伪通州警察局长', '1933-1945', '', '指挥伪警察协助日军搜捕抗日分子，参与“治安强化”行动，欺压百姓。；投日后任伪冀南道尹，管辖邢台、邯郸等地，推行“治安强化”运动，配合日军对冀南根据地的“囚笼政策”。；组织地方自卫团，配合日军袭击抗日村庄，杀害村干部和群众。；在唐山开滦矿区组织伪保安队，镇压矿工罢工，为日军控制煤炭资源效力。；在唐山地区推行伪政府法令，组织汉奸团体，协助日军收集情报，镇压当地抗日活动。……（共涉及14个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
