REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b0d4333d37d65ff0bfa25d9f37623ae1', '马伯援', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪晋中道尹', '1939-1945', '', '任伪晋中道尹期间，推行保甲制度，强征民夫修筑公路和碉堡，协助日军清乡扫荡。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('c0346f29d2825ca4bf79008332dc76bb', '马占元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '五寨县伪新民会主任、伪军大队长（驻望都）、伪潞城县便衣队队长、伪热河省丰宁县协和会青年训练所所长', '1940-1945', '', '负责伪新民会宣传，推行奴化教育，煽动民众反对抗日政权。；带领便衣队混入集市和村庄，刺探八路军情报，多次引导日军突袭抗日村庄。；率伪军驻守望都西关，多次突袭周边村庄，抢劫牲畜和粮食，并参与杀害冀中军区第十分区交通员。；训练汉奸青年，灌输奴化思想，组织青年团协助日军巡逻，曾带领特务抓捕丰宁地区的地下党员，并参与破坏抗日交通线。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d7eca4cf356953a9bd843f9ae77031f1', '马占山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满开原县自卫团团长、伪满洲国军政部总长（短暂投敌后反正）、伪满黑龙江省省长（后反正）、伪满黑龙江省省长（短暂投敌后反正）、伪满黑龙江省长（短暂投敌后反正）', '1931-1940', '', '曾一度投降日军任伪职，但不久反正抗日，其投敌期间未在葫芦岛地区有具体活动，但作为东北汉奸名单常被提及。；一度投日任伪职，影响绥中地区部分旧部附逆，后反正抗日，但前期行为已构成汉奸事实。；原黑龙江抗日将领，1932年一度投日任伪黑龙江省长，但不久反正抗日，故其汉奸身份短暂且存在争议。；原开原县民团头目，投日后任自卫团长，配合日军“扫荡”，烧毁村庄，强征壮丁，罪行累累。；一度投敌任伪职，但不久反正抗日，其在辽宁鞍山地区短暂活动期间未造成重大危害。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a9c5a94bd6555f31b291ade55c77d32c', '马占山（后期投日）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满军政部总长（一度在锦州地区活动）', '1932-1945', '', '早期抗日，后一度投日，任伪满军政部总长，其部队曾在锦州地区配合日军行动。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b6f8247a41e15a528b4e0e0fb609468e', '马占山（投敌时期短暂活动于锦州）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满军政部总长（后反正）', '', '', '1932年曾一度投敌，在锦州地区与日军合作，但不久反正，此条仅记录其投敌期间行为。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
