REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9d688182f041598c915dcc96c6b6a757', '马占山（注：后反正，但初期曾投日，在吉林活动）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林', '吉林', '[]', '伪黑龙江省长（短暂投敌，后反正）', '1931-1932', '', '九一八后一度诈降任伪职，在吉林、长春参与日伪活动，后反正抗日，故不列为最终汉奸。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
