REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('07284cf8320b589fac71fd028d728597', '马占山（非抗日将领马占山，同名汉奸）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪垣曲县税务局长、伪左云县警备队副队长、伪应县新民会会长', '1938-1945', '', '协助日军在左云县各村庄设立“爱路村”，强迫村民报告八路军动向，多次带队伏击过路的小股抗日武装。；任伪应县新民会会长，推行奴化教育，强迫民众参加“反共”集会。；为日军征收各种苛捐杂税，强征民间财物，中饱私囊，并协助日军控制粮食贸易，导致当地百姓饥荒。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
