REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('0b863caef0f056aa87dc98994331ab04', '马占魁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪灵石县自卫团团长、定襄县伪税务局局长、平陆县伪警备队中队长', '1938-1945', '', '为日军征收各种苛捐杂税，横征暴敛，逼死多名交不起税的农民，并贪污部分税款。；率自卫团为日军站岗放哨，截击抗日游击队，杀害多名抗日军属。；率伪警备队多次围剿抗日游击队，烧毁村庄，抢夺牲畜，杀害无辜百姓，罪行累累。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('09d09f9157935f86a9e0faa8d84f6243', '马占鳌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、辽宁', '山西、辽宁', '[]', '伪古交区自卫团长、伪满清河地区协和会分会会长', '1935-1945', '', '组织汉奸自卫团，配合日军巡逻，参与杀害八路军伤员。；利用协和会组织宣传‘日满亲善’，诱骗青年参加伪军，并协助日军在清河地区进行‘归屯并户’。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d9a514f9cc9b5dc39e4b19b63e0bbd39', '马国栋', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪保定道尹公署顾问、伪唐山高地区联防队长、伪榆社县自卫团团长、伪石家庄宪兵队翻译官、伪石家庄警察局局长、伪获鹿县新民会会长', '1938-1945', '', '组织自卫团配合日军巡逻放哨，参与“三光”政策行动，烧毁村庄。；参与策划对唐县、阜平一带的“治安强化”运动，协助日军建立保甲制度。；在唐山高地区（今开平区一带）组织伪联防队，配合日军“清乡”，杀害抗日积极分子，抢夺民财。；为日军宪兵队担任翻译，参与刑讯逼供抗日志士，直接导致数十人牺牲。；投日警察头目，任伪石家庄警察局局长，在井陉矿区设立特务据点，搜捕抗日分子，严刑拷打矿工和地下党员。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('88d4d4b66fa65564bc9791669e3d8552', '马国选', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪枣强县（今属衡水）保安队副队长', '1940-1945', '', '率伪军多次袭击枣强、衡水边界抗日村庄，烧杀抢掠，抓捕抗日积极分子。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8c5ae5e9fe4f51429ef37abf793edddf', '马子良', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪晋城保安团团长、伪长治县税务局长', '1939-1945', '', '组织伪保安团，配合日军多次扫荡晋城周边山区，杀害抗日游击队员，抢劫民财。；为日军征收各种苛捐杂税，中饱私囊，并协助日军控制经济，破坏抗日根据地物资流通。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('659c360bcaeb5b3c99261a0c88e38aa4', '马廷福', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪临榆县保安大队长、伪冀东保安队大队长', '1935-1945', '', '在秦皇岛、山海关地区指挥伪保安队，协助日军清乡，抓捕抗日群众，抢掠财物。；在秦皇岛、山海关一带率伪军扫荡抗日游击队，烧杀抢掠', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
