REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('51f0abc8d3385972b33046822359065a', '马德山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、山西、河北', '北京、山西、河北', '[]', '伪代县情报股长、伪任丘县警备队副队长、伪冀南道保安司令部副官、伪固安县保安大队长、伪复兴区自卫团团长、伪安次县保安团团长、伪定县新民会会长、伪平谷县维持会会长、伪广平县维持会会长、伪广灵县商会会长、伪廊坊维持会会长、伪文水县警备队长、伪武安县警备队中队长、伪邢台县特务队队长、伪邢台县税务局长、伪邯郸县新民会会长、伪邯郸县特务队队长、伪邯郸县自卫团团长、伪青龙县大杖子乡乡长、伪魏县保安团中队长、成安县伪自卫团团长、灵丘县伪特务队队长、运城伪保安团副团长', '1937-1945', '', '日军占领平谷初期，组织维持会为日军筹粮筹款，提供向导，并劝降当地武装力量。；在文水县配合日军“扫荡”，烧毁村庄，抢掠财物。；为日军控制广灵商业，强迫商户向日军“献金”，并垄断食盐、布匹等物资供应，从中牟利，同时为日军收购军需物资。；专门抓捕抗日嫌疑人员，严刑逼供，杀害多名地下党员和进步群众。；专门搜集八路军和游击队活动情报，向日军报告，导致多次抗日行动失败，多名抗日人员被捕牺牲。……（共涉及23个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
