REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f72173b0ff9052c191ceae63e940cc31', '马文德', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪保定警察局局长、伪献县税务局局长、灵寿县伪警察所所长', '1939-1945', '', '主持伪警察局，设立特务机构，破坏中共地下组织，逮捕并刑讯抗日人士，直接参与多起屠杀事件。；为日军强征苛捐杂税，盘剥百姓，资助伪军经费，民愤极大。；效忠日军，负责灵寿县城治安，多次带队搜捕抗日地下党员，破坏抗日组织。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('d20fe59860095766aad2df96c63681d5', '马文斌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪襄垣县税务局长', '1940-1943', '', '为日军强征各种苛捐杂税，盘剥百姓，将搜刮的物资供给日军，导致民不聊生。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('49854bf7a7865ec28683a511345625aa', '马文波', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、河北', '北京、河北', '[]', '伪冀东教育督办、伪冀东道公署卢龙县联络员、伪冀中剿共军第一师师长（活动于高阳一带）、伪安新县警备大队长、伪定兴县维持会会长（初期）、伪平山县知事、伪石家庄市警察局局长、伪雄县财政科长、藁城县伪保安联队队长', '1937-1945', '', '在通州推行奴化教育，强制学校教授日语，篡改历史教材，灌输“中日亲善”思想。；率伪警备队多次围剿白洋淀雁翎队，烧毁水村，逮捕抗日家属。；日军占领定兴后率先组织维持会，为日军筹粮派夫，指认抗日积极分子，导致多人被捕。；为日伪政权征收苛捐杂税，强抢粮食，供应日军军需，压榨百姓。；率伪军驻扎高阳、蠡县交界，多次进攻八路军游击队，烧毁抗日村庄，抢掠物资，并杀害地方抗日干部。……（共涉及9个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('fea07466bb9d53d3a13f04dd08cd9a5d', '马文焕', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、山西、河北', '北京、山西、河北', '[]', '伪保定道安国县知事（后期）、伪山西新民会武乡分会会长、伪延庆县教育科督学、伪行唐县教育科督学、伪运城宣抚班班长、伪邢台县教育督学、伪黎城县西井镇维持会长、尧山区伪区长、平乡县伪区公所区长（第二区）、晋县伪新民会会长、栾城县伪教育科科长', '1938-1945', '', '在延庆各小学推行日语教育，强迫学生唱日本国歌，检举有抗日思想的教师，导致多名教师被捕。；为日军进行奴化宣传，强迫民众参加“中日亲善”集会，破坏抗日舆论，诱骗青年为日军效力。；负责新民会在武乡的宣传活动，鼓吹‘中日亲善’，诱骗青年参加伪军，并收集抗日情报供日军。；强迫村民修建碉堡，向日军献粮，并告密杀害地下党员。；继任伪县长后，继续推行日军‘三光政策’，组织伪军配合日军扫荡，并强迫青年加入伪军。……（共涉及11个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('8be688f147125242a0bf4c766a410019', '马文田', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪石门市保安团团长', '1940-1945', '', '率伪军多次进攻正定、获鹿等抗日根据地，杀害抗日干部和群众，制造多起惨案。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('6dfa2d001b3a5512b9cb9e8d6d0cb83b', '马文禄', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '元氏县伪军大队长、深泽县伪税务局长、赵县伪税务局局长', '1938-1945', '', '率伪军参与‘铁壁合围’扫荡，杀害抗日武装人员及无辜村民。；为日军征收各种苛捐杂税，强征粮款，盘剥百姓，将物资供应日军，并克扣伪职人员薪饷，中饱私囊。；为日军征收各种苛捐杂税，盘剥百姓，将大量物资供给日军。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
