REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('b412af5457d054aa935712a8aca34424', '马永昌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '壶关县伪合作社主任', '1942-1945', '', '为日军统制经济服务，垄断粮食、食盐等物资，强制低价收购农民产品，导致百姓饥荒。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('aebcd1f95096575f87caee184ef0e603', '马永魁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪大同县知事、伪大同县知事、伪大同省民政厅长、伪大同县知事（后任伪蒙疆政府要职）', '1937-1945', '', '任伪大同县知事期间，推行保甲制度，强征壮丁，配合日军“治安强化运动”，迫害抗日家属。；任伪大同县知事期间，为日军征收粮款，抓捕抗日军民，并参与“清乡”行动，破坏地下抗日组织。；历任伪大同县知事、伪大同省民政厅长，推行保甲制度，强征壮丁，配合日军“三光政策”，在新荣地区多次组织伪军扫荡抗日根据地。；投靠日军，历任伪大同县知事，在浑源等地推行保甲制度，抓捕抗日分子，强征劳工。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('08083d13bce4561cb640c30eab5f4b06', '马玉堂', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪南宫县警备队中队长、伪清河县税务局长、伪石家庄循环化工园区（原属藁城）联保主任、伪藁城县特务队队长、枣强县伪情报股长、武强县（今属衡水）伪保安团团长', '1940-1945', '', '在现循环化工园区一带强征壮丁，为日军修建军事设施，迫害抗日家属。；专门刺探抗日情报，抓捕地下党员，刑讯逼供，罪大恶极。；专门搜集八路军和抗日政府情报，多次导致抗日人员被捕牺牲，民愤极大。；率伪团配合日军对饶阳、武强交界处的抗日游击区进行反复“清剿”，杀害多名抗日村干部。；率警备队多次袭击抗日村庄，烧杀抢掠，杀害抗日军属，罪大恶极。……（共涉及6个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('89910396846a5e80bbb25b89eaf4ea5a', '马瑞图', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '正定县伪教育科长、石家庄伪商会会长', '1938-1945', '', '为日军统制石家庄商业，强制商户缴纳“慰劳金”，为日军收购战略物资，帮助日军经济掠夺。；推行奴化教育，强迫学校使用日伪教材，宣扬“中日亲善”。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('271e2d7ee2c450d0b2f02a206f435ec3', '马登科', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪偏关县自卫团团长、伪朔县新民会会长', '1940-1945', '', '组织自卫团为日军站岗放哨，协助封锁抗日根据地交通线，并参与抓捕八路军侦察员。；推行奴化教育，组织“新民会”宣传亲日思想，诱骗青年参加伪军。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
