REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('9fd1d91d9a435298996fec8a54da1629', '高云昆', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '天津、辽宁', '天津、辽宁', '[]', '伪咸水沽镇镇长、伪岫岩县教育局长', '1932-1945', '', '在咸水沽一带为日军征粮、抓夫，报告八路军活动，导致多名抗日群众被捕。；原岫岩教育界人士，投日后任伪教育局长，强制推行奴化教育，删除中国历史教材，灌输亲日思想。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
