REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('32d70db4931754aab3d50afa4e5d738a', '高凌霨', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、河北', '北京、天津、河北', '[]', '伪华北政务委员会天津办事处主任（1937-1938）、伪华北政务委员会委员长、伪天津市市长（曾任）、伪华北政务委员会委员长（后任天津伪职）、伪华北政务委员会委员长（曾兼天津地区事务）、伪华北政务委员会委员长（曾辖天津）、伪华北政务委员会委员长（曾驻天津活动）、伪华北政务委员会常委（曾驻通州活动）、伪天津市参议会议长、伪天津治安维持会会长、伪天津特别市公署顾问、伪天津特别市市长、伪河北省省长、伪天津特别市市长、伪河北省长、伪天津特别市市长（1937-1938）、伪天津特别市市长（曾兼管北平周边）、伪天津特别市市长（首任）、伪河北省政府主席（早期）、伪河北省政府委员、伪天津特别市市长（曾涉石家庄）、伪河北省省长兼天津治安维持会会长（1937-1938）、伪河北省省长（1938-1939）、伪河北省省长（辖区含秦皇岛）、伪河北省省长（辖宁河）', '1937-1945', '', '原北洋政客，投日后在华北伪政权任职，间接参与昌平地区伪行政协调。；作为华北伪政权高层，参与对通州地区的统治决策，支持日军经济掠夺和军事镇压。；作为华北伪政权高层，其政策直接影响天津及东丽地区，支持建立各级伪政权，协助日军经济掠夺。；曾任北洋政府总理，后投靠日伪，在天津担任顾问，为日伪政权出谋划策。；日军占领天津后率先附逆，组织伪政权，协助日军接管南开大学校园，将校舍改为日军兵营和仓库，驱逐师生。……（共涉及27个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f68f89c391815a7e962de884c3618ac1', '高凤山', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '枣强县伪军大队长', '1942-1945', '', '率伪军驻守枣强县城，参与多次‘扫荡’，在张秀屯、大营等地制造惨案，杀害无辜百姓。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
