REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('73080ef8b8625b10beaa5a0af1d1f020', '高占奎', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪定县警察局局长、栾城县伪情报组组长', '1939-1945', '', '指挥伪警察抓捕抗日地下党员，破坏地下交通站，参与“清乡”行动。；专门搜集八路军和抗日政府情报，多次导致抗日人员被捕牺牲。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('948107882bd159d6a1053331b9f59ed2', '高占英', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '交城县伪税务局局长、伪卢龙县警察所所长、伪武邑县（今属衡水）知事、伪满城县第一区区长、灵丘县伪税务局局长', '1938-1945', '', '为日军强征各种苛捐杂税，逼死多名交不起税的农民，贪污勒索民财。；巧立名目征收各种苛捐杂税，搜刮民财，上缴日军作为军费。；在满城城关一带为日军征粮派夫，告密抗日积极分子，致使数名群众被杀害。；严刑拷打被捕抗日人员，指认地下党员，破坏卢龙县交通站，导致多名交通员牺牲。；在武邑县为日军征粮派款，组织汉奸武装，袭击抗日游击队。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3a0537dcb964559cbe7de5f03f88f7c1', '高占魁', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪代县自卫团团长、伪华北治安军第2集团军第5旅旅长、伪安国县特务队队长、伪行唐县警备大队大队长、方山县伪新民会会长、灵寿县伪情报组组长、赵县伪新民会会长', '1938-1945', '', '负责方山伪新民会，推行奴化教育，宣传“中日亲善”，强迫群众参加反共集会，收集抗日情报。；组织地方自卫团，协助日军维持占领区秩序，参与“清剿”行动，杀害抗日民兵和群众。；专门刺探八路军情报，化装潜入抗日村庄，诱捕抗日干部，并参与多起屠杀事件。；驻防阜平、涞源一带，多次率部袭击八路军后方医院，杀害伤病员和医护人员，并参与“无人区”制造。；专门刺探八路军活动情报，多次向日军报告抗日武装行踪，导致数次战斗失利。……（共涉及7个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('eeb28cfc33235c9f8f332aab95fe7f43', '高占鳌', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪青龙县自卫团总团长', '1940-1945', '', '组织地方自卫团协助日军防守据点，参与“并村”行动，在路口设卡盘查行人，抓捕抗日嫌疑分子。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2cad9516993b5cedb710bfe401fd05ed', '高干臣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪汾阳县知事、伪离石县保安队队长', '1939-1945', '', '在汾阳（今吕梁汾阳市）建立伪政权，协助日军推行“治安强化”运动。；率伪保安队在柳林一带袭击抗日游击队，杀害抗日干部。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('132ca09a10c5518383fc783d3db3266b', '高德林', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、吉林、河北', '北京、吉林、河北', '[]', '伪东光县税务局长、伪任丘县警备队队长、伪任丘县警察局局长、伪保定地区“剿共”司令、伪保定绥靖军司令、伪保定道尹（管辖博野）、伪冀东保安队司令、伪冀东保安队团长（驻昌黎）、伪冀东保安队大队长（驻唐山）、伪冀东保安队指挥官、伪冀东保安队指挥官、伪保定地区警备司令、伪冀东保安队指挥官、伪华北治安军团长、伪冀东保安队指挥官（沧州一带活动）、伪冀东保安队第三总队队长、伪冀东保安队第五总队队长、伪冀东剿共军司令、伪冀东警备队大队长、伪冀东道尹（管辖唐山、迁安等县）、伪冀东防共自治政府保安队头目、伪治安军师长、伪冀东防共自治政府保安队队长、伪冀中保安司令、伪冀中保安队副司令（活动于石家庄周边）、伪冀中保安队总队长、伪冀中剿共军司令、伪冀中剿共军司令（活动于沧州南部）、伪冀中剿共军司令（活动范围含献县）、伪冀中剿共军司令（涉大厂）、伪冀中道尹兼石家庄警备司令、伪冀南保安司令（活动于邢台、临西）、伪冀南道保安队总队长、伪冀南道保安队指挥官（活动涉及南皮）、伪冀南道尹、伪冀南道尹兼保安司令、伪冀南道尹（管辖衡水、阜城等县）、伪冀南道尹（辖衡水、安平）、伪冀西保安队司令、伪华北治安军某团团长（活动于威县）、伪华北治安军独立团团长、伪华北治安军独立团团长（驻定兴）、伪华北治安军独立团团长（驻防怀柔）、伪华北治安军第1集团军司令、伪华北治安军第1集团军司令（驻防保定地区）、伪华北治安军第20团团长（驻防三河、廊坊一带）、伪华北治安军第3集团军司令、伪华北治安军第一军军长、伪华北治安军第一集团军司令、伪华北治安军第三集团军司令、伪华北治安军邢台地区司令、伪华北治安军邢台道尹公署顾问、伪吉林地区“讨伐”队指挥官（活动于桦甸）、伪唐山保安团团长、伪定县县长、伪徐水县保安队副队长、伪文安新民会会长、伪沧县保安队队长、伪沧州地区‘剿共’总指挥、伪沧州水上警察局局长、伪河北省保安司令、伪河北省保安司令、伪保定绥靖公署参谋长、伪河间县新民会会长、伪津南道保安副司令、伪满辽源县警察署署长、伪磐石县税捐局局长、伪邢台道尹公署顾问兼伪保安司令、冀中伪军第五师师长（活动于饶阳周边）、房山县伪自卫团总团长', '1933-1945', '', '率治安军在怀柔山区“扫荡”，实行“三光”政策，屠杀无辜百姓，抢夺物资，配合日军围剿平北抗日根据地。；组织伪自卫团，协助日军封锁山区，截断抗日物资运输，杀害过路群众。；率伪军多次深入桦甸山区“讨伐”抗联，烧毁村屯，抢夺粮食，并诱降抗联叛徒，破坏抗联组织。；为日军强征苛捐杂税，搜刮民财充作军费，并参与“粮谷出荷”政策，导致磐石地区百姓饿殍遍野。；在辽源县（今双辽市）警察署任职期间，多次率警队抓捕抗联交通员，破坏地下组织，并参与“归屯并户”，烧毁民房，造成大量平民流离失所。……（共涉及75个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
