REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('2d7b1455e7435e93804554794fd6507c', '高文彬', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '辽宁', '辽宁', '[]', '伪满兴城县教育局长', '1936-1945', '', '推行日本奴化教育，强制学校教授日语，删除中国历史内容，在葫芦岛地区毒害青少年。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
