REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('5ba9b438aa8057fe971e7bd39b052daf', '高步云', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西、河北', '山西、河北', '[]', '伪保德县财政科科长、伪偏关县税务局长、伪大同省财政厅长、伪孝义县保安团团长、伪崞县（原平）警备队长、伪忻县自卫团团长、伪朔县警察局局长、伪汾阳维持会会长、伪涞源县新民会会长、伪盂县税务局长、伪阳高县新民会会长、岚县伪军连长、平定县伪维持会会长', '1937-1945', '', '率保安团配合日军对孝义西部山区进行“铁壁合围”，烧毁村庄十余个，抢掠牲畜粮食，并参与活埋抗日军属。；率伪军驻防岚县普明镇，多次袭击八路军游击队，抢劫百姓财物，杀害抗日军属。；日军占领汾阳后出任维持会长，为日军筹集粮款，强征劳役，并告密导致多名抗日群众被捕牺牲。；负责为日军搜刮民财，强征各种苛捐杂税，在新荣地区逼死多名交不起税的农民，并参与鸦片专卖毒害百姓。；组织新民会宣传“大东亚共荣”，诱骗青年参加伪军，并协助日军征集慰安妇。……（共涉及13个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('09079d2052f4508881896aca18db3714', '高步瀛', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '伪山西省第四行政区（阳泉）专员、伪朔县税务局局长、伪阳泉宣抚班班长、繁峙县伪商会会长、静乐县伪税务局长', '1938-1945', '', '组织商会为日军筹措军饷和物资，垄断粮食贸易，从中牟利，打压抗日商户。；为日军推行“以战养战”政策，增设苛捐杂税，强征商业税和土地税，导致商户和农民破产，并将所得款项直接供给日军军需。；为日军强征各种苛捐杂税，搜刮民财，导致百姓负担沉重。；为日军推行“以华制华”政策，组织伪自卫团，强征青年充当伪军，并参与日军对狮脑山等根据地的围剿行动。；随日军进行‘宣抚’活动，散布亲日言论，诱骗民众归顺，破坏抗日宣传，并指认抗日家属。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
