REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('3ac5a443a78a5903bb44040e63d9ec35', '黄南鹏', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津', '北京、天津', '[]', '伪北平市警察局特务科科长、伪华北绥靖军第4军军长', '1939-1945', '', '在北平及海淀地区指挥特务活动，抓捕抗日地下工作者，破坏中共平西根据地联络点；原直系军官，投日后在天津以南地区驻防，协助日军“清剿”冀中八路军。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('bc9eb38525fc5ee9bf32bb94f4a53f81', '齐栋材', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪保定宪兵队翻译官、伪蠡县维持会会长、伪高阳县知事（县长）', '1938-1945', '', '为日军宪兵队充当翻译，参与审讯和酷刑迫害被捕抗日志士。；日军占领初期组织维持会，为日军筹粮派夫，协助建立伪政权，镇压抗日活动。；在任期间推行保甲制度，强征壮丁，搜刮民财，配合日军“三光政策”，多次率伪警包围村庄，杀害抗日家属。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('a96a39ea6e6258e2b8e07a82eb22b15b', '齐燮元', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '北京、天津、河北', '北京、天津、河北', '[]', '伪华北政务委员会治安总署督办、伪华北政务委员会治安总署督办、伪华北治安军总司令、伪华北政务委员会治安总署督办、伪华北绥靖军总司令、伪华北政务委员会治安总署督办（曾驻石家庄）、伪华北政务委员会治安总署督办（管辖唐山驻军）、伪华北政务委员会治安总署督办（管辖唐山）、伪华北政务委员会治安总署督办（管辖河北包括河间）、伪华北政务委员会治安总署督办（管辖邢台）、伪华北政务委员会治安总署督办（辖保定地区）、伪华北政务委员会治安总署督办（驻北平，但影响天津西青）、伪华北政务委员会治安总署督办（驻津）、伪华北治安军总司令、伪华北治安军总司令、伪华北政务委员会治安总署督办、伪华北治安军总司令（兼天津驻军）、伪华北治安军总司令（在天津滨海地区驻军）、伪华北治安军总司令（在密云驻有部队）、伪华北治安军总司令（在昌黎、秦皇岛驻有治安军）、伪华北治安军总司令（在秦皇岛驻有部队）、伪华北治安军总司令（曾在保定莲池一带驻军）、伪华北治安军总司令（曾驻保定指挥）、伪华北治安军总司令（曾驻天津南开区）、伪华北治安军总司令（曾驻天津）、伪华北治安军总司令（活动于冀东含唐山）、伪华北治安军总司令（活动于河北）、伪华北治安军总司令（活动涉及天津）、伪华北治安军总司令（活动范围含冀东）、伪华北治安军总司令（活动范围含通州）、伪华北治安军总司令（涉及唐山）、伪华北治安军总司令（涉及沧县驻军）、伪华北治安军总司令（管辖唐山驻军）、伪华北治安军总司令（管辖涞源伪军）、伪华北治安军总司令（驻天津地区）、伪华北治安军总司令（驻防石家庄）、伪华北绥靖军总司令、伪华北绥靖军总司令（驻天津）、华北伪治安军总司令（管辖河北含石家庄）', '1937-1945', '', '北平沦陷后投敌，任伪华北治安军总司令，组织伪军协助日军清剿抗日武装，在北平及周边地区实施“扫荡”。；原直系军阀，投日后负责华北伪军，在丰台及北平周边配合日军“扫荡”，镇压抗日武装。；在北平及丰台地区组织伪军，协助日军清剿抗日武装，镇压民众反抗。；北洋直系军阀，投日后在北平组建伪治安军（绥靖军），配合日军“扫荡”冀中、平郊抗日根据地，在大兴一带多次清剿抗日武装。；在北平及华北地区组织伪治安军，配合日军扫荡抗日根据地，捕杀抗日军民，破坏地下组织。……（共涉及85个地区的犯罪记录）', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('594de58493505c6a865540aa3dffe1ff', '齐燮元（注：此人为伪华北政务委员会头目，但主要活动在北平，不列）', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '山西', '山西', '[]', '', '', '', '', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('f7f23c136fd45ca89941856a27371529', '齐知政', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '吉林、辽宁', '吉林、辽宁', '[]', '伪吉林省协和会总务部长、伪满洲国长春县县长、伪满锦县（今凌海）县长、伪长春市副市长', '1932-1945', '', '协助市长管理长春，参与“新京”城市规划，驱逐原住民。；在长春、净月地区组织协和会，宣传“日满一体”，监视民众思想，告密迫害反满人士。；原长春县地方士绅，投日后任伪长春县长，在长春经开区（原属长春县）一带推行日伪统治。；在凌海地区强制推行“归屯并户”，制造无人区，配合日军围剿义勇军，征收苛捐杂税。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
REPLACE INTO `traitors` (`Id`, `Name`, `CourtesyName`, `Pseudonym`, `BirthYear`, `DeathYear`, `BirthYearType`, `DeathYearType`, `NativePlace`, `Province`, `AliasesJson`, `IdentityTagsJson`, `Period`, `Faction`, `Summary`, `RelatedIdsJson`, `CreatedAt`, `UpdatedAt`) VALUES ('32ed2e8b4ee35e1a8b9e04b5d7fb3a2c', '齐耀荣', NULL, NULL, NULL, NULL, 'unknown', 'unknown', '河北', '河北', '[]', '伪行唐县知事', '1940-1945', '', '在行唐县强征粮食，抓捕抗日群众，配合日军修建封锁沟和碉堡。', '[]', '2026-09-09 00:00:00.0000000', '2026-09-09 00:00:00.0000000');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d4544de471b85cacb49c6e5a42167298', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪蒙古联合自治政府副主席', NULL, '原东北军军官，1933年投靠日军，组建伪蒙古军，在乌兰察布、丰镇等地协助日军扫荡抗日武装，镇压民众，后任伪蒙疆政府要职。', '内蒙古乌兰察布_丰镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('45d4fa3740a05a5abbc25171059bd2f1', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙古联合自治政府主席', NULL, '蒙古王公，长期与日本关东军勾结，在乌兰察布地区推行“蒙古自治”，建立伪政权，为日军提供兵员和情报，协助统治当地。', '内蒙古乌兰察布_丰镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('446e7af4fcc8502bba60a516e9503095', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙古军参谋长、伪蒙古联合自治政府政务院院长', NULL, '参与伪蒙疆政权建设，在丰镇、乌兰察布等地组织伪行政机构，配合日军“治安强化”运动，迫害抗日军民。', '内蒙古乌兰察布_丰镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b94098773d06515e94bd2cbf1d97b7fb', 'a6fe2171a37f59a0a1a45779d088abd0', 1937, '伪蒙古军第1师师长', NULL, '率伪蒙古军在乌兰察布、丰镇一带驻防，多次参与对八路军和游击队的“围剿”，烧杀抢掠，残害百姓。', '内蒙古乌兰察布_丰镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('90ea8f3f9ef95e36a119ffd0e6dc3eeb', '3613c9792d855571bd9dcedeb3091e5e', 1938, '伪丰镇县县长', NULL, '任伪丰镇县长期间，推行日伪苛政，强征粮税，抓捕抗日志士，协助日军建立保甲制度，镇压当地反抗。', '内蒙古乌兰察布_丰镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fe3a11d9e4cf594e94998b2aa10b484a', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西联军司令', NULL, '原土匪出身，投日后在乌兰察布、丰镇一带活动，率伪军配合日军进攻大青山抗日根据地，劫掠民众，罪行累累。', '内蒙古乌兰察布_丰镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2501309875ea519daf564980a4497920', '7919fe83935950c484b84fc165626e11', 1939, '伪东亚同盟军总司令', NULL, '原国民党将领，投敌后在乌兰察布地区组织伪军，参与对抗日武装的“讨伐”，后因内部矛盾被日军处决。', '内蒙古乌兰察布_丰镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('64fcc9a9d3595922b775737ae179d6d9', '816af17b0eb75cd2af61c252b0bc97f8', 1938, '伪蒙古军第2师师长', NULL, '率部驻防丰镇周边，多次袭击抗日游击队，杀害抗日干部，强征民夫修筑日军工事。', '内蒙古乌兰察布_丰镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d4a25eeafee35534b872fe88870a8144', '4bd9cd1ed4f65f568f7afde7603fda36', 1939, '伪乌兰察布盟盟长', NULL, '投靠日伪，任伪盟长期间，推行奴化教育，组织伪警察镇压抗日活动，为日军提供物资和劳役。', '内蒙古乌兰察布_丰镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ca8c19978c585ba989dcfd3b3c0f0551', 'f8128d92a5455f2886dae039c7903166', 1939, '伪晋北自治政府参议（后投敌）', NULL, '原晋军将领，被俘后变节，在乌兰察布地区协助日伪收编散兵，参与“清乡”行动。', '内蒙古乌兰察布_丰镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d9e215643a1a54fd8a2b9298ba129a96', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪蒙古联合自治政府副主席', NULL, '原为热河地方军阀，1933年投靠日军，组建伪蒙古军，在察哈尔、绥远（含乌兰察布、兴和一带）配合日军进攻抗日武装，后任伪蒙疆政府要职，协助日本殖民统治。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9a1eebfb7813515b8c653d82980d3e2b', '03751651c36952668c9b65b923b9c221', 1933, '伪蒙古联盟自治政府主席、伪蒙疆联合自治政府主席', NULL, '蒙古王公，长期策划“蒙古独立”，1936年成立伪蒙古军政府，1939年任伪蒙疆政府主席，其势力覆盖乌兰察布、兴和地区，为日军提供兵员和情报，镇压抗日活动。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b91acce1854f53ac9ed6dae3498c6768', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令、伪东亚同盟军总司令', NULL, '原绥远地方土匪/军阀，1937年投日，在乌兰察布、兴和及绥远地区组织伪军，配合日军扫荡抗日根据地，残害百姓，后任伪绥西联军司令。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c3cd7004d55e57e7ab476eade1b727d6', '7919fe83935950c484b84fc165626e11', 1938, '伪东亚同盟军副总司令', NULL, '原东北军将领，后投靠日军，在绥东（含兴和、乌兰察布）一带协助日军围剿八路军游击队，参与“治安肃正”行动。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('812947de04385924b45d4486b4ab8735', '4521f356ec205b2c8a2e82a1253b1d13', 1936, '伪蒙古军第1军军长', NULL, '蒙古族上层，投靠德王和日军，率伪蒙古军在乌兰察布北部及兴和地区驻防，协助日军镇压抗日民众，征收粮草。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e602ddfa2f1b5d28b671c721c70f112d', 'd20dc98a469e5262ac91c570963efebd', 1937, '伪蒙古军第2军军长', NULL, '伪蒙古军高级军官，活动于绥远东部（含兴和、商都、化德一带），配合日军进攻大青山抗日游击队，参与“清乡”屠杀。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('445a2fa1abfc514da21c3c06ec0a6082', 'a6fe2171a37f59a0a1a45779d088abd0', 1938, '伪蒙古军第3军军长', NULL, '伪蒙古军将领，在乌兰察布地区驻防，协助日军维持殖民秩序，抓捕抗日地下工作者，参与经济掠夺。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('37bb10b2dc3f53938170403e938bb5a9', '7893cdab2278525ca46f22df1ae1de18', 1939, '伪蒙古军第4军军长', NULL, '伪蒙古军高级指挥官，活动于乌兰察布南部及兴和一带，多次率部袭击八路军大青山支队，破坏抗日政权。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d2b2604388de53b0bf51358691f291a3', '10cf9499b86c5eb48e46960674ae33ce', 1939, '伪蒙古军第5军军长', NULL, '伪蒙古军将领，在乌兰察布、兴和地区参与“扫荡”，强征民夫修筑公路和碉堡，配合日军推行“保甲制”。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4a1e60f5de25505eb63fe5f79dfef03d', '6c3bbf1716b853a4adbe3aae1a990cad', 1939, '伪蒙疆政府兴和县县长', NULL, '在兴和县任伪县长期间，为日军征粮派款，组织伪警察镇压抗日群众，协助日军建立情报网。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0758a8a10bf154f69e107f04c7da0874', '3fbf1154caed5e6491d769fb56464132', 1940, '伪绥东保安司令（后投日）', NULL, '原国民党军官，1940年投日，在乌兰察布东部（兴和、丰镇）组织伪保安队，配合日军“蚕食”抗日根据地。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('27ae9e6f90bf5917bebf86918835d455', 'dd16228ed77d5347a9db49d43cc1ddae', 1941, '伪兴和县警察署署长', NULL, '在兴和县任伪警察署长，抓捕抗日军民，严刑逼供，直接参与多起屠杀事件。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a6874fbed86e5d0cb0b95a3bb353d51b', '54c6652a4c7650c2afc80fa79ef135c1', 1940, '伪乌兰察布盟公署参事', NULL, '在乌兰察布盟伪政权中负责“宣抚”工作，为日军宣传“大东亚共荣”，协助推行奴化教育。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('603bf61d1967559abdc09bdeba3edb69', 'f8128d92a5455f2886dae039c7903166', 1939, '伪晋北政厅顾问（兼绥东事务）', NULL, '原晋军将领，投日后任伪职，参与对乌兰察布、兴和地区的军事“讨伐”和物资掠夺。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('54ff2670bac753b5829d0adb11862e18', 'dbaf8cd68c5d5e3caa0978b7e06efe50', 1941, '伪蒙古军第6师师长', NULL, '率伪蒙古军第6师驻防兴和、尚义一带，多次袭击八路军游击队，杀害抗日干部和群众。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7c386e65d0a2577fa803ad3405d0ab8c', '987a275226335a46b1a0fdc3d18055ae', 1939, '伪蒙疆政府内政部长', NULL, '作为伪蒙疆高层，参与制定对乌兰察布、兴和地区的“治安强化”政策，支持日军“三光”作战。', '内蒙古乌兰察布_兴和');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1e6ca903240d57e682a8ac3080fe1947', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪蒙古联盟自治政府副主席', NULL, '原为热河土匪，后投靠日军，任伪蒙古军总司令，参与侵占绥东（含凉城）地区，协助日军镇压抗日力量，推行殖民统治。', '内蒙古乌兰察布_凉城');
