INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e1ef0417017850fa8c1cb2eb2a7021b4', '987a275226335a46b1a0fdc3d18055ae', 1936, '伪蒙古军政府参谋部长、伪蒙疆政府政务院院长', NULL, '参与伪蒙政权决策，协助日军在乌兰察布、凉城等地推行保甲制度，组织伪警察镇压抗日活动。', '内蒙古乌兰察布_凉城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1325f97b639c53a98965b346ebcd3d6f', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西联军总司令、伪东亚同盟军总司令', NULL, '绥远土匪出身，投日后率伪军多次进犯凉城、蛮汉山一带，配合日军扫荡八路军大青山支队，烧杀抢掠。', '内蒙古乌兰察布_凉城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a4e02b6047115d9d8d73064d0b9b70e8', '816af17b0eb75cd2af61c252b0bc97f8', 1938, '伪凉城县县长', NULL, '任伪凉城县长期间，为日军征粮派款，组织伪警察抓捕抗日地下人员，破坏中共凉城抗日根据地。', '内蒙古乌兰察布_凉城');
