INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('af3663819b8d5dcb94e325ce90a371b4', '7919fe83935950c484b84fc165626e11', 1938, '伪东亚同盟军副司令', NULL, '原东北军将领，投日后在绥东、凉城一带收编土匪，配合日军进攻大青山抗日游击根据地。', '内蒙古乌兰察布_凉城');
