INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d8afd4df82205ebe92000fc0de75ad3f', '9a5a1ebde04057d5a145d3ac6bf8014c', 1938, '伪绥远省防共自治军头目', NULL, '原国民党军官，投日后在凉城、和林格尔一带组织伪军，协助日军建立据点，破坏抗日交通线。', '内蒙古乌兰察布_凉城');
