INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('266878a7574c5771be68d45c50f8f2ad', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、蒙疆联合自治政府副主席', NULL, '原东北军将领，后投日，在化德一带协助德王组建伪蒙古军，多次率部进攻察哈尔、绥远抗日武装，镇压抗日力量。', '内蒙古乌兰察布_化德');
