INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9aa6300a8fb85702a344e52c308002ab', '03751651c36952668c9b65b923b9c221', 1933, '伪蒙疆联合自治政府主席、伪蒙古军总司令', NULL, '在察哈尔右翼前旗及乌兰察布地区积极推行日本侵略者的“蒙疆自治”政策，组织伪蒙古军配合日军进攻抗日武装，并在当地实施殖民统治和奴化教育。', '内蒙古乌兰察布_察哈尔右翼前旗');
