INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('12cd36231bf652d981aa4b4ee0f1aa5c', '987a275226335a46b1a0fdc3d18055ae', 1938, '伪蒙疆联合自治政府政务院院长', NULL, '在乌兰察布及察哈尔右翼前旗地区推行伪政权法令，组织汉奸团体协助日军维持治安，强征民夫和粮食，迫害抗日军民。', '内蒙古乌兰察布_察哈尔右翼前旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f651f0c1ac8f5e33920069a35018369d', '66f4a5c280815acc8e8258aae4d43407', 1937, '伪察哈尔盟盟长、伪蒙疆政府参议', NULL, '在察哈尔右翼前旗一带为日军效劳，参与建立伪旗公署，强迫当地民众“归顺”日伪，并协助日军围剿八路军游击队。', '内蒙古乌兰察布_察哈尔右翼前旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d46b8d2fa2865c5eb236cb9bff47267f', 'd20dc98a469e5262ac91c570963efebd', 1939, '伪察哈尔右翼前旗旗长', NULL, '直接管理察哈尔右翼前旗日伪政权，向日军提供当地抗日活动情报，强征壮丁和牲畜，实施保甲连坐制度，镇压反抗民众。', '内蒙古乌兰察布_察哈尔右翼前旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('81aa00e7fff4508398fd014200d53247', '4858ca8309a454e28d3ed02c77c72106', 1937, '伪察哈尔盟副盟长、伪蒙古军师长', NULL, '在乌兰察布东部及察哈尔右翼前旗地区率伪军参与“扫荡”，烧毁村庄，杀害抗日干部，并协助日军建立特务情报网。', '内蒙古乌兰察布_察哈尔右翼前旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e8f68602483754f3b4513b89a2cad508', '0bdad7ed3ff95e64824a390e109d259d', 1940, '伪察哈尔右翼前旗警察署署长', NULL, '指挥伪警察在旗内搜捕抗日地下工作者，严刑逼供，并配合日军进行“治安强化运动”，残害无辜百姓。', '内蒙古乌兰察布_察哈尔右翼前旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b7dcd303104253c2a890e9a9ed933d0e', '2b916287eb355472aa494ce7ca93f994', 1941, '伪蒙疆政府驻乌兰察布办事处主任', NULL, '负责协调日伪军与地方汉奸势力，在察哈尔右翼前旗推行“以华制华”政策，组织汉奸武装“自卫团”袭扰抗日根据地。', '内蒙古乌兰察布_察哈尔右翼前旗');
