INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('15a6c532cf1e5cf2993fe71a670b2de9', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '蒙疆联合自治政府副主席/伪蒙古军总司令', NULL, '原东北军将领，后投日，在绥东（含集宁一带）率伪蒙古军协助日军进攻抗日武装，镇压民众。', '内蒙古乌兰察布_集宁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('84a148ba67945c2fac2244346e602428', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军司令', NULL, '绥远地区土匪出身，投日后在乌兰察布、集宁周边为日军效力，参与扫荡和清乡，残害抗日军民。', '内蒙古乌兰察布_集宁');
