INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e07e3b8263525b18b9bc35b3e7411aec', '9f3e530b56db5b60aa5697cadac48a6e', 1939, '伪蒙古军旅长', NULL, '任伪蒙古军旅长，活动于鄂尔多斯及乌海一带，参与镇压当地抗日游击队，掠夺牲畜和粮食。', '内蒙古乌海_海南');
