INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fd1d5497b4ba5ef2b953b03723b6334d', '503d6795918c590ea63fa33e7df5978d', 1932, '伪兴安南省省长', NULL, '在兴安南省（含乌兰浩特地区）协助日军实施“蒙地分治”，征收粮草，迫害抗日志士。', '内蒙古兴安_乌兰浩特');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('06ca7705c5865bb78d968029d3806c5d', 'e9d6895d49625d10aff374a3c26c6105', 1932, '伪兴安西省省长', NULL, '在兴安盟西部及乌兰浩特周边配合日军清乡，组织伪警察队，参与围剿东北抗联部队。', '内蒙古兴安_乌兰浩特');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0688c6895c6b5f4fafdecf36b3c5052a', '22705a4d09735e009b8805878930c287', 1935, '伪兴安总省参事官', NULL, '在乌兰浩特地区为伪满政权效力，参与制定“蒙人治蒙”政策，协助日军控制蒙古族民众，破坏抗日组织。', '内蒙古兴安_乌兰浩特');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('adb0720d14c4599e9d00b5436d9db9ab', '7893cdab2278525ca46f22df1ae1de18', 1938, '伪兴安军管区司令', NULL, '指挥伪兴安军驻守乌兰浩特，多次配合日军进攻抗联三路军，屠杀抗日军民。', '内蒙古兴安_乌兰浩特');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1ed72975b1c55cd596c8122105967a37', '2fae5c65dd395f52a2183aabf63f814d', 1940, '伪兴安军第1师师长', NULL, '率伪军在兴安盟、乌兰浩特一带执行“讨伐”任务，制造多起惨案，强征民夫修筑军事工事。', '内蒙古兴安_乌兰浩特');
