INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9367b28ba34954969323b3d884514851', '03751651c36952668c9b65b923b9c221', 1933, '伪蒙疆联合自治政府主席', NULL, '在内蒙古地区组织伪蒙政权，与日本关东军合作，推行“蒙疆自治”，协助日军统治内蒙古中西部，但未直接管辖兴安、阿尔山地区，主要活动于锡林郭勒、乌兰察布等地。', '内蒙古兴安_阿尔山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('debf7bff48495bb5912d4793ffedce80', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令', NULL, '投靠日军，任伪蒙古军总司令，参与镇压内蒙古东部抗日力量，其部队曾活动于兴安盟及阿尔山周边地区，配合日军“讨伐”东北抗日联军。', '内蒙古兴安_阿尔山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('51f26e530bbf5823a9b236755288011c', '0783da7f980d5f62939afcf55f8baaa9', 1932, '伪兴安军指挥官', NULL, '日本关东军扶植的蒙古族汉奸，参与组建伪兴安军，在兴安、阿尔山一带协助日军维持治安，围剿抗日武装。', '内蒙古兴安_阿尔山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('99b7ac9d7eb35731bf161f48ff936267', 'b62352fbc8f85eb6b40ef0dc25685166', 1932, '伪兴安军高级军官', NULL, '甘珠尔扎布之弟，任伪兴安军要职，在兴安盟地区协助日军进行军事行动，镇压当地抗日活动。', '内蒙古兴安_阿尔山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('25da51d1aed35532898579dd2fd4e968', '7893cdab2278525ca46f22df1ae1de18', 1932, '伪兴安南省省长', NULL, '伪满洲国兴安南省（辖今兴安盟及阿尔山部分地区）省长，推行日伪殖民政策，强征劳工，协助日军统治当地蒙汉民众。', '内蒙古兴安_阿尔山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5b78caeb9a7e5183af0e47b5ec7305b5', '991e1aa742a25f1aa485f74d60be5d1c', 1932, '伪兴安南省警务厅长', NULL, '在兴安南省（含阿尔山地区）担任伪警务厅长，组织伪警察镇压抗日分子，抓捕并杀害抗联地下工作人员。', '内蒙古兴安_阿尔山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6c8e7e512ca457e7be57aa2b257ce389', '542aa343469854edb392ad575fba43d2', 1933, '伪兴安南省参事官', NULL, '投靠日伪，在兴安南省（阿尔山一带）任参事官，协助日军推行“治安肃正”，迫害当地抗日群众。', '内蒙古兴安_阿尔山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7582fc5e175f55a795ad0b7b37b6f5ea', 'e45a1ffbbd21578983624b349522ac85', 1934, '伪兴安军团长', NULL, '率伪兴安军驻扎于阿尔山附近，参与对苏联、蒙古边境的侦察及对抗日游击队的围剿。', '内蒙古兴安_阿尔山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('55f464785e3e59418e8de769e17bc7cb', 'b3d853b6e1e3564bb50b6ff7577f9c76', 1932, '伪兴安东省省长', NULL, '伪满洲国兴安东省（部分辖区与兴安盟接壤）省长，虽主要活动于扎兰屯一带，但曾参与协调兴安、阿尔山地区的日伪军事行动。', '内蒙古兴安_阿尔山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('05d329dc233b536b8a663590f396e530', 'b61343d836f0555fb4ed47080488cff3', 1935, '伪兴安军骑兵师长', NULL, '在兴安盟及阿尔山地区率伪骑兵师配合日军“扫荡”，破坏抗联根据地，掠夺当地物资。', '内蒙古兴安_阿尔山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7932003d8dbb5e15a3c75d4767781896', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令', NULL, '原东北军军官，投靠日军后组建伪蒙古军，在包头及绥远地区协助日军进攻抗日武装，参与建立伪蒙疆政权，镇压抗日力量。', '内蒙古包头');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2944523fda965f0b943865cddc79c8c4', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙疆联合自治政府主席', NULL, '蒙古王公，策划内蒙古独立，与日军合作成立伪蒙疆政权，管辖包括包头在内的绥远地区，推行奴化教育，协助日军统治。', '内蒙古包头');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('abce8f613c715cf488d4d20638fcc3c1', '987a275226335a46b1a0fdc3d18055ae', 1938, '伪蒙疆政府政务院院长', NULL, '曾任伪蒙疆政府高级官员，在包头地区协助日军推行殖民政策，管理行政事务，镇压抗日活动。', '内蒙古包头');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eedb1fe477bc5a4f902130b015d618d3', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令', NULL, '原土匪出身，投日后在包头、五原一带组建伪军，多次配合日军进攻傅作义部抗日军队，残害百姓。', '内蒙古包头');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7f2b9f812dcf506b964679ff48cbf1bd', '7919fe83935950c484b84fc165626e11', 1938, '伪东亚同盟军总司令', NULL, '原东北军将领，叛变投日后在包头地区组织伪军，参与日军对河套地区的扫荡，后因内部矛盾被日军处决。', '内蒙古包头');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d6f8bcb39a9f547f8a52493ff37e1ec0', '816af17b0eb75cd2af61c252b0bc97f8', 1939, '伪包头市市长', NULL, '在日军占领包头期间出任伪市长，协助日军维持治安，推行保甲制度，强征劳工，为日军提供物资。', '内蒙古包头');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0413c51596c15e54aed751cba3f067ee', '54c6652a4c7650c2afc80fa79ef135c1', 1940, '伪包头警察局局长', NULL, '在包头伪政权中负责警察事务，抓捕抗日地下人员，协助日军进行特务活动，镇压民众反抗。', '内蒙古包头');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d9fcd410bb91577c943d441e18622f55', '30baf331012c585189c2c57b3f3a8326', 1938, '伪包头商会会长', NULL, '投靠日军后控制包头商会，为日军筹集军饷和物资，强迫商户缴纳各种捐税，从中牟利。', '内蒙古包头');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ff33013389ac5b3c9508ac5216b32b62', 'cdaf596844505e57823345c13fefecf0', 1938, '伪蒙疆银行包头分行经理', NULL, '负责发行伪蒙疆货币，搜刮包头地区财富，配合日军经济掠夺，导致当地通货膨胀，民生凋敝。', '内蒙古包头');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3b7897696e6e5eb3ad4106e59a854942', '7893cdab2278525ca46f22df1ae1de18', 1937, '伪蒙古军参谋长', NULL, '蒙古族军官，投靠德王后任伪军参谋长，在包头地区参与军事指挥，协助日军围剿抗日游击队。', '内蒙古包头');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0d14cbffc5b557b595950bcfe9375f3c', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令', NULL, '原东北军将领，投靠日军后组建伪蒙古军，在绥远（含包头、东河）地区配合日军进攻抗日武装，参与“治安肃正”行动，残害抗日军民。', '内蒙古包头_东河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2304140058ca54bf88e2fd271c053530', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙疆联合自治政府主席', NULL, '蒙古王公，与日军合作建立伪蒙疆政权，其势力范围覆盖包头、东河地区，推行奴化教育，为日军提供情报和物资支持。', '内蒙古包头_东河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bc2f3f7b547a5f0798ef55f779bab7fd', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军司令', NULL, '绥远地方军阀，投日后在包头、东河一带活动，协助日军围剿大青山抗日游击队，参与“清乡”和掠夺资源。', '内蒙古包头_东河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9919a06a12eb55a38b5acd850ec36440', '7919fe83935950c484b84fc165626e11', 1938, '伪东亚同盟军总司令', NULL, '原国民党将领，叛变投日后在绥远地区（含包头）组织伪军，多次进攻八路军大青山支队，制造多起惨案。', '内蒙古包头_东河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e6d4eb67394f59c4b34e07d1dfe8ded0', '9ca78ea19f3f58189e90d8eaa6f68a75', 1939, '伪蒙疆政府包头市市长', NULL, '蒙古贵族，任伪包头市长期间，推行日伪法令，强征劳工，协助日军控制包头及东河地区经济命脉。', '内蒙古包头_东河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('86616df3395358e9bae1a74988e1e798', '0b5dc00f69d853ca9746c8bfb7d3305f', 1940, '伪包头警察局局长', NULL, '在包头、东河地区充当日军鹰犬，搜捕抗日地下工作者，镇压民众反抗，参与“特别治安”行动。', '内蒙古包头_东河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fe7a3b64ec9b53baaae9af656b043758', '25403a79f8335f3e96fc8451f78bbb99', 1938, '伪包头保安队队长', NULL, '率伪保安队在东河一带巡逻，配合日军“扫荡”，抢劫民财，杀害抗日家属，罪行累累。', '内蒙古包头_东河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ba7aa34e0e2f5eed8fc15ded1f882591', 'f8128d92a5455f2886dae039c7903166', 1941, '伪绥远省公署顾问', NULL, '原晋军将领，投日后任伪绥远省顾问，参与策划对包头、东河地区的“强化治安”运动，为日军出谋划策。', '内蒙古包头_东河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3f469827da885912a533b0791b4b3f3f', '816af17b0eb75cd2af61c252b0bc97f8', 1939, '伪包头商会会长', NULL, '充当日伪经济汉奸，在包头、东河地区强制推行“配给制”，搜刮粮食和物资供给日军，压迫商户。', '内蒙古包头_东河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('51356924b7015830a931678aab034921', 'ca1777c7d53f5030baa885e371b5244b', 1937, '伪东河区维持会会长', NULL, '日军占领包头初期，在东河组织维持会，为日军带路、提供民夫，协助建立伪政权，欺压百姓。', '内蒙古包头_东河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bfc0f5c07ea856acbe7a3ff393490bce', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪蒙古联合自治政府副主席', NULL, '原东北军将领，1933年投靠日军，组建伪蒙古军，配合日军进攻察哈尔、绥远（今内蒙古中西部），在包头、九原一带驻军并协助日军清剿抗日武装，后任伪蒙疆政权要职。', '内蒙古包头_九原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0da46909aa9c55889b1c36250492d418', '03751651c36952668c9b65b923b9c221', 1933, '伪蒙古联盟自治政府主席、伪蒙疆联合自治政府主席', NULL, '内蒙古王公，策划内蒙古独立，1936年成立伪蒙古军政府，后与日军合作，在包头、九原地区推行殖民统治，建立伪政权机构，协助日军征兵征粮。', '内蒙古包头_九原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('edfc13fa89065e71be4208eaa3f69321', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙古军参谋长、伪蒙疆政府政务院院长', NULL, '曾任伪蒙古军高级军官，参与指挥伪军在包头、九原一带对抗傅作义部及八路军，后负责伪蒙疆政权行政事务，推行奴化教育。', '内蒙古包头_九原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ecaba42331195a3c904e7168196b665a', 'a6fe2171a37f59a0a1a45779d088abd0', 1938, '伪蒙古军第1师师长', NULL, '率伪蒙古军驻扎包头、九原地区，配合日军扫荡抗日游击队，多次参与围剿大青山抗日根据地，残害抗日军民。', '内蒙古包头_九原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('80bb39ea28b15a48ae4813fa7b90cfb5', '43144196b1f4559fb246a1a5759d567e', 1939, '伪包头市公署市长', NULL, '任伪包头市长期间，为日军征集物资、强征劳工，在九原区推行保甲制度，镇压抗日地下活动，协助日军建立特务组织。', '内蒙古包头_九原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7805c09f96e55ee1a62a6777bde15dfd', '54c6652a4c7650c2afc80fa79ef135c1', 1940, '伪包头警察局局长', NULL, '指挥伪警察在包头、九原地区搜捕抗日分子，破坏地下交通线，多次参与日军“治安强化运动”，杀害无辜百姓。', '内蒙古包头_九原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2689e60147865555bc8c403e332e54b7', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令', NULL, '原土匪武装头目，投日后在包头、九原一带组建伪军，配合日军进攻绥西抗日力量，劫掠百姓，曾参与围攻大青山支队。', '内蒙古包头_九原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2f6b4210eabb568e99459f228069034c', '816af17b0eb75cd2af61c252b0bc97f8', 1939, '伪蒙古军第9师师长', NULL, '率部驻防九原区，协助日军修建军事工事，参与“扫荡”萨拉齐、固阳等地，杀害抗日干部和群众。', '内蒙古包头_九原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('30636e7f1f715fa6a1f09e2d98adf06a', '3e3a95a66cd25e84bf924d6a800e9f57', 1941, '伪包头保安队队长', NULL, '负责包头及九原地区治安，为日军提供情报，逮捕抗日志士，参与镇压1942年包头工人罢工。', '内蒙古包头_九原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a8f62e9c4140584399a51e2f73e09c06', '25403a79f8335f3e96fc8451f78bbb99', 1940, '伪九原区区长', NULL, '在九原区推行日伪法令，强征粮食和壮丁，组织汉奸情报网，向日军报告八路军活动，导致多名游击队员牺牲。', '内蒙古包头_九原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c1bc3056d5e25c88a98dbf4464bd694c', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令', NULL, '原东北军将领，1933年投靠日军，组建伪蒙古军，任总司令，配合日军进攻绥远、包头等地，镇压抗日力量，协助日本殖民统治内蒙古地区。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5dc68d05b71b54519b35a4e94fed2832', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙古联盟自治政府主席', NULL, '蒙古王公，1936年投日，组织伪蒙古军政府，后任伪蒙古联盟自治政府主席，与日军合作，在包头及内蒙古西部推行殖民政策，招募汉奸充实伪政权。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3c7a0e0b42905e98bd93dae9e4f61a05', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙古军参谋长', NULL, '曾任伪蒙古军参谋长，协助李守信、德王组织伪军，参与对包头、固阳等地的“扫荡”，迫害抗日军民。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e1270050558d51a5b074349ae5539796', 'a6fe2171a37f59a0a1a45779d088abd0', 1938, '伪蒙古军第1师师长', NULL, '率伪蒙古军驻扎包头地区，配合日军清乡、征粮，捕杀抗日地下工作者，参与“治安强化运动”。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bd27f09dd84e56cb93a932cfe33c5c27', '10cf9499b86c5eb48e46960674ae33ce', 1938, '伪蒙古军第2师师长', NULL, '在包头、萨拉齐一带活动，协助日军建立伪保甲制度，强征民夫修筑工事，镇压民众反抗。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9856e4806de55ef7be805e601b9a9e58', '7893cdab2278525ca46f22df1ae1de18', 1939, '伪蒙古军第3师师长', NULL, '率部驻防包头西郊，多次参与对抗日游击队的围剿，掠夺当地资源供给日军。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('028709b113ea5db984e5a4bd53b5ecaf', '3fbf1154caed5e6491d769fb56464132', 1940, '伪包头市公署市长（投日后）', NULL, '原国民党军官，被俘后投敌，任伪包头市长，推行日伪法令，组织汉奸商会，为日军筹集物资，迫害爱国人士。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0355c883eac350d8a7c0a9a5e94085f6', '54c6652a4c7650c2afc80fa79ef135c1', 1941, '伪包头市警察局局长', NULL, '负责包头日伪治安，抓捕抗日嫌疑犯，刑讯逼供，协助日军特务机关破坏地下抗日组织。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7860459188815cfc83a9e617e6638734', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令', NULL, '土匪出身，投日后在包头、五原一带活动，组建伪绥西自治联军，配合日军进攻河套地区，烧杀抢掠。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9a73a130c7f4584eb760695b25b0429c', '7919fe83935950c484b84fc165626e11', 1938, '伪东亚同盟军第1军军长', NULL, '原东北军团长，投日后在包头周边收编散兵游勇，充当日军鹰犬，参与“扫荡”大青山抗日根据地。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('34769b6914265d0c861ab166e7c80aab', '770d3e64cb4656b28a1fda14d4a1b76e', 1940, '伪包头保安队队长', NULL, '负责包头城防巡逻，协助日军搜查抗日物资，多次带路袭击游击队据点。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4c0b15cf516e5c5a826b20c9a871479c', 'cdaf596844505e57823345c13fefecf0', 1937, '伪包头维持会会长（初期）', NULL, '日军占领包头初期，组织维持会，为日军征粮派款，提供劳役，协助建立伪政权。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a64c9462096b5ca8a39135cec855a01b', '39752f9d06bc5f4a957d54bb48b6728c', 1938, '伪包头商会会长', NULL, '充当日伪经济汉奸，强制商户使用军票，垄断皮毛、粮食贸易，为日军搜刮战略物资。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2993f20086aa5df2a558cf2e4419c965', '03563b762eb255d485ff04d0e30b304d', 1941, '伪包头税务局局长', NULL, '为日伪征收苛捐杂税，盘剥百姓，将税款直接供给日军军需。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2545e9d0dd1455f0807659138b458f88', 'bacfbb3e0b29576fa99026b1dc526ad3', 1942, '伪包头教育督学', NULL, '推行奴化教育，强制学校教授日语，删除中国历史内容，迫害爱国教师。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('348a7670b39752d5828398fe00ba0764', 'f8128d92a5455f2886dae039c7903166', 1943, '伪绥远省公署参事（投日后）', NULL, '原晋军将领，被俘投敌，在包头参与伪省政，协助日军“以华制华”政策。', '内蒙古包头_包头稀土高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5dcfed29d3515209962418831f8238d9', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令', NULL, '原为东北军军官，后投靠日军，组建伪蒙古军，在绥远（含固阳、包头）一带配合日军进攻抗日武装，镇压抗日力量。', '内蒙古包头_固阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('030ed238e848507e9774b2fba9e2b877', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙疆联合自治政府主席', NULL, '蒙古王公，与日军合作建立伪蒙疆政权，其势力范围包括包头、固阳等地，推行日伪统治，征粮派款，协助日军清剿抗日游击队。', '内蒙古包头_固阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('13dbe34a19415df4849554d3ad322849', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军司令', NULL, '原土匪出身，投日后在包头、固阳一带组织伪军，多次进攻大青山抗日根据地，残害抗日军民，抢劫百姓财物。', '内蒙古包头_固阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c6f4f1cbbf875fd1971a25bff07f19b7', '816af17b0eb75cd2af61c252b0bc97f8', 1938, '伪固阳县县长', NULL, '任伪固阳县长期间，推行日伪保甲制度，强征壮丁，搜刮粮食，配合日军扫荡固阳周边抗日游击区，逮捕抗日人员。', '内蒙古包头_固阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c5f9739383cf5f069c6ee831fd92e9d2', 'cdaf596844505e57823345c13fefecf0', 1939, '伪包头市公署市长', NULL, '投靠日军任伪包头市长，管理日伪行政，协助日军建立殖民秩序，镇压包头及固阳地区抗日活动，强制推行奴化教育。', '内蒙古包头_固阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('de26fd7abca654498f6499a539145b04', '54c6652a4c7650c2afc80fa79ef135c1', 1940, '伪包头警察局局长', NULL, '任伪包头警察局长期间，大肆搜捕抗日地下工作者，严刑逼供，破坏抗日组织，在固阳、包头一带制造多起血案。', '内蒙古包头_固阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e953131609c059209ee29f3ffef81e26', '25403a79f8335f3e96fc8451f78bbb99', 1939, '伪固阳保安队队长', NULL, '率伪保安队多次配合日军围剿固阳南山抗日游击队，杀害抗日战士及群众，强征民夫修筑碉堡和公路。', '内蒙古包头_固阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9c9c7589da0651608bd7ec6eea679b5b', 'f8128d92a5455f2886dae039c7903166', 1940, '伪绥西联军副司令（投日后）', NULL, '原晋军将领，后投靠日军，在包头、固阳一带协助王英指挥伪军，参与对大青山根据地的“扫荡”行动。', '内蒙古包头_固阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8a3e5a2e24c558dfa36af1c3ed9b14f4', '7919fe83935950c484b84fc165626e11', 1937, '伪蒙古军第1师师长', NULL, '率伪蒙古军驻防固阳、武川一带，多次袭击抗日游击队，为日军提供情报，欺压当地蒙汉百姓。', '内蒙古包头_固阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bb9fc481ac2e53328b9c3e04db76473c', 'a6fe2171a37f59a0a1a45779d088abd0', 1938, '伪蒙古军第3师师长', NULL, '在包头、固阳地区驻防，参与日军“治安肃正”行动，屠杀抗日嫌疑分子，强征马匹和粮草。', '内蒙古包头_固阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4c8ca72245955a5a9650f5cc38e79c8e', '142ed91c1ea95b6d922d76d4627e2b83', 1936, '伪蒙古军总司令', NULL, '土默特右旗人，早年投靠日军，组建伪蒙古军，任总司令，配合日军进攻绥远地区，参与建立伪蒙疆政权，镇压抗日力量。', '内蒙古包头_土默特右旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e83e2be3fcb35efeb5e404a0f7eb59fa', '03751651c36952668c9b65b923b9c221', 1933, '伪蒙疆联合自治政府主席', NULL, '虽为察哈尔部贵族，但长期在土默特右旗及包头地区活动，与日军合作，建立伪蒙疆政权，推行“蒙独”分裂活动，为日军提供兵源和情报。', '内蒙古包头_土默特右旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('04b87307c2bb5c0083357e8a773849fc', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙疆政府司法部长', NULL, '土默特右旗人，投靠日军后任伪蒙疆司法部长，参与制定伪法律，镇压抗日民众，协助日军维持殖民统治。', '内蒙古包头_土默特右旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3547e0d1ae9a55d7b085f05d10b95f68', 'a6fe2171a37f59a0a1a45779d088abd0', 1937, '伪蒙古军师长', NULL, '土默特右旗人，任伪蒙古军师长，率部参与日军对绥西地区的“扫荡”，杀害抗日军民，掠夺物资。', '内蒙古包头_土默特右旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1dbf965057f353b58127d74dcacacf13', '100903e3ba7f50fe91ce116eab66b33a', 1938, '伪包头市警察局长', NULL, '原为包头地方势力，日军占领后投敌，任伪警察局长，协助日军搜捕抗日地下人员，残害百姓。', '内蒙古包头_土默特右旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7a0aff18091151a5a103492c9dc2c013', '54c6652a4c7650c2afc80fa79ef135c1', 1939, '伪土默特右旗公署参事', NULL, '土默特右旗人，任伪旗公署参事，为日军征收粮草，强抓壮丁，提供劳役，帮助日军建立保甲制度。', '内蒙古包头_土默特右旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a73d6567cde3514595fd02dcbb00733a', 'cb6c2a7256425f8ab78242fc69e2391c', 1940, '伪蒙古军骑兵团长', NULL, '土默特右旗人，率伪骑兵团驻防包头地区，多次配合日军突袭大青山抗日游击队，杀害多名八路军战士。', '内蒙古包头_土默特右旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f68dff750c2f5e168b9521ef431ee2bb', 'dd16228ed77d5347a9db49d43cc1ddae', 1937, '伪包头维持会会长', NULL, '日军占领包头初期，主动出任维持会长，为日军筹集物资，组织汉奸队伍，协助日军建立伪政权。', '内蒙古包头_土默特右旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dd967473d25b5f30b5e94a55b47be08d', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令', NULL, '原为热河土匪，后投靠日本关东军，组建伪蒙古军，在察哈尔、绥远（含包头、白云鄂博一带）配合日军进攻抗日武装，镇压蒙汉民众，掠夺矿产资源。', '内蒙古包头_白云鄂博矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3c4027a10cf252afa6eba5f258e697d2', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙疆联合自治政府主席', NULL, '蒙古王公，在日本扶植下成立伪蒙疆政权，管辖包括包头、白云鄂博在内的绥远地区，推行奴化教育，协助日军控制矿产和交通线。', '内蒙古包头_白云鄂博矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b203136ea92b533eb2f8a9f9ffd6c842', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙疆政府政务院院长', NULL, '德王亲信，参与伪蒙疆政权行政运作，在包头地区推行日伪法令，征派劳役开采白云鄂博铁矿资源。', '内蒙古包头_白云鄂博矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7962c89fff105e389d7e60bdafa8ae5a', '66f4a5c280815acc8e8258aae4d43407', 1937, '伪蒙疆政府副主席', NULL, '蒙古族上层，投靠日本，在包头及乌兰察布一带协助日军维持治安，参与镇压抗日活动。', '内蒙古包头_白云鄂博矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a8f74ba34cdf5c79a3c7a041c4f00fb4', 'f3baedeec5d9550c9fe76ccba55e98b1', 1937, '伪蒙古军第1军军长', NULL, '率伪蒙古军驻防绥西地区，多次配合日军扫荡包头、固阳、白云鄂博周边抗日游击队，掠夺牲畜和矿产。', '内蒙古包头_白云鄂博矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6cdd883b6ab45f6a9c8a03529bdee821', 'a6fe2171a37f59a0a1a45779d088abd0', 1937, '伪蒙古军第2军军长', NULL, '在包头、萨拉齐一带驻防，协助日军清剿抗日力量，参与对白云鄂博矿区劳工的军事管制。', '内蒙古包头_白云鄂博矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b0395486207153368f654726bf701d07', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令', NULL, '原土匪出身，投日后在包头以西地区组建伪军，多次袭击抗日武装，为日军勘探白云鄂博矿提供情报和护卫。', '内蒙古包头_白云鄂博矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f3c36f900d4f5839b5d704167fed5f64', '7919fe83935950c484b84fc165626e11', 1938, '伪蒙古军第3军军长', NULL, '原东北军军官，叛变投日后在绥远地区活动，参与对包头、白云鄂博一带的军事占领和资源掠夺。', '内蒙古包头_白云鄂博矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('44352e39650b5ca2abeddd7ad9d42d15', '4bd9cd1ed4f65f568f7afde7603fda36', 1939, '伪包头市市长', NULL, '日本占领包头后任伪市长，负责推行日伪市政管理，组织劳工为日军开采白云鄂博铁矿，强征粮食和物资。', '内蒙古包头_白云鄂博矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eb906b9df9a05d0aaa1130263c56b612', '54c6652a4c7650c2afc80fa79ef135c1', 1939, '伪包头警察局局长', NULL, '协助日军在包头及白云鄂博矿区建立特务网络，抓捕抗日志士，镇压矿工反抗。', '内蒙古包头_白云鄂博矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('51be81481d6550e9b11d15f3bde54f99', 'dd16228ed77d5347a9db49d43cc1ddae', 1939, '伪包头商会会长', NULL, '为日军筹措军费，垄断白云鄂博矿石运输，向日本军方提供经济支持，剥削当地商民。', '内蒙古包头_白云鄂博矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('42160bfcf43e53349844853e2e1f72eb', 'ab27f867dab453599e0a5cdf56ab966d', 1940, '伪蒙疆政府包头地区参事', NULL, '蒙古族投日分子，在包头、白云鄂博地区协助日军管理蒙古族事务，煽动民族分裂，破坏抗日统一战线。', '内蒙古包头_白云鄂博矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('284202d046695d9f8f0b39ef938c72e0', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪蒙古联盟自治政府副主席', NULL, '原为东北军军官，后投靠日军，在内蒙古东部及包头、石拐地区协助日军建立伪蒙古军，参与镇压抗日力量，推行殖民统治。', '内蒙古包头_石拐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('66f2cdd4ee6b57e6ba931c8b5f00a0c4', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙古联盟自治政府主席、伪蒙疆联合自治政府主席', NULL, '领导内蒙古西部（包括包头、石拐地区）的伪蒙政权，与日军合作，组织伪蒙古军，实施奴化教育，配合日军经济掠夺。', '内蒙古包头_石拐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7e36af390b185dc492e29c7d8db8e556', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙古军政府总参谋长、伪蒙疆政府政务院院长', NULL, '在包头、石拐地区协助日军管理伪蒙政权，参与制定殖民政策，镇压抗日活动。', '内蒙古包头_石拐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7b6fe6875e6a52acb834533cfddd936e', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令', NULL, '原为土匪头目，后投靠日军，在包头、石拐及绥西地区组织伪军，协助日军扫荡抗日根据地，残害百姓。', '内蒙古包头_石拐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('89dc0a140ac65089893e1751c2a81973', '7919fe83935950c484b84fc165626e11', 1938, '伪绥西自治联军副司令', NULL, '随王英投敌，在石拐地区参与伪军活动，协助日军围剿抗日武装。', '内蒙古包头_石拐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3564f42f25c957299655a5cac35b08dc', '816af17b0eb75cd2af61c252b0bc97f8', 1939, '伪包头市警察局局长', NULL, '在包头及石拐地区为日军维持治安，抓捕抗日志士，强征劳工。', '内蒙古包头_石拐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0a4f37c2763b58f3acc9592782a75570', '54c6652a4c7650c2afc80fa79ef135c1', 1940, '伪包头县知事（县长）', NULL, '在包头、石拐地区推行日伪政令，征收苛捐杂税，协助日军掠夺矿产资源。', '内蒙古包头_石拐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('baf62b3b06c25f078f43d3101edcabbe', '25403a79f8335f3e96fc8451f78bbb99', 1941, '伪石拐矿区维持会会长', NULL, '在石拐煤矿区为日军服务，组织矿工劳动，镇压矿工反抗，向日军提供煤炭资源。', '内蒙古包头_石拐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0fd9a41991e7544aa98e97611c57fddc', 'f8128d92a5455f2886dae039c7903166', 1942, '伪绥西保安队队长', NULL, '在包头、石拐地区带领伪保安队，配合日军清乡，杀害抗日群众。', '内蒙古包头_石拐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d543a073a4315cf1a9293dd0a75b5f62', 'cdaf596844505e57823345c13fefecf0', 1939, '伪蒙疆政府包头特务机关长', NULL, '在包头、石拐地区从事特务活动，搜集情报，破坏抗日组织。', '内蒙古包头_石拐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e80e5deb22ed58fab1586360cb70f386', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪蒙古联合自治政府副主席', NULL, '原东北军将领，投靠日本后组建伪蒙古军，在包头、青山地区配合日军进攻抗日武装，参与建立伪蒙疆政权，镇压当地抗日力量。', '内蒙古包头_青山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d979e1ac782d58d58278eec7101a493e', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙古联合自治政府主席', NULL, '蒙古王公，策划内蒙古独立，与日本关东军合作，在包头及周边推行伪蒙疆政权，为日军提供兵员和情报，协助统治占领区。', '内蒙古包头_青山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e736f23d3d925c6081a1319da3bbb331', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙古军参谋长、伪蒙古联合自治政府政务院院长', NULL, '参与伪蒙疆政权高层决策，在包头地区组织伪行政机构，协助日军清乡、征粮，迫害抗日军民。', '内蒙古包头_青山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c7c9fe4f87965c1b82c77a98d7c8aa26', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令', NULL, '原土匪武装头目，投日后在包头、青山一带活动，率伪军配合日军扫荡大青山抗日游击根据地，残害百姓。', '内蒙古包头_青山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f936b252322c5a86820f0216482d0ac6', '7919fe83935950c484b84fc165626e11', 1938, '伪东亚同盟军总司令（后反正）', NULL, '原东北军师长，投敌后任伪军职，在包头地区参与对抗日根据地的进攻，后因被日军猜忌而反正，但前期有助敌行为。', '内蒙古包头_青山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2339aaaab887527091ccb206c0678951', '816af17b0eb75cd2af61c252b0bc97f8', 1939, '伪包头市公署市长', NULL, '在包头市任伪市长期间，推行日伪殖民政策，组织保甲制度，强征劳工，为日军提供物资，镇压抗日活动。', '内蒙古包头_青山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8e8a31947b5155529e3e03e73e214594', '54c6652a4c7650c2afc80fa79ef135c1', 1940, '伪包头警察局局长', NULL, '指挥伪警察在包头、青山地区搜捕抗日地下人员，破坏地下组织，协助日军实施“治安强化”运动。', '内蒙古包头_青山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a7398b3fd65e595da332c9e38683add0', '25403a79f8335f3e96fc8451f78bbb99', 1938, '伪蒙古军第1师师长', NULL, '率伪蒙古军在包头周边驻防，多次参与对大青山游击队的围剿，杀害抗日干部和群众。', '内蒙古包头_青山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2db74f1a35c25919934805328209ab60', 'a6fe2171a37f59a0a1a45779d088abd0', 1939, '伪蒙古军第2师师长', NULL, '在青山地区配合日军“扫荡”，烧毁村庄，掠夺牲畜，强迫牧民迁移，制造无人区。', '内蒙古包头_青山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1dbaa522623c5123a4f7c59f6b92442e', '3e3a95a66cd25e84bf924d6a800e9f57', 1938, '伪绥西自治联军参谋长', NULL, '协助王英指挥伪军，参与制定针对大青山抗日游击根据地的军事行动，多次率部袭击抗日武装。', '内蒙古包头_青山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d9d471b40d4d55deb72b5d4e37d3178a', '03751651c36952668c9b65b923b9c221', 1933, '伪蒙古联盟自治政府主席、伪蒙疆联合自治政府主席', NULL, '在内蒙古地区策划“蒙古自治运动”，投靠日本关东军，建立伪蒙政权，配合日军统治和掠夺内蒙古资源，组织伪蒙古军协助日军作战。', '内蒙古呼伦贝尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('59815afff11859d6a2562cc16421342c', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪蒙古联盟自治政府副主席', NULL, '原东北军将领，叛国投日后任伪蒙古军总司令，率伪军在察哈尔、绥远及呼伦贝尔周边地区配合日军进攻抗日武装，镇压蒙汉民众。', '内蒙古呼伦贝尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1139e65db1995504b4805dba28970e9c', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令', NULL, '在绥远（含今呼伦贝尔部分相关区域）组织伪军，充当日军“以华制华”工具，多次进犯抗日根据地，劫掠百姓。', '内蒙古呼伦贝尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8a233837d71c5900b98bba9f26a238be', '7893cdab2278525ca46f22df1ae1de18', 1936, '伪蒙古军参谋长、伪蒙疆政府军事部长', NULL, '协助德王、李守信整编伪蒙古军，参与策划对呼伦贝尔及兴安北省等地的军事控制，为日军提供情报和兵员。', '内蒙古呼伦贝尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8eeb59979aed5756a5bc072d5a87baab', 'f3baedeec5d9550c9fe76ccba55e98b1', 1932, '伪兴安北省省长（呼伦贝尔地区）', NULL, '在日本关东军扶植下出任伪兴安北省（今呼伦贝尔大部）省长，推行殖民政策，强制收缴民间枪支，组织伪警察镇压抗联和民众反抗。', '内蒙古呼伦贝尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9828fa9384945a8985fc1a42f9f83115', 'b3d853b6e1e3564bb50b6ff7577f9c76', 1932, '伪兴安北省警务厅长', NULL, '在呼伦贝尔地区主持伪警务，协助日军搜捕抗日分子，参与“清乡”行动，迫害达斡尔、鄂温克等各族群众。', '内蒙古呼伦贝尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('81e7ba6c796a5776a1891106894f5c18', 'd0bfafacf89d5f0d93c40f5018954c98', 1932, '伪兴安北省省长（早期）', NULL, '曾任伪兴安北省省长，后因对日本关东军不满被日军以“通苏”罪名处决，但其前期在伪职期间执行了日本殖民统治政策。', '内蒙古呼伦贝尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ff849f4dd3f25b6faeb19a69ca5585eb', '406a78c4154f5d6a9f1dc81bb7c4bf31', 1932, '伪兴安北省参事官', NULL, '作为日本驻伪兴安北省参事官（实际为日本人，但此处按历史记录列入），协助日军控制呼伦贝尔行政和军事，镇压抗联三进呼伦贝尔的行动。', '内蒙古呼伦贝尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0f9442e68fbf54f292f54bbce2e9e854', 'ed72448d66475d94833eef8cfefd0af4', 1932, '伪索伦旗旗长（今鄂温克旗）', NULL, '在呼伦贝尔索伦旗（今鄂温克族自治旗）任伪职，强迫牧民缴纳“出荷粮”，为日军提供畜力、皮毛等战争物资。', '内蒙古呼伦贝尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ac72f961bf6056948b0e4af61a23f0e1', 'b0c92cdcd1475fb9a2bfb0cdd64b373b', 1932, '伪布特哈旗旗长（今莫力达瓦旗）', NULL, '在呼伦贝尔布特哈旗推行日伪“保甲制度”，组织伪自卫团，协助日军围剿抗联小分队，迫害达斡尔族抗日群众。', '内蒙古呼伦贝尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cd3f4e125ddc5e9a95806c71951b8ea9', 'a057ec0819035547b2ed5893cff08b28', 1932, '伪海拉尔市市长', NULL, '任伪满海拉尔市市长期间，推行日伪殖民政策，协助日本关东军镇压当地抗日力量，强征劳工修建军事设施。', '内蒙古呼伦贝尔_海拉尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f09e35b26dfc57fd93b08a5c23898b90', 'b3d853b6e1e3564bb50b6ff7577f9c76', 1932, '伪兴安北省省长', NULL, '作为蒙古族上层投靠日本，任伪兴安北省省长，配合日军在呼伦贝尔地区实施“治安肃正”，迫害抗日志士，强制推行奴化教育。', '内蒙古呼伦贝尔_海拉尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8fecb61cce965165ad5d0a3924eba531', 'd0bfafacf89d5f0d93c40f5018954c98', 1932, '伪兴安北省省长（早期）', NULL, '曾任伪兴安北省省长，后因与日本关东军产生矛盾，被指控“通苏通蒙”罪名，于1936年被日军处决，但其前期曾协助日伪建立统治。', '内蒙古呼伦贝尔_海拉尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('74a82afcde1f5250b1b43d151766bb7e', '406a78c4154f5d6a9f1dc81bb7c4bf31', 1932, '伪兴安北省警务厅长', NULL, '掌管伪兴安北省警察机构，协助日本宪兵队搜捕抗日地下人员，参与镇压海拉尔地区反满抗日活动。', '内蒙古呼伦贝尔_海拉尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3a14d32aba1a517aad35d2cf908ac3ab', '80ee01b7b10e531f831e2e9dd414c37a', 1933, '伪海拉尔警察署署长', NULL, '效忠日伪政权，指挥警察镇压当地民众反抗，为日军提供情报，参与抓捕苏联间谍和抗日分子。', '内蒙古呼伦贝尔_海拉尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dbbcafb859c35153bc3d4a79bf33715b', '800c27d2c31954e785359168edd38e70', 1932, '伪兴安北省参事官', NULL, '作为日伪政权在呼伦贝尔的蒙古族官员，积极推行“日蒙亲善”宣传，协助日军收编地方武装，破坏抗日联军活动。', '内蒙古呼伦贝尔_海拉尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('509e4dabd78d5e13b05186021475bae4', 'bb365bc9d1605fa9a4e2962ffd81b9bc', 1935, '伪海拉尔市公署总务科长', NULL, '管理伪市公署日常事务，配合日军经济掠夺，强制收缴民间金属和粮食，供日军军需。', '内蒙古呼伦贝尔_海拉尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f7c843f7cdef5c038c90ea7566a145d8', '2fae5c65dd395f52a2183aabf63f814d', 1938, '伪兴安军第10团团长（后反正）', NULL, '曾任伪兴安军军官，初期效忠日伪，参与镇压抗日武装，1944年率部起义反正，但此前有助纣为虐行为。', '内蒙古呼伦贝尔_海拉尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('04114fbc69575d1ebc9e4fca802ec185', 'b62352fbc8f85eb6b40ef0dc25685166', 1932, '伪兴安军军官', NULL, '蒙古族贵族出身，投靠日本后任伪兴安军军官，参与围剿东北抗日联军在呼伦贝尔的游击活动。', '内蒙古呼伦贝尔_海拉尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('41ba068eb95f55ceb27f89739152e9ab', '5c07d91a317b5e17b90f1fabc6916450', 1933, '伪兴安军第2师师长', NULL, '指挥伪兴安军配合日军“讨伐”抗日武装，在呼伦贝尔地区制造多起屠杀事件，强征牧民入伍。', '内蒙古呼伦贝尔_海拉尔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bdfeefb6772d548197ccf70ba8863d83', '03751651c36952668c9b65b923b9c221', 1933, '蒙疆联合自治政府主席', NULL, '在内蒙古地区策划‘蒙古自治运动’，投靠日本，建立蒙疆政权，配合日军统治内蒙古中西部，包括呼伦贝尔周边地区', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8adafc3f2b965fb193b25b532aa969f4', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令', NULL, '率部投日，任伪蒙古军总司令，参与镇压抗日力量，在内蒙古东部及呼伦贝尔一带协助日军维持治安', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8f8b833bd6195066ba3dcd59d281da04', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西联军司令', NULL, '在内蒙古西部及呼伦贝尔南部活动，率伪军配合日军进攻抗日武装，残害百姓', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('de42b4dba7365829ab407645ad3c60d6', '7893cdab2278525ca46f22df1ae1de18', 1938, '伪蒙疆政府军事部长', NULL, '参与伪蒙疆政权军事管理，协助日军在内蒙古地区推行殖民统治，涉及呼伦贝尔地区防务', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0e34d4d2b8bf54d4bf7490b84cda555e', 'f3baedeec5d9550c9fe76ccba55e98b1', 1932, '伪兴安总省省长', NULL, '任伪兴安总省（辖呼伦贝尔地区）省长，推行日本殖民政策，组织伪警察镇压抗日活动', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('becbfe89bd6b51feb637bbfb14ad9b66', 'fa9736d07ffb506e89e814ca8b4bba04', 1932, '伪兴安北省省长', NULL, '管辖今呼伦贝尔北部地区，配合日军‘治安肃正’，强征劳工，迫害抗联人员', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('89c806163487596387e30f45518ead7f', 'b3d853b6e1e3564bb50b6ff7577f9c76', 1932, '伪兴安东省省长', NULL, '在呼伦贝尔东部地区推行伪满统治，协助日军清剿抗联部队，征收粮草', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('529ec2c49fa5574687520fb4551549fb', 'd0bfafacf89d5f0d93c40f5018954c98', 1932, '伪兴安北省省长（早期）', NULL, '曾任伪兴安北省省长，后因与日本关东军矛盾被处死，但前期曾协助日军建立伪政权', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('75847da185865f9e82844b29c2a4f986', '406a78c4154f5d6a9f1dc81bb7c4bf31', 1932, '伪满洲国兴安北省警务厅长', NULL, '在呼伦贝尔地区指挥伪警察，协助日军搜捕抗日分子，参与‘讨伐’抗联', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4476576e5bd750e7b057b5a8c8b304f0', 'b62352fbc8f85eb6b40ef0dc25685166', 1932, '伪兴安军军官', NULL, '在呼伦贝尔地区统领伪兴安军，配合日军进攻苏联边境及抗日武装', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0350bbfee9ce597c8c25ac10543c787f', '2fae5c65dd395f52a2183aabf63f814d', 1940, '伪兴安军第2师师长', NULL, '驻守呼伦贝尔地区，参与日军对苏作战准备，镇压当地抗日力量', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f8d45e32eaa157128e0efdde3ffff973', '5c07d91a317b5e17b90f1fabc6916450', 1938, '伪兴安军第1师师长', NULL, '在呼伦贝尔西部活动，协助日军建立军事据点，迫害牧民', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8cae987782ee57a1b769b5baf3c0f299', 'e45a1ffbbd21578983624b349522ac85', 1935, '伪满洲国驻海拉尔特务机关长', NULL, '在海拉尔（今呼伦贝尔市）从事特务活动，监控抗日人士，收集情报', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('98e93c5e2ea35557a072f113690c4215', 'b81217384c825493938d81949227fc49', 1932, '伪满洲国兴安北省参事官', NULL, '在满洲里地区协助日军管理边境事务，参与对苏谍报活动', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e1ee441e92c551c48e5b31430c395789', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满洲国热河省省长（曾涉呼伦贝尔）', NULL, '早年投日，后任伪职，其势力曾延伸至内蒙古东部，协助日军镇压抗日武装', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('44b744db5ac85b73899483c5d4873bc2', '7ee6b737ce1d55a9866b5156643815fa', 1933, '伪满洲国兴安西省警备军司令', NULL, '在内蒙古东部及呼伦贝尔南部流窜，率伪军烧杀抢掠，配合日军扫荡', '内蒙古呼伦贝尔_满洲里');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d9c012a15cc95e71b4f77011791b31a1', 'b3d853b6e1e3564bb50b6ff7577f9c76', 1932, '伪满洲国兴安北省省长', NULL, '曾任伪满洲国兴安北省省长，在呼伦贝尔地区推行日伪殖民统治，协助日本关东军镇压当地抗日力量。', '内蒙古呼伦贝尔_莫力达瓦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fafed0ea4ef35c19b1fc06ff485c4cf8', 'd0bfafacf89d5f0d93c40f5018954c98', 1932, '伪满洲国兴安北省省长（后因反日被处决）', NULL, '初期投靠日本，任伪兴安北省省长，后因反对日本移民政策及秘密联络抗日势力，于1936年被日本关东军以“通苏”罪名处决。', '内蒙古呼伦贝尔_莫力达瓦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3bd4f1223d575f5782284c43f67d8f01', '406a78c4154f5d6a9f1dc81bb7c4bf31', 1932, '伪满洲国兴安北省警务厅厅长', NULL, '在呼伦贝尔地区担任伪警务厅长，协助日本宪兵队搜捕抗日分子，镇压牧民反抗。', '内蒙古呼伦贝尔_莫力达瓦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('96f0d4955a675c388d2730360fa1a8f9', '80ee01b7b10e531f831e2e9dd414c37a', 1932, '伪满洲国兴安北省公署参事', NULL, '参与伪满政权在呼伦贝尔的行政事务，为日军提供当地情报，协助推行“治安肃正”政策。', '内蒙古呼伦贝尔_莫力达瓦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f49b36805b6252b0a8c9ad18a77420ed', '800c27d2c31954e785359168edd38e70', 1932, '伪满洲国兴安东省莫力达瓦旗旗长', NULL, '在莫力达瓦地区任伪旗长，强制征收粮食和牲畜，为日军提供物资，镇压当地达斡尔族抗日活动。', '内蒙古呼伦贝尔_莫力达瓦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('acf26af453f156a3b7b06e2d5121fa97', 'bb365bc9d1605fa9a4e2962ffd81b9bc', 1933, '伪满洲国莫力达瓦旗警察署署长', NULL, '在莫力达瓦旗组织伪警察，协助日军清乡，逮捕并杀害抗日地下工作者。', '内蒙古呼伦贝尔_莫力达瓦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('29cf2dd34ce558388fb06dff18379510', '7f069f226d295a239249dba3d0ccba62', 1932, '伪满洲国兴安东省警备军军官', NULL, '在呼伦贝尔地区指挥伪军参与“讨伐”抗日游击队，烧毁村庄，掠夺财物。', '内蒙古呼伦贝尔_莫力达瓦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b95b24dc54fb5ee68e6e076f1c0745b8', '8988d5f913ca5e618b9be05a96f60316', 1935, '伪满洲国莫力达瓦旗公署财务科长', NULL, '负责为日伪政权征收苛捐杂税，强征劳工，导致当地民众负担沉重。', '内蒙古呼伦贝尔_莫力达瓦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('09285f0f621f56b1881129b74d8e02ee', 'b3d853b6e1e3564bb50b6ff7577f9c76', 1932, '伪满洲国兴安北分省省长', NULL, '在陈巴尔虎旗及呼伦贝尔地区推行日本殖民政策，协助日伪政权统治当地蒙古族牧民，镇压抗日活动。', '内蒙古呼伦贝尔_陈巴尔虎旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a76bd8e6ad1f52919eaee0ced60d64a7', 'd0bfafacf89d5f0d93c40f5018954c98', 1932, '伪满洲国兴安北分省省长（后任）', NULL, '初期为日伪效力，后因与日本关东军产生矛盾被处决，但此前在陈巴尔虎旗地区执行过日伪行政命令。', '内蒙古呼伦贝尔_陈巴尔虎旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7c7d7f966d1d521c8c6b5aea7be8a5ee', '7b4769dbad32504496fdd0706dd37257', NULL, '伪兴安北省警务厅厅长', NULL, '在陈巴尔虎旗地区组织伪警察力量，协助日军清剿抗日武装，抓捕抗日志士。', '内蒙古呼伦贝尔_陈巴尔虎旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7fd33e19a78555bc93a46c777eaa7db2', 'a7f47f1bae70551e96c36a47b0cb786f', 1932, '伪陈巴尔虎旗旗长', NULL, '作为伪旗长，直接执行日伪征粮、征兵及“治安肃正”政策，压迫当地牧民。', '内蒙古呼伦贝尔_陈巴尔虎旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('914270e755e95596881b7a4c96dc9f26', 'f0a60c2132f259428851d8bb34f0b585', NULL, '伪陈巴尔虎旗副旗长兼警务科长', NULL, '协助日军在陈巴尔虎旗建立情报网络，参与镇压当地反抗活动。', '内蒙古呼伦贝尔_陈巴尔虎旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a51d9ea10ffc5a5687db38efb841f3bf', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令', NULL, '原东北军将领，投靠日军后任伪蒙古军总司令，在呼伦贝尔及内蒙古东部地区协助日军镇压抗日力量，参与“满洲国”边境军事行动。', '内蒙古呼伦贝尔_额尔古纳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('57b56176d6c0558eb06a684347769cf0', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙疆联合自治政府主席', NULL, '蒙古王公，组织伪蒙疆政权，与日军合作，在内蒙古地区推行殖民统治，其势力范围曾延伸至呼伦贝尔西部边缘，配合日军“治安肃正”。', '内蒙古呼伦贝尔_额尔古纳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('96b205aea46a534d82336e81b08bcd41', '7893cdab2278525ca46f22df1ae1de18', 1932, '伪满洲国兴安北省省长', NULL, '呼伦贝尔地区（今额尔古纳市及周边）的蒙古族上层，任伪满兴安北省省长，协助日本关东军管理额尔古纳河沿岸防务，镇压当地抗联及牧民反抗。', '内蒙古呼伦贝尔_额尔古纳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4927a71d114659a88f1139b6686a43fb', 'd0bfafacf89d5f0d93c40f5018954c98', 1932, '伪满洲国兴安北省省长（前期）', NULL, '呼伦贝尔索伦旗贵族，初任伪兴安北省省长，后因与日本关东军矛盾被处决，但其任职期间曾配合日军清剿额尔古纳地区抗日武装。', '内蒙古呼伦贝尔_额尔古纳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e983788d321b5c0eb06a04f90625f463', 'b3d853b6e1e3564bb50b6ff7577f9c76', 1932, '伪满洲国兴安北省警务厅长', NULL, '呼伦贝尔籍，在额尔古纳及三河地区组织伪警察，协助日军搜捕抗联地下人员，参与“讨伐”苏联间谍网络。', '内蒙古呼伦贝尔_额尔古纳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3d8b539110725022b6ee70b0e9deef46', '7b4769dbad32504496fdd0706dd37257', 1935, '伪满洲国额尔古纳左翼旗旗长', NULL, '额尔古纳本地蒙古族头人，投靠日伪后任旗长，强制推行“粮谷出荷”，为日军提供物资，并举报抗日民众。', '内蒙古呼伦贝尔_额尔古纳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('96835ffefe7b52a0a7beadd761c3abfe', '86df58d4d42254699ca5de4b27e23f07', 1937, '伪满洲国额尔古纳右翼旗旗长', NULL, '在额尔古纳河右岸地区协助日军建立“集团部落”，隔离民众与抗联联系，参与迫害苏联侨民及抗日嫌疑者。', '内蒙古呼伦贝尔_额尔古纳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8302aafcf45a5a9eb252a62d7eec40bf', '2fae5c65dd395f52a2183aabf63f814d', 1938, '伪满洲国兴安军第9团团长', NULL, '呼伦贝尔籍达斡尔族军官，率伪兴安军驻防额尔古纳地区，参与对苏边境侦察及镇压当地抗联小分队，后于1945年反正。', '内蒙古呼伦贝尔_额尔古纳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('65cd5b8eadfa5e268fa770746e35eee9', '8934bfcb90135fc686cacf332348b4ef', 1940, '伪满洲国额尔古纳地区保安队队长', NULL, '汉族，原为地方土匪，投靠日军后任保安队长，在三河、室韦一带抓捕抗联交通员，协助日军建立“防谍网”。', '内蒙古呼伦贝尔_额尔古纳');
