INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d65efd84b86e5caea8ff0eb71b775d2b', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙疆联合自治政府主席', NULL, '蒙古王公，与日本合作建立伪蒙疆政权，其势力范围覆盖土默特左旗，推行奴化教育，为日军提供情报和兵源。', '内蒙古呼和浩特_土默特左旗');
