INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('170093be4d5253c185db8ac7a2a578b3', '66f4a5c280815acc8e8258aae4d43407', 1938, '伪蒙疆政府民政部长', NULL, '土默特左旗贵族，在伪政权中负责地方行政，强征民夫和粮食供日军使用，破坏当地抗日地下组织。', '内蒙古呼和浩特_土默特左旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fe5e39b668245db38eac64de1223ec0a', 'a6fe2171a37f59a0a1a45779d088abd0', 1939, '伪蒙古军第9师师长', NULL, '土默特左旗人，率伪军多次扫荡大青山抗日根据地，烧毁村庄，杀害八路军伤员和群众。', '内蒙古呼和浩特_土默特左旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('07c53ea33d085f489958feb4b2bdbdef', '100903e3ba7f50fe91ce116eab66b33a', 1940, '伪土默特左旗公署参事', NULL, '协助日军推行保甲制度，强迫村民报告八路军行踪，导致多名地下党员被捕牺牲。', '内蒙古呼和浩特_土默特左旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('298068c221d554b0a6a4758d574e7d50', 'cfe1eb34b7b350aebfae13cb95fd4404', 1937, '伪蒙古军第2师副师长', NULL, '土默特左旗人，早年参加抗日，后叛变投日，参与围剿绥远抗日游击队，后因内讧被日军处决。', '内蒙古呼和浩特_土默特左旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e22dba9f825a5316b5688f3dab73e3ff', 'f8128d92a5455f2886dae039c7903166', 1941, '伪绥西自治联军司令', NULL, '原晋军将领，投日后在土默特左旗一带收编土匪，配合日军封锁抗日根据地，劫掠百姓财物。', '内蒙古呼和浩特_土默特左旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9c78cded8390519bb02dd8223192810a', '3e3a95a66cd25e84bf924d6a800e9f57', 1942, '伪土默特左旗警察署署长', NULL, '亲自带队搜捕抗日分子，严刑拷打嫌疑人员，向日军提供大青山游击队活动情报。', '内蒙古呼和浩特_土默特左旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b3f989cf459758c89a2ce3de475cd922', 'a3b7b63474ac524084f1bd8d8783933e', 1943, '伪蒙古军第12师团长', NULL, '在土默特左旗西部驻防，多次袭击抗日武工队，杀害地方抗日干部，强征壮丁补充伪军。', '内蒙古呼和浩特_土默特左旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4de14d09132553dd8f93f96e4100b06c', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪蒙古联合自治政府副主席', NULL, '原东北军将领，1933年投靠日军，组建伪蒙古军，在绥远（今呼和浩特、托克托一带）配合日军进攻抗日武装，参与建立伪蒙疆政权，镇压当地抗日力量。', '内蒙古呼和浩特_托克托');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('75ecb9a1981f5aed900ed80d949e12c5', '03751651c36952668c9b65b923b9c221', 1933, '伪蒙古联盟自治政府主席、伪蒙疆联合自治政府主席', NULL, '蒙古王公，1936年在日军扶植下成立伪蒙古军政府，后任伪蒙疆政权首脑，在呼和浩特、托克托地区推行日伪统治，协助日军清乡、征粮、抓捕抗日人士。', '内蒙古呼和浩特_托克托');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('83aa2053e54952e79673243045d854c4', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令', NULL, '原土匪出身，抗战期间投靠日军，在托克托、呼和浩特一带组织伪军，多次配合日军扫荡大青山抗日根据地，残害百姓，抢劫物资。', '内蒙古呼和浩特_托克托');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('560f4d43c7e0561593129cfa709eb721', '7919fe83935950c484b84fc165626e11', 1936, '伪蒙古军第1师师长', NULL, '原东北军军官，后投日，在绥远地区参与伪蒙古军作战，曾在托克托、呼和浩特周边协助日军进攻抗日游击队，并参与镇压民众反抗。', '内蒙古呼和浩特_托克托');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9f19a0106d855f989b1bd1c9b1f563d1', 'a6fe2171a37f59a0a1a45779d088abd0', 1937, '伪蒙古军第2师师长', NULL, '蒙古族军官，投日后在呼和浩特、托克托一带驻防，配合日军进行“治安肃正”，屠杀抗日军民，强征民夫修筑工事。', '内蒙古呼和浩特_托克托');
