INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8f3b4d5ff4b4577c80c30a87f7e7d92a', '4521f356ec205b2c8a2e82a1253b1d13', 1937, '伪蒙古军副司令', NULL, '在武川、四子王旗等地协助日军建立伪政权，组织伪警察队，抓捕抗日地下工作者，强征牲畜粮食供给日军。', '内蒙古呼和浩特_武川');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a50038eaeca150e4b5e93a72f9e7dd23', 'e925dd52f9355556b46352422eafe49a', NULL, '（不列入，因非汉奸）', NULL, '', '内蒙古呼和浩特_武川');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('740cd36423775b96bbf9faba625c0fcb', '142ed91c1ea95b6d922d76d4627e2b83', 1936, '伪蒙古军总司令、伪蒙古联盟自治政府副主席', NULL, '原东北军军官，后投靠日本关东军，组建伪蒙古军，参与侵占察哈尔、绥远（今呼和浩特地区），协助日军镇压抗日力量，并在玉泉区（旧归化城）设立伪政权机构。', '内蒙古呼和浩特_玉泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8c2156764887550b92759d3aeda050f8', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙古联盟自治政府主席、伪蒙疆联合自治政府主席', NULL, '内蒙古王公贵族，全面投靠日本，在呼和浩特（归绥）建立伪蒙疆政权，推行奴化教育，配合日军“治安强化”运动，迫害抗日军民，其伪政府机构曾驻于旧城（今玉泉区一带）。', '内蒙古呼和浩特_玉泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('54e5bb9e66555a01aa27f2850b1da941', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙古军政府秘书长、伪蒙疆联合自治政府总务委员长', NULL, '原北洋政府官员，投日后参与伪蒙疆政权高层决策，在归绥（今呼和浩特）协助日伪推行殖民统治，参与经济掠夺和“清乡”行动。', '内蒙古呼和浩特_玉泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2a5bc5f632375d4eb3804752eff1b503', 'f3baedeec5d9550c9fe76ccba55e98b1', 1937, '伪蒙古军第1军军长', NULL, '原内蒙古地方武装头目，投日后率伪蒙古军驻扎绥远地区，多次配合日军扫荡大青山抗日游击根据地，在归化城（玉泉区）一带抓捕抗日人员。', '内蒙古呼和浩特_玉泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4e9403b032745e1fa766e3e062a9061d', 'a6fe2171a37f59a0a1a45779d088abd0', 1937, '伪蒙古军第2军军长', NULL, '投靠日军后驻防绥西及归绥周边，参与镇压民众反抗，协助日军强征粮草，其部队曾在玉泉区（旧城）设卡盘查，迫害无辜百姓。', '内蒙古呼和浩特_玉泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ec2e6186da5c5ea58e16a79a3505c189', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令', NULL, '原绥远地方土匪武装头目，投日后编为伪军，活动于归绥（今呼和浩特）及绥西地区，多次进攻抗日游击队，在玉泉区周边村庄烧杀抢掠。', '内蒙古呼和浩特_玉泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ff8201586c32527fbce8e08c664aca47', '7919fe83935950c484b84fc165626e11', 1937, '伪蒙古军第3军军长（后反正）', NULL, '原东北军将领，投日后任伪职，驻扎归绥期间曾协助日军维持治安，后因日军猜忌被软禁，1939年反正失败被杀，但其前期行为已构成汉奸事实。', '内蒙古呼和浩特_玉泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ef5301b286665adba12f2266074ee6f5', '816af17b0eb75cd2af61c252b0bc97f8', 1938, '伪归绥县知事（县长）', NULL, '在日伪统治下任归绥县（含今玉泉区大部）伪县长，推行保甲制度，强征捐税，为日军提供粮食和情报，协助镇压抗日地下组织。', '内蒙古呼和浩特_玉泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9b17607d312b5bf6baec978e72ba548e', '0b5dc00f69d853ca9746c8bfb7d3305f', 1939, '伪归绥市公署市长（旧城区域）', NULL, '任伪归绥市市长期间，管理旧城（玉泉区）行政事务，执行日伪“治安肃正”计划，强制居民领取“良民证”，并参与奴化宣传。', '内蒙古呼和浩特_玉泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3242abb6c9db54309c075d923f0d411b', '256f790df3ca5bda9908673d0a57ee7f', 1938, '伪巴彦塔拉盟盟长（辖归绥地区）', NULL, '投日后任伪巴彦塔拉盟盟长，管辖今呼和浩特及周边旗县，在玉泉区设立伪盟公署分支机构，配合日军推行“蒙地奉上”和鸦片专卖政策。', '内蒙古呼和浩特_玉泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8be440e617af5b539445bf1dfce2a577', '66f4a5c280815acc8e8258aae4d43407', 1937, '伪蒙古联盟自治政府司法部长', NULL, '参与伪蒙疆政权立法和司法镇压，在归绥（今呼和浩特）设立伪法院，迫害抗日嫌疑人员，其活动范围涉及玉泉区旧城监狱。', '内蒙古呼和浩特_玉泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d99a27fd81eb54dba950ed8d900122ac', '7893cdab2278525ca46f22df1ae1de18', 1937, '伪蒙古军总参谋长', NULL, '原东北军军官，投日后任伪蒙古军总参谋长，策划多次对绥远抗日根据地的“围剿”，在归绥城防和玉泉区一带布设特务网。', '内蒙古呼和浩特_玉泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fcb163cd800e567485bf6c2bc5c28fde', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪蒙古联盟自治政府副主席', NULL, '原为东北军军官，后投靠日本关东军，在内蒙古东部及呼和浩特、赛罕地区协助日军建立伪蒙古军，参与镇压抗日力量，推行“蒙疆自治”政策，为日军提供兵员和情报。', '内蒙古呼和浩特_赛罕');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('702a7a8c6f815b608c0c5e8ecf8b2cbc', '03751651c36952668c9b65b923b9c221', 1933, '伪蒙古联盟自治政府主席、伪蒙疆联合自治政府主席', NULL, '内蒙古王公贵族，积极投靠日本，在呼和浩特（归绥）及周边地区建立伪政权，配合日军“以蒙治蒙”策略，组织伪蒙古军，协助日军清剿抗日武装，推行奴化教育。', '内蒙古呼和浩特_赛罕');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('305f8f72a8bf5b54abae0bbb6af6cd51', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙古联盟自治政府总务部长、伪蒙疆政府政务院院长', NULL, '原为国民党地方官员，后投日，在呼和浩特地区主持伪政府行政事务，协助日军征粮、征税，镇压抗日活动，参与制定“蒙疆”地区殖民政策。', '内蒙古呼和浩特_赛罕');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b2e1fc07c8455579b044ce9a8b78f786', 'f3baedeec5d9550c9fe76ccba55e98b1', 1936, '伪蒙古军第1师师长、伪蒙疆政府军事顾问', NULL, '在呼和浩特、赛罕一带协助日军训练伪军，多次参与“扫荡”抗日游击队，残害当地百姓，为日军提供后勤支持。', '内蒙古呼和浩特_赛罕');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c206b3841a15513185c9d863c13ede56', 'a6fe2171a37f59a0a1a45779d088abd0', 1937, '伪蒙古军第2师师长', NULL, '在归绥（今呼和浩特）及周边地区率伪军配合日军作战，围剿大青山抗日根据地，破坏地下抗日组织，强征民夫修筑军事工事。', '内蒙古呼和浩特_赛罕');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c385bd642b5258f9b7f821c531872db4', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令', NULL, '原为土匪武装头目，投日后在呼和浩特、赛罕地区活动，协助日军控制交通线，袭击抗日武装，掠夺民间财物，充当日军“以华制华”工具。', '内蒙古呼和浩特_赛罕');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8e1cffd1116f51aebfd8dd6bac65eb33', '7919fe83935950c484b84fc165626e11', 1938, '伪蒙古军第3师师长', NULL, '在呼和浩特南部及赛罕地区驻防，配合日军“治安肃正”行动，逮捕抗日志士，强迫农民种植鸦片，为日军筹措军费。', '内蒙古呼和浩特_赛罕');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ebdf95c6a2ea55bdacb8b7be1e561cef', '816af17b0eb75cd2af61c252b0bc97f8', 1938, '伪归绥县知事（县长）', NULL, '在呼和浩特（归绥）城区及赛罕地区推行日伪保甲制度，强征粮食和劳役，协助日军建立情报网，镇压抗日群众运动。', '内蒙古呼和浩特_赛罕');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ab4d4c655fbd5d7e9fd2550575cc896f', '54c6652a4c7650c2afc80fa79ef135c1', 1939, '伪巴彦塔拉盟盟长', NULL, '管辖包括呼和浩特、赛罕在内的地区，积极执行日本殖民政策，推行“蒙地奉上”运动，强占农民土地，配合日军“三光政策”清剿抗日根据地。', '内蒙古呼和浩特_赛罕');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1654a81a86e05395904e0aef92428bf1', '7893cdab2278525ca46f22df1ae1de18', 1937, '伪蒙古军总参谋长', NULL, '在呼和浩特地区参与策划多次对抗日游击队的围剿，协助日军建立伪警察体系，迫害抗日家属，为日军提供蒙古族士兵招募服务。', '内蒙古呼和浩特_赛罕');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('20be26c79c175ee89f5e6fe1fd520827', '2b5378ecc56d5f4f84f06756e495b505', 1936, '伪蒙古军第1军军长、伪绥西自治联军总司令', NULL, '原为土匪出身，后投靠日军，任伪蒙古军第1军军长，在绥西（包括临河、五原一带）配合日军进攻傅作义部，烧杀抢掠，残害百姓，并参与组织伪政权，镇压抗日力量。', '内蒙古巴彦淖尔_临河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a5bb2a5442b15581ad9d012a6bc5fcb7', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪蒙古联合自治政府副主席', NULL, '原为东北军军官，后叛变投日，任伪蒙古军总司令，其部队长期活动于绥远（含巴彦淖尔地区），协助日军控制河套平原，多次进攻抗日武装，并推行奴化教育。', '内蒙古巴彦淖尔_临河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5c3651d7a66e529dbacd70354c42a674', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙古联盟自治政府主席、伪蒙疆联合自治政府主席', NULL, '蒙古王公，积极投靠日本，建立伪蒙政权，其势力范围涵盖绥西地区，支持日军在临河等地设立伪警察署和保甲制度，镇压抗日活动，强征粮草。', '内蒙古巴彦淖尔_临河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e112d63275a257be9abe5160c8450190', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙古军第2军军长', NULL, '投靠日军后任伪蒙古军第2军军长，曾率部驻扎绥西一带，配合日军扫荡临河、陕坝等地，杀害抗日军民，掠夺财物。', '内蒙古巴彦淖尔_临河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1c4b2da258e05d0db6f51bd674c4847b', 'a6fe2171a37f59a0a1a45779d088abd0', 1938, '伪蒙古军第3师师长', NULL, '在绥西地区活动，协助日军围剿抗日游击队，参与建立伪乡村政权，强迫民众充当苦力，修筑军事工事。', '内蒙古巴彦淖尔_临河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c412682b39a152d38c7e4d344eeff4f0', '816af17b0eb75cd2af61c252b0bc97f8', 1939, '伪绥西自治联军副司令', NULL, '王英的副手，在临河、五原一带协助日军维持治安，参与屠杀抗日群众，并负责为日军征收粮食和牲畜。', '内蒙古巴彦淖尔_临河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bde459990622528d93d21cf794188e41', '25403a79f8335f3e96fc8451f78bbb99', 1940, '伪临河县县长', NULL, '日军占领临河期间任伪县长，推行日伪政策，组织汉奸保安队，协助日军清乡，逮捕抗日地下工作者，强征壮丁。', '内蒙古巴彦淖尔_临河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5bd3423211af57568cf18547134fd9d6', 'ea4f3b1f4a09554e998aeabe0a2715b4', 1941, '伪五原县县长（兼管临河部分地区）', NULL, '在日伪政权下任职，配合日军对河套地区进行经济掠夺，强制推行“治安强化运动”，迫害抗日家属。', '内蒙古巴彦淖尔_临河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dab45fbe05f85f7eaec3d81ea8816994', 'f8128d92a5455f2886dae039c7903166', 1942, '伪绥西警备司令（后投日）', NULL, '原为晋军将领，后投靠日军，任伪绥西警备司令，在临河、狼山一带协助日军防守，镇压当地抗日武装。', '内蒙古巴彦淖尔_临河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('68193c9e25725634957fd4450d8562cd', '3c0cec769a465f2da5d9587d32cf51f4', 1938, '伪蒙古军骑兵第5团团长', NULL, '长期在巴彦淖尔地区活动，率部袭击抗日游击队，抢劫村庄，并参与日军“扫荡”行动，杀害无辜百姓。', '内蒙古巴彦淖尔_临河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b4f5dbe73ecb576f9638e88e27923245', '03751651c36952668c9b65b923b9c221', 1933, '伪蒙疆联合自治政府主席、伪蒙古军总司令', NULL, '在乌拉特中旗及内蒙古西部策划“蒙古自治”，组建伪蒙古军，配合日军进攻绥远，建立傀儡政权，压迫抗日力量。', '内蒙古巴彦淖尔_乌拉特中旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7ac32ac415f95afb846fb7ca0dbf0c92', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军副总司令、伪蒙疆政府副主席', NULL, '率伪蒙古军侵占乌拉特中旗等地，协助日军清剿抗日武装，镇压蒙汉民众反抗，参与奴化统治。', '内蒙古巴彦淖尔_乌拉特中旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8b6b92eb7db05f94b90bce45f8d6baeb', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令', NULL, '在乌拉特中旗及河套地区为日军效力，组织伪军袭扰抗日部队，破坏中共地下组织，残害抗日军民。', '内蒙古巴彦淖尔_乌拉特中旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('30df87a5261a544182417d3ac62031f2', 'de8250ebfaaa563f81144b0512538c75', 1938, '伪绥西自治联军副司令', NULL, '随王英在乌拉特中旗一带活动，参与“清乡”行动，搜捕抗日分子，强征民夫，掠夺物资。', '内蒙古巴彦淖尔_乌拉特中旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8b9debfc869456b281f6e0e0f63fd7de', 'a6fe2171a37f59a0a1a45779d088abd0', 1937, '伪蒙古军第3师师长', NULL, '驻防乌拉特中旗期间，配合日军建立伪警察机构，强迫牧民“归顺”，镇压抗日游击队。', '内蒙古巴彦淖尔_乌拉特中旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7a892a997cb05bea9c64e4d4536472b5', 'ca45014abb9c54d79ae21bac9cc0a131', 1937, '伪蒙古军第4师师长', NULL, '在乌拉特中旗及乌拉特后旗一带活动，为日军提供情报，围剿抗日武装，推行“保甲制度”。', '内蒙古巴彦淖尔_乌拉特中旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('879fc0c422ef5cb79f34ba89ba64abd5', 'b182d6095559505a81aea13144dfe038', 1938, '伪蒙古军第9师师长（前期）', NULL, '在乌拉特中旗驻防期间曾执行日军命令，参与对抗日根据地的封锁，但后期于1945年率部反正（仍列入前期汉奸行为）。', '内蒙古巴彦淖尔_乌拉特中旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9dabdd16ab735293b892fc7c69484e7b', '49351a01baa950518bd6931f2075e257', 1939, '伪蒙疆政府政务院参议', NULL, '参与伪蒙疆政权在乌拉特中旗的行政建设，协助推行奴化教育，宣传“日蒙亲善”。', '内蒙古巴彦淖尔_乌拉特中旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3b02dc59ba865382a956e4b1dfaa1999', '987a275226335a46b1a0fdc3d18055ae', 1938, '伪蒙疆政府司法部长', NULL, '在乌拉特中旗设立伪法院，迫害抗日群众，审理“政治犯”，维护日伪统治秩序。', '内蒙古巴彦淖尔_乌拉特中旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8c04d92244fd56a4a2752ff1c79bb6c2', 'f3baedeec5d9550c9fe76ccba55e98b1', 1938, '伪乌拉特中旗旗长', NULL, '作为伪旗长，为日军征收粮草、牲畜，强抓壮丁，破坏抗日地下活动。', '内蒙古巴彦淖尔_乌拉特中旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fa627b86fe85592f81189d3f6b2e6683', 'b9d899275b0e502a9a10eb1abe6288c1', 1939, '伪乌拉特中旗警察署署长', NULL, '指挥伪警察搜捕抗日分子，严刑逼供，协助日军“扫荡”周边村落。', '内蒙古巴彦淖尔_乌拉特中旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('96b7db414c3450a8905b306be029261a', '37b65348094d5dbbb61b169a94549558', 1940, '伪乌拉特中旗保安队队长', NULL, '率保安队配合日军围剿大青山抗日游击队，杀害多名交通员和群众。', '内蒙古巴彦淖尔_乌拉特中旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4e66735ce334574eb5caf423bb2f3f51', '142ed91c1ea95b6d922d76d4627e2b83', 1936, '伪蒙古军总司令', NULL, '原东北军军官，后投靠日本关东军，在乌拉特前旗及周边地区协助日军建立伪蒙古军政权，参与镇压抗日力量，配合日军“扫荡”河套地区。', '内蒙古巴彦淖尔_乌拉特前旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('59bb3ff3f22e56d8807c06fce3b624b0', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙疆联合自治政府主席', NULL, '蒙古族贵族，与日本合作建立“蒙疆政权”，其势力范围包括乌拉特前旗一带，推行奴化教育，为日军提供兵员和物资，协助日军控制河套地区。', '内蒙古巴彦淖尔_乌拉特前旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6367886dff195ba2a05bfa86292a91cc', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙疆政府司法部长', NULL, '参与伪蒙疆政权司法体系，在乌拉特前旗地区协助日军维持殖民统治，镇压抗日活动。', '内蒙古巴彦淖尔_乌拉特前旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('092aa8ce25b45d469aa69e99575c7316', '66f4a5c280815acc8e8258aae4d43407', 1937, '伪蒙疆政府民政部长', NULL, '在乌拉特前旗及河套地区推行伪蒙疆政策，组织保甲制度，强征民夫和粮食供日军使用。', '内蒙古巴彦淖尔_乌拉特前旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b47baef5a93d541b9ef5a67106ace0e1', 'f3baedeec5d9550c9fe76ccba55e98b1', 1937, '伪蒙古军师长', NULL, '率伪蒙古军驻扎乌拉特前旗一带，配合日军围剿傅作义部抗日武装，残害当地抗日军民。', '内蒙古巴彦淖尔_乌拉特前旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('839db0fddbcd581a85733d862db5570b', 'a6fe2171a37f59a0a1a45779d088abd0', 1938, '伪蒙古军骑兵团长', NULL, '在乌拉特前旗地区为日军搜集情报，参与“清乡”行动，逮捕并杀害抗日地下工作者。', '内蒙古巴彦淖尔_乌拉特前旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4098e5a44730546bb72626f1faf4f255', '10cf9499b86c5eb48e46960674ae33ce', 1939, '伪乌拉特前旗旗长', NULL, '作为伪旗长，协助日军在乌拉特前旗推行“治安强化运动”，强征劳工修建军事设施，压榨当地牧民。', '内蒙古巴彦淖尔_乌拉特前旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f1936129922f575c86cc7db70bca79da', 'b9d899275b0e502a9a10eb1abe6288c1', 1940, '伪乌拉特前旗保安队长', NULL, '率伪保安队为日军站岗放哨，参与围捕抗日游击队，多次向日军报告抗日活动线索。', '内蒙古巴彦淖尔_乌拉特前旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cf99619ffd8d562cb9996143820cf369', '03751651c36952668c9b65b923b9c221', 1933, '蒙疆联合自治政府主席', NULL, '在内蒙古地区策划‘蒙古自治运动’，投靠日本，建立蒙疆政权，配合日军统治绥远（含今巴彦淖尔地区），推行奴化政策。', '内蒙古巴彦淖尔_乌拉特后旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('03c81373c1b156f08d65ad1a4bf453fb', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '蒙疆联合自治政府副主席、伪蒙古军总司令', NULL, '率伪蒙古军侵占绥远北部（含乌拉特后旗一带），协助日军‘清剿’抗日武装，镇压蒙汉民众。', '内蒙古巴彦淖尔_乌拉特后旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cd9aba6cb1255892943b52d04f7bc850', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令', NULL, '在绥西（含巴彦淖尔地区）组织伪军，配合日军进攻河套抗日根据地，劫掠百姓，破坏抗战。', '内蒙古巴彦淖尔_乌拉特后旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5bdca35ef9505fc0b986764014308975', '7919fe83935950c484b84fc165626e11', 1938, '伪绥西联军副司令（后反正）', NULL, '一度投靠日军，在乌拉特后旗及周边地区参与伪军活动，后反正抗日（但前期有汉奸行为）。', '内蒙古巴彦淖尔_乌拉特后旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5dca18faff0d5ecaba60ed399599be2e', 'daa7800f6f0d536db2b4db1f4fbebc90', 1939, '伪乌拉特后旗保安队队长', NULL, '在乌拉特后旗为日军效力，协助维持伪政权，镇压当地抗日牧民，征收苛捐杂税。', '内蒙古巴彦淖尔_乌拉特后旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('065a0df7e2f35bd1b47796812e35b5eb', 'f755416a4e3a5db7bd2d187663706fd1', 1940, '伪乌拉特后旗旗长（日伪任命）', NULL, '在日伪统治下担任旗长，推行‘保甲制度’，强迫牧民供粮供畜，配合日军‘治安肃正’。', '内蒙古巴彦淖尔_乌拉特后旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dd49d0fd364d54d981fa7becb7e88fec', '98779f1563e95d6694bd853d8dd99318', 1941, '伪乌拉特中旗（含后旗部分地区）协理', NULL, '协助日伪在乌拉特地区征募伪军，提供情报，参与围剿抗日游击队。', '内蒙古巴彦淖尔_乌拉特后旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7fad8f7cb84351188a2a35feeef71d79', '1e538d32c0ee5676a7de398ee8835d1b', 1942, '伪乌拉特后旗警察署署长', NULL, '指挥伪警察抓捕抗日志士，破坏地下抗日组织，为日军提供劳役。', '内蒙古巴彦淖尔_乌拉特后旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f6a8bf6b8d535b389a04c6eae798ffca', '2b5378ecc56d5f4f84f06756e495b505', 1936, '伪蒙古军第1军军长、伪绥西自治联军总司令', NULL, '原为土匪出身，后投靠日军，在五原、临河一带组织伪军，配合日军进攻绥西，多次参与对五原地区的扫荡和破坏，是当地主要的汉奸武装头目。', '内蒙古巴彦淖尔_五原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7f46857256bd55bcb16c958a2e0ae5cd', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军副总司令、伪蒙古联盟自治政府副主席', NULL, '热河人，投日后成为伪蒙疆政权核心人物，其势力范围曾延伸至绥西五原地区，协助日军控制该区域，并组织伪军对抗抗日武装。', '内蒙古巴彦淖尔_五原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8d479ab11517573dbdc55bd5b6bc6405', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙古联盟自治政府主席、伪蒙疆联合自治政府主席', NULL, '蒙古族王公，投靠日本后建立伪蒙政权，其行政管辖名义上包括五原地区，支持日军在绥西的军事行动，并推行奴化教育。', '内蒙古巴彦淖尔_五原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a06ba49dcd2452f98618dd09d0019452', '987a275226335a46b1a0fdc3d18055ae', 1938, '伪蒙古军第9师师长', NULL, '在五原、安北一带驻防，协助日军清剿抗日游击队，曾参与1939-1940年日军对五原的进攻，并纵容部下掠夺百姓。', '内蒙古巴彦淖尔_五原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('43c93f404acb57efba172f7f43e53335', 'a6fe2171a37f59a0a1a45779d088abd0', 1939, '伪蒙古军第5师师长', NULL, '率部在绥西地区活动，多次配合日军扫荡五原周边村庄，杀害抗日军民，并强征民夫修筑工事。', '内蒙古巴彦淖尔_五原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('acd0944d466d509580b55072505cd76b', '816af17b0eb75cd2af61c252b0bc97f8', 1940, '伪绥西自治联军副司令', NULL, '王英的副手，长期盘踞五原地区，为日军搜集情报，并参与对抗日根据地的封锁和破坏。', '内蒙古巴彦淖尔_五原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f5dfa96d805a5a9f881a12113053831a', '25403a79f8335f3e96fc8451f78bbb99', 1940, '伪五原县县长', NULL, '日军占领五原期间任伪县长，推行保甲制度，强征粮食和劳役，协助日军维持殖民统治，并迫害抗日家属。', '内蒙古巴彦淖尔_五原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b57830822d3e5931b4d43de5921af3e7', 'f8128d92a5455f2886dae039c7903166', 1941, '伪绥西自治联军参谋长', NULL, '参与策划伪军对五原地区的多次突袭，并负责训练伪军，配合日军“治安强化”运动。', '内蒙古巴彦淖尔_五原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c595179abd5a55aca20de73938d8313e', 'f5fe59e9e13854cbb87a474a95350c50', 1940, '伪五原县警察局长', NULL, '为日军效忠，搜捕抗日地下人员，破坏地下交通线，并参与镇压当地民众的反抗。', '内蒙古巴彦淖尔_五原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('51b74da7d9715be483a09f7c1343fed1', '797aabd204925c4ca86f5fe0f271febd', 1939, '伪安北县（今属五原）维持会会长', NULL, '日军占领安北后组织维持会，为日军筹粮派款，并引导日军袭击抗日武装驻地。', '内蒙古巴彦淖尔_五原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7baa78316e71537090074c69e5925659', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪蒙古军第1军军长、绥西自治联军总司令', NULL, '原为土匪出身，后投靠日军，任伪蒙古军第1军军长，率部在绥西（今巴彦淖尔、杭锦后旗一带）配合日军扫荡抗日武装，残害百姓，制造多起惨案。', '内蒙古巴彦淖尔_杭锦后旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0e6344e6277e5065acea38fc41dad5d1', '142ed91c1ea95b6d922d76d4627e2b83', 1936, '伪蒙古军总司令、伪蒙古联盟自治政府副主席', NULL, '原为东北军军官，后投靠日本关东军，参与组建伪蒙古军，多次率部进犯绥西地区，协助日军镇压抗日力量，是蒙奸头目之一。', '内蒙古巴彦淖尔_杭锦后旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3441b2ec0be7516994ebdcfbe9a86f89', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙古联盟自治政府主席、伪蒙疆联合自治政府主席', NULL, '蒙古王公，积极投靠日本，策划内蒙古独立，建立伪蒙政权，其势力范围包括巴彦淖尔地区，支持日军对绥西的军事行动，推行奴化政策。', '内蒙古巴彦淖尔_杭锦后旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fe9d2daaadad594c8b46a73debdd5c5e', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙古军第2军军长', NULL, '原为绥西地方武装头目，后投日，任伪蒙古军第2军军长，驻防绥西，协助日军清剿抗日游击队，强征民夫粮草，欺压当地民众。', '内蒙古巴彦淖尔_杭锦后旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a173793f94a05450ae4ba604fc292fc9', 'a6fe2171a37f59a0a1a45779d088abd0', 1938, '伪蒙古军第3师师长', NULL, '在绥西地区率伪军配合日军“扫荡”，参与杀害抗日军民，掠夺财物，破坏抗日组织。', '内蒙古巴彦淖尔_杭锦后旗');
