INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f2c84bf13bd6564495d9a6196be41779', '710133df938e558c84163d4073e8e797', 1933, '伪奈曼旗旗长、伪兴安西省参事', NULL, '在奈曼旗任伪职期间，强征民夫修建警备道路和碉堡，为日军提供粮食和物资，镇压当地抗捐抗税民众。', '内蒙古通辽_奈曼旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('44ed39aaaef7513bb66f61d60f85bf55', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪蒙疆政府副主席', NULL, '热河土匪出身，投日后率伪蒙古军多次侵入通辽、奈曼旗地区，配合日军扫荡，烧杀抢掠，并协助建立伪蒙疆政权。', '内蒙古通辽_奈曼旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2a688b47531f56709a299b12c809a034', '03751651c36952668c9b65b923b9c221', 1933, '伪蒙疆联合自治政府主席', NULL, '虽主要活动于锡林郭勒，但其伪蒙疆政权势力延伸至奈曼旗、通辽一带，支持伪军和特务机构在该地区镇压抗日活动。', '内蒙古通辽_奈曼旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('efa22cd1eb405e18b5602f65daf0d3e2', '3c0cec769a465f2da5d9587d32cf51f4', 1932, '伪通辽县警察署署长', NULL, '在通辽县任职期间，积极协助日军搜捕抗日地下人员，破坏抗日组织，多次带队袭击奈曼旗边境的抗日武装。', '内蒙古通辽_奈曼旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3c469f935d045e639197fb4f5b0c3b59', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪军将领', NULL, '原奉系军阀，投日后其势力曾控制奈曼旗部分地区，为日军提供兵源和情报，参与围剿辽西抗日义勇军。', '内蒙古通辽_奈曼旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('29d5a6243a765b6bba7b905a46b69d6c', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令', NULL, '原为热河土匪，后投靠日军，任伪蒙古军总司令，在通辽、库伦旗等地协助日军镇压抗日力量，参与‘治安肃正’行动。', '内蒙古通辽_库伦旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f6ed9df3254854c2ab80b6a58538d84b', '3613c9792d855571bd9dcedeb3091e5e', 1935, '伪库伦旗旗长', NULL, '投靠日伪政权，任库伦旗伪旗长，强制推行‘粮谷出荷’政策，强征民夫修建日军工事，迫害抗日群众。', '内蒙古通辽_库伦旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ff497e34291b5044a2e768aef4dc5fac', '3ebc486d0cc35745b5221bd653b89bcf', 1932, '伪通辽县县长', NULL, '原为地方士绅，后投靠日军，任伪通辽县县长，协助日军建立保甲制度，搜捕抗日地下人员，强征军粮。', '内蒙古通辽_库伦旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('39fc0bfb59e150eca49c5e90aa35ae27', 'cdd3637bd3b75f5b8e78c1289053459c', 1934, '伪兴安西省省长', NULL, '蒙古王公出身，投靠日本关东军，任伪兴安西省省长，管辖通辽、库伦旗等地，推行‘蒙地奉上’政策，为日军提供兵源和物资。', '内蒙古通辽_库伦旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('05a7a88e1b465194b7c27b450e8bcec5', '7893cdab2278525ca46f22df1ae1de18', 1935, '伪兴安西省警务厅长', NULL, '在通辽、库伦旗地区组织伪警察队，参与‘清乡’行动，杀害抗日军民，协助日军强征劳工。', '内蒙古通辽_库伦旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('918d64a12c49515da5ce18adbdb86918', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省警备司令（曾驻通辽）', NULL, '原奉系军阀，九一八后投敌，率伪军多次进犯通辽、库伦旗，围剿抗日义勇军，烧毁村庄。', '内蒙古通辽_库伦旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('80134d4811355985b7bb449c0f92cc46', '7ee6b737ce1d55a9866b5156643815fa', 1933, '伪满‘讨伐’军头目', NULL, '土匪出身，投靠日军后率伪军在库伦旗、通辽一带‘讨伐’抗日武装，屠杀百姓，掠夺牲畜。', '内蒙古通辽_库伦旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1f44ec220a6c59ed8ba3401e4a036854', '0783da7f980d5f62939afcf55f8baaa9', 1932, '伪兴安南省省长、伪满洲国陆军中将', NULL, '科尔沁左翼中旗人，蒙古族。九一八事变后投靠日本关东军，参与组建伪兴安军，任伪兴安南省省长，协助日军镇压蒙古族抗日武装，推行奴化教育，强征劳工，为日军提供物资和情报。', '内蒙古通辽_科尔沁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f908c458aa715709aa80129f51c08cea', 'b62352fbc8f85eb6b40ef0dc25685166', 1932, '伪兴安军总参谋长、伪满洲国陆军少将', NULL, '科尔沁左翼中旗人，甘珠尔扎布之弟。长期在伪兴安军任职，参与指挥伪军围剿抗日游击队，配合日军“治安肃正”行动，残害抗日军民。', '内蒙古通辽_科尔沁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5ea517af9538542c96b99f3721706c86', '6b5fb4ffaaaf5d6baf9d53a79ad37110', 1933, '伪兴安南省警备军司令', NULL, '科尔沁左翼后旗人，蒙古族。投靠日军后任伪警备军司令，多次率伪军袭击抗日武装，协助日军建立“集团部落”，制造无人区，强征牧民从军。', '内蒙古通辽_科尔沁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('562abe1b51835bf0b93e841bda87d7d4', 'ef60fdd2fb755383bae49a9449061381', 1934, '伪兴安西省省长（后并入兴安总省）', NULL, '科尔沁右翼前旗人，蒙古族。任伪省长期间，推行日本殖民政策，强征土地，组织伪警察镇压反抗，为日军提供粮食和牲畜。', '内蒙古通辽_科尔沁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('db02692fad7d5b14b52b51567b6f7257', '9a2d8c78a78b5e01bfaed10eb6318722', 1935, '伪通辽县公署参事官、伪兴安南省民政厅长', NULL, '科尔沁左翼中旗人。在通辽地区协助日军建立保甲制度，强征劳工修建军用公路和机场，参与“清乡”行动，逮捕抗日地下工作者。', '内蒙古通辽_科尔沁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a45416ce96b750adb38da73b84f81803', '300b0b13e1f4525cae469312175046bc', 1936, '伪兴安南省警务厅长', NULL, '科尔沁左翼后旗人。主持伪警务，组织特务网，破坏抗日地下组织，多次率警察队围剿抗日游击队，刑讯逼供抗日志士。', '内蒙古通辽_科尔沁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1aa890cd89e453a9b2bc750e75a16450', '98ff81fcf3875d5ba28789ef6b061950', 1937, '伪科尔沁左翼中旗旗长', NULL, '在旗内强制推行“出荷粮”制度，搜刮民财，强征青年加入伪满军，协助日军镇压蒙古族民众的反抗运动。', '内蒙古通辽_科尔沁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ee088ea19fed5db19c10a8a65c15fc24', '19e984de1b5450e698cb26691a29a327', 1938, '伪科尔沁左翼后旗旗长', NULL, '积极执行日本“开拓团”移民政策，强占牧民草场，组织伪旗公署武装配合日军“讨伐”，杀害抗日群众。', '内蒙古通辽_科尔沁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8236fa67f5b85dad9277989057f0a550', 'ff0f89e65f4950a6809413d19bf70e97', 1939, '伪兴安南省警备军团长（后反正）', NULL, '科尔沁左翼中旗人。早期在伪军中任职，参与镇压抗日活动，但后期于1945年8月率部反正，故仅列其投敌时期行为。', '内蒙古通辽_科尔沁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fd9e712f82d05c13aeed7ab8ca223d83', 'f425524fe4e055cd9c0602988bdea35c', 1940, '伪通辽地区保安队队长', NULL, '在通辽县城及周边为日军充当鹰犬，搜捕抗日分子，参与“三光”政策下的扫荡行动，抢劫百姓财物。', '内蒙古通辽_科尔沁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0ff82c443dfa57a1b616d3fb601ff11e', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪蒙古联合自治政府副主席', NULL, '原东北军军官，后投靠日军，组建伪蒙古军，在通辽及内蒙古东部地区协助日军镇压抗日力量，参与“治安肃正”行动，掠夺资源，迫害民众。', '内蒙古通辽_通辽经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e7413b44815053e989516b6036e05621', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙古联盟自治政府主席、伪蒙疆联合自治政府主席', NULL, '蒙古王公，与日军合作，在内蒙古地区建立伪政权，其势力范围涉及通辽一带，推行奴化教育，配合日军经济掠夺和军事统治。', '内蒙古通辽_通辽经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6a748ecf37a85b3cb9e3000c67d518e5', '987a275226335a46b1a0fdc3d18055ae', 1936, '伪蒙古军政府总参谋长、伪蒙古军中将', NULL, '参与伪蒙古军组建，在通辽及哲里木盟地区协助日军清剿抗日武装，强征民夫，为日军提供情报和后勤支持。', '内蒙古通辽_通辽经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f61747f6f6ad56d68d5bf57b82bdb330', '7893cdab2278525ca46f22df1ae1de18', 1937, '伪蒙古军第1师师长、伪蒙古军第9师师长', NULL, '在通辽、开鲁等地率伪军配合日军“扫荡”，屠杀抗日军民，抢夺牲畜粮食，破坏抗日根据地。', '内蒙古通辽_通辽经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9ad154032d345f22a9ba337903060c7a', '300b0b13e1f4525cae469312175046bc', 1932, '伪兴安西省省长、伪满洲国兴安总署参事', NULL, '在通辽所属的兴安西省（今通辽部分地区）任伪职，推行伪满洲国殖民政策，强征土地，组织伪警察镇压反抗。', '内蒙古通辽_通辽经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a1ed6eb37f3d53638faaef50e5b0cd16', '6112f4dfd9635c88a5c0c89afa7da57a', 1932, '伪通辽县县长', NULL, '任伪通辽县县长期间，为日军征收粮饷，抓捕抗日志士，协助日军建立保甲制度，实施“连坐”统治。', '内蒙古通辽_通辽经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('aa5e65ca7d0157289954b3f2af65ac81', '8aa7ccd414bb5151beecd79da6cbd86b', 1933, '伪通辽县警务科科长', NULL, '指挥伪警察在通辽城区及周边搜捕地下抗日人员，刑讯逼供，多次参与日军“讨伐”行动。', '内蒙古通辽_通辽经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('be9a859582a154ef942631f3275196d7', '3c0cec769a465f2da5d9587d32cf51f4', 1934, '伪通辽地区保安队队长', NULL, '率保安队配合日军在通辽经开区（原通辽县辖区）一带清乡，烧毁村庄，杀害无辜百姓，掠夺财物。', '内蒙古通辽_通辽经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dd8d8275852c57e39730da371c021900', '409d15a867215376a5408b6b91819650', 1935, '伪兴安南省警备军团长', NULL, '在通辽、科尔沁左翼后旗等地驻防，参与日军“治安肃正”，围剿抗日游击队，残害蒙汉民众。', '内蒙古通辽_通辽经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8c73125a120a505692270581bb6f8536', 'b3d853b6e1e3564bb50b6ff7577f9c76', 1932, '伪兴安西省警务厅长', NULL, '在通辽地区推行伪满警察制度，组织特务网络，破坏抗日组织，协助日军强征劳工。', '内蒙古通辽_通辽经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1842c50d6af657f6ad2abcbe5e3dea5d', '03751651c36952668c9b65b923b9c221', 1933, '伪蒙古联盟自治政府主席、伪蒙疆联合自治政府主席', NULL, '在鄂尔多斯及内蒙古西部策划“蒙古独立”，投靠日本关东军，建立伪蒙政权，配合日军对伊克昭盟（今鄂尔多斯）进行殖民统治和军事镇压。', '内蒙古鄂尔多斯');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('55e4bd319fca5ff09a6cb4b82fbeb13e', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪蒙疆联合自治政府副主席', NULL, '率伪蒙古军多次进犯鄂尔多斯地区，参与围剿抗日武装，协助日军在伊克昭盟推行“治安肃正”，残害抗日军民。', '内蒙古鄂尔多斯');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c531c1bc01175d24ba103e097150f1c5', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙古联盟自治政府总务部长、伪蒙疆政府政务院院长', NULL, '作为德王主要幕僚，参与伪政权对鄂尔多斯各旗的行政控制，推行奴化教育和物资掠夺政策。', '内蒙古鄂尔多斯');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('89a2a0849fa258f6b5a06eb9c28466bb', '66f4a5c280815acc8e8258aae4d43407', 1936, '伪蒙古军政府秘书长、伪蒙疆政府参议', NULL, '在鄂尔多斯地区为日军搜集情报，协助伪政权征粮派款，破坏当地抗日地下组织。', '内蒙古鄂尔多斯');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0bae470ad68e58f58cd62d2000bda703', 'f3baedeec5d9550c9fe76ccba55e98b1', 1937, '伪蒙古军第1师师长', NULL, '率伪蒙古军驻扎鄂尔多斯北部，配合日军“扫荡”达拉特旗、杭锦旗等地，杀害抗日游击队成员。', '内蒙古鄂尔多斯');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c036123a85c05846a28c5ec846a14ef9', '10cf9499b86c5eb48e46960674ae33ce', 1938, '伪伊克昭盟盟长（后任）', NULL, '在日军扶植下担任伪伊克昭盟盟长，强迫各旗王公向日军效忠，组织伪警察镇压反抗民众。', '内蒙古鄂尔多斯');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('373fc0d1475c5291b10a189d8ed4a1be', '727b4e4be11055f4aa12b2612d4f056c', 1939, '伪伊克昭盟副盟长、伪鄂尔多斯保安队指挥官', NULL, '协助日军在鄂尔多斯建立伪保安队，参与抓捕抗日志士，为日军提供劳役和粮食。', '内蒙古鄂尔多斯');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6da496f743bd5d4f8e0f101b8cd0be4c', 'f755416a4e3a5db7bd2d187663706fd1', 1937, '伪达拉特旗扎萨克（旗长）', NULL, '投靠日军，在达拉特旗推行“保甲制度”，强征壮丁补充伪军，并配合日军对黄河以南地区进行经济封锁。', '内蒙古鄂尔多斯');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0fd6630a11255444b94bbac77c926ea8', '3f78c06af8dc5b588e032beca890c683', 1938, '伪杭锦旗协理、伪蒙古军第9师军官', NULL, '在杭锦旗为日军征收牲畜和皮毛，参与围剿中共领导的桃力民抗日游击队。', '内蒙古鄂尔多斯');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b414dd79b7925e63858ba5c21de9c409', '349c2c8dff795beaaa9abd88acb394e4', 1939, '伪乌审旗保安团长、伪伊克昭盟警备军指挥官', NULL, '在乌审旗残酷镇压牧民抗日活动，多次袭击八路军骑兵支队，杀害多名革命干部。', '内蒙古鄂尔多斯');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('66e83c2473fa51b19bc7df3a13f3c24c', 'daa7800f6f0d536db2b4db1f4fbebc90', 1940, '伪鄂托克旗保安司令', NULL, '依附日军，在鄂托克旗设立伪警察所，禁止牧民与抗日武装接触，并参与日军“清边”行动。', '内蒙古鄂尔多斯');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('47441b6e98175011b4e24cb57c9781cd', 'cefbc210eea2517d9440a70e54fe5ee4', 1937, '伪准格尔旗协理', NULL, '为准格尔旗日军据点提供情报，协助伪军强征民夫修筑工事，迫害倾向抗日的蒙古族青年。', '内蒙古鄂尔多斯');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cd2534260f6552cf98b0fadf7c5620a5', '4c6ec48b14d35db9a7441c63256666c3', 1938, '伪郡王旗（今伊金霍洛旗）扎萨克', NULL, '公开投日，在郡王旗悬挂日本旗，强迫旗民向日军献马献粮，并阻挠成吉思汗陵西迁中的抗日宣传。', '内蒙古鄂尔多斯');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('41e5a699b1fa5738b800d8cd264a8358', '5f6d81998a9751eaa7c1fc2f15c493ec', 1941, '伪札萨克旗（今属伊金霍洛旗）保安队长', NULL, '率伪保安队配合日军“扫荡”札萨克旗南部，抓捕并杀害抗日地下交通员。', '内蒙古鄂尔多斯');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('09f03c5394d55fcab2c36bdba7304ac8', 'dcb2a4ba17ad58c7a7b24d93552dc4f4', 1937, '伪伊克昭盟盟长（初期）', NULL, '在日军威逼下曾出任伪盟长，默许日军在鄂尔多斯设立特务机关，后因国民党争取而动摇，但前期行为已构成附逆。', '内蒙古鄂尔多斯');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('13e2b40af9f05d5181c94fd4bf61bfb9', '2b5378ecc56d5f4f84f06756e495b505', 1936, '伪蒙古军第1军军长、伪绥西自治联军总司令', NULL, '原为土匪出身，后投靠日军，在鄂尔多斯及东胜地区协助日军进攻抗日武装，镇压民众，掠夺物资，是当地主要汉奸头目之一。', '内蒙古鄂尔多斯_东胜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('16919ce8bbe85892b7b45c79f9a69d3a', '48d43b75209b51e7a30d96d4dd8a4319', 1938, '伪伊克昭盟盟长、伪蒙古军第2军军长', NULL, '蒙古族贵族，投靠日本后任伪伊克昭盟盟长，在鄂尔多斯地区推行日伪统治，强迫牧民缴粮纳税，协助日军清剿抗日力量。', '内蒙古鄂尔多斯_东胜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3c23000c4e4a53abbfa5ce1d352125de', '3f78c06af8dc5b588e032beca890c683', 1939, '伪伊克昭盟副盟长、伪蒙古军第3师师长', NULL, '在鄂尔多斯地区组织伪蒙古军，配合日军扫荡东胜周边，残害抗日军民，强征民夫修筑工事。', '内蒙古鄂尔多斯_东胜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8cd36ea040c45538819daf298157bea1', 'b841b838b8435f50898e953253608a1f', 1940, '伪鄂尔多斯保安队队长', NULL, '在东胜及伊金霍洛旗一带为日军搜集情报，抓捕抗日地下人员，参与镇压当地反抗活动。', '内蒙古鄂尔多斯_东胜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ed8894bd78ac51679b6f67bfac1158f3', 'cdaf596844505e57823345c13fefecf0', 1941, '伪东胜县知事（县长）', NULL, '任伪东胜县知事期间，推行日伪保甲制度，强征粮食，组织汉奸武装，协助日军控制东胜城区及周边。', '内蒙古鄂尔多斯_东胜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7fb8ae69bfe752f980d63b0bee9eacae', '0252fd52c0055060abe57096ca4c50be', 1942, '伪东胜县警察局局长', NULL, '在东胜地区为日军效力，搜捕抗日分子，迫害百姓，参与日伪“治安强化”行动。', '内蒙古鄂尔多斯_东胜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8e78d282c2f75d55b6210c79ba8dcfcb', '6be2c737b9c856c88bdfbbf92df75721', 1940, '伪伊克昭盟保安司令部参谋长', NULL, '参与策划对东胜地区抗日游击队的围剿，协助日军建立情报网，破坏抗日组织。', '内蒙古鄂尔多斯_东胜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1dae79ed3cd8572cb6e2abe03407cd0a', 'daa7800f6f0d536db2b4db1f4fbebc90', 1937, '乌审旗保安团团长、伪伊克昭盟乌审旗扎萨克', NULL, '投靠日军及伪蒙疆政权，任乌审旗保安团团长，协助日军镇压抗日力量，参与“伊盟事变”中镇压蒙古族人民的反抗，迫害进步人士，强征民夫为日军服务。', '内蒙古鄂尔多斯_乌审旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eddfc527600c5ff0abc56e5bf5ca5f22', '349c2c8dff795beaaa9abd88acb394e4', 1938, '乌审旗协理、伪伊克昭盟乌审旗代理扎萨克', NULL, '与日军及伪蒙疆政府勾结，在乌审旗推行伪蒙疆政策，协助日军征收粮草、马匹，破坏抗日活动，参与围剿中共领导的抗日游击队。', '内蒙古鄂尔多斯_乌审旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6d975a8c84e25f5ca936a422363a6567', '1ca68bd301eb546ea44a8b65b829569d', 1940, '伪乌审旗保安队队长', NULL, '率保安队投靠伪蒙疆军，多次配合日军“扫荡”乌审旗南部抗日根据地，杀害抗日军民，抢劫财物，并强迫牧民迁徙至日军控制区。', '内蒙古鄂尔多斯_乌审旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('caf91d5677d2535fbd281dbdcf1c1dc4', '039316d8598c556597a95c9463c40d88', 1941, '伪伊克昭盟乌审旗警察署署长', NULL, '效忠伪蒙疆政权，在乌审旗建立伪警察体系，搜捕抗日地下工作者，向日军提供情报，参与镇压“独贵龙”运动余部。', '内蒙古鄂尔多斯_乌审旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b6feeb4418fa5662ab885fb0661f4467', '5f6d81998a9751eaa7c1fc2f15c493ec', 1939, '伪乌审旗公署翻译官兼情报员', NULL, '为日军及伪蒙疆政府担任翻译，刺探中共伊克昭盟工委及陕北根据地的军事动向，多次引导日军袭击乌审旗边境的抗日武装。', '内蒙古鄂尔多斯_乌审旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('de58db1c5bcf5fd6a8e2a99f47edb4ae', '3f78c06af8dc5b588e032beca890c683', 1937, '伪达拉特旗保安司令', NULL, '投靠日军，任伪伊克昭盟达拉特旗保安司令，协助日军镇压抗日力量，强征民夫修建军事设施。', '内蒙古鄂尔多斯_达拉特旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1267c5b8c6635bbeb2808db3725735c8', '48d43b75209b51e7a30d96d4dd8a4319', 1938, '伪达拉特旗西协理兼保安团长', NULL, '投靠日伪，任伪达拉特旗西协理，配合日军“扫荡”抗日根据地，向日军提供情报并征收粮草。', '内蒙古鄂尔多斯_达拉特旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a5df88cad89f5418acdc47fbce3c7dbc', 'd8371b88ce3259b7b3252464e4585980', 1939, '伪达拉特旗东协理', NULL, '充当日军傀儡，参与组织伪旗公署，协助日军推行“治安强化运动”，迫害抗日军民。', '内蒙古鄂尔多斯_达拉特旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9717cc9353fb580cb49247a306710539', 'bae12dcc23085ac1ac1f1ca631dfb851', 1940, '伪达拉特旗保安队副官', NULL, '为日军效力，参与围剿八路军游击队，抓捕并杀害抗日群众，充当日军翻译和密探。', '内蒙古鄂尔多斯_达拉特旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('183cb8b97b1b5a00a4dba7d296dba5f7', '13ab498376e75d43bb862d4beffef2ea', 1941, '伪达拉特旗警察署署长', NULL, '效忠日伪政权，指挥伪警察镇压抗日活动，强征壮丁，勒索百姓，协助日军掠夺当地资源。', '内蒙古鄂尔多斯_达拉特旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('37c3a9f147255534999d9df0e527bb30', 'c6f7e697c35754e3925f4dea865d8a0e', 1938, '鄂托克旗保安司令部副官、日伪“绥西自治联军”团长', NULL, '投靠日军后，在鄂托克旗及周边地区为日军搜集情报，协助日军镇压抗日力量，并参与日伪军对当地牧民的掠夺和迫害。', '内蒙古鄂尔多斯_鄂托克旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2130771088285a73a1674694e2af8148', '6535c1710ff451369315999175829977', 1937, '鄂托克旗保安司令、后投日任伪“伊克昭盟公署”顾问', NULL, '原为地方武装首领，1938年后暗中与日军勾结，向日军提供军需物资和情报，并阻挠抗日武装在鄂托克旗的活动，1943年被抗日力量处决。', '内蒙古鄂尔多斯_鄂托克旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('735cb17819105a16b521f91d213bb52d', '1ca68bd301eb546ea44a8b65b829569d', 1940, '鄂托克旗伪警察署署长', NULL, '在日军扶植下建立伪警察机构，负责搜捕抗日分子，强征民夫为日军修筑工事，并参与对当地民众的敲诈勒索。', '内蒙古鄂尔多斯_鄂托克旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('396236717d365bd5b2146493da471a11', '349c2c8dff795beaaa9abd88acb394e4', 1941, '鄂托克旗伪旗长（日伪时期）', NULL, '在日本顾问控制下出任伪旗长，推行日伪“蒙疆”政策，强制收缴民间枪支，强迫牧民“捐献”牲畜支持日军，并协助日军镇压反日牧民。', '内蒙古鄂尔多斯_鄂托克旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e8243a2ef4335ee29f38983b54b554ca', 'e8ea5bffea635dfd8a05606a164649a9', 1939, '日伪“鄂托克旗维持会”会长', NULL, '组织维持会为日军提供粮草和向导，配合日军“扫荡”抗日游击队，并参与诱捕抗日地下工作人员。', '内蒙古鄂尔多斯_鄂托克旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('66c9393c4e31554c9e97a2293c17a4cc', '03751651c36952668c9b65b923b9c221', 1933, '蒙疆联合自治政府主席', NULL, '在锡林郭勒盟（含今二连浩特地区）发起‘蒙古自治运动’，后投靠日本，建立蒙疆政权，配合日军统治内蒙古地区。', '内蒙古锡林郭勒_二连浩特');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cf7959e82d3656e3a7a6f094013c843b', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '蒙疆联合自治政府副主席、伪蒙古军总司令', NULL, '原为热河地方军阀，后投靠日本，在锡林郭勒及察哈尔地区组织伪蒙古军，协助日军镇压抗日力量。', '内蒙古锡林郭勒_二连浩特');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4e03e169651c57e093b963e952f08289', '987a275226335a46b1a0fdc3d18055ae', 1938, '伪蒙疆政府政务院院长', NULL, '参与德王伪政权，负责行政事务，在锡林郭勒盟推行日本殖民政策。', '内蒙古锡林郭勒_二连浩特');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e7afc607c91e5dd0b2876a6d3c89855a', '66f4a5c280815acc8e8258aae4d43407', 1937, '伪蒙疆政府参议、锡林郭勒盟盟长', NULL, '作为锡林郭勒盟地方贵族，投靠日本，协助维持伪政权在草原地区的统治。', '内蒙古锡林郭勒_二连浩特');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('07662f2d5b9657cca72eda018dc3fbb8', '10cf9499b86c5eb48e46960674ae33ce', 1937, '伪锡林郭勒盟副盟长', NULL, '在德王伪政权下担任副盟长，参与征收粮草、征发民夫等为日军服务。', '内蒙古锡林郭勒_二连浩特');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3060b009f91657d5bede6e85d06267f5', '2dead506b01556878a3873c74d1af922', 1939, '伪锡林郭勒盟东部联合旗旗长', NULL, '在二连浩特附近地区（今苏尼特左旗/右旗一带）担任伪旗长，协助日军控制边境。', '内蒙古锡林郭勒_二连浩特');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('22f65de232ee56d8a36e5c47bb758586', 'cc3c84d84bcb5482871d1d876bcb4188', 1936, '伪蒙古军师长、驻锡林郭勒地区指挥官', NULL, '指挥伪蒙古军部队在锡林郭勒草原扫荡抗日游击队，并参与对苏蒙边境的侦察。', '内蒙古锡林郭勒_二连浩特');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c9c66000d59d538298256a0e402e71bf', '7893cdab2278525ca46f22df1ae1de18', 1937, '伪蒙古军总参谋长', NULL, '参与策划伪蒙古军在锡林郭勒及二连浩特地区的军事行动，协助日军建立情报网。', '内蒙古锡林郭勒_二连浩特');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ef1c1e8a97b357dd9b3468d6e3bf1605', '03751651c36952668c9b65b923b9c221', 1933, '蒙疆联合自治政府主席、伪蒙古军总司令', NULL, '苏尼特右旗扎萨克亲王，1933年策动内蒙古独立，后投靠日本，组建伪蒙古军，任蒙疆联合自治政府主席，配合日军统治内蒙古地区，镇压抗日力量。', '内蒙古锡林郭勒_苏尼特左旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('37bdbdabdaf15a3dbf6284210c6af318', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军副总司令、伪蒙疆政府副主席', NULL, '原东北军军官，后投靠德王和日军，任伪蒙古军副总司令，参与对绥远、察哈尔等地的军事行动，协助日军维持殖民统治。', '内蒙古锡林郭勒_苏尼特左旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a9e028f54ada592b8df9ab0aa3334ec8', '987a275226335a46b1a0fdc3d18055ae', 1938, '伪蒙疆政府政务院院长', NULL, '原国民党蒙藏委员会官员，投日后任伪蒙疆政府政务院院长，推行日伪法令，协助日本对内蒙古西部进行殖民统治。', '内蒙古锡林郭勒_苏尼特左旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d5637bb31b46590183af2d336a01c678', '66f4a5c280815acc8e8258aae4d43407', 1937, '伪蒙疆政府参议、苏尼特左旗伪旗长', NULL, '苏尼特左旗贵族，投靠日本后任伪旗长，协助日军征粮派款、强征劳工，镇压当地抗日活动。', '内蒙古锡林郭勒_苏尼特左旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b02cc9f422ee5d83a6c621ca6ccde095', 'd20dc98a469e5262ac91c570963efebd', 1937, '伪蒙疆政府察哈尔盟盟长', NULL, '原察哈尔部总管，投日后任伪察哈尔盟盟长，管辖苏尼特左旗等地区，推行日伪保甲制度，搜刮民财。', '内蒙古锡林郭勒_苏尼特左旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c53ed62539dd56f788964948d1979428', '4858ca8309a454e28d3ed02c77c72106', 1938, '伪蒙疆政府司法部长', NULL, '原锡林郭勒盟副盟长，投日后任伪司法部长，参与制定镇压抗日民众的法令，迫害蒙汉进步人士。', '内蒙古锡林郭勒_苏尼特左旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0423358ac600515cbba6b4d419a360bc', '10cf9499b86c5eb48e46960674ae33ce', 1939, '伪蒙疆政府内政部长', NULL, '原苏尼特左旗贵族，投日后任伪内政部长，协助日本特务机关监控当地民众，破坏抗日地下组织。', '内蒙古锡林郭勒_苏尼特左旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('12003c70626e56159b722893565da57d', '2384ff93635957b9b66f9997bbbc5580', NULL, '阿拉善旗札萨克（旗王）', NULL, '在抗日战争期间，虽名义上隶属国民政府，但为保全自身利益，与日本特务机关及伪蒙疆政权保持暧昧关系，曾接待日本特务人员，并默许日伪势力在旗内活动，未积极抗日。', '内蒙古阿拉善_阿拉善右旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ab9dbf56c11656fb8ecb28db23c4784d', '4263777d01945044b7eeca4cfe11d4ef', NULL, '阿拉善旗协理', NULL, '协助达理札雅处理旗务，与日本特务及伪蒙疆政权有暗中往来，曾为日军搜集阿拉善地区情报，并协助日伪人员渗透旗境。', '内蒙古阿拉善_阿拉善右旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('08272e4922f757d1b1601fd91b330b59', 'd22406c8944d55318c5309341b595eae', NULL, '阿拉善旗喇嘛庙上层喇嘛', NULL, '利用宗教身份为日本特务机关传递情报，煽动部分蒙古族民众对日伪政权持友好态度，并参与接待日本考察团。', '内蒙古阿拉善_阿拉善右旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4930e20a097951ee826358faf49d5056', '2e64c685b85b5c039a01ef4eab99e7ef', NULL, '阿拉善旗保安队军官', NULL, '在日伪势力拉拢下，曾向伪蒙疆政权提供阿拉善旗军事布防信息，并协助日伪人员偷运武器进入旗境。', '内蒙古阿拉善_阿拉善右旗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dfef8d922fb25664b16e8fbf52bfd835', '4d2d3d155bb454339a738c1c49764a53', 1937, '伪华北政务委员会委员长', NULL, '1937年北平沦陷后出任伪中华民国临时政府行政委员会委员长，后任伪华北政务委员会委员长，积极推行日本殖民统治，镇压抗日活动。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('acb7f397497e531a9f5bd7089c5d8251', 'f507817e989158b6a3fd828c617b43cd', 1937, '伪华北政务委员会内政总署督办、伪国民政府考试院院长', NULL, '曾任伪中华民国临时政府议政委员会常务委员，后任伪华北政务委员会内政总署督办，协助日军在北平及华北地区推行治安强化运动。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4d8c944129dc5480835cc112325a51c5', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北治安军总司令', NULL, '北平沦陷后投敌，任伪华北治安军总司令，组织伪军协助日军清剿抗日武装，在北平及周边地区实施“扫荡”。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('97b280620be254be879ae5303c397031', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府委员长', NULL, '1935年成立伪冀东防共自治政府，管辖包括北平东部地区，后并入伪中华民国临时政府，长期为日本侵略服务。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('56639da10ec353e59802f422c479f1c7', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府秘书长', NULL, '协助殷汝耕管理伪冀东政权，参与对北平东部地区的殖民统治和物资掠夺。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f7e1cb8a308455b98263728793fdcef0', '911fda0920525bc1b3c52a4451339c82', 1938, '伪华北政务委员会常务委员、伪北京市长', NULL, '曾任伪中华民国临时政府司法委员会委员长，后任伪华北政务委员会常务委员，并一度兼任伪北京市长，推行日伪法令。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1a8ee608b59f5f9cb9f898e39a408d15', '37b4d45b85b2500c8c00d62157eee60d', 1938, '伪北京市市长', NULL, '1938年出任伪北京市市长，在任期间配合日军实施保甲制度、粮食统制，镇压北平城内抗日地下活动。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f187b14c8dfc51b0a4ce5965233d367f', '81630a2fb4475f6f9739f4b7c0996e70', 1938, '伪北京市警察局局长', NULL, '任伪北京市警察局局长，负责北平城内的治安监控，大肆搜捕抗日志士，协助日军进行“思想战”。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f5cda046b4a851de821d3e3404096c57', 'd941126e8c785a22a9720c46c6bd1778', 1940, '伪华北政务委员会治安总署督办', NULL, '曾任伪华北治安军高级将领，参与指挥伪军在北平东城及周边地区镇压抗日力量。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b3be180310a8505f86b9eb686b3a88f6', '7c51a2464caa5e18aaf829b24f6c43bc', 1940, '伪华北政务委员会绥靖总署督办', NULL, '在北平任职期间，负责伪军整编和“剿共”军事行动，对东城地区的地下抗日组织进行破坏。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c1a8805b46945459bfdfd64cf84e4947', '75d8bf07a9d358088ac18c65c44c0f26', 1938, '伪中国联合准备银行总裁', NULL, '在北平东城设立伪中国联合准备银行总部，发行伪币，掠夺中国资财，为日军侵华战争提供经济支持。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f937efb1c0375e97b11bbc2a9cec7337', '623d392eb5a05d4cac7b4f9ccb0a1da6', 1937, '伪华北政务委员会咨询委员', NULL, '北洋时期政客，北平沦陷后接受伪职，虽未直接掌权，但利用旧关系为日伪政权笼络人心。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('135d8b7f2b3f5168ac848a16f277fedd', '47c2a5c483015a58bd37abc52be5e3fe', 1937, '伪华北政务委员会顾问', NULL, '曾任北洋政府官员，后投靠日伪，在北平担任顾问，参与策划经济统制政策。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b3b761377f765eb99a42bcfa2d4a1bc3', 'e9dcbc06f7da51b491b08b0a854afc6e', 1937, '伪华北政务委员会咨询委员', NULL, '北洋政府前官员，北平沦陷后出任伪职，为日伪政权提供政治咨询，协助维持殖民秩序。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c1fdc1eb0a205031bd8a9de982b654ee', '21cc4aaf640b5ed887e72b8e95768412', 1937, '伪北平维持会会长', NULL, '1937年北平沦陷后率先组织伪北平维持会，迎接日军进城，后任伪临时政府顾问，是东城地区早期汉奸头目。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f2781f74e35858e3a9e14dc58c1cb61f', '2f5ae369af5d5ad4850f67907bb9b8aa', 1938, '伪北平市商会会长', NULL, '任伪北平商会会长期间，强迫商户为日军提供物资，协助日伪进行经济掠夺和粮食配给。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('acc2e592fd3f52b79bc9bd3eb2a91954', '1e54aa620f8857b2bbddf71bf2d6391c', 1940, '伪华北政务委员会实业总署督办', NULL, '在北平主管伪实业部门，推动华北资源对日输出，参与对东城工商业的统制。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('46fba95ecc695b858e135ed4171c57d0', '95ff7846d44f5084991c9d5d1c60db78', 1940, '伪华北政务委员会外交总署督办', NULL, '负责伪华北政权对外事务，协助日本控制北平外交资源，镇压抗日外交活动。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('42c885775cc85597804f2aa7c3310107', '048718df0a8f5b4f87ffcb385f5b35ab', 1940, '伪华北政务委员会教育总署督办', NULL, '在北平推行奴化教育，修改教科书，强制学校教授日语，破坏东城地区教育体系。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('28b0d8da8af059a6ac6f7aa484ba3b17', '7db565fbb6f85076949c7779b860a64f', 1938, '伪北京市工务局局长', NULL, '负责北平市政工程，为日军修建军事设施，强征民夫，破坏城市基础设施。', '北京东城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4c6d054c8d2c525d93bdb1c5ee9db643', 'f507817e989158b6a3fd828c617b43cd', 1937, '伪华北政务委员会内务总署督办、伪华北政务委员会委员长', NULL, '原北洋政客，投日后任伪华北政务委员会要职，在北平（今北京）及丰台地区推行日伪统治，协助日军征粮、镇压抗日活动。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d1e7766a638d5aefa1c8a6d32df51a9c', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北治安军总司令、伪华北政务委员会治安总署督办', NULL, '原直系军阀，投日后负责华北伪军，在丰台及北平周边配合日军“扫荡”，镇压抗日武装。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('62bad00d679b57eabb64fc4eb266aecb', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府委员长', NULL, '早年在冀东成立伪政权，其势力范围曾涉及北平近郊及丰台一带，为日军提供情报和后勤支持。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('17932b5917c9557f9126ab0b1961b5d5', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府秘书长、伪北平市警察局局长', NULL, '殷汝耕亲信，后任伪北平警察局长，在丰台地区协助日军维持治安，镇压抗日民众。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ae085856c8175df9ba9506ead68c9cbf', '340adba25424535985417eba5e18abbe', 1937, '伪北平市市长', NULL, '投日后任伪北平市长，管辖包括丰台在内的北平地区，推行日伪法令，强征物资。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a9083fac06b55da988faecbda6da085b', '37b4d45b85b2500c8c00d62157eee60d', 1938, '伪北平市市长、伪华北政务委员会常委', NULL, '继任伪北平市长，在丰台地区设立伪警察机构，配合日军“清乡”和粮食统制。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fd4275d4b3715929907c328c66be74bf', '81630a2fb4475f6f9739f4b7c0996e70', 1938, '伪北平市警察局局长', NULL, '长期任伪北平警察头目，在丰台地区抓捕抗日地下人员，执行日伪保甲制度。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d8b1e237f58a5963b4e90594e98dc41e', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪华北政务委员会教育总署督办', NULL, '在北平及丰台推行奴化教育，控制学校，强迫学生参加日伪活动。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b92d76d8fd7b5af4b43261cc31fcba32', '75d8bf07a9d358088ac18c65c44c0f26', 1938, '伪中国联合准备银行总裁', NULL, '在北平设立伪银行，发行伪币，在丰台地区强制兑换，掠夺经济资源。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ee82009e9b545a59b5e9349a4f8439e1', '4d2d3d155bb454339a738c1c49764a53', 1937, '伪华北政务委员会委员长（首任）', NULL, '原北洋政客，投日后主持伪华北政权，管辖北平及丰台，组织伪军和警察协助日军。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eb4d1e8f06915e9883455d7d4e2a4c0c', '911fda0920525bc1b3c52a4451339c82', 1940, '伪华北政务委员会常务委员、伪北平特别市市长', NULL, '在任期间强化丰台地区日伪统治，推行“治安强化运动”，镇压抗日力量。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bd60a970e05b5642bdc8824575cad186', 'ae8bd48eee0359c0aaae313d5b588d6f', 1944, '伪北平市市长（末任）', NULL, '抗战末期任伪北平市长，在丰台地区继续维持日伪秩序，直至日本投降。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('981a60e19c9252a4ac04b1b9c59a8f69', '07961601ff2f53f5863147f327d72168', 1937, '伪天津市市长（曾兼北平地区职务）', NULL, '虽主要任伪天津市长，但曾参与北平及丰台地区的日伪协调，协助日军镇压抗日活动。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('63d897dfbd66569cbebcdd3a5b67c17c', '7db565fbb6f85076949c7779b860a64f', 1938, '伪北平市社会局局长', NULL, '在丰台地区推行日伪社会控制，组织“新民会”分会，进行奴化宣传。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f119001e1311542ebd1df6557e623a78', 'ae5e62ce9181549e82e0d8ae0327fbba', 1938, '伪北平市新闻检查所所长', NULL, '控制北平及丰台地区报刊舆论，查禁抗日言论，为日伪宣传服务。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e713a51b6d1a56ac8007f6f0db5b7137', '07961601ff2f53f5863147f327d72168', 1937, '伪北平市警察局局长、伪华北政务委员会常委', NULL, '七七事变后投敌，协助日军维持北平治安，镇压抗日活动，参与伪华北政权组建。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a9b77085d1ab5d618515a1268e5434a3', '4d2d3d155bb454339a738c1c49764a53', 1937, '伪中华民国临时政府行政委员会委员长、伪华北政务委员会委员长', NULL, '在北平建立伪政权，推行奴化政策，为日军搜刮物资，配合“治安强化运动”。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b1cf1ebe0be45d7baf6b11ac188d9e7c', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北治安军总司令', NULL, '在北平及丰台地区组织伪军，协助日军清剿抗日武装，镇压民众反抗。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9c27af11bdb9556faaad09793a2d0fd4', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府委员长（曾辖丰台地区）', NULL, '在冀东（含丰台周边）成立伪政权，脱离国民政府，为日军提供后勤与情报支持。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f3a6a8005a785d0995014024b4fc9a14', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府秘书长、伪北平市社会局局长', NULL, '协助殷汝耕建立伪冀东政权，后在北平参与伪市政管理，迫害抗日人士。', '北京丰台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9f3fa27a87765bad8a7f2be00fff7a88', 'f507817e989158b6a3fd828c617b43cd', 1937, '伪华北政务委员会内政总署督办、伪华北政务委员会委员长', NULL, '原北洋政客，七七事变后投敌，在北平组织伪政权，任伪华北政务委员会要职，推行奴化教育，协助日军经济掠夺，镇压抗日力量。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f3f0254646615276919e0b5967dc111f', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北治安军总司令、伪华北政务委员会治安总署督办', NULL, '北洋直系军阀，投日后在北平组建伪治安军（绥靖军），配合日军“扫荡”冀中、平郊抗日根据地，在大兴一带多次清剿抗日武装。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fa566d4ede14565786470a07274a22be', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府政务长官（后并入北平伪政权）', NULL, '早年在冀东成立伪政权，后活动于北平，协助日军控制平津地区，参与对大兴等县的伪化统治，推行保甲制度。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7107b4df523352f59640b02ef7189d0f', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府秘书长、伪北平市政府参事', NULL, '殷汝耕心腹，参与冀东伪政权，后转任北平伪职，协助日军管理大兴等县行政，强征民夫和粮食。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('22d27230081f5ba4a86ac7601245a8c3', '37b4d45b85b2500c8c00d62157eee60d', 1938, '伪北平市市长（1938-1943）', NULL, '原国民党官员，投日后任伪北平市长，管辖包括大兴在内的郊区，推行日伪法令，镇压抗日活动，组织“献铜献铁”等物资搜刮。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ca618132e0cb5e1e9aa1cf4edbe96f70', '81630a2fb4475f6f9739f4b7c0996e70', 1938, '伪北平市警察局局长', NULL, '在任期间指挥伪警察在大兴等地抓捕抗日志士，破坏地下组织，协助日军设立“爱护村”和封锁沟。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('256239ab98f75646ba4175891c05b3a4', 'd941126e8c785a22a9720c46c6bd1778', 1937, '伪北平维持会会长（1937年短暂）', NULL, '七七事变后率先组织北平地方维持会，迎接日军进城，协助维持治安，后因权力斗争失势，但前期对大兴地区伪政权建立有直接影响。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b3f894c6bdf25f3db2f55fe94e47eeba', '07961601ff2f53f5863147f327d72168', 1937, '伪天津市市长（曾兼管平郊）、伪华北政务委员会委员', NULL, '原宋哲元部幕僚，投日后在北平、天津活动，参与制定对大兴等县的“治安强化”计划，提供抗日武装情报。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('61755052ec6651d8922ac9212c5b8697', '4d2d3d155bb454339a738c1c49764a53', 1937, '伪中华民国临时政府行政委员会委员长、伪华北政务委员会委员长', NULL, '伪华北最高傀儡头目，在北平设立伪政权，统辖大兴等县，推行“新民会”奴化宣传，配合日军“三光”政策。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d3e923277e825d91a784bf7796e13b51', '911fda0920525bc1b3c52a4451339c82', 1943, '伪华北政务委员会常务委员、伪北京市长（1943-1945）', NULL, '继余晋龢后任伪北平市长，强化对大兴等郊区的控制，增设伪警察分驻所，搜捕八路军地下工作人员。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c2aac420b083515a83d4111e999d7805', 'c9a7e52fd0eb523bb7dc27de493f596e', 1939, '伪山西省长（后调北平伪华北政务委员会任职）', NULL, '虽主政山西，但后期在北平参与伪华北政务，曾到大兴视察“治安强化”成果，支持日军建立“模范村”。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4a215343b62f50bd99c74be41a352daa', '75d8bf07a9d358088ac18c65c44c0f26', 1938, '伪中国联合准备银行总裁、伪华北政务委员会经济顾问', NULL, '在北平发行伪币，掠夺大兴等县物资，导致当地经济崩溃，间接支持日军战争机器。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f6c1c5ccfc9e5cf59d2f16700bb1423f', 'ae5e62ce9181549e82e0d8ae0327fbba', 1938, '伪《新民报》社长、伪华北宣传联盟负责人', NULL, '在北平控制舆论，在大兴地区散发汉奸报纸，美化日军侵略，污蔑抗日军民。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6e2dbd458b3157d3ada83b6953e69781', '048718df0a8f5b4f87ffcb385f5b35ab', 1938, '伪华北政务委员会教育总署督办', NULL, '推行奴化教育，在大兴各中小学强制使用日伪教材，删除中国历史内容，强迫学生参加“新民会”活动。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5aeb648b7f805727b27f2b34f96f0dcb', '18aef3d94e845b4db3b3f4a9edc7e359', 1938, '伪大兴县知事（县长）', NULL, '直接统治大兴县，组织伪县公署，配合日军修建炮楼和封锁沟，强征壮丁，镇压当地抗日游击队。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('450ea7eece6056638589f41e4e30a49b', 'd02f2f9296a7509fa051c8ebe09107a2', 1940, '伪大兴县知事（继任）', NULL, '任内推行“保甲连坐”，在大兴各村设立伪保长，搜捕抗日干部，向日军提供粮食和情报。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('358bc347db80558a82b43e0088e092f6', '7a06de5943d057d3b62ffe5e4296a4b3', 1942, '伪大兴县知事（后期）', NULL, '在任期间配合日军“五次治安强化运动”，在大兴南部地区制造无人区，杀害抗日群众。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c0ccda68c90658debe2c7bdb86dc97b5', '340adba25424535985417eba5e18abbe', 1939, '伪北平特别市警察局督察长（分管郊区）', NULL, '专门负责大兴、宛平等郊县“剿共”，指挥伪军警突袭村庄，逮捕抗日家属。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6ae5a660c7c55754abafa7122596265b', 'ff316bb34a4d5261b5c244468fda7a59', 1940, '伪大兴县保安队队长', NULL, '率伪保安队多次进攻大兴采育、青云店一带的抗日武装，烧毁村庄，杀害民兵。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('66123e1957365875a11afcc5b5213265', 'bd9f9f87c6ae5466b0b61cbd65e84d14', 1940, '伪华北治安军第1集团军司令（驻防平郊）', NULL, '所部驻大兴黄村、南苑等地，参与“扫荡”平南根据地，制造多起惨案。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9f3fa27a87765bad8a7f2be00fff7a88', 'f507817e989158b6a3fd828c617b43cd', 1937, '伪华北政务委员会内政总署督办、伪华北政务委员会委员长', NULL, '在北平（今北京）积极投靠日本，主持伪华北政权，推行奴化教育，镇压抗日活动，协助日军经济掠夺。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f3f0254646615276919e0b5967dc111f', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北治安军总司令、伪华北政务委员会治安总署督办', NULL, '在北平及华北地区组织伪治安军，配合日军扫荡抗日根据地，捕杀抗日军民，破坏地下组织。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('333abaae5f98568b9122fd34487a88c2', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府委员长（后并入北平伪政权）', NULL, '在冀东及北平周边地区建立伪政权，为日军提供情报和后勤支持，协助日军控制平津地区。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('434972b76d515a0299b6bb812fbb8ea5', 'be830f2d60665f0189881935079af216', 1938, '伪北平市市长（1938-1940）', NULL, '任伪北平市长期间，推行日伪法令，强征民夫物资，协助日军维持占领秩序，镇压抗日活动。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('36a8f4de76dc5bf78e75d9c21d6804cf', '37b4d45b85b2500c8c00d62157eee60d', 1940, '伪北平市市长（1940-1943）', NULL, '在北平推行保甲制度，配合日军搜捕抗日人士，强制推行粮食统制，导致民不聊生。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f7f6915a67d65402a5157f495bbf6ef4', '81630a2fb4475f6f9739f4b7c0996e70', 1937, '伪北平市警察局局长', NULL, '在北平及大兴地区指挥伪警察，协助日军逮捕抗日志士，破坏地下交通线，参与“治安强化”运动。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('954fd3e5eda85a589dae8a700afdf3e1', 'd941126e8c785a22a9720c46c6bd1778', 1937, '伪北平维持会会长（1937年）', NULL, '七七事变后率先组织维持会，迎接日军入城，协助建立伪政权，为日军征粮派款。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3e1c74acdf325a32bd86a7344e8cfdbd', '07961601ff2f53f5863147f327d72168', 1937, '伪北平市警察局局长（后任伪天津市长）', NULL, '在北平任职期间出卖抗日情报，参与镇压学生运动，协助日军清剿大兴等郊县抗日武装。', '北京大兴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7283b2d8855f57f195a122edeacb2cb2', '4fc078bb6abd52efaab226d2d53038c6', 1935, '伪冀东防共自治政府保安司令', NULL, '在密云地区协助日军镇压抗日武装，推行“治安肃正”，残害抗日军民。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('397eb107eba35a16bcd386166c882706', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府政务长官（管辖密云）', NULL, '策划冀东事变，使密云等22县脱离中国行政管辖，沦为日本傀儡统治区。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('36f537120cc5551a87fe6864dfb0d92d', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府秘书长兼密云县知事', NULL, '在密云推行奴化教育，强征民夫修建日军据点，协助日军“清乡”。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2ddca97ca1655efa82447f2327281801', 'f507817e989158b6a3fd828c617b43cd', 1940, '伪华北政务委员会委员长（管辖密云）', NULL, '在密云地区推行保甲制度，组织伪军配合日军扫荡八路军根据地。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7d3daf0e578e5098972dca7d93d991ca', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1939, '伪华北治安军总司令（在密云驻有部队）', NULL, '派遣伪治安军驻防密云，多次参与围剿密云抗日游击队，杀害无辜百姓。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('03fc6c63df22567690c2ec4b405e2363', '142ed91c1ea95b6d922d76d4627e2b83', 1937, '伪蒙古军总司令（曾窜扰密云北部）', NULL, '率伪蒙古军配合日军在密云北部山区烧杀抢掠，破坏抗日根据地。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cc66d9ae8bc85173bab4bb35fac2a5a2', '6edb269a696555c193c5c25b9caf01c3', 1938, '伪密云县保安队队长', NULL, '充当日军鹰犬，搜捕抗日干部，刑讯逼供，多次带队突袭密云村庄。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9f0832b40ec3514ba89eb397f68d82be', '33f48787d6295324995de4d2f715fb78', 1935, '伪冀东保安队总队长（活动于密云）', NULL, '在密云一带强征壮丁，配合日军建立“无人区”，制造多起惨案。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c5f3b5896fab5d6980c0778b63ceb275', '99afd279f9bb50b2b65b52b289c8e71d', 1935, '伪冀东保安队第一总队队长（驻密云）', NULL, '初期为殷汝耕效力，在密云镇压抗日活动，后反正但影响有限。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('593b7ea25c4a50ddb3b891ed8046cbbf', 'f1bc5258a2755a94b57a483a9c673bc6', 1938, '伪密云县知事（1938-1940）', NULL, '推行日伪“粮食统制”，强征密云农民粮食，导致大量饥荒。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9401a502112d5bb0861a6fdbc87775e3', '5a6833c44b3c59adaff56aaff0d11e31', 1939, '伪密云县警察局局长', NULL, '协助日军抓捕抗日家属，破坏地下交通线，残害进步群众。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eae384315dd35293a6d19d872683ec41', 'ad0c9f9af10054c68d58a879c97add74', 1941, '伪华北“剿共”军指挥官（曾活动于密云）', NULL, '率伪军配合日军“铁壁合围”，在密云云蒙山区烧毁村庄数十个。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('95aee7b7b28353fcbe4a0a07aadd7644', '99afd279f9bb50b2b65b52b289c8e71d', 1935, '伪冀东防共自治政府保安队第一总队队长', NULL, '在密云地区协助日军维持治安，镇压抗日活动，参与冀东伪政权的军事行动。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4834e0b3638d5f1eaf96fd0e9399bb51', '33f48787d6295324995de4d2f715fb78', 1935, '伪冀东防共自治政府密云县知事', NULL, '在密云县推行日伪统治，强征粮税，协助日军建立保甲制度，迫害抗日军民。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e8ea94659b01586390c63242ae403d6c', '0c6268d47d1656aeaa4e03096f2d60ea', 1938, '伪密云县保安团团长', NULL, '率保安团配合日军扫荡密云山区，围捕八路军游击队，杀害抗日干部及群众。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e1f7815ed7635f61b58279c27372a73f', '613b305324ea5706a1ce5406bd618a72', 1940, '伪密云县警察局局长', NULL, '在密云县城及周边地区搜捕抗日分子，破坏地下组织，向日军提供情报。', '北京密云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5e46f8aa42e25d249e7c6a5b7f87c0fc', '99afd279f9bb50b2b65b52b289c8e71d', 1935, '伪冀东防共自治政府保安队第一总队总队长', NULL, '1935年参与殷汝耕成立的伪冀东防共自治政府，驻防平谷、密云一带，协助日军维持治安，镇压抗日活动。1938年反正后投靠国民党，但此前已造成抗日力量损失。', '北京平谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bbb2a4abb8aa526b96767f746ad94fee', '09a43f86f2b5580c80262d0857a985bf', 1935, '伪冀东防共自治政府保安队第二总队总队长', NULL, '率部驻守平谷地区，配合日军清剿抗日游击队，多次参与“扫荡”行动，抓捕并杀害抗日军民。', '北京平谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3dc53153da3f5ecbb6b60ac129422be4', '6edb269a696555c193c5c25b9caf01c3', 1935, '伪冀东防共自治政府保安队第三总队总队长', NULL, '在平谷及周边地区执行日军命令，强征民夫修筑炮楼和公路，破坏抗日根据地交通线。', '北京平谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('553c4824f56d587f8014d04ab48f71f9', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府政务长官', NULL, '虽非平谷本地人，但其建立的伪政权直接管辖平谷，推行“自治”卖国政策，为日军提供粮秣和劳役，是平谷地区汉奸体系的最高后台。', '北京平谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4a039b07572d534ea708f81251b4499f', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府秘书长', NULL, '协助殷汝耕管理平谷等县政务，组织伪警察和保甲制度，监控抗日分子，强迫民众悬挂伪旗。', '北京平谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('67508ac1c5c55b7681dd6b49ddadeee4', '503de500a44b531d918af851527aadf1', 1936, '伪平谷县知事（县长）', NULL, '在平谷县内推行伪政权法令，征收苛捐杂税，强征壮丁补充伪军，并配合日军“治安肃正”行动。', '北京平谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2def6d7b93eb550795b3bff6513b30c5', '41265d62a2c9566781d8e01edc3f99c1', 1937, '伪平谷县保安团团长', NULL, '组织地方伪武装，多次袭击八路军游击队，破坏中共地下组织，杀害抗日干部和群众。', '北京平谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a0903ff748725e4791b7f074dd0c1b76', 'de51473be6265f10b54eec7061d19b8a', 1938, '伪平谷县警察局局长', NULL, '指挥伪警察搜捕抗日人员，严刑逼供，并协助日军建立“人圈”隔离区，导致大量平民死亡。', '北京平谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('adb7c1de2f0e5521846315eb17ba6db7', '1a6b2c0340215f378ff8d84a2f652a88', 1939, '伪平谷县新民会会长', NULL, '推行奴化教育，宣传“中日亲善”，强迫学生和民众参加反共集会，搜集抗日情报供日军使用。', '北京平谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7f96ffa1dcb752fb965bbd4f56128073', '51f0abc8d3385972b33046822359065a', 1937, '伪平谷县维持会会长', NULL, '日军占领平谷初期，组织维持会为日军筹粮筹款，提供向导，并劝降当地武装力量。', '北京平谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e3c9e1b8142b5dc28f8bd7b2884f0439', 'd20f5369a05f555585e24f85e66e19f8', 1940, '伪平谷县自卫团总团长', NULL, '率自卫团配合日军“扫荡”盘山、鱼子山等抗日根据地，烧毁村庄，抢掠物资。', '北京平谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c686cee19ee95b30b3a860a6c7a7db42', '7c0648423ccb57838732f7aeb28b3830', 1941, '伪平谷县特务队队长', NULL, '专门刺探八路军情报，诱捕抗日家属，多次带队突袭中共秘密联络点。', '北京平谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('66c61ebca7f956b89cd7f2ddf2ebca6b', 'f507817e989158b6a3fd828c617b43cd', 1937, '伪华北政务委员会内政总署督办、伪华北政务委员会委员长', NULL, '原北洋政客，投日后任伪华北政务委员会要职，在北平推行奴化教育，协助日军经济掠夺，镇压抗日活动。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('614029d7127c574592fbc6f348adeb34', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北治安军总司令、伪华北政务委员会治安总署督办', NULL, '原直系军阀，投日后组建伪华北治安军，在北平及周边地区配合日军“扫荡”，围剿八路军和抗日游击队。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fcd803c3913d5a0382d33b053f0f7de8', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府委员长（后并入北平伪政权）', NULL, '早年亲日，1935年成立冀东伪政权，后参与华北伪政权活动，在北平、延庆一带协助日军推行“自治”和殖民统治。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e2538ba42b1b50f4a6b6c184132bf729', 'be830f2d60665f0189881935079af216', 1937, '伪冀东防共自治政府秘书长、伪北平特别市市长', NULL, '殷汝耕亲信，后任伪北平市长，在北平市区及延庆等郊县推行保甲制度，强征粮食物资，镇压抗日分子。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0a849d8eeffb5d8ba1574d29ad557693', '37b4d45b85b2500c8c00d62157eee60d', 1938, '伪北平特别市市长（1938-1943年）', NULL, '原国民党官员，投日后任伪北平市长，在延庆等辖区推行日伪法令，组织“献铜献铁”，协助日军强化治安。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9f877d41180e53a98b678a2750ee6803', '81630a2fb4475f6f9739f4b7c0996e70', 1937, '伪北平特别市警察局局长', NULL, '在北平及延庆地区指挥伪警察，搜捕抗日地下人员，破坏中共地下组织，参与“治安强化运动”。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3c55fa3c4a49577ea603734aa583284e', 'd941126e8c785a22a9720c46c6bd1778', NULL, '伪北平维持会会长（1937年）', NULL, '七七事变后率先投敌，组织北平维持会，为日军提供粮食、劳力和情报，协助建立伪政权。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('710ae4a19dfc5361a603f9288d79b1f3', '07961601ff2f53f5863147f327d72168', 1937, '伪北平维持会委员、伪华北政务委员会教育总署督办', NULL, '参与北平维持会，后主管伪教育，在延庆等县推行奴化教育，强制学习日语，篡改历史教材。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5369a0ae32525b209f22fd9457a4bd79', '7db565fbb6f85076949c7779b860a64f', 1943, '伪北平特别市市长（1943-1945年）', NULL, '继任伪北平市长，在延庆等地区继续推行日伪“粮食统制”，强征农民粮食，配合日军“扫荡”。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('550927b8363c512ab36f382e241ac57e', 'ad87f7e4a912559c80661050e7208ba3', 1938, '伪华北政务委员会实业总署督办', NULL, '在北平及延庆地区控制矿山、土地资源，为日军开采铁矿石等战略物资，剥削当地劳工。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('008fc3c8d51a54a9a6d9457860540bf1', '75d8bf07a9d358088ac18c65c44c0f26', 1938, '伪中国联合准备银行总裁', NULL, '在北平发行伪币，在延庆等县强制兑换法币，掠夺民间财富，造成通货膨胀，破坏抗日经济基础。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a36948302f4b5269a141bc65d55936fc', '911fda0920525bc1b3c52a4451339c82', 1937, '伪华北政务委员会常务委员、伪司法委员会主任', NULL, '参与北平伪政权司法系统，在延庆等地设立伪法院，迫害抗日群众，判处抗日志士死刑或劳役。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b65e316687575f999f95e241aa9e624f', '4d2d3d155bb454339a738c1c49764a53', 1937, '伪华北政务委员会委员长（1937-1940年）', NULL, '原北洋财政官僚，投日后任伪华北政务委员会委员长，在北平及延庆地区全面推行日伪统治，组织“新民会”进行奴化宣传。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6ce0f63d47c05460a4f1e620779547c8', '95ff7846d44f5084991c9d5d1c60db78', 1940, '伪华北政务委员会常务委员、伪外交总署督办', NULL, '在北平参与伪政权外交事务，协助日本与汪伪政权协调，在延庆等县推行“中日亲善”宣传。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dfd0f20243f95e0db365f2cb844337cb', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省长（曾兼北平伪职）', NULL, '虽主政山西，但曾参与北平伪政权高层会议，其势力范围涉及延庆西部山区，协助日军封锁抗日根据地。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5d849c6b5bf052819c74a4695dfb0285', '3720970371315007b5ae28dc02cc15c3', 1938, '伪延庆县知事（县长）', NULL, '在延庆县任伪县长期间，强征民夫修筑炮楼和公路，组织伪自卫团，配合日军对南山（平北根据地）进行“蚕食”。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e93e212228c4561dbefcf8580998c131', '16e120c3b8d05888a4115aac4839d8b2', 1940, '伪延庆县知事（县长）', NULL, '在延庆推行“保甲连坐”制度，搜捕八路军侦察员，向日军提供抗日武装活动情报，并强征粮食支援日军。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cba96b3697a959d58af6eba63625315d', '24721b137d3d5fa69cbbfd7b4f57f2eb', 1943, '伪延庆县知事（县长）', NULL, '在延庆县实施“集家并村”，制造无人区，强迫村民迁入“人圈”，以切断八路军与群众联系，导致大量平民死亡。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('031dc2d3567b5cf4ae5960ee4118e34e', '9ca8f82df12958b9ac4d7381f7eaeeaa', 1939, '伪延庆县保安队队长', NULL, '率伪保安队多次袭击延庆南山抗日游击队，杀害抗日干部家属，参与日军“扫荡”时烧毁村庄。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('15cbc674b3f75c43a033d4fe89c1d66a', '3e06b4c62e29510eae1912bccce60793', 1940, '伪延庆县警察所所长', NULL, '在延庆县城及各乡镇设立警察分所，抓捕中共地下党员，刑讯逼供，破坏平北地委在延庆的交通站。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6fb800d1f3dc5fe9bdb97efa89f0e2a4', '53e915a30fc856da828d458cc7ae0125', 1938, '伪延庆县新民会会长', NULL, '在延庆组织新民会分会，推行“中日满提携”宣传，强迫青年参加“青少年团”，为日军募集“国防献金”。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ad56b4fd886f54c4936740d52b5f1143', 'b12ddd1588c2542eabd395ba6cb92e2b', 1941, '伪延庆县自卫团总团长', NULL, '组织地方自卫团，在延庆各要道设卡盘查，截获八路军物资，并配合日军对海坨山根据地进行封锁。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('478e2c76d025563aad54a5f7f17b3f8c', 'df4297e5caa653e1957eb4a3ce24de44', 1939, '伪延庆县财政科科长', NULL, '负责为日军征收田赋和苛捐杂税，在延庆地区强征“治安费”，中饱私囊，导致农民破产。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('56e7ee079b9e5835b702502535d82e83', 'fea07466bb9d53d3a13f04dd08cd9a5d', 1940, '伪延庆县教育科督学', NULL, '在延庆各小学推行日语教育，强迫学生唱日本国歌，检举有抗日思想的教师，导致多名教师被捕。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('06a308ccf96b5edc8e0e8be2c11c2a3f', 'fd0b174468f856638bd0fb256d267c93', 1942, '伪延庆县情报班班长', NULL, '专门收集平北八路军情报，多次带领日军偷袭延庆北部村庄，造成抗日干部牺牲。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4658f3d2fb1158468b6962cbe3f06123', 'd61188ea607454ba87a7547316b9d153', 1941, '伪延庆县监狱典狱长', NULL, '在延庆监狱虐待关押的抗日军民，实施酷刑，并协助日军将“要犯”押送北平宪兵队。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e09307345b465a4eb7123257fdad0ce7', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪蒙疆联合自治政府副主席', NULL, '原为热河地方军阀，1933年投靠日军，在延庆及察哈尔地区配合日军进攻抗日武装，后任伪蒙疆政权要职，协助日军统治平北地区。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ef6fab3714f6560f9c312f5ae1ef51c7', '03751651c36952668c9b65b923b9c221', 1935, '伪蒙疆联合自治政府主席', NULL, '蒙古王公，与日军合作建立伪蒙疆政权，其势力范围包括延庆北部山区，曾组织伪蒙军配合日军“扫荡”平北抗日根据地。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3467225991d552218040e106dcababc3', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪东亚同盟军总司令、伪绥西联军司令', NULL, '原为土匪武装头目，后投靠日军，在延庆、怀来一带活动，多次率伪军进攻八路军平北军分区，残害抗日军民。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5a1f08e5d3a25709b2a35f55783add29', '995d97d5ab36539093351888246ac8fe', 1939, '伪延庆县知事（县长）', NULL, '任伪延庆县知事期间，推行日伪保甲制度，强征民夫修筑据点，配合日军“治安强化运动”，抓捕抗日干部和群众。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7d230c794e1d5ff9a7552b73ece0f339', '25403a79f8335f3e96fc8451f78bbb99', 1940, '伪延庆县保安队队长', NULL, '率伪保安队多次袭击延庆南山抗日游击队，杀害八路军地方工作人员，并参与日军对海坨山根据地的封锁。', '北京延庆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ec6098a2a27353ef94f1654128af76e2', '340adba25424535985417eba5e18abbe', 1938, '伪怀柔县知事', NULL, '投靠日伪政权，任怀柔县知事，协助日军推行保甲制度，强征民夫，搜刮粮食，镇压抗日活动。', '北京怀柔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6023f4936ed45ec986db541778bc0d42', '33f48787d6295324995de4d2f715fb78', 1935, '伪冀东防共自治政府保安队头目（活动于怀柔一带）', NULL, '参与殷汝耕伪冀东政权，在怀柔地区组织伪保安队，配合日军清乡，抓捕抗日军民。', '北京怀柔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cb0a857dcc885336b40982d455ba6e5f', '6edb269a696555c193c5c25b9caf01c3', 1939, '伪怀柔县警察局局长', NULL, '效忠日军，指挥伪警察搜捕抗日地下人员，破坏中共怀柔地区组织，参与“治安强化运动”。', '北京怀柔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('558f3ccb76315a77a52da78596cd4b73', '19fb47a898685fbb9631c8b660b6a8f2', 1940, '伪怀柔县新民会会长', NULL, '主持怀柔新民会，推行奴化教育，组织“反共宣传”，强迫民众参加日伪集会，为日军收集情报。', '北京怀柔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('21c8da8bcb1955fc9e4ba855886a21aa', '9ca8f82df12958b9ac4d7381f7eaeeaa', 1941, '伪怀柔县保安队副队长', NULL, '率伪保安队多次袭击八路军游击队，杀害抗日干部，烧毁村庄，协助日军修建封锁沟。', '北京怀柔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b348e4a32c5650d097bf6ef68bcbe856', '132ca09a10c5518383fc783d3db3266b', 1942, '伪华北治安军独立团团长（驻防怀柔）', NULL, '率治安军在怀柔山区“扫荡”，实行“三光”政策，屠杀无辜百姓，抢夺物资，配合日军围剿平北抗日根据地。', '北京怀柔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b99dad16e61d535d8f6e327291e44013', '340adba25424535985417eba5e18abbe', 1938, '伪怀柔县知事', NULL, '在任期间推行日伪统治政策，协助日军征粮、强征劳工，镇压抗日活动。', '北京怀柔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3b15fde9a2c95540b43dd59ed48ac6ae', 'b48ca46c920c5d86815e7d749a4acc2c', 1940, '伪怀柔县保安队队长', NULL, '率伪军配合日军扫荡抗日根据地，抓捕抗日军民，参与制造多起惨案。', '北京怀柔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1f8b243c42995477a27ebe6d4b2cce57', '4952c9b8362456ca913789f6976c145d', 1941, '伪怀柔县警察局局长', NULL, '组织伪警察协助日军搜捕地下党员，破坏抗日组织，强征捐税。', '北京怀柔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('527f7d4e7ec857c68bb221f66d0dc377', '95822e7b4b4a56bf91a3de47061dd52e', 1942, '伪怀柔县新民会会长', NULL, '推行奴化教育，宣传“中日亲善”，强迫民众参加反共集会，搜集抗日情报。', '北京怀柔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('100df373efd0568aa471c24e7e6fd67e', '5ae0b0684cc4589db47453bfb3b3708c', 1937, '房山县伪县长', NULL, '投靠日军，任房山县伪县长，协助日军推行保甲制度，强征民夫，搜刮粮食，镇压抗日活动。', '北京房山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('be01500d8654576482d3eeedfcc08a4e', '316cc483865057089895b48829218edb', 1938, '房山县伪保安队队长', NULL, '率伪保安队多次配合日军扫荡房山抗日根据地，杀害抗日干部和群众，抢劫财物。', '北京房山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('41cace9eaa855eb09cb47f511351cc88', 'b7851a2bb17955198176ccbac07d2d06', 1940, '房良联合县伪警备队大队长', NULL, '在房山、良乡一带为日军效力，围剿八路军游击队，抓捕抗日家属，破坏地下交通线。', '北京房山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ac7d028f88705816b622d936639efb25', 'a5a7ca203d195b54b576c7a539cf4c58', 1939, '房山县伪警察局局长', NULL, '效忠日军，指挥伪警察搜捕抗日分子，严刑逼供，多次带路袭击抗日村庄。', '北京房山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2cf42bb7541a5c2789eabf480febb5ed', '8320e3e3065f5f31a864a1fd27201ca3', 1941, '房山县伪新民会会长', NULL, '主持房山新民会，推行奴化教育，宣传“中日亲善”，强迫民众参加反共集会。', '北京房山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2452c4dae5b45a9ea49bcc8bb79d4e50', '132ca09a10c5518383fc783d3db3266b', 1942, '房山县伪自卫团总团长', NULL, '组织伪自卫团，协助日军封锁山区，截断抗日物资运输，杀害过路群众。', '北京房山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('82d68cae6dcf5624a62f83d517f94283', 'e60d0335f96157edb58448797cda6ce0', 1938, '良乡县伪县长（房山邻县，但辖区涉及房山部分地区）', NULL, '在良乡及房山交界地区推行日伪统治，强征粮食，组织伪军配合日军“清乡”。', '北京房山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fd4e27c8c51f59b8a60246b550242390', 'fd0b174468f856638bd0fb256d267c93', 1940, '房山县伪财政科科长', NULL, '为日军征收各种苛捐杂税，贪污抗日家属财产，协助日伪经济封锁。', '北京房山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('674133ed8ab9584b86f355dcc921db82', 'f507817e989158b6a3fd828c617b43cd', 1937, '伪华北政务委员会内政总署督办、伪华北政务委员会委员长', NULL, '原北洋政客，投日后任伪华北政务委员会要职，在北平（今北京）推行日伪统治政策，参与奴化宣传和物资统制。', '北京昌平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8f1bc5fe9b7d5070a71e1b59babc5bc3', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北治安军总司令、伪华北政务委员会治安总署督办', NULL, '原直系军阀，投日后在北平组建伪治安军，配合日军“扫荡”抗日根据地，镇压北平及周边地区抗日力量。', '北京昌平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6444eb87ddd65451afec3fbcbffd6769', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府委员长（后并入伪华北政权）', NULL, '早年亲日，1935年成立冀东伪政权，辖区包括昌平一带，后任伪华北政务委员会经济总署督办，协助日军经济掠夺。', '北京昌平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('88b11883753d5f6ea39f0376a2b9b3e1', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府秘书长、伪昌平县知事（代理）', NULL, '殷汝耕亲信，参与冀东伪政权运作，曾代理昌平地区伪行政事务，推行日伪法令。', '北京昌平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('37e92a3ff8f0545bae23459d04d40e7d', '340adba25424535985417eba5e18abbe', 1943, '伪北平市市长（1943-1945）', NULL, '原北洋官僚，投日后任伪北平市长，管辖包括昌平在内的北平郊区，配合日军征粮、抓夫和“治安强化”运动。', '北京昌平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('30f1d49e59605da29ecd59ccde288287', '81630a2fb4475f6f9739f4b7c0996e70', 1937, '伪北平市警察局局长', NULL, '在北平（含昌平）任伪警察头目，协助日军搜捕抗日分子，镇压民众反抗，维护殖民秩序。', '北京昌平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('59fc18a12f12536c92721d2a31e51c59', '37b4d45b85b2500c8c00d62157eee60d', 1938, '伪北平市市长（1938-1943）', NULL, '原国民党官员，投日后任伪北平市长，在昌平等郊区推行保甲制度，强征劳工，为日军提供物资。', '北京昌平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('15943a0faec651cbb54ff2101c5c5a6e', '07961601ff2f53f5863147f327d72168', 1937, '伪北平市警察局局长（早期）', NULL, '原宋哲元部参谋，七七事变后投日，任伪北平警察局长，协助日军控制北平及昌平治安。', '北京昌平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7e279c9aa92b5152ab47446c70e3e95e', 'd941126e8c785a22a9720c46c6bd1778', 1937, '伪北平维持会会长（1937年短暂）', NULL, '原北洋将领，北平沦陷初期组织伪维持会，为日军稳定昌平等郊区秩序服务。', '北京昌平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4a76d945febf55f780d42787f40aee3e', '4d2d3d155bb454339a738c1c49764a53', 1937, '伪中华民国临时政府行政委员会委员长（北平）', NULL, '原北洋财阀，在北平组建伪临时政府，管辖昌平等地，推行日伪政治、经济政策。', '北京昌平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b36971663d475c9bbf9987920d63c043', '03a22ef55d3353c9839e247460f68d95', 1940, '伪华北政务委员会司法委员会委员长', NULL, '原北洋司法总长，投日后在北平参与伪司法体系，对昌平地区抗日民众进行“审判”镇压。', '北京昌平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bd68b974ded1502b9f2803fce067fb63', '901d931e3da25695bb656596253feed9', 1937, '伪华北政务委员会教育总署督办', NULL, '原北大教授，投日后主管北平及昌平教育，推行奴化教育，删改历史教材。', '北京昌平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5b5fc5244fc5544e8f4eca25e460da0d', '911fda0920525bc1b3c52a4451339c82', 1940, '伪华北政务委员会常务委员、伪北平市市长（1940）', NULL, '原北洋司法总长，投日后在北平任职，参与“治安强化运动”，对昌平抗日根据地实施封锁。', '北京昌平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0cc7d97e0a785029bb6d4acc04eceb42', '75d8bf07a9d358088ac18c65c44c0f26', 1938, '伪中国联合准备银行总裁（北平）', NULL, '在北平设立伪银行，发行联银券，掠夺昌平等地民间财富，造成经济混乱。', '北京昌平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('75c77afc19c154b7be580c77dc5bbefc', '623d392eb5a05d4cac7b4f9ccb0a1da6', 1937, '伪华北政务委员会咨询委员（未实际任职但参与活动）', NULL, '原亲日政客，虽未任实职，但为日伪在北平及昌平的活动提供政治支持。', '北京昌平');
