INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('008f788e18bc5347a0fac4d1ed97fb04', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '冀东防共自治政府政务长官', NULL, '1935年在通州成立冀东防共自治政府，公开投敌，管辖冀东22县，为日军提供粮饷和劳役，镇压抗日活动。', '北京通州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('71d68a3366185dc08d93e1a35da67d4e', 'be830f2d60665f0189881935079af216', 1935, '冀东防共自治政府秘书长、通县县长', NULL, '协助殷汝耕建立伪政权，负责通州地区行政事务，推行奴化教育，强征民夫修建日军工事。', '北京通州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0909dcf2c9ae5e819affe8cf58da0c95', '99afd279f9bb50b2b65b52b289c8e71d', 1935, '冀东保安队第一总队队长（后反正）', NULL, '初期为殷汝耕效力，但1937年7月29日率部发动通州起义，杀死日军和汉奸数百人，后反正抗日，故其前期行为属被迫附逆。', '北京通州');
