INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d27ecb32c93e5595910f3eca52123f02', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北治安军总司令、伪华北政务委员会治安总署督办', NULL, '原直系军阀，投日后组建伪华北治安军，在门头沟山区参与“扫荡”八路军游击队，协助日军封锁抗日根据地。', '北京门头沟');
