INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9c1e1ae66a895a04a33058bc15beff08', 'c1678fb1f25657d499495f03556efa76', 1931, '伪满吉林警备军司令、伪满陆军上将', NULL, '原东北军将领，投日后任伪吉林警备军司令，多次率伪军“围剿”抗日游击队，在丰满一带参与清乡和屠杀抗日军民。', '吉林丰满');
