INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('12fe9523b841597e92c045a90d9941cf', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满吉林省高等法院院长（后任伪满立法院院长）', NULL, '参与伪满司法体系建立，审判抗日志士，以“反满抗日”罪名判处多人死刑或重刑，在吉林及丰满地区制造冤狱。', '吉林丰满');
