INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c13ebe6005d65409a843769ed6235bb8', '013c82db459e55769cfebd7525d6ccb7', 1931, '伪满国务总理大臣', NULL, '原清朝遗老，伪满首任总理，在四平、吉林等地推行奴化教育，协助日本殖民统治。', '吉林四平');
