INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ed14b0177fda58b08bf592f1b0d9602d', '1ea6405224d35b439d5a62eb23dca975', 1931, '伪满四平地区保安队队长', NULL, '原土匪头目，投日后在四平、梨树一带为日军充当“讨伐队”向导，屠杀抗日义勇军。', '吉林四平');
