INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9ecd9064531654c7959317c3b670a4a0', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八后投敌，在吉林、昌邑一带协助日军镇压抗日武装，后任伪满高官。', '吉林昌邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ca92874860375848a801675bbf239cf5', 'c1678fb1f25657d499495f03556efa76', 1931, '伪满吉林警备司令、伪满陆军上将', NULL, '原吉林军军官，叛变投日，在吉林地区多次围剿抗日游击队，参与“讨伐”杨靖宇等抗联部队。', '吉林昌邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dd6af26ff5565232a1e13cca0309d21b', 'c8a80042591a58269f0254a2c8cc2851', 1932, '伪满吉林省长、伪满治安部大臣', NULL, '原东北军旅长，投日后任伪吉林省长，在昌邑及周边推行保甲制度，协助日军清乡。', '吉林昌邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b9bd545092e25e27a54c8f366dce294a', '06c1ecca7c3f5240b6bf4a99f59beae0', 1932, '伪满吉林市市长、伪满民生部大臣', NULL, '满族亲日分子，在吉林市及昌邑区实施奴化教育，强征劳工，镇压反满抗日活动。', '吉林昌邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d6a7fc23b06955d2b202a3b7f6726f10', '1dfa2e56c73a5f21b364cddcacef0519', 1932, '伪满吉林警察厅厅长', NULL, '在吉林昌邑地区组织特务警察，抓捕抗日地下工作者，破坏抗联联络站。', '吉林昌邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0be162673bce5c30bffe61700b737feb', 'd4e3306af4f458f794f2ae592a42473d', 1933, '伪满吉林宪兵队队长', NULL, '在昌邑一带残害抗日军民，参与制造多起屠杀事件，协助日军“讨伐”抗联。', '吉林昌邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3dc670c57d8e5460885c66d17283b3f9', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满立法院院长（曾活动于吉林）', NULL, '原奉系律师，投日后在吉林地区为伪满政权立法，协助日伪统治，参与“治安肃正”。', '吉林昌邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4624d1b3cf2a509c8cc46b1399a05264', '8f60ed6bf0f85a62a7840ff91b875b4f', 1932, '伪满黑龙江省长（曾兼任吉林地区清乡督办）', NULL, '在吉林昌邑周边推行“集团部落”，烧毁民房，制造无人区，切断抗联补给。', '吉林昌邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ab80131859c453b38349fd49d375b911', '3083c32dac1e5182a8f6e46300335aa7', 1932, '伪满吉林省教育厅长', NULL, '在昌邑地区推行日语教育，篡改历史教材，强迫学生效忠日本天皇。', '吉林昌邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('28958c53ea095bd1b11d55adcca6df36', '0da09f00ee6a55878e86adbb70127338', 1932, '伪满吉林省财政厅长', NULL, '为日军筹措军费，在昌邑强征捐税，掠夺粮食资源，支持侵华战争。', '吉林昌邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a3b901ac48e454398b7e7f006b5e9bd0', '3c0cec769a465f2da5d9587d32cf51f4', 1932, '伪桦甸县警务科科长', NULL, '在桦甸县任职期间，积极协助日军镇压抗日武装，多次率伪警察讨伐抗日游击队，抓捕并杀害抗日军民数十人。', '吉林桦甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0f25a53eea8f57838ecda6819967d1c1', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满吉林军区司令（曾驻桦甸一带）', NULL, '原东北军将领，九一八后投敌，任伪满军事要职，其部队在桦甸、吉林地区参与“讨伐”东北抗日联军，烧杀抢掠，破坏抗日根据地。', '吉林桦甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('00ce1f660c825cf0bd724272a321e915', 'c1678fb1f25657d499495f03556efa76', 1932, '伪满吉林剿匪总司令', NULL, '率伪军多次进攻桦甸、磐石一带的抗日游击队和抗联部队，制造多起惨案，是日寇在吉林地区的主要帮凶。', '吉林桦甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2cb9403fe9d25ad2a913a03b9ace2329', 'c8a80042591a58269f0254a2c8cc2851', 1932, '伪满吉林警备司令', NULL, '在吉林地区推行“治安肃正”，指挥伪军配合日军对桦甸山区进行反复“扫荡”，杀害抗联战士及无辜百姓。', '吉林桦甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c350791526055b79aa6f1d715d88e44f', '9cc8abde983e5319b2c80645c3730535', 1933, '伪桦甸县县长', NULL, '在任期间强征劳工修建警备道路和碉堡，为日军提供粮食和物资，并组织汉奸情报网，破坏抗日地下组织。', '吉林桦甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6c8409cdd0f656d09d91ced616b773ec', '50b41f744fc55c7d913a913c23b0de99', 1935, '伪桦甸县协和会会长', NULL, '积极宣传“日满亲善”，协助日伪当局推行“保甲连坐”制度，检举抗日分子，导致多名抗联联络员被捕牺牲。', '吉林桦甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0fee70a29c4a51329d534c25cbf1edd2', 'f7a7ba95fca5540bac55da4b4fc103e2', 1936, '伪桦甸县警察署署长', NULL, '亲自带队搜捕抗联密营，在桦甸红石砬子一带袭击抗联伤病员，并参与“归屯并户”政策，制造无人区。', '吉林桦甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f0dec91bdb5950519614d9b170c8b4d1', 'c926652ec0d1522e89e96328f99a2fe8', 1937, '伪桦甸县保安队队长', NULL, '率保安队配合日军在桦甸夹皮沟、老金厂等地围剿抗联第一路军，多次提供日军情报，并杀害抗联侦察员。', '吉林桦甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fd4a3d080f5b5ddc931d68b255b8e447', 'c552feab438259f9bed94b87f2042708', 1940, '伪桦甸县司法矫正局局长', NULL, '将抓捕的抗联嫌疑人和无辜百姓投入矫正院，实施酷刑和劳役，致多人死亡，是日伪法西斯统治的忠实执行者。', '吉林桦甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2b9bce61c4fa5e5c8cf73a675b60a273', '132ca09a10c5518383fc783d3db3266b', 1938, '伪吉林地区“讨伐”队指挥官（活动于桦甸）', NULL, '率伪军多次深入桦甸山区“讨伐”抗联，烧毁村屯，抢夺粮食，并诱降抗联叛徒，破坏抗联组织。', '吉林桦甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('de200613c15952348ef491ea008aeb4d', '2300e528128d54c19855a4669664572a', 1931, '伪满洲国财政部总长、吉林省省长', NULL, '九一八事变后叛国投敌，协助日军占领吉林，任伪吉林省长官，推行殖民统治，镇压抗日力量。', '吉林永吉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8670864820965c53a82ed75b90d75d24', '581b3709952c5c81bc3860d3c62dff90', 1932, '伪吉林省财政厅长、伪吉林省长', NULL, '投靠日本，任伪吉林省财政厅长及省长，协助日军搜刮资源，推行奴化教育。', '吉林永吉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('272308409df35dd6944eca8e780d053c', '06c1ecca7c3f5240b6bf4a99f59beae0', 1933, '伪吉林省警务厅长、伪吉林省长', NULL, '长期担任伪吉林省警务厅长，后升任伪省长，镇压抗日义勇军和地下党，抓捕爱国人士。', '吉林永吉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8d8ee6be9f5050bc987ac324842a4949', '3083c32dac1e5182a8f6e46300335aa7', 1935, '伪吉林省民政厅长、伪吉林省长', NULL, '投敌后任伪省民政厅长，推行保甲制度，协助日军清乡，迫害抗日家属。', '吉林永吉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ff51e711dbe151859cb94d19393f1015', 'e6b8425fe2a75f1390d3cc8927ce0ae7', 1932, '伪永吉县县长', NULL, '任伪永吉县长期间，强征劳工，为日军修建军事设施，镇压当地抗日活动。', '吉林永吉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a26d52e333a255589fd6375ca0f78ad1', '02a3787f18a95e358889252db1ff78d9', 1933, '伪永吉县警务科长', NULL, '协助日军搜捕抗日分子，破坏地下组织，参与制造多起屠杀事件。', '吉林永吉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bbc38bc0d9ee529f9fa1be178b98bd54', '5e4ae6e524305885be6f33f0be6cd934', 1932, '伪吉林省教育厅长', NULL, '推行奴化教育，强制学校教授日语，篡改历史，灌输“日满亲善”思想。', '吉林永吉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7d8dac4a7a2059bbbdda75a472d7622b', '0da09f00ee6a55878e86adbb70127338', 1932, '伪吉林省实业厅长', NULL, '协助日本掠夺吉林木材、矿产等资源，为日军提供经济支持。', '吉林永吉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b1ddd8ce95fa5d29864394c6361d6ea5', '9b5824136943524caac2b49f4d988458', 1937, '伪吉林省协和会会长', NULL, '组织协和会，宣传“王道乐土”，煽动民众支持伪满政权，监视抗日言行。', '吉林永吉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f4b14591eb815882b0419a27ff15c46c', 'b8852f66fd825aae828fc4475d35392f', 1938, '伪永吉县协和会副会长', NULL, '协助日军进行思想控制，举报抗日群众，参与“治安肃正”行动。', '吉林永吉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('47db762f16a05a25bba066d8dc2231ce', '79bb05de63395319ab27fff095ca2ac8', 1932, '伪磐石县警务局指导官', NULL, '协助日军镇压磐石抗日游击队，多次参与“讨伐”杨靖宇领导的南满抗日武装，抓捕抗日群众并刑讯逼供。', '吉林磐石');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('60770ea858e85fbfbbe95a45011e78a8', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满洲国热河省省长（原籍磐石，曾活动于磐石）', NULL, '九一八事变后公开投敌，在磐石一带招募伪军，配合日军围剿抗日义勇军，并参与建立伪满地方政权。', '吉林磐石');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('72465684bbc256e19ce9a1829a3ccdb7', '802dd1e9fe095ba4a8cbdc66a100361e', 1932, '伪满洲国军政部大臣（曾驻磐石地区）', NULL, '作为伪满高级将领，指挥伪军多次对磐石玻璃河套、红石砬子等抗日根据地发动“大讨伐”，杀害抗日军民。', '吉林磐石');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('36e3b3528fb75af68205a6ae78f95029', '3c0cec769a465f2da5d9587d32cf51f4', 1933, '伪磐石县保安队队长', NULL, '率保安队为日军带路，破坏磐石地下党组织，参与制造“磐石惨案”，逮捕并杀害多名抗日联军联络员。', '吉林磐石');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2df4f9f44ab057f0aeb0f241296a9ff7', 'f13fea3281b35a0ea71eb3863d7d53f7', 1934, '伪磐石县警察署署长', NULL, '积极推行“归屯并户”，切断抗日武装与群众联系，多次率警察袭击磐石抗日游击队营地，并实施“连坐”政策。', '吉林磐石');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('99e9a06390755ce9b5e3912f937dbc14', 'b507e0af05415e5a9319eea3243e9a6b', 1935, '伪磐石县协和会会长', NULL, '组织汉奸宣传队，鼓吹“日满亲善”，搜集抗日情报提供给日军，并强迫百姓捐献物资支援伪军“讨伐”。', '吉林磐石');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('17e8765c457a59ce9db4a90195cedea4', '30e372454b6252f4b301d91d5616ecab', 1932, '伪磐石县自卫团团长', NULL, '率自卫团配合日军在磐石山区搜捕抗联战士，曾参与袭击杨靖宇部队后方医院，杀害伤员和医护人员。', '吉林磐石');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3b75a60b366f5b14a3f7baccdbf5755f', '34141ca126ff51c0a4a5eb7a8c5b4040', 1933, '伪磐石县司法科科长', NULL, '审判并迫害抗日志士，以“反满抗日”罪名判处多人死刑或长期监禁，并协助日军建立“思想矫正院”。', '吉林磐石');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('733fd075e55b5256a6a481cda073dcf4', '132ca09a10c5518383fc783d3db3266b', 1934, '伪磐石县税捐局局长', NULL, '为日军强征苛捐杂税，搜刮民财充作军费，并参与“粮谷出荷”政策，导致磐石地区百姓饿殍遍野。', '吉林磐石');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c911a3750f8b5cb1ad2eb4535d4fde5f', 'e60d0335f96157edb58448797cda6ce0', 1936, '伪磐石县教育会会长', NULL, '推行奴化教育，强制学校教授日语和“满洲国”历史，检举爱国教师，并组织学生为日军“献金”活动。', '吉林磐石');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('febefcab3e0d5fc99a656507f9905d49', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八后投敌，在吉林地区参与镇压抗日武装，后任伪满高官，协助日军统治东北。', '吉林舒兰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e47c9a446db65ec5b22335fef52a6882', '2300e528128d54c19855a4669664572a', 1931, '伪满财政部总长、宫内府大臣', NULL, '原吉林副司令长官公署参谋长，1931年叛变，引日军占领吉林，建立伪吉林省政权，是吉林地区首要汉奸。', '吉林舒兰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9785a693bb925ca6ac77811510d73e15', '06c1ecca7c3f5240b6bf4a99f59beae0', 1932, '伪满吉林省省长', NULL, '原吉林省政府官员，投日后历任伪吉林省长，推行日伪殖民政策，镇压抗日力量。', '吉林舒兰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('84b72fc16d8357a0b1cfc72920fe2e9a', '0da09f00ee6a55878e86adbb70127338', 1932, '伪满吉林省省长、伪满民生部大臣', NULL, '原吉林省政府官员，投敌后任伪吉林省长，协助日军清乡，强征劳工。', '吉林舒兰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4d5f92cab03d5c2bada34c0b15d4b87a', 'b8852f66fd825aae828fc4475d35392f', 1932, '伪满吉林省警务厅长', NULL, '在吉林地区组织伪警察，配合日军围剿抗联，抓捕抗日志士。', '吉林舒兰');
