INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c414643226d058ca9af51180861294d6', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长（曾任吉林地区司法职务）', NULL, '原东北法律界人士，投日后参与伪满立法，为日本殖民统治提供法律依据。', '吉林舒兰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('155434fd84ed53deb7b4ba5098a39790', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满军政部大臣（曾任吉林驻军）', NULL, '原东北军旅长，九一八后率部投敌，在吉林、舒兰一带协助日军镇压义勇军。', '吉林舒兰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9867d8018dac5df08adb81f4a8c4cd4f', 'c8a80042591a58269f0254a2c8cc2851', 1931, '伪满治安部大臣（曾任吉林地区）', NULL, '原东北军将领，投日后负责伪满治安，参与围剿抗联。', '吉林舒兰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('950379dd244458839a32676fc694274e', 'ff9e89d899b252749c4c67a488d7ebd2', 1932, '伪满吉林警备司令', NULL, '原吉林驻军团长，投敌后任伪警备司令，在舒兰、五常一带多次进攻抗联部队。', '吉林舒兰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ee799c3949545a9ba1b3d7607f612bf2', '05024b123cc45ed8ac41b71c1d26adcb', 1932, '伪满舒兰县县长', NULL, '投日后任伪舒兰县长，推行保甲制度，强征粮食，协助日军建立“集团部落”。', '吉林舒兰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9ebc33b9dc2955edbc6e426a2b2f1496', '50b41f744fc55c7d913a913c23b0de99', 1932, '伪满舒兰县警务科长', NULL, '在舒兰地区组织伪警察队，多次参与搜捕抗联地下组织。', '吉林舒兰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('292cd46ef85a5082aed313d27b405d0c', '1c5a7c0239a3585ba753fb5dd8066643', 1932, '伪满吉林协和会会长', NULL, '在吉林地区宣传“日满亲善”，组织汉奸团体，破坏抗日统一战线。', '吉林舒兰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f558088d422356cba4fb02920085eb95', '55d5c28516215af6bb912b6e514aad47', 1933, '伪满吉林保安队队长', NULL, '率伪保安队在舒兰山区围剿抗联第三军，烧毁民房，屠杀百姓。', '吉林舒兰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d562a5898ed05a87bee27ab06a46eb42', '091187ee16085ccea2e4606033830c16', 1935, '伪满吉林宪兵队翻译官', NULL, '在吉林、舒兰地区协助日军宪兵队审讯、拷打抗日军民，提供情报。', '吉林舒兰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('127740f8441c5908934cf279c45703da', '2300e528128d54c19855a4669664572a', 1931, '伪满洲国财政部总长、吉林省伪省长', NULL, '九一八事变后叛国投敌，主动迎接日军占领吉林，协助建立伪吉林省政权，为日军提供财政和行政支持。', '吉林船营');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d6a38ded2f7b5cd7af2cb26e7350a2f4', '06c1ecca7c3f5240b6bf4a99f59beae0', 1932, '伪吉林省警务厅长、伪吉林市市长', NULL, '在船营地区推行日伪警察制度，镇压抗日活动，参与“治安肃正”行动，抓捕抗日志士。', '吉林船营');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('12db92dbc4fc5b8ca0ace54419ade5c6', '0da09f00ee6a55878e86adbb70127338', 1932, '伪吉林省民政厅长、伪吉林省长（后期）', NULL, '协助日伪推行“保甲制度”和“连坐法”，在船营地区强征劳工，为日军提供物资。', '吉林船营');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6b27c53f08de5643b5d49a9f962e9560', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满洲国立法院院长（曾驻吉林活动）', NULL, '作为汉奸法律顾问，参与制定伪满法令，为日本殖民统治提供法律依据，涉及船营地区土地掠夺。', '吉林船营');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4ef790d4d51c56d69d619717a1cca9f5', '802dd1e9fe095ba4a8cbdc66a100361e', 1933, '伪满第一军管区司令（驻吉林）', NULL, '率伪军配合日军在船营及周边“讨伐”抗日武装，制造多起屠杀事件。', '吉林船营');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c40af658d3e7566f9780ea684d614f56', '3083c32dac1e5182a8f6e46300335aa7', 1932, '伪吉林省教育厅长', NULL, '推行奴化教育，在船营地区学校强制推行日语教学和“日满亲善”宣传。', '吉林船营');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5e1370776e5a52a19de293af238cd9df', '9d9a0add0c285a94840c9d63f7e0641c', 1937, '伪吉林市警察局长', NULL, '指挥警察在船营地区搜捕地下抗日分子，破坏抗日组织，协助日军进行“思想矫正”。', '吉林船营');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d7edd4e87a365073acca4ac2ffd8c808', '5e4ae6e524305885be6f33f0be6cd934', 1932, '伪满外交部大臣（曾参与吉林事务）', NULL, '代表伪满与日本签订不平等条约，出卖东北权益，间接影响船营地区资源控制。', '吉林船营');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7fdb4c854cf25d7d8421c3ac59027317', '581b3709952c5c81bc3860d3c62dff90', 1932, '伪吉林省实业厅长', NULL, '协助日本财阀在船营地区开采矿产、掠夺森林资源，强征当地农民为矿工。', '吉林船营');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('71e3e24a5fa3539bb1eafd5c0dbead87', 'b8852f66fd825aae828fc4475d35392f', 1935, '伪吉林市商会会长', NULL, '为日伪筹集军费，强迫商户“献金”，垄断粮食配给，从中牟利，压迫船营商民。', '吉林船营');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e81f68ce6ab55ab09d30cd866c6ffd19', '3c0cec769a465f2da5d9587d32cf51f4', 1932, '蛟河县伪县长', NULL, '任伪蛟河县县长期间，积极推行日伪殖民政策，强征劳工，镇压抗日活动，协助日军清剿抗日联军。', '吉林蛟河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1b328eccd71b55f79a1e0b2805c86097', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪吉林省警务厅厅长（曾辖蛟河地区）', NULL, '原东北军将领，后投敌叛国，任伪吉林省警务厅厅长，在蛟河等地组织伪警察配合日军围剿抗联，残害抗日志士。', '吉林蛟河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b1c14c08ca4d50eb99bb67170395cdad', 'c1678fb1f25657d499495f03556efa76', 1932, '伪吉林省“讨伐”司令（曾率部在蛟河地区作战）', NULL, '伪满军事将领，多次率伪军进入蛟河、敦化一带“讨伐”抗日武装，制造多起屠杀事件。', '吉林蛟河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9f34a774877d5757b7135f0b82f59009', 'f13fea3281b35a0ea71eb3863d7d53f7', 1933, '蛟河伪保安队队长', NULL, '充当日军走狗，带领保安队抓捕抗日军民，破坏地下组织，强征民夫修筑军事工事。', '吉林蛟河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('74bb0875333b5df18284a175b57bad64', 'd1a2bc6cc59852509921beccf024e0d6', 1934, '蛟河地区伪自卫团团长', NULL, '组织伪自卫团协助日军巡逻，多次袭击抗联小分队，杀害无辜百姓，霸占民财。', '吉林蛟河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0d344003ecd7527394e28f0c4988b197', '30e372454b6252f4b301d91d5616ecab', 1935, '蛟河县伪警察署署长', NULL, '效忠日伪，指挥伪警察搜捕抗日分子，刑讯逼供，破坏抗日联络站，罪行累累。', '吉林蛟河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('10db5b345cfd5259b84283530c76b505', '5083865d0c725f23932b336d9ea3b1a0', 1936, '蛟河日军宪兵队翻译', NULL, '为日军宪兵队充当翻译，参与审讯和迫害抗日志士，告密导致多名地下党员被捕牺牲。', '吉林蛟河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('daebfa0831ac58c6ae946a7dd45b9fe1', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八事变后投敌，任伪满热河省省长，镇压抗日武装，协助日军进攻热河。虽籍贯辽宁盖平，但长期在吉林、辽源一带活动，曾参与围剿辽源地区抗日游击队。', '吉林辽源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5b5a3f52b0e4552aba693ac358b740a7', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满第一军管区司令官、伪满治安部大臣', NULL, '原东北军旅长，投日后任伪满第一军管区司令官，驻防吉林、辽源地区，多次率伪军“讨伐”抗日义勇军和抗联部队，屠杀抗日军民。', '吉林辽源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bf40e163beaa53e8a1172b1d4ff04882', 'c8a80042591a58269f0254a2c8cc2851', 1931, '伪满吉林省省长、伪满民生部大臣', NULL, '原吉林陆军军官，投日后历任伪满吉林省警务厅长、省长，在吉林、辽源地区推行保甲制度，强征劳工，协助日军清剿抗联。', '吉林辽源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fbac2b8a808e511f966a7e0fb095bfdd', '06c1ecca7c3f5240b6bf4a99f59beae0', 1931, '伪满吉林省警务厅长、伪满奉天省省长', NULL, '满族贵族，投日后任伪满吉林省警务厅长，在吉林、辽源地区建立伪警察网络，抓捕抗日地下工作者，参与制造多起惨案。', '吉林辽源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('36e5a1f00b515e8d9dc13cd6b51ac45e', 'e6b8425fe2a75f1390d3cc8927ce0ae7', 1932, '伪满辽源县县长（今辽源市）', NULL, '原辽源县地方士绅，日军占领后出任伪县长，为日军征粮派款，组织伪自卫团，镇压辽源地区抗日民众运动。', '吉林辽源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('50c31b46a550588688431d8271d0d6fa', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长、伪满吉林省高等法院院长', NULL, '原奉系法律顾问，投日后任伪满吉林省高等法院院长，在吉林、辽源地区审判抗日志士，以“反满抗日”罪名判处多人死刑。', '吉林辽源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('32f32f4a6ca9573a81f79c0ca04138e1', '581b3709952c5c81bc3860d3c62dff90', 1931, '伪满吉林省财政厅长、伪满中央银行副总裁', NULL, '原吉林官银号总办，投日后负责伪满在吉林、辽源地区的财政搜刮，发行伪币，掠夺粮食和物资，支持日军战争。', '吉林辽源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('25fa8fb8c97d5b23847b1745dc8d98d9', '0da09f00ee6a55878e86adbb70127338', 1935, '伪满吉林省省长（继任）', NULL, '原吉林省政府官员，投日后任伪满吉林省省长，在辽源地区推行“集团部落”政策，强迫农民并村，制造无人区，切断抗联补给。', '吉林辽源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6ad4bf86781152af8fc702cd8eac4ab2', '3083c32dac1e5182a8f6e46300335aa7', 1932, '伪满吉林省教育厅长', NULL, '原吉林教育界人士，投日后推行奴化教育，在吉林、辽源各学校强制教授日语和“王道乐土”思想，迫害爱国师生。', '吉林辽源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9e1016cec28d550495b1023bc22ed8f8', 'b8852f66fd825aae828fc4475d35392f', 1933, '伪满辽源地区警备司令', NULL, '原地方保安团长，投日后任辽源地区伪警备司令，多次率伪军袭击抗联杨靖宇部，在辽源山区烧毁民房，杀害抗联家属。', '吉林辽源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a5001ae5fd33595a978ff7fa8b6b7b80', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八事变后投敌，曾任伪满热河省省长，后任伪满军政部大臣，积极协助日军镇压抗日武装，在辽源、东丰一带参与“讨伐”抗日义勇军。', '吉林辽源_东丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dca196ce0e905fbb9a5e275d4dc5249d', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满奉天省警备司令官、伪满第一军管区司令', NULL, '原东北军旅长，投日后任伪满奉天省警备司令官，管辖包括辽源、东丰在内的地区，多次指挥伪军配合日军围剿抗日游击队，屠杀抗日军民。', '吉林辽源_东丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('12ba91c5910f542a94d037b1682b200b', 'c8a80042591a58269f0254a2c8cc2851', 1931, '伪满吉林省省长、伪满治安部大臣', NULL, '原东北军将领，投日后历任伪满吉林省省长等职，在吉林、辽源地区推行殖民统治，强征劳工，镇压抗日活动。', '吉林辽源_东丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3112deef3cbf5c24a43150c42136714c', '2300e528128d54c19855a4669664572a', 1931, '伪满财政部总长、伪满宫内府大臣', NULL, '原吉林省政府委员，九一八事变后主动开城迎敌，协助日军占领吉林，后任伪满高官，对吉林、辽源地区抗日力量进行残酷镇压。', '吉林辽源_东丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4f8c4cac6d5b5a8fb616ef5f912ce2c4', '06c1ecca7c3f5240b6bf4a99f59beae0', 1932, '伪满吉林省警务厅厅长', NULL, '在吉林、辽源、东丰地区任伪警务要职，组织伪警察和特务，搜捕抗日地下工作者，破坏抗日组织，制造多起惨案。', '吉林辽源_东丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2392f055fb8e538ebea355b344440665', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长', NULL, '原奉系官员，投日后参与策划伪满建国，虽主要活动于新京，但其势力涉及吉林全省，支持在辽源、东丰等地建立伪政权。', '吉林辽源_东丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3b36edccc5b35ef48e0eeb5a2dcb4f49', '581b3709952c5c81bc3860d3c62dff90', 1932, '伪满吉林省财政厅厅长', NULL, '在吉林地区任职期间，为日军筹措军费，强征粮税，掠夺东丰、辽源一带资源，间接支持日军侵华战争。', '吉林辽源_东丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bc23577320cc538586bf46ee903af4e6', '9d9a0add0c285a94840c9d63f7e0641c', 1932, '伪满东丰县县长', NULL, '在东丰县任伪县长期间，推行日伪“保甲制度”，组织自卫团，配合日军清乡，抓捕抗日群众，强征壮丁。', '吉林辽源_东丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('147990c7036954068eba28806ba9109c', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满辽源县（今辽源市）县长', NULL, '在辽源地区任伪县长，积极执行日伪“治安肃正”政策，协助日军建立“集团部落”，迫害抗日家属。', '吉林辽源_东丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8c3ac5c967cb5c2c9a5de8e44f8bf285', '9aeaa43e6c4553d2b977206f785a8b86', 1933, '伪满西安县（今辽源）警务科长', NULL, '在辽源（原西安县）任伪警务科长，指挥伪警察多次袭击抗日游击队，逮捕并杀害抗日志士，罪行累累。', '吉林辽源_东丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7b16d6ab26c652b6bad2047909b10e8a', '518df2b681c153fb9b804c58dd719cf6', 1935, '伪满东丰县警务科特务股长', NULL, '在东丰县从事特务活动，发展汉奸情报网，破坏抗日地下组织，直接参与刑讯逼供抗日人员。', '吉林辽源_东丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bab75f31ca6456b59f0ebd84e49d8030', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满洲国热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，协助日军统治吉林西部及辽源一带。', '吉林辽源_东辽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e09bdfef121c5423b1d9de348f361796', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满洲国奉天省省长、伪满第一军管区司令', NULL, '原东北军旅长，投日后任伪满高官，其辖区包括今辽源、东辽部分地区，曾配合日军“讨伐”抗联和抗日义勇军。', '吉林辽源_东辽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('13628e0d7b495f1e892d9a976a8f336a', '1c5a7c0239a3585ba753fb5dd8066643', 1932, '伪满东边道保安司令', NULL, '原土匪武装头目，投日后被委任为东边道（含今辽源、东辽一带）保安司令，多次率伪军袭击抗日游击队，残害百姓。', '吉林辽源_东辽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e4f5b7dad61a5b0e9b9d263bf33588b4', 'ba0c34cfbbe05ffe98387776313dd710', 1932, '伪满西安县（今辽源）县长', NULL, '任伪西安县县长期间，强制推行“保甲制度”，强征劳工，为日军提供煤炭资源，镇压当地反满抗日活动。', '吉林辽源_东辽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d9fb1739a2a65c3f8139db161163fdea', '606871181831599da1c9dafcd2664aab', 1933, '伪满东丰县（邻接东辽）警务科长', NULL, '在伪警务系统任职，多次参与围捕抗联地下交通员，协助日军建立“集团部落”，制造无人区。', '吉林辽源_东辽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('35f6e73641f35e309b08bf538eb7eaf2', 'f13fea3281b35a0ea71eb3863d7d53f7', 1931, '伪满西安县（今辽源）警务局长', NULL, '九一八后投敌，任伪警务局长，组织伪警察配合日军清乡，逮捕抗日志士，并参与“讨伐”活动。', '吉林辽源_东辽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e6c38ae8bd5952c0ac22780c4e99d19c', '01580a2207fc546097fc33e00c2593b9', 1937, '伪满东辽县（今东辽）协和会事务长', NULL, '负责协和会宣传，推行奴化教育，煽动民众“日满亲善”，并监视举报抗日分子。', '吉林辽源_东辽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b48069314e2550a1b9ae6ff7ae19a156', 'c552feab438259f9bed94b87f2042708', 1932, '伪满西安县（今辽源）自卫团长', NULL, '组织地方自卫团，协助日军维持治安，多次参与袭击抗联小分队，杀害无辜群众。', '吉林辽源_东辽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('435cdf5060885200823201818ed52ad4', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满洲国国务总理大臣', NULL, '虽为伪满中央高官，但曾长期控制吉林地区军政，其政策直接影响辽源、东辽，支持日军“治安肃正”，镇压当地抗日力量。', '吉林辽源_东辽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('552ee747c5555fc898eeb5b62a6c009a', '2300e528128d54c19855a4669664572a', 1931, '伪满洲国财政部总长、宫内府大臣', NULL, '原吉林副司令长官，九一八后投敌，曾协助日军占领吉林全省，其势力范围覆盖辽源、东辽，参与组织伪军对抗抗联。', '吉林辽源_东辽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6fcabbc30b84566b9f4bb5093dd885ce', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八后投敌，在辽源、西安（今辽源市东辽县一带）参与镇压抗日武装，协助日军建立伪满统治，后任伪满热河省省长，推行殖民政策。', '吉林辽源_西安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('def146cc2cac52cb805f17dcb69fd68c', '3c0cec769a465f2da5d9587d32cf51f4', 1932, '伪满西安县（今辽源市）县长', NULL, '在西安县（今辽源市）任伪县长期间，强征民夫、搜刮粮食，配合日军“讨伐”抗日游击队，多次向关东军提供抗日人员情报，导致多名抗联战士被捕牺牲。', '吉林辽源_西安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f5d0e262fe8350da96519f72b4d5cd1f', 'c3752141ad965f4a95ae8948b058741b', 1933, '伪满辽源县警务科长', NULL, '在辽源县（今双辽市一带）组织伪警察队，参与围剿杨靖宇领导的抗联第一路军，曾率队袭击抗联密营，烧毁粮食和物资，并抓捕抗日群众送交日军宪兵队。', '吉林辽源_西安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('36d19126ce785645a3c6d0ac472bb5f4', 'f13fea3281b35a0ea71eb3863d7d53f7', 1934, '伪满西安县保安队队长', NULL, '在西安县（今辽源市）组建汉奸保安队，配合日军“集家并屯”，制造无人区，多次参与对磐石、桦甸一带抗联游击队的“扫荡”，杀害抗联伤员和群众。', '吉林辽源_西安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6f5950d969e15cb3b065be75ccf41edf', '01580a2207fc546097fc33e00c2593b9', 1935, '伪满辽源县协和会会长', NULL, '在辽源县（今双辽市）推行奴化教育，组织“协和会”宣传“日满亲善”，强迫民众捐献铜铁支援日军，并告密检举反满抗日分子，导致多名爱国人士被捕。', '吉林辽源_西安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e2919d2f6d6b5b34b412bc80ed1c27ff', 'c552feab438259f9bed94b87f2042708', 1936, '伪满西安县宪兵队翻译', NULL, '在西安县（今辽源市）宪兵队任翻译，参与审讯和刑讯抗日志士，多次歪曲供词陷害无辜百姓，协助日军制造多起惨案，如“西安县大逮捕”事件。', '吉林辽源_西安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1bc978f10e7458e4a6115098897a5899', '8016740ed41c5e2091c997bae7a87402', 1937, '伪满辽源县自卫团团长', NULL, '在辽源县（今双辽市）组织自卫团，为日军提供劳力和情报，参与破坏抗联地下交通线，曾率团袭击抗联小分队，抢掠群众财物，并强征青年充当伪军。', '吉林辽源_西安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b043ca89ff17554eaf13bece15f7e5ff', '524ea1464d725f59b1574b96b98c21d6', 1938, '伪满西安县税务局长', NULL, '在西安县（今辽源市）任伪税务局长期间，巧立名目征收“出荷粮”和“国防献金”，盘剥农民，导致当地粮荒，并将搜刮的物资无偿供给日军。', '吉林辽源_西安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('84ca4d11d9c65ca7b69700586126aa41', '132ca09a10c5518383fc783d3db3266b', 1939, '伪满辽源县警察署署长', NULL, '在辽源县（今双辽市）警察署任职期间，多次率警队抓捕抗联交通员，破坏地下组织，并参与“归屯并户”，烧毁民房，造成大量平民流离失所。', '吉林辽源_西安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('92348935453959b189d920889b0b706f', 'dfdbd57fc3f1531e8cc960507c5d03cf', 1940, '伪满西安县“讨伐队”队长', NULL, '在西安县（今辽源市）率“讨伐队”多次进山搜剿抗联残部，曾于1941年在东辽河沿岸伏击抗联小分队，杀害抗联战士5人，并割下首级向日军邀功。', '吉林辽源_西安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('843ee3edecdc5654a1307694e02c1b70', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八后投敌，任伪满要职，镇压抗日力量，协助日军统治吉林地区。', '吉林辽源_龙山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5fba4c30743c5f55a1fe9dac92bb3d4c', '2300e528128d54c19855a4669664572a', 1931, '伪满吉林省省长、伪满宫内府大臣', NULL, '清朝宗室，九一八时在吉林投降日军，建立伪吉林省政权，积极协助日军殖民统治。', '吉林辽源_龙山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('09e939648b905cea81f50f19f14632e7', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满奉天省省长、伪满治安部大臣', NULL, '原东北军旅长，投日后在辽源一带参与清剿抗日武装，后任伪满高官。', '吉林辽源_龙山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('30e6ce18c61359f698478055f8b2b73c', '1c5a7c0239a3585ba753fb5dd8066643', 1932, '伪满吉林省警务厅长', NULL, '在吉林、辽源地区组织伪警察，协助日军搜捕抗日志士，镇压民众反抗。', '吉林辽源_龙山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f443f75123c3596e8070736f4f757c3b', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长、伪满司法部大臣', NULL, '参与策划伪满建国，在吉林地区推行殖民法律，迫害抗日人士。', '吉林辽源_龙山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0dfa8e2c11ee51a480cfd9199b1e2a2b', '581b3709952c5c81bc3860d3c62dff90', 1932, '伪满吉林省财政厅长', NULL, '为日军在吉林、辽源地区征收苛捐杂税，掠夺资源，支持侵略战争。', '吉林辽源_龙山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f792504123e055fabd8ffeead3f11fde', '06c1ecca7c3f5240b6bf4a99f59beae0', 1932, '伪满吉林省民政厅长', NULL, '协助日军推行保甲制度，在龙山地区组织汉奸特务，破坏抗日地下组织。', '吉林辽源_龙山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7bbac0b9e3905602b1df432d28b7a710', '0da09f00ee6a55878e86adbb70127338', 1932, '伪满吉林省教育厅长', NULL, '推行奴化教育，在吉林、辽源学校中强制宣传“日满亲善”，抹杀民族意识。', '吉林辽源_龙山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('90b92ad48dc155aab63f54b9abb84324', '181a098fc1fb5ed5a72da41548f64fed', 1932, '伪满吉林地区警备司令', NULL, '原东北军将领，投日后在辽源、龙山一带率伪军围剿抗日游击队，制造多起惨案。', '吉林辽源_龙山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2bf4e8dd861a5fb0b611974b0c979b87', 'c8a80042591a58269f0254a2c8cc2851', 1932, '伪满吉林省保安司令', NULL, '在吉林、辽源地区指挥伪军“讨伐”抗日武装，屠杀无辜百姓。', '吉林辽源_龙山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3812b22adb495d349edcd40f4cb61f35', 'f13fea3281b35a0ea71eb3863d7d53f7', 1933, '伪满辽源县县长', NULL, '在辽源地区积极推行日伪政策，强征劳工，为日军提供粮食和物资。', '吉林辽源_龙山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('377694e857535a918d343f8ecb7b63bf', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满龙山地区维持会会长', NULL, '在龙山地区组织汉奸武装，协助日军维持治安，镇压抗日群众。', '吉林辽源_龙山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b2148922d640567ca27493562fb48c94', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满国务总理大臣', NULL, '原东北军将领，全面投日后总揽伪满政务，对吉林、辽源地区抗日活动进行残酷镇压。', '吉林辽源_龙山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('658fba6b64615709b8d83f46a45ca4ed', 'ba311422856554c7ad7f3f75d09c3d78', 1932, '伪满参议府议长', NULL, '参与伪满政权决策，支持日军在吉林、辽源地区的殖民统治。', '吉林辽源_龙山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f332d10d606c5a11a188b62355f5a897', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1932, '伪满监察院院长', NULL, '在吉林地区协助日军建立情报网，迫害抗日爱国人士。', '吉林辽源_龙山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('11027dbbb7b9525e9f570a0cd84d4194', '2300e528128d54c19855a4669664572a', 1931, '伪满洲国财政部总长、吉林省省长', NULL, '九一八事变后投靠日本，协助日军占领吉林，积极推行伪满洲国殖民统治，出卖吉林地区主权和资源。', '吉林长春');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e58c06741fe95ab7bb03a5cb5f3e8b35', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满洲国国务总理大臣（曾任东省特别区长官）', NULL, '原东北军将领，后投敌，长期担任伪满最高行政职务，在长春（新京）主持伪满政府，协助日本奴役东北人民。', '吉林长春');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eda4ced1c12c54e1a4790318c791afc1', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满洲国参议府议长（曾任奉天省省长）', NULL, '原东北军要员，投日后在伪满中央任职，参与策划并支持对吉林、长春地区的殖民统治政策。', '吉林长春');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4237d4d6a12e5017a8dcc10dcf015678', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1932, '伪满洲国监察院院长', NULL, '曾任伪满要职，在长春（新京）参与伪满政权建设，协助日本控制东北金融与行政。', '吉林长春');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9c614cd14fcc5c5f9d09676849125e11', 'a2f31a9be59d5a89b0426ae789e7bef9', 1932, '伪满洲国尚书府大臣', NULL, '原奉系官僚，投日后在伪满中枢任职，参与起草和推行奴化政策，活跃于长春政治圈。', '吉林长春');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e38a5d68583b53ec8f104b36ef64fa94', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满洲国立法院院长', NULL, '曾任伪满立法院院长，在长春（新京）参与伪满立法活动，为日本殖民统治提供法律依据。', '吉林长春');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('30a5f10625e35235ad942716bc963b94', '581b3709952c5c81bc3860d3c62dff90', NULL, '伪吉林省省长（后期）', NULL, '继熙洽之后出任伪吉林省长，在吉林市及长春地区推行日伪各项政策，镇压抗日力量。', '吉林长春');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b4031cb7449d5b0882bb755a23ee1a20', '06c1ecca7c3f5240b6bf4a99f59beae0', 1932, '伪吉林省警务厅长', NULL, '在吉林地区组织伪警察，协助日军搜捕抗日志士，残酷镇压吉林、长春一带的抗日活动。', '吉林长春');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bf1efbf99e99599f943358c977fa35de', '0da09f00ee6a55878e86adbb70127338', 1932, '伪吉林省财政厅长', NULL, '负责为伪满政权在吉林地区搜刮民财，征收苛捐杂税，支持日军经济掠夺。', '吉林长春');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8e6569fdf58c581bb2d3270947c7f19f', '9d9a0add0c285a94840c9d63f7e0641c', 1932, '伪长春特别市市长（新京特别市长）', NULL, '在长春（新京）担任伪市长，协助日本进行城市规划和殖民管理，强制推行保甲制度。', '吉林长春');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6da86bbbd48f5ec48cdbeba41318c717', '35e268a2eb6a57f5b5a3be250f503a59', 1932, '伪长春特别市警察局长', NULL, '在长春地区指挥伪警察，参与多次大搜捕，迫害抗日地下工作者和普通民众。', '吉林长春');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5c405470d3c55e1a9cb3da3677be3ce3', '8f60ed6bf0f85a62a7840ff91b875b4f', 1932, '伪满洲国经济部大臣（曾任吉林省实业厅长）', NULL, '在吉林和长春地区推动日本经济统制，协助掠夺粮食、木材等资源，并参与奴工管理。', '吉林长春');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('225afbeb8fc955789e0fb1beae01ac7e', '2b437180a5505d89afed6a8146c9383e', 1932, '伪满洲国交通部大臣', NULL, '负责伪满交通建设，在长春（新京）及吉林地区修建军用铁路和公路，服务于日军侵略。', '吉林长春');
