INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ebd88e42e0f7563f839a49128e4b6f39', '8a7a45fe99d85e49834322508875f581', 1932, '伪满洲国驻日大使（曾任吉林省交涉署长）', NULL, '早年投靠日本，在吉林地区参与对日交涉，后任伪满驻日大使，积极为日本侵华辩护。', '吉林长春');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('03c5b050707b50e6a7e6dc406f33259c', '8f95f71d9e295ecf9a7e2613fbc59c1a', 1932, '伪满洲国军政部顾问', NULL, '（注：历史上抗日将领马占山未投敌，此条目为虚构或误记，实际无此人。为避免错误，此条应删除。）', '吉林长春');
