INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f5896f8dbbe851d58f9ab9c5e9b6b893', '581b3709952c5c81bc3860d3c62dff90', 1932, '伪满洲国吉林省财政厅长', NULL, '原吉林财政官员，投日后主管伪省财政，为日军搜刮民财，供应军需。', '吉林高');
