INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('82757029abba5176b5824db5e4c1cab2', '1dfa2e56c73a5f21b364cddcacef0519', 1932, '伪满洲国吉林协和会会长', NULL, '投日后任伪吉林协和会头目，宣传“王道乐土”，组织奴化活动。', '吉林高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fbd76d7643e85c5da9e6e4f02f94c2d5', '8f60ed6bf0f85a62a7840ff91b875b4f', 1932, '伪满洲国经济部大臣', NULL, '原吉林实业家，投日后任伪满经济部大臣，控制东北经济命脉，为日本掠夺资源。', '吉林高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ca181c4560535e96a5ee66e3ce786ae6', '2b437180a5505d89afed6a8146c9383e', 1932, '伪满洲国交通部大臣', NULL, '原吉长铁路局长，投日后任伪满交通部大臣，协助日军管理铁路，运输军需。', '吉林高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b49656b881e45912b329d337d8df76ca', '318089c2a3375e67b7c33f0820381332', 1932, '伪满洲国文教部大臣', NULL, '原吉林教育界人士，投日后推行奴化教育，删改历史教材，宣扬“日满一体”。', '吉林高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6fc49a5226c95c578258a61b4b6ca769', 'e6b8425fe2a75f1390d3cc8927ce0ae7', 1932, '伪满洲国吉林省实业厅长', NULL, '投日后主管伪省实业，协助日本开采吉林矿产，强征农民土地。', '吉林高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('009f520287735857a140daad93d26035', 'a2bccda0ab0f53c1808a09f401ea85ca', 1932, '伪满洲国吉林省教育厅长', NULL, '投日后推行奴化教育，强制学校教授日语，灌输“忠君爱国”思想。', '吉林高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1d97a7de013e5601ad67b0a04f484ed4', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，协助日军统治吉林地区。', '吉林龙潭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1028fcaa32cc52159bfdb4f85311360a', '2300e528128d54c19855a4669664572a', 1931, '伪满财政部总长、伪满宫内府大臣', NULL, '原吉林副都统，九一八事变后主动开城迎降日军，策划吉林独立，建立伪吉林省政权，是吉林地区首要汉奸。', '吉林龙潭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5188e4475a905a42a61a62321ba48f8b', '9ecee7f0ddf659e583819e721e164c94', 1932, '伪满新京特别市市长、伪满交通部大臣', NULL, '清肃亲王善耆之子，投靠日本后历任伪满要职，在吉林龙潭地区推行殖民政策，协助日军镇压抗联。', '吉林龙潭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9cdbbf4483545b82acbe5f2b0f966765', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满治安部大臣、伪满第一军管区司令', NULL, '原东北军旅长，投敌后任伪满第一军管区司令，驻防吉林，多次率伪军围剿东北抗日联军。', '吉林龙潭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9878b1ac282b5179bb266514935c8cf2', 'c8a80042591a58269f0254a2c8cc2851', 1932, '伪满吉林省省长、伪满民生部大臣', NULL, '原吉林省政府参议，投日后任伪吉林省长，在龙潭地区推行保甲制度，强征劳工，协助日军经济掠夺。', '吉林龙潭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bdb5a79ad69c5d0192ccc6ebe314c703', '9d9a0add0c285a94840c9d63f7e0641c', 1932, '伪满吉林市警察局局长', NULL, '原吉林警察系统官员，投日后任伪吉林市警察局长，在龙潭地区大肆搜捕抗日分子，破坏地下组织。', '吉林龙潭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('aca0f0b94b8d50de8865f16adc369ea9', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满立法院院长、伪满司法部大臣', NULL, '原奉系法律顾问，投日后参与伪满立法，在吉林地区推行奴化教育，协助日本殖民统治。', '吉林龙潭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6e64bd3f18e4505d8d148ea8704deeea', 'af224963fb455c99a96bee0aadf29f89', 1933, '伪满吉林省警务厅厅长', NULL, '原吉林警察厅官员，投日后任伪省警务厅长，在龙潭区设立多个警察分所，残酷镇压抗日群众。', '吉林龙潭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c064a361a0965955a248038973b9cb5d', '0da09f00ee6a55878e86adbb70127338', 1932, '伪满吉林省财政厅厅长', NULL, '原吉林财政官员，投日后负责为日军筹措军费，在龙潭地区强征捐税，掠夺资源。', '吉林龙潭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5c4172e2a97355d5973c8eb2857ce9c7', '1dfa2e56c73a5f21b364cddcacef0519', 1934, '伪满吉林市协和会会长', NULL, '原吉林士绅，投日后任伪协和会会长，在龙潭地区组织汉奸团体，宣传“日满亲善”，瓦解抗日意志。', '吉林龙潭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a10b71cddb475f92a0d5e569a340a818', '340adba25424535985417eba5e18abbe', 1937, '伪天津特别市市长', NULL, '曾任伪天津市市长，推行日伪统治政策，协助日军控制天津地区，包括东丽（时属天津县）的治安与经济掠夺。', '天津东丽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f6e197b5d2f057df8a0564024d3dd6ee', '9a05a840f4165f4db3e6b806c0058634', 1943, '伪天津特别市市长', NULL, '继任伪市长，继续为日本侵略服务，强化对天津及周边地区（含东丽）的殖民管理，征粮派款，镇压抗日活动。', '天津东丽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3917ab90ddef5d148827e6443c632fa8', '7eaa90ba217050158dd164b88dd7ca7f', 1938, '伪天津县知事/县长', NULL, '作为伪天津县行政长官，管辖包括东丽在内的区域，配合日军清乡，强征民夫，实施保甲制度。', '天津东丽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0977111893d157de8e71ae3cd1c8463c', '34279a10aeeb55cb97ee1ff96fae70fd', 1940, '伪天津县知事', NULL, '在任期间协助日军推行“治安强化运动”，在东丽地区（如军粮城、赤土一带）设立据点，搜捕抗日分子。', '天津东丽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('61dec0cd3747528faba764c00480d95d', 'c1c1ed0add425f0aa51eb37da604b7bd', 1942, '伪天津县知事', NULL, '负责伪天津县行政，对东丽地区实施粮食统制，强征物资，并组织汉奸武装配合日军扫荡。', '天津东丽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ee0b686988e9514aaa64105e7f3263b0', '32d70db4931754aab3d50afa4e5d738a', 1937, '伪华北政务委员会委员长（曾兼天津地区事务）', NULL, '作为华北伪政权高层，其政策直接影响天津及东丽地区，支持建立各级伪政权，协助日军经济掠夺。', '天津东丽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('91a2432d6c175ab4a7744d3999583865', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1939, '伪华北治安军总司令', NULL, '指挥伪治安军在天津东丽等地区驻防，参与“扫荡”抗日武装，杀害无辜百姓。', '天津东丽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('afdf74a7974f5a4eab57ac55a3775f6f', '6b71c1f8a88e55d88a22726eee2c52e9', 1938, '伪天津特别市警察局局长', NULL, '在天津及东丽地区建立特务网络，抓捕抗日志士，协助日军宪兵队进行残酷镇压。', '天津东丽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7a717489aa66570ab44a1c4abb8a8174', '14adcfc6021c513888a19263f1acb12f', 1937, '伪天津青帮头目/汉奸特务', NULL, '在天津东丽一带经营赌场烟馆，为日军搜集情报，参与迫害抗日群众，是地方恶霸型汉奸。', '天津东丽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('77ec13d7e238568aad0aeb29040a2543', '2af01e48c8c458878ff249af74b6c59e', 1940, '伪天津县保安队队长', NULL, '率伪保安队在东丽地区（如大毕庄、金钟河沿岸）巡逻，协助日军封锁交通，抓捕抗日人员。', '天津东丽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4aa2876259295c2ab938fdffb873af13', '7eaa90ba217050158dd164b88dd7ca7f', 1937, '伪天津特别市市长', NULL, '曾任伪天津市治安维持会委员长，后任伪天津特别市市长，积极推行日伪政权统治，镇压抗日活动。', '天津北辰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c255f3fbc3f4559086304713ab972bcf', '9a05a840f4165f4db3e6b806c0058634', 1940, '伪天津特别市市长', NULL, '继任伪天津特别市市长，协助日军实施经济掠夺和殖民统治，参与奴化教育推广。', '天津北辰');
