INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7e0193d787a5592fb459d6e93470d858', '6b71c1f8a88e55d88a22726eee2c52e9', 1935, '伪冀东防共自治政府天津办事处主任', NULL, '在天津为伪冀东政权服务，协助日军控制天津地区，破坏抗日活动。', '天津北辰');
