INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9c23bfd4488151359b563dc7293a3bc6', '32d70db4931754aab3d50afa4e5d738a', 1937, '伪天津特别市市长（首任）', NULL, '原北洋政客，天津沦陷后投日，任伪天津市长，协助日军接管天津，推行殖民统治，镇压抗日活动。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b03f653f2cf65ecebf9819f2ea941fac', '07961601ff2f53f5863147f327d72168', 1938, '伪天津特别市市长（第二任）', NULL, '原北洋官员，投日后任伪天津市长，在天津实施粮食统制，配合日军经济掠夺，逮捕抗日志士。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5584352657ec57038a45924dca85694d', '9a05a840f4165f4db3e6b806c0058634', 1943, '伪天津特别市市长（第三任）', NULL, '原外交官，投日后任伪天津市长，推行奴化教育，为日军提供劳工和物资，镇压地下抗日组织。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0b26c30b5d355f6ea67631738ad8df31', 'c66d1199e0f55a44ad0a16f8f1e355e1', 1937, '伪天津特别市公署顾问、伪华北政务委员会参议', NULL, '原天津文化界名人，投日后为日军在天津的文化侵略和殖民宣传服务，协助伪政权管理天津。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b0e36120caae5f72ab505dac20dfaf85', '81630a2fb4475f6f9739f4b7c0996e70', 1937, '伪天津警察局局长', NULL, '原天津警察系统官员，投日后任伪警察局长，在天津大肆搜捕抗日分子，破坏地下党联络站。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('54e4fcdc62db5eb8997b413cbf5ec73e', '340adba25424535985417eba5e18abbe', 1938, '伪冀东道尹、伪唐山市长', NULL, '原北洋官僚张弧之子，投日后在冀东（唐山、秦皇岛一带）任伪职，协助日军控制冀东矿区，镇压工人抗日运动。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('367a99c984cb5936b03960977c0629c0', '5ecdb6b22c615e368ffe537daaadad8f', 1939, '伪冀南道尹', NULL, '投日后任伪冀南道尹，管辖邢台、邯郸等地，推行“治安强化”运动，配合日军对冀南根据地的“囚笼政策”。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('feb29afa2e11583a8cebaee547744b84', 'eaa98601735151758eb8003f30e945e6', 1938, '伪保定道尹', NULL, '投日后任伪保定道尹，在冀中地区建立伪组织，强征民夫修筑碉堡公路，协助日军封锁抗日根据地。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('578c6fc83d295ca3b76a77bd2772f9e2', '24d3b7d6748157bbba495506f1eefbc6', 1938, '伪津海道尹（天津周边地区）', NULL, '投日后任伪津海道尹，管辖天津周边各县，推行伪政权法令，配合日军“清乡”行动。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a420f41d26c75f138fcb205974196110', '623d392eb5a05d4cac7b4f9ccb0a1da6', 1937, '伪华北政务委员会咨询委员（未正式就任但参与活动）', NULL, '原北洋交通系领袖，虽未任实职，但多次为伪华北政权出谋划策，在天津、河北有广泛人脉，协助日军拉拢旧官僚。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f69819cbb05e5890b123a08fbab11a31', '47c2a5c483015a58bd37abc52be5e3fe', 1937, '伪华北政务委员会经济顾问', NULL, '原北洋外交官，投日后在天津、河北为日军经济统制提供方案，参与掠夺华北资源。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c6ddc0af06af5779976c87982c89e8c9', 'e9dcbc06f7da51b491b08b0a854afc6e', 1937, '伪华北政务委员会法制顾问', NULL, '原北洋政客，投日后在北平、天津参与伪政权法律制定，为日军殖民统治提供合法性包装。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('364308e6b5c05647af7b81d301b6a7e6', '660f09b7ca32519485bb3a85e3371544', NULL, '（本人未投日，其旧部如）', NULL, '（此条为说明：孙传芳本人拒绝投日，但其旧部如周荫人、卢香亭等部分在河北投日，但无具体任职记录，故不列入。）', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('88720b5666285fee86d49aad0f8258d6', '9fa82ef38fea50c080649fee7c13c876', 1938, '伪华北绥靖军高级顾问（未公开任职但参与）', NULL, '原直系将领，投日后在天津、河北为伪军训练提供军事指导，协助齐燮元整编伪治安军。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2d511ff68de558848628e0c7668d1a89', 'c76033240de65c00b1770d6977ec70a1', 1937, '伪冀东保安队顾问', NULL, '原孙传芳部将，投日后在冀东地区协助日军训练伪军，参与镇压冀东抗日暴动。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4bebda579c6952c7baae33921efc3ec8', '4fc078bb6abd52efaab226d2d53038c6', 1933, '伪华北绥靖军总参议（未及就任被刺杀）', NULL, '原北洋皖系军阀，1933年受日军指使在天津、河北策划华北自治，被军统刺杀于北平六国饭店。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7dd3e661fca1585e9c76a96ae4397d33', '08a1ec477255562bb8a0e3fe6556bf8f', 1940, '伪冀察战区副总指挥（投日未遂被处决）', NULL, '原西北军将领，在河北南部与日军秘密勾结，企图投敌，被高树勋处决，未及正式投日。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c259d4a674cf574fa6a3277f60487de4', '0ec2ee6fed265ec5991932a6ff128192', 1943, '伪第五方面军总司令（投日后）', NULL, '原国民党第24集团军总司令，1943年在太行山被俘投日，其部队活动范围涉及河北南部，协助日军进攻冀鲁豫根据地。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('46d74fbb50e7594884809db68e96a7ff', 'a4b6b520415e5c858408bae9e7e4f97d', 1943, '伪新编第五军军长（投日后）', NULL, '原国民党将领，1943年投日，在河北、河南交界地区配合日军作战，袭击八路军。', '天津河北');
