INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bac4764dc0cf5dfaa7881f687188bf58', '58966c334b6350e9906938b4e1e222b2', 1941, '伪淮海省省长（原在河北活动）', NULL, '原国民党军官，投日后曾在华北（含河北）任职，后调任淮海，在河北期间参与反共活动。', '天津河北');
