INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9235f94be3b75c73a7b9ce404d7ef5c1', 'd0dc35dc2ec1562c9fed6773147f420d', 1938, '伪华北绥靖军参谋长', NULL, '原东北军将领，投日后任伪华北绥靖军参谋长，参与策划对河北抗日根据地的军事行动。', '天津河北');
