INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0a7d692fe67c5e59839d868461497d16', '9a05a840f4165f4db3e6b806c0058634', 1939, '伪天津特别市市长', NULL, '投日后任伪天津市长，推行日伪经济统制，为日军征粮征物，镇压天津抗日地下活动。', '天津河北');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8c0e86887e8b5ddc943c95d19dea0d22', '4d2d3d155bb454339a738c1c49764a53', 1937, '伪中华民国临时政府行政委员会委员长、伪华北政务委员会委员长', NULL, '原北洋财政官僚，投日后组建北平伪临时政府，管辖河北、天津等地，推行“以华制华”政策。', '天津河北');
