INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ba99842543e0519c983f7e6bf404fd2e', '7eaa90ba217050158dd164b88dd7ca7f', 1937, '伪天津商会会长、伪华北工商协会会长', NULL, '充当日本经济汉奸，控制天津商会，为日军征购战略物资，强迫商户捐献，垄断粮食和棉布贸易', '天津滨海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cfd1aa3a2964597db6482179bdd21733', 'e2fb0ddafac153ddafb917ae0099452d', 1938, '伪天津警察局局长', NULL, '指挥伪警察协助日军搜捕抗日分子，破坏地下党组织，镇压学生运动，参与制造多起逮捕和屠杀事件', '天津滨海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4c2ef6be68525487b0d0e98ae1250033', '340adba25424535985417eba5e18abbe', 1943, '伪天津市长（后期）', NULL, '接任伪天津市长，继续执行日伪政策，强化物资统制，强征劳工，配合日军最后挣扎', '天津滨海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6d138fddbca75124b990509f01c253ba', 'd2ee8f86e2bb5c469998afa9e90425f7', 1939, '伪天津地方法院院长', NULL, '为日伪司法服务，审判抗日志士，以“反满抗日”罪名判处爱国人士，维护日伪统治秩序', '天津滨海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('70013c43012d5e12b215896861fb6fee', '5c3741669af15a6e9889a80ed6b45794', 1938, '伪天津县知事（县长）', NULL, '在天津县推行日伪保甲制，强征民夫修建日军工事，勒索百姓，协助日军扫荡郊区抗日武装', '天津滨海');
