INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('35209859f6645e99b0c6901e3559bde8', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1938, '伪华北治安军总司令（在天津滨海地区驻军）', NULL, '组织伪治安军，在天津及滨海地区配合日军“扫荡”，屠杀抗日军民，其部队在塘沽、汉沽一带犯下暴行', '天津滨海');
