INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('65e7be8bb48d5a1ea4a0ab537cb70c43', 'be830f2d60665f0189881935079af216', 1936, '伪冀东防共自治政府秘书长（后任伪天津特别市秘书长）', NULL, '协助殷汝耕管理冀东，后调任天津伪政府，参与策划经济统制，协助日军掠夺天津工业资源', '天津滨海');
