INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b21a790e6c46586b90c968c02bb0ffda', 'b5b29d4e25db5f6db06c7cb4fd7ab546', 1939, '伪侯马矿区警备队长', NULL, '在侯马矿区为日军看管煤矿，镇压矿工反抗，强抓劳工送往东北。', '山西临汾_侯马');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c39d47c948b15b45b4963d97f7aa4c16', '36291946c2a055ef95a843efb1461a1b', 1942, '伪临汾绥靖公署参议', NULL, '为日军出谋划策，参与策划对临汾抗日武装的围剿，并劝降部分国民党游击队。', '山西临汾_侯马');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b1193fa432a158e8b66fd05ba7be3bb6', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '曾任阎锡山部高级官员，投日后任伪山西省长，推行日伪政权统治，协助日军在山西各地建立维持会，镇压抗日力量。', '山西临汾_侯马');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ce505a78f28a554c8269f54a94287429', '2b38113bed725cedaecdd9dc8d6365ec', 1938, '伪山西省公署顾问兼临汾地区维持会头目', NULL, '在临汾地区组织伪维持会，为日军征粮派夫，破坏抗日组织，协助日军扫荡。', '山西临汾_侯马');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4e4de2fc08bc54fdb0a581ca399fbc4d', '7987b939a2f5512296c45c13c7af807a', 1939, '伪临汾县知事', NULL, '投靠日军后任临汾伪县长，强征民夫修筑碉堡公路，搜捕抗日军民，向日军提供情报。', '山西临汾_侯马');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('111fbf23601f5908918151f9dcad3724', '142ed91c1ea95b6d922d76d4627e2b83', 1937, '伪蒙古军总司令（曾在晋南活动）', NULL, '虽为蒙奸，但曾率伪蒙古军配合日军在山西南部（包括临汾、侯马一带）作战，参与围剿抗日游击队。', '山西临汾_侯马');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5bb1536d24f852cebd1a115260c6928b', 'f8128d92a5455f2886dae039c7903166', 1941, '阎锡山部将领（后投日）', NULL, '在晋西事变后一度与日军秘密勾结，其部队在侯马、曲沃一带与日军达成默契，协助日军维持占领区秩序。', '山西临汾_侯马');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('47b1ff92da305f42848d2b2a5c801f26', 'b5b29d4e25db5f6db06c7cb4fd7ab546', 1940, '伪晋南道道尹', NULL, '任伪晋南道（辖临汾、侯马等县）道尹，推行保甲制度，为日军筹集粮饷，镇压当地抗日武装。', '山西临汾_侯马');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('884fcbdc38c955d1a5938a2a767fc2cb', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '投靠日军后任伪山西省长，推行奴化政策，协助日军在山西各地（包括临汾、古县一带）建立伪政权，强征粮税，镇压抗日活动。', '山西临汾_古县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2783d48fd3a850b680ba572bb8d8691d', '2b38113bed725cedaecdd9dc8d6365ec', 1938, '伪临汾县知事/伪县长', NULL, '日军占领临汾后出任伪县长，组织维持会，为日军提供情报，强迫民众修路筑堡，参与清乡扫荡，残害抗日军民。', '山西临汾_古县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('98bff08fb1cd52629c6868edf2a7dfc2', 'abfbfc55b2075575b7abe7d534e7196d', 1939, '伪古县维持会会长', NULL, '在古县地区组织维持会，协助日军征粮派款，出卖抗日积极分子，破坏地下抗日组织，导致多名群众被捕遇害。', '山西临汾_古县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0f6f1a8c00915764a3bef98abac4363b', '142ed91c1ea95b6d922d76d4627e2b83', 1940, '伪临汾保安队队长', NULL, '率伪保安队配合日军在临汾、古县交界地带进行多次“扫荡”，烧毁村庄，抢劫财物，抓捕并杀害抗日游击队员及家属。', '山西临汾_古县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8efc29fa62ba51e184030fb06a0a9c92', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '曾任阎锡山部将领，后投敌任伪山西省长，推行日伪政权统治，协助日军在山西各地建立维持会，镇压抗日力量。', '山西临汾_吉县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4d7b1129dc0e5548b82634d73365a6a9', '2b38113bed725cedaecdd9dc8d6365ec', 1939, '伪山西省公署顾问', NULL, '在临汾地区协助日军进行“治安强化运动”，组织伪警察和保甲制度，搜捕抗日军民。', '山西临汾_吉县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4079dd394a755efe91af9d4090c612ec', '7987b939a2f5512296c45c13c7af807a', 1940, '伪吉县知事', NULL, '任伪吉县知事期间，强征民夫修筑日军碉堡，强迫百姓领取“良民证”，并配合日军扫荡抗日根据地。', '山西临汾_吉县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3a2a499de30a5c3c9c91e315d942d530', '04e59fa422205372aae1c93ef3c9935a', 1941, '伪临汾县保安队队长', NULL, '率伪保安队多次袭击抗日游击队，杀害抗日干部，并参与日军在临汾的“清乡”行动。', '山西临汾_吉县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4223ffd1a19457b8bfd0b635335050df', 'f8128d92a5455f2886dae039c7903166', 1942, '伪晋绥军第7集团军总司令（投敌后）', NULL, '原阎锡山部将领，后与日军勾结，在吉县、乡宁一带配合日军进攻八路军，提供情报并协助维持日占区秩序。', '山西临汾_吉县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('009f6573f5ab5207a7ff93f4e8824e66', 'b5b29d4e25db5f6db06c7cb4fd7ab546', 1939, '伪临汾地区维持会会长', NULL, '组织维持会为日军筹集粮饷，强征劳役，并告密导致多名地下党员被捕牺牲。', '山西临汾_吉县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('527fc866b791516c8bb48419bd43f735', '36291946c2a055ef95a843efb1461a1b', 1943, '伪山西剿共军第1师师长', NULL, '率伪军驻防吉县一带，参与日军“铁滚扫荡”，烧毁村庄，掠夺物资，杀害抗日群众。', '山西临汾_吉县');
