INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('108f905eb7445df78ed45abd6640c015', 'f223b1b5966f5fcba005351202deb598', 1941, '伪晋西地区保安副司令', NULL, '在吉县、蒲县等地组织伪保安团，协助日军镇压民众反抗，参与“三光”政策下的破坏行动。', '山西临汾_吉县');
