INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b8ed640332ae51448f7fbb39c6c7ec96', '7987b939a2f5512296c45c13c7af807a', 1940, '伪吉县维持会会长', NULL, '在吉县组织维持会，为日军征粮派款，出卖抗日志士，导致多名地下党员被捕牺牲。', '山西临汾_吉县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3a2a499de30a5c3c9c91e315d942d530', '04e59fa422205372aae1c93ef3c9935a', 1941, '伪临汾县保安队队长', NULL, '率伪军配合日军在临汾、吉县一带“清乡”，烧杀抢掠，残害百姓，破坏抗日组织。', '山西临汾_吉县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('12d51fd980ea51ebb291579e0eafabd2', 'f8128d92a5455f2886dae039c7903166', 1943, '伪晋西地区“剿共”司令', NULL, '原晋军将领，后投敌任伪职，在吉县、乡宁等地指挥伪军进攻八路军，制造多起惨案。', '山西临汾_吉县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7c76c143337a59d8a08189dfe33a4b14', '7987b939a2f5512296c45c13c7af807a', 1938, '伪山西省公署顾问', NULL, '曾任阎锡山部军官，后投靠日军，参与组建伪山西政权，协助日军在晋南地区进行“扫荡”和情报搜集。', '山西临汾_大宁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8e9a566cd1a1514ebaa1b3db7085b34f', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '原阎锡山政府要员，后投敌任伪山西省省长，推行日伪统治政策，在临汾、大宁等地强征粮税，镇压抗日力量。', '山西临汾_大宁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6dfba8840faf51a69dc5e26962498372', '2b38113bed725cedaecdd9dc8d6365ec', 1939, '伪临汾县知事', NULL, '任伪临汾县知事期间，协助日军建立保甲制度，抓捕抗日军民，并强迫民众修筑公路和碉堡。', '山西临汾_大宁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dbb645590ba85aaca64031475786149f', '04e59fa422205372aae1c93ef3c9935a', 1938, '伪大宁维持会会长', NULL, '日军侵占大宁后出任维持会长，为日军筹集粮食、派夫拉差，并告密导致多名抗日干部被捕牺牲。', '山西临汾_大宁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ac61a4698fcf5c89a144f76dd6b31e56', '142ed91c1ea95b6d922d76d4627e2b83', 1938, '伪安泽县知事', NULL, '在日军占领安泽期间，出任伪县知事，协助日军推行“治安强化运动”，强征民夫修筑炮楼和公路，并组织伪警察队搜捕抗日军民。', '山西临汾_安泽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4d17b622b8e75fb186115142c2225f52', '89011c25945756f0895607dfc57520e6', 1939, '伪安泽县保安队队长', NULL, '率领伪保安队配合日军多次扫荡安泽抗日根据地，杀害抗日干部和群众数十人，并参与抢劫粮食和物资。', '山西临汾_安泽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d2faa5190b755130bbb05298eb7d4d43', 'b0f4d279a7185c07a07bc0b51ee6ecd0', 1938, '伪临汾县知事（兼安泽部分地区）', NULL, '在临汾及周边地区（含安泽西部）任伪职，为日军提供情报，强征捐税，并参与建立伪自卫团，镇压抗日活动。', '山西临汾_安泽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('49e7acf42b285959a594eb9d81ae10b1', '03b3ecf4f2f750d49a27d274d2bc8839', 1938, '伪安泽县维持会会长', NULL, '日军初占安泽时，率先组织维持会，为日军筹集粮款，并劝诱乡绅投敌，破坏抗日统一战线。', '山西临汾_安泽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('41987f2609fa512694638ba8c93bb030', '8c52a2d114655375bd9ebee7a8983881', 1940, '伪安泽县警察所所长', NULL, '指挥伪警察抓捕抗日地下党员和进步群众，严刑逼供，导致多人牺牲，并协助日军推行“保甲制度”。', '山西临汾_安泽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('edf3b7706f645a92abd5b0db4e5ef999', '3475d83172b1517494ebe1185e05a653', 1941, '伪安泽县新民会会长', NULL, '负责在安泽宣传“中日亲善”和“大东亚共荣”，组织奴化教育，并诱骗青年参加伪军。', '山西临汾_安泽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9afab4811bc25f0ba80bf0114f5753b1', '6be2c737b9c856c88bdfbbf92df75721', 1942, '伪安泽县警备队中队长', NULL, '率警备队驻守安泽县城，多次参与“清乡”行动，杀害抗日军属，并抢劫民间财物。', '山西临汾_安泽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('60c32c66bbbe50aba8f611051658ad9b', 'c1b1c603b33255eb89e6a49f50326e0a', 1939, '伪临汾道公署参事（兼管安泽事务）', NULL, '作为伪临汾道官员，参与策划对安泽抗日根据地的经济封锁，并协助日军建立情报网。', '山西临汾_安泽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a923dcaa9b625b9d98efd5decb4441f4', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令（曾在山西活动）', NULL, '投靠日军，任伪蒙古军总司令，曾率部配合日军在山西、绥远等地进攻抗日武装，参与镇压晋西抗日根据地。', '山西临汾_安泽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b7df6f7fd84c5fd4ba22a3bab422ef4a', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪东亚同盟军总司令（活动于山西北部）', NULL, '原为土匪，后投日，任伪东亚同盟军总司令，在山西北部及绥远地区为日军效力，多次袭扰抗日军民。', '山西临汾_安泽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c9507bc79cca513fa720e2f267b95348', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长（1938-1943）', NULL, '日本扶植的伪山西省省长，在太原推行日伪统治，协助日军“扫荡”晋南、临汾、安泽等抗日根据地，强征粮税。', '山西临汾_安泽');
