INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eb0c36a38c0b52a593df772f44552379', '7987b939a2f5512296c45c13c7af807a', 1938, '伪山西省公署顾问', NULL, '曾任中共顺直省委书记，后叛变投敌，在山西临汾、蒲县一带为日军搜集情报，协助建立伪政权，破坏抗日组织。', '山西临汾_蒲县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2d1442d1d9755b34a0174ae36041b742', '04e59fa422205372aae1c93ef3c9935a', 1938, '伪蒲县维持会会长', NULL, '日军占领蒲县后出任维持会长，为日军征粮派款，强拉民夫，镇压抗日群众，曾率伪警抓捕抗日干部并送交日军宪兵队。', '山西临汾_蒲县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6dc6b3fc157a5bb58f87af064b9a304e', 'aa7913ec446c597faf6a8833076cf708', 1939, '伪临汾县保安队副队长', NULL, '原为地方民团头目，投日后任伪保安队副队长，在临汾、蒲县交界地带多次袭击八路军游击队，杀害抗日家属，抢劫物资。', '山西临汾_蒲县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cf123cc3682d5a809a4c92c564528e61', '22c3b1ca05ae5b069f4e86515cfbfce9', 1940, '伪蒲县警察所所长', NULL, '充当日军耳目，在蒲县城乡建立情报网，多次带领日伪军突袭抗日村庄，逮捕并刑讯逼供抗日军民，致多人死亡。', '山西临汾_蒲县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('211c15b5ab3352c9adafb4af0de2150d', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '原为阎锡山部属，投日后任伪山西省长，推行日伪政权统治，协助日军在山西各地建立维持会，镇压抗日力量。', '山西临汾_襄汾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0a4f92680bfd5723a54fdc6c251e38e3', '2b38113bed725cedaecdd9dc8d6365ec', 1939, '伪山西省公署顾问', NULL, '参与日伪对临汾、襄汾地区的“治安强化”运动，协助日军收集情报，破坏抗日组织。', '山西临汾_襄汾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cac375ee6d6555e482297f90d2675b3f', '7a4d595c479e5af792f43dfe435fb25b', 1940, '伪临汾县知事', NULL, '在临汾县城推行保甲制度，强征民夫修筑碉堡公路，为日军提供粮食和劳役，镇压当地抗日群众。', '山西临汾_襄汾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f2b6c52797255df6b4cc174be7f2a9f6', '04e59fa422205372aae1c93ef3c9935a', 1938, '伪襄陵县（今襄汾）维持会会长', NULL, '日军占领襄陵后组织维持会，为日军筹粮派款，出卖抗日积极分子，导致多名地下党员被捕牺牲。', '山西临汾_襄汾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9b6523eadbb05f3b887f2d2f017734ca', '67441094f5ab50528a4402978598d4c3', 1941, '伪汾城县（今襄汾）警备队队长', NULL, '率伪警备队多次配合日军“扫荡”汾城、襄陵一带，杀害抗日军民，抢劫物资，烧毁村庄。', '山西临汾_襄汾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('62545c559aa75078bc732dc64ddae2bc', '153310fe23185f0ca1018c325e83762c', 1942, '伪山西省政府参议（兼临汾地区特务）', NULL, '原为地方士绅，投日后充当日军特务，在临汾、襄汾交界处建立情报网，多次引导日军突袭抗日游击队驻地。', '山西临汾_襄汾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f2c12b0b50da517db5176f912ea44e84', 'f8128d92a5455f2886dae039c7903166', 1943, '伪晋南保安司令部顾问', NULL, '协助日军整编伪军，在临汾、襄汾地区招募伪军士兵，参与对抗日根据地的经济封锁。', '山西临汾_襄汾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6dd5eab5a6125f3c8d588237bd669da8', '062751f88bf45488abeca9b133d926b3', 1939, '伪襄陵县新民会会长', NULL, '推行奴化教育，强迫民众参加“新民会”活动，搜集抗日言论，向日军告密，导致多名群众被杀害。', '山西临汾_襄汾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9a98ff9a26275b3eab1f02c28e9def67', '8a4917ec4ae656d999760b7131dc4175', 1940, '伪山西省文化协会委员（驻临汾）', NULL, '在临汾地区宣传“中日亲善”，为日军粉饰侵略，参与审查和销毁抗日书刊，破坏文化抗日活动。', '山西临汾_襄汾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3a48be3d3fb05fe4968db488f63cbb06', '2533453a1931526b9326f076cbf651f5', 1942, '伪汾城县保安团副团长', NULL, '协助日军在汾城（今襄汾）实施“三光政策”，率部袭击抗日村庄，掠夺牲畜粮食，杀害抗日家属。', '山西临汾_襄汾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cf0b6a05a33d53589de5187c94f13432', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '曾任阎锡山部高级官员，后投敌任伪山西省省长，协助日军推行“治安强化运动”，镇压抗日力量，征收苛捐杂税，为日军提供物资和情报。', '山西临汾_襄汾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1f487219c4b35e769e26bbd568980f7d', '2b38113bed725cedaecdd9dc8d6365ec', 1938, '伪山西省公署顾问兼临汾地区维持会会长', NULL, '在临汾地区组织伪政权，协助日军建立“维持会”，强迫民众领取“良民证”，搜捕抗日志士，并参与日军对襄汾等地的扫荡行动。', '山西临汾_襄汾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('537afa79b8cc5f0ea99972a6f9d58d69', '7a4d595c479e5af792f43dfe435fb25b', 1939, '伪临汾县知事', NULL, '任伪临汾县知事期间，为日军征粮派夫，破坏抗日根据地，曾配合日军在襄汾、汾城一带清乡，杀害抗日军民。', '山西临汾_襄汾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('57b499a44b2c5a0cba266bb6d0232746', '142ed91c1ea95b6d922d76d4627e2b83', 1940, '伪襄陵县（今襄汾）维持会会长', NULL, '在襄陵县（今属襄汾）组织伪维持会，为日军提供当地抗日武装情报，参与“扫荡”时带路，并强征民夫修筑碉堡和公路。', '山西临汾_襄汾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d2ea5f9b7bca578abe38a29970755692', '153310fe23185f0ca1018c325e83762c', 1941, '伪山西省政府顾问（原阎锡山幕僚）', NULL, '虽名义为顾问，但实际参与伪省府对临汾、襄汾地区的“宣抚”工作，协助日军分化抗日力量，劝降地方武装。', '山西临汾_襄汾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('42377d71cac5585aafb957a450eec01a', 'b5b29d4e25db5f6db06c7cb4fd7ab546', 1938, '伪山西省公署顾问', NULL, '曾任阎锡山部将领，后投日，任伪山西省公署顾问，协助日伪政权在山西推行殖民统治，参与对晋西南地区的“扫荡”策划。', '山西临汾_隰县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f3f850c38f80520fb76c94c905b6a30b', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '原为阎锡山幕僚，投日后任伪山西省省长，在太原及晋南地区推行日伪政令，组织伪军和维持会，镇压抗日力量。', '山西临汾_隰县');
