INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('77fdb07783c65c938354611fece6ee84', 'fa86a72a17bd5951b4407075ff1a677b', 1942, '伪石楼-交口联防区指挥官', NULL, '统管伪军和伪警察，在交口西部山区推行“并村”政策，制造无人区，切断八路军补给线。', '山西吕梁_交口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8cc4e7ca9e4e57b9b2bf48bde30d0c70', '43f70910341c59c580aa04262b5b1762', 1937, '交城县伪县长', NULL, '投靠日军，任交城县伪县长，协助日军推行“治安强化运动”，强征民夫、粮食，镇压抗日群众。', '山西吕梁_交城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('32d1d3fe43625230868843fdff8057e6', '8edba735e5835b9ca5a0ac5b125e9326', 1938, '交城县伪保安队队长', NULL, '率伪保安队多次配合日军扫荡交城山区抗日根据地，杀害抗日干部和群众，烧毁村庄。', '山西吕梁_交城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('12775e9685215c7bb010912ba0ab8923', 'd802b369e43c5e1095e9d2dcfa66ce3b', 1939, '交城县伪警察局局长', NULL, '为日军搜集抗日情报，抓捕地下党员和进步人士，参与制造多起惨案。', '山西吕梁_交城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c9c28dfefb27509981c00d2455f6add0', '5c921e3d243b56ecb74f90581038ff0d', 1937, '交城县伪维持会会长', NULL, '日军占领交城后率先组织维持会，为日军筹粮派款，强迫百姓领取“良民证”。', '山西吕梁_交城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('da6d0d6b40725599b55ff4605e697016', '22c3b1ca05ae5b069f4e86515cfbfce9', 1940, '交城县伪自卫团团长', NULL, '组织伪自卫团，配合日军封锁抗日根据地，参与“三光”政策行动，抢劫百姓财物。', '山西吕梁_交城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f0c65a3475f557c1819c1a2ef36dc09c', 'e60d0335f96157edb58448797cda6ce0', 1941, '吕梁地区伪警备队副队长', NULL, '在吕梁山区多次率伪军袭击八路军游击队，杀害抗日家属，破坏地下交通线。', '山西吕梁_交城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5d5b9916e23c54ed92a3d03f78ebb6bc', '948107882bd159d6a1053331b9f59ed2', 1938, '交城县伪税务局局长', NULL, '为日军强征各种苛捐杂税，逼死多名交不起税的农民，贪污勒索民财。', '山西吕梁_交城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('97a1f5b222e950619e7cf072866d5b90', 'b46657ea48515d69991ec5ab9ccca515', 1939, '交城县伪新民会会长', NULL, '宣扬“中日亲善”，组织奴化教育，诱骗青年参加伪军，破坏抗日宣传。', '山西吕梁_交城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4464e75d923455f2882212f5f3f2f466', 'fd5781316fab54ec85b964acf16144f8', 1940, '交城县伪区公所区长', NULL, '在交城东区为日军征粮抓丁，告密出卖抗日村干部，导致多名党员牺牲。', '山西吕梁_交城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e36a0a1afe3055b0bcf004cf39b32c58', 'f713b495ff1c51a89f0c1c9fa379e895', 1942, '吕梁地区伪军独立营营长', NULL, '率伪军驻守交城至离石公路沿线，袭击抗日运输队，抢劫物资，杀害护送人员。', '山西吕梁_交城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('49a0cd4f1e005934bd6fb9bdb296913f', 'f8128d92a5455f2886dae039c7903166', 1939, '伪山西省公署顾问、阎锡山部投敌将领', NULL, '曾任阎锡山部军长，1939年投靠日军，任伪山西省公署顾问，协助日军在晋西地区推行“治安强化”运动，参与对抗日根据地的扫荡。', '山西吕梁_孝义');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5735fc3c382c590eb9d73862fa190b02', 'f223b1b5966f5fcba005351202deb598', 1940, '伪山西保安司令部副司令（投敌后）', NULL, '原阎锡山部将领，后与日军勾结，在吕梁、孝义一带组织伪保安队，配合日军清剿抗日武装，残害抗日军民。', '山西吕梁_孝义');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dc6f54babc8751c09e5141054dfe9781', 'b5b29d4e25db5f6db06c7cb4fd7ab546', 1938, '伪孝义县知事', NULL, '日军占领孝义后出任伪县知事，为日军征粮派款，强征民夫修筑碉堡公路，破坏抗日地下组织，抓捕抗日人员。', '山西吕梁_孝义');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8512f4fadca85a4886be8a5c9c1bf0c8', '627600350a805bcba587366083b75195', 1939, '伪晋西地区“剿共”司令', NULL, '原晋绥军将领，投敌后任伪“剿共”司令，在孝义、中阳、离石一带多次率伪军袭击八路军游击队，烧杀抢掠。', '山西吕梁_孝义');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a17bd484384b5c72acbbff72395b936e', '3ecfae9ff43c5029ab1679ba2722a82a', 1940, '伪孝义县警备队队长', NULL, '组织伪警备队，为日军提供情报，参与多次对孝义抗日根据地的“扫荡”，杀害抗日干部和群众数十人。', '山西吕梁_孝义');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f72b29f29e285cbe9433e860b5aba13a', '8889ca062e5650f5a1f0f9b458376980', 1941, '伪吕梁地区维持会会长', NULL, '在吕梁山区多个村镇建立维持会，为日军摊派粮款，强迫百姓领取“良民证”，并告密导致多名地下党员被捕牺牲。', '山西吕梁_孝义');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('51b4014906ed5c3f8ac2c2908bb431e5', '5ba9b438aa8057fe971e7bd39b052daf', 1942, '伪孝义县保安团团长', NULL, '率保安团配合日军对孝义西部山区进行“铁壁合围”，烧毁村庄十余个，抢掠牲畜粮食，并参与活埋抗日军属。', '山西吕梁_孝义');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('61382ae384305a5391c7613a4787c1aa', 'd72e220330bb5f47903f6c651cff9d31', 1940, '伪山西省第六区行政督察专员（驻孝义）', NULL, '在孝义设立伪行政机构，推行保甲制度，强征青年充当伪军，并协助日军建立情报网，破坏抗日政权。', '山西吕梁_孝义');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cd04f4d274e551fab464716038d7fdde', 'f3b50491ce8455588b0bf433a65bb3bd', 1941, '伪孝义县新民会会长', NULL, '利用新民会宣传奴化思想，组织“青年训练班”为日军输送伪职人员，并参与诱降抗日游击队员。', '山西吕梁_孝义');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e4aa37df60a353de9f6440728c2be28a', '7401837a0aec54c6bd9e0cc79da674d4', 1943, '伪吕梁山区“和平救国军”支队长', NULL, '收编散兵游勇组成伪军支队，在孝义、汾阳交界处设卡收税，抢劫商旅，多次袭击八路军运输队。', '山西吕梁_孝义');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eec851ea0ca45fe992f9d65b8fcfe880', '945ae1b8fd815a5186188783c92f9adf', 1939, '伪孝义县警察局局长', NULL, '指挥伪警察搜捕抗日分子，严刑拷打逼供，破坏中共孝义县委地下联络站，导致多名交通员牺牲。', '山西吕梁_孝义');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bb41f0a913dd53968ee1246d6f366774', '47feaf20346c5ba8b655635346e85eca', 1938, '伪孝义县“宣抚班”班长', NULL, '随日军宣抚班在孝义农村进行“怀柔”宣传，诱骗群众回村“归顺”，随后指认抗日家属，致使多人被日军杀害。', '山西吕梁_孝义');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3f40dd3f76cc59349563732692bfe580', '1c5a128633cf50dc8de2a8b2c01a0146', 1938, '岚县伪县长', NULL, '投靠日军，任岚县维持会会长及伪县长，协助日军建立伪政权，强征民夫，搜刮粮食，镇压抗日群众。', '山西吕梁_岚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('343d2a97ed1b5c6da43a49c7db27c969', 'aba25c76faa55cc799611265e41dbbf3', 1940, '岚县伪保安队副队长', NULL, '率伪保安队配合日军扫荡抗日根据地，抓捕抗日干部，杀害无辜百姓，烧毁村庄。', '山西吕梁_岚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bb48980440f45cb8881bee925587b3f1', '0f049069cc8c5406a9bd916729197bba', 1939, '岚县伪警察所所长', NULL, '充当日军爪牙，负责岚县县城治安，多次带队搜捕地下党员，刑讯逼供抗日志士。', '山西吕梁_岚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e384d2fdeb30581cbd226a311ef25462', '706f573e84a55602b5524be304cca94e', 1941, '岚县伪区公所区长', NULL, '在岚县东村一带设立伪区公所，为日军征收粮款，告密抗日活动，导致多名群众被捕。', '山西吕梁_岚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d85e3ea38f825da9a8ce88e56c460061', '6be2c737b9c856c88bdfbbf92df75721', 1942, '岚县伪新民会会长', NULL, '宣传奴化思想，组织“新民会”胁迫群众参加日军庆典，破坏抗日宣传，提供情报给日军。', '山西吕梁_岚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3a46a5b2c2575183a3e86e7c67263cd5', '5ba9b438aa8057fe971e7bd39b052daf', 1943, '岚县伪军连长', NULL, '率伪军驻防岚县普明镇，多次袭击八路军游击队，抢劫百姓财物，杀害抗日军属。', '山西吕梁_岚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('24e438f1ef92518c81d9101fce1e1f53', '6fac5b3093e75f2eb048c97af0e6c7d4', 1940, '岚县汉奸密探', NULL, '充当日军便衣密探，混入集市和村庄刺探八路军情报，直接导致岚县游击队两次遭伏击。', '山西吕梁_岚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('62215826e26e5a0c84eaac40f2c1fff1', '1699423414475bb9a1076228949cf3f2', 1941, '岚县伪合作社主任', NULL, '控制岚县物资配给，垄断食盐、布匹，高价盘剥百姓，将紧缺物资优先供应日军。', '山西吕梁_岚县');
