INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2dc9643c68b65bdd832ca87479427184', 'be4eaecc9af056e787d52f2319a57fdc', 1941, '文水县伪新民会会长', NULL, '宣传奴化思想，组织“新民会”为日军服务，强迫群众参加反共集会，告密抗日积极分子。', '山西吕梁_文水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cad31d6ed9485572a66051f54c5ec463', '0ddb00faaf79530da6011753a2589a9b', 1942, '文水县伪区公所区长（一区）', NULL, '在文水一区为日军征粮派夫，协助日军建立“维持会”，镇压当地抗日活动。', '山西吕梁_文水');
