INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('41de1f768e335f75b412f537c18bddba', 'b0e7b6c675a85c98b597c515dcb58624', 1939, '文水县伪商会会长', NULL, '为日军筹措军需物资，垄断粮食布匹，从中牟利，并强迫商户向日军“献金”。', '山西吕梁_文水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('927b8d730a645eb8b0d7c5eca7f4a634', 'e237f0e92533578a8a7eb74e21e10eb6', 1940, '文水县伪自卫团团长', NULL, '组织伪自卫团，配合日军巡逻封锁，参与“清乡”行动，杀害抗日游击队员。', '山西吕梁_文水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('790365166cee550ea7a33d895123d4e3', '375f64770be354759bcbcb31879bc3ee', 1939, '第二战区司令长官（暗中通敌）', NULL, '虽名义抗日，但1940年后与日军达成“默契”，在文水等晋西地区默许伪政权存在，部分部下直接投敌。', '山西吕梁_文水');
