INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9db9a208deef520ebcba49ebe7d2f816', '142ed91c1ea95b6d922d76d4627e2b83', 1936, '伪蒙古军总司令、伪大同地区军事指挥官', NULL, '率伪蒙古军配合日军侵占大同，后驻防该地区，参与“扫荡”八路军根据地，残害抗日军民。', '山西大同');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ba77adc4c5d05feeb77b568c75657edf', '03751651c36952668c9b65b923b9c221', 1937, '伪蒙疆联合自治政府主席（辖大同）', NULL, '作为伪蒙疆政权首脑，将大同划入其统治范围，支持日军经济掠夺和奴化教育，是蒙奸首要人物。', '山西大同');
