INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c82d4240e21e5d25b7503e0cc7aed83b', '27c84878572e5361a427d9981c30abbf', 1939, '伪大同警务段段长', NULL, '统领伪警察，协助日军抓捕抗日地下人员，破坏中共大同地下组织，参与屠杀无辜百姓。', '山西大同');
