INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9559e412a03059cdad5074fbaf69655b', '44a56b7e5dd0548f9a90e01ab4fb636a', 1940, '伪大同经济合作社主任', NULL, '负责为日军统制大同地区粮食和物资，强制低价收购农民粮食，导致民众饥荒，并贪污勒索。', '山西大同_大同经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9d01a66221e55ea9a7b4ca07f6c940ff', '3c0cec769a465f2da5d9587d32cf51f4', 1937, '伪大同宪兵队翻译兼密探', NULL, '为日军宪兵队充当翻译和密探，告密抓捕抗日人士，参与刑讯逼供，造成多名地下党员牺牲。', '山西大同_大同经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e20fff38dba454ef858a9800f0c612da', '1b2a74c9131c529189abbe38ef160927', 1937, '伪大同县维持会会长', NULL, '日军初占大同后组织维持会，为日军征夫派款，提供慰安妇，协助建立伪政权。', '山西大同_大同经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b036e48a3384502d918cfae6e239b909', 'c519ae0e253d5f0a8970efc34285a045', 1938, '伪大同矿区警察署署长', NULL, '管理大同煤矿矿区，残酷压榨矿工，迫害反抗劳工，为日军掠夺煤炭资源提供武力保障。', '山西大同_大同经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6a1f1d9345cf5b23bdc4896b3cdbf253', '142ed91c1ea95b6d922d76d4627e2b83', 1937, '伪蒙古军总司令、伪大同省省长', NULL, '投靠日军，任伪蒙古军总司令，后任伪大同省省长，协助日军统治大同地区，镇压抗日活动，强征劳工与粮食物资。', '山西大同_大同经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('496626b484b652ab9dc55a818b0dd6ab', 'bd9f9f87c6ae5466b0b61cbd65e84d14', 1937, '伪大同县知事（县长）', NULL, '日军占领大同后出任伪县长，推行保甲制度，组织伪警察协助日军清乡，抓捕抗日军民，征收苛捐杂税。', '山西大同_大同经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f826dbfa210859188ac19f7f4294662b', '23f501dac7075660a40e35f451c085d6', 1938, '伪晋北政厅厅长（驻大同）', NULL, '任伪晋北自治政府要职，后任伪晋北政厅厅长，管理大同及周边县份，配合日军“治安强化运动”，奴化教育民众。', '山西大同_大同经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0eb7b203a9085c3eabef2a8ca4c6985e', 'bc30a098483b5d089fb9d8e46c9211df', 1937, '伪晋北自治政府最高委员', NULL, '日军扶植的伪晋北自治政府首脑，驻大同，主持伪政权日常事务，为日军提供粮秣、情报，协助镇压抗日力量。', '山西大同_大同经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5b6dbea037d657d7a4a6b009880a7dbb', '1844d9740d0a5e8c9fd03b840a893aa0', 1938, '伪大同商会会长', NULL, '充当汉奸商人，为日军统制大同煤炭、皮毛等资源，强迫商户“献金”，协助日军经济掠夺，迫害爱国商民。', '山西大同_大同经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f3d362ef07d55144afccb5c90931f8d5', '27c84878572e5361a427d9981c30abbf', 1939, '伪大同保安队队长', NULL, '率伪保安队配合日军扫荡大同周边抗日根据地，杀害抗日干部，抢劫民财，多次参与“清乡”行动。', '山西大同_大同经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cf77e1ae932b54b7926a8b4eaba33cfe', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、天镇县保安队队长', NULL, '原为天镇县地方武装头目，日军侵占天镇后投敌，任伪蒙古军总司令，协助日军镇压抗日力量，参与“治安强化运动”，残害当地百姓。', '山西大同_天镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5ae69424f44d54d6848910dc8dc529ac', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令、天镇地区伪军头目', NULL, '原为土匪出身，后投靠日军，在天镇、大同地区组织伪军，配合日军扫荡抗日根据地，抢劫民财，杀害抗日军民。', '山西大同_天镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('454daa35fe545cfa82ef5d605dbaf466', '27c84878572e5361a427d9981c30abbf', 1937, '伪天镇县知事（县长）', NULL, '日军占领天镇后出任伪县长，推行日伪政权，强征粮税，组织维持会，协助日军建立保甲制度，镇压抗日活动。', '山西大同_天镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c4cf6c02bd27541eb9b9896bed117ba0', '1330cb6794015bf995004164cbdee4f0', 1938, '伪天镇县警察局局长', NULL, '任伪警察局长期间，抓捕抗日地下工作者，为日军提供情报，参与“清乡”行动，残害无辜群众。', '山西大同_天镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8cba72d972405c518dd4627aea76aa35', '8320e3e3065f5f31a864a1fd27201ca3', 1937, '伪大同省公署参事、天镇县维持会会长', NULL, '天镇沦陷后率先组织维持会，迎接日军，后升任伪大同省参事，协助日军推行经济掠夺政策，强征民夫。', '山西大同_天镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c0385aa39cdc572ea51b6a611c9bf376', 'c73fd813480653559ada941382fd4b24', 1939, '伪天镇县保安团团长', NULL, '组织地方伪保安团，配合日军“扫荡”天镇南山抗日游击队，杀害多名抗日群众，烧毁村庄。', '山西大同_天镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('878159d23cfb52ad8ffb4a3c475fb10c', 'bd9768cce97c51739fa3dac7c5639ebc', 1940, '伪天镇县新民会会长', NULL, '任伪新民会会长，推行奴化教育，强迫民众参加“反共”集会，搜集抗日情报供日军使用。', '山西大同_天镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2b06e4e73ac556fb867b011573ac8978', '44196d928e4856589a333de83b1cae68', 1938, '伪大同省天镇县税务局长', NULL, '为日军征收各种苛捐杂税，强抢粮食，导致天镇百姓饥荒，并贪污勒索，民愤极大。', '山西大同_天镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fbd557dbecff57f0a38cd904026a194b', 'fdc924a005d9538a8da27a0094bf8f69', 1941, '伪天镇县警备队队长', NULL, '率警备队多次袭击八路军游击队，杀害抗日干部，并参与日军“三光”政策，烧杀抢掠。', '山西大同_天镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b8b5880429cc50688e49364d80f2ddf3', '7203cbd1598a5c3f8ccc19f99be6641e', 1937, '伪天镇县司法科科长', NULL, '为日伪政权审判抗日人士，滥施酷刑，判处多名爱国群众死刑或劳役，是日伪司法帮凶。', '山西大同_天镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9dbcca36a5a757c198221ee75405f80a', '3c0cec769a465f2da5d9587d32cf51f4', 1937, '伪天镇县知事', NULL, '日军侵占天镇后出任伪县长，协助日军推行“治安强化运动”，强征民夫修筑碉堡，并参与掠夺当地粮食资源供给日军。', '山西大同_天镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('528ce59ecebb57efb6177d8d9d79a80a', '5220106099c25b7984d80c869672323e', 1938, '伪大同省公署顾问', NULL, '作为伪蒙疆政府派驻大同的代表，配合日军实施“以华制华”政策，参与组建伪警察队，镇压抗日活动，并协助日伪军清乡。', '山西大同_天镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6bb361028d1253fa803a5482ac30457f', '142ed91c1ea95b6d922d76d4627e2b83', 1936, '伪蒙古军总司令（活动于大同地区）', NULL, '率伪蒙古军配合日军占领大同及周边地区，后任伪蒙疆联合自治政府要职，在天镇一带协助日军“扫荡”，残害抗日军民。', '山西大同_天镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3b41b6afb163580685f9ac97acac851d', 'f8128d92a5455f2886dae039c7903166', 1939, '伪晋北政厅厅长（后投敌）', NULL, '原晋军将领，投日后任伪晋北政厅厅长，管辖包括天镇在内的晋北各县，推行奴化教育，强征劳工，为日军提供物资支持。', '山西大同_天镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('38e6fe3a972e5cb0b5cb1b0cf2f4b6ca', 'bc30a098483b5d089fb9d8e46c9211df', 1937, '伪大同县知事（兼辖天镇事务）', NULL, '日军占领大同后出任伪县知事，组织维持会，协助日军建立伪政权，并参与对天镇地区抗日武装的围剿。', '山西大同_天镇');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('576f1651372e51a4a00ca5170b1badab', '142ed91c1ea95b6d922d76d4627e2b83', 1937, '伪蒙古军总司令、伪大同省公署顾问', NULL, '原为土匪出身，后投靠日军，任伪蒙古军总司令，参与指挥伪军配合日军扫荡左云、大同地区，残害抗日军民，推行“治安强化”运动。', '山西大同_左云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('acf174ecd084506daa974009c6891c14', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令、伪大同地区宣抚使', NULL, '组织伪军武装，在左云、右玉、大同边界地区多次袭击八路军游击队，抓捕抗日干部，为日军提供情报，协助日军建立伪政权。', '山西大同_左云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bc0fb9a3b9cd5c21807fdbcdd4b8b0e2', 'f8128d92a5455f2886dae039c7903166', 1938, '伪晋北政厅厅长（后改称伪大同省省长）', NULL, '原为阎锡山部将领，投日后任伪晋北政厅厅长，管辖大同、左云等县，推行日伪“施政跃进”政策，强征民夫、粮食，镇压抗日活动。', '山西大同_左云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('53bd49081f015a718d2be00d78d6aca7', '23f501dac7075660a40e35f451c085d6', 1939, '伪大同县知事（曾兼左云县伪职）', NULL, '在左云、大同地区组织伪警察队，配合日军“清乡”，杀害抗日家属，强征苛捐杂税，破坏地下党组织。', '山西大同_左云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5b15e2671641564182d3e2661406d348', '27c84878572e5361a427d9981c30abbf', 1940, '伪左云县保安队队长', NULL, '率伪保安队多次突袭左云南山抗日根据地，烧毁村庄，抓捕并杀害八路军伤病员及地方干部，罪行累累。', '山西大同_左云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c905786df1e05a51a56c424a018a3d14', '8889ca062e5650f5a1f0f9b458376980', 1937, '伪左云县维持会会长', NULL, '日军占领左云后率先组织维持会，为日军筹粮派款，提供抗日人员名单，导致多名地下党员被捕牺牲。', '山西大同_左云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1f7475dbfe0e5928b1439f0cecd9b463', 'd23b605c327f5958a1ce4e4e8443ceb1', 1941, '伪大同省警务厅特务科科长', NULL, '负责大同、左云地区特务工作，建立情报网，破坏抗日组织，亲自审讯并酷刑折磨被捕的抗日志士。', '山西大同_左云');
