INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('307c8e7506d0509ab85055ee2f5138ee', '00cabf19b9e4579fbb8cf12e85e3abc6', 1939, '伪大同省警务厅厅长', NULL, '主管伪警宪特，在左云、大同地区建立情报网，多次组织搜捕地下党员，破坏抗日组织，执行日军“三光”政策。', '山西大同_左云');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('55ff585d657554d89200cad9b2249416', '142ed91c1ea95b6d922d76d4627e2b83', 1937, '伪蒙古军总司令、伪大同省省长', NULL, '投靠日军，任伪蒙古军总司令，后任伪大同省省长，协助日军在平城地区推行殖民统治，镇压抗日力量。', '山西大同_平城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('de9d8a097d2e590f9de9f0f55cf04dff', '3c0cec769a465f2da5d9587d32cf51f4', 1938, '伪大同县知事', NULL, '任伪大同县知事期间，强征民夫、粮食，为日军提供物资，抓捕抗日军民，破坏地下抗日组织。', '山西大同_平城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('508e517b29d85943b3825cc35ff11762', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满洲国国务总理大臣（曾涉足大同地区）', NULL, '虽主要活动于东北，但曾以伪满高官身份视察大同、平城地区，协助日军协调华北伪政权，推行奴化政策。', '山西大同_平城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a8513a6f7c07566ca8f9963fc59ba072', 'f8128d92a5455f2886dae039c7903166', 1937, '伪晋北自治政府顾问', NULL, '原晋军将领，投日后任伪晋北自治政府顾问，参与组建伪政权，协助日军在平城地区建立保甲制度，镇压抗日活动。', '山西大同_平城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f9138d44c56c525a9a74b98c5f158aec', 'bc30a098483b5d089fb9d8e46c9211df', 1939, '伪大同省公署参事', NULL, '任伪大同省公署参事，负责文化教育领域，推行奴化教育，篡改历史教材，为日军侵略张目。', '山西大同_平城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2d20c3001a005b7dbb8cefe0bd597fe3', '1844d9740d0a5e8c9fd03b840a893aa0', 1940, '伪大同保安队队长', NULL, '任伪大同保安队队长，率伪军配合日军扫荡平城周边村庄，杀害抗日干部和群众，抢劫财物。', '山西大同_平城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8d58a2b8eeba50ce87cd3f2198df8f3f', '4bd9cd1ed4f65f568f7afde7603fda36', 1937, '伪平城维持会会长', NULL, '日军占领平城后首任维持会会长，为日军筹集粮饷，强迫商户“献金”，协助日军建立治安秩序。', '山西大同_平城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('09cc988931f25370b8d1ba8c2e136193', '05b30d336bd85287a3148c07f0f2bd34', 1938, '伪大同警察局局长', NULL, '任伪大同警察局局长，指挥伪警抓捕抗日地下党员，严刑逼供，破坏中共平城地下交通站。', '山西大同_平城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('72a41ac949de5cd49e8b77ff7373ee95', '3d54f8fc40a95bcca4bf279c54506cf6', 1939, '伪平城商会会长', NULL, '任伪平城商会会长，为日军统制物资，强制商户低价出售粮食、布匹，从中牟利，资助伪军。', '山西大同_平城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a3e64c6809d75ed495cb8162dd55ba2e', 'fd0b174468f856638bd0fb256d267c93', 1937, '伪大同宣抚班班长', NULL, '任伪大同宣抚班班长，随日军进行“宣抚”活动，诱骗民众归顺，收集抗日情报，破坏群众抗日团体。', '山西大同_平城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f165edaa9347513ebe7ffc443aa2205e', '3c0cec769a465f2da5d9587d32cf51f4', 1937, '伪大同县知事', NULL, '日军侵占大同后出任伪大同县知事，协助日伪推行保甲制度，强征粮食物资，镇压抗日民众。', '山西大同_平城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7795d518aaac5130a44039d22d3077b6', '142ed91c1ea95b6d922d76d4627e2b83', 1937, '伪蒙古军政府副主席、伪大同省公署顾问', NULL, '原东北军将领，投日后参与组建伪蒙古军，后任伪大同省顾问，协助日军控制平城地区，参与“治安强化运动”。', '山西大同_平城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('59e053246b9b5c30acaa71b5518c55a9', 'f8128d92a5455f2886dae039c7903166', 1937, '伪晋北自治政府最高委员', NULL, '原阎锡山部将领，大同沦陷后投敌，任伪晋北自治政府最高委员，负责平城地区伪政权运作，配合日军清乡。', '山西大同_平城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8715bb81d3ed56b9af7c8247e311485f', 'cbf51e619442501987295265d484d416', 1938, '伪大同警察局局长', NULL, '任伪大同警察局长期间，积极搜捕抗日地下人员，破坏中共平城地下组织，协助日军推行“三光政策”。', '山西大同_平城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f21794fdd3ee524a93358e279d0e8cce', 'ada1dba9fdd65d1dabb791b4554d2450', 1939, '伪大同商会会长', NULL, '充当日伪经济汉奸，为日军统制平城地区物资，强征商户捐款，垄断粮食贸易，导致民不聊生。', '山西大同_平城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e697a2bf1438574fb62aaca22f64e696', '3c0cec769a465f2da5d9587d32cf51f4', 1937, '伪广灵县县长', NULL, '投靠日军后出任伪广灵县县长，协助日军推行“治安强化运动”，强征民夫修筑炮楼和公路，并组织伪警察所镇压抗日群众，曾配合日军扫荡南山抗日根据地。', '山西大同_广灵');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('79970d5b84b65662817c82a81f304b9b', '5220106099c25b7984d80c869672323e', 1938, '伪广灵县保安队队长', NULL, '原为地方土匪，后投降日军任伪保安队队长，率部多次袭击八路军游击队，杀害抗日干部和军属，并参与日军在广灵县西加斗、南村等地的“清乡”行动。', '山西大同_广灵');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('25db8289562750a28b6d9742fffc9127', '7236a25f5eb95a3896a8db1a77923567', 1939, '伪广灵县警察所所长', NULL, '任伪警察所长期间，积极为日军搜集情报，抓捕抗日地下党员，并参与建立“保甲制度”，强迫村民领取“良民证”，多次带队搜查抗日物资。', '山西大同_广灵');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c9deb937b5fe590b87ad038bc3849859', '1ddf042d8a9d5fcdac2e82958f641fd3', 1940, '伪广灵县新民会会长', NULL, '负责在广灵推行奴化教育，组织“新民会”宣传“中日亲善”，强迫学校使用伪满教材，并动员青年参加伪军，协助日军进行经济掠夺。', '山西大同_广灵');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d4bba1e07e4c5346bef2cfd781d2e2d7', '8320e3e3065f5f31a864a1fd27201ca3', 1938, '伪广灵县财政科科长', NULL, '为日军征收各种苛捐杂税，包括“亩捐”“门牌捐”等，并负责为日军筹办粮秣，曾强行征收民间粮食和牲畜，导致当地百姓生活极度困苦。', '山西大同_广灵');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c8081059d965577da18e88f95ce2bb54', '359f67e3978f550ebc17a547be54484a', 1941, '伪广灵县警备队副队长', NULL, '率警备队配合日军在广灵县东部山区“扫荡”，烧毁村庄多处，并参与杀害八路军伤病员和抗日群众，1943年在暖泉镇附近伏击抗日游击队。', '山西大同_广灵');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('86ea3e994aa85490816942654d0c6755', '9b0436fb47615db386551fba69ea63bb', 1937, '伪广灵县翻译官', NULL, '为日军驻广灵部队担任翻译，多次参与审讯抗日志士，并利用翻译身份敲诈勒索百姓，曾向日军告密导致多名地下党员被捕牺牲。', '山西大同_广灵');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e3ab92da25d6595eb72d65ae5b26934c', '180f029f9ed45d05ba59896812097128', 1937, '伪广灵县维持会会长（初期）', NULL, '日军占领广灵后率先组织维持会，为日军筹集粮款、提供向导，并协助日军建立伪政权，后调任伪大同县公署任职。', '山西大同_广灵');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2cf7bd8fabee56848723add77604a5a4', '57214b348cec5d359040630a87a35553', 1942, '伪广灵县特务队队长', NULL, '专门负责刺探八路军情报，带领特务队破坏抗日交通线，曾抓捕并杀害抗日村长数人，其特务队以手段残忍著称。', '山西大同_广灵');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2fd6c5b6673f521b86c74d6c447629d5', '51f0abc8d3385972b33046822359065a', 1938, '伪广灵县商会会长', NULL, '为日军控制广灵商业，强迫商户向日军“献金”，并垄断食盐、布匹等物资供应，从中牟利，同时为日军收购军需物资。', '山西大同_广灵');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3a00081c5d4a52da82fb53d96bb863d4', '3c0cec769a465f2da5d9587d32cf51f4', 1937, '伪广灵县知事', NULL, '日军侵占广灵后出任伪县知事，协助日军推行“治安肃正”，强征民夫修筑碉堡公路，并组织伪警察队镇压抗日群众。', '山西大同_广灵');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('abc180f7543b5e4680cc7453a2e95d65', '27c84878572e5361a427d9981c30abbf', 1938, '伪广灵县保安队队长', NULL, '率伪保安队多次配合日军扫荡南山抗日根据地，抓捕并杀害抗日干部和群众，抢劫粮食物资。', '山西大同_广灵');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c8701663f2a35cf48b4ca634fbe1d53b', '7236a25f5eb95a3896a8db1a77923567', 1939, '伪广灵县新民会会长', NULL, '负责在广灵推行奴化宣传，组织“新民会”分会，强迫民众参加“反共”集会，收集抗日情报供日军使用。', '山西大同_广灵');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6e700394a92d59ef846a34ea5d62134b', '2afacc26d5e95d5f89e96f3404f7e387', 1940, '伪大同省公署参事兼广灵县联络员', NULL, '作为日伪大同省与广灵之间的联络人，参与策划“铁壁合围”扫荡，并协助日伪军建立保甲制度，实行连坐。', '山西大同_广灵');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('137a8ebe3bdb51a78221f463a17c8b2c', '142ed91c1ea95b6d922d76d4627e2b83', 1937, '伪蒙古军总司令、伪大同省省长', NULL, '原为土匪出身，投靠日军后任伪蒙古军总司令，1939年任伪晋北自治政府（后改大同省）最高顾问，后任伪大同省省长，协助日军推行“治安强化运动”，镇压抗日力量，强征劳工，掠夺大同煤炭资源。', '山西大同_新荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('23d03ff8e000586b94208d10e8b88d79', 'bc30a098483b5d089fb9d8e46c9211df', 1937, '伪晋北自治政府主席', NULL, '原为大同商会会长，日军侵占大同后出任伪晋北自治政府主席，积极为日军筹粮筹款，组织伪警察协助日军清乡，迫害抗日军民。', '山西大同_新荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ee0836a3e5e05454a293e77f884707c0', 'aebcd1f95096575f87caee184ef0e603', 1938, '伪大同县知事、伪大同省民政厅长', NULL, '历任伪大同县知事、伪大同省民政厅长，推行保甲制度，强征壮丁，配合日军“三光政策”，在新荣地区多次组织伪军扫荡抗日根据地。', '山西大同_新荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d446368c3db755cdaf740cd5767792fa', '663db8b222185e65916a5b94545a578e', 1939, '伪大同省警务厅长', NULL, '负责伪大同省警察系统，协助日军建立特务情报网，在新荣区及周边村庄抓捕抗日干部和群众，刑讯逼供，杀害多名抗日志士。', '山西大同_新荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a49e6cf3355b505186e753bf1be3479a', '27c84878572e5361a427d9981c30abbf', 1940, '伪大同省保安队司令', NULL, '指挥伪保安队配合日军对新荣山区抗日游击队进行多次“围剿”，烧毁村庄，掠夺财物，残害百姓。', '山西大同_新荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('768cfe0f12735c8cba5b8775485a0a70', 'f8128d92a5455f2886dae039c7903166', 1941, '伪大同省参议长（投敌后）', NULL, '原晋军将领，被俘后投敌，任伪大同省参议长，为日军出谋划策，劝降抗日武装，协助建立伪政权基层机构。', '山西大同_新荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f778b669449b5a11b53005b529142da3', 'a101512bf69455ea94f0a94fa807662e', 1938, '伪新荣区维持会会长', NULL, '在新荣地区（今新荣区）组织维持会，为日军征收粮税，提供情报，强迫村民修炮楼、修公路，多次带领日军袭击八路军小分队。', '山西大同_新荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eb38f34f7f5e5b7c90e78c575c8ef8f7', 'ae5556612a955d3bbb0ec62284038da2', 1939, '伪大同县保安团团长', NULL, '率伪保安团驻守新荣一带，参与“清乡”行动，杀害抗日军属，抢劫民财，强抓民夫，罪行累累。', '山西大同_新荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('30c51caed864533d9dfa15c709035087', 'f5fe59e9e13854cbb87a474a95350c50', 1940, '伪大同省特务机关长（汉奸特务）', NULL, '为日军宪兵队效命，在新荣地区发展特务网络，破坏地下抗日组织，逮捕并杀害多名共产党员和进步人士。', '山西大同_新荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1845928e28b452dc9a7e627fd02ebe4d', '5ba9b438aa8057fe971e7bd39b052daf', 1938, '伪大同省财政厅长', NULL, '负责为日军搜刮民财，强征各种苛捐杂税，在新荣地区逼死多名交不起税的农民，并参与鸦片专卖毒害百姓。', '山西大同_新荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f1d71b3b3f8d546b8e7fbea1c465fe03', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令', NULL, '原东北军将领，后投靠日军，在察哈尔、绥远及大同地区协助日军进攻抗日武装，建立伪蒙古政权，参与对晋北地区的殖民统治和物资掠夺。', '山西大同_新荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2585ee58bae053dda8d23830ce332dd5', '2b5378ecc56d5f4f84f06756e495b505', 1935, '伪大汉义军总司令', NULL, '原土匪武装头目，投日后在绥远、大同周边地区为日军充当鹰犬，多次配合日军扫荡抗日根据地，残害抗日军民。', '山西大同_新荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('faad912f60995ce3b61e27bd0515fe00', 'fd0e81b6bf6c52f2999b8497dbaf0a27', 1937, '伪大同县知事（县长）', NULL, '日军侵占大同后出任伪大同县知事，推行保甲制度，强征粮食劳役，协助日军镇压抗日活动，迫害爱国群众。', '山西大同_新荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6ccc4fdcbbce5fc6bc5fec379d1a379b', '27c84878572e5361a427d9981c30abbf', 1939, '伪大同省公署警务厅厅长', NULL, '负责伪大同省（辖今大同、新荣等地）警察特务系统，指挥汉奸警察抓捕抗日地下人员，破坏抗日组织，参与“治安强化运动”。', '山西大同_新荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('43c1c7da5a175bf3af7e668e2d25b6e4', 'f8128d92a5455f2886dae039c7903166', 1938, '伪晋北政厅顾问（后任伪山西省公署参议）', NULL, '原阎锡山部将领，投日后任伪晋北政厅顾问，协助日军管理大同及周边县政，为新荣等地区伪政权出谋划策，参与经济统制。', '山西大同_新荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bb248dfd1922525ebab49268030a4a62', '913193722a0f53b4a0057799caec9971', 1937, '伪浑源县县长', NULL, '投靠日军，任伪浑源县县长，协助日军推行‘治安强化运动’，强征民夫，搜刮粮食，镇压抗日群众。', '山西大同_浑源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('349a06d6c3b5584d96568ba6729ff7af', '142ed91c1ea95b6d922d76d4627e2b83', 1937, '伪蒙疆自治政府副主席、伪蒙古军总司令', NULL, '原东北军将领，后投日，在察哈尔、绥远及山西北部（含大同、浑源一带）配合日军进攻抗日武装，参与建立伪蒙疆政权，为日军提供兵力和情报。', '山西大同_浑源');
