INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e062f0302e7c563f8dd52613ca7bb7cc', 'bc30a098483b5d089fb9d8e46c9211df', 1937, '伪晋北自治政府主席（后并入蒙疆）', NULL, '原大同地方士绅，日军占领大同后出任伪晋北自治政府主席，管辖大同、浑源等县，为日军征收赋税、组织伪军。', '山西大同_浑源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('958e8344d83451aeadaf3594acc5313e', 'aebcd1f95096575f87caee184ef0e603', 1937, '伪大同县知事（后任伪蒙疆政府要职）', NULL, '投靠日军，历任伪大同县知事，在浑源等地推行保甲制度，抓捕抗日分子，强征劳工。', '山西大同_浑源');
