INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5bead97fd1c55f6faabd02e9b9d7b4d4', '3431dea1a2da51858cdd8b535b09e9da', 1937, '伪浑源县维持会会长', NULL, '日军初占浑源时出任维持会长，为日军筹集粮款，提供向导，帮助日军建立伪政权。', '山西大同_浑源');
