INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6aeb8f96663a557195e60728c5ecd018', '3a0537dcb964559cbe7de5f03f88f7c1', 1938, '伪代县自卫团团长', NULL, '组织地方自卫团，协助日军维持占领区秩序，参与“清剿”行动，杀害抗日民兵和群众。', '山西忻州_代县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('abd47217b4d35839a7c96f47b6b3932a', '7fc406b6c9185213a6a635dbf6786d6a', 1937, '代县伪县长', NULL, '日军侵占代县后出任伪县长，协助日军推行“治安强化运动”，强征粮税，镇压抗日群众。', '山西忻州_代县');
