INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b4f80800512252c797b9b9689b80ea4b', '4527552e23f9577f98000acd156fc0cf', 1938, '宁武县伪县长', NULL, '投靠日军，任宁武县维持会会长及伪县长，协助日军推行“治安强化”运动，强征民夫，搜刮粮食，镇压抗日群众。', '山西忻州_宁武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e496f89df8605cd39c542ab56b33be1f', '5b188d9f82c0563fbe03dbae02fbe2a6', 1939, '宁武县伪保安队队长', NULL, '组织伪保安队，配合日军扫荡抗日根据地，多次带队袭击八路军游击队，杀害抗日干部和群众。', '山西忻州_宁武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4b8a301874c959beb84ee965a62dbd08', '11075ec1248c514ba47cb733a311b2c2', 1940, '宁武县伪警察局局长', NULL, '效忠日军，建立伪警察体系，搜捕抗日地下党员，破坏抗日组织，参与“清乡”行动。', '山西忻州_宁武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('37538d306a6555c2af6d6ea021162df8', '00cabf19b9e4579fbb8cf12e85e3abc6', 1938, '忻州（忻县）伪县长', NULL, '任忻县伪县长期间，积极推行日伪政权法令，强征捐税，组织伪自卫团，协助日军建立据点，迫害抗日家属。', '山西忻州_宁武');
