INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0b81b2ea8543505b9c23ed65c7c9b614', '3d79a7a783f45001866c62be7cd7fa6a', 1940, '忻县伪警察所所长', NULL, '负责忻县城内特务工作，抓捕抗日进步人士，严刑逼供，向日军提供情报。', '山西忻州_宁武');
