INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5587166073565db5b463a40f1f943d2b', 'a7b8f25405b25aceb266e7ad8b9e9495', 1938, '宁武县伪维持会副会长', NULL, '日军占领宁武初期，积极组织维持会，为日军带路搜捕抗日武装，强派苦力修筑公路和碉堡。', '山西忻州_宁武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('19771ae160c6516dbfdf426ba0ef684b', '26f91554f5d75fd4ab63fd50c1ced47e', 1940, '忻县伪区公所区长（奇村一带）', NULL, '在日伪统治下，强征壮丁，催缴粮款，告密抗日活动，导致多名村民被日军杀害。', '山西忻州_宁武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7e20de8f34ac577cbbe2bf86e16f051c', 'e60d0335f96157edb58448797cda6ce0', 1941, '宁武县伪新民会会长', NULL, '负责在宁武推行奴化教育，组织“新民会”宣传亲日思想，破坏民众抗日情绪，协助日军建立“爱护村”。', '山西忻州_宁武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('55edb6568bef5d2e8501340da1afaa4e', '4527552e23f9577f98000acd156fc0cf', 1938, '伪宁武县知事', NULL, '任伪宁武县知事期间，协助日军推行‘治安强化运动’，强征民夫修筑碉堡公路，并组织伪警备队镇压抗日群众，曾配合日军扫荡抗日根据地，掠夺粮食资源供给日军。', '山西忻州_宁武');
