INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4dd79ab97c625ee7af25091251b07bee', '737529efae90581dbb63ec770ab8f6c3', 1939, '伪宁武县新民会会长', NULL, '负责在宁武推行奴化教育，宣传‘中日亲善’，组织汉奸团体刺探抗日情报，并协助日军建立保甲制度，强化殖民统治。', '山西忻州_宁武');
