INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e784ba7679ac5caf8f172813a9e42b78', '737529efae90581dbb63ec770ab8f6c3', 1941, '静乐县伪新民会会长', NULL, '在静乐推行奴化教育，组织“新民会”宣传“中日亲善”，强迫民众参加反共集会，收集抗日情报提供给日军特务机关。', '山西忻州_静乐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ba3eb5b667965b74a7efaae0caf7d55c', 'f5fe59e9e13854cbb87a474a95350c50', 1942, '静乐县伪区公所区长（康家会区）', NULL, '为日军征收粮款，强抓壮丁补充伪军，曾向日军告密导致康家会村多名抗日积极分子被杀害。', '山西忻州_静乐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9efdda4244de5f1ea28a2a828e047776', 'e221ec8121d150ae9ee3db1429fdbe4c', 1940, '静乐县伪自卫团团长', NULL, '组织伪自卫团协助日军守备据点，参与“清乡”行动，在静乐北部山区烧毁民房，抢劫百姓财物。', '山西忻州_静乐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8f4ded2565ef5ff9bf4d614ed4efb862', '09079d2052f4508881896aca18db3714', 1939, '静乐县伪税务局长', NULL, '为日军推行“以战养战”政策，增设苛捐杂税，强征商业税和土地税，导致商户和农民破产，并将所得款项直接供给日军军需。', '山西忻州_静乐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c0badc767a5959528b9cdc248750fd48', '57467a8918295140bf59dbcd24e55bb5', 1941, '静乐县伪警备队中队长', NULL, '率伪警备队多次袭击八路军游击队驻地，在娄烦、静乐交界处设伏，杀害抗日战士及民兵共十余人。', '山西忻州_静乐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d051481eb566553e99805d55380fd9d2', 'ac23691e1eff574daa6c8b6dd43285c7', 1938, '静乐县伪维持会副会长', NULL, '日军初占静乐时率先投敌，协助日军建立维持会，为日军带路寻找抗日武装藏身点，致使多处秘密粮仓被毁。', '山西忻州_静乐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9fb68e3f40c65be9bc1d0c6eae0c13fc', '706f573e84a55602b5524be304cca94e', 1942, '静乐县伪教育科长', NULL, '强制推行日伪教材，删除中国历史内容，强迫学校悬挂日本国旗，并检举有爱国言论的教师，导致多名教师被捕。', '山西忻州_静乐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1af28a8b43ac599f849ca737ad5734a8', 'f223b1b5966f5fcba005351202deb598', 1938, '伪静乐县知事', NULL, '投靠日军后任静乐县伪知事，协助日军推行“治安强化运动”，强征民夫修筑碉堡，搜捕抗日军民，并强迫百姓领取“良民证”。', '山西忻州_静乐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5bf5108f2fb550de831b10261492c58c', '6cf10d4aa7945cc0b66d83616709e0c5', 1940, '伪静乐县保安队队长', NULL, '率伪保安队多次配合日军扫荡静乐抗日根据地，杀害抗日干部和群众，抢劫粮食，烧毁村庄，罪行累累。', '山西忻州_静乐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4679bf417222518cb5f30dff6e23a46a', '6f751e18423658f9ab3bd9eec482adb9', 1941, '伪静乐县警察所所长', NULL, '为日军搜集抗日情报，抓捕地下党员和进步群众，严刑逼供，并参与“清乡”行动，破坏抗日组织。', '山西忻州_静乐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e9e907c31cf95e629ac7799efc10d449', '00cabf19b9e4579fbb8cf12e85e3abc6', 1942, '伪静乐县新民会会长', NULL, '积极推行奴化教育，组织“新民会”宣传亲日思想，诱骗青年参加伪军，并协助日军征粮派款，压榨百姓。', '山西忻州_静乐');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('424cce0d3f295c1e90a21350864a5e9c', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '投靠日军，出任伪山西省省长，推行奴化教育，协助日军掠夺山西资源，镇压抗日活动。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9ca8b1000d6f5696981844c9f084efda', '2b38113bed725cedaecdd9dc8d6365ec', 1938, '伪山西省公署顾问', NULL, '曾任阎锡山部属，后投敌，为日军提供山西军政情报，参与组建伪政权。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ce011312f16f5f1b85e358a89b84e34e', 'a58cb96088d85d5893faba30b3d9c994', 1937, '伪山西省维持会会长（早期）', NULL, '太原沦陷后参与组织维持会，协助日军稳定占领区秩序，后因内部矛盾被日军弃用。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b3a087278068550b97bf820ad2856384', 'f0a05b45394f5fcf9e2d9b7b4cbf4e5d', 1937, '伪晋北自治政府主席', NULL, '在大同地区成立伪晋北自治政府，配合日军“以华制华”政策，征收苛捐杂税，强征劳工。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4dc949c9f8415ed083053fcd660005ff', 'bc30a098483b5d089fb9d8e46c9211df', 1937, '伪晋北自治政府副主席', NULL, '协助梁上椿管理伪政权，参与镇压大同煤矿工人反抗，为日军提供煤炭资源。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('787ee9e1ae1f525fa03a3cfdbd892d7d', 'b0d4333d37d65ff0bfa25d9f37623ae1', 1939, '伪晋中道尹', NULL, '任伪晋中道尹期间，推行保甲制度，强征民夫修筑公路和碉堡，协助日军清乡扫荡。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('225c54cc1af356498b90248a3d0fc2f1', '7a4d595c479e5af792f43dfe435fb25b', 1940, '伪晋中保安司令', NULL, '组织伪保安队，配合日军围剿八路军游击队，杀害抗日军民，掠夺粮食。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1f6337e1882e5be5992607031334d2ea', '36291946c2a055ef95a843efb1461a1b', 1939, '伪太原绥靖公署参议', NULL, '原晋军将领，投日后为日军策划“治安强化运动”，在晋中地区建立情报网。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7af6c57afaeb5053b0971e4e9b0c4a14', '627600350a805bcba587366083b75195', 1941, '伪晋中清乡委员会主任', NULL, '负责晋中地区清乡行动，屠杀抗日群众，烧毁村庄，被日军授予“功勋”称号。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('66fcbf2b70115128953bad3828010786', 'f223b1b5966f5fcba005351202deb598', 1942, '伪山西剿共军第一军军长', NULL, '率伪军参与“铁壁合围”扫荡，在晋中平川多次袭击八路军，制造无人区。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eebc84b4793b5ca89b339505e2c47c4c', 'f8128d92a5455f2886dae039c7903166', 1943, '伪山西保安副司令', NULL, '原晋绥军将领，投敌后负责训练伪军，在晋中各县建立伪警察所，镇压抗属。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1813f9229b5f540e88a410b61c80fa4b', 'b5b29d4e25db5f6db06c7cb4fd7ab546', 1940, '伪晋中经济统制局局长', NULL, '垄断晋中粮食、棉花贸易，强制低价收购农产品，供应日军军需，导致民众饥荒。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('54c05793dcbd58cf84f7d77e510c4236', '795d54b643a854aab552b777ecb072fb', 1939, '伪山西新民会总干事', NULL, '在晋中推行“新民会”宣传，组织青少年奴化教育，破坏抗日群众组织。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9243b191566c5e5997a00436b676f46b', 'a4cb751ad6845d2a9bac0e35b76c372c', 1941, '伪晋中特务机关长', NULL, '为日军搜集晋中抗日武装情报，逮捕地下党员，酷刑审讯，杀害多名爱国志士。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('54950896c5975e7d95ee4dfda851f9d1', '153310fe23185f0ca1018c325e83762c', 1938, '伪山西省财政厅长', NULL, '为日军征收田赋、摊派军费，在晋中各县强征“慰劳金”，中饱私囊。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a07f14a218f8580c8aed021555b879b3', '0dce8b353ad1501e8bb6c2199bce5f5d', 1938, '伪山西宣抚使', NULL, '负责对晋中民众进行“宣抚”，诱降抗日分子，破坏抗日统一战线。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('93cf60100312544c97091700693a1d35', '7cb391898b59555e89984b74a94e7d18', 1940, '伪华北政务委员会山西分会委员', NULL, '虽名义居北平，但参与策划晋中伪政权运作，协助日军推行“治安肃正”。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('192a3d0fad4c5b1ab4c213638277ed37', '31d200721992579e8bb8f5bbb914f497', NULL, '', NULL, '', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('424cce0d3f295c1e90a21350864a5e9c', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '曾任阎锡山部将领，投日后任伪山西省长，推行日伪政权统治，协助日军在晋中地区进行“治安强化”和物资掠夺。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dc09bf46844556dbbad146fe1aaf236d', '2b38113bed725cedaecdd9dc8d6365ec', 1940, '伪晋中道尹', NULL, '任伪晋中道（驻榆次）道尹，负责晋中各县伪政权管理，配合日军清乡、征粮，镇压抗日力量。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('932e1fd061f754da8286b1547c743067', 'f0a05b45394f5fcf9e2d9b7b4cbf4e5d', 1939, '伪山西公署顾问/汉奸', NULL, '晋中祁县人，曾任伪山西省公署参事，参与组织“新民会”在晋中活动，为日军搜集情报并推行奴化教育。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7d6d97cbf8315d8f9509cea0e86f1fd7', 'f8128d92a5455f2886dae039c7903166', 1941, '伪晋绥军投日将领（后反正）', NULL, '原晋绥军将领，1941年中条山战役后一度投日，在晋中地区协助日军收编散兵，后于1942年反正归队。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b86af0593b3a54cd983eee56d9239c9c', 'f223b1b5966f5fcba005351202deb598', 1943, '伪“山西剿共军”指挥官（争议）', NULL, '原阎锡山部将领，抗战后期与日军秘密勾结，在晋中地区配合日伪军进攻八路军，但名义上未公开投敌，史料中列为“通敌”人物。', '山西晋中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0eaa9ac00c4a5119ae43698bed1bdb03', '2b5378ecc56d5f4f84f06756e495b505', 1938, '伪山西省公署顾问、伪晋中道尹', NULL, '投靠日军后任伪职，协助日伪在晋中地区推行“治安强化”运动，镇压抗日力量，强征民夫与粮食，破坏抗日根据地', '山西晋中_和顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('25cfcd9ec14a5a809ac61f28133dea6f', 'f8128d92a5455f2886dae039c7903166', 1941, '伪山西保安副司令（后投敌）', NULL, '原晋绥军将领，被俘后变节投日，参与组建伪军，在晋中、和顺一带配合日军“扫荡”，残害抗日军民', '山西晋中_和顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5550d7ffe7ed58fcb6f9b381bef3d056', 'eb30ef64b60d52fdbba910bc5475ca42', 1940, '伪和顺县保安队队长', NULL, '原土匪出身，投日后任和顺县伪保安队长，多次带队袭击抗日游击队，杀害抗日干部，强征百姓财物', '山西晋中_和顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('14fa6857809054808b5b13b831ba41a8', '142ed91c1ea95b6d922d76d4627e2b83', 1937, '伪蒙古军总司令（曾涉晋中）', NULL, '虽主要活动于绥远，但曾率伪蒙古军配合日军进犯晋中地区，参与对和顺等地的军事“讨伐”，烧杀抢掠', '山西晋中_和顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ccca8539f2d7539ea85d483775678ceb', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '作为伪山西省最高行政长官，统辖包括晋中、和顺在内的伪政权，推行奴化教育，强征劳工，支持日军经济掠夺', '山西晋中_和顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('582eda9f99de5992a66bf5dc1cfe7c10', '26bc6327b99951a39c4ac15c7d966a86', 1937, '太谷县伪县长', NULL, '投靠日军，任太谷县维持会会长及伪县长，协助日军推行“治安强化运动”，强征粮税，镇压抗日群众。', '山西晋中_太谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8444f633b6235a00b71737a4a3e6e563', 'ae439c952b755ce79276f3910133a3a2', 1938, '太谷县伪保安队队长', NULL, '率伪保安队配合日军扫荡抗日根据地，抓捕抗日干部和群众，制造多起惨案。', '山西晋中_太谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('673ebecdd1b254e097f7e82252495801', '4509ed01400755b79ca0f020d04a32c0', 1940, '晋中伪道尹公署顾问', NULL, '原太谷士绅，后任伪晋中道尹公署顾问，为日军出谋划策，参与经济掠夺和“清乡”行动。', '山西晋中_太谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6184c11b551d5aab9c16358e0688d8fa', 'df1b4b5bc00b5eb78ad25b02464e329c', 1939, '太谷县伪警察局局长', NULL, '组织伪警察协助日军搜捕抗日分子，破坏地下交通线，残害进步人士。', '山西晋中_太谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c8834aaa3cd852b085c601e132fdadcd', 'be4eaecc9af056e787d52f2319a57fdc', 1941, '太谷县伪新民会会长', NULL, '推行奴化教育，宣传“中日亲善”，强迫民众参加反共集会，搜集抗日情报。', '山西晋中_太谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('92ee68a85a945484907da5d9e0633785', '7236a25f5eb95a3896a8db1a77923567', 1942, '晋中伪军暂编第10团团长', NULL, '率伪军驻防太谷、祁县一带，多次袭击八路军游击队，杀害抗日家属，抢掠百姓财物。', '山西晋中_太谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0dbf9bee26e952c8a0cf284712633521', 'fdc924a005d9538a8da27a0094bf8f69', 1938, '太谷县伪税务局局长', NULL, '为日军征收各种苛捐杂税，强征粮食和棉花，导致百姓负担沉重，部分物资被转运至日军军需。', '山西晋中_太谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4c1a28a58eb7599ebb19a59764fc8079', '1c453faf99415eb1b645e6b61e75b4d3', 1937, '太谷县伪维持会副会长', NULL, '日军占领太谷初期，协助建立维持会，为日军提供当地情报，并组织“宣抚班”诱降抗日人员。', '山西晋中_太谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('626ec379b0d05ad3bc56e86a8417f221', '17d5a2945846565abdb11e3f8c815240', 1940, '太谷县伪区公所区长', NULL, '管辖太谷多个伪区，强迫青壮年充当伪军，配合日军修筑炮楼和封锁沟，破坏抗日根据地。', '山西晋中_太谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a52b5fb6210059fca8c75fc69780cc69', '5add00735cda57e18d23a44f4cf685a0', 1943, '晋中伪保安司令部参谋', NULL, '参与策划对太谷南山抗日根据地的“铁壁合围”，提供兵力部署建议，导致多名抗日战士牺牲。', '山西晋中_太谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('582eda9f99de5992a66bf5dc1cfe7c10', '26bc6327b99951a39c4ac15c7d966a86', 1937, '太谷县伪县长', NULL, '日军占领太谷后出任伪县长，协助日军推行“治安强化”运动，强征粮税，镇压抗日群众。', '山西晋中_太谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a583f4ee58765596aa637149cebf4f09', 'd68c6ed8ce0b5d538532a0f19242a2ed', 1938, '太谷县伪保安队队长', NULL, '率伪保安队配合日军扫荡抗日根据地，抓捕抗日军民，烧毁村庄，民愤极大。', '山西晋中_太谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('07fb07e8b55356ea9db0ab9187448895', 'ae439c952b755ce79276f3910133a3a2', 1940, '晋中地区伪警备队副队长', NULL, '在太谷、祁县一带活动，多次带伪军袭击八路军游击队，杀害抗日干部，抢夺物资。', '山西晋中_太谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d588698605075199811e2604cf573a9d', '77b3e5f877bc5245b2b68373f7c53f58', 1937, '太谷县伪维持会会长', NULL, '日军初占太谷时组织维持会，为日军筹集粮款，提供情报，帮助建立伪政权。', '山西晋中_太谷');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a0bbdff539da52b39da3dc105ba3f6bb', '2307c9b62e84544eb9cffe1d95846ae0', 1937, '寿阳县伪县长', NULL, '投靠日军，任寿阳县维持会会长及伪县长，协助日军推行“治安强化”运动，强征民夫，搜刮粮食，镇压抗日群众。', '山西晋中_寿阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a3186b231af454e590b5be3ce3135f22', 'f8128d92a5455f2886dae039c7903166', 1938, '伪晋中道尹（后投敌）', NULL, '原晋绥军将领，后投降日军，任伪晋中道尹，管辖寿阳等县，配合日军扫荡，组织伪警备队，破坏抗日根据地。', '山西晋中_寿阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('52a4ef96cb225c7185ef68b64e4ebc38', 'a101512bf69455ea94f0a94fa807662e', 1939, '寿阳县伪保安队队长', NULL, '组建伪保安队，多次配合日军袭击寿阳抗日游击队，抓捕抗日干部，并参与“清乡”行动，残害百姓。', '山西晋中_寿阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('71301d13d15d5c8d9612b988f87ea54a', '737529efae90581dbb63ec770ab8f6c3', 1940, '寿阳县伪警察局局长', NULL, '任伪警察局长期间，协助日军建立情报网，侦捕地下党员，参与制造多起屠杀事件，强征劳工送往东北。', '山西晋中_寿阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d467c21070305d5ebae2fdbd65da442f', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '投靠日军，任伪山西省公署省长，推行奴化政策，协助日军镇压抗日力量，征收苛捐杂税，迫害抗日军民。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7b3ee04f37275e29a0a9425e79f2a00f', '2b38113bed725cedaecdd9dc8d6365ec', 1938, '伪山西省警务厅厅长', NULL, '主持伪省警务，组织伪警察协助日军“扫荡”，抓捕抗日人士，破坏地下抗日组织。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('87a57411f4ee5523847856c92e9dbae9', 'f0a05b45394f5fcf9e2d9b7b4cbf4e5d', 1938, '伪山西省财政厅厅长', NULL, '为日军搜刮民财，推行伪币，控制经济命脉，资助伪军和特务活动。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('704d9186a1d25ee58c7e85a20a8441c7', '7a4d595c479e5af792f43dfe435fb25b', 1938, '伪山西省教育厅厅长', NULL, '推行奴化教育，篡改历史教材，强迫学生效忠日本天皇，破坏中国传统文化教育。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2bb955b3f01f5e53a6b0837b5c582f22', '8bc90a26340654668e4b6fc91a09c218', NULL, '', NULL, '', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e00b8aee46fe53c9aac7b8e54af2d256', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令（活动涉及晋北）', NULL, '率伪蒙军配合日军进攻山西，在晋中、左权周边地区参与“扫荡”，屠杀抗日军民。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('72619a09bbe1530c8e34bb024a4f8664', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西联军总司令（活动涉及晋西）', NULL, '率伪军骚扰晋西、晋中地区，为日军充当帮凶，劫掠百姓，袭击抗日武装。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c21627c75e3657c5a8326d94d9550737', 'eb30ef64b60d52fdbba910bc5475ca42', 1939, '伪雁北挺进队司令（活动涉及晋北）', NULL, '盘踞雁北，多次配合日军进攻晋中根据地，残杀抗日干部和群众，制造多起惨案。', '山西晋中_左权');
