INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('61ddd9794bfd5321a4b271fe49c8dcdd', '4dc1ca7c2e5d59e298c97f16fa6e4303', 1941, '伪山西剿共军第1师师长', NULL, '率伪军驻防晋中，多次进攻左权县抗日根据地，参与“铁壁合围”大扫荡，杀害八路军伤员。', '山西晋中_左权');
