INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('caeefdc8615e5f6484b17d673138bc07', 'b4c379b6c4ff594eb5d1bd4e4a87483c', 1944, '伪左权县特务', NULL, '向日军报告左权县被服厂位置，导致被服厂被毁。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('aa45dad4bb8d5625b52e97f11f97799f', '2bb00044e7e3530bbb3a684946b0bf34', 1943, '伪左权县保安队队员', NULL, '参与“清乡”时抢劫百姓财物，并殴打老人。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bf02c6011a415a0d81716b7e48a707db', '12d5865ea83d5413ac977e2f3894dcf5', 1944, '伪左权县密探', NULL, '侦察八路军骑兵队动向，导致骑兵队遭伏击，损失战马。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8dd4223712c55a1abcc28bc8b5286ebf', '61f0973e8d9b568192aa35d25a3473e6', 1943, '伪左权县维持会翻译', NULL, '为日军翻译，故意歪曲供词，导致无辜村民被杀害。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('883ac970f82855cf994ee883ce5337bd', '951fed4bf8e75d88867947cfca56c9c0', 1944, '伪左权县警备队副班长', NULL, '参与杀害左权县抗日村长，并放火烧毁其房屋。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('19e9b2f9be4953419bd1f935f42259ca', '0424a86909215ee598786324eecaa3cd', 1943, '伪左权县便衣特务', NULL, '混入抗日群众中，指认积极分子，导致4人被捕。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('646158f144705f168534f2666e74df9f', '1153d4bb8d2f5918a901b67172b175a1', 1944, '伪左权县保安队队员', NULL, '参与“扫荡”左权县羊角村，杀害群众1人，抢走牲畜。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('aa66dcee39ea52b3a46ef35efad56c01', 'f6b6f6d793135fd38df564323d5118df', 1943, '伪左权县密探', NULL, '报告八路军医院转移路线，导致医院遭袭，伤员伤亡。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d467c21070305d5ebae2fdbd65da442f', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '曾任伪山西省公署省长，推行日伪政权统治，协助日军在山西各地（含晋中、左权周边）进行清乡和物资掠夺。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a68a5a77bf6c5ae69c2c1eef49d185f5', '2b38113bed725cedaecdd9dc8d6365ec', 1939, '伪山西省公署顾问', NULL, '作为日伪山西省政府高级顾问，参与策划对太行山区（含左权县）的扫荡行动，并协助日军建立伪政权和情报网。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e19389f291575ac5991612db2761886c', 'f0a05b45394f5fcf9e2d9b7b4cbf4e5d', 1937, '伪晋北自治政府最高委员', NULL, '在晋北地区（与晋中、左权有联系）组织伪政权，配合日军进攻山西抗日根据地，曾参与对左权县周边地区的军事围剿。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fbdd992242f55ab6b7a18de0904425f7', 'f8128d92a5455f2886dae039c7903166', 1941, '伪山西保安司令部副司令', NULL, '原晋绥军将领，后投敌任伪职，在晋中地区组织伪保安队，协助日军镇压抗日力量，多次参与对左权（原辽县）根据地的破坏行动。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4386469374ca5a44b9b77d0d805d1fd4', '142ed91c1ea95b6d922d76d4627e2b83', 1936, '伪蒙古军总司令（活动涉及山西）', NULL, '虽以察哈尔、绥远为主，但其伪军部队曾配合日军在山西东部（含晋中、左权一带）进行扫荡，烧杀抢掠。', '山西晋中_左权');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('657dc93745a55080b0163962210f401f', 'f8128d92a5455f2886dae039c7903166', 1937, '伪山西省公署顾问、伪晋中地区维持会头目', NULL, '原晋绥军将领，投日后任伪职，协助日军在晋中平遥一带推行‘治安强化运动’，组织伪军配合扫荡，残害抗日军民。', '山西晋中_平遥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('73b6d6adf9ea51c286a73240a002c85a', '893a5a0c549b5d46a9901248f7c35e96', 1938, '伪平遥县知事（县长）', NULL, '任伪平遥县知事期间，强征粮税，建立伪警察所，抓捕抗日地下人员，向日军提供情报，破坏平遥抗日根据地。', '山西晋中_平遥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5ce0d1c3aaa156379cdf3a0ef0e292bf', '17d5a2945846565abdb11e3f8c815240', 1939, '伪平遥县保安队队长', NULL, '率伪保安队多次袭击平遥县抗日游击队，杀害抗日干部，参与日军‘三光’政策行动，烧毁村庄数十个。', '山西晋中_平遥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('505b000ebba754ada99f38deeae69831', '7d1cf2dd80e35b6688633dfcb3f7f3d8', 1940, '伪山西省警务厅厅长（兼管晋中）', NULL, '原阎锡山部属，投日后主管伪警务，在晋中平遥设立多个特务据点，指挥伪警宪特搜捕抗日分子，制造多起惨案。', '山西晋中_平遥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1f4550a04fcd53d8a7bce99d63fb8641', '7987b939a2f5512296c45c13c7af807a', 1938, '伪晋中道尹公署参议', NULL, '为日军出谋划策，参与组建平遥、介休等地伪维持会，协助日军建立‘爱护村’，强迫村民报告八路军动向。', '山西晋中_平遥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4c942b58f624525eaa665ee1616d3013', '52d5204841145ace9f131a41c859c9cb', 1939, '伪平遥县新民会会长', NULL, '主持平遥新民会，推行奴化教育，组织‘青年训练班’，诱骗青年为日军服务，并搜集抗日情报上交日军宪兵队。', '山西晋中_平遥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('872c07524d695aaf92965a0d26630795', '7401837a0aec54c6bd9e0cc79da674d4', 1941, '伪平遥县警备队副队长', NULL, '率警备队配合日军‘铁壁合围’，在平遥东南山区搜捕八路军伤病员，杀害群众20余人，抢劫牲畜粮食。', '山西晋中_平遥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('13e71f5952fe59f191313a4c69cca5e3', '26f91554f5d75fd4ab63fd50c1ced47e', 1942, '伪晋中剿共自卫团团长', NULL, '组建自卫团，在平遥、祁县交界处设卡盘查，多次伏击抗日运输队，将抓获的抗日人员押送日军太原工程队。', '山西晋中_平遥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('157b1ec523ea5675b3b94d96ef6eac8a', '945ae1b8fd815a5186188783c92f9adf', 1938, '伪平遥县财政科科长', NULL, '为日军征收‘地亩捐’‘门户捐’，强征民间铜铁，导致平遥百姓负担沉重，并贪污伪政权款项中饱私囊。', '山西晋中_平遥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5296dea1ff3959f691cf2fcd2c1bda30', '161450f780e65c149df443c6651f63bb', 1940, '伪平遥县特务队队长', NULL, '专门负责侦缉抗日地下党，曾率特务队突袭平遥城内秘密联络点，逮捕地下党员7人，其中4人被日军处决。', '山西晋中_平遥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2e647d0ca47a5b228e0a6dd9df93db66', '2b5378ecc56d5f4f84f06756e495b505', 1938, '伪平遥县知事', NULL, '日军占领平遥后出任伪县长，协助日军推行“治安强化运动”，强征民夫修筑碉堡公路，搜刮粮食资敌，镇压抗日群众。', '山西晋中_平遥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5ce0d1c3aaa156379cdf3a0ef0e292bf', '17d5a2945846565abdb11e3f8c815240', 1939, '伪平遥县保安队队长', NULL, '率伪军多次配合日军扫荡平遥抗日根据地，杀害抗日干部和群众，制造多起惨案。', '山西晋中_平遥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1ed6cd5e0cfc5a31b8d54ae9f2bf88cd', 'f0baa384725151ad9fb99cef1a20fe7c', 1940, '伪平遥县警察所所长', NULL, '效忠日军，破坏地下抗日组织，逮捕并刑讯逼供抗日志士，提供情报协助日军突袭。', '山西晋中_平遥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('381d58dee5ee52bdb08bc7de11cc9c0f', '72c0f683a2a65b1cbabefdaed63f3708', 1941, '伪晋中道道尹（辖平遥）', NULL, '作为伪山西省公署任命的晋中地区最高汉奸官员，督导各县伪政权，推行日伪经济掠夺和保甲制度，强征壮丁。', '山西晋中_平遥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('31b8300e510257a0875f1ab2b3809ded', '2b5378ecc56d5f4f84f06756e495b505', 1938, '伪昔阳县知事', NULL, '投靠日军，任伪昔阳县知事，协助日军推行‘治安强化运动’，强征民夫，搜刮粮食，镇压抗日群众。', '山西晋中_昔阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0b8c52c819ea56fbb053b1b17120d4b5', '142ed91c1ea95b6d922d76d4627e2b83', 1939, '伪昔阳县保安队队长', NULL, '组织伪保安队，配合日军扫荡抗日根据地，多次带队袭击八路军游击队，杀害抗日干部和群众。', '山西晋中_昔阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('710f77976fe058e5ab48e1a51635602b', 'be4eaecc9af056e787d52f2319a57fdc', 1940, '伪昔阳县警察局局长', NULL, '任伪警察局长，抓捕抗日地下党员，严刑逼供，破坏抗日组织，向日军提供情报。', '山西晋中_昔阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('365b13347189595893f06f4f6d2e3e3b', 'a4c1d2ff3ae25c6fb9a6cc84c43413d9', 1941, '伪晋中道尹公署顾问（昔阳籍）', NULL, '作为昔阳籍汉奸，在伪晋中道任职，参与策划‘清乡’行动，协助日军在昔阳一带建立伪政权。', '山西晋中_昔阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('07dab7be1368504aaf7ce70b65a94ad1', '26f91554f5d75fd4ab63fd50c1ced47e', 1938, '伪昔阳县维持会会长', NULL, '日军占领昔阳后出任维持会长，为日军筹集粮款，强征劳役，并告密导致多名抗日群众被捕。', '山西晋中_昔阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c34e8764c4db530e886ab25084516a68', '25e59baf651353e2b38dfc322fb650ec', 1940, '伪昔阳县新民会会长', NULL, '负责在昔阳推行奴化教育，组织‘新民会’宣传亲日思想，强迫群众参加反共集会。', '山西晋中_昔阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1f86b33a7c1d5326b0d094afdcdf1545', 'c73fd813480653559ada941382fd4b24', 1942, '伪昔阳县警备队副队长', NULL, '率警备队配合日军‘铁壁合围’，在昔阳东部山区烧毁村庄，抢掠物资，杀害抗日军属。', '山西晋中_昔阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ae31c7be450b5135b92c86bb65e1c1cf', '930d87dd3bfd5349add3c37d51a9086c', 1943, '伪晋中地区‘剿共’自卫团团长（昔阳人）', NULL, '组织自卫团，在昔阳、和顺交界地带伏击八路军运输队，并参与屠杀抗日俘虏。', '山西晋中_昔阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('31b8300e510257a0875f1ab2b3809ded', '2b5378ecc56d5f4f84f06756e495b505', 1938, '伪昔阳县知事', NULL, '投靠日军，任伪昔阳县知事，协助日军建立维持会，推行保甲制度，强征民夫，搜刮粮食，镇压抗日群众。', '山西晋中_昔阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0b8c52c819ea56fbb053b1b17120d4b5', '142ed91c1ea95b6d922d76d4627e2b83', 1939, '伪昔阳县保安队队长', NULL, '组织伪保安队，配合日军扫荡抗日根据地，抓捕抗日干部和家属，参与制造多起惨案。', '山西晋中_昔阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('573a34f17498574bb78224e1011ef8b9', '0363562b5098582589ed74d60db92635', 1940, '伪昔阳县警察局局长', NULL, '效忠日军，指挥伪警察刺探抗日情报，破坏地下组织，残害进步人士。', '山西晋中_昔阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4016a308bcf3560c924e413f8b379d34', '00cabf19b9e4579fbb8cf12e85e3abc6', 1941, '伪晋中道尹（辖昔阳）', NULL, '任伪晋中道尹期间，积极推行日伪“治安强化运动”，在昔阳等县组织“新民会”，强抓壮丁，掠夺资源。', '山西晋中_昔阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f9308004b24c5b218a8ac9df03a91d40', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '曾任阎锡山部高级官员，投日后任伪山西省省长，推行日伪政权各项政策，协助日军进行经济掠夺和殖民统治。', '山西晋中_榆次');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('03b32ea8aea15f4e99c2f462f44f4760', '2b38113bed725cedaecdd9dc8d6365ec', 1938, '伪山西省公署顾问、伪榆次县知事', NULL, '投靠日军后任榆次县伪知事，协助日军建立维持会，强征民夫、粮食，镇压抗日活动。', '山西晋中_榆次');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('16daf069af2a5c46addd045a586fca6c', 'f8128d92a5455f2886dae039c7903166', 1939, '伪晋北政厅厅长（后投日）', NULL, '原晋绥军将领，后投靠日军，任伪晋北政厅厅长，配合日军在晋中、榆次一带“扫荡”，残害抗日军民。', '山西晋中_榆次');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9977e42819fe5401b1eed7ea77000355', 'f0a05b45394f5fcf9e2d9b7b4cbf4e5d', 1938, '伪山西省公署财政厅长', NULL, '负责为日军搜刮山西及榆次地区财税，推行伪币，掠夺粮食和矿产资源，支持日军战争机器。', '山西晋中_榆次');
