INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ebd0646f463d53209c7b35a9641398e7', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长（管辖晋城地区）', NULL, '作为伪山西省最高行政长官，推行日伪统治政策，在晋城地区强化保甲制度，征收苛捐杂税，镇压抗日活动。', '山西晋城');
