INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0a95c989c2e75c309955bffe5d05236a', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令（曾活动于朔州周边）', NULL, '原东北军将领，后投日，任伪蒙古军总司令，曾率部在晋北（含朔州地区）配合日军扫荡抗日武装。', '山西朔州');
