INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e50885d8bf8a5b44b682811a8174e9de', '27c84878572e5361a427d9981c30abbf', 1939, '伪朔县保安队队长', NULL, '充当日军走狗，任朔县保安队队长，多次带队围捕抗日地下工作者，烧毁村庄。', '山西朔州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1d57f27ddd585c08b9731b48bd2a3878', '8889ca062e5650f5a1f0f9b458376980', 1940, '伪平鲁县知事', NULL, '任伪平鲁县知事，协助日军建立伪政权，强征民夫修筑碉堡，迫害抗日家属。', '山西朔州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('60b4bacb5da356bb857293ccf74e48ca', '1c5a5b4b57a35e3887780282d0b228d6', 1937, '伪山阴县维持会会长', NULL, '日军占领山阴后出任维持会长，为日军筹集粮款，出卖抗日情报。', '山西朔州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d3be81d2fc755cbfb3846c0b7c140fe8', 'c73fd813480653559ada941382fd4b24', 1941, '伪怀仁县警备大队长', NULL, '投靠日军，任怀仁县警备大队长，参与“扫荡”朔州西部抗日根据地，杀害多名游击队员。', '山西朔州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d8aff2ae8be85709a5bc3aa2b8d9ca71', '07284cf8320b589fac71fd028d728597', 1938, '伪应县新民会会长', NULL, '任伪应县新民会会长，推行奴化教育，强迫民众参加“反共”集会。', '山西朔州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('479a5e0938b55e928ad1e652db269b20', '5ba9b438aa8057fe971e7bd39b052daf', 1940, '伪朔县警察局局长', NULL, '充当日军鹰犬，任朔县警察局长，大肆搜捕抗日分子，刑讯逼供。', '山西朔州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dd2c92b53d1d5a5a93993c1d0decf49d', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪蒙疆自治政府副主席、伪绥西联军总司令', NULL, '原为晋系军阀，后投靠日军，在山西北部及绥远地区组织伪军，配合日军扫荡抗日根据地，残害抗日军民。', '山西朔州_山阴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4c7f0bb1a90557629f2321b13e9ef4c0', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪蒙疆自治政府军事部长', NULL, '曾率伪蒙古军进犯山西北部，包括朔州、山阴一带，协助日军建立伪政权，镇压抗日活动。', '山西朔州_山阴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b1cc291511cb5acab92074254efac0f1', '03751651c36952668c9b65b923b9c221', 1937, '伪蒙疆联合自治政府主席', NULL, '作为伪蒙疆政权首脑，其势力范围涵盖山西北部部分地区，支持日军对朔州、山阴等地的占领和殖民统治。', '山西朔州_山阴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e21c3f5c2abc5aa5a84b5d6cfec52720', 'eb30ef64b60d52fdbba910bc5475ca42', 1939, '伪山阴县保安队队长、伪警察署署长', NULL, '原为山阴地方土匪，后投靠日军，任伪职，多次带伪军袭击抗日游击队，杀害抗日干部和群众，是山阴地区著名的汉奸。', '山西朔州_山阴');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e4bd07d693b452dea5ba287e4d9f19d4', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令', NULL, '原为东北军将领，后投靠日军，在平鲁及绥远一带配合日军扫荡抗日武装，残害百姓。', '山西朔州_平鲁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e9b84b814dfc54d693b707b5edb425c8', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令', NULL, '在晋北及平鲁周边地区为日军效力，多次率伪军进攻抗日根据地，劫掠粮食物资。', '山西朔州_平鲁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3b47651c092a5d6abd0592b431215e57', 'eb30ef64b60d52fdbba910bc5475ca42', 1939, '伪平鲁县保安队队长', NULL, '原为土匪，后投靠日军，任平鲁县伪保安队长，协助日军清乡，逮捕抗日军民，勒索乡民。', '山西朔州_平鲁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d0cef96ae8645c1d9e7aadb4358d8533', '3ecfae9ff43c5029ab1679ba2722a82a', 1940, '伪平鲁县维持会会长', NULL, '在平鲁县城组织维持会，为日军征粮派款，提供情报，破坏抗日地下组织。', '山西朔州_平鲁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('016cad862dfc5f8d86758d3dee0f67c5', '3c0cec769a465f2da5d9587d32cf51f4', 1937, '应县伪县长', NULL, '日军侵占应县后出任伪县长，协助日伪推行保甲制度，强征粮饷，镇压抗日民众。', '山西朔州_应县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9ecd3eb04c4954fa87b4af054922bee7', '27c84878572e5361a427d9981c30abbf', 1938, '应县伪警察所所长', NULL, '效忠日军，指挥伪警察抓捕抗日干部和群众，参与多次“扫荡”行动。', '山西朔州_应县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('53b686a7d4aa5b31b9cdc6ffdb326102', '36858bfafe7c5a60a38a37d68095dc4c', 1939, '应县伪保安队队长', NULL, '率伪保安队配合日军袭击抗日根据地，烧杀抢掠，民愤极大。', '山西朔州_应县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f4b0a2aea385582881445925c28ab658', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令', NULL, '原为东北军军官，后投靠日军，在绥远、山西北部（含朔州、怀仁一带）协助日军进攻抗日武装，建立伪政权，参与“治安强化运动”，残害抗日军民。', '山西朔州_怀仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9d74b7363e625dd4805a2fa1dadfb285', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪绥西自治联军总司令', NULL, '原为土匪出身，后投日，在晋北（含朔州、怀仁地区）配合日军扫荡，劫掠百姓，袭击八路军游击队，为日军提供情报。', '山西朔州_怀仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c44fb1d1850f51ef9af657000b07b397', 'eb30ef64b60d52fdbba910bc5475ca42', 1938, '伪雁北挺进队司令', NULL, '原为国民党地方武装头目，后投靠日军，在朔州、怀仁、山阴一带活动，多次围攻抗日根据地，杀害抗日干部和群众，制造多起惨案。', '山西朔州_怀仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9c9a8aae9fd6595fb87dab9e0afc237f', 'f8128d92a5455f2886dae039c7903166', 1939, '伪晋北自治政府顾问', NULL, '原为阎锡山部军官，后投日，在怀仁、朔县等地协助日军推行保甲制度，强征民夫，掠夺粮食，镇压抗日活动。', '山西朔州_怀仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('010537c199d6571b9e274b7a3f865263', '04ee0b0ea19655c4985894a5e3f3dd4a', 1940, '伪怀仁县知事', NULL, '任伪怀仁县知事期间，为日军征粮派款，组织伪警察抓捕抗日分子，破坏地下党组织，协助日军修建碉堡和封锁沟。', '山西朔州_怀仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('890217ab763450239ea79f41b5026bf5', '5635de6ec8b954938e4177b1f1011954', 1941, '伪朔县保安大队长', NULL, '在朔县、怀仁交界地带活动，率伪军多次袭击八路军武工队，杀害抗日家属，抢劫群众财物，充当日军“扫荡”帮凶。', '山西朔州_怀仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3082d5fe00895273a7c98de4ee5de8f8', '8889ca062e5650f5a1f0f9b458376980', 1942, '伪怀仁县警察局长', NULL, '在怀仁县城内建立特务网络，搜捕抗日地下工作者，严刑逼供，导致多名抗日人员牺牲，并参与日军“清乡”行动。', '山西朔州_怀仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('83e6df5830c2581392daa1d87e1b8510', '1c5a5b4b57a35e3887780282d0b228d6', 1940, '伪雁北道公署参事', NULL, '在朔州、怀仁一带为日军推行“以华制华”政策，组织汉奸宣传队，破坏抗日统一战线，并参与策划对抗日根据地的经济封锁。', '山西朔州_怀仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e856bb95afee5f96b98fa4733026a622', '3c0cec769a465f2da5d9587d32cf51f4', 1937, '伪朔县县长', NULL, '日军侵占朔县后出任伪县长，协助日军推行“治安强化”运动，强征民夫修筑碉堡、封锁沟，并参与镇压抗日军民，征收苛捐杂税供日军军需。', '山西朔州_朔城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('13b017cac90f5ac59d9f4f4a6919b3ea', '142ed91c1ea95b6d922d76d4627e2b83', 1936, '伪蒙古军政府副主席、伪蒙古军总司令（曾活动于朔城周边）', NULL, '虽为察哈尔人，但多次率伪蒙古军配合日军在朔县、平鲁一带“扫荡”，烧杀抢掠，破坏抗日根据地，并协助日军建立伪政权。', '山西朔州_朔城');
