INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1b09e5f408415164ac984b09da072f28', '3ecfae9ff43c5029ab1679ba2722a82a', 1940, '伪朔县保安队队长', NULL, '率伪保安队配合日军袭击朔城周边村庄，抓捕抗日干部和群众，实施“连坐”政策，并参与制造多起屠杀事件。', '山西朔州_朔城');
