INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ca175fddaa135e61a728e24f6dc56aec', '142ed91c1ea95b6d922d76d4627e2b83', 1938, '伪运城维持会会长', NULL, '组织维持会为日军征粮派款，强迫商户悬挂伪旗，出卖抗日情报，导致多名地下党员被捕。', '山西运城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('19b864154eb35bb19ba8d4ac9c7f98e4', 'ce3ed8888ec652fcb9c95d4413ccdd94', 1940, '伪解县知事', NULL, '在解县推行保甲制度，强征壮丁补充伪军，协助日军掠夺食盐资源，镇压民众反抗。', '山西运城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ff546a1923d354ce9602c1c1c113a253', '6c315e526acf5688be33ab1eee2c6a0c', 1941, '伪安邑县警备队副队长', NULL, '率警备队袭击抗日游击队，抓捕并刑讯抗日群众，参与日军“治安强化运动”。', '山西运城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a8db1f41ec5f517b8f2f60958048c9da', '76c12ec1765c52da9979871bc7873502', 1938, '万泉县伪县长', NULL, '投靠日军，任万泉县维持会会长及伪县长，协助日军推行“治安强化运动”，强征民夫，搜刮粮食，镇压抗日群众。', '山西运城_万荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('16056b514d7e55fd98b5e71e002bb723', '2b5378ecc56d5f4f84f06756e495b505', 1939, '万泉县伪保安队队长', NULL, '组织伪保安队，配合日军扫荡抗日根据地，多次带队抓捕抗日干部和家属，烧毁村庄，民愤极大。', '山西运城_万荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9a5eadd099b5551dae32be0ba49321b7', 'fc12731bbe6a5d148de0b75c1c114683', 1938, '荣河县伪县长', NULL, '任荣河县伪县长，为日军征收粮款，强抓壮丁，破坏地下抗日组织，曾指使汉奸告密导致多名抗日人员被捕牺牲。', '山西运城_万荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4d2342074bc65902b3ec63f375157597', '6c315e526acf5688be33ab1eee2c6a0c', 1940, '荣河县伪警察局局长', NULL, '充当日军耳目，指挥伪警察搜捕抗日分子，严刑拷打进步群众，并参与日军“清乡”行动，抢劫民财。', '山西运城_万荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c438e5fb285554e8bdda905a5047d86d', 'da4bf1ddb0f352dbb8cba684b927ab9a', 1938, '万泉县伪维持会副会长', NULL, '协助日军建立伪政权，为日军提供情报，强迫村民领取“良民证”，并克扣赈济物资中饱私囊。', '山西运城_万荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('096e7ccc5ba9508e8c03a6bdd3a528f8', '7ad2992b4e32522880aa14559fb49a2b', 1941, '荣河县伪保安团副团长', NULL, '率伪军多次袭击抗日游击队，杀害抗日战士，并参与日军在汾河沿岸的封锁行动，阻断抗日物资运输。', '山西运城_万荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3b6a8d7444635de6908de3079f9163b6', '2d8a0faad54f5bea87fe89fb3c8c03b5', 1939, '万泉县伪税务局局长', NULL, '为日军强征各种苛捐杂税，逼死多名交不起税的农民，并贪污部分税款，助纣为虐。', '山西运城_万荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('87450431638f5c8cafb8ac7eb59fb2e0', '52e76e3de571564cb8221d313b3064e0', 1942, '荣河县日伪便衣队队长', NULL, '带领便衣队刺探抗日军情，多次引导日军突袭村庄，杀害抗日家属，罪行累累。', '山西运城_万荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ddbff97274465bf3ae506344da34fc3c', '2b5378ecc56d5f4f84f06756e495b505', 1938, '伪万泉县知事', NULL, '日军占领万泉后出任伪县长，协助日军推行“治安强化”运动，强征民夫修筑炮楼据点，搜刮粮食资敌。', '山西运城_万荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f0b951c3a9075d97b3e26ba34351eacb', '3bf67686c57252e08e39d6f5d301f744', 1938, '伪万泉县维持会会长', NULL, '日军初占万泉时组织维持会，为日军提供当地抗日武装情报，并强迫百姓欢迎日军，后被抗日武装处决。', '山西运城_万荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('183a7cb5ef3a53b095e2451054ec0c8d', 'f0baa384725151ad9fb99cef1a20fe7c', 1939, '伪荣河县知事', NULL, '在荣河县（今属万荣）任伪县长期间，配合日军“扫荡”抗日根据地，组织伪警备队抓捕抗日军民，并推行保甲连坐制度。', '山西运城_万荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('df29a388461d58ec9626482dfc429204', 'fc12731bbe6a5d148de0b75c1c114683', 1940, '伪荣河县警备队队长', NULL, '率伪军多次参与对抗日游击队的围剿，杀害多名抗日干部，并强征百姓粮食供应日军。', '山西运城_万荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('46cf1a2629a254e882abd402245f9dc4', '8a40e2a9a0c15403908c323cc0dbbc6f', NULL, '', NULL, '', '山西运城_万荣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fca15ed84e6855c09aa937688609d62a', '2b5378ecc56d5f4f84f06756e495b505', 1938, '伪临晋县知事', NULL, '日军占领临晋后出任伪知事，协助日军推行‘治安强化运动’，强征民夫修筑碉堡公路，并组织伪警备队镇压抗日民众。', '山西运城_临猗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('97e24af11b51570e9da75c690b6d6ac5', '9df111dbb24a5363a5c0158aaba434ae', 1939, '伪猗氏县知事', NULL, '任伪猗氏县知事期间，为日军提供粮秣情报，参与‘清乡’行动，抓捕抗日干部及家属，并强迫百姓领取‘良民证’。', '山西运城_临猗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('40700beb4ddf599690356b35a4cc2aa9', '0ee6551492325c6698194a09aad3f702', 1938, '伪运城维持会会长', NULL, '日军侵占运城后率先投敌，组织维持会，为日军筹措物资，协助建立伪政权，并出卖抗日地下工作者名单。', '山西运城_临猗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a8d0b646a9ec514890bca53f038cbe03', '6c315e526acf5688be33ab1eee2c6a0c', 1940, '伪运城保安队副队长', NULL, '率部充当日军爪牙，多次参与‘扫荡’临猗、万泉一带，杀害抗日游击队员，并抢劫百姓财物。', '山西运城_临猗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b9f10d74f0bd58128c632d7045520367', 'eca6f1c850fc545c81553cc0cd3dc1fa', 1941, '伪临晋县警备大队长', NULL, '指挥伪警备队配合日军突袭抗日村庄，放火烧毁民房，并亲自拷打被俘的抗日军民，致多人死亡。', '山西运城_临猗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('91c8256788b352c38e6ae931fa53e8c8', '7131a0b05ae85c1c99de06bbd99c2f8f', 1942, '伪猗氏县新民会会长', NULL, '利用新民会宣传‘中日亲善’，强迫青年参加伪军训练，并密报抗日活动，导致多名地下党员被捕。', '山西运城_临猗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('62cc84e8c7a551d1bf41d2f45f51f048', '55ee3b3a8aaf5f379c665ca50bc22e2f', 1939, '伪运城商会会长', NULL, '为日军统制物资，强征商户捐款，垄断食盐和棉花贸易，从中牟利，并协助日军经济掠夺。', '山西运城_临猗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a61b7c0bbfde5e868dbbe74c2c1c43c0', '7ad2992b4e32522880aa14559fb49a2b', 1938, '伪临晋县维持会副会长', NULL, '为日军带路搜捕抗日家属，参与建立‘爱护村’，强迫村民报告八路军动向，并杀害两名抗日交通员。', '山西运城_临猗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f53006300010556dbacc1a3307cb5b5a', 'a274a0b51976540e85b02641ac9a20a7', 1940, '伪猗氏县警察局长', NULL, '指挥伪警察协助日军设卡盘查，抓捕过往可疑人员，并参与‘大检举’行动，将数十名群众押送日军宪兵队。', '山西运城_临猗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2428b2661d1352e1a2afac4fb9005491', '231861bd037c500b9f6574030d28a4af', 1938, '伪运城宣抚班班长', NULL, '随日军宣抚班到临猗各村演讲，诱骗百姓归顺，并收集地方武装情报，导致多支抗日小分队遭伏击。', '山西运城_临猗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('672908c57c97573e9d102d96585588db', '76c12ec1765c52da9979871bc7873502', 1938, '垣曲县伪县长', NULL, '投靠日军后出任垣曲县维持会会长及伪县长，协助日军建立伪政权，强征民夫修筑碉堡，搜刮粮食供给日军，并参与诱捕抗日军民。', '山西运城_垣曲');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('642ac602d5fd5e6ca986e75dcb2eac9c', '2b5378ecc56d5f4f84f06756e495b505', 1939, '伪垣曲县保安队队长', NULL, '率保安队多次配合日军扫荡抗日根据地，杀害抗日干部和群众，抢劫物资，并强迫青年加入伪军。', '山西运城_垣曲');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f6a6630b328e5a7798f053a34ccb053b', '5c921e3d243b56ecb74f90581038ff0d', 1940, '伪垣曲县警察局局长', NULL, '在日军占领期间任伪警察局长，负责侦缉抗日地下人员，严刑拷打被捕者，并协助日军推行“治安强化运动”。', '山西运城_垣曲');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('61b2c2f293175685b82668a4333dddeb', '3f241dfb90ff51518948ad5c3d297eba', 1938, '垣曲县伪维持会副会长', NULL, '积极为日军筹粮派款，强迫村民参加“爱护村”，向日军报告抗日武装动向，导致多处秘密联络点被破坏。', '山西运城_垣曲');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('85cabf979e7b5d6eb645ca214a95f58b', '231861bd037c500b9f6574030d28a4af', 1941, '伪垣曲县教育科长', NULL, '推行奴化教育，强迫学校使用日伪教材，宣扬“中日亲善”，并告发多名爱国教师，致其被捕或失踪。', '山西运城_垣曲');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e16da89375335996a0ac54678d774fb9', '07284cf8320b589fac71fd028d728597', 1939, '伪垣曲县税务局长', NULL, '为日军征收各种苛捐杂税，强征民间财物，中饱私囊，并协助日军控制粮食贸易，导致当地百姓饥荒。', '山西运城_垣曲');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b6785833e6955c63a8d151085a5f5a73', 'edab9b9b38df5aee90d6eaffa789decb', 1940, '伪垣曲县新民会主任', NULL, '组织新民会宣传“大东亚共荣”，刺探抗日情报，并组织汉奸团体破坏抗日群众组织。', '山西运城_垣曲');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('54a09b22a3715b399f63ddfee178e9f6', 'fdc924a005d9538a8da27a0094bf8f69', 1942, '伪垣曲县警备队小队长', NULL, '多次带队突袭抗日村庄，烧杀抢掠，曾一次杀害无辜村民十余人，并抢夺牲畜粮食。', '山西运城_垣曲');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4b2cca9c2cb35aa6a6e7ce3e5144aa8f', 'f93f7b7b4d9f5cdf8284d8c9b5cf12d7', 1939, '垣曲县伪区公所区长', NULL, '在辖区强制推行“良民证”，抓捕抗日嫌疑人员，并配合日军“扫荡”，提供当地地形和人员情报。', '山西运城_垣曲');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('614614ada18d5e25bda69bdbda3805c1', 'b2cb3b9447ff5e6fb64795a71c198872', 1941, '伪垣曲县合作社理事长', NULL, '垄断食盐、布匹等物资配给，克扣百姓配额，高价转卖，并利用合作社为日军收集战略物资。', '山西运城_垣曲');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('672908c57c97573e9d102d96585588db', '76c12ec1765c52da9979871bc7873502', 1938, '垣曲县伪县长', NULL, '投靠日军后任垣曲县维持会会长及伪县长，协助日军建立伪政权，强征民夫修筑碉堡公路，并组织伪警备队配合日军扫荡抗日根据地，残害抗日军民。', '山西运城_垣曲');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bc52f04444045ab2b4c6f5e843dc1a21', '2b5378ecc56d5f4f84f06756e495b505', 1939, '伪垣曲县保安大队长', NULL, '原为地方土匪，后投靠日军任伪保安大队长，率部多次袭击八路军游击队，抓捕并杀害抗日干部，曾参与制造“皋落惨案”，纵兵抢掠百姓财物。', '山西运城_垣曲');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3bc0d665f97f5e6d8e3014625cc2a607', '5c921e3d243b56ecb74f90581038ff0d', 1940, '垣曲县伪警察局长', NULL, '在日军扶植下任伪警察局长，负责侦缉抗日地下人员，多次带队搜捕中共地下党员，刑讯逼供并移交日军宪兵队，致使多名抗日志士牺牲。', '山西运城_垣曲');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6048ee35c08e56eead996d8d806b4c8b', '3f241dfb90ff51518948ad5c3d297eba', 1941, '伪垣曲县新民会会长', NULL, '积极推行日军“治安强化运动”，组织汉奸宣传队散布亲日言论，强迫民众参加“新民会”，并收集抗日情报提供给日军，破坏抗日群众组织。', '山西运城_垣曲');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c095d87eb0bc54519780cf3c8703cedc', '76c12ec1765c52da9979871bc7873502', 1938, '夏县伪县长', NULL, '投靠日军，任夏县伪县长，协助日军推行“治安强化运动”，强征民夫，搜刮粮食，镇压抗日群众。', '山西运城_夏县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('df1519fdac95564cbe0551ebf163ffaf', '142ed91c1ea95b6d922d76d4627e2b83', 1939, '夏县伪保安队队长', NULL, '率伪保安队多次配合日军扫荡抗日根据地，抓捕抗日军民，烧毁村庄，民愤极大。', '山西运城_夏县');
