INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3c12518cab3259f59914c328ae16dd78', '2906bcb94ebc588ebb19b618529e511d', 1938, '夏县伪维持会会长', NULL, '日军占领夏县后率先组织维持会，为日军提供情报，指认抗日家属，导致多人被捕遇害。', '山西运城_夏县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('121a9e6da8955383a340c83b131ab04f', '6c315e526acf5688be33ab1eee2c6a0c', 1940, '运城伪警察局局长', NULL, '效忠日军，指挥伪警察搜捕地下党员，破坏抗日组织，参与“清乡”行动，残害百姓。', '山西运城_夏县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6a637af4a34356e1a7d33ecd5f4058f0', 'edab9b9b38df5aee90d6eaffa789decb', 1941, '夏县伪新民会会长', NULL, '宣传“中日亲善”，强迫群众参加新民会，刺探抗日情报，协助日军推行奴化教育。', '山西运城_夏县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0fc3801bd15251a498d8b73c80568814', '51f0abc8d3385972b33046822359065a', 1939, '运城伪保安团副团长', NULL, '率伪军参与“三光”扫荡，在夏县、运城交界处多次袭击游击队，杀害抗日干部和群众。', '山西运城_夏县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('45ab05b3de655f23929f4ccf4dd7b0b2', '7194deed37a3584cb9c036b33312e513', 1939, '夏县伪税务局局长', NULL, '为日军强征各种苛捐杂税，盘剥百姓，将大量税款上交日军充作军费，民不聊生。', '山西运城_夏县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5fac3801afc55cc8856750d10e8eac70', 'e60d0335f96157edb58448797cda6ce0', 1940, '运城伪教育督学', NULL, '推行奴化教育，强迫学校使用日伪教材，禁止讲授中国历史，迫害爱国教师。', '山西运城_夏县');
