INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('99c334da2fc35abc9d9ae3cb62f0c0b6', 'a885927cd073551fabc84253bbb152f3', 1938, '伪永济县维持会副会长、日伪合作社社长', NULL, '为日军征购粮食、棉花等战略物资，垄断食盐贸易，从中牟利，并强迫农民种植鸦片，导致当地民生凋敝。', '山西运城_永济');
