INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('931d8483f19052a5a2f5c9d04132c205', '2b38113bed725cedaecdd9dc8d6365ec', 1938, '伪山西省公署顾问', NULL, '为日军出谋划策，参与建立伪政权，协助日军在运城地区清乡扫荡。', '山西运城_河津');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('afc0f3f940eb5388846daa51989581e6', '04e59fa422205372aae1c93ef3c9935a', 1939, '伪河津县知事', NULL, '任伪河津县知事，强征民夫修筑公路碉堡，为日军提供粮食情报，迫害抗日家属。', '山西运城_河津');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('868933f743085bcd9fc72bb037705c8a', '2f74df7c0254512388c38ef6f3a3d8ca', 1940, '伪河津县保安队队长', NULL, '率伪军配合日军扫荡汾南抗日根据地，抓捕杀害抗日干部，勒索百姓。', '山西运城_河津');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ef22e7da113b5ecf9b40e48f84e060ce', '67441094f5ab50528a4402978598d4c3', 1938, '伪河津县维持会会长', NULL, '组织维持会迎接日军，协助建立伪政权，摊派粮款，为日军带路袭击村庄。', '山西运城_河津');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('449581133c5c528bbb5f574c5fa97c94', 'fffe019cbd895052b54cda18e0474a34', 1939, '伪运城道尹', NULL, '任伪运城道尹，管辖河津等县，推行保甲制度，强征壮丁，配合日军经济封锁。', '山西运城_河津');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('87084e641b2052db8a711b944188bd0c', 'c36ed77fe8ef552bb6bb631a999ac31f', 1941, '伪运城警备司令', NULL, '指挥伪军驻守运城、河津要道，参与多次扫荡，杀害抗日游击队员。', '山西运城_河津');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a9b6871bfe71528183f4df9edb7ca404', '6da181400a015ced8f2b9e4cbb31b41d', 1940, '伪河津县新民会会长', NULL, '宣传中日亲善，组织奴化教育，搜集抗日情报，破坏地下党组织。', '山西运城_河津');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b4b1e187c7f159408d5b577482bde6da', 'da4bf1ddb0f352dbb8cba684b927ab9a', 1939, '伪河津县警察所所长', NULL, '带领伪警察抓捕抗日群众，严刑逼供，协助日军屠杀无辜百姓。', '山西运城_河津');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a06b4c44314558cda8530cb586241ccc', '03b3ecf4f2f750d49a27d274d2bc8839', 1938, '伪河津县财政科科长', NULL, '为日军征收苛捐杂税，贪污抗日物资，逼迫农民交出粮食支援日军。', '山西运城_河津');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('83ec50b004b65cf498a840520d42bae6', 'c36ed77fe8ef552bb6bb631a999ac31f', 1938, '河津县伪县长', NULL, '日军占领河津后出任伪县长，协助日军推行“治安强化运动”，强征民夫修筑碉堡公路，并组织伪警备队镇压抗日群众，曾配合日军扫荡汾南抗日根据地。', '山西运城_河津');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6d5e5932982153b9b74b9cfb2f981469', 'ef756074e8c05f0d8cdbc61496d93094', 1939, '河津县伪保安队队长', NULL, '率伪保安队多次袭击抗日游击队，抓捕并杀害抗日军民，为日军提供情报，参与“清乡”行动，在河津东庄、南午芹等地制造多起惨案。', '山西运城_河津');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d0eb07bc9ac75d0e962268be7046c6ce', 'da4bf1ddb0f352dbb8cba684b927ab9a', 1938, '日伪河津县维持会会长', NULL, '日军侵占初期出任维持会长，为日军筹措粮款，强征民夫，并组织汉奸团体“新民会”宣传奴化思想，破坏抗日组织。', '山西运城_河津');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8d86b95830e8594ab39256129c461af6', 'dfe410b863b25a2f8db8d82f4cd5a90e', 1941, '伪河津县警备队副队长', NULL, '协助日军在河津、稷山交界地带“扫荡”，多次带路袭击抗日县政府驻地，残害抗日干部，并勒索百姓财物，民愤极大。', '山西运城_河津');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2c40d31c751e5f00958c324783afb4d1', '873358d5c725553692ad6badfdc50049', 1939, '日伪河津县教育科长', NULL, '推行奴化教育，强制学校使用日伪教材，宣扬“中日亲善”，并检举抗日师生，导致多名进步教师被捕遇害。', '山西运城_河津');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bb80a22f67db5f41b5b2b24644b1af0d', '76c12ec1765c52da9979871bc7873502', 1938, '伪运城维持会会长', NULL, '日军占领运城后出任维持会长，协助日军征粮派款、强征民夫，镇压抗日民众，为日军提供情报。', '山西运城_盐湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('00e9167233ed51d184c8a65905811a2e', '2b5378ecc56d5f4f84f06756e495b505', 1939, '伪盐湖保安队队长', NULL, '组织汉奸武装，配合日军扫荡盐湖周边村庄，杀害抗日干部和群众，抢劫财物。', '山西运城_盐湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9af3620869135bbb901225dd80c4667a', '0ee6551492325c6698194a09aad3f702', 1940, '伪盐湖区区长', NULL, '在日军扶植下担任伪区长，推行保甲制度，强征壮丁，搜刮民财，迫害抗日家属。', '山西运城_盐湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0f84a82d27eb522e83158ca094e9f8f6', '22c3b1ca05ae5b069f4e86515cfbfce9', 1941, '伪运城便衣队队长', NULL, '充当日军特务，刺探抗日武装情报，多次带领日军突袭抗日据点，抓捕地下党员。', '山西运城_盐湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a2b1f32ad7f851ae9d3c8bff840f896d', '231861bd037c500b9f6574030d28a4af', 1938, '伪盐湖商会会长', NULL, '为日军筹措军饷，控制盐业贸易，强迫商户向日军献金，从中牟利，并告发抗日商人。', '山西运城_盐湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3d6a3ff0368d5936be7612bd9f4f4e39', 'fdc924a005d9538a8da27a0094bf8f69', 1939, '伪运城警察局局长', NULL, '指挥伪警察协助日军维持治安，搜捕抗日分子，严刑拷打被捕人员，参与屠杀行动。', '山西运城_盐湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d79e0cee0fa35f2284abd44d18c593dd', 'e345f27d716a5d1990819e80016498f3', 1940, '伪盐湖自卫团团长', NULL, '组织自卫团为日军站岗放哨，参与清乡行动，烧毁村庄，抢夺粮食，杀害无辜百姓。', '山西运城_盐湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('48a2290108d45beb93ec47c34374a056', 'fea07466bb9d53d3a13f04dd08cd9a5d', 1938, '伪运城宣抚班班长', NULL, '为日军进行奴化宣传，强迫民众参加“中日亲善”集会，破坏抗日舆论，诱骗青年为日军效力。', '山西运城_盐湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3544e9877d2854f0adc05c231551707b', 'ae5556612a955d3bbb0ec62284038da2', 1939, '伪盐湖税务所所长', NULL, '为日军征收各种苛捐杂税，盘剥百姓，私吞税款，并协助日军控制盐湖盐业资源。', '山西运城_盐湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('db00292a8ae054b5941a556d45a3eae5', 'cfc8c7d56cde53ff85dba613ff8af8ad', 1941, '伪运城情报站站长', NULL, '建立汉奸情报网络，向日军提供抗日武装活动情报，导致多次抗日行动失败，多名抗日志士牺牲。', '山西运城_盐湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9dac1ddcc321565cad668a1a781dbfb2', '142ed91c1ea95b6d922d76d4627e2b83', 1937, '伪蒙古军总司令、晋南地区伪军头目', NULL, '在运城、盐湖一带协助日军扫荡抗日武装，参与建立伪政权，镇压抗日群众。', '山西运城_盐湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b80994b092e355f2859cc2e9e33a3348', '2b5378ecc56d5f4f84f06756e495b505', 1938, '伪绥西联军司令、晋南伪军顾问', NULL, '率伪军配合日军在运城盐湖地区进行“清乡”，掠夺盐业资源，残害抗日军民。', '山西运城_盐湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2f171df50d675fb49424d126275017d6', '30b42c4d5b265db7b5f918654d509a98', 1939, '伪运城县知事（县长）', NULL, '在运城推行日伪统治，强征民夫修筑工事，协助日军控制盐湖，迫害抗日家属。', '山西运城_盐湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f4bbac4bdceb594c951e1e2c30e2a3a1', '4dfc0c6aac7d5712bc027bb01cad49ca', 1940, '伪盐湖保安队队长', NULL, '率保安队为日军护卫盐池，抓捕抗日地下工作者，参与多次屠杀事件。', '山西运城_盐湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d80dd3e1702e5b959a39292529276d6e', '76c12ec1765c52da9979871bc7873502', 1938, '稷山县伪县长', NULL, '日军占领稷山后出任伪县长，协助日军推行“治安强化”运动，强征民夫，搜刮粮食，镇压抗日群众。', '山西运城_稷山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ebc2c1a78dd1581bbd6fad40edc4a2e2', '552a7dc761085fe4a3f99e9d4b6bf62d', 1939, '稷山县伪保安队队长', NULL, '率伪保安队配合日军扫荡抗日根据地，抓捕抗日军民，烧毁村庄，民愤极大。', '山西运城_稷山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('243a970f4a6c54cfa243e497122016e1', 'aa7913ec446c597faf6a8833076cf708', 1938, '运城伪商会会长', NULL, '为日军筹措物资，垄断粮食和食盐贸易，向日军提供经济情报，协助日军经济掠夺。', '山西运城_稷山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('88bcfe42ff6f5b80a249a12133a255fb', '9a175367a3b559f0a73d283977699a9f', 1939, '运城伪警察局局长', NULL, '负责运城城区治安，搜捕抗日地下人员，严刑逼供，破坏抗日组织。', '山西运城_稷山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('67e12d8e8991563eb23985845d9d20ac', '805dcb001bbe5f8782dcde83d247d210', 1940, '晋南伪“剿共”司令', NULL, '在运城、稷山一带组织伪军，多次配合日军“扫荡”，杀害抗日干部和群众，烧毁村庄。', '山西运城_稷山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('55a12277cb6653f48369f9947aca7a65', '76c12ec1765c52da9979871bc7873502', 1938, '绛县伪县长', NULL, '投靠日军后出任绛县维持会会长，后任伪县长，协助日军推行‘治安强化运动’，强征民夫、粮食，镇压抗日群众，曾亲自带队抓捕抗日干部并交予日军宪兵队处决。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e8cd4c209e14561dbf5b6a7a23e0d46a', '2b5378ecc56d5f4f84f06756e495b505', 1939, '绛县伪保安队队长', NULL, '组织伪保安队配合日军‘扫荡’抗日根据地，多次袭击抗日游击队驻地，杀害抗日军属，并参与日军在绛县南樊镇、横水镇等地的烧杀抢掠行动。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e2ab331d8c0e56faa44ecb8361a94e4d', '0ee6551492325c6698194a09aad3f702', 1940, '绛县伪警察所所长', NULL, '效忠日军，负责绛县县城及周边治安，大肆搜捕抗日地下党员和进步人士，严刑逼供后移交日军，导致多名抗日志士牺牲。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('03b1544c205453a09ca7cd47cb10dd75', '805dcb001bbe5f8782dcde83d247d210', 1941, '绛县伪新民会会长', NULL, '在绛县推行奴化教育，组织‘新民会’宣传‘中日亲善’，强迫百姓参加反共集会，并收集抗日情报提供给日军特务机关。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('24ba618cdf9459368556438d9d5bcf5a', 'e60d0335f96157edb58448797cda6ce0', 1939, '运城伪商会会长', NULL, '在运城沦陷期间为日军筹措军需物资，垄断粮食、棉花等战略物资贸易，从中牟利，并协助日军建立经济封锁线，破坏抗日根据地物资流通。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('74ee0c5c99e15edfa77c9ec9ff48aca7', 'fdc924a005d9538a8da27a0094bf8f69', 1940, '运城伪警备队副队长', NULL, '率伪警备队参与日军对中条山抗日游击队的多次围剿，在夏县、闻喜、绛县交界地带杀害抗日战士及无辜百姓，并抢劫村庄财物。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dd84609157a55d4b9b18474e5d0b9db0', 'dd70fe911e01561ab9b6cac5a6a5b594', 1942, '运城伪‘剿共’委员会主任', NULL, '专门策划针对抗日地下组织的破坏行动，在运城、绛县等地发展特务网络，曾导致绛县抗日县政府多名工作人员被捕牺牲。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e9bb0103d00d573baa448cb3a3837138', '7ad2992b4e32522880aa14559fb49a2b', 1940, '绛县伪区公所区长（横水区）', NULL, '在横水镇一带为日军强征壮丁和粮食，欺压百姓，并多次向日军报告抗日武装动向，致使游击队多次遭袭。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('51808541361156aba939147ae896d7b4', 'ea140ed54446565696fdd581d2bd2de7', 1939, '绛县伪‘宣抚班’班长', NULL, '随日军‘宣抚班’在绛县农村进行反动宣传，诱骗村民归顺日军，破坏抗日群众组织，并参与建立伪村政权。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8ea5bc9440425e2493703a2bc70b363a', 'ae5556612a955d3bbb0ec62284038da2', 1938, '运城伪河东道尹公署顾问', NULL, '作为日军顾问参与运城地区伪政权决策，协助日军推行‘以华制华’政策，在绛县、安邑等县督导征粮和劳役，民愤极大。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('55a12277cb6653f48369f9947aca7a65', '76c12ec1765c52da9979871bc7873502', 1938, '绛县伪县长', NULL, '投靠日军，任绛县维持会会长及伪县长，协助日军推行‘治安强化运动’，强征民夫、粮食，镇压抗日群众，捕杀抗日家属。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e8cd4c209e14561dbf5b6a7a23e0d46a', '2b5378ecc56d5f4f84f06756e495b505', 1939, '绛县伪保安队队长', NULL, '组织伪保安队，配合日军‘扫荡’抗日根据地，多次带队袭击绛县周边村庄，抢劫财物，杀害抗日干部和民兵。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b898e260f5705545ac24c4263b4b8780', '0ee6551492325c6698194a09aad3f702', 1940, '绛县伪警察局局长', NULL, '效忠日军，建立伪警察体系，搜捕地下党员和抗日积极分子，严刑逼供，破坏抗日地下组织。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f7a8809176ce5ccf9685061c3f14fc8b', '805dcb001bbe5f8782dcde83d247d210', 1938, '运城（安邑）伪县长', NULL, '在运城地区任伪职，为日军征收粮款，提供劳役，协助日军建立伪政权，镇压当地抗日武装。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8249ec925ea15b3384b0e5aa27e68527', 'b5cce75bad6f5096911e0e1add680e09', 1939, '运城伪保安司令', NULL, '统领运城伪军，配合日军对中条山抗日根据地多次‘清剿’，杀害抗日军民，烧毁村庄。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8e8e37acff1e55d4a5f6f286205be6dc', '8c03960ff5a75b39895d4f9cc446e383', 1941, '晋南伪军顾问（投敌后）', NULL, '原国民党军官，后投敌任晋南伪军顾问，参与策划对绛县、垣曲等地的‘扫荡’，为日军提供情报。', '山西运城_绛县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('449a6e573f805aa1b6485b9f5385a9f0', '2b5378ecc56d5f4f84f06756e495b505', 1938, '伪芮城县维持会会长', NULL, '日军占领芮城后出任维持会长，为日军征粮派款，协助建立伪政权，镇压抗日民众。', '山西运城_芮城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dffcabde22e951a4b710588f427a5c9e', '61b56ec28fc8552bbb96bcd0bb9dd4c1', 1939, '伪芮城县保安队队长', NULL, '率伪军配合日军扫荡抗日根据地，抓捕并杀害抗日军民，抢劫百姓财物。', '山西运城_芮城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('68354e628b965207b40551bc57494104', '0ee6551492325c6698194a09aad3f702', 1940, '伪芮城县警察局局长', NULL, '效忠日军，负责维持县城治安，搜捕抗日地下人员，迫害爱国群众。', '山西运城_芮城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ae07abf44c025ae6899d3f819c706275', '3f241dfb90ff51518948ad5c3d297eba', 1938, '伪运城道公署顾问', NULL, '作为日军顾问参与运城地区伪政权决策，协助推行奴化教育和经济掠夺。', '山西运城_芮城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('698757b385eb542eaeb27ea524c27178', '552a7dc761085fe4a3f99e9d4b6bf62d', 1939, '伪运城保安司令部副司令', NULL, '指挥伪军多次进攻中条山抗日游击队，破坏抗日组织，残害百姓。', '山西运城_芮城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f99257c59f7b58578a408455cca61461', '8c03960ff5a75b39895d4f9cc446e383', 1941, '伪山西省公署参事', NULL, '在太原伪省府任职，参与制定针对晋南地区的“治安强化”措施，协助日军清乡。', '山西运城_芮城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('510f8670f7bc5e978e44be9626d88b3b', '4509ed01400755b79ca0f020d04a32c0', 1940, '伪芮城县新民会会长', NULL, '宣传“中日亲善”，组织奴化教育，强迫民众参加反共集会，收集抗日情报。', '山西运城_芮城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eace495b5ace50f481d13aece8f0298a', 'a4897e4f456b539c837126359fd4dc7e', 1942, '伪运城粮食统制委员会主任', NULL, '为日军强征粮食，压低粮价收购，导致百姓饥荒，并将粮食转运日军军需。', '山西运城_芮城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('62b95ae383e052f1a722717ddca629ce', 'aa7913ec446c597faf6a8833076cf708', 1939, '伪芮城县税务局局长', NULL, '为日军征收各种苛捐杂税，勒索商户，中饱私囊，并协助日军控制经济命脉。', '山西运城_芮城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d9e18b27243e5895b7c19f3086388a7c', '05d72939614156a89c18bb736835b10c', 1940, '伪运城特务队队长', NULL, '专门刺探抗日军情，抓捕地下党员，刑讯逼供，制造多起惨案。', '山西运城_芮城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cfccf9df1a7d54abbe7447fecd005719', '76c12ec1765c52da9979871bc7873502', 1938, '闻喜县伪县长', NULL, '投靠日军，出任闻喜县维持会会长及伪县长，协助日军推行“治安强化运动”，强征民夫、粮食，镇压抗日群众。', '山西运城_闻喜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('34b8378b0cb75e69ac901a9881dc70a1', 'c7d6d28aad9852619a0a2e25052358c7', 1939, '闻喜县伪保安队队长', NULL, '组织伪保安队，配合日军扫荡抗日根据地，多次抓捕、杀害抗日军民，抢劫百姓财物。', '山西运城_闻喜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('97b7822a313253c6ac81ea84940ae5ae', '89011c25945756f0895607dfc57520e6', 1940, '闻喜县伪警察局局长', NULL, '任伪警察局长期间，大肆搜捕抗日地下党员和进步人士，严刑逼供，破坏地下抗日组织。', '山西运城_闻喜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b025414cb8e5515f89f52e3cf36a53fd', '805dcb001bbe5f8782dcde83d247d210', 1941, '闻喜县伪新民会会长', NULL, '积极宣传“中日亲善”“大东亚共荣”，为日军收集情报，诱骗青年参加伪军。', '山西运城_闻喜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b16919a5279356838a7151a4e1e8f3c7', '068a2fb66df658e086387e0c265ca6bc', 1942, '闻喜县伪区公所区长（第三区）', NULL, '在辖区推行保甲制度，强派捐税，向日军报告抗日武装动向，导致多次袭击失败。', '山西运城_闻喜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('15cf050357595d65b93f425df22ac45c', '4753d97eef6a5723bb99ab69abe8b784', 1943, '闻喜县伪军大队长', NULL, '率伪军多次袭击抗日游击队驻地，杀害多名抗日战士，烧毁村庄。', '山西运城_闻喜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('771026a83b0e5145b5533ac95f183b9f', 'c364b934e4c759fb852b20a786ddb707', 1939, '闻喜县伪税务局局长', NULL, '为日军征收各种苛捐杂税，盘剥百姓，中饱私囊，并协助日军控制粮食流通。', '山西运城_闻喜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('501a828136025f8fb7d018a36a27f1db', 'a885927cd073551fabc84253bbb152f3', 1940, '闻喜县伪教育科长', NULL, '强制推行奴化教育，删改教材，强迫学生参加日军庆典，宣扬“皇军必胜”。', '山西运城_闻喜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('31608e84aeb95ece8a7d72d11ac03a07', 'e81013753399573e9b5ecafc8a1c1331', 1938, '闻喜县维持会副会长', NULL, '日军占领初期，协助建立维持会，为日军筹集粮款，提供向导，参与清乡。', '山西运城_闻喜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5da51bc355da584c9c30c171f5549c01', 'edab9b9b38df5aee90d6eaffa789decb', 1942, '闻喜县伪合作社社长', NULL, '垄断食盐、火柴等物资配给，克扣百姓口粮，将物资优先供应日军。', '山西运城_闻喜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cfccf9df1a7d54abbe7447fecd005719', '76c12ec1765c52da9979871bc7873502', 1938, '闻喜县伪县长', NULL, '投靠日军后出任闻喜县维持会会长及伪县长，协助日军推行“治安强化运动”，强征民夫修筑碉堡公路，并组织伪警备队镇压抗日群众，曾配合日军扫荡稷王山抗日根据地。', '山西运城_闻喜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('55dae7cafde351caa49bdd90a2c118c8', '2b5378ecc56d5f4f84f06756e495b505', 1940, '闻喜县伪保安队队长', NULL, '原为地方土匪，后投靠日军任闻喜县伪保安队队长，多次率部袭击抗日游击队，杀害抗日干部和群众，并参与日军“三光”政策行动，抢劫粮食和财物。', '山西运城_闻喜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('966c4e912e1a5fe08d2f4ae60f8e7641', '9a175367a3b559f0a73d283977699a9f', 1939, '运城（安邑）伪知事', NULL, '任伪安邑县知事期间，积极为日军征粮派款，建立伪区村政权，破坏抗日地下组织，并协助日军建立情报网，导致多名抗日人员被捕牺牲。', '山西运城_闻喜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c4183d80a7b6507a95411a97b52b3b57', '8c03960ff5a75b39895d4f9cc446e383', 1941, '伪河东道尹（运城地区）', NULL, '投敌后任伪河东道尹，管辖运城、临晋、猗氏等县，推行日伪“新民会”奴化教育，强征劳工送往东北和日本，并组织伪军配合日军“扫荡”中条山抗日武装。', '山西运城_闻喜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0f5a699c96805bc98065f1666b315d20', '3bf67686c57252e08e39d6f5d301f744', 1942, '闻喜县伪警备队副队长', NULL, '充当日军耳目，多次带队搜捕抗日家属，严刑逼供地下党员，并参与杀害抗日村长和民兵，罪行累累。', '山西运城_闻喜');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('303110d56f955628ba63df3b43d7dc40', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '曾任伪山西省省长，推行日伪政权统治，协助日军在山西各地建立维持会，镇压抗日力量。', '山西长治');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5611b35af1b25726b61b779a069ed3cf', '2b38113bed725cedaecdd9dc8d6365ec', 1938, '伪长治县知事', NULL, '任伪长治县知事期间，为日军征收粮款，强抓民夫，破坏抗日组织，协助日军扫荡。', '山西长治');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('64a9c98e9ef8564f93e104f84daa8170', 'ea6f46335bd257259394a1581cf6ae85', 1939, '伪长治县保安队队长', NULL, '率伪保安队配合日军多次袭击抗日根据地，杀害抗日干部和群众，参与“治安强化”运动。', '山西长治');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('83b8ea6878165fec87d2776b91f54aa4', 'abfbfc55b2075575b7abe7d534e7196d', 1940, '伪潞安府（长治）警备司令', NULL, '任伪警备司令期间，负责长治城防，搜捕抗日地下人员，提供情报给日军，镇压反日运动。', '山西长治');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b277ca598e8e54caae525274b42ed940', 'd34e7c17c41559c79a3fd4e024c4b7e6', 1938, '伪长治县维持会会长', NULL, '组织维持会为日军筹粮派款，强迫百姓领取“良民证”，告密导致多名抗日群众被捕牺牲。', '山西长治');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('156c607955dd5a79af7487ffd27dd67a', 'd6ca38cec4105c5ea630f21d3071e2d8', 1939, '伪长治县警察局局长', NULL, '指挥伪警察协助日军抓捕抗日分子，严刑逼供，破坏地下交通线，参与屠杀平民事件。', '山西长治');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c28d688659e75bdaa2db2163f113683b', '7f23b9969bf356229370dbaa8c6a8a03', 1940, '伪长治县新民会会长', NULL, '推行奴化教育，宣传“中日亲善”，组织汉奸团体，刺探抗日情报，协助日军“清乡”。', '山西长治');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e059973f3996531e842ddda13076c39e', '153310fe23185f0ca1018c325e83762c', 1939, '伪山西省政府顾问（长治籍）', NULL, '虽主要活动于太原，但作为长治籍汉奸，多次为日军劝降抗日武装，提供长治地区抗日力量情报。', '山西长治');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('28e17ea9f48a5f0c93641a8fc18a4e32', 'e4f2f760ffe15aee9ae9b3f78f742971', 1938, '伪长治县税务局局长', NULL, '为日军强征各种苛捐杂税，盘剥百姓，将所得物资供给日军，并参与经济封锁抗日根据地。', '山西长治');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b719d68ac60459dfa7fbefb7fbdcd678', 'a945c7f78be75191999fcf09526ad87e', 1938, '伪长治县宣抚班班长', NULL, '随日军进行“宣抚”活动，诱骗群众归顺日伪，破坏抗日政权，多次带领日军突袭村庄。', '山西长治');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5e92137692505d919bc1e76b7fec01de', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '曾任阎锡山部高级将领，后投日，出任伪山西省省长，在长治地区推行日伪统治，协助日军清乡、征粮、镇压抗日力量。', '山西长治');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0b70b40338c75132b90944467a95f4ee', '2b38113bed725cedaecdd9dc8d6365ec', 1938, '伪长治县知事/县长', NULL, '日军占领长治后出任伪县长，组织维持会，为日军提供情报，强征民夫修筑碉堡公路，迫害抗日家属。', '山西长治');
