INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('035b5edc26e5534583e977b71cf67ab2', '61b56ec28fc8552bbb96bcd0bb9dd4c1', 1939, '伪平顺县保安队队长', NULL, '率伪保安队多次配合日军扫荡抗日根据地，抓捕抗日干部和群众，烧毁村庄，抢夺财物，并参与杀害八路军伤员。', '山西长治_平顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b83166dfedd95632b61c2cc816dc6e5f', '23f029abab5a57d0a839a045dad9962c', 1940, '伪平顺县维持会会长', NULL, '为日军筹粮派款，强征民夫，提供情报，并诱骗青年加入伪军，破坏抗日地下组织。', '山西长治_平顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('50d1646cba21503da5243eaa8eff8a08', 'f5a772d6aa0a5576852bb4bc7015d992', 1941, '伪平顺县新民会主任', NULL, '推行奴化教育，宣传“中日亲善”，强迫群众参加反共集会，并协助日军清查抗日家属。', '山西长治_平顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('aaf8ec5314df56f8af4281bd348b7fe4', 'b2cb3b9447ff5e6fb64795a71c198872', 1942, '伪平顺县警察所所长', NULL, '带领伪警察搜捕抗日分子，严刑拷打被捕人员，并参与日军“清乡”行动，杀害多名抗日群众。', '山西长治_平顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ff2e93bcd713537d99393be7eee6e290', '2b5378ecc56d5f4f84f06756e495b505', 1938, '伪平顺县知事', NULL, '日军占领平顺期间出任伪县知事，协助日军推行“治安强化运动”，强征民夫修筑碉堡公路，搜刮粮食资敌，并组织伪警察镇压抗日群众。', '山西长治_平顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fa95846e8f16552d83c1ed2f1c37cc29', 'bfd40f1709945a61b3282a776d9a8a61', 1938, '伪平顺县维持会会长', NULL, '日军首次侵占平顺时组织维持会，为日军带路清乡，指认抗日家属，强迫百姓领取“良民证”，并参与诱降抗日干部。', '山西长治_平顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e9eb90ceffee5a9797c05c63c097fa5f', 'be4eaecc9af056e787d52f2319a57fdc', 1940, '伪平顺县保安队副队长', NULL, '率伪保安队配合日军扫荡抗日根据地，在平顺东部山区烧毁村庄，抓捕抗日民兵，并参与杀害多名抗日村干部。', '山西长治_平顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('54fb578a40ed5367aee4fdaa24e03c78', '717335c4dfa55523a2ab8c89e46c6892', 1941, '伪长治县警备队大队长（活动于平顺边境）', NULL, '长期在平顺、长治交界地带活动，为日军搜集八路军情报，多次带队突袭平顺抗日村庄，抢劫粮食牲畜，并强迫青年加入伪军。', '山西长治_平顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3129d269b656500386be3371ebffe792', 'f8128d92a5455f2886dae039c7903166', 1938, '伪山西省公署顾问', NULL, '原晋绥军将领，投日后任伪山西省公署顾问，协助日军在山西推行‘治安强化运动’，参与对武乡抗日根据地的‘扫荡’策划。', '山西长治_武乡');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('53e30afcd0cd5574a9af61d05ca4645e', '639800ac767a553e8cb106c6e62d7186', 1939, '伪武乡县知事', NULL, '1939年出任伪武乡县知事，组织伪县署，强征民夫修筑公路和碉堡，配合日军多次清乡，抓捕抗日干部和群众。', '山西长治_武乡');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a2908774c74b5b919225f88cf7b1d0ea', 'a395a48f8aa0596da4adb5c008740758', 1940, '伪武乡县保安队队长', NULL, '任伪保安队长，率伪军协助日军袭击八路军后方机关，在武乡东部地区烧杀抢掠，杀害抗日军属多名。', '山西长治_武乡');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2ba4ba1ee32256239abc95b3eabfe2ad', 'c1e2f5df1e235189b5219755fb0dc49f', 1941, '伪武乡县警察所所长', NULL, '负责伪警察所，搜捕抗日地下党员，破坏武乡地下交通站，曾亲自刑讯逼供致多名抗日群众死亡。', '山西长治_武乡');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c8fa0c013c065b7facc7af8d68b423dd', 'e60d0335f96157edb58448797cda6ce0', 1938, '伪长治县知事', NULL, '投日后任伪长治县知事，推行日伪‘保甲制度’，在长治、武乡交界地带建立伪政权，强征粮食支援日军。', '山西长治_武乡');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c26d0addbe315da891e3e0f0f6993568', '61b56ec28fc8552bbb96bcd0bb9dd4c1', 1939, '伪长治县保安团副团长', NULL, '率保安团在长治北部及武乡南部地区‘扫荡’，杀害抗日游击队队员，并参与日军‘三光政策’行动。', '山西长治_武乡');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('444a50a4d90657c185b4a068cd361488', 'fea07466bb9d53d3a13f04dd08cd9a5d', 1940, '伪山西新民会武乡分会会长', NULL, '负责新民会在武乡的宣传活动，鼓吹‘中日亲善’，诱骗青年参加伪军，并收集抗日情报供日军。', '山西长治_武乡');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5578afd2dbd65adf90daf180a95f3c04', '08448280f4165cd383749b86036722e2', 1939, '伪武乡县维持会会长', NULL, '日军占领武乡县城后任维持会长，为日军筹集粮款，强迫村民‘欢迎皇军’，并告密导致多名抗日村长被杀。', '山西长治_武乡');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dcc03f3bb400565c91fe8acae4f32673', '068a2fb66df658e086387e0c265ca6bc', 1941, '伪山西剿共军第二师师长（驻长治地区）', NULL, '率伪剿共军驻防长治、武乡一线，多次参与对太行根据地的进攻，在武乡蟠龙镇一带制造多起惨案。', '山西长治_武乡');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5e91aec58edd5e2c96c26ea64cd37f57', 'e237f0e92533578a8a7eb74e21e10eb6', 1942, '伪武乡县新民会青年训练所主任', NULL, '负责训练伪青年团员，灌输奴化思想，并组织青年协助日军巡逻，破坏武乡抗日群众组织。', '山西长治_武乡');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c18b557310e6571b8df03e0b43e66e97', 'f8128d92a5455f2886dae039c7903166', 1938, '伪山西省公署顾问、伪山西新民会头目', NULL, '原晋绥军将领，投日后任伪山西省公署顾问，协助日军在山西推行“治安强化运动”，参与对武乡等抗日根据地的“扫荡”策划。', '山西长治_武乡');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d766eaa6709f5ab9a4c663bd98f8e70f', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '曾任伪山西省长，在长治、武乡地区推行保甲制度，强征粮食与劳工，配合日军对太行根据地的经济封锁和军事清剿。', '山西长治_武乡');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c9a3f5592b5b5a27bf168734fb0054f8', '2b38113bed725cedaecdd9dc8d6365ec', 1939, '伪长治县知事（县长）', NULL, '任伪长治县知事期间，组织汉奸武装“警备队”，多次引导日军突袭武乡、襄垣交界处的抗日村庄，杀害抗日干部和群众。', '山西长治_武乡');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('92f0dcc4ac4856be809bed46dd1708d1', '142ed91c1ea95b6d922d76d4627e2b83', 1940, '伪武乡县维持会会长', NULL, '在武乡县日军占领区组织维持会，为日军提供情报，强征民夫修筑碉堡和公路，参与“三光政策”下的烧杀抢掠行动。', '山西长治_武乡');
