INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fb2b20741a6b58989f8dea7f85e0b85a', '2afacc26d5e95d5f89e96f3404f7e387', 1938, '沁县伪县长', NULL, '投靠日军后任沁县伪县长，协助日军推行‘治安强化运动’，强征粮税，抓捕抗日军民，破坏地下组织。', '山西长治_沁县');
