INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('265a59d0b326549987ec27d8e30b6a02', '2b38113bed725cedaecdd9dc8d6365ec', 1938, '伪长治县知事', NULL, '日军占领长治后出任伪县知事，组织伪警察和保甲制度，强征粮税，配合日军扫荡，迫害抗日家属。', '山西长治_潞州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e0f6f7b40e225103af5627ea44f7eeb5', 'ea6f46335bd257259394a1581cf6ae85', 1938, '伪潞安府维持会会长', NULL, '日军侵占潞安（今长治）后，主动投靠，任维持会长，为日军筹集物资，指认抗日分子，导致多名地下党员被捕。', '山西长治_潞州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('766bd6135a47539bb7cd46be9c6e883d', 'd34e7c17c41559c79a3fd4e024c4b7e6', 1939, '伪潞城县保安队队长', NULL, '率部投敌，担任伪保安队长，多次配合日军袭击八路军游击队，在潞城、长治一带烧杀抢掠，民愤极大。', '山西长治_潞州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d44a26ce320754f0914b199351a5437d', '61b56ec28fc8552bbb96bcd0bb9dd4c1', 1940, '伪长治县警备队副队长', NULL, '原为地方土匪，后投靠日军，任警备队副队长，负责搜捕抗日群众，曾参与制造多起屠杀事件。', '山西长治_潞州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ecf0ad6dbd535d1c8f8220e739596bcb', 'be4eaecc9af056e787d52f2319a57fdc', 1941, '伪长治县新民会会长', NULL, '为日伪宣传服务，组织“新民会”进行奴化教育，强迫民众参加反共集会，收集抗日情报。', '山西长治_潞州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fa1fe7a0e9235ff9b892f9896e27c012', '5e07c4ed1fc75823aa9f6bfb5f953ed4', 1938, '伪潞州区（原长治县）维持会副会长', NULL, '协助日军建立伪政权，负责摊派粮款，欺压百姓，曾向日军告密导致抗日村长被杀。', '山西长治_潞州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('669a4e21b149506bb2ecad49b6b100d0', '8c5ae5e9fe4f51429ef37abf793edddf', 1939, '伪长治县税务局长', NULL, '为日军征收各种苛捐杂税，中饱私囊，并协助日军控制经济，破坏抗日根据地物资流通。', '山西长治_潞州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3f598a72825e5f9c8343e9da74fb416b', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '曾任阎锡山部高级官员，后投敌任伪山西省长，推行日伪政权统治，协助日军在山西各地（包括长治地区）进行殖民统治和物资掠夺。', '山西长治_潞州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9648d7ba3883517c8d99e024d4944a71', '2b38113bed725cedaecdd9dc8d6365ec', 1938, '伪长治县知事/维持会会长', NULL, '日军占领长治后，出任伪维持会会长及伪县知事，为日军征粮派款，镇压抗日民众，破坏地下抗日组织。', '山西长治_潞州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8bd3133aed215d91bc48fe0b8fc5e006', '142ed91c1ea95b6d922d76d4627e2b83', 1938, '伪蒙古军总司令（曾驻晋东南）', NULL, '虽为蒙奸，但曾率伪蒙古军配合日军在长治、潞州一带进行“扫荡”，烧杀抢掠，协助日军建立伪政权。', '山西长治_潞州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('81e22e9cd9c95ef581473e5c9a5de274', 'f8128d92a5455f2886dae039c7903166', 1941, '伪山西保安副司令（后投敌）', NULL, '原晋绥军将领，1941年被俘后投敌，任伪山西保安副司令，参与对长治、潞州地区抗日根据地的清剿行动。', '山西长治_潞州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('add9405e9ab85660ab03aaba647d5086', 'f0a05b45394f5fcf9e2d9b7b4cbf4e5d', 1940, '伪长治地区警备队长', NULL, '本地地痞出身，投靠日军后任伪警备队长，在潞州一带抓捕抗日军民，强征壮丁，为日军提供情报。', '山西长治_潞州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e7fba10f86085b45b7496394a98c6af4', '142ed91c1ea95b6d922d76d4627e2b83', 1938, '伪襄垣县知事', NULL, '日军占领襄垣后出任伪县知事，协助日军推行“治安强化”运动，强征民夫修筑炮楼，搜刮粮食供日军使用。', '山西长治_襄垣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e97a86aa4f7d5211a7c13e4d94623bf7', '71f249296df65e7d8a9b6fbff4d7d7c3', 1939, '伪襄垣县保安队队长', NULL, '带领伪保安队配合日军扫荡抗日根据地，多次袭击八路军游击队，杀害抗日干部和群众。', '山西长治_襄垣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('531d9c0d34fd541e9bb0b49ce47d3485', '22c3b1ca05ae5b069f4e86515cfbfce9', 1940, '伪襄垣县警察所所长', NULL, '为日军搜集抗日情报，抓捕抗日地下工作者，参与“清乡”行动，迫害无辜百姓。', '山西长治_襄垣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('134a087c198d59d9903c137008077c2e', '1a75e961ae2c5114b5bcaf3ac0442fe0', 1938, '伪襄垣县维持会会长', NULL, '组织维持会为日军征粮派款，强迫村民领取“良民证”，告密抗日积极分子，导致多人被捕牺牲。', '山西长治_襄垣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e8924b14049d586891222f4e482dd909', 'bfd6fa60d8cd5c2bb50d740bab79faab', 1939, '伪襄垣县新民会会长', NULL, '宣传奴化思想，推行“中日亲善”谎言，组织青年参加伪军训练，破坏抗日群众组织。', '山西长治_襄垣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('745c20c4bcb1528bbd43106974884f80', '65b73a139ec85aa8978aedaf6a6787c3', 1941, '伪襄垣县警备队副队长', NULL, '率警备队参与日军“铁壁合围”扫荡，烧毁村庄，抢劫财物，杀害抗日军属。', '山西长治_襄垣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c8eebc59493a5d73937879275ab949c5', 'd20fe59860095766aad2df96c63681d5', 1940, '伪襄垣县税务局长', NULL, '为日军强征各种苛捐杂税，盘剥百姓，将搜刮的物资供给日军，导致民不聊生。', '山西长治_襄垣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('465ba23e14a05eee8c4023c4070ff194', 'e60d0335f96157edb58448797cda6ce0', 1942, '伪襄垣县情报组长', NULL, '专门刺探八路军和游击队活动情报，多次导致抗日武装遭袭，造成重大损失。', '山西长治_襄垣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a6a25bd7336e55249dd8012a462a2a4b', '2b5378ecc56d5f4f84f06756e495b505', 1938, '襄垣县伪县长', NULL, '投靠日军，任襄垣县维持会会长及伪县长，协助日军推行“治安强化”运动，强征民夫，搜刮粮食，镇压抗日群众。', '山西长治_襄垣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4d2d9a2fd4225f3693c2e5934d004156', '5c921e3d243b56ecb74f90581038ff0d', 1940, '襄垣县伪保安队队长', NULL, '组织伪保安队，配合日军扫荡抗日根据地，多次带队袭击八路军游击队，杀害抗日干部和群众。', '山西长治_襄垣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2af58ccd12785d6a9a61b5637bec584f', '3f241dfb90ff51518948ad5c3d297eba', 1941, '襄垣县伪警察局局长', NULL, '效忠日伪政权，负责襄垣县城及周边治安，搜捕抗日地下人员，破坏抗日组织，参与“清乡”行动。', '山西长治_襄垣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5025a308fdd05774bc5cedfc674ce565', 'afdd7c9c8cf457a794610739f1bec55c', 1938, '襄垣县伪维持会副会长', NULL, '协助日军建立伪政权，为日军提供情报，强迫百姓领取“良民证”，并参与征收苛捐杂税。', '山西长治_襄垣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e751a5e024335ef19c848fb5ce5627aa', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令（曾活动于晋东南）', NULL, '原东北军将领，后投日，在山西、绥远等地配合日军扫荡，曾率伪军进入长治、长子一带协助日军清乡，残害抗日军民。', '山西长治_长子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ce491cccd4d95b818a038c9f464cfea9', '2b5378ecc56d5f4f84f06756e495b505', 1937, '伪东亚同盟军总司令（活动于晋冀豫边区）', NULL, '绥西土匪出身，投日后率伪军多次进犯晋东南，在长子、长治地区参与日军“治安强化”行动，抓捕抗日干部。', '山西长治_长子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f4fb46728eed577abd45e8fa8dfc9337', '9e1894b6afc15e9b842958a982c5012d', 1939, '伪山西剿共军第2师师长（驻防长治地区）', NULL, '原国民党军官，叛变投敌后驻防长治、长子，协助日军建立伪政权，强征民夫修筑碉堡，多次带队偷袭抗日根据地。', '山西长治_长子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('01e0d0e27a43524ebeb164698d602501', '7ee6b737ce1d55a9866b5156643815fa', 1940, '伪华北治安军第3集团军司令（活动于晋东南）', NULL, '惯匪出身，投日后率伪治安军驻扎长治周边，参与日军对长子县抗日根据地的“铁壁合围”，屠杀无辜百姓。', '山西长治_长子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c8274b6df75858f981dcfa6c2f01fb77', '04ee0b0ea19655c4985894a5e3f3dd4a', 1941, '伪山西省政府警务厅厅长（管辖长治、长子）', NULL, '负责晋东南伪警体系，在长子县设立多个伪警察所，协助日军搜捕地下党员，破坏抗日组织。', '山西长治_长子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d78bbfca46da51d7a039b587c8ba7f5a', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长（管辖长治、长子地区）', NULL, '作为山西伪政权最高长官，推行保甲制度，在长子县强征粮食和壮丁，支持日军“三光”政策，是长治地区伪政权最高责任人。', '山西长治_长子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d8629dc8959b5b5ab497de2aec311702', 'f0a05b45394f5fcf9e2d9b7b4cbf4e5d', 1939, '伪山西省公署顾问（兼管晋东南）', NULL, '参与策划长治、长子地区“治安肃正”计划，组织汉奸特务刺探八路军情报，协助日军建立“爱护村”监控民众。', '山西长治_长子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a7b556c1c8e35f4eaf8c7b6e7a69dee0', '7987b939a2f5512296c45c13c7af807a', 1938, '伪山西新民会会长（活动于长治）', NULL, '叛徒出身，在长治、长子推行奴化教育，组织“新民会”宣传“中日亲善”，诱骗青年参加伪军。', '山西长治_长子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('302dbb3e049c5985ae9919067ee8edd7', '1e7226376c8a53399d10a5c65c086bf5', 1940, '伪长子县知事（县长）', NULL, '在长子县任伪县长期间，强征苛捐杂税，为日军提供粮食和情报，多次带日伪军包围村庄抓捕抗日家属。', '山西长治_长子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3ca53660f9835029b964d06cd85095a8', '0c6268d47d1656aeaa4e03096f2d60ea', 1941, '伪长子县保安队大队长', NULL, '率伪保安队配合日军在长子县丹朱镇、色头镇等地扫荡，杀害抗日民兵，烧毁民房，民愤极大。', '山西长治_长子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('07f8c978afce549d851d1854586b2c93', '57b3f7e086c05324a1fbd81a9797e6b8', 1939, '伪长治县知事（兼管长子部分区域）', NULL, '在长治、长子交界地区推行“连坐法”，强迫百姓报告八路军行踪，导致多名抗日群众被日军杀害。', '山西长治_长子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('96ad2c59a3435fd3bae7b077fd844360', '66b931c23a085ced9bfccb5bac6f4820', 1942, '伪长治地区警备队指挥官', NULL, '指挥伪警备队在长子县西堡头、南陈等地设卡盘查，截获抗日物资，并参与日军对长子县抗日政府的围剿。', '山西长治_长子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bcfaeb9ebb42566287bb5acda60f85fd', 'c9a7e52fd0eb523bb7dc27de493f596e', 1938, '伪山西省省长', NULL, '曾任阎锡山部将领，投日后任伪山西省长，推行日伪政权统治，协助日军在山西各地建立维持会，镇压抗日力量。', '山西长治_长治高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('76dd1d05dd2e5b178989f82c004583b5', '2b38113bed725cedaecdd9dc8d6365ec', 1938, '伪长治县知事', NULL, '日军占领长治后出任伪县知事，组织伪警察和保甲制度，强征粮食，配合日军扫荡抗日根据地。', '山西长治_长治高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ad77fbc761ed52129a94e3aa9cb7e2aa', 'ea6f46335bd257259394a1581cf6ae85', 1939, '伪长治县保安队队长', NULL, '率伪保安队多次袭击抗日游击队，抓捕抗日军民，烧毁村庄，为日军提供情报。', '山西长治_长治高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('21ea2c137f1f5631ab544acf55e36499', '40763cd48b925562b705c0efe0152e7d', 1938, '伪长治县维持会会长', NULL, '组织维持会为日军筹粮派款，强迫百姓领取“良民证”，协助日军建立伪政权。', '山西长治_长治高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('193bdf9bd4c05de582ad4a2c3a146632', 'd34e7c17c41559c79a3fd4e024c4b7e6', 1939, '伪高平县知事', NULL, '在高平地区推行日伪统治，强征民夫修筑公路和碉堡，镇压抗日活动。', '山西长治_长治高');
