INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7c46b72480cd54d0b02b5d38251864e5', 'a4b6b520415e5c858408bae9e7e4f97d', 1941, '伪盂县自卫团总团长', NULL, '组织伪自卫团，协助日军封锁抗日根据地，参与“三光”政策，杀害无辜群众。', '山西阳泉_盂县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('265386a907565a85a48d41aa09565e1a', 'a7f60614061e5c0c8de452a9a5954a3e', 1938, '伪盂县县长', NULL, '任伪盂县县长期间，积极推行日伪政权，组织维持会，协助日军扫荡抗日根据地，抓捕抗日军民，强征粮税，破坏抗日组织。', '山西阳泉_盂县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('faf717d6876d5809aecf8bca8f192db7', 'e3d1fa3d448c5597835ea70ebfb8fbfd', 1940, '伪盂县保安队队长', NULL, '率伪保安队配合日军多次袭击盂县抗日游击队，杀害抗日干部和群众，参与制造多起惨案，烧毁村庄，掠夺财物。', '山西阳泉_盂县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5f4a72ee20825c2d8f1e6ebeb8620b09', '6f751e18423658f9ab3bd9eec482adb9', 1941, '伪阳泉矿警队队长', NULL, '在阳泉矿区为日军效力，镇压矿工抗日活动，出卖抗日情报，协助日军抓捕地下党员，迫害矿工，克扣口粮。', '山西阳泉_盂县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7f2c1747288e521dbd51f2da6e4f4339', '22c3b1ca05ae5b069f4e86515cfbfce9', 1939, '伪盂县维持会会长', NULL, '组织维持会为日军筹粮筹款，强征民夫修筑炮楼和公路，向日军报告八路军活动线索，导致多处抗日联络点被破坏。', '山西阳泉_盂县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ba493c63e7e453fe81c94abf00defe5b', '068a2fb66df658e086387e0c265ca6bc', 1942, '伪阳泉区公署顾问', NULL, '充当日军顾问，参与策划对盂县、阳泉周边抗日根据地的“清剿”行动，诱降抗日人员，推行“保甲制度”，残害抗日家属。', '山西阳泉_盂县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('59cb1c0a40935cbcabfc1247526f1418', '23f501dac7075660a40e35f451c085d6', 1937, '伪阳泉矿区维持会会长', NULL, '日军占领阳泉后，组织维持会，协助日军征粮派款，镇压矿区抗日工人运动，曾出卖多名地下党员给日军宪兵队。', '山西阳泉_矿区');
