INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0137fcfee7035358a4bf2db60d4c1d0a', '3f241dfb90ff51518948ad5c3d297eba', 1940, '伪阳泉矿区合作社主任', NULL, '垄断矿区粮食和煤炭配给，克扣矿工口粮，将物资低价供给日军，并强迫矿工无偿劳动，从中贪污中饱私囊。', '山西阳泉_矿区');
