INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('01898b15aae75189bd7ba4ec7358ff25', '5b560385786f5ebc9f8f38276f67ad6f', 1937, '伪保定绥靖公署主任、伪河北省保安司令', NULL, '原北洋军官，投日后在保定组织伪军，参与围剿八路军冀中根据地，残害抗日军民。', '河北保定');
