INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d600a6e888c651c1ab927702f6c9fffd', '0cfa5cb121bd5e43ad3cf2fdadaaf14a', 1939, '伪保定县知事（县长）', NULL, '任伪保定县长期间，强征民夫修筑炮楼公路，向日军提供情报，迫害抗日家属。', '河北保定');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5a51c268803753319102c15e47698899', 'f507817e989158b6a3fd828c617b43cd', 1937, '伪华北政务委员会内政总署督办（曾驻保定活动）', NULL, '虽籍贯安徽，但长期在华北包括保定活动，主持伪政权，推行奴化教育，协助日军经济掠夺。', '河北保定');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('406a783a45225e158ef188d3c953ecb9', '469663dcf9c45273982bd02b6777f23f', 1939, '伪华北治安军第1集团军司令', NULL, '原为八路军冀中军区第10军分区司令员，1939年叛变投敌，在保定地区组建伪军，多次配合日军扫荡白沟新城及周边抗日根据地，杀害抗日军民数百人。', '河北保定_保定白沟新城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c26f199e5f2555bdb80259a5f935f503', 'b7851a2bb17955198176ccbac07d2d06', 1940, '伪保定道尹公署保安司令', NULL, '原国民党地方武装头目，投日后任保定地区伪保安司令，在白沟新城、高碑店一带设立据点，残酷镇压抗日群众，制造多起惨案。', '河北保定_保定白沟新城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('193f4e9cbee6544dbca70b677ad6e704', 'fc815e0e8db55008a8a6914b42626e67', 1941, '伪河北省警备处副处长兼保定地区清乡督察', NULL, '在保定及白沟新城推行“保甲连坐”制度，组织汉奸特务队，多次突袭抗日村庄，逮捕并杀害抗日干部及家属。', '河北保定_保定白沟新城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('121be1751b7d5529adedb5b077ff2c3f', 'ad0c9f9af10054c68d58a879c97add74', 1942, '伪华北政务委员会保定办事处主任', NULL, '原国民党河北省民政厅长，投日后负责保定地区伪政权行政事务，协助日军强征粮食、劳工，在白沟新城一带破坏抗日地道。', '河北保定_保定白沟新城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('75228d62ead85956a6ab4e5c465bd7ce', '96dffd6ec2e55bbdaacbfb739c2f6186', 1938, '伪白沟河维持会会长', NULL, '白沟新城本地恶霸，投日后任维持会长，为日军提供抗日情报，勒索商户，多次带日军搜查白沟河两岸村庄，致使数十名群众遇害。', '河北保定_保定白沟新城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f8923ce961345ff4a4618fef0a49065b', '1c5a5b4b57a35e3887780282d0b228d6', 1940, '伪保定宪兵队特高课翻译兼密探队长', NULL, '原为保定商人，投日后充当日军翻译，组建密探网，在白沟新城、容城、雄县等地诱捕抗日志士，直接参与刑讯逼供。', '河北保定_保定白沟新城');
