INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('07617aa78d8c502184d091b0058104c2', '6a1825c9473c582cb2e94ddd1fee54b1', 1939, '伪曲阳县知事（县长）', NULL, '投靠日军后任伪县长，积极推行日伪“治安强化”运动，强征民夫修筑炮楼和封锁沟，配合日军扫荡，镇压抗日活动。', '河北保定_曲阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ac0f8807a77e5a1585162cec26a4972f', 'ddb23c0430b05c31ba42342c0fe96e71', 1940, '伪曲阳县警备大队长', NULL, '率伪警备队多次参与对抗日村庄的围剿，抓捕并杀害抗日军民，抢劫财物，烧毁房屋，民愤极大。', '河北保定_曲阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4f65fbd7e559549184b73bedd678ff05', '149dcf8873e359459d3e861031b92afc', 1941, '伪曲阳县新民会会长', NULL, '为日军宣传奴化思想，组织汉奸情报网，刺探抗日军情，协助日军搜捕抗日分子。', '河北保定_曲阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5e9480054d135df0bda068be854d86f4', '199710bc8f1e5a34b6cbbce6003dac9e', 1942, '伪曲阳县便衣队队长', NULL, '带领便衣汉奸队专门暗杀抗日干部和积极分子，多次袭击区小队，破坏抗日组织，罪行累累。', '河北保定_曲阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fdeba29907d353f3b11efd7d2984b32a', 'e60d0335f96157edb58448797cda6ce0', 1939, '伪曲阳县警察局局长', NULL, '效忠日军，管理伪警察，协助日军抓捕抗日群众，严刑拷打逼供，破坏地下党组织。', '河北保定_曲阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1a7f0c89d97058a3ac850c576126eafc', 'd638c9a7248352f4a7c8aa1ae0217119', 1937, '伪曲阳县维持会会长（早期）', NULL, '日军侵占曲阳后率先组织维持会，为日军筹粮派款，提供劳役，帮助日军建立伪政权。', '河北保定_曲阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f645077fceee5235826b181108cc496e', 'fe9baa21e645508fb3e434958f34d048', 1940, '伪曲阳县税务局长', NULL, '为日军强征各种苛捐杂税，盘剥百姓，资助伪军和日军军费，并参与经济封锁抗日根据地。', '河北保定_曲阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3ed231cd1a9c5648a07463588a212038', '0839e283a4685e9a8a2b24d93945e7c4', 1941, '伪曲阳县自卫团团长', NULL, '组织伪自卫团，配合日军“清乡”，在曲阳北部山区多次袭击八路军游击队，杀害抗日家属。', '河北保定_曲阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('63e3118e5dc15ea9a14527bfa1fe4724', '4799a9ceeb0c5afd9dca86b400626c92', 1942, '伪曲阳县情报站站长', NULL, '专门收集八路军和抗日政府情报，多次导致抗日干部被捕牺牲，是日军在曲阳的重要耳目。', '河北保定_曲阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6617003854d0547691ce00f5a0408410', '7caaf63588be5c8ca34ab9ae8bd818bb', 1937, '伪曲阳县知事', NULL, '投靠日军，任曲阳县伪政权首脑，协助日军推行‘治安强化运动’，强征民夫修筑炮楼据点，镇压抗日群众。', '河北保定_曲阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8ee88f1b5ce858709f96394c93e616db', '19fb47a898685fbb9631c8b660b6a8f2', 1939, '伪曲阳县保安联队队长', NULL, '组织伪保安队配合日军扫荡曲阳抗日根据地，多次带队袭击村庄，杀害抗日干部和群众，抢劫粮食资敌。', '河北保定_曲阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5ba7c71845d757a5a5443b932dbf1956', '2bef98aae3795ef983d374377d02823f', 1940, '伪曲阳县警察所所长', NULL, '充当日军耳目，建立特务情报网，抓捕抗日军民，破坏地下党组织，参与制造多起惨案。', '河北保定_曲阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5d22856200495eb48b3b3dd071970803', '1654e28f47635e1db34fb2f806df6939', 1941, '伪曲阳县新民会会长', NULL, '为日军推行奴化教育，组织‘新民会’宣传‘中日亲善’，强迫群众参加反共集会，协助日军征粮派款。', '河北保定_曲阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c15b446f7aac52bca521dfb73710cde9', '469663dcf9c45273982bd02b6777f23f', 1938, '伪冀中保安队司令', NULL, '原为八路军冀中军区第10军分区司令员，1940年叛变投敌，在望都、定县一带组建伪军，多次配合日军扫荡抗日根据地，杀害抗日干部和群众。', '河北保定_望都');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('923fdd2e4cfe55239f4fc29cf55d192e', 'ad0c9f9af10054c68d58a879c97add74', 1938, '伪河北省保安司令（后投敌）', NULL, '原国民党河北民军总指挥，后与日军勾结，在冀中地区（含望都）破坏抗日组织，袭击八路军后方机关，制造摩擦事件。', '河北保定_望都');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5c5e6bc09ef25f798a17a15420d81f68', 'fc815e0e8db55008a8a6914b42626e67', 1939, '伪望都县知事', NULL, '任伪望都县知事期间，推行保甲制度，强征民夫修筑炮楼和封锁沟，配合日军清乡，多次组织伪警抓捕抗日家属。', '河北保定_望都');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b646272e8f735984b9b1d2b459497cb9', '19fb47a898685fbb9631c8b660b6a8f2', 1940, '伪望都县保安联队队长', NULL, '率伪军驻守望都各据点，多次参与对抗日根据地的“扫荡”，烧毁村庄，抢劫粮食，并杀害多名八路军侦察员。', '河北保定_望都');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f03e8f30ac7a5df389d636aff847af2e', 'f7f8040dcded5eeda38e25c365225d63', 1941, '伪望都县警察所所长', NULL, '在望都县城内建立特务情报网，侦捕抗日地下党员，严刑逼供，导致多名抗日人员牺牲或被捕。', '河北保定_望都');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d6243b492e165824afb9a9e3d727ef6a', '1c5a5b4b57a35e3887780282d0b228d6', 1942, '伪冀中道尹公署参事（分管望都）', NULL, '参与策划望都地区“治安强化运动”，推行“自首”政策，诱降部分意志不坚定者，破坏地方党组织。', '河北保定_望都');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1c86cbf52f06521eafea61020b9f0d54', '72ff70842aed5327ae57a9ccc7bf806b', 1940, '伪望都县新民会会长', NULL, '利用新民会宣传奴化思想，组织“青少年团”为日军搜集情报，并强迫民众参加“庆祝会”欢迎日军。', '河北保定_望都');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6f741d1bb755567488a58b66f0036af6', 'c0346f29d2825ca4bf79008332dc76bb', 1943, '伪军大队长（驻望都）', NULL, '率伪军驻守望都西关，多次突袭周边村庄，抢劫牲畜和粮食，并参与杀害冀中军区第十分区交通员。', '河北保定_望都');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bd32ca38dd9a57ce9d0a86185587671e', 'a4b6b520415e5c858408bae9e7e4f97d', 1943, '伪新五军军长（活动范围含冀中）', NULL, '原国民党将领，1943年投敌，其部队曾调防冀中地区，在望都一带协助日军“扫荡”，但主要活动在豫北，与望都关联有限。', '河北保定_望都');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e389e1ba247b5e38afaadbe4dd6664a2', '0ec2ee6fed265ec5991932a6ff128192', 1943, '伪第五方面军总司令（名义上辖冀中）', NULL, '投敌后任伪职，其势力范围名义上包括冀中，但实际未直接驻军望都，仅通过伪政权间接控制。', '河北保定_望都');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c4f2eb327dfe5118a77502b3e11ab500', '469663dcf9c45273982bd02b6777f23f', 1937, '伪冀东保安队司令、伪保定道尹', NULL, '原为国民党地方武装头目，后投靠日军，任伪冀东保安队司令，在保定、望都一带协助日军“扫荡”，残害抗日军民，后任伪保定道尹，推行日伪统治政策。', '河北保定_望都');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8f980f73cedd57e2ba7a3cfa0cab6156', 'b7851a2bb17955198176ccbac07d2d06', 1938, '伪望都县知事、伪河北省保安队副司令', NULL, '曾任伪望都县知事，在望都县内强征粮税、抓捕抗日人员，组织伪警备队配合日军清乡，后升任伪河北省保安队副司令，继续在保定地区镇压抗日活动。', '河北保定_望都');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6072588263345d409546517653baef0f', '7caaf63588be5c8ca34ab9ae8bd818bb', 1937, '伪望都县维持会会长', NULL, '日军占领望都后，率先组织维持会，为日军提供粮秣、民夫情报，协助建立伪政权，并参与诱降抗日分子，破坏当地地下党组织。', '河北保定_望都');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7ef9c6b188f3580aa4a64a996cbfea5b', 'fc815e0e8db55008a8a6914b42626e67', 1940, '伪保定道公署顾问兼望都县保安联队队长', NULL, '原为土匪头目，投日后任望都县保安联队队长，多次率部袭击八路军游击队，在望都、清苑边界制造“无人区”，杀害抗日家属，并配合日军进行“治安强化运动”。', '河北保定_望都');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1a40353d55ce5fb4b9ff06d7fa1b38a9', '469663dcf9c45273982bd02b6777f23f', 1938, '伪涞水县保安联队队长', NULL, '原为地方武装头目，投日后任伪保安联队队长，多次配合日军扫荡涞水山区，捕杀抗日干部和群众，制造多起惨案。', '河北保定_涞水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('58bc4c2906595f44b945bc08a11c54b6', 'b7851a2bb17955198176ccbac07d2d06', 1940, '伪涞水县警备大队大队长', NULL, '率伪军驻守涞水县城及重要据点，参与日军“治安强化”运动，搜捕抗日军民，破坏地下组织，抢劫粮食物资。', '河北保定_涞水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('956995e2965e55f499151cdbc487a6c5', '8320e3e3065f5f31a864a1fd27201ca3', 1941, '伪涞水县新民会会长', NULL, '负责在涞水推行奴化教育，组织“新民会”宣传亲日思想，强迫民众参加反共集会，协助日军征粮派夫。', '河北保定_涞水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('aca7a66a7ac05aaa805469ad055c96ae', '4de5af157ba75f47b2ca9a19b2691125', 1939, '伪涞水县警察所所长', NULL, '指挥伪警察特务，侦缉抗日活动，逮捕进步人士，刑讯逼供，向日军提供情报，参与“清乡”行动。', '河北保定_涞水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('39ff61b05fe05ad5ac56b1a64a5e44b0', '39d432c291145512a4678090a21e497d', 1937, '伪涞水县维持会会长', NULL, '日军占领涞水初期，组织维持会，为日军筹粮筹款，强征民夫修路筑堡，协助建立伪政权。', '河北保定_涞水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('64f4a6a01651502092781c3dc1793967', 'ebbb0f7c117a52c2bd61747296a39dc4', 1942, '伪涞水县自卫团团长', NULL, '率自卫团配合日军封锁山区，袭击八路军游击队，杀害抗日家属，抢夺群众牲畜和粮食。', '河北保定_涞水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d82824e3758c5e0eb553127197b2cb6d', '98b5ef0fa3fd582990f25a664c57e2df', 1943, '伪涞水县特务队队长', NULL, '专门从事特务活动，跟踪、绑架抗日干部，破坏地下交通线，多次带队突袭村庄抓捕“嫌疑分子”。', '河北保定_涞水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b62ae705f91c52fba87fe4f2278371ee', 'e60d0335f96157edb58448797cda6ce0', 1940, '伪涞水县财政科科长', NULL, '为伪政权征收各种苛捐杂税，强征“治安费”“慰劳金”，贪污勒索，加重民众负担，资助日军军费。', '河北保定_涞水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5d13c9f73fc15122b6cd3c4386df239c', '9b0436fb47615db386551fba69ea63bb', 1941, '伪涞水县教育督学', NULL, '推行日伪奴化教材，强迫学校悬挂日伪旗帜，检举抗日师生，导致多名教师被捕。', '河北保定_涞水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7b8baf5033635b7d84b3a2c04cb25a04', '93d67a250cd5581fb5abfe6a6343c97a', 1942, '伪涞水县情报站站长', NULL, '建立情报网络，向日军报告八路军活动规律，导致多次伏击失败，造成抗日武装重大损失。', '河北保定_涞水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('07585ea77cc558cdbe68a1912049ca1d', '7caaf63588be5c8ca34ab9ae8bd818bb', 1937, '涞水县伪县长', NULL, '投靠日军，任涞水县伪县长，协助日军推行“治安强化运动”，强征民夫、粮食，镇压抗日群众。', '河北保定_涞水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('efc651f5bf245099a2cadaf4094998bb', '98f434e5c4be544dbf5b4ac887efc5c9', 1938, '涞水县伪保安联队长', NULL, '组织伪保安队，配合日军扫荡抗日根据地，多次袭击八路军游击队，杀害抗日干部和群众。', '河北保定_涞水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ca9d5159bf7157aa91a4b3f4bf869086', '8320e3e3065f5f31a864a1fd27201ca3', 1939, '涞水县伪警察所长', NULL, '任伪警察所长，抓捕抗日地下工作者，破坏中共地下组织，参与“清乡”行动。', '河北保定_涞水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2acc3be4142e573db8fa3746f743c624', 'b7851a2bb17955198176ccbac07d2d06', 1940, '保定地区伪军头目（活动于涞水一带）', NULL, '率伪军驻防涞水、易县交界，多次参与对晋察冀根据地的“扫荡”，烧杀抢掠，民愤极大。', '河北保定_涞水');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7b778433daaf59768c61847f7e6c9d66', '469663dcf9c45273982bd02b6777f23f', 1938, '伪涞源县保安联队队长、伪华北治安军第3集团军第6团团长', NULL, '原为八路军晋察冀军区第1军分区第5支队支队长，1939年12月叛变投敌，率部袭击抗日政权，杀害多名抗日干部，后任伪军团长，在涞源、易县一带配合日军扫荡，制造多起惨案。', '河北保定_涞源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('42d23e9959fb57bd8e81b93cd153f0e7', 'b7851a2bb17955198176ccbac07d2d06', 1940, '伪涞源县警备大队大队长', NULL, '原为地方土匪头目，投靠日军后任伪警备大队长，在涞源县内抓捕抗日军民，严刑拷打，直接参与杀害八路军侦察员和村干部，并强征民夫修筑碉堡。', '河北保定_涞源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1bae92c23d5e5c24bd4675659a5d9487', 'd638c9a7248352f4a7c8aa1ae0217119', 1939, '伪涞源县知事（县长）', NULL, '投靠日伪政权，任涞源县伪知事，推行保甲制度，组织维持会，强征粮食和劳役，配合日军“治安强化”运动，镇压抗日群众，破坏地下党组织。', '河北保定_涞源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a9d004af80b25cc8b5f339e27cabe738', '13a79375295e59ecb8912c2038082de2', 1937, '伪涞源县维持会会长（早期）', NULL, '日军侵占涞源后率先组织维持会，为日军提供粮草、向导，协助建立伪政权，并煽动民众投降，后随日军行动，参与清乡。', '河北保定_涞源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f23f5a2622c85558bf5b57a1dbbdea70', 'f7f8040dcded5eeda38e25c365225d63', 1941, '伪涞源县警察所所长', NULL, '任伪警察所长期间，指挥伪警搜捕抗日家属，破坏交通线，多次带队突袭村庄，抢劫财物，并参与杀害被俘的八路军伤员。', '河北保定_涞源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c2c44c5a4c9e5f3ba0d7ef2afc060e3b', '5ba9b438aa8057fe971e7bd39b052daf', 1940, '伪涞源县新民会会长', NULL, '负责日伪“新民会”在涞源的活动，推行奴化教育，组织“青少年团”刺探抗日情报，并协助日军诱降抗日人员。', '河北保定_涞源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('db441c1077af5774bb75f8c4b1279507', 'ebbb0f7c117a52c2bd61747296a39dc4', 1942, '伪涞源县保安队中队长', NULL, '原为国民党溃兵，投日后任伪中队长，多次率队袭击八路军游击队驻地，在走马驿、银坊等地杀害抗日群众，烧毁房屋。', '河北保定_涞源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3973bd6137a259f4ac0d36f87ead1866', '4bacf28daf7a51cba530244f54f1310b', 1943, '伪冀察战区挺进军第24集团军总司令（驻涞源周边）', NULL, '虽主要活动于豫北，但其部队曾窜扰涞源地区，与日军勾结，接受伪职，其下属部队在涞源北部山区劫掠抗日村庄，抓捕壮丁。', '河北保定_涞源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('06d0f3dbc62054a596ffca5b6276c4d7', '0ec2ee6fed265ec5991932a6ff128192', 1943, '伪河北省保安司令（名义上管辖涞源）', NULL, '1943年投降日军后任伪职，其势力范围波及保定西部山区，曾派伪军协助日军对涞源根据地进行“扫荡”，但本人未常驻涞源。', '河北保定_涞源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3e768e32789b5b7d81918fccbbeea2d3', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1939, '伪华北治安军总司令（管辖涞源伪军）', NULL, '作为华北伪军最高指挥官，其下属部队多次在涞源地区与八路军作战，指挥“治安肃正”行动，间接导致涞源多起屠杀事件。', '河北保定_涞源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eedc6889a048559cb0f9e71993f9e72a', 'b7851a2bb17955198176ccbac07d2d06', 1937, '涞源县伪县长', NULL, '投靠日军，任涞源县伪县长，协助日军推行“治安强化运动”，强征民夫修筑炮楼据点，镇压抗日群众，多次配合日军扫荡抗日根据地。', '河北保定_涞源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4b43be5ddad754c19e6c3ce324a1a5c0', 'd02150065ff25117aa9938dedd0a98c0', 1938, '伪涞源县保安联队队长', NULL, '组织伪保安队，为日军提供情报，参与“清剿”八路军游击队，残害抗日干部和家属，制造多起惨案。', '河北保定_涞源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('093f53f0aa4d5f0c86761d742169cd7f', '9494e09b1a915350bd4d2799937e05e3', 1939, '伪涞源县警察所所长', NULL, '效忠日军，指挥伪警察搜捕抗日分子，破坏地下交通站，勒索百姓，协助日军建立保甲制度，强化殖民统治。', '河北保定_涞源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('926b98649dca57eb84324d0848b3b60d', 'a40ba5601ad25ab1b1616a9e7ec8e7c0', 1940, '伪涞源县新民会会长', NULL, '为日军推行奴化教育，组织“新民会”宣传“中日亲善”，诱骗青年参加伪军，搜集抗日情报，破坏群众抗日组织。', '河北保定_涞源');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1cf506011a7e5efca93de9fb38063067', 'b7851a2bb17955198176ccbac07d2d06', 1937, '伪涿县县长、伪保安队队长', NULL, '投靠日军后任涿县伪县长，组织伪保安队镇压抗日民众，配合日军扫荡，残害抗日干部和家属。', '河北保定_涿州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('62a1164d26a75511a79cd74870566134', '04bd5021cbb1577da2ff048830b10305', 1938, '伪涿县警备队大队长', NULL, '率伪警备队多次袭击抗日根据地，抓捕并杀害八路军侦察员和地下党员，烧毁村庄。', '河北保定_涿州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('396d4c2de42e5a088b6c818e9e4139e6', 'fc815e0e8db55008a8a6914b42626e67', 1939, '伪保定道尹公署顾问', NULL, '原国民党地方官员，投敌后任伪保定道顾问，协助日军推行“治安强化运动”，在涿州一带强征民夫、掠夺粮食。', '河北保定_涿州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2e654abafafa59879b4e77687c9bc4b4', '469663dcf9c45273982bd02b6777f23f', 1940, '伪华北治安军第18团团长', NULL, '原土匪武装头目，投日后改编为治安军，驻防涿州、固安一带，多次参与“清剿”八路军，屠杀抗日群众。', '河北保定_涿州');
