INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('286345550f3e52b9be829ebc7bf0aa73', 'b7851a2bb17955198176ccbac07d2d06', 1940, '伪满城县警备大队大队长', NULL, '率伪警备大队多次突袭满城西部山区抗日村庄，烧杀抢掠，并参与制造多起惨案。', '河北保定_满城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('453e43ea372258da885293bb8b501060', 'f7f8040dcded5eeda38e25c365225d63', 1941, '伪满城县新民会会长', NULL, '负责在满城推行奴化教育，组织“新民会”宣传亲日思想，强迫民众参加反共集会。', '河北保定_满城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('54b523464b8a51a8b231cb35c44bd779', '316cc483865057089895b48829218edb', 1942, '伪满城县警察局局长', NULL, '指挥伪警察搜捕抗日家属，严刑逼供，破坏地下交通站，导致多名抗日干部牺牲。', '河北保定_满城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e47412c860bf53f988fe6fe2e6566d72', '948107882bd159d6a1053331b9f59ed2', 1940, '伪满城县第一区区长', NULL, '在满城城关一带为日军征粮派夫，告密抗日积极分子，致使数名群众被杀害。', '河北保定_满城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('aef5b044b26c54beb1b256b310b95a26', 'a4b6b520415e5c858408bae9e7e4f97d', 1943, '伪冀察战区挺进军暂编第2军军长（活动于满城周边）', NULL, '虽为军阀出身，但1943年后公开投敌，其部队在满城、易县一带配合日军“清剿”，劫掠百姓。', '河北保定_满城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('735fb65f29f354c9ae66339b98ab1ccc', '08a1ec477255562bb8a0e3fe6556bf8f', 1940, '伪华北治安军第1集团军总司令（曾驻防保定满城地区）', NULL, '反复无常，最终投日，其部队在保定、满城一带参与“治安强化运动”，围剿八路军。', '河北保定_满城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('659ee7f9cf5e5a6f8b08063c63ef5542', '0ec2ee6fed265ec5991932a6ff128192', 1943, '伪第24集团军总司令（活动范围含满城）', NULL, '1943年投降日军，所部在冀西包括满城地区协助日军防守据点，进攻抗日武装。', '河北保定_满城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f0db57fbe8335db68d8c973811a534dc', '0dd3beb27d8b597baf7b6be86e893586', 1942, '伪第2方面军总司令（曾率部在保定满城一带驻防）', NULL, '率伪军数万人在冀中、冀西地区包括满城，配合日军进行“铁壁合围”扫荡。', '河北保定_满城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('92b5dffb6f2a5086a589360d939326ad', '469663dcf9c45273982bd02b6777f23f', 1937, '伪满城县保安联队队长、伪满城县政府顾问', NULL, '原为满城地方武装头目，后投靠日军，任伪保安联队队长，协助日军扫荡抗日根据地，捕杀抗日干部和群众，制造多起惨案。', '河北保定_满城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('de1054481eea5457ba84bd0bc387d3f9', 'decde3a9e5125b99a93cb5e72fc89072', 1938, '伪满城县知事（县长）', NULL, '任伪满城县知事期间，推行日伪保甲制度，强征粮食和民夫，配合日军“治安强化运动”，镇压抗日活动，破坏地下党组织。', '河北保定_满城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e90e4db4298857a2970f5492aee1c985', 'fc815e0e8db55008a8a6914b42626e67', 1939, '伪满城县警备大队长', NULL, '率伪警备队多次袭击满城山区抗日游击队，杀害抗日军属，参与日军“三光”政策行动，烧毁村庄多处。', '河北保定_满城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3d4de2a8e643505d8db5f271887f8bd6', '5d539abf99b357b2867c31ebe6513848', 1940, '伪满城县新民会会长', NULL, '为日伪宣传效劳，组织“新民会”进行奴化教育，诱骗青年参加伪军，搜集抗日情报提供给日军。', '河北保定_满城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('14dd2a78135353b59fc727f659d2a859', '469663dcf9c45273982bd02b6777f23f', 1937, '伪河北省保安队司令、伪保定道尹', NULL, '原为土匪，后投靠日军，任伪河北省保安队司令，在保定地区残酷镇压抗日军民，制造多起血案，后任伪保定道尹，协助日军推行“治安强化运动”。', '河北保定_竞秀');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5b369bf5011a5e1aa249ee5fd60f34ad', '132ca09a10c5518383fc783d3db3266b', 1939, '伪华北治安军第1集团军司令', NULL, '原为国民党军军官，投敌后任伪华北治安军第1集团军司令，驻防保定一带，多次率部“扫荡”冀中抗日根据地，杀害抗日干部和群众。', '河北保定_竞秀');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('25b8a880de565deabb1bb6ba613dabf9', '316ac7ce2af5541e82177cfb3eec52dd', 1938, '伪保定市市长', NULL, '任伪保定市市长期间，积极推行日伪政权各项政策，强征民夫，搜刮粮食，协助日军建立保甲制度，镇压抗日活动。', '河北保定_竞秀');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3380733f2fb75603a51af7e8edfd41ff', 'f507817e989158b6a3fd828c617b43cd', 1937, '伪华北政务委员会内政总署督办（曾驻保定）', NULL, '虽为华北级汉奸，但多次到保定视察督导，推动伪政权在保定地区的建立，支持日军清乡和“三光”政策。', '河北保定_竞秀');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d2e6e4bc14745d45b3c52432786d05bb', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北治安军总司令（曾驻保定指挥）', NULL, '作为华北伪军最高指挥官，多次在保定地区部署“扫荡”行动，其部队在竞秀区（原保定城西）一带杀害抗日志士。', '河北保定_竞秀');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('014ea6892be559d39f17ba5c76467bc4', '0f9718e2185859ad9a2919936bdc4e66', 1938, '伪保定县知事', NULL, '任伪保定县知事期间，为日军提供情报，组织伪警察抓捕抗日地下党员，强征劳工送往东北。', '河北保定_竞秀');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7771ad93f8a55ca28f8f7188a6ae3353', 'fc815e0e8db55008a8a6914b42626e67', 1940, '伪保定保安队大队长', NULL, '率伪保安队配合日军在竞秀区及周边村庄进行“清剿”，烧毁民房，抢掠财物，杀害抗日家属。', '河北保定_竞秀');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('812fefe9c9ec56b4ba88a91bae290114', 'f72173b0ff9052c191ceae63e940cc31', 1939, '伪保定警察局局长', NULL, '主持伪警察局，设立特务机构，破坏中共地下组织，逮捕并刑讯抗日人士，直接参与多起屠杀事件。', '河北保定_竞秀');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d5bbb2ef2b4c5c838123ce4a99862b8b', 'f507817e989158b6a3fd828c617b43cd', 1937, '华北政务委员会内政总署督办、伪河北省省长', NULL, '原北洋政客，投日后任伪华北政务委员会要职，在保定、莲池一带推行日伪统治，镇压抗日力量，协助日军进行经济掠夺和奴化教育。', '河北保定_莲池');
