INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1264ca5572265d14b56e32ef9161b077', '190dabfac9075fad8821b4606545bb75', 1937, '伪保定市维持会会长、伪保定道尹', NULL, '保定本地士绅投敌，组织维持会迎接日军，后任伪保定道尹，为日军提供情报，强征民夫，破坏莲池书院等文化场所。', '河北保定_莲池');
