INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b90fc833bc0d5684b5fe4ac0e720f327', '132ca09a10c5518383fc783d3db3266b', 1942, '伪保定绥靖军司令', NULL, '指挥伪军配合日军对蠡县进行多次大扫荡，实行“三光”政策，造成大量平民伤亡。', '河北保定_蠡县');
