INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9f19c20c3e215674b5a2005f0d53519e', 'a4b6b520415e5c858408bae9e7e4f97d', 1943, '伪新五军军长（活动于冀中）', NULL, '原国民党军阀，投日后在冀中一带活动，其部队参与围剿蠡县抗日游击队。', '河北保定_蠡县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3feef817315957eea60f36d3edbf5f15', 'b2e08518b85d5648aa0d76e9f152d677', 1944, '伪第二集团军司令（曾驻保定）', NULL, '率伪军驻扎保定地区，配合日军对蠡县进行军事清剿，强征民夫修筑工事。', '河北保定_蠡县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('40d87b4404795420ac00478bcbd396e6', 'bc18fe5ce9665dd19c23a3c03acad179', 1941, '伪蠡县警察局局长', NULL, '负责伪警察系统，搜捕抗日地下党员，破坏交通联络站，多次带队突袭村庄。', '河北保定_蠡县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b6299d5bf47853e18ac304e424906604', '5ddb13935d765e6f8714d41d4654e1c7', 1931, '伪冀东防共自治政府保安队队长、伪满军旅长', NULL, '原为东北军军官，后投靠日军，在冀中地区协助日军清剿抗日武装，1938年因内部矛盾被处决。', '河北保定_蠡县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('efe63d8189c15362bae3c632298b65cc', 'ad0c9f9af10054c68d58a879c97add74', 1938, '伪河北省政府民政厅长（后投敌）', NULL, '原国民党将领，后投靠日伪，在保定、蠡县一带组织伪政权，协助日军推行“治安强化运动”，迫害抗日群众。', '河北保定_蠡县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('05bbb1c297095738995a0e1a70e4f458', 'b7851a2bb17955198176ccbac07d2d06', 1939, '伪蠡县保安联队队长', NULL, '蠡县本地人，组建伪保安队，多次配合日军扫荡蠡县抗日根据地，杀害多名抗日干部和群众。', '河北保定_蠡县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('57dcc19620755b88b2ac31fc84b98634', 'fc815e0e8db55008a8a6914b42626e67', 1940, '伪保定道尹公署顾问', NULL, '原为保定士绅，投日后任伪职，参与策划对蠡县、高阳等地的“清剿”行动，强征民夫修筑炮楼。', '河北保定_蠡县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7587d747670659b5bb261cf15c1547dd', '469663dcf9c45273982bd02b6777f23f', 1941, '伪冀中剿共军第一师师长', NULL, '原为八路军冀中军区某部叛徒，后投靠日军，在蠡县、博野一带活动，多次袭击抗日武装，制造“赵庄惨案”。', '河北保定_蠡县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('42eee9a8b95b567fa348805802c7b5ae', '469663dcf9c45273982bd02b6777f23f', 1938, '伪华北治安军第1集团军司令', NULL, '原为八路军晋察冀军区第3军分区第10大队大队长，1939年叛变投敌，在阜平、唐县一带组织伪军，多次配合日军扫荡抗日根据地，杀害抗日干部和群众。', '河北保定_阜平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cc3e9fd7b10b5525ac147bf0224f75a0', 'ad0c9f9af10054c68d58a879c97add74', 1938, '伪河北省保安司令（后投敌）', NULL, '原国民党河北民军总指挥，在阜平、曲阳一带与八路军摩擦，后公开投敌，协助日军建立伪政权，破坏抗日组织。', '河北保定_阜平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5f60074d533a5ce3ba294b500aa770ea', '8320e3e3065f5f31a864a1fd27201ca3', 1937, '伪阜平县维持会会长', NULL, '日军占领阜平后出任维持会长，为日军征集粮草、派夫修路，指认抗日积极分子，导致多名地下党员被捕牺牲。', '河北保定_阜平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e69ec0e09b2255e2983d0e9b557ba83d', 'b7851a2bb17955198176ccbac07d2d06', 1940, '伪阜平县警备队队长', NULL, '率伪警备队多次突袭阜平周边村庄，烧毁民房，抢掠物资，并参与制造“平阳惨案”等屠杀事件。', '河北保定_阜平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5de16cb47b8a54d791e9b90c5f8153fd', '5ae0b0684cc4589db47453bfb3b3708c', 1939, '伪保定道尹公署顾问', NULL, '原阜平士绅，投敌后为日军提供阜平山区地形情报，协助策划对晋察冀军区机关的围剿行动。', '河北保定_阜平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('895d4db5c82a51cd8f33571a5f9ed049', '68139bf5da4659cb84fd1528c8758bab', 1941, '伪阜平县新民会会长', NULL, '推行奴化教育，强迫群众参加“反共救国”集会，搜集抗日情报，并参与诱降八路军基层干部。', '河北保定_阜平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6249fe4d9d165412afd30f4a50037abe', '3a0537dcb964559cbe7de5f03f88f7c1', 1942, '伪华北治安军第2集团军第5旅旅长', NULL, '驻防阜平、涞源一带，多次率部袭击八路军后方医院，杀害伤病员和医护人员，并参与“无人区”制造。', '河北保定_阜平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8884dc8e212a5c839220c1d51a03d3db', '2273b5f4e2e957b8970ec8f875c19e08', 1943, '伪阜平县保安团团长', NULL, '配合日军进行“清剿”，在阜平城南庄等地抓捕抗日家属，严刑逼供，勒索钱财，并强征壮丁补充伪军。', '河北保定_阜平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5b232472c4685355917e2346f90805d9', '469663dcf9c45273982bd02b6777f23f', 1938, '伪阜平县保安联队队长、伪阜平县政府顾问', NULL, '原为八路军晋察冀军区某部干部，1938年叛变投敌，组建伪保安队，多次配合日军扫荡阜平抗日根据地，抓捕杀害抗日干部和群众，破坏地方党组织，罪行累累。', '河北保定_阜平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3ccc9860e5c3507dbe25bfe570a030a0', 'ad0c9f9af10054c68d58a879c97add74', 1938, '伪河北省政府民政厅长（后投敌）、河北民军总指挥（叛变前）', NULL, '原国民党将领，在阜平、保定一带活动，后公开投靠日军，协助日军建立伪政权，组织武装袭扰抗日武装，参与“曲线救国”反共活动，对阜平根据地造成破坏。', '河北保定_阜平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('808dd070862f5d9b8dec00b2142979d9', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北政务委员会治安总署督办、伪华北绥靖军总司令', NULL, '作为华北伪军最高头目，其指挥的伪治安军多次在保定、阜平地区参与“扫荡”，围剿八路军，烧杀抢掠，是阜平一带抗日军民的主要敌伪军事力量之一。', '河北保定_阜平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1468dfdc71025fb081d6e091b1e31d6a', 'f507817e989158b6a3fd828c617b43cd', 1937, '伪华北政务委员会委员长', NULL, '伪华北政权首脑，在保定、阜平推行“治安强化运动”，组织保甲制度，强征粮食，配合日军对阜平抗日根据地进行经济封锁和军事清剿。', '河北保定_阜平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('67b3bc0d41fa52e2927d7d5a8dcd36dd', '5b560385786f5ebc9f8f38276f67ad6f', 1938, '伪河北省保安司令、伪冀东保安队头目', NULL, '在保定、阜平周边地区组织伪保安队，多次参与对阜平山区的“讨伐”，杀害抗日军民，并协助日军建立情报网，破坏地下抗日组织。', '河北保定_阜平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f0a977095ece59a2bac49b7cb714f91e', 'b7851a2bb17955198176ccbac07d2d06', 1937, '伪雄县县长', NULL, '投靠日军，任伪雄县县长，推行保甲制度，强征民夫，协助日军扫荡抗日根据地，残害抗日军民。', '河北保定_雄县');
