INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7a537c780d7d555fba8bd5df97388e9e', '316cc483865057089895b48829218edb', 1940, '伪雄县警备大队长', NULL, '率伪警备队多次袭击八路军游击队，破坏抗日组织，勒索百姓，民愤极大。', '河北保定_雄县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('32c2dbcc04465751a7f81a6c30b88e0b', '469663dcf9c45273982bd02b6777f23f', 1941, '伪华北治安军独立团长（活动于雄县一带）', NULL, '原为抗日武装头目，后叛变投敌，率部驻防雄县，参与日军“治安强化运动”，围剿抗日武装。', '河北保定_雄县');
