INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('845a5d34272a520790fdef11af09cf4f', 'e4112c8cc52e50e9aaf2da197ce5569b', 1942, '伪雄县特务队长', NULL, '充当日军特务，专门刺探八路军情报，带领日伪军突袭村庄，杀害抗日积极分子。', '河北保定_雄县');
