INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('79a334caa50f5d3c8c402eb1d0dc2fbc', '3a7b5940ec4b5bc684b90652e901811b', 1940, '伪雄县警备大队长', NULL, '充当日军爪牙，率伪军频繁袭击八路军游击队，破坏地下党组织，残害抗日家属，勒索百姓财物。', '河北保定_雄县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3f70e60c517f578489de28d84d66dd16', '316cc483865057089895b48829218edb', 1941, '伪雄县新民会会长', NULL, '推行日伪奴化教育，组织汉奸宣传队，强迫群众参加“反共”集会，搜集抗日情报提供给日军。', '河北保定_雄县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7e5943ecd86a5e659f690644064eb456', '469663dcf9c45273982bd02b6777f23f', 1942, '伪雄县自卫团团长', NULL, '原为地方武装头目，后公开投敌，率自卫团协助日军封锁交通线，参与“清乡”行动，杀害多名抗日积极分子。', '河北保定_雄县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('046cbab7e200515a9de72c2277d89648', '469663dcf9c45273982bd02b6777f23f', 1938, '伪华北治安军第1集团军司令', NULL, '原为八路军晋察冀军区第3军分区游击军司令，1939年叛变投敌，在易县、满城、顺平（完县）一带配合日军扫荡，残害抗日军民，制造多起惨案。', '河北保定_顺平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f76af06cddeb5726874bb31b1b259c18', '3f9b986d40525a7784eb5032a6b5d8eb', 1938, '伪顺平县（完县）知事', NULL, '任伪完县县长期间，推行保甲制度，强征粮饷，协助日军建立据点，抓捕抗日干部，破坏地下组织。', '河北保定_顺平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2128fb626b4e5d9089301506b044572a', 'b7851a2bb17955198176ccbac07d2d06', 1940, '伪保安联队队长', NULL, '在顺平、唐县交界地带活动，率伪军多次突袭抗日村庄，杀害区村干部，烧毁民房，被当地群众称为“王阎王”。', '河北保定_顺平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bafd95007261597ba2ec3e9ee9238607', 'fba619d17c1452b583893a4e40d787f8', 1941, '伪顺平县警备大队副大队长', NULL, '原为抗日游击队干部，1941年被俘后变节，供出多处秘密粮库和交通站，导致多名交通员牺牲。', '河北保定_顺平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('64267ba1d16457a7a3664ec87b81b4d3', '81cb8b5127065a1fb7bd3039f7e332c3', 1939, '国民党河北民军总指挥（后投日）', NULL, '虽名义上抗日，但多次与八路军摩擦，1942年后其部属在顺平一带与日军暗中勾结，提供情报，协助清剿。', '河北保定_顺平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('315fe479b3ff5e94811eea2774ca9ad0', 'b7851a2bb17955198176ccbac07d2d06', 1937, '伪高碑店保安联队长、伪新城县警备队长', NULL, '在高碑店及周边地区组织伪军，多次配合日军扫荡抗日根据地，残害抗日军民，制造多起惨案。', '河北保定_高碑店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a20f7e45b33150edae2870e968f2bb6a', 'fc815e0e8db55008a8a6914b42626e67', 1938, '伪河北省保安司令部参议、伪保定道尹公署顾问', NULL, '原为国民党地方官员，投敌后协助日军在保定地区推行“治安强化运动”，参与清乡和特务活动。', '河北保定_高碑店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('799ad4a892a450608a81db4e24e01f19', '0f9718e2185859ad9a2919936bdc4e66', 1937, '伪高碑店维持会会长', NULL, '日军占领高碑店后率先组织维持会，为日军征粮派款，提供情报，帮助日军建立伪政权。', '河北保定_高碑店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d94d07df950a58959c6765629d62b758', '805dcb001bbe5f8782dcde83d247d210', 1939, '伪新城县知事（县长）', NULL, '在任期间积极推行日伪政策，强征民夫修筑炮楼和公路，镇压抗日群众，向日军提供抗日人员名单。', '河北保定_高碑店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('68ecd07bc8625e0c972ba5111438dce8', 'a3eb8307fd6a5cd5a48713eabac55d34', 1940, '伪保定绥靖军第3集团军第6旅旅长', NULL, '率伪军驻防保定及高碑店一带，多次参与对八路军冀中根据地的进攻，烧杀抢掠，民愤极大。', '河北保定_高碑店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f9f28953b3ba568d8342deeb94b56762', '68139bf5da4659cb84fd1528c8758bab', 1941, '伪高碑店警察署署长', NULL, '指挥伪警察搜捕抗日地下工作者，破坏地下交通站，严刑拷打被捕人员，致死多人。', '河北保定_高碑店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('07074c7726b25371a35b89f530205c0e', 'a4b6b520415e5c858408bae9e7e4f97d', 1943, '伪新编第5军军长（曾驻防保定周边）', NULL, '原国民党将领，1943年投敌后所部在保定、高碑店一带活动，配合日军“扫荡”，并参与诱降国民党军队。', '河北保定_高碑店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('140c3219853459c2ba99a8316a69bb61', '0ec2ee6fed265ec5991932a6ff128192', 1943, '伪第24集团军总司令（曾辖保定地区伪军）', NULL, '投敌后任伪职，其部队在河北保定地区协助日军维持治安，参与对抗日武装的围剿。', '河北保定_高碑店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3120719ce5d95543b1fb7e0382d16a56', '132ca09a10c5518383fc783d3db3266b', 1942, '伪冀中剿共军司令', NULL, '率伪军在高碑店、定兴、新城等地反复“清剿”，杀害抗日干部和群众，掠夺财物。', '河北保定_高碑店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('82f78c1ff86e5376aa825171c36cba27', '57b3f7e086c05324a1fbd81a9797e6b8', 1938, '伪高碑店新民会会长', NULL, '负责在占领区推行奴化教育，组织“新民会”宣传“中日亲善”，刺探抗日情报，协助日军抓壮丁。', '河北保定_高碑店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c5472bd975fd552fb967ef4aeee6bcce', 'b7851a2bb17955198176ccbac07d2d06', 1937, '伪高碑店保安联队长、伪定兴县警备队长', NULL, '在高碑店、定兴一带组织伪军，多次配合日军扫荡抗日根据地，残害抗日军民，制造多起血案。', '河北保定_高碑店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0c55be2c9e7252a1862a5d3568100e56', '469663dcf9c45273982bd02b6777f23f', 1940, '伪华北治安军第20团团长（原冀中军区第6军分区司令员，后叛变）', NULL, '原八路军干部，1940年叛变投敌，在高碑店、涿州、新城一带充当日军帮凶，出卖抗日组织，率伪军袭击抗日武装。', '河北保定_高碑店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2b51cbd64018541194732b81c93f7f6f', 'ad0c9f9af10054c68d58a879c97add74', 1938, '伪河北省保安司令（名义上，实际活动于冀中）', NULL, '虽为国民党顽固派，但在高碑店地区与日军暗中勾结，破坏抗日统一战线，其部队曾配合日军围剿八路军。', '河北保定_高碑店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0930f33ff0445c0fb697d46b17dc500c', 'fc815e0e8db55008a8a6914b42626e67', 1939, '伪新城县（今高碑店市）知事', NULL, '任伪县长期间，推行保甲制度，强征粮款，为日军提供情报，镇压抗日群众，协助日军建立维持会。', '河北保定_高碑店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('233a8243442e5a87a4889344c68ecef7', '629954bc42a05671bfe89a32ffe10591', 1937, '伪高碑店维持会会长', NULL, '日军占领高碑店后率先投敌，组织维持会，为日军筹集物资，指认抗日分子，导致多名地下党员被捕牺牲。', '河北保定_高碑店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f1d3561498155b03ab98c2ffec62e408', 'ad0c9f9af10054c68d58a879c97add74', 1938, '国民党河北民军总指挥（后投敌）', NULL, '原国民党将领，后与日伪勾结，在冀中地区破坏抗日力量，协助日军扫荡高阳、博野一带，残害抗日军民。', '河北保定_高阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b46fd5461298536c83a56ed0ee5e0971', 'b7851a2bb17955198176ccbac07d2d06', 1940, '伪高阳县保安联队队长', NULL, '率伪军多次配合日军对高阳抗日根据地进行“清剿”，抓捕并杀害抗日干部和群众，烧毁村庄，罪行累累。', '河北保定_高阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a7568be77ae55493bd8c1bd28ea24f8a', 'b44e6f5042525c0381b62a6442432fb1', 1941, '伪高阳县警备大队长', NULL, '充当日军爪牙，在高阳境内设卡盘查，搜捕八路军情报员，参与制造多起惨案，如“北辛庄惨案”。', '河北保定_高阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2c702bdd962859e0bc3d6a3106a82e48', 'c23b448023765698868dea186bde4ad6', 1942, '伪高阳县新民会会长', NULL, '为日军推行“治安强化运动”，组织汉奸宣传队，强迫民众参加“反共”集会，提供抗日人员名单，导致多名地下党员被捕。', '河北保定_高阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bbcd7713dc6655919d97b6c55dbafbc5', '5bf6dbd0cc795afab4181a1b8f6fef90', 1937, '伪保定道公署顾问兼高阳维持会会长', NULL, '日军侵占高阳后率先投敌，组织维持会，为日军征粮派夫，协助建立伪政权，并出卖当地抗日积极分子。', '河北保定_高阳');
