INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5aca84585a8a53d5a778345ec708f482', 'e2903b8085cc595dbd15aedb7003a94c', 1943, '伪新编第五军军长（有争议，实际未长期驻高阳）', NULL, '虽主要活动于河南，但曾派部队配合日军扫荡冀中高阳地区，其下属伪军在当地有扰民行为。', '河北保定_高阳');
