INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6266cf1d5ce152eb938c35bc08e03c60', '503de500a44b531d918af851527aadf1', 1935, '伪冀东防共自治政府民政厅长', NULL, '负责伪政权在冀东地区的民政事务，在丰润、唐山等地推行日伪统治政策，强征民夫修筑公路和军事设施。', '河北唐山_丰润');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('43b8a020288e57d4b1a60898393a4056', '340adba25424535985417eba5e18abbe', 1935, '伪冀东防共自治政府财政厅长', NULL, '为伪政权筹措经费，在唐山、丰润地区加征苛捐杂税，搜刮民财，支持日军侵略战争。', '河北唐山_丰润');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bceabafdedbf5d0ab832e5d5a8fec956', '3720970371315007b5ae28dc02cc15c3', 1938, '伪丰润县知事（县长）', NULL, '在丰润县任伪职期间，积极推行日伪“治安强化运动”，组织伪警察和保甲武装，配合日军扫荡抗日根据地，残害抗日军民。', '河北唐山_丰润');
