INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d70067eacc565cbe87b69250b9a8d88b', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府秘书长、代理政务长官', NULL, '殷汝耕主要助手，参与伪政府行政运作，在唐山地区推行保甲制度，协助日军镇压抗日力量。', '河北唐山_唐山汉沽管理');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f7506479c522590c90ca57143b0c96f9', 'c1ba15e6cdf55fd7891106db4277da0d', 1935, '伪冀东防共自治政府外交处长', NULL, '负责与日本关东军联络，参与签订卖国协定，为日军在唐山、汉沽等地驻军和掠夺资源提供便利。', '河北唐山_唐山汉沽管理');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3c3ca184dff150c69b72ad34faab5e6c', '503de500a44b531d918af851527aadf1', 1935, '伪冀东防共自治政府民政厅长', NULL, '主管伪政权民政事务，在唐山各县推行日伪户籍管理，强征劳役，协助日军建立伪乡村政权。', '河北唐山_唐山汉沽管理');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3e8429c8d1cf5a0bbf9989e2e9d4f311', '340adba25424535985417eba5e18abbe', 1935, '伪冀东防共自治政府财政厅长', NULL, '为伪政权筹措经费，征收苛捐杂税，将唐山地区盐税、矿税等收入用于日军军需。', '河北唐山_唐山汉沽管理');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('989036cbf5535aec8cbdfa86a8d68706', '3720970371315007b5ae28dc02cc15c3', 1935, '伪冀东防共自治政府教育厅长', NULL, '推行奴化教育，在唐山、汉沽等地学校强制教授日语，删改历史教材，灌输“中日亲善”思想。', '河北唐山_唐山汉沽管理');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ac049b650b445eb4bbfce3b80a85972d', 'f1bc5258a2755a94b57a483a9c673bc6', 1935, '伪冀东防共自治政府建设厅长', NULL, '负责为日军修建公路、碉堡和军事设施，在唐山沿海地区强征土地，破坏抗日根据地交通。', '河北唐山_唐山汉沽管理');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('df9d4931c55859618e5361fddaa02296', '6edb269a696555c193c5c25b9caf01c3', 1935, '伪冀东保安队司令', NULL, '率伪保安队配合日军在唐山、丰润、汉沽一带“扫荡”，屠杀抗日军民，制造多起惨案。', '河北唐山_唐山汉沽管理');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('de3bbf3bbaf5567e941f250a1896471e', '09a43f86f2b5580c80262d0857a985bf', 1936, '伪冀东保安队副司令、伪唐山警备司令', NULL, '长期驻守唐山，协助日军清乡，抓捕抗日志士，镇压开滦煤矿工人罢工，参与“治安强化运动”。', '河北唐山_唐山汉沽管理');
