INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9f74058485145532ae594cf755de3f64', '0c6268d47d1656aeaa4e03096f2d60ea', 1938, '伪开滦煤矿矿警队队长（唐山）', NULL, '镇压矿工反抗，为日军控制开滦煤矿提供武力支持，迫害进步工人。', '河北唐山_唐山海港经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6211eec071e557e8b3bdc72ef03b5329', '64cd6973a53a573988b1719436273d16', 1939, '伪唐山宪兵队翻译官', NULL, '为日军宪兵队充当翻译，参与刑讯逼供抗日志士，罪行累累。', '河北唐山_唐山海港经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b2c00cca400558739d005780f9c8c66e', '25403a79f8335f3e96fc8451f78bbb99', 1940, '伪唐山“治安军”团长', NULL, '率部在唐山周边“清乡”，烧毁村庄，抢夺财物，杀害抗日家属。', '河北唐山_唐山海港经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9de95a20a6685b0a822bdeb4502b6ad6', '8971710d07f853e88929efbf675bcaed', 1942, '伪冀东“反共救国军”司令（活动于唐山沿海地区）', NULL, '在唐山海港经开区（今京唐港一带）沿海地区袭扰抗日武装，为日军运输护航。', '河北唐山_唐山海港经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('afa3cca5752154939d8f6a30e70d3de4', 'b7851a2bb17955198176ccbac07d2d06', 1941, '伪唐山地区“保甲”总联保长', NULL, '推行保甲连坐制度，强迫百姓举报抗日分子，导致多人被捕牺牲。', '河北唐山_唐山海港经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d310c0ea833750adbafffcf0a58ba590', '670555e204c055cd90041cdd7d49d5b5', 1939, '伪滦县县长（管辖今海港经开区部分区域）', NULL, '在滦县及沿海地区强征粮税，配合日军“扫荡”，镇压当地抗日游击队。', '河北唐山_唐山海港经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('31a2961763555b22a77d8d514fdd88fc', '3a4ecd9e70b4504b8f47bc4eb0ad0e18', 1940, '伪乐亭县县长（今海港经开区部分区域曾属乐亭）', NULL, '在乐亭沿海一带组织伪政权，协助日军封锁海岸线，破坏抗日交通。', '河北唐山_唐山海港经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3cce92804c31588bbbc3d0d4631a09f3', '1f3ceb58c5b25ba1ad0d8cdd75aa724b', 1938, '伪丰润县县长（唐山辖区）', NULL, '在丰润推行日伪统治，多次配合日军围剿冀东八路军，制造无人区。', '河北唐山_唐山海港经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9a1242011bf65940b25e32089661fe34', '141511aa2e9350709c42bd21c2395472', 1940, '伪唐山“新民会”青少年团长', NULL, '组织青少年进行军事训练，灌输亲日思想，为日军培养伪军后备力量。', '河北唐山_唐山海港经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6cd174c60ee6532f9fd630cf2e254bb5', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府政务长官', NULL, '1935年11月在通州成立伪冀东防共自治政府，辖冀东22县（含唐山、芦台一带），推行日伪统治，协助日军镇压抗日力量。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('abfa972d80275d5c9cca9b80315d40c3', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府秘书长/代理政务长官', NULL, '殷汝耕的主要助手，参与伪冀东政府行政运作，在唐山地区推行奴化教育和经济掠夺。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5468ce35b487557da3185f63b8fa1f47', '6edb269a696555c193c5c25b9caf01c3', 1935, '伪冀东保安队司令', NULL, '原为冀东保安队头目，投日后任伪司令，在唐山、芦台一带协助日军清乡，镇压抗日游击队。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('886529dd7dd055efaa307e18eab9215b', '33f48787d6295324995de4d2f715fb78', 1935, '伪冀东自治政府顾问/伪华北治安军高参', NULL, '唐山丰润人，早年投靠日军，参与组建伪冀东政权，后任伪治安军高参，在唐山地区招募伪军，配合日军扫荡。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1316d475d61b5a56a85f57521a326130', '99afd279f9bb50b2b65b52b289c8e71d', 1935, '伪冀东保安队第一总队队长（后反正）', NULL, '原冀东保安队军官，投日初期在唐山地区维持伪秩序，1937年通州事变中反正，但此前在唐山、芦台一带执行伪职。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ac03bdbab4695cc0be02d06516ac88b7', '6f9c44c820815521b2d42b6fcc7b005d', 1935, '伪冀东保安队第二总队队长（后反正）', NULL, '与张庆余类似，投日期间在唐山、芦台地区参与伪政权军事活动，后反正。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7a55a776da7f5c308e475e1245ae2b86', '801d6d8b0d9958d685ad7892948df677', 1935, '伪冀东防共自治政府唐山办事处主任', NULL, '在唐山市区设立伪办事处，管理民政、税收，配合日军控制唐山工矿企业，镇压工人抗日活动。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3d915ae7aad156fb98e90384519f57c3', '6cfb68638ff354acb2c330bf9e7ecdfd', 1937, '伪唐山商会会长', NULL, '投靠日伪，组织商会为日军筹措军费，强征物资，协助日伪经济统制，在唐山芦台一带盘剥商户。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('22ec5eb47420536d9abd967662057649', 'bdc65b94361955e98916b39f842b9e00', 1938, '伪唐山警察局局长', NULL, '在唐山市区及芦台地区建立伪警察网络，搜捕抗日志士，破坏地下组织，执行日军“治安强化”政策。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0f539fce96c85155af30de523f26c3d7', '132ca09a10c5518383fc783d3db3266b', 1939, '伪冀东剿共军司令', NULL, '率伪军驻防唐山、芦台一带，多次参与对冀东抗日根据地的围剿，屠杀平民，烧毁村庄。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7d22a9b44f2d512893bdc1dcc4af70c3', '76a98f532b95578e93e65bd668324e32', 1941, '伪冀东特别行政区公署顾问', NULL, '原东北军军官，投日后任伪顾问，在唐山地区策划“治安肃正”，建立保甲制度，强迫民众“连坐”。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a3f9300a4aac503db95502f0b97a72c2', '3f227cbbf3cf5ad685e893c899c0087f', 1937, '伪芦台镇维持会会长', NULL, '在芦台镇（今芦台经开区一带）组织维持会，为日军提供粮食、劳力和情报，协助镇压当地抗日武装。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cf78e98f41da5cc89bb233a9417d4720', 'a4b6b520415e5c858408bae9e7e4f97d', 1943, '伪冀察战区挺进军总司令（后投日）', NULL, '1943年投敌，任伪军职，其部队活动范围涉及唐山、芦台周边，配合日军进攻抗日根据地。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1f6fac9d750b57dfa4073d172eaf20b0', '0ec2ee6fed265ec5991932a6ff128192', 1943, '伪第五方面军总司令（投日）', NULL, '1943年投日，所部在冀东包括唐山地区参与“扫荡”，为日军提供伪军支援。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0958d6a5d23f5272aa10f9488aa1a7d9', '0dd3beb27d8b597baf7b6be86e893586', 1942, '伪第二方面军总司令（投日）', NULL, '投日后其部队曾调至冀东，在唐山、芦台一带协助日军维持占领区秩序。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('391cc07a0d0a53d998840c69b6b568a5', '190dabfac9075fad8821b4606545bb75', 1938, '伪冀东道尹', NULL, '任伪冀东道尹，管辖唐山、芦台等县，推行日伪行政，强征壮丁，掠夺资源。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('01d9f4eff47a53ac8245c790c75d99b2', '5ecdb6b22c615e368ffe537daaadad8f', 1940, '伪唐山矿区保安大队长', NULL, '在唐山开滦矿区组织伪保安队，镇压矿工罢工，为日军控制煤炭资源效力。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6d1acb275ed85742a8e4616d0fe75c74', '340adba25424535985417eba5e18abbe', 1940, '伪华北政务委员会唐山专员', NULL, '负责唐山地区日伪政务，推行“新民会”奴化宣传，协助日军进行经济统制。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5367e67fc32a556e8bb9a1eca52fee3f', 'f507817e989158b6a3fd828c617b43cd', 1940, '伪华北政务委员会委员长（涉及唐山地区）', NULL, '作为华北伪政权最高头目，其政策直接覆盖唐山、芦台，支持当地伪政权镇压抗日活动。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('57eac8afca905b03912ef4c0da7afa0a', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1939, '伪华北治安军总司令（涉及唐山）', NULL, '指挥伪治安军在唐山、芦台地区多次“清剿”，杀害抗日军民，是冀东地区主要伪军头目。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6cd174c60ee6532f9fd630cf2e254bb5', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府政务长官', NULL, '1935年11月在通州成立伪冀东防共自治政府，管辖包括唐山、芦台在内的冀东22县，推行亲日政策，配合日军经济掠夺和治安维持。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('abfa972d80275d5c9cca9b80315d40c3', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府秘书长/代理政务长官', NULL, '协助殷汝耕管理伪政权，在唐山地区推行保甲制度，镇压抗日活动，征收苛捐杂税供日军使用。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('03cfe0bf23cd577b897ccacdc36f5a0f', 'c1ba15e6cdf55fd7891106db4277da0d', 1935, '伪冀东防共自治政府唐山办事处主任', NULL, '在唐山地区为日军征粮派夫，建立伪警察机构，破坏中共地下组织，协助日军控制唐山矿区。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5468ce35b487557da3185f63b8fa1f47', '6edb269a696555c193c5c25b9caf01c3', 1935, '伪冀东保安队司令', NULL, '率伪保安队驻防唐山、芦台一带，多次围剿抗日游击队，参与制造镇压民众事件，后随伪政权并入华北伪政府。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e1bbfae0da66516ca1015727449d458a', '33f48787d6295324995de4d2f715fb78', 1935, '伪冀东防共自治政府顾问/伪军头目', NULL, '在唐山、芦台地区组织伪军武装，协助日军清乡，抓捕抗日军民，并参与经济统制，垄断当地食盐和粮食贸易。', '河北唐山_唐山芦台经开区');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ae70f126fd3f501e945749c3e96fbd70', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '冀东防共自治政府政务长官', NULL, '1935年11月在通州成立冀东防共自治政府，辖冀东22县（含唐山、丰润、滦县等地），公开投日，推行奴化教育，协助日军镇压抗日力量。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7e95e79f9c2b5ab3a30d97c13d6f83a7', 'be830f2d60665f0189881935079af216', 1935, '冀东防共自治政府秘书长/代理政务长官', NULL, '殷汝耕的主要助手，参与冀东政府运作，后接替殷汝耕主持伪政府，协助日军在冀东地区征粮、抓夫、建立保甲制度。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('27e541a5ba535bfbb079d5179eeb3110', '6edb269a696555c193c5c25b9caf01c3', 1935, '冀东保安队第一总队队长', NULL, '原为国民党军警，投日后任冀东保安队队长，驻防唐山一带，协助日军清剿抗日游击队，参与镇压冀东抗日暴动。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2dce361c6b735ec3bf6dbf70213a2e3a', '33f48787d6295324995de4d2f715fb78', 1935, '冀东保安队第二总队队长', NULL, '投靠日军后负责唐山地区治安，多次率部袭击冀东抗日联军，杀害抗日军民，后随伪政府改编。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('78dab74348e259c582effc9087c5afde', '99afd279f9bb50b2b65b52b289c8e71d', 1935, '冀东保安队第三总队队长（后反正）', NULL, '初期为冀东伪保安队军官，驻防通州，曾参与镇压抗日活动，但1937年通州事变中反正，击杀日军，后脱离伪职。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('92ce669de1fb58809862f6de71e3fae3', '6f9c44c820815521b2d42b6fcc7b005d', 1935, '冀东保安队第四总队队长', NULL, '伪冀东保安队军官，驻防冀东地区，参与维持伪政权统治，后随通州事变反正。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b4efba4dd7ac55c5806a67178fc6c218', '5ecdb6b22c615e368ffe537daaadad8f', 1936, '伪冀东政府唐山办事处主任', NULL, '在唐山地区推行伪政府法令，组织汉奸团体，协助日军收集情报，镇压当地抗日活动。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3d20f1dd8a8f5d6aa4b16091c6e52443', '6cfb68638ff354acb2c330bf9e7ecdfd', 1937, '伪唐山商会会长', NULL, '投靠日军，控制唐山商会，为日军筹集物资、摊派捐款，强迫商户悬挂伪旗，迫害爱国商人。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('aaca732cd75054c8a2a5fdeefc00225f', '801d6d8b0d9958d685ad7892948df677', 1935, '伪冀东自治政府警务厅长', NULL, '负责冀东伪警察系统，在唐山、滦县等地建立伪警察所，抓捕抗日分子，协助日军进行“清乡”。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fdf5faee0c9a58048b63df86006a79ee', '34d52a037a3f502485c1096ba7c18521', 1938, '伪丰润县知事', NULL, '在丰润县（今属唐山市）推行伪政权，组织“自卫团”配合日军扫荡，强征民夫修筑炮楼，残害抗日家属。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bf0d52e0c7d55c0daf81cb75427a28d7', 'f145c20197cc5cebbd6f995535fc8252', 1939, '伪滦县知事', NULL, '在滦县（今属唐山市）任伪县长，积极为日军提供粮食和情报，参与“治安强化运动”，杀害多名抗日群众。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('548695e54f885459b35e99b53ef3b001', '340adba25424535985417eba5e18abbe', 1940, '伪冀东道尹（驻唐山）', NULL, '作为伪河北省冀东道行政长官，驻唐山，统辖冀东各县伪政权，推行保甲连坐，组织汉奸武装“反共自卫团”。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('06672a19010152ca991851d88f6c1dc6', '76a98f532b95578e93e65bd668324e32', 1941, '伪冀东绥靖军司令', NULL, '原东北军军官，投日后任伪绥靖军司令，驻唐山，率伪军多次进攻冀东八路军根据地，制造多起惨案。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e77283beb9515b3a9f114720faa0058f', 'fe417281717f53fcb1eebd0f820af04b', 1938, '伪唐山警察局局长', NULL, '在唐山市区任伪警察局长，残酷镇压工人罢工和学生运动，逮捕并刑讯抗日地下工作者。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7f2fad2a87b75ec3ab88f137ab8ac11a', '0c6268d47d1656aeaa4e03096f2d60ea', 1942, '伪唐山地区“剿共”司令', NULL, '组织汉奸武装，在唐山周边村庄进行“扫荡”，烧杀抢掠，杀害八路军伤员和村干部。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('23b37ebfc38659989a61d700161f34fd', '805dcb001bbe5f8782dcde83d247d210', 1940, '伪高各庄（今属唐山高地区）维持会会长', NULL, '在唐山高各庄一带组织维持会，为日军带路，提供抗日人员名单，协助日军屠杀村民。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('61503752df28525b82ff3f31d4b74771', 'a4b6b520415e5c858408bae9e7e4f97d', 1943, '伪冀东保安司令（后投敌）', NULL, '原国民党将领，1943年投日，任伪冀东保安司令，驻唐山，率部配合日军“扫荡”，但后期有动摇。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bfdff87ee0d85334b5193e020ef691e1', '68139bf5da4659cb84fd1528c8758bab', 1938, '伪唐山矿务局督办', NULL, '管理唐山煤矿，强迫矿工为日军生产煤炭，克扣工资，镇压矿工罢工，致多起矿难。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9de374900f9d52d5b4a0a6dd02ee1308', '35df3a396910569cae6b5fcde72b99a7', 1939, '伪唐山教育督办', NULL, '推行奴化教育，强制学校教授日语，删改历史教材，迫害爱国教师，组织学生参拜神社。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bfb87ec7762d5034965fded5515c017d', 'd9a514f9cc9b5dc39e4b19b63e0bbd39', 1941, '伪唐山高地区联防队长', NULL, '在唐山高地区（今开平区一带）组织伪联防队，配合日军“清乡”，杀害抗日积极分子，抢夺民财。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2ce27479816259279d55c94c23825493', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府政务长官', NULL, '1935年11月在通州成立伪冀东防共自治政府，管辖包括唐山、冀东22县，推行亲日政策，协助日军控制冀东地区，征收苛捐杂税，镇压抗日活动。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fa7a3b34e6295294be9bee2eac366f19', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府秘书长、代理政务长官', NULL, '殷汝耕的主要助手，参与伪冀东政府运作，后代理政务长官，协助日军在唐山地区推行保甲制度，强征民夫，掠夺资源。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('616b4c24c32a55fd8483ff39ff4960f8', 'c1ba15e6cdf55fd7891106db4277da0d', 1938, '伪唐山地区行政督察专员', NULL, '在唐山地区任伪职，为日军“治安强化运动”服务，组织伪警察和保甲，搜捕抗日军民，强征粮食和劳工，支持日军对冀东抗日根据地的扫荡。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('27a954234d0451118eb00c80a1be45da', '6edb269a696555c193c5c25b9caf01c3', 1937, '伪冀东保安队司令、伪唐山保安司令', NULL, '原冀东保安队头目，投日后任伪保安司令，驻防唐山及周边，配合日军清乡，多次参与围剿冀东八路军游击队，残害抗日群众。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2eef7fbc8f815615ae579895d61f8535', '33f48787d6295324995de4d2f715fb78', 1935, '伪冀东自治政府委员、伪唐山维持会会长', NULL, '唐山地方士绅投敌，组织维持会，协助日军建立伪政权，为日军筹粮筹款，破坏抗日组织，后任伪冀东政府委员。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a8537ecfae8e59ab96243b3afbc8c692', '6cfb68638ff354acb2c330bf9e7ecdfd', 1938, '伪唐山警察局局长', NULL, '统领伪唐山警察，执行日军命令，大肆搜捕抗日地下党员和爱国人士，实施“连坐”制度，协助日军进行经济封锁。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c5bc022bf94354ebad80e6e1b6aa7909', '801d6d8b0d9958d685ad7892948df677', 1938, '伪冀东剿共军司令', NULL, '在唐山高地区（今唐山高新区一带）活动，组织伪军“剿共”，配合日军扫荡，烧杀抢掠，破坏抗日根据地。', '河北唐山_唐山高');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ef3944ee64d158d1ae1234cce2a4b790', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府政务长官', NULL, '1935年11月在通州成立冀东防共自治政府，管辖包括唐山、开平在内的冀东22县，公开投敌，为日军提供粮饷和劳役，镇压抗日活动。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('21fae0e3ff4058a093e58bfef0728af5', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府秘书长、代理政务长官', NULL, '协助殷汝耕管理伪政府，在唐山地区推行奴化教育，强征民夫修建军事设施，配合日军清乡。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a359113e2b1b552795d4ea5477743128', 'c1ba15e6cdf55fd7891106db4277da0d', 1935, '伪冀东防共自治政府民政厅长', NULL, '负责伪政府民政事务，在开平、丰润等地推行保甲制度，协助日军建立伪基层政权，迫害抗日家属。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9e7c79dfb5615b089d6805ff4f9cb296', '6edb269a696555c193c5c25b9caf01c3', 1935, '伪冀东保安队第一总队队长', NULL, '率部驻防唐山、开平一带，多次配合日军扫荡抗日游击队，抓捕并杀害抗日军民，制造多起惨案。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b7f25bbcd963585e986545929e46063b', '09a43f86f2b5580c80262d0857a985bf', 1935, '伪冀东保安队第二总队队长', NULL, '在唐山地区协助日军维持治安，参与镇压1938年冀东抗日大暴动，屠杀暴动群众。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('96d685223fa454e290109c3329db46d3', '99afd279f9bb50b2b65b52b289c8e71d', 1935, '伪冀东保安队第三总队队长（后反正）', NULL, '初期在唐山、开平执行伪政府命令，但1937年通州起义反正，此处仅列其前期汉奸行为。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cbd80d06c1c250c19362c13e184c2032', '13f640997bf957c680c3a89ec672b307', 1935, '伪冀东保安队第四总队队长', NULL, '驻防唐山地区，协助日军收缴民间武器，强征壮丁，破坏抗日组织。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('71de1701b33352cba9196063dec4032b', '8edba735e5835b9ca5a0ac5b125e9326', 1938, '伪唐山特别市公署市长', NULL, '1938年伪冀东政府改为伪河北省后，任伪唐山市长，推行日伪经济统制，强征粮食煤炭，为日军提供战争物资。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4d2503b7726554559618d1f123ce9dad', 'bdc65b94361955e98916b39f842b9e00', 1938, '伪唐山特别市公署警察局长', NULL, '指挥伪警察在唐山、开平地区搜捕抗日地下党员，破坏交通线，多次参与“治安强化运动”。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('07e560bd83d9576c8677be672632f361', '801d6d8b0d9958d685ad7892948df677', 1938, '伪冀东剿共军司令', NULL, '在唐山、开平、滦县一带组建伪军，配合日军进行“铁壁合围”扫荡，杀害抗日干部数百人。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('07d7779e66f6592a87da8ea721d09ea6', '132ca09a10c5518383fc783d3db3266b', 1936, '伪冀东保安队第五总队队长', NULL, '长期盘踞开平镇，设立据点，勒索百姓，多次袭击八路军游击队，烧毁村庄。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4b3cfa07bea15580a2e7342364f3cab3', '782458db75cd520a8d6076faf8457826', 1937, '伪开平区维持会会长', NULL, '日军占领开平后组织维持会，为日军征粮派款，提供情报，协助建立伪区公所。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5c4d0d5044e5534280ffe857de1a95b5', '5af5570ba011572f971eab206ca84a58', 1940, '伪开平区区长', NULL, '在开平推行“保甲连坐”，强抓壮丁送日军当苦力，克扣抗日家属救济粮。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a8bf580278c159a9877ec03a11badcdd', '33f48787d6295324995de4d2f715fb78', 1935, '伪冀东自治政府顾问', NULL, '作为日本顾问的帮凶，参与策划唐山地区“自治”运动，煽动地方武装投日。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c959905fe5f35f008234d5f86b1ac138', '6cfb68638ff354acb2c330bf9e7ecdfd', 1938, '伪唐山商会会长', NULL, '为日军强制收购钢铁、棉花，压低价格盘剥商户，资助伪军经费。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7bff90af7aa550ae9a0b754e83d7f263', '46d89066451d566aac2203e5e4f61cb9', 1935, '伪冀东防共自治政府教育督办', NULL, '在唐山、开平各学校推行日语教育，篡改历史教材，强迫学生参拜日本神社。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9149c5a15b245f209e9a9c1aec6718e6', 'eb16f12e82445062991b80687ab7f146', 1935, '伪冀东防共自治政府顾问（未实际到任但参与策划）', NULL, '虽主要活动于东北，但曾为殷汝耕出谋划策，涉及唐山地区伪政权设计。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('01b26a4f91e25e90b3f5b5cfee03be7c', '340adba25424535985417eba5e18abbe', 1935, '伪冀东防共自治政府财政厅长', NULL, '在唐山地区发行伪币，搜刮民间金银，造成通货膨胀，民不聊生。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c39a9cb266525173840b7d4821b5c8a9', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1940, '伪华北政务委员会治安总署督办（管辖唐山驻军）', NULL, '虽总部在北京，但其伪军部队多次在唐山、开平地区扫荡，指挥“治安军”屠杀抗日群众。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b3701cad1496537b9067fd536d577dcd', '5b560385786f5ebc9f8f38276f67ad6f', 1941, '伪华北治安军第二集团军司令（驻防唐山）', NULL, '率治安军驻扎唐山，配合日军进行“剔抉”扫荡，在开平制造无人区。', '河北唐山_开平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('68b5089adb6b54c5b20a0bd9ca78fea9', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '冀东防共自治政府主席', NULL, '1935年11月在通州成立冀东防共自治政府，宣布冀东22县脱离国民政府，管辖范围包括唐山、曹妃甸所在地区，为日本侵略者服务，征收苛捐杂税，镇压抗日活动。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('af714414b50a5f659922a2c70eb884bc', 'be830f2d60665f0189881935079af216', 1935, '冀东防共自治政府秘书长/代理主席', NULL, '协助殷汝耕管理冀东伪政权，参与组织伪军和警察，配合日军清乡，在唐山地区推行奴化教育。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bfe72d37da4b53d8ae836598e3a3c6e9', 'c1ba15e6cdf55fd7891106db4277da0d', 1935, '冀东防共自治政府民政厅长', NULL, '在冀东伪政权中负责民政事务，协助日军控制唐山、滦县等地基层政权，强征民夫修筑军事工事。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8d944c72fb685375945ba84e5feab004', '6edb269a696555c193c5c25b9caf01c3', 1935, '冀东保安队司令', NULL, '统率冀东伪保安队，驻防唐山一带，多次配合日军扫荡抗日游击队，杀害抗日军民。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c0d127ab34c7574993edd6ab5bc6b258', '09a43f86f2b5580c80262d0857a985bf', 1936, '冀东伪军第一师师长', NULL, '率伪军在唐山、丰润、滦县等地进攻八路军，烧毁村庄，掠夺物资。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('08497be1b99e584aac98a6a931cb1e48', '99afd279f9bb50b2b65b52b289c8e71d', 1935, '冀东保安队第一总队队长', NULL, '初期为殷汝耕效力，后于1937年通州事变中反正，但此前曾在唐山地区参与镇压抗日活动。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f92442403d625eefaa582aed9b680384', '13f640997bf957c680c3a89ec672b307', 1936, '冀东伪军第二师师长', NULL, '驻防唐山地区，协助日军“治安肃正”，抓捕抗日地下工作者。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1f7d10c8ce685179a7ab12d3c1db0a4a', 'bc18fe5ce9665dd19c23a3c03acad179', 1938, '伪冀东道公署道尹', NULL, '伪冀东道（辖唐山、昌黎、滦县等地）最高行政长官，推行保甲制度，强征粮食支援日军。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6bc71ec1db925f8f834bb216ad355f6e', '76a98f532b95578e93e65bd668324e32', 1939, '伪冀东道公署顾问', NULL, '日本顾问的帮凶，参与策划对冀东抗日根据地的“铁壁合围”，在曹妃甸沿海地区组织伪自卫团。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8d7262da5e1e55fe99ebdbd6342dcbbb', '801d6d8b0d9958d685ad7892948df677', 1940, '伪唐山治安军司令', NULL, '统率伪治安军驻唐山，多次袭击冀东八路军，在曹妃甸一带设卡盘查，杀害抗日群众。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5a300a4fb0365e62a6627bb31ff41815', '132ca09a10c5518383fc783d3db3266b', 1941, '伪冀东剿共军司令', NULL, '在唐山、丰南、滦南等地进行“清剿”，制造多起惨案，烧毁渔船，封锁沿海交通。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('df0f06b879a55878a71a5eeaca949c29', '35df3a396910569cae6b5fcde72b99a7', 1938, '伪丰润县知事', NULL, '管辖包括曹妃甸周边区域，为日军提供情报，强征劳工，迫害抗日家属。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a623210d513c5d889ea4ef262780d8e2', '340adba25424535985417eba5e18abbe', 1939, '伪滦县知事', NULL, '在滦县及沿海地区推行“连坐法”，协助日军掠夺盐业资源，镇压渔民抗日活动。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a506cfdc37995d15881afe99701b5ba7', '33f48787d6295324995de4d2f715fb78', 1936, '伪冀东保安队第三总队长', NULL, '驻防唐山古冶一带，参与屠杀抗日游击队员，抢劫商旅。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ab807a139c3e5627999bca11beffd65a', 'c9252cd8d98258c290bb7fa7a520ec49', 1939, '伪唐山警察局局长', NULL, '指挥伪警察搜捕抗日分子，破坏地下组织，在曹妃甸港口设立检查站。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0e0757c7dfaf5ade8eb934088f87b16a', '71f249296df65e7d8a9b6fbff4d7d7c3', 1940, '伪冀东盐务局局长', NULL, '控制曹妃甸沿海盐场，将盐产大量供应日军，禁止民间私盐，导致渔民困苦。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('42e8eee5148c500e9f62f01f657704c6', 'a4b6b520415e5c858408bae9e7e4f97d', 1943, '伪冀东挺进军总司令（后投敌）', NULL, '原国民党将领，1943年投敌后任伪职，在唐山北部山区配合日军进攻八路军。', '河北唐山_曹妃甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5f580a6056685e09a9edee8d53197258', '0ec2ee6fed265ec5991932a6ff128192', 1943, '伪冀察战区总司令（投敌后）', NULL, '投敌后名义上管辖冀东部分地区，虽未直接驻唐山，但影响伪军行动，间接参与对曹妃甸沿海的封锁。', '河北唐山_曹妃甸');
