INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('75e8cb55a35553f788b56a5cceb5486f', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府秘书长、代理政务长官', NULL, '殷汝耕的主要助手，参与伪冀东政府运作，在唐山地区推行奴化教育和经济掠夺，后接替殷汝耕主持伪政府。', '河北唐山_滦南');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('225c6c7d02fd5a7db99295f5ece1c006', '503de500a44b531d918af851527aadf1', 1935, '伪冀东防共自治政府民政厅长', NULL, '负责伪冀东政府民政事务，在滦南、乐亭等地推行保甲制度，协助日军清乡，迫害抗日家属。', '河北唐山_滦南');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('07efd8e44bcc58dfad7d8d1227e3a7d6', '340adba25424535985417eba5e18abbe', 1935, '伪冀东防共自治政府财政厅长', NULL, '掌管伪冀东财政，为日军筹措军费，强征苛捐杂税，导致唐山、滦南地区民生凋敝。', '河北唐山_滦南');
