INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d4c215e4962e556bb21f264cabf241d3', 'be830f2d60665f0189881935079af216', 1935, '冀东防共自治政府秘书长、代理政务长官', NULL, '殷汝耕的主要助手，参与冀东伪政权运作，管理唐山地区伪行政事务，协助日军征粮派款。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8001419f649f539b82f344c1e2e2a173', '6edb269a696555c193c5c25b9caf01c3', 1935, '冀东保安队第一总队队长、伪冀东自治政府军事头目', NULL, '原中国军队军官，投日后任冀东保安队头目，驻防唐山、迁安一带，参与镇压冀东抗日暴动，围剿抗日游击队。', '河北唐山_迁安');
