INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d4299ff884bd513c9fc249c1390b3c59', '99afd279f9bb50b2b65b52b289c8e71d', 1935, '冀东保安队第二总队队长（后反正）', NULL, '原冀东保安队军官，初期在唐山地区为伪政权效力，但1937年通州事变中反正起义，击毙日军顾问，后脱离伪职。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2393babb8bfb52bdb54df4d205c28b22', '6f9c44c820815521b2d42b6fcc7b005d', 1935, '冀东保安队第三总队队长（后反正）', NULL, '与张庆余一同在通州反正，但此前曾在唐山、迁安一带执行伪政权命令，参与镇压抗日活动。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0591191919e85160b9d9e92ec8cd834c', '5ecdb6b22c615e368ffe537daaadad8f', 1936, '伪冀东政府迁安县长', NULL, '在迁安县任伪县长期间，推行日伪保甲制度，强征民夫修筑公路和炮楼，搜捕抗日分子，向日军提供情报。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dd469f0d2e0556329e422eb112eb4578', 'f4575ccf91a355f3b296f9c9ce9b70df', 1937, '伪冀东政府唐山市长（或唐山地区伪行政长官）', NULL, '在唐山市区任伪职，管理日占区民政，协助日军实行经济统制，掠夺开滦煤矿资源，镇压工人罢工。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('65f0498b47a35859a5f566259563d7b7', '801d6d8b0d9958d685ad7892948df677', 1936, '伪冀东自治政府保安队头目、伪冀东剿共司令', NULL, '在唐山、滦县、迁安一带率伪军多次围剿冀东抗日联军，杀害抗日军民，后被抗日武装击毙。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('15d82361c5af54de9a0009febb10bf91', '68139bf5da4659cb84fd1528c8758bab', 1938, '伪冀东政府迁安保安团长', NULL, '在迁安地区组织伪保安团，配合日军进行“扫荡”，烧毁村庄，抓捕抗日家属，罪行累累。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4add8993bd985748a389a69f59758bef', 'cabd7a206ce15f91a6b748b7c157d70d', 1939, '伪迁安县警察局长', NULL, '在迁安县城及乡镇建立伪警察网络，严查抗日地下交通线，多次带队搜捕八路军游击队和地下党员。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2d315c90fa0059a48ea4f9d4c3c1c340', '132ca09a10c5518383fc783d3db3266b', 1938, '伪冀东道尹（管辖唐山、迁安等县）', NULL, '作为冀东地区最高伪行政长官，统筹各县伪政权，推行“治安强化运动”，在迁安等地实施“连坐”制度。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('428f0c118a355076b78cdcb4fd9e599c', 'bdc65b94361955e98916b39f842b9e00', 1937, '伪冀东政府滦县（含迁安西部）维持会长', NULL, '在滦县、迁安交界地区组织维持会，为日军筹集粮饷，诱降抗日人员，破坏地方抗日武装。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ada254da19a85473b60fa3c052cfed6b', '59787560de815b89a3be4e03a8aa54ce', 1935, '伪冀东防共自治政府军事顾问（原东北军将领）', NULL, '虽主要在伪满任职，但多次到冀东唐山、迁安地区指导伪军作战，协助日军策划“扫荡”方案。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2940820c66235d6d8847ba10e44352a9', 'eb16f12e82445062991b80687ab7f146', 1935, '伪冀东政府法律顾问（后任伪满要职）', NULL, '参与冀东伪政权法律制定，为日伪统治提供“合法性”包装，间接助长唐山、迁安地区的殖民统治。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0c29212388ba505d863b7c0e060d290a', 'f507817e989158b6a3fd828c617b43cd', 1940, '伪华北政务委员会委员长（管辖冀东）', NULL, '作为华北伪政权最高头目，其统治范围覆盖唐山、迁安，支持当地伪军警镇压抗日活动，推行奴化政策。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9f93757ba14f54ce9fabe474e7db873d', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1939, '伪华北治安军总司令', NULL, '其麾下治安军多次在唐山、迁安地区驻防和作战，配合日军围剿八路军冀东军区，制造多起惨案。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ab70cc582ec05685a731423d21cce884', '5b560385786f5ebc9f8f38276f67ad6f', 1938, '伪冀东保安队指挥官（驻唐山）', NULL, '长期驻守唐山，指挥伪军参与对迁安、遵化等地的“清剿”，杀害抗日干部和群众。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8d3c88d17408581b8fcb4a43006b62ac', '3f227cbbf3cf5ad685e893c899c0087f', 1940, '伪迁安县新民会会长', NULL, '在迁安推行新民会奴化宣传，组织青少年接受日伪教育，收集抗日情报，协助日军“宣抚”工作。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c20c477d24f0513180c69b1288a78b61', 'a4b6b520415e5c858408bae9e7e4f97d', 1943, '伪冀东剿共军司令（后反正）', NULL, '虽为军阀投机，但曾在冀东地区（含迁安）与日军合作，参与对抗日根据地的进攻，后于1945年投降八路军。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5ad930ed1dec506ab0d18d068cc1d31c', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '冀东防共自治政府政务长官', NULL, '1935年11月在日本扶植下成立冀东防共自治政府，辖冀东22县（含唐山、迁安一带），推行亲日政策，协助日军控制冀东地区。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d4c215e4962e556bb21f264cabf241d3', 'be830f2d60665f0189881935079af216', 1935, '冀东防共自治政府秘书长、代理政务长官', NULL, '协助殷汝耕管理冀东伪政权，参与组织伪保安队，镇压抗日活动，后随伪政权并入华北临时政府。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('940719b807c85047aba67b2e69225dc7', 'c1ba15e6cdf55fd7891106db4277da0d', 1935, '冀东防共自治政府民政厅长', NULL, '在冀东伪政权中负责民政事务，推行日伪统治措施，协助日军在唐山、迁安等地建立保甲制度。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2c93848792b1530490957671dd133d4c', '6edb269a696555c193c5c25b9caf01c3', 1935, '冀东伪保安队司令', NULL, '率原中国军队投敌，任冀东伪保安队司令，驻防唐山一带，多次配合日军“扫荡”冀东抗日根据地，残害抗日军民。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1c12b107b77a5713af9fa2a59d95c829', '33f48787d6295324995de4d2f715fb78', 1935, '冀东伪自治联军总司令', NULL, '在冀东地区组织伪军，参与镇压迁安、遵化等地抗日武装，后任伪华北治安军高级军官。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c7151293a24b56f391ace053ab6f27c5', 'aff7314ed693526bb65154642113fc91', 1938, '伪迁安县县长', NULL, '任伪迁安县长期间，推行日伪“治安强化”运动，强征民夫修筑炮楼、封锁沟，配合日军清乡，逮捕抗日人员。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3448e3d2fbd85d6a9e47fdcd11c76d17', '340adba25424535985417eba5e18abbe', 1938, '伪冀东道尹', NULL, '任伪冀东道尹（辖唐山、迁安等县），积极推行日伪经济掠夺和奴化教育，组织伪警察镇压抗日活动。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('acd6f94dce48577b9781e65ed2e51b41', '34279a10aeeb55cb97ee1ff96fae70fd', 1939, '伪唐山特别市市长', NULL, '任伪唐山市长期间，为日军提供煤炭等战略物资，强制推行“献铜献铁”运动，并协助日军抓捕劳工。', '河北唐山_迁安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6d7abdddada35e54be19f155ef61d5c3', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府政务长官', NULL, '1935年11月在通州成立冀东防共自治政府，管辖包括唐山、迁西在内的冀东22县，公开投敌，为日军提供粮秣和劳役，镇压抗日活动。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a61c13679ec250a7b35cdd8a30c84999', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府秘书长、代理政务长官', NULL, '殷汝耕的主要助手，参与伪政府行政运作，协助日军在冀东地区推行保甲制度，强征民夫修筑工事。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2b01b031cb6250c1b3af5536c2c14683', '6edb269a696555c193c5c25b9caf01c3', 1935, '伪冀东保安队第一总队队长', NULL, '原为冀东保安队军官，投日后率部驻防唐山一带，配合日军清剿抗日武装，参与制造多起屠杀事件。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8bad7ee8c54154c48a9b277692c52df3', '09a43f86f2b5580c80262d0857a985bf', 1935, '伪冀东保安队第二总队队长', NULL, '驻防迁西、遵化交界地区，多次袭击八路军游击队，抓捕抗日群众并移交日军宪兵队。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4811168a660b51d595d9298483260b08', '99afd279f9bb50b2b65b52b289c8e71d', 1935, '伪冀东保安队第三总队队长（后反正）', NULL, '初期投日，在唐山地区维持伪秩序，1937年通州起义反正，但此前曾参与镇压抗日活动。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9bf7b3cc74315725906d1600412417c7', '6f9c44c820815521b2d42b6fcc7b005d', 1935, '伪冀东保安队第四总队队长（后反正）', NULL, '投日期间在唐山、丰润一带活动，协助日军收缴民间枪支，后随通州起义反正。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4a8cf08a64345885b288cc75445ac6e1', 'bc18fe5ce9665dd19c23a3c03acad179', 1938, '伪冀东道尹公署道尹', NULL, '伪冀东道（辖唐山、迁西等县）最高行政长官，推行日伪“治安强化运动”，组织汉奸武装“反共自卫团”。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('047948c4097554c9bed0a6b76c701274', 'bdc65b94361955e98916b39f842b9e00', 1938, '伪迁西县知事（县长）', NULL, '在迁西县（时属迁安县）推行日伪统治，强征粮食，建立伪村公所，配合日军“扫荡”抗日根据地。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ca033927ed1f5b80a4d1c26eb490ab17', '5ecdb6b22c615e368ffe537daaadad8f', 1939, '伪迁安县公署顾问', NULL, '日本顾问的华人助手，参与策划对迁西山区抗日游击队的围剿，残害抗日家属。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7a36d1ae386b54a9851da4e2cc0db229', '801d6d8b0d9958d685ad7892948df677', 1939, '伪冀东剿共军司令', NULL, '率伪军驻扎唐山、迁西一带，多次进攻冀东八路军，制造“潘家峪惨案”等血案（潘家峪属丰润，但活动范围覆盖迁西）。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4fd6741147ce564783dba932a5625c4a', '132ca09a10c5518383fc783d3db3266b', 1940, '伪冀东警备队大队长', NULL, '在迁西、遵化边界地区设卡盘查，捕杀抗日干部，破坏地下交通线。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bf3759fb3c705769a9fbe5bda8149c86', '33f48787d6295324995de4d2f715fb78', 1937, '伪唐山维持会会长', NULL, '唐山沦陷后组织维持会，为日军征集物资，协助建立伪政权，后任伪冀东银行董事。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f39c6c296a485aea942400a2a35c48be', '6cfb68638ff354acb2c330bf9e7ecdfd', 1938, '伪唐山特别市公署市长', NULL, '在唐山市区推行日伪经济统制，强征劳工，镇压工人罢工，迫害抗日分子。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7cf4c53b73ea553384faa6e6ac00c2ab', 'eb16f12e82445062991b80687ab7f146', 1937, '伪华北政务委员会顾问（曾涉唐山地区）', NULL, '虽主要活动于北平，但多次赴唐山、迁西指导“治安肃正”，为日军出谋划策。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('802dd47b371e5162ab306f72b9ff7344', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1939, '伪华北治安军总司令（活动范围含冀东）', NULL, '其指挥的治安军多次在唐山、迁西地区“驻剿”，配合日军实行“三光政策”。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e0147b6d27d257158dfd9e55643ed335', '5b560385786f5ebc9f8f38276f67ad6f', 1940, '伪冀东保安司令', NULL, '驻防唐山，负责冀东伪军整编，多次组织对迁西抗日根据地的围攻。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c514bd45a6c75609be3b41fa6c9c9e49', '340adba25424535985417eba5e18abbe', 1943, '伪冀东道尹（继任）', NULL, '接替王铁相，继续推行日伪统治，在迁西等地强抓壮丁补充伪军。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dcef8090c01c5c5da3d032139429c368', '3f227cbbf3cf5ad685e893c899c0087f', 1941, '伪迁西县保安队队长', NULL, '率伪保安队常驻迁西金厂峪一带，为日军护矿，镇压矿工反抗，杀害抗日游击队员。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('426e00bdcc645e0198989a3d9222bd8a', '782458db75cd520a8d6076faf8457826', 1938, '伪冀东新民会会长', NULL, '在唐山、迁西地区组织新民会，进行奴化宣传，搜集抗日情报，协助日军“宣抚”。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('73c839c8b60d553a8b134cdc0a2cc48e', '68139bf5da4659cb84fd1528c8758bab', 1940, '伪迁西警察署署长', NULL, '在迁西县城及主要集镇设立警察分所，抓捕抗日地下党员，刑讯逼供，致死多人。', '河北唐山_迁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2dd993d56849510990d1805a75200629', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满洲国立法院院长、冀东防共自治政府顾问', NULL, '原为奉系政客，后投靠日本，参与策划冀东事变，协助建立伪冀东防共自治政府，并任顾问，为日军在冀东地区统治出谋划策。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e91f4600aa3f56c3b277a15be3d58569', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府政务长官', NULL, '1935年11月在通州成立伪冀东防共自治政府，管辖包括唐山、遵化在内的冀东22县，公开投敌，为日军提供粮秣、劳役，并镇压抗日活动。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('960a5582a59453e6bd76331c100d2cd7', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府秘书长、代理政务长官', NULL, '殷汝耕的得力助手，参与伪政府日常行政，协助日军在唐山、遵化等地推行保甲制度，强征民夫，搜刮物资。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bc1554345c2b52e2ac213de5499ff988', '503de500a44b531d918af851527aadf1', 1935, '伪冀东防共自治政府民政厅长', NULL, '负责伪政府民政事务，在遵化、唐山等地推行日伪户籍登记，协助日军清乡，迫害抗日家属。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('576442bd235451828eb5c784a8253955', '340adba25424535985417eba5e18abbe', 1935, '伪冀东防共自治政府财政厅长', NULL, '主管伪政府财政，为日军筹措军费，在唐山、遵化强征各种捐税，掠夺当地资源。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5412a6045a8e561991fcf2abbc4ff204', 'b1165db7ffb15bdc99c05cc39193abd8', 1935, '伪冀东防共自治政府建设厅长', NULL, '负责伪政府建设事务，组织劳工为日军修建公路、碉堡，在遵化山区协助日军封锁抗日根据地。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1f40843c29db5bcea32ad0e6e0d29e1c', 'd9d481038a005f3281a727e7423755c5', 1935, '伪冀东保安队总队长', NULL, '原为地方武装头目，投靠殷汝耕后任伪保安队总队长，在唐山、遵化一带配合日军扫荡，围剿抗日游击队。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('19e8a0be35fd58f4bdecf6c9b1cc6c0b', '801d6d8b0d9958d685ad7892948df677', 1935, '伪冀东保安队第三总队队长', NULL, '驻防唐山地区，多次率伪军袭击遵化、迁西等地的抗日武装，杀害抗日军民。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e497235530a359faa0d7899c25c5963e', '6edb269a696555c193c5c25b9caf01c3', 1935, '伪冀东保安队第五总队队长', NULL, '活动于遵化、玉田一带，配合日军进行“讨伐”，烧毁村庄，抓捕抗日干部。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5119a15b2afb532db63b4972046e15f9', '33f48787d6295324995de4d2f715fb78', 1935, '伪冀东自治政府顾问、伪华北治安军高参', NULL, '原为军阀余部，投日后任伪职，参与策划冀东伪政权，后任伪华北治安军高参，在唐山地区协助日军训练伪军。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e48ea3ed6433527daf724cad41114c6e', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北政务委员会治安总署督办、伪华北治安军总司令', NULL, '虽为华北级汉奸，但其指挥的伪治安军多次在唐山、遵化地区进行大规模“扫荡”，直接参与屠杀抗日军民。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fe394c542c925172af875caae8ec5cec', '5b560385786f5ebc9f8f38276f67ad6f', 1939, '伪华北治安军第一集团军司令', NULL, '率伪治安军驻扎冀东，在遵化、唐山等地建立据点，配合日军推行“治安强化运动”，围剿八路军。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ebb4783739145b93bb27cb26f2a368d3', 'ecf60592ca4e5eb7a1acb966d596dbac', 1938, '伪唐山特别市市长', NULL, '1938年伪唐山市政府成立后任市长，为日军在唐山矿区掠夺资源服务，镇压工人罢工，迫害抗日分子。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('69d6a4f80ad75f3f8c3f6ddc6c30b4c7', 'bdc65b94361955e98916b39f842b9e00', 1938, '伪唐山特别市警察局局长', NULL, '负责唐山地区日伪治安，多次组织特务抓捕抗日地下党员，破坏抗日组织。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a21becb792b65a198b077e6ea023e030', '6cfb68638ff354acb2c330bf9e7ecdfd', 1938, '伪遵化县知事（县长）', NULL, '在遵化县推行日伪统治，强征粮食，组织伪自卫团，协助日军在遵化山区修建封锁沟，围困抗日根据地。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('628ecac64e8653ed8b0187dd84d3ad1c', '1dbffbc715a15493bcf55f10a8e2143a', 1938, '伪遵化县保安队队长', NULL, '率伪保安队多次袭击遵化境内的抗日游击队，杀害抗日群众，烧毁村庄。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ab2a94d3c35e50ddabd1b8b3b1207e2d', 'c0f29d2b79d05a22a00c28ce3fc8b533', 1939, '伪遵化县警察所所长', NULL, '在遵化县城及各乡镇建立伪警察网络，搜捕抗日干部，为日军提供情报。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f1cdd69c8f215ec5b9e8f52f458a53f2', '30c7e9e79c175963a01b3fe7ff11bbab', 1940, '伪遵化县新民会会长', NULL, '负责遵化地区日伪奴化宣传，组织“新民会”活动，强迫民众参加反共集会，收集抗日情报。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e6e2ff8f3a5b55649c165875e94146ac', '629954bc42a05671bfe89a32ffe10591', 1938, '伪冀东道尹公署道尹（驻唐山）', NULL, '管辖唐山、遵化等县，推行日伪“治安肃正”计划，组织伪军配合日军扫荡。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('546c0d85de8b5518a3fbb6d8f9f21cac', '5ecdb6b22c615e368ffe537daaadad8f', 1938, '伪冀东道公署顾问', NULL, '作为日本顾问的帮凶，参与策划冀东地区“清乡”行动，在遵化等地建立“爱护村”制度。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('70efd1c3928159e1921b9a8154fc9b94', '33f48787d6295324995de4d2f715fb78', 1935, '冀东防共自治政府保安队总队长', NULL, '1935年参与策划冀东事变，任伪保安队总队长，协助日军控制冀东地区，镇压抗日活动。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9c11d4c371255ba884c7bbb9e3f53d2c', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '冀东防共自治政府政务长官', NULL, '1935年11月成立冀东防共自治政府，辖唐山、遵化等22县，公开投敌，为日军提供行政和军事支持。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d198ccba5976581fbbe331eada8650dc', 'be830f2d60665f0189881935079af216', 1935, '冀东防共自治政府秘书长', NULL, '协助殷汝耕管理伪政府，参与推行奴化教育和经济掠夺政策，在遵化一带强征粮税。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a90ab3aa76685ef58ea1534ee1b2e5b7', '6edb269a696555c193c5c25b9caf01c3', 1936, '伪冀东保安队第三总队队长', NULL, '驻防唐山、遵化地区，多次配合日军扫荡抗日根据地，杀害抗日军民，烧毁村庄。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e456da27c7b3566b9e2e5c7c21dc0b30', 'bc18fe5ce9665dd19c23a3c03acad179', 1938, '伪遵化县知事', NULL, '任伪遵化县知事期间，强征民夫修筑炮楼和公路，向日军提供情报，镇压遵化抗日游击队。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b61a486ab2305adb8b889ef6067e62f6', '99afd279f9bb50b2b65b52b289c8e71d', 1935, '伪冀东保安队第一总队队长', NULL, '在唐山地区为日军维持治安，参与清乡行动，后于1937年反正，但此前有协助日军压迫民众行为。', '河北唐山_遵化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a9057659fca05d8b9820394d80de7a0d', 'ad0c9f9af10054c68d58a879c97add74', 1937, '冀中保安司令、河北省保安司令', NULL, '原国民党将领，后投靠日军，在冀中地区组织伪保安队，协助日军扫荡抗日根据地，捕杀抗日军民。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e400f2d4cb7b5a018dcb1c21d2018f1c', '132ca09a10c5518383fc783d3db3266b', 1935, '伪冀东保安队司令', NULL, '原冀东保安队头目，1935年随殷汝耕投日，在冀东（含廊坊北部部分地区）镇压抗日活动，配合日军“治安肃正”。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('37d9744a9250567fa599016fb2f26e99', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府委员长', NULL, '1935年成立冀东伪政权，管辖包括廊坊部分县区（如香河、三河等），推行奴化教育，为日军提供粮秣和情报。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('07e36cebdc0d541d9c551f9fc92c3827', 'be830f2d60665f0189881935079af216', 1937, '伪冀东防共自治政府政务长官（后任）', NULL, '继殷汝耕后主持冀东伪政权，在廊坊地区强化保甲制度，强征民夫修筑炮楼和封锁沟。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('20bae9d90be75cb585bdd692e10769f8', 'f507817e989158b6a3fd828c617b43cd', 1940, '伪华北政务委员会委员长', NULL, '作为华北伪政权最高头目，其统治范围涵盖廊坊地区，支持日军“三光政策”，并组织伪军配合扫荡。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('959c1866a22b5b628015fcb8240cdb5f', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1939, '伪华北治安军总司令', NULL, '指挥伪治安军在廊坊及周边地区频繁“清剿”，杀害抗日干部，掠夺物资，并参与制造多起惨案。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cd5fb5d647e45a999286d93043408010', '5b560385786f5ebc9f8f38276f67ad6f', 1940, '伪河北省省长', NULL, '在任期间推行日伪“新民会”政策，在廊坊各县建立伪县署，强征壮丁，破坏地下抗日组织。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('89fe2fd7f0ec5ac88ea202b3f1e0d1eb', '190dabfac9075fad8821b4606545bb75', 1943, '伪河北省省长（后任）', NULL, '继续执行日军命令，在廊坊地区强化“治安强化运动”，搜捕抗日家属，实施经济封锁。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('96f7117c45065296bb36946d94ab88e3', '7c51a2464caa5e18aaf829b24f6c43bc', 1943, '伪华北政务委员会治安总署督办', NULL, '负责华北伪军整编，在廊坊一带部署伪军据点，配合日军对大清河、永定河流域的扫荡。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('96de8fdd01645eb68f43714865a1906a', '3f227cbbf3cf5ad685e893c899c0087f', 1938, '伪安次县知事', NULL, '在安次（今廊坊安次区）任伪县长期间，积极为日军征粮派款，组织汉奸特务队，抓捕抗日群众。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1b60f954fe9b53229f91b4558680525b', '9ca8f82df12958b9ac4d7381f7eaeeaa', 1939, '伪永清县知事', NULL, '在永清县推行“保甲连坐”，多次引导日军突袭抗日村庄，造成多起屠杀事件。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8fc2ce183ec155569e9c0a10f0dbe9a5', '2b3aa41fa6f45f01b94a57451961c170', 1940, '伪固安县知事', NULL, '在固安建立伪警察所和情报网，破坏中共固安县委地下活动，协助日军抓捕抗日干部。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5b54a96ccde05affbfa963624b8933e7', 'e8e4722a45635863beed6a1c19034daf', 1937, '伪香河县知事', NULL, '香河县伪政权头目，强征民夫修建日军机场和碉堡，镇压当地抗日武装。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('17e65b5e24c05de68de517f8427f26a3', '98f434e5c4be544dbf5b4ac887efc5c9', 1938, '伪三河县知事', NULL, '在三河县推行“粮食统制”，搜刮民财，并组织汉奸武装“反共自卫团”袭击游击队。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d060263bc7a2584aac7bb0fdebde4886', '33f48787d6295324995de4d2f715fb78', 1937, '伪冀东保安队第三总队长', NULL, '驻防廊坊北部地区，多次率部参与对冀中十分区（含霸州、文安等地）的扫荡，烧杀抢掠。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ae63569bbe185b36bdc0294bbed5aedc', '6edb269a696555c193c5c25b9caf01c3', 1938, '伪冀东保安队第五总队长', NULL, '在廊坊东部（如大厂、香河）活动，配合日军“剔抉”行动，杀害八路军伤员和村干部。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('37231efa6b2959d4a01afdf62685ed99', '76a98f532b95578e93e65bd668324e32', 1941, '伪冀东“剿共”军司令', NULL, '在廊坊地区组建伪“剿共”军，专门袭击抗日县大队，并策反抗日队伍中的动摇分子。', '河北廊坊');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('555c6eb38e6a5629863f573250185aa9', 'bc18fe5ce9665dd19c23a3c03acad179', 1942, '伪华北治安军第12集团司令', NULL, '率部驻防廊坊至天津铁路沿线，破坏抗日交通线，多次参与“铁壁合围”扫荡。', '河北廊坊');
