INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e21b03455ce95859abe6322525711e6f', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙古联盟自治政府主席、伪蒙疆联合自治政府主席', NULL, '蒙古王公，1936年在日军扶植下成立伪蒙古军政府，后成为伪蒙疆政权首脑，其势力范围覆盖张家口、尚义等察哈尔地区，推行奴化教育与殖民统治。', '河北张家口_尚义');
