INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4fc5cad6d43b56b2b02af97d078899ce', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、察哈尔盟公署顾问', NULL, '原为热河土匪，后投靠日军，任伪蒙古军总司令，在张家口及察哈尔地区协助日军镇压抗日力量，参与建立伪蒙疆政权，推行奴化政策。', '河北张家口_桥西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('227446ee52965a1aa0ec28ce62c411fa', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙疆联合自治政府主席', NULL, '蒙古王公，在日本扶植下成立伪蒙疆政权，以张家口为重要活动中心，配合日军统治察哈尔、绥远等地，提供兵员和物资，协助日军清剿抗日武装。', '河北张家口_桥西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9af2d074b6ba52ecb46b279a444231f2', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙疆联合自治政府总务厅长', NULL, '在张家口伪政权中担任要职，负责行政事务，推行日本殖民政策，参与经济掠夺和治安维持，镇压当地抗日活动。', '河北张家口_桥西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('64a36406445258a09cbec9918f000ac7', 'c26803f6684e5028aefd0f491d4c762b', 1937, '伪张家口市市长', NULL, '原为张家口商会会长，日军占领后出任伪市长，为日军征粮派款，组织伪警察协助日军维持统治，迫害抗日民众。', '河北张家口_桥西');
