INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('87d2d6d87c2d5fe2b15ffaa25c967b9c', '90b7692155d355f7a5f6defbca0b1d40', 1938, '伪蔚县知事（县长）', NULL, '投靠日伪，任蔚县伪县长，推行保甲制度，建立伪警察队，配合日军扫荡，抓捕抗日人员，强征劳工。', '河北张家口_蔚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5dbce4fc2fb259f68a5e6161282e22f8', '8d1562d16c855d018c34bab9d622b88d', 1939, '伪蔚县保安队大队长', NULL, '原为地方土匪，后投靠日军，任伪保安队长，率伪军多次袭击八路军游击队，杀害抗日干部，烧毁村庄。', '河北张家口_蔚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e380185974aa505ebacf724668242b64', '8320e3e3065f5f31a864a1fd27201ca3', 1940, '伪蔚县新民会会长', NULL, '负责蔚县新民会，推行奴化宣传，组织“反共救国会”，刺探抗日情报，协助日军进行文化侵略。', '河北张家口_蔚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1136cf14e5865aa085bcb1ab9606368e', 'be4eaecc9af056e787d52f2319a57fdc', 1941, '伪蔚县警察局长', NULL, '任伪警察局长期间，残酷镇压抗日群众，多次带队搜捕地下党员，刑讯逼供，制造多起惨案。', '河北张家口_蔚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d45f22a01c8f5f5ca6a2ed4cf1dff7b9', '39d432c291145512a4678090a21e497d', 1939, '伪张家口宣化县知事（兼蔚县督导）', NULL, '在宣化、蔚县一带督导伪政权，强征粮食，组织“自卫团”，配合日军“治安强化运动”，破坏抗日根据地。', '河北张家口_蔚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('75eab11568b65bec9eda24ecb3c084cf', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪张家口特别市市长', NULL, '原为东北军将领，后投靠日军，任伪蒙古军总司令，参与侵占察哈尔，1939年后任伪张家口特别市市长，协助日军推行殖民统治，镇压抗日力量。', '河北张家口_蔚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1dfcc07747b250eeac7e4d66e3338898', '03751651c36952668c9b65b923b9c221', 1936, '伪蒙疆联合自治政府主席', NULL, '蒙古王公，在日本扶植下建立伪蒙疆政权，辖张家口、大同、归绥等地，配合日军“以华制华”政策，在蔚县等地区推行奴化教育和物资统制。', '河北张家口_蔚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6d74f02bf0f558c18bbf2a07c20a7ae5', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙疆联合自治政府总务厅长', NULL, '德王亲信，负责伪蒙疆政权行政事务，参与制定针对张家口及蔚县等地的征粮、征兵和保甲制度，协助日军清剿抗日游击队。', '河北张家口_蔚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a88f5fed5db45bd5b2f548e89e1a0923', 'c26803f6684e5028aefd0f491d4c762b', 1937, '伪张家口市公署市长（后任伪蒙疆政府经济部长）', NULL, '原张家口商会会长，投日后任伪市长，为日军筹集物资，强征劳工，在蔚县等地推行经济掠夺，压制抗日活动。', '河北张家口_蔚县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('02ec67713bdd5505aa882d4b51274906', 'f1e034ba219e5663bf35a90945f8137a', 1938, '伪蔚县知事（县长）', NULL, '日军占领蔚县后任伪县长，组织伪警备队，配合日军“扫荡”，强征粮食，抓捕抗日军民，破坏中共蔚县地下组织。', '河北张家口_蔚县');
