INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1a5118b86e4552dc806a39bc2abb1e26', '987a275226335a46b1a0fdc3d18055ae', 1937, '伪蒙疆联合自治政府总务厅长', NULL, '长期担任伪蒙疆政府高级职务，负责行政事务，协助日军在张家口、阳原一带推行保甲制度，强征劳役，搜刮粮食，镇压抗日活动。', '河北张家口_阳原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('80675bd1050f5dfc992700af98ee782f', 'c26803f6684e5028aefd0f491d4c762b', 1937, '伪张家口市公署市长', NULL, '原为张家口商会人物，日军占领后出任伪市长，为日军征收捐税，提供物资，并参与建立伪警察机构，迫害抗日军民。', '河北张家口_阳原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('324a9a70e0cb56e59e403e960b091666', 'dbaf8cd68c5d5e3caa0978b7e06efe50', 1938, '伪阳原县知事（县长）', NULL, '任伪阳原县知事期间，积极推行日伪政令，组织维持会，强征民夫修筑据点，配合日军扫荡，残害抗日干部和群众。', '河北张家口_阳原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('774ea97a3fdf5dfd9a1546b2da01f8a3', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪热河省省长', NULL, '1933年日军侵占热河后投敌，任伪热河省省长，协助日军推行殖民统治，镇压抗日力量，强征劳工，掠夺资源。', '河北承德');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3e0b18d925fb5170adaa7725e1f38a60', '2b437180a5505d89afed6a8146c9383e', 1933, '伪热河省警务厅长', NULL, '任伪热河省警务厅长期间，组织伪警察配合日军“讨伐”抗日武装，抓捕抗日志士，实施“治安肃正”。', '河北承德');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b6f459b0e78b5f219fb159f6d83243e3', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满洲国监察院院长（曾涉承德地区）', NULL, '作为伪满高官，参与策划对热河（含承德）的殖民统治，协助日军建立伪政权，推行奴化教育。', '河北承德');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b7dfe4baca93599d98579ada591b2931', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1932, '伪满民政部总长（曾涉热河事务）', NULL, '参与伪满对热河地区的行政规划，支持日军侵略，协助镇压承德一带的抗日活动。', '河北承德');
