INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('789416661a1c5820bcede12b8da783ad', '1c5a7c0239a3585ba753fb5dd8066643', 1933, '伪承德县县长', NULL, '任伪承德县县长期间，强征民夫修建军事工程，配合日军“清乡”，迫害抗日家属。', '河北承德');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('33e05ad7fb8451d58668356aa6743118', '33f48787d6295324995de4d2f715fb78', 1933, '伪热河省保安司令', NULL, '组建伪保安队，协助日军围剿承德周边抗日游击队，参与制造多起屠杀事件。', '河北承德');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6b37d5ec9b545939adf3e61610c4ccae', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满洲国国务总理（涉热河地区政策）', NULL, '作为伪满最高行政长官，批准对承德地区的“治安肃正”计划，支持日军残酷镇压抗日力量。', '河北承德');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('97566d1bb08b5cc2b5e7d9a1c450d11d', 'ba311422856554c7ad7f3f75d09c3d78', 1932, '伪满参议府议长（涉热河事务）', NULL, '参与制定伪满对热河（含承德）的统治政策，协助日军建立殖民秩序。', '河北承德');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c040aff8a121571984ca70eff6b7cb59', '9ecee7f0ddf659e583819e721e164c94', 1933, '伪热河省实业厅长', NULL, '在承德地区掠夺矿产、森林资源，强征劳工，为日军战争提供物资。', '河北承德');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dbfa1c638cd55917bd4b84591998e143', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪满洲国热河省省长兼第五军管区司令', NULL, '原东北军将领，1933年投敌，任伪热河省省长，协助日军镇压抗日武装，推行“治安肃正”，残害抗日军民。', '河北承德');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f87ef0996edd5ca599b7dad50693099f', '2ccc9a42e40e54a5b4d02397b3fcd7fd', 1934, '伪满洲国热河省警务厅厅长', NULL, '负责热河地区伪警察体系，配合日军进行“讨伐”，抓捕抗日地下工作者，实施“连坐”政策。', '河北承德');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d40d4888fd5a50408c18c52d0d193ad1', 'eb16f12e82445062991b80687ab7f146', 1933, '伪满洲国热河省参事官', NULL, '参与伪满政权在承德地区的行政建设，协助推行奴化教育，为日军掠夺资源提供行政支持。', '河北承德');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9b77e1a64fae59bc95b41fc8509d7451', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令（活动于热河、察哈尔边境）', NULL, '原热河地方武装头目，投靠日军后任伪蒙古军总司令，在承德北部及围场、丰宁一带配合日军“扫荡”，屠杀抗日游击队。', '河北承德');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('91a75812ea9f5834874ca2a4d261bfd5', 'ddcfb16d41be52418ca83c43624dca1c', 1937, '伪承德县县长', NULL, '在承德县推行伪满“街村制”，强征劳工，搜刮粮食，协助日军建立“无人区”，迫害抗日群众。', '河北承德');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8a560e768f1850bb929748dd3a7d471d', '3c0cec769a465f2da5d9587d32cf51f4', 1939, '伪丰宁县警务科科长', NULL, '在丰宁、隆化一带组织伪警察队，参与制造“无人区”，多次袭击八路军游击队，杀害抗日干部。', '河北承德');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('96ee40ffb45959ce8aadf5b71764114f', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪满洲国热河省省长', NULL, '原东北军将领，1933年投敌，任伪热河省省长，协助日军镇压抗日武装，推行殖民统治，在丰宁、承德一带组织伪警察和保甲制度，强征民夫修筑军事工事。', '河北承德_丰宁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a0ef42c8d3ce5a90890bea8ec73fe191', '2ccc9a42e40e54a5b4d02397b3fcd7fd', 1934, '伪满洲国热河省警务厅厅长', NULL, '在承德、丰宁地区建立特务情报网，多次指挥围剿抗日游击队，逮捕并杀害抗日军民，参与“集家并村”行动，制造无人区。', '河北承德_丰宁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('06ee6096fe4c584bb8ec08032c4460d2', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪满洲国热河地区军事顾问', NULL, '原热河地方军阀，投日后在丰宁、围场一带配合日军扫荡，参与镇压抗日义勇军，后任伪蒙古军总司令，长期在热河北部活动。', '河北承德_丰宁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('19944f016b55586e87a986a9980ebd64', '4b74de49fe295d089c7808ac8eae8402', 1937, '伪丰宁县县长', NULL, '在丰宁推行日伪“治安肃正”政策，组织汉奸自卫团，强征粮食，配合日军“三光”政策，迫害抗日家属，破坏地下抗日组织。', '河北承德_丰宁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0f99fd3461e95c6792acbd5b89ef3739', '3c0cec769a465f2da5d9587d32cf51f4', 1938, '伪承德县警察署署长', NULL, '在承德、丰宁交界地区设立多个警察分所，抓捕抗日干部，刑讯逼供，曾亲手杀害多名八路军侦察员，并参与“人圈”管理。', '河北承德_丰宁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1e2112d1a1be5c0eaccaeca51fbeae79', '0b2e00f047d35a799f6e0f8e40416b8a', 1940, '伪热河省协和会丰宁分会会长', NULL, '为日军宣传“日满亲善”，组织汉奸青年团，刺探抗日军情，协助日军在丰宁山区进行“梳篦式”清剿，导致多支小股游击队损失。', '河北承德_丰宁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2c09a166f0455523bc5ab5d868e922b1', 'c552feab438259f9bed94b87f2042708', 1935, '伪满洲国军热河省警备军团长', NULL, '率伪军驻防承德、丰宁，多次参与对抗日根据地的“讨伐”，烧毁村庄，掠夺牲畜，在丰宁黑山嘴一带制造多起惨案。', '河北承德_丰宁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('47d5ae4cf1925965b62d0d6b7a31f6ae', '41e2250015c454eab744b3305a452aff', 1939, '伪丰宁县警务科科长', NULL, '直接指挥伪警察和特务，在丰宁各地设立“检问所”，盘查行人，搜捕抗日分子，曾诱降并杀害抗日游击队小队长。', '河北承德_丰宁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4e10a177ffb259a387f4a1478e8bd7d0', '5be08c100d06553796f244b98545bd92', 1941, '伪承德地区保安队总队长', NULL, '组织汉奸保安队，配合日军在丰宁、隆化一带进行“大扫荡”，实行“连坐法”，强迫村民报告抗日活动，杀害无辜群众数十人。', '河北承德_丰宁');
