INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d28732ce95855c4585e285f8e546d25b', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令', NULL, '原热河地方军阀，投日后任伪蒙古军总司令，曾率部在丰宁、围场一带进攻抗日游击队，参与镇压民众反抗。', '河北承德_丰宁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7a93bfb2acc75d62b4fc8af216400844', '4b74de49fe295d089c7808ac8eae8402', 1938, '伪承德县警务科长', NULL, '在承德地区组织伪警察特务，搜捕抗日地下人员，破坏抗日组织，多次带队“清乡”残害百姓。', '河北承德_丰宁');
