INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e2726bfa0cad517f87602f95f0d7ba4d', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪热河省警备军司令', NULL, '原东北军将领，投日后任伪热河省警备军司令，在承德、兴隆一带配合日军‘扫荡’，围剿抗日武装，残害抗日军民。', '河北承德_兴隆');
