INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bfd1afa56d645a509660e44178d713cd', '3613c9792d855571bd9dcedeb3091e5e', 1935, '伪兴隆县警务科长', NULL, '在兴隆地区组织伪警察队，抓捕抗日地下工作者，破坏抗日组织，参与‘清乡’行动，杀害多名抗日群众。', '河北承德_兴隆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d95a714a83585a08aff18f02e938dd6f', '3c0cec769a465f2da5d9587d32cf51f4', 1938, '伪兴隆县保安团长', NULL, '率伪保安团配合日军对兴隆山区进行反复‘扫荡’，烧毁村庄，强迫村民迁入‘集团部落’，致使大量平民死亡。', '河北承德_兴隆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f5dd54c5eb1e5107bb1e903665f98706', 'ce4c63c9505e5b01ba9aa9d1ec2f09f4', 1937, '伪承德县（含兴隆部分）维持会会长', NULL, '投靠日军，组织维持会为日军征粮派款，提供劳役，并告密抗日分子，导致多名抗日人员被捕牺牲。', '河北承德_兴隆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b366f828dbb55f418722816743b44812', '4b74de49fe295d089c7808ac8eae8402', 1939, '伪热河省协和会兴隆分会主任', NULL, '积极宣传‘日满亲善’，推行奴化教育，搜集抗日情报，协助日军实施‘三光政策’，在兴隆地区犯下罪行。', '河北承德_兴隆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('39b707c5e2755a1c9868673111ee7871', 'bb640cda2098539fb0e4e975ca83a94f', 1940, '伪兴隆县警察署署长', NULL, '指挥伪警察多次突袭抗日村庄，逮捕并严刑拷打抗日群众，参与制造多起惨案，如‘狗背岭惨案’。', '河北承德_兴隆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b692c04fbaf4587eb15e1fa025c6e56a', 'a3eb8307fd6a5cd5a48713eabac55d34', 1941, '伪兴隆县自卫团总团长', NULL, '组织自卫团协助日军封锁山区，切断抗日武装补给线，并亲自带队搜捕抗日游击队员，杀害多名伤员。', '河北承德_兴隆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('43388c19903454d39e3dd24e45591646', 'aae2ba480b10558f9d3fc16c6df77331', 1942, '伪兴隆县特务队长', NULL, '充当日军特务，打入抗日组织内部，策反叛徒，导致兴隆地区多个地下联络站被破坏，数十名抗日人员牺牲。', '河北承德_兴隆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('af4840cdfeac50f28faa7934202f942a', '091187ee16085ccea2e4606033830c16', 1933, '兴隆县伪县长', NULL, '任伪兴隆县县长期间，积极推行日伪“治安肃正”政策，组织保甲制度，协助日军镇压抗日武装，强征劳工，掠夺资源。', '河北承德_兴隆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7065719a788955769688e9c5de984e6b', '1dbffbc715a15493bcf55f10a8e2143a', 1938, '兴隆县伪警察署署长', NULL, '率伪警察配合日军“扫荡”，抓捕抗日军民，破坏地下组织，参与制造多起惨案。', '河北承德_兴隆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2b8ed6d0de8c5224a96a00a224c8ce2b', 'ddb23c0430b05c31ba42342c0fe96e71', 1940, '伪兴隆县协和会会长', NULL, '宣传“中日亲善”，组织奴化教育，搜集抗日情报，协助日军推行“集家并村”政策，制造无人区。', '河北承德_兴隆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('007f2578f2715a138b0ebf239bd66aeb', '39d432c291145512a4678090a21e497d', 1941, '伪承德省兴隆县保安队队长', NULL, '率保安队多次袭击八路军游击队，杀害抗日干部，烧毁村庄，为日军充当鹰犬。', '河北承德_兴隆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8e299e0663145db3802ac5017ddca0be', '8320e3e3065f5f31a864a1fd27201ca3', 1942, '伪兴隆县警务科科长', NULL, '负责特务工作，建立情报网，逮捕抗日群众，严刑逼供，破坏抗日根据地。', '河北承德_兴隆');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b0822998596e5b4aac54eaaf0250a762', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪满洲国热河省省长', NULL, '原东北军将领，1933年投敌，任伪热河省省长，协助日军镇压抗日武装，推行殖民统治，强征劳工，掠夺资源。', '河北承德_双桥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('317ef0a52b985dce9d1692554226ebed', '2ccc9a42e40e54a5b4d02397b3fcd7fd', 1933, '伪热河省警务厅厅长', NULL, '负责伪满警察系统，在承德及双桥地区大肆搜捕抗日分子，实施“治安肃正”，制造多起屠杀事件。', '河北承德_双桥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c37eaef41d4f527bb336555aebaa7cdf', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令', NULL, '原热河地方军阀，投日后任伪蒙古军总司令，曾率部在承德、双桥一带配合日军“扫荡”，残害抗日军民。', '河北承德_双桥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0c08cbca37885ad3bdf47abd21605266', '4b74de49fe295d089c7808ac8eae8402', 1938, '伪承德县县长', NULL, '任伪承德县县长期间，推行保甲制度，强征粮税，协助日军建立“无人区”，迫害百姓，破坏抗日根据地。', '河北承德_双桥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('46faf5fa91115dec8ca94dd3e5e616ee', '3c0cec769a465f2da5d9587d32cf51f4', 1940, '伪双桥区警察署署长', NULL, '在双桥地区充当日军鹰犬，抓捕抗日地下工作者，严刑逼供，多次带队突袭村庄，烧杀抢掠。', '河北承德_双桥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5a314a7f581b536a94b7d9babbea644c', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满奉天市长、伪华北政务委员会顾问', NULL, '原籍河北，后投靠日本，参与伪满政权建立，协助日本在华北推行殖民统治，镇压抗日力量。', '河北承德_双滦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7e87e93220215e26a84b5d4bf583ecc8', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北治安军总司令', NULL, '河北宁河人，组织伪治安军配合日军扫荡冀东、热河等地，残害抗日军民。', '河北承德_双滦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7023fe6ac7685aa49509d2d1b207ca01', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府主席', NULL, '虽非承德籍，但所辖冀东地区包括今承德部分区域，与日军勾结，建立伪政权，破坏抗日活动。', '河北承德_双滦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6d01b41d85595cae93de5a14cd7fd678', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令、伪热河省警备司令', NULL, '热河（今承德）人，率伪蒙古军协助日军侵占热河，后在承德地区驻防，镇压抗日游击队。', '河北承德_双滦');
