INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9f898b8c1e7d5b4ca834a6ab142a52d0', 'a4b6b520415e5c858408bae9e7e4f97d', 1943, '伪华北剿共军司令（后期投敌）', NULL, '虽为军阀出身，但在热河地区活动时曾与日军合作，其部队在承德周边参与“剿共”行动。', '河北承德_双滦');
