INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b1d3e0551f3553bc8217798950abdbac', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪热河省警备司令', NULL, '原东北军将领，1933年投敌，任伪热河省警备司令，协助日军镇压围场、承德地区抗日武装，参与“治安肃正”行动，残害抗日军民。', '河北承德_围场');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1adb25bd8c5b54e1af5765405d9251af', '2ccc9a42e40e54a5b4d02397b3fcd7fd', 1935, '伪围场县县长', NULL, '任伪围场县县长期间，推行保甲制度，强征民夫修建警备道路和碉堡，为日军提供粮秣情报，多次配合日伪军“扫荡”围场抗日游击区。', '河北承德_围场');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9b9a42a3613a56b184cbf67c207f2180', '142ed91c1ea95b6d922d76d4627e2b83', 1933, '伪蒙古军总司令', NULL, '热河土匪出身，投日后任伪蒙古军总司令，其部队长期活动于围场、赤峰一带，参与镇压抗日义勇军，掠夺当地资源，协助日军建立伪政权。', '河北承德_围场');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('022b1f54575454a4b83a008812b3d390', '3c0cec769a465f2da5d9587d32cf51f4', 1934, '伪热河省警务厅长', NULL, '原热河地方警察头目，投日后任伪警务厅长，在承德、围场等地建立特务情报网，抓捕抗日地下工作者，指挥伪警察配合日军“清乡”。', '河北承德_围场');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2a9b3aaa6fbd5a5684ed3606b2e9d204', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪满洲国热河省省长', NULL, '1933年日军侵占热河后投敌，任伪热河省省长，协助日军镇压抗日武装，推行殖民统治，在宽城、承德一带强征劳工、掠夺资源。', '河北承德_宽城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0771a93eff975bdd91c56ab39b6645dd', '052953092dd65cd0842745f73b88095e', 1933, '伪满洲国青龙县（含今宽城部分区域）县长', NULL, '在宽城、青龙一带为日军效命，组织伪警察和保甲制度，参与“治安肃正”，围剿抗日游击队，强征民夫修建警备道路和碉堡。', '河北承德_宽城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ae95fe9c0d5f5e74bfd6cb48696666c6', '4dfc0c6aac7d5712bc027bb01cad49ca', 1934, '伪满洲国宽城警察署署长', NULL, '长期在宽城地区担任伪警察头目，抓捕抗日军民，刑讯逼供，多次带队“讨伐”抗日武装，并协助日军实施“集家并村”政策。', '河北承德_宽城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8ca7ea67b0d25f918bc9dae91507c5c6', '2bba12a586dc5fdcb92c600fd3c53bbc', 1935, '伪宽城协和会会长', NULL, '在宽城地区宣传“日满亲善”，组织协和会分会，刺探抗日情报，强迫民众参加“勤劳奉仕”，为日军提供物资和人力。', '河北承德_宽城');
