INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('675031c063ed5b0c8298143c3dadaab1', '181a098fc1fb5ed5a72da41548f64fed', 1932, '伪满洲国参议、伪热河省民生厅长', NULL, '原东北军将领，投日后在伪热河省任职，推行日伪奴化教育，强征粮食和民夫，为日军侵华战争服务。', '河北承德_隆化');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('244e21f4da365d08977b4656510d985f', 'c8a80042591a58269f0254a2c8cc2851', 1932, '伪满洲国治安部大臣、伪热河省警务厅长', NULL, '原奉系军官，投日后负责热河地区伪警察体系，协助日军搜捕抗日分子，在隆化等地设立集中营和特务机构。', '河北承德_隆化');
