INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7ce53eb9776753a2a3c741b92c48f929', 'ad0c9f9af10054c68d58a879c97add74', 1938, '伪华北政务委员会下属伪军头目（后反正）', NULL, '原国民党将领，一度与日军勾结，在沧州、衡水一带组织“冀察战区挺进军”与八路军摩擦，后因内部矛盾被日军抛弃，其部属部分投敌成为伪军。', '河北沧州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('da1d2b2d4b0c534cac663fdd849f1b2e', 'a3eb8307fd6a5cd5a48713eabac55d34', 1938, '伪沧县知事', NULL, '任伪沧县知事期间，积极推行日伪保甲制度，建立“自卫团”协助日军清乡，多次向日军提供八路军活动情报，并参与屠杀抗日军属。', '河北沧州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4a4cb9e9f19753de8c76a09414a4c168', '0c6268d47d1656aeaa4e03096f2d60ea', 1939, '伪津海道（沧州属）保安队司令', NULL, '统率伪保安队数千人，配合日军对沧州、河间、献县等地进行“扫荡”，烧毁村庄、掠夺物资，并参与制造多起惨案。', '河北沧州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('99894fdb26f95087a43eb90493777532', 'd844b2aa7baa5a3288f89eb4dd6f9a99', 1937, '伪盐山县维持会会长', NULL, '日军占领盐山后率先组织维持会，为日军筹粮派款，强拉壮丁充实伪军，并指使汉奸特务破坏抗日地下组织。', '河北沧州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('995cc58088965d5cbb4defeaa2b37a31', '29b4079aa77d5c5b8908d899dde123b2', 1938, '伪东光县县长', NULL, '投靠日军，任东光县伪县长，推行日伪统治，强征粮税，镇压抗日民众。', '河北沧州_东光');
