INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3c1569026d6e53c3bd4cd3c8a5e3ce80', 'b7851a2bb17955198176ccbac07d2d06', 1940, '伪津南道保安副司令（活动于沧州地区）', NULL, '在沧州、吴桥一带指挥伪军围剿八路军，烧杀抢掠，破坏抗日组织，后随日军投降。', '河北沧州_吴桥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('143a862b17a152d486a436465ef404f8', 'a3eb8307fd6a5cd5a48713eabac55d34', 1939, '伪吴桥县警察所所长', NULL, '效忠日军，建立特务网络，搜捕抗日地下党员，刑讯逼供，残害百姓。', '河北沧州_吴桥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cbe371e270f25b69a9f5b0e09ef276b1', '29b4079aa77d5c5b8908d899dde123b2', 1937, '伪沧县县长', NULL, '投靠日军后任伪沧县县长，协助日军推行“治安强化运动”，镇压抗日群众，征收苛捐杂税，提供情报配合日军扫荡冀鲁边区抗日根据地。', '河北沧州_孟村');
