INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('70476be1f68c57eca071722477ba8d97', '59deec8ad3625443a6189415feb7e2f3', 1938, '伪青县新民会会长', NULL, '在青县运河段推行奴化教育，组织汉奸情报网，破坏抗日群众组织，协助日军强征劳工。', '河北沧州_运河');
