INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c6725a145b8d59259900329cacb5a731', '3d749df4036853df9ae3fcfecd4a76ae', 1939, '伪沧县（含今黄骅部分区域）警备大队长', NULL, '长期盘踞沧县东部及黄骅沿海地区，为日军运输物资、封锁港口，抓捕抗日志士，并强征民夫修建炮楼和封锁沟。', '河北沧州_黄骅');
