INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9e2fc22cbe335fb3afc60391e1a386ec', '340adba25424535985417eba5e18abbe', 1935, '伪冀东防共自治政府民政厅长、伪河北省民政厅长', NULL, '长期在河北伪政权任职，参与建立保甲连坐制度，在石家庄地区镇压抗日群众。', '河北石家庄');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ab4d94e79062565580687bf156f24d21', 'a3eb8307fd6a5cd5a48713eabac55d34', 1938, '伪冀南道尹（辖石家庄部分县）', NULL, '原军阀，投日后任伪冀南道尹，管辖石家庄南部各县，组织伪警备队清乡。', '河北石家庄');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eb181ffdc3a059bb926fda6e70d43701', 'eaa98601735151758eb8003f30e945e6', 1938, '伪真定道尹（石家庄地区）', NULL, '伪真定道（驻石家庄）最高行政长官，直接管理石家庄及周边各县，推行“治安肃正”，强征劳工。', '河北石家庄');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('39ba659a0d6153a39453dc9f3e03bc48', '850ba88ee60a5a9ea2c48c5301c93805', 1938, '伪石家庄市市长', NULL, '首任伪石家庄市长，建立伪市公署，配合日军对市区进行军事管制和人口清查。', '河北石家庄');
