INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7c24ddf607cf5628bfc8965c3deac16e', '6f751e18423658f9ab3bd9eec482adb9', 1940, '伪赵县知事', NULL, '在赵县（今属石家庄）任伪知事，强征青年加入伪军，并参与“五一大扫荡”行动。', '河北石家庄');
