INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('852ae2b5cb315e059e34511bfa61ef15', '2e498fb74f2d5d20a037235fa2d14f1c', 1940, '伪行唐县知事', NULL, '在行唐县任伪知事，推行“连坐法”，杀害抗日军属，并参与“治安强化”运动。', '河北石家庄');
