INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7d965aad7cba53abbaadb30d0d2b0e17', 'd9a514f9cc9b5dc39e4b19b63e0bbd39', 1939, '伪石家庄宪兵队翻译官', NULL, '为日军宪兵队担任翻译，参与刑讯逼供抗日志士，直接导致数十人牺牲。', '河北石家庄');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6773e6943d1c5169b384931de4f3fd30', 'eec2c533207f505a9cee190adb48cd37', 1940, '伪石家庄警察局局长', NULL, '管理伪警察，协助日军进行户口清查，抓捕地下党员。', '河北石家庄');
