INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('08a2b7559b035bda83bae9027a492f90', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北政务委员会治安总署督办、伪华北绥靖军总司令', NULL, '原北洋军阀，投日后在石家庄及华北地区组织伪治安军，协助日军扫荡抗日根据地，镇压抗日军民。', '河北石家庄');
