INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b56b815cc672595a949d562dfdded2cf', '190dabfac9075fad8821b4606545bb75', 1942, '伪河北省省长（后期）', NULL, '在石家庄一带强化伪政权统治，组织保甲制度，协助日军进行经济掠夺和物资统制。', '河北石家庄');
