INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dd6db0b9d58350f589bd55f238419db9', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府主席（影响石家庄地区）', NULL, '虽以冀东为主，但其伪政权势力曾延伸至石家庄一带，策动地方分离，为日军侵略提供政治掩护。', '河北石家庄');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('039fab4647995896b7882d139aeb9a60', '32d70db4931754aab3d50afa4e5d738a', 1937, '伪河北省政府委员、伪天津特别市市长（曾涉石家庄）', NULL, '参与组建河北伪政权，在石家庄地区协助日军清乡，抓捕抗日志士。', '河北石家庄');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7f07b73517275030a52b77b01949a600', 'a3eb8307fd6a5cd5a48713eabac55d34', 1937, '井陉县伪县长', NULL, '日军占领井陉后出任伪县长，协助日军推行保甲制度，强征民夫，搜刮粮食，镇压抗日群众。', '河北石家庄_井陉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3de76de922ee54c7be5981a2e8d1a9ee', '2263cc4d807b589b840da11fa34004e0', 1938, '井陉县伪保安联队队长', NULL, '组织伪保安队配合日军扫荡抗日根据地，多次袭击八路军游击队，杀害抗日干部和群众。', '河北石家庄_井陉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a389fb08f270506fa2e37b9e0d76b97e', '120b2287cec25d49a1da8a468367070b', 1938, '井陉矿伪矿长', NULL, '管理日军控制的井陉煤矿，强迫矿工超负荷劳动，克扣工资，向日军提供煤炭资源，迫害抗日矿工。', '河北石家庄_井陉');
