INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d71302b1a0ad575e9ffe7e0afb8b0ded', '805dcb001bbe5f8782dcde83d247d210', 1939, '井陉县伪警察局局长', NULL, '指挥伪警察抓捕抗日地下党员，破坏抗日组织，参与“治安强化运动”，残害百姓。', '河北石家庄_井陉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('da610f4bdd945a84a044dac71077e1d8', 'a36aa29d94ad5885b0a729c66f783d15', 1940, '井陉县伪教育科长', NULL, '推行奴化教育，强迫学校使用日伪教材，宣扬“中日亲善”，禁止传授中国历史。', '河北石家庄_井陉');
