INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8f9f220087f856c5b41a5b6f7171d8c1', '5b560385786f5ebc9f8f38276f67ad6f', 1938, '河北省伪保安司令（驻保定，指挥石家庄伪军）', NULL, '统辖全省伪保安队，多次调集伪军参与对石家庄西部山区（含井陉）的“讨伐”，杀害抗日军民。', '河北石家庄_井陉');
