INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eaf53db05a705e9c91386d3b53cd8922', '2263cc4d807b589b840da11fa34004e0', 1938, '井陉矿伪矿长', NULL, '充当日军控制的井陉煤矿伪矿长，为日军掠夺煤炭资源服务，迫害矿工，破坏抗日活动。', '河北石家庄_井陉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8e54c7b3d6dc569a90ebcd42212dd379', '120b2287cec25d49a1da8a468367070b', 1939, '石家庄伪商会会长', NULL, '任石家庄伪商会会长，为日军筹措物资，强迫商户捐款，协助日伪经济封锁。', '河北石家庄_井陉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d94a7442240551f99908b7bfc4bfbbac', 'f507817e989158b6a3fd828c617b43cd', 1940, '伪华北政务委员会委员长（涉及河北）', NULL, '作为伪华北政权头目，其势力范围覆盖河北包括石家庄、井陉地区，推行奴化教育，配合日军“扫荡”。', '河北石家庄_井陉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f0a7cec13ce1548a8df30107b9e1ebcb', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1939, '伪华北治安军总司令（活动于河北）', NULL, '指挥伪治安军在河北各地包括石家庄、井陉一带协助日军清剿抗日武装，制造多起惨案。', '河北石家庄_井陉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b5ebca8baf3557e98e4936d62f003272', '4d2d3d155bb454339a738c1c49764a53', 1937, '伪华北政务委员会委员长', NULL, '原北洋政客，1937年北平沦陷后出任伪中华民国临时政府行政委员会委员长，后任伪华北政务委员会委员长，管辖包括河北在内的华北地区，推行日伪统治政策，协助日军经济掠夺和治安强化运动。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('afe6f50192215a82a1d6f8401a3c3437', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北治安军总司令', NULL, '原直系军阀，投日后任伪华北治安军（绥靖军）总司令，在河北、石家庄等地组织伪军配合日军扫荡抗日根据地，镇压抗日力量。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('da9b546dd7635d5595964bd8164f8722', '5b560385786f5ebc9f8f38276f67ad6f', 1938, '伪河北省省长', NULL, '原北洋将领，投日后任伪河北省省长，在石家庄等地推行日伪政权，强征粮税，协助日军建立保甲制度，迫害抗日军民。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1eed5b15846d5169b9080388b273882a', '190dabfac9075fad8821b4606545bb75', 1940, '伪河北省省长', NULL, '原国民党地方官员，投日后任伪河北省省长，在石家庄、井陉矿区强化日伪统治，配合日军对冀中、冀西抗日根据地进行“扫荡”和“清剿”。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('27e8504015cb5d59af03cc447a626221', '7c51a2464caa5e18aaf829b24f6c43bc', 1943, '伪河北省省长', NULL, '原东北军将领，投日后任伪河北省省长，在石家庄地区推行日伪“新国民运动”，强征劳工，掠夺井陉煤矿资源。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d3111bde79c056d180e7cc868f8f30eb', '340adba25424535985417eba5e18abbe', 1938, '伪石家庄市市长', NULL, '投日分子，任伪石家庄市市长期间，建立日伪市政机构，推行奴化教育，协助日军控制石家庄交通枢纽和井陉煤矿运输。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5d6a5eb4c00c5f6ea6964a300904c5d6', 'ae5e62ce9181549e82e0d8ae0327fbba', 1940, '伪石家庄市市长', NULL, '原新闻界人士，投日后任伪石家庄市市长，在井陉矿区强化治安，组织伪警察镇压矿工反抗，为日军提供煤炭资源。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3f9700ede067505a9352c0e2682f2a22', 'ad87f7e4a912559c80661050e7208ba3', 1942, '伪石家庄市市长', NULL, '投日官员，任伪石家庄市市长期间，配合日军“治安强化运动”，在井陉矿区设立伪保甲组织，强征矿工劳役。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7fd75fa7ff6b56d1aad427cc06e99722', '27c3b75378305b0fac02727f80ff2c3d', 1937, '伪井陉矿务局局长', NULL, '原井陉煤矿中方管理人员，日军占领后投敌，任伪井陉矿务局局长，为日军开采煤炭，残酷压榨矿工，导致大量矿工死亡。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('13a4b4bb848c58099cca2ca6768f103b', '332f51c15bef586eb8d0a9e9b7707442', 1941, '伪井陉矿务局局长', NULL, '投日矿务官员，继任伪井陉矿务局局长，扩大煤炭生产供日军军需，组织矿工“勤劳奉仕”，镇压矿工罢工和抗日活动。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('266890f5247e5755827fc88b533a0cdc', '132ca09a10c5518383fc783d3db3266b', 1938, '伪冀西保安队司令', NULL, '原地方土匪武装头目，投日后任伪冀西保安队司令，活动于石家庄、井陉一带，多次配合日军袭击八路军游击队，残害抗日群众。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('51492e51cd5a51c0a0eec976b7249736', 'a5db6ac48f775b13b780a694d8dec4d1', 1938, '伪井陉县知事', NULL, '投日汉奸，任伪井陉县知事，在井陉矿区推行日伪政权，强征粮食和劳工，协助日军建立“爱护村”以隔离抗日武装。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d1d962953d125360ba1221af82059a88', '805dcb001bbe5f8782dcde83d247d210', 1940, '伪井陉县知事', NULL, '投日官员，任伪井陉县知事，在矿区实施“连坐制”，抓捕抗日地下工作者，向日军提供井陉煤矿情报。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('74cf8098f365582a88ce6234a840eab1', '8320e3e3065f5f31a864a1fd27201ca3', 1943, '伪井陉县知事', NULL, '投日汉奸，任伪井陉县知事，配合日军“三光政策”，在井陉山区烧毁村庄，强征民夫修筑碉堡和封锁沟。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('31b862f39a2a53d186b258d0291ec058', 'd9a514f9cc9b5dc39e4b19b63e0bbd39', 1938, '伪石家庄警察局局长', NULL, '投日警察头目，任伪石家庄警察局局长，在井陉矿区设立特务据点，搜捕抗日分子，严刑拷打矿工和地下党员。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8fe79e5a5649573997c7e361bfb34d17', '25403a79f8335f3e96fc8451f78bbb99', 1942, '伪石家庄警察局局长', NULL, '投日汉奸，继任伪石家庄警察局局长，强化对井陉矿区的特务监控，破坏中共地下组织，参与“大检举”行动。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b5ebca8baf3557e98e4936d62f003272', '4d2d3d155bb454339a738c1c49764a53', 1937, '伪华北政务委员会委员长', NULL, '在北平组织伪华北政权，对河北、石家庄及井陉矿区推行日伪统治，协助日军掠夺井陉煤矿资源。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7383239e089d5269986bcc271560da78', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1938, '伪华北治安军总司令', NULL, '指挥伪治安军在河北各地（包括石家庄、井陉矿区）扫荡抗日力量，配合日军“治安强化运动”。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('da9b546dd7635d5595964bd8164f8722', '5b560385786f5ebc9f8f38276f67ad6f', 1938, '伪河北省省长', NULL, '任伪河北省长期间，在石家庄、井陉等地推行保甲制度，强征劳工用于井陉煤矿开采，镇压抗日活动。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('aa5c7a10d63e518eace37741eb5a0ab4', '190dabfac9075fad8821b4606545bb75', 1940, '伪河北省省长（继任）', NULL, '在河北（含石家庄、井陉）强化日伪统治，配合日军对井陉矿区进行经济掠夺，迫害矿工及抗日家属。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ebe20e84c53052a5a3b2961dbeedcc88', '7c51a2464caa5e18aaf829b24f6c43bc', 1939, '伪河北省保安司令', NULL, '在石家庄、井陉一带组织伪保安队，协助日军围剿八路军游击队，破坏抗日根据地。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5dce22b6d11d58d4b1682f75cf6e8367', 'a5db6ac48f775b13b780a694d8dec4d1', 1938, '伪井陉矿警备队队长', NULL, '充当日军爪牙，负责井陉煤矿的警戒，镇压矿工反抗，抓捕并杀害抗日地下工作者。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('20f97136205c50cfbe1e025f217b8cf0', '2263cc4d807b589b840da11fa34004e0', 1939, '伪井陉县知事', NULL, '在井陉县（含矿区）推行日伪法令，强征民夫修路筑堡，协助日军封锁抗日根据地。', '河北石家庄_井陉矿');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('58f31e9d4222501596462adbb577c325', '0f9718e2185859ad9a2919936bdc4e66', 1937, '元氏县伪县长', NULL, '投靠日军，任元氏县伪县长，协助日军推行‘治安强化运动’，强征民夫、粮食，镇压抗日群众。', '河北石家庄_元氏');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3d93231133e2512d81cf2c31a983ee6a', '3d749df4036853df9ae3fcfecd4a76ae', 1938, '元氏县伪保安联队队长', NULL, '率伪军多次扫荡抗日根据地，杀害抗日干部和群众，制造多起惨案。', '河北石家庄_元氏');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c201a949658c5d958358d4e10bc0a620', 'aa7913ec446c597faf6a8833076cf708', 1939, '元氏县伪警察所所长', NULL, '为日军搜集情报，抓捕抗日地下人员，参与‘清乡’行动。', '河北石家庄_元氏');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('308689bc242f521f94fc7a52276fb46e', '805dcb001bbe5f8782dcde83d247d210', 1940, '元氏县伪新民会会长', NULL, '宣传奴化思想，组织‘新民会’活动，诱骗青年参加伪军。', '河北石家庄_元氏');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e0cce29ff87750d9aa81cbdc07d0576a', '0948048118f050898c5e091379fc491b', 1941, '元氏县伪自卫团团长', NULL, '带领伪自卫团配合日军封锁抗日根据地，抢劫百姓财物。', '河北石家庄_元氏');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1032abaeda1a515095bcbac169729255', '6569c31c5dc85c1db61f9a7e89e27750', 1942, '元氏县伪区长（南佐区）', NULL, '为日军催粮派款，告密抗日积极分子，导致多名群众被捕。', '河北石家庄_元氏');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('29f090dbcdb552cd936cade261e96dc8', 'e60d0335f96157edb58448797cda6ce0', 1943, '元氏县伪区长（城关区）', NULL, '协助日军建立保甲制度，强迫村民‘连坐’，镇压反抗日军统治的百姓。', '河北石家庄_元氏');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b3f7b9918eaa51cc8b818116b9a41267', '6dfa2d001b3a5512b9cb9e8d6d0cb83b', 1940, '元氏县伪军大队长', NULL, '率伪军参与‘铁壁合围’扫荡，杀害抗日武装人员及无辜村民。', '河北石家庄_元氏');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f694a098c8d053e99ab97a5e8a7cdce3', 'a4b6b520415e5c858408bae9e7e4f97d', 1943, '冀西伪军暂编第3军军长（活动于元氏一带）', NULL, '原国民党将领投敌，其部队在元氏地区配合日军进攻抗日根据地，抢掠物资。', '河北石家庄_元氏');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('54e30a532dbf5e7794186951d08bff22', '0ec2ee6fed265ec5991932a6ff128192', 1943, '伪河北省保安司令（曾涉元氏地区）', NULL, '投日后任伪职，其下属部队在石家庄、元氏一带协助日军‘扫荡’。', '河北石家庄_元氏');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('58f31e9d4222501596462adbb577c325', '0f9718e2185859ad9a2919936bdc4e66', 1937, '元氏县伪县长', NULL, '投靠日军，任元氏县伪县长，协助日军推行“治安强化运动”，组织伪政权，强征民夫，搜刮粮食，镇压抗日群众。', '河北石家庄_元氏');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3d93231133e2512d81cf2c31a983ee6a', '3d749df4036853df9ae3fcfecd4a76ae', 1938, '元氏县伪保安联队队长', NULL, '率伪军配合日军“扫荡”抗日根据地，杀害抗日干部和群众，破坏抗日组织，烧毁村庄。', '河北石家庄_元氏');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c201a949658c5d958358d4e10bc0a620', 'aa7913ec446c597faf6a8833076cf708', 1939, '元氏县伪警察所所长', NULL, '效忠日军，负责伪警察事务，搜捕抗日地下人员，严刑逼供，协助日军建立情报网。', '河北石家庄_元氏');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('308689bc242f521f94fc7a52276fb46e', '805dcb001bbe5f8782dcde83d247d210', 1940, '元氏县伪新民会会长', NULL, '在元氏推行奴化教育，宣传“中日亲善”，组织汉奸团体，破坏抗日宣传，强迫民众参加伪组织。', '河北石家庄_元氏');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9e5dcdbcb18052c5bdcec8b80e1cbf20', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北政务委员会治安总署督办、伪华北绥靖军总司令', NULL, '原北洋军阀，投日后任伪华北最高军事长官，在河北等地组织伪军配合日军扫荡，镇压抗日力量。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ca9af1b7e747550cb0d0b50471cfe1f1', '5b560385786f5ebc9f8f38276f67ad6f', 1938, '伪河北省省长', NULL, '投日后任伪河北省长，推行日伪政权，在石家庄、平山等地区强征粮税，协助日军建立保甲制度。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7368caabe3fc55e0be5cfc98077f7dc4', '190dabfac9075fad8821b4606545bb75', 1940, '伪河北省省长（继任）', NULL, '继任伪河北省长，在石家庄地区强化治安肃正，配合日军“三光政策”，迫害抗日军民。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f9a00697896c54789ca7dc0ad74f7cc1', '7c51a2464caa5e18aaf829b24f6c43bc', 1943, '伪河北省省长（后期）', NULL, '原东北军将领，投日后任伪河北省长，在平山一带推行“新民会”奴化教育，协助日军经济掠夺。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a20df13d14cb5b5aaff41621545473be', '340adba25424535985417eba5e18abbe', 1939, '伪石家庄市市长', NULL, '伪石家庄首任市长，建立日伪市政机构，在平山等周边县份推行“治安强化运动”，镇压抗日活动。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('823e4830d6715795b806349e4d6477e2', 'ae5e62ce9181549e82e0d8ae0327fbba', 1943, '伪石家庄市市长（继任）', NULL, '继任伪石家庄市长，协助日军控制交通线，在平山地区强征民夫修筑碉堡和封锁沟。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f124c35a8bb5573eafa02dd838a8da07', '5a987d9102265eba9baf4a023d34f9ae', 1938, '伪平山县县长', NULL, '首任伪平山县长，组建伪县公署和伪警察所，多次带日伪军袭击平山抗日根据地，杀害村干部。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('df39b5f334f25dc8b026b39777429189', '7482d659099a5d7faa77e791889019a0', 1940, '伪平山县县长（继任）', NULL, '继任伪平山县长，推行“自首”政策，诱捕抗日干部，在平山洪子店、回舍等地制造多起惨案。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('868091b2bed25e008b62fcf80d10b5e4', '8320e3e3065f5f31a864a1fd27201ca3', 1942, '伪平山县县长（后期）', NULL, '后期伪平山县长，配合日军“蚕食”政策，在平山山区建立伪维持会，强征粮食支援日军。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d2807e235bc95b7f921f8c6816f38f6f', '805dcb001bbe5f8782dcde83d247d210', 1940, '伪平山县保安联队队长', NULL, '伪平山地方武装头目，率伪军多次围剿平山抗日游击队，杀害八路军侦察员和群众。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d0d84220b84b5aafa95c5a522af80c27', 'a5cd3e9d06ec50b0a4a1fb1422e57df2', 1941, '伪平山县新民会会长', NULL, '负责平山日伪奴化宣传，组织“新民会”青年团，破坏抗日群众组织，搜集情报。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('484d73b6744b52a4aeae1e48e8977fe9', 'fea647750e6c5be0bdc4b4a125b7a0df', 1940, '伪平山县回舍镇维持会会长', NULL, '地方恶霸投日，在回舍镇设立维持会，向日军告密抗日积极分子，导致多名群众被捕。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2fa96251be6750a88f1f295e3fff73ec', '7919fe83935950c484b84fc165626e11', 1939, '伪平山县洪子店维持会会长', NULL, '在洪子店一带为日军征粮派款，协助日军烧毁村庄，民愤极大。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8d404e1539225d2bb79a62a2bf327488', '505cacec26355e02a99fda674488026a', 1942, '伪平山县岗南镇汉奸特务', NULL, '充当日军密探，多次带领日军偷袭平山抗日后方医院，杀害伤员。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5963b9ccfb1551fe9e4e4e00e7dd4172', '261b7ca33db35e75b6c6bec87bed70f9', 1942, '伪石家庄地区剿共军司令', NULL, '率伪剿共军驻石家庄，在平山、灵寿边界进行“清剿”，烧毁抗日村庄十余个。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9e5dcdbcb18052c5bdcec8b80e1cbf20', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1937, '伪华北政务委员会治安总署督办、伪华北绥靖军总司令', NULL, '原北洋直系将领，投日后任伪华北最高军事长官，在河北等地组织伪军配合日军扫荡，镇压抗日力量，其势力范围涉及石家庄及平山周边地区。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c525ec13c89551dca3da1f3b2b959abe', '5b560385786f5ebc9f8f38276f67ad6f', 1938, '伪河北省省长、伪冀东防共自治政府委员', NULL, '原北洋军将领，投日后任伪河北省长，在石家庄、平山等地区推行保甲制度，强征粮税，协助日军建立伪政权，破坏抗日根据地。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b81c44c05bdb5437bc2302fff72b18db', '190dabfac9075fad8821b4606545bb75', 1939, '伪河北省保安司令、伪冀南道尹', NULL, '在石家庄地区组织伪保安队，多次配合日军对平山、灵寿等抗日根据地进行“清剿”，杀害抗日干部和群众。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fa6dd67f493e5dcc856a41331284342a', '340adba25424535985417eba5e18abbe', 1938, '伪河北省政府教育厅长、伪华北政务委员会教育总署督办', NULL, '在河北推行奴化教育，在石家庄、平山等地学校强制灌输“中日亲善”思想，迫害爱国师生。', '河北石家庄_平山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b972e93ae44c5e5185b1b7bbf9a270b5', 'f507817e989158b6a3fd828c617b43cd', 1937, '伪华北政务委员会委员长', NULL, '作为华北伪政权最高头目，其统治范围覆盖石家庄、平山地区，支持日军“治安强化运动”，对抗日根据地实行经济封锁和军事围剿。', '河北石家庄_平山');
