INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('46487bc67a515c87882515306f0aad4e', '6dfa2d001b3a5512b9cb9e8d6d0cb83b', 1938, '赵县伪税务局局长', NULL, '为日军征收各种苛捐杂税，盘剥百姓，将大量物资供给日军。', '河北石家庄_赵县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ba3344ba6f135e13839046484420213f', 'a4b6b520415e5c858408bae9e7e4f97d', 1943, '冀南伪军暂编第三军军长（活动于赵县一带）', NULL, '原国民党将领，后投敌任伪军军长，在赵县及周边地区配合日军‘扫荡’，进攻抗日武装。', '河北石家庄_赵县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4c4dfbc638ad5bb3ab8cdcbc11e68bea', '08a1ec477255562bb8a0e3fe6556bf8f', 1939, '冀察战区游击司令（后投敌，活动涉及赵县）', NULL, '在赵县一带反复无常，最终投靠日军，其部队曾协助日军袭击抗日游击队。', '河北石家庄_赵县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('30961549625950819b761e0a153ce15b', '0ec2ee6fed265ec5991932a6ff128192', 1943, '伪第五方面军总司令（曾驻防石家庄地区，影响赵县）', NULL, '国民党将领投敌，任伪军高级指挥官，其势力范围覆盖石家庄及赵县，参与‘扫荡’行动。', '河北石家庄_赵县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('16be136faa88558e98662bee506eebb4', 'ea5fc95149e5572c84e089b03f96040c', 1937, '赵县伪县长', NULL, '投靠日军，任赵县伪县长，协助日军推行“治安强化运动”，强征民夫，搜刮粮食，镇压抗日群众。', '河北石家庄_赵县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bf815c76020f5456b70bb4e405d4852d', '149dcf8873e359459d3e861031b92afc', 1938, '赵县伪保安联队队长', NULL, '组织伪保安队，配合日军扫荡抗日根据地，杀害抗日干部和群众，抢劫财物。', '河北石家庄_赵县');
