INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0a3bd56c3c005979a92fa2e80b4bad95', '8320e3e3065f5f31a864a1fd27201ca3', 1940, '石家庄地区伪自卫团总团长', NULL, '在石家庄及赵县一带组织伪自卫团，协助日军封锁抗日根据地，参与多次“扫荡”，残害百姓。', '河北石家庄_赵县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c3824b8f9cc352458b58700af824bbf1', '6287c6f9060c56a8996f474a62278a73', 1937, '赵县伪维持会会长', NULL, '日军占领赵县后率先投敌，任维持会长，为日军筹粮派款，提供情报，帮助日军建立伪政权。', '河北石家庄_赵县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1a66f98f82f25251ba0c60fb2ffb8b59', 'ea5fc95149e5572c84e089b03f96040c', 1938, '伪辛集县知事', NULL, '任伪辛集县知事期间，协助日军推行保甲制度，强征民夫修筑炮楼，镇压抗日群众，多次向日军提供八路军情报。', '河北石家庄_辛集');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8b93292722da5a869e0bc2d8001c6de9', '149dcf8873e359459d3e861031b92afc', 1939, '伪辛集县保安队队长', NULL, '率伪保安队配合日军扫荡束鹿（今辛集）抗日根据地，杀害抗日干部和群众数十人，抢劫粮食资敌。', '河北石家庄_辛集');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d9094e85f46a56aa9e8a9b1c96b2f41d', 'b84d2d138cd956bbb3bb86a1cfc6aafd', 1940, '伪束鹿县（今辛集）新民会会长', NULL, '积极推行奴化教育，组织“新民会”宣传“中日亲善”，诱骗青年参加伪军，破坏抗日组织。', '河北石家庄_辛集');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e0706c6e48f050748352d01983f560c9', '7349044acae9539594f29ed71bc6c7de', 1937, '伪辛集维持会会长', NULL, '日军占领辛集后首任维持会长，为日军筹粮派款，指认抗日家属，导致多名群众被捕杀害。', '河北石家庄_辛集');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('df13d6e831965542be075aedf21a3a3a', '61eadb27ba095cc29caf3c1b617aef29', 1941, '伪石家庄道尹公署顾问', NULL, '原为石家庄商会头目，投敌后任伪道署顾问，协助日军经济统制，垄断粮食棉花，打压民族工商业。', '河北石家庄_辛集');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b55355d4b47b508983079c859320b22e', '49854bf7a7865ec28683a511345625aa', 1939, '伪石家庄市警察局局长', NULL, '指挥伪警察配合日军搜捕地下党员，破坏石家庄地下交通站，逮捕进步学生并施以酷刑。', '河北石家庄_辛集');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f9ee15c9bf8955b1b64a9beed006c2ce', 'd2015d5b9ed9588387acf3c68eeee390', 1940, '伪石家庄保安团团长', NULL, '率伪保安团多次参与对正定、获鹿等地的“清剿”，烧毁村庄，杀害抗日武装人员及平民。', '河北石家庄_辛集');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('837e888552d95281a49f8491087d2742', 'a4b6b520415e5c858408bae9e7e4f97d', 1943, '伪冀察战区挺进军总司令（后投敌）', NULL, '原国民党将领，1943年投降日军，所部改编为伪军，在石家庄周边地区配合日军进攻八路军，并参与“曲线救国”活动。', '河北石家庄_辛集');
