INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('edc6902b3fb6542395eb075b125698de', '8320e3e3065f5f31a864a1fd27201ca3', 1939, '伪石家庄特务机关情报员', NULL, '为日军提供抗日组织活动情报，导致多名地下党员被捕牺牲。', '河北石家庄_长安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2530760b5dc956dbb5962636f4c73b41', '7d83da19164056e89585bf2075e4c39a', 1940, '伪石家庄商会会长', NULL, '强迫商户向日军捐献物资，控制粮食配给，从中牟利，资助伪军。', '河北石家庄_长安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f3eec31225545555878190f3e8fe4f8f', '0f9718e2185859ad9a2919936bdc4e66', 1937, '伪河北省保安司令、伪华北治安军第1集团军司令', NULL, '原东北军将领，投日后任伪河北省保安司令，在石家庄地区协助日军“扫荡”，镇压抗日军民，后任伪治安军集团军司令，参与对冀中根据地的进攻。', '河北石家庄_长安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7525ed05ad0f51038815985af899599b', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1938, '伪华北政务委员会治安总署督办、伪华北治安军总司令', NULL, '北洋旧军阀，投日后任伪华北治安军最高指挥官，其部队在石家庄、长安（今长安区）一带多次配合日军清剿抗日武装，制造多起惨案。', '河北石家庄_长安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c4bd52e0cd015e9489ffffef1891403c', '5b560385786f5ebc9f8f38276f67ad6f', 1940, '伪河北省长（1940-1943）', NULL, '原北洋军将领，投日后任伪河北省长，驻保定，其行政管辖范围包括石家庄地区，推行保甲制度，强征粮税，协助日军建立“治安强化”区。', '河北石家庄_长安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bbaf2603237d5f50bb95e35875f768a3', '190dabfac9075fad8821b4606545bb75', 1943, '伪河北省长（1943-1945）', NULL, '继杜锡钧任伪河北省长，在石家庄一带强化伪政权统治，配合日军进行“大扫荡”，迫害抗日家属，搜刮民间物资。', '河北石家庄_长安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cc17f16ef65e5797a3380ae581b95217', '5ddb13935d765e6f8714d41d4654e1c7', 1937, '伪冀东防共自治政府保安队头目（后调任石家庄地区伪军头目）', NULL, '原国民党军官，投日后在冀东及石家庄周边组织伪军，参与对正太铁路沿线抗日游击队的围剿，后因内讧被日军处决。', '河北石家庄_长安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3b7033a6d1235007a6e59f761d80268b', '25403a79f8335f3e96fc8451f78bbb99', 1940, '伪石家庄特别市市长（1940-1942）', NULL, '在任期间推行日伪“治安肃正”计划，在长安区（今长安区）一带设立伪警察所，抓捕抗日地下工作者，强征劳工修建军事设施。', '河北石家庄_长安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('71a3bdddfb0750a2b23fdc9628d18f54', 'f507817e989158b6a3fd828c617b43cd', 1940, '伪华北政务委员会委员长（1940-1943）', NULL, '虽驻北平，但其伪政权直接管辖石家庄、长安地区，多次下令“清乡”，支持当地伪军警对抗日力量进行残酷镇压。', '河北石家庄_长安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f9883051ebd152a18c8aadb3a7332b0b', '0f9718e2185859ad9a2919936bdc4e66', 1937, '伪高邑县知事', NULL, '日军占领高邑后出任伪县长，协助日军推行保甲制度，强征民夫修筑炮楼和封锁沟，镇压抗日群众，向日军提供抗日武装情报。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('68237638df25520fb72cf0d10bb7d6e3', '3d749df4036853df9ae3fcfecd4a76ae', 1938, '伪高邑县保安联队队长', NULL, '组织伪保安队配合日军扫荡高邑抗日根据地，多次袭击抗日区公所，杀害抗日干部和军属，抢夺粮食资敌。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7ec84cb32e805920b24de7a2ebab2892', 'cfd3e4c4456951818d23a404aa7cd13d', 1939, '伪高邑县警察所所长', NULL, '负责高邑县城治安，大肆搜捕抗日地下党员和进步青年，严刑逼供，破坏抗日地下组织，为日军提供情报。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ae53e39b6a5955db86f18b0504397974', '805dcb001bbe5f8782dcde83d247d210', 1940, '伪高邑县新民会会长', NULL, '推行奴化教育，组织“新民会”宣传“中日亲善”，强迫群众参加反共集会，协助日军征粮和搜集抗日活动情报。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d5fa20b1893c502bb1acaa13c7d64374', '9ca8f82df12958b9ac4d7381f7eaeeaa', 1941, '伪高邑县第一区区长', NULL, '在城关一带为日军催粮派款，抓捕抗日家属，破坏群众抗日组织，多次带领日军搜查村庄。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1b376b6cf8ca59e2b95038bc0740a813', 'e60d0335f96157edb58448797cda6ce0', 1942, '伪高邑县第二区区长', NULL, '在万城、中韩一带为日军建立“爱护村”，强迫村民报告八路军动向，参与杀害抗日交通员。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b7eda006776253ab970271be095728c7', '98b5ef0fa3fd582990f25a664c57e2df', 1943, '伪高邑县第三区区长', NULL, '在西南岩、北渎一带配合日军清乡，烧毁抗日村庄房屋，抢夺牲畜和粮食，抓捕抗日民兵。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('62a597fc44265680bc1c069e6f24f443', 'e345f27d716a5d1990819e80016498f3', 1940, '伪高邑县特务队队长', NULL, '专门刺探八路军和游击队情报，多次带领特务队夜袭抗日村庄，逮捕并杀害抗日干部，罪行累累。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('45b77b66d732562db38f506f423a8478', 'fd5781316fab54ec85b964acf16144f8', 1937, '伪高邑县维持会会长（初期）', NULL, '日军初占高邑时组织维持会，为日军筹粮筹款，提供向导，协助建立伪政权，后转任伪县公署顾问。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('83db2462ec2b5aca97ff76d12077e7ac', 'a4b6b520415e5c858408bae9e7e4f97d', 1939, '伪冀南道尹（管辖高邑）', NULL, '作为伪冀南道最高行政长官，统辖包括高邑在内的多个县，积极推行日伪“治安强化运动”，督促各县伪政权镇压抗日力量。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('976f8fcfedf6514eaa5175edbdc847f8', '81efd44528465ef987c1886265b3a5d0', 1941, '伪高邑县教育科长', NULL, '强制学校使用日伪教材，推行奴化教育，解散抗日小学，迫害爱国教师，组织学生为日军“祝捷”活动。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('821ea0c50d0552a585571625d1b9437a', '9976b6ee787c55a49f55994aca68e77f', 1938, '高邑县汉奸土匪武装头目', NULL, '投靠日军后组织土匪武装，在高邑、元氏交界地带抢劫商旅，袭击抗日游击队，为日军充当耳目，残害百姓。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bcea60f4838e5bc2b55932dfba636113', '6f99d6e8396d5a1e86cb7f780cd0660c', 1937, '高邑县伪县长', NULL, '投靠日军，任高邑县伪县长，协助日军推行保甲制度，强征民夫，搜刮粮食物资，镇压抗日群众。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d2b6e93e62b756d8b246839b7e24bd64', '149dcf8873e359459d3e861031b92afc', 1938, '高邑县伪保安联队队长', NULL, '组织伪保安队，配合日军扫荡抗日根据地，抓捕抗日军民，杀害多名地下工作者。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('793121b996195489aec64bc03d74ee1b', '0518f249e38156f7b288c3fe0f62f301', 1939, '高邑县伪警察所所长', NULL, '任伪警察所长，负责高邑县城治安，协助日军清查抗日分子，多次带队突袭村庄，掠夺财物。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7460b8120bf4560fa77ca788b85fad5e', '805dcb001bbe5f8782dcde83d247d210', 1938, '石家庄伪商会会长', NULL, '在石家庄（时称石门）任伪商会会长，为日军统制物资、摊派捐款，从中牟利，并协助日军经济掠夺。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f318c2e82ed85793a9acc216acb14605', '5779f8b2ed2459088958922c00530c80', 1940, '冀南道伪道尹（辖高邑等县）', NULL, '任伪冀南道尹，管辖包括高邑在内的多县，推行日伪“治安强化运动”，组织伪军配合扫荡，征收苛捐杂税。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0b3a6bfc78ec5e2589fa2afe0de5f5aa', '81efd44528465ef987c1886265b3a5d0', 1939, '石家庄伪市长（石门市）', NULL, '任伪石门市市长，协助日军建立殖民统治，推行奴化教育，强征劳工，为日军提供后勤支持。', '河北石家庄_高邑');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ec18efbc7f0b52a39635f6f03b7c5877', '0f9718e2185859ad9a2919936bdc4e66', 1937, '伪河北省保安队司令', NULL, '在石家庄地区组织伪军，协助日军扫荡抗日根据地，残害抗日军民。', '河北石家庄_鹿泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('761c655251b2519da9e282b94b9b2186', '5a987d9102265eba9baf4a023d34f9ae', 1938, '伪获鹿县（今鹿泉区）知事', NULL, '在获鹿县推行日伪统治，强征粮税，镇压抗日活动，抓捕并杀害抗日志士。', '河北石家庄_鹿泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e22dc31ce0ab5ab398b691671bedb4a7', '332f51c15bef586eb8d0a9e9b7707442', 1939, '伪石家庄市公署市长', NULL, '主持石家庄伪市政，配合日军经济掠夺，建立保甲制度，协助日军清乡。', '河北石家庄_鹿泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3f26406d50ff5fce89bdfc381728d932', '132ca09a10c5518383fc783d3db3266b', 1938, '伪冀南道尹兼保安司令', NULL, '在石家庄及周边地区扩充伪军，多次参与对正定、获鹿等地的扫荡，杀害抗日干部。', '河北石家庄_鹿泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('489525012d425596b6a5ffd41dfbe89d', '8320e3e3065f5f31a864a1fd27201ca3', 1940, '伪获鹿县警察所长', NULL, '指挥伪警察抓捕抗日地下党员，破坏抗日组织，协助日军在鹿泉地区设立据点。', '河北石家庄_鹿泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('25d154ac6b7e5adaa9477f859280ab16', '0b2e00f047d35a799f6e0f8e40416b8a', 1941, '伪石家庄特务机关长（汉奸翻译）', NULL, '为日军充当翻译，参与审讯和酷刑迫害抗日俘虏，提供情报导致多起抗日行动失败。', '河北石家庄_鹿泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ab3b75c523d0570d94ef110fd6c9b073', 'd9a514f9cc9b5dc39e4b19b63e0bbd39', 1939, '伪获鹿县新民会会长', NULL, '推行奴化教育，组织汉奸宣传队，诱骗青年参加伪军，协助日军征粮。', '河北石家庄_鹿泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('59e15bb36b795c6b969704a9d8e2e054', 'bdfe62d83bca55bcbfd3aa9b0f038a01', 1943, '伪新五军军长（其部在石家庄地区活动）', NULL, '所部在石家庄、获鹿一带与日军合作，围剿八路军游击队，但本人非鹿泉籍，故仅列其部属行为。', '河北石家庄_鹿泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1cd564898eb653c4bbb130ca1bce8019', '2bfd7cea97c4576bb7e91c332d0275e3', 1940, '伪获鹿县保安团团长', NULL, '率伪保安团在鹿泉山区多次袭击抗日武装，烧毁村庄，杀害抗日军属。', '河北石家庄_鹿泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('db32b83955b25a489f2edbf75455b2e4', '1aadec610c17599bb555d2d02824acf3', 1938, '伪石家庄商会会长（汉奸商人）', NULL, '为日军筹措军需物资，垄断粮食棉花贸易，资助伪政权，并告发抗日商人。', '河北石家庄_鹿泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e2f06eee9f495975ba358cca52320c74', '57b3f7e086c05324a1fbd81a9797e6b8', 1937, '伪获鹿县维持会会长', NULL, '日军占领获鹿初期，组织维持会，为日军带路搜捕抗日分子，强征民夫修炮楼。', '河北石家庄_鹿泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('93ad81e7563f5c64a44bcb84e74b7510', 'a48bab22cb22595ab2f87582b1d728b2', 1942, '伪石家庄警察局督察长', NULL, '指挥伪警侦缉队，破坏中共地下交通站，逮捕多名抗日联络员。', '河北石家庄_鹿泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('072a457e40c454719c83b678616c04ae', '0cfa5cb121bd5e43ad3cf2fdadaaf14a', 1937, '伪鹿泉县知事', NULL, '任伪鹿泉县知事期间，积极推行日伪政权，强征民夫，搜刮粮食，配合日军“治安强化”运动，镇压抗日群众。', '河北石家庄_鹿泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ff749117fb5a5e9aa77b222147b00cd9', '7e667a99334858eea8a000540b9ebeaf', 1938, '伪获鹿县保安联队队长', NULL, '率伪军多次扫荡抗日根据地，杀害抗日干部和群众，烧毁村庄，为日军提供情报，是当地罪大恶极的汉奸武装头目。', '河北石家庄_鹿泉');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('92683def7d9b5e6a92f0fe822b0f9188', '332f51c15bef586eb8d0a9e9b7707442', 1939, '伪石家庄市公署顾问', NULL, '作为日伪在石家庄的重要帮凶，参与策划经济统制，垄断物资，协助日军抓捕劳工，并破坏抗日地下组织。', '河北石家庄_鹿泉');
