INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5cea509f919e569e8edd77eb688a6d49', '659c360bcaeb5b3c99261a0c88e38aa4', 1939, '伪临榆县保安大队长', NULL, '在秦皇岛、山海关地区指挥伪保安队，协助日军清乡，抓捕抗日群众，抢掠财物。', '河北秦皇岛_北戴河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6a89594d6ff555c193b9973487a6e77d', 'be830f2d60665f0189881935079af216', 1935, '伪冀东防共自治政府民政厅长、伪河北省公署顾问', NULL, '在冀东地区协助日伪推行“自治”运动，参与建立伪政权，协助日军控制冀东包括秦皇岛、北戴河一带的行政与资源掠夺。', '河北秦皇岛_北戴河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('aebf2d226461562c89cc8765a8111f01', 'd88feff2fed55e8c90f24442be17d7e4', 1935, '伪冀东防共自治政府政务长官（首脑）', NULL, '1935年11月在通州成立伪冀东防共自治政府，管辖包括秦皇岛、北戴河在内的冀东22县，公开投敌，为日军提供后勤与情报支持，镇压抗日活动。', '河北秦皇岛_北戴河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('50eb8cff9419502a96794dc2f7643861', 'c1ba15e6cdf55fd7891106db4277da0d', 1935, '伪冀东防共自治政府外交处长、伪唐山市长', NULL, '在冀东伪政权中负责对日交涉，后任伪唐山市长时间内，管辖范围涉及秦皇岛地区，协助日军推行保甲制度，强征劳工，掠夺当地资源。', '河北秦皇岛_北戴河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8f571c0ca03250fe878ec036eb9bdd45', 'f507817e989158b6a3fd828c617b43cd', 1940, '伪华北政务委员会委员长', NULL, '作为华北伪政权最高头目，其管辖范围包括河北全省及秦皇岛、北戴河地区，积极推行“治安强化运动”，配合日军扫荡，镇压抗日力量，强征粮食与物资。', '河北秦皇岛_北戴河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2bcbdd4d620a5dd79423a02a0c186207', 'a96a39ea6e6258e2b8e07a82eb22b15b', 1939, '伪华北治安军总司令', NULL, '在河北及冀东地区（含秦皇岛、北戴河）组建伪治安军，协助日军清剿抗日游击队，在沿海地区设卡盘查，抓捕抗日人士，为日军维持占领秩序。', '河北秦皇岛_北戴河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('72ef27ee88f35c5d88770bc77fe4721d', '5b560385786f5ebc9f8f38276f67ad6f', 1938, '伪冀东道尹（后改称冀东特别区行政长官）', NULL, '长期担任冀东地区伪行政长官，直接管辖秦皇岛、北戴河等县，推行日伪法令，组织“自卫团”，强征民夫修筑工事，协助日军控制港口与铁路。', '河北秦皇岛_北戴河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('48af508b2d1b51a7970e35a8c71ecee1', 'aa0c8ac73f1156599f0925edb288e06a', 1933, '伪卢龙县知事', NULL, '1933年日军侵占卢龙后，出任伪县知事，协助日军推行保甲制度，强征民夫修筑炮楼，镇压抗日民众，向日军提供抗日武装情报。', '河北秦皇岛_卢龙');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('43b30c22452c5a1a9ce5ae7e26a8ac2e', 'd656f48cf2d85497b35b891007639db9', 1933, '伪卢龙县警务科长', NULL, '组织伪警察队，多次配合日军“扫荡”卢龙北部山区，抓捕抗日干部和群众，参与制造多起惨案，勒索百姓财物。', '河北秦皇岛_卢龙');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2481f9968ba1539191f0c14243944ee3', 'cfd3e4c4456951818d23a404aa7cd13d', 1935, '伪冀东防共自治政府卢龙县顾问', NULL, '作为日本顾问的帮凶，参与改编伪保安队，推行奴化教育，强迫学校使用伪满教材，破坏抗日地下组织。', '河北秦皇岛_卢龙');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2a30fff92b5357738ec53fc6534480c1', '8faac6e6e1df5c1cbb467a551338a5fa', 1937, '伪卢龙县商会会长', NULL, '为日军征购粮食、棉花等战略物资，从中牟利，并强迫商户捐款支持伪军，向日军告密抗日商贩。', '河北秦皇岛_卢龙');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7099a7f4f4e151df91dbd51e949f0323', '8320e3e3065f5f31a864a1fd27201ca3', 1938, '伪卢龙县新民会会长', NULL, '组织新民会宣传“中日亲善”，诱骗青年参加伪军，收集抗日根据地情报，协助日军建立情报网。', '河北秦皇岛_卢龙');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6f3718816fa35e43941c68ba03316617', 'e60d0335f96157edb58448797cda6ce0', 1939, '伪卢龙县保安队大队长', NULL, '率伪保安队多次袭击滦河沿岸抗日村庄，烧毁房屋，抢掠财物，杀害抗日军属，并参与“治安强化运动”。', '河北秦皇岛_卢龙');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('35b6596134ce5a3896561e621d5b9e9d', '948107882bd159d6a1053331b9f59ed2', 1940, '伪卢龙县警察所所长', NULL, '严刑拷打被捕抗日人员，指认地下党员，破坏卢龙县交通站，导致多名交通员牺牲。', '河北秦皇岛_卢龙');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('97b7b7974b8659efbf30e42508d54c28', '49854bf7a7865ec28683a511345625aa', 1941, '伪冀东道公署卢龙县联络员', NULL, '负责与日军宪兵队联络，提供抗日武装活动路线，参与策划“铁壁合围”行动，致使八路军游击队损失惨重。', '河北秦皇岛_卢龙');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d9b8a272080056f5953f428d3c2929e0', 'fd0b174468f856638bd0fb256d267c93', 1938, '伪卢龙县教育科长', NULL, '强制推行日语教育，删改历史教材，宣扬“王道乐土”，迫害爱国教师，禁止学生传唱抗日歌曲。', '河北秦皇岛_卢龙');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('28eb1f5526015f7d913ac681ec2ffc5c', '5ce1c02ef79359899d18ca6eb9d942cd', 1942, '伪卢龙县自卫团团长', NULL, '组织地主武装自卫团，配合日军封锁山区，盘查过往行人，多次伏击八路军运输队，杀害掉队伤员。', '河北秦皇岛_卢龙');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ff8007efd1015c0cb01fa8006e87a3e7', 'aa0c8ac73f1156599f0925edb288e06a', 1938, '伪卢龙县知事', NULL, '任伪卢龙县知事期间，协助日军推行保甲制度，强征民夫修筑炮楼，并配合日伪军扫荡抗日根据地，抓捕抗日军民。', '河北秦皇岛_卢龙');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3aca09ae1ef95704994e6489302d9643', '33f48787d6295324995de4d2f715fb78', 1935, '伪冀东防共自治政府保安队头目', NULL, '原为冀东保安队军官，后投靠日军，在卢龙、秦皇岛一带协助日军维持治安，参与镇压抗日武装，并强迫百姓种植罂粟。', '河北秦皇岛_卢龙');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ac066695934851e197ca86ea1c9cace1', '340adba25424535985417eba5e18abbe', 1935, '伪冀东防共自治政府民政厅长（曾管辖卢龙地区）', NULL, '作为伪冀东政权核心成员，推动卢龙等县建立伪组织，配合日军经济掠夺，强征粮食和劳工。', '河北秦皇岛_卢龙');
