INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d84a0b755aee589681b54d15eb23229e', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满洲国立法院院长、伪华北政务委员会顾问', NULL, '原为奉系人物，后投靠日本，参与伪满洲国建立，并协助日本在华北推行殖民统治，曾到山海关一带活动', '河北秦皇岛_山海关');
