INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5fee187d27825f6db0660daf52522408', '0ec2ee6fed265ec5991932a6ff128192', 1943, '伪第二十四集团军总司令（活动涉及邯郸地区）', NULL, '国民党将领投敌，任伪职，其部队在邯郸、馆陶一带参与‘清剿’八路军，制造惨案。', '河北邯郸_馆陶');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('baadd4e25b8e5ca3bddc17e47655f1a0', 'ea55418bb64358919749be99b10c7957', 1939, '伪冀南道尹（管辖邯郸、馆陶等县）', NULL, '为日军推行伪政权，组织伪行政机构，强征壮丁，搜刮民财，镇压抗日活动。', '河北邯郸_馆陶');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('644be8b4b13f5acfa7d58a6cfda05cb2', '63d72c059de65adb9b3f8d6a41f47f49', 1938, '伪馆陶县知事', NULL, '投靠日军后出任馆陶县伪政权首脑，协助日军推行“治安强化运动”，强征民夫修筑炮楼、封锁沟，并组织伪警备队配合日军扫荡抗日根据地，多次抓捕抗日军民送交日军处决。', '河北邯郸_馆陶');
