INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6f7e8b986d365c3c802fdc461225b4a8', '87337018bc85555cb8cd92602b5c34ea', 1941, '伪邯郸道尹公署顾问（兼馆陶事务）', NULL, '作为日伪在邯郸地区的汉奸头目之一，参与策划对馆陶、大名等地的经济掠夺，强制推行“配给制”，垄断粮食和棉花贸易，并协助日军建立情报网，破坏地下抗日组织。', '河北邯郸_馆陶');
