INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('154274a094045b0d8f9b34b5f0883de7', '20c077ec34715edda1d6baadaca29d16', 1938, '鸡泽县伪县长', NULL, '投靠日军，任鸡泽县维持会会长及伪县长，协助日军推行“治安强化运动”，强征民夫修筑炮楼，镇压抗日群众，勒索百姓财物。', '河北邯郸_鸡泽');
