INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('53519eaa08b95aaa8ea92822fbd742f9', '29a3392a65d159ecbbda25787e52bd90', 1941, '鸡泽县伪警察所所长', NULL, '效忠日军，负责伪警察系统，搜捕抗日地下人员，破坏抗日组织，为日军提供情报并参与“清乡”行动。', '河北邯郸_鸡泽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3a50ab9d5c755de998375bc8fe6b95bb', '3bb982868cff5e47850b8fe730b0666a', 1942, '鸡泽县伪自卫团团长', NULL, '组织伪自卫团，协助日军在鸡泽东部地区建立据点，强迫村民“连坐”，征收苛捐杂税，欺压百姓。', '河北邯郸_鸡泽');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c91815f7c3d350eebf7f318645627523', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，后任伪满军政部大臣，为日本侵略者效力。', '辽宁丹东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a1984db9cf57509398005e4f6887133c', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满第一军管区司令、伪满治安部大臣', NULL, '原东北军旅长，1932年投敌，任伪满第一军管区司令，在辽宁东部（含丹东地区）围剿抗日义勇军，后升任伪满治安部大臣。', '辽宁丹东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0eebff18d25a54e38220b6a60873f33b', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满安东省省长', NULL, '原安东地区地方势力，投日后任伪满安东省省长，管辖今丹东一带，协助日军推行殖民统治，镇压抗日活动。', '辽宁丹东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b77b870a300f59a8b61a44421d0280c3', 'f13fea3281b35a0ea71eb3863d7d53f7', 1933, '伪满安东省警务厅长', NULL, '在丹东地区任伪警务厅长，组织警察特务搜捕抗日志士，破坏地下抗日组织，参与“讨伐”抗日联军。', '辽宁丹东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('445936e14e4c55a9b7ee9d066d2ec99a', '3de6f584b1b75a69a535180aca36f08a', 1937, '伪满安东市市长', NULL, '任伪安东市（今丹东）市长，推行日伪经济统制，强征劳工，协助日军建立治安维持会，镇压市民反抗。', '辽宁丹东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5a856c41149451d4831df53e80f23236', 'ecf6a1b1a6ed56a98f906eec390e855f', 1934, '伪满安东地区警备司令', NULL, '原东北军军官，投日后任安东地区警备司令，率伪军多次“扫荡”宽甸、凤城等抗日游击区，杀害抗日军民。', '辽宁丹东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('298846789c045e2788b2a08d0c3828fe', '79bb05de63395319ab27fff095ca2ac8', 1935, '伪满安东省协和会会长', NULL, '任伪安东省协和会会长，宣传“日满亲善”，组织汉奸团体，配合日军进行思想奴化，收集抗日情报。', '辽宁丹东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('80a8a42a60e75c50bb69d77916bbd424', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满安东省高等法院院长', NULL, '在丹东地区任伪高等法院院长，以法律名义迫害抗日人士，判处大量爱国者死刑或重刑，为日伪统治服务。', '辽宁丹东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dd3ba64642f55af59a2e2fcd908fc662', '1c5a7c0239a3585ba753fb5dd8066643', 1933, '伪满安东省实业厅长', NULL, '在丹东地区任伪实业厅长，协助日本掠夺安奉铁路沿线资源，强占农民土地，为日军提供物资支持。', '辽宁丹东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7ba2ddff5f365bc4ae93f7702bdcd46b', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满国务总理大臣（曾涉安东地区）', NULL, '虽为伪满中央高官，但多次到安东（丹东）视察，推动“治安肃正”，支持当地伪军警镇压抗日武装。', '辽宁丹东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('366e404a91c65875a1cc40b1e3339d27', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八事变后投敌，曾任伪满热河省省长，协助日军镇压抗日武装，后任伪满军政部大臣，参与伪满政权核心决策。', '辽宁丹东_东港');
