INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d5a1267f9cb5525f9d1463fd91ed1aa4', '1ea6405224d35b439d5a62eb23dca975', 1937, '伪满安东省省长', NULL, '曾任伪满安东省（今丹东地区）省长，积极推行日伪政策，强征劳工，协助日军清剿抗日游击队。', '辽宁丹东_东港');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e5cd4a24cdb657a98a0646da53975737', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满安东省警务厅厅长', NULL, '在安东（丹东）地区任伪警务厅长，抓捕抗日志士，破坏地下抗日组织，参与制造多起屠杀事件。', '辽宁丹东_东港');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('573bb64778215685a7c40007c7c484a3', '3de6f584b1b75a69a535180aca36f08a', 1932, '伪满东边道保安司令', NULL, '活动于东港、凤城一带，率伪军配合日军围剿抗日义勇军，烧毁村庄，残害百姓。', '辽宁丹东_东港');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ecb89592f45a56a3af96495530be637d', 'ecf6a1b1a6ed56a98f906eec390e855f', 1933, '伪满安东地区警备军司令', NULL, '驻守安东（丹东）及东港地区，多次率伪军进攻抗日根据地，杀害抗联战士及群众。', '辽宁丹东_东港');
