INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fa4a977f79235c73a923be81e1afe1ab', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日义勇军，后任伪满军政部大臣，协助日军统治辽宁地区。', '辽宁丹东_凤城');
