INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('36124f45f2a6596fadd94399703cd6a5', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满参议府议长', NULL, '清末举人，曾任奉天省议会议长，九一八后投靠日本，参与策划伪满洲国成立，任伪满参议府议长，为日伪统治出谋划策。', '辽宁丹东_凤城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('20a02f0e1d95545a9d9c43b2a1c88632', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满奉天省省长、伪满民政部大臣', NULL, '原东北军将领，曾任辽宁省政府主席，九一八事变后被日军俘虏，随即投敌，任伪满奉天省省长，后任伪满民政部大臣，协助日军统治辽宁。', '辽宁丹东_凤城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('77c9fc075d175578a4f2ff0916db6a15', '2300e528128d54c19855a4669664572a', 1931, '伪满财政部大臣、伪满宫内府大臣', NULL, '原吉林省政府委员，九一八后投日，参与建立伪满洲国，虽主要活动于吉林，但曾参与辽宁地区日伪政权建设，任伪满财政部大臣。', '辽宁丹东_凤城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c5fe4f716f875efabc7c629ffbe6e60f', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满洲国国务总理大臣', NULL, '原东北军将领，九一八后投日，曾任伪满参议府议长、军政部总长，后任伪满国务总理大臣，是日伪在东北（含辽宁）的最高傀儡。', '辽宁丹东_凤城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('81953a2e3e44548c9a35c07ee2955eb8', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长', NULL, '原奉系律师，九一八后投日，参与起草伪满洲国《建国宣言》，任伪满立法院院长，曾为日军在辽宁的殖民统治提供法律支持。', '辽宁丹东_凤城');
