INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e8d90c9fe705527690fa50c72c1c629c', '6f751e18423658f9ab3bd9eec482adb9', 1932, '伪满安东省税务局局长', NULL, '原安东税务官员，投日后任伪满安东省税务局局长，在丹东、凤城地区强征各种苛捐杂税，搜刮民财。', '辽宁丹东_凤城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('25fdf53cecc7511d84d81b4a01574597', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满第5军管区司令', NULL, '原东北军将领，九一八后投敌，曾任伪满热河省省长，在宽甸、丹东一带协助日军镇压抗日武装，推行殖民统治。', '辽宁丹东_宽甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a1c1a7838586587d9bc1890d3fc643f5', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满奉天省省长、伪满治安部大臣', NULL, '原东北军旅长，投日后任伪满奉天省省长，管辖包括宽甸在内的辽东地区，配合日军“讨伐”抗联，强征劳工。', '辽宁丹东_宽甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e585af3168cd54e38ee9cfb99028acab', '1ea6405224d35b439d5a62eb23dca975', 1937, '伪满安东省省长', NULL, '伪满安东省（今丹东地区）最高行政长官，推行日伪“治安肃正”，在宽甸等地设立警察机构，迫害抗日军民。', '辽宁丹东_宽甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('db1abd9ac5725295b62fea81d66036cb', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满安东省警务厅长', NULL, '负责安东省（含宽甸）警察特务系统，指挥抓捕抗日地下人员，参与制造多起屠杀事件。', '辽宁丹东_宽甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7f8561ff4e125b4ebdb65a054b4ff3b7', '3de6f584b1b75a69a535180aca36f08a', 1932, '伪宽甸县县长', NULL, '首任伪宽甸县长，协助日军建立伪政权，强征民夫修建警备道路和碉堡，镇压当地抗日义勇军。', '辽宁丹东_宽甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('98dcc7b2d3c05ffd9fa146d6ef0a2426', '1885517c4b5b53f093b96c0dece295e7', 1937, '伪宽甸县县长', NULL, '继任伪宽甸县长，推行“归屯并户”，制造无人区，配合日军围剿杨靖宇领导的抗联部队。', '辽宁丹东_宽甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('65a8b299d02652618cd5b7912c060192', '0e3cb744f8ba581bb4073554347ef113', 1933, '伪宽甸县警察署署长', NULL, '长期担任宽甸警察头目，直接指挥“讨伐队”，多次袭击抗联密营，杀害抗日群众。', '辽宁丹东_宽甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1940d6b6e23c53a0b7db2cbffdf50c17', 'fdc924a005d9538a8da27a0094bf8f69', 1938, '伪宽甸县协和会会长', NULL, '负责日伪思想宣传，组织“协和会”搜集抗日情报，煽动民众告密，破坏地下抗日组织。', '辽宁丹东_宽甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9ae2206066655d0eabdce724c43d2f0d', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满洲国国务总理大臣', NULL, '虽为伪满中央高官，但多次到安东、宽甸视察，推动“治安强化”政策，对当地抗日力量进行系统性镇压。', '辽宁丹东_宽甸');
