INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fec850082bc251f9bf38ed1dbcd3b577', 'cfc937867ee15c178a5ccff259be8ac9', 1934, '伪宽甸县保安队队长', NULL, '带领保安队配合日军搜山，抓捕抗联交通员，参与“大讨伐”行动，杀害多名抗联战士。', '辽宁丹东_宽甸');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d53cf7e3f9685064ae4d1409c7df58ba', '3c0cec769a465f2da5d9587d32cf51f4', 1939, '伪安东省地方保安局局长', NULL, '负责安东省（含宽甸）地方武装，组织“自卫团”协助日军封锁山区，切断抗联补给线。', '辽宁丹东_宽甸');
