INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b412b450d63b5defb7529842654e41a9', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满参议府议长', NULL, '原奉系文人，投日后任伪满参议府议长，参与制定殖民政策，支持对安东地区的经济掠夺和思想控制。', '辽宁丹东_振安');
