INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0c19de3cb2195c54a7bc6187b7f20584', 'e605798af81b50b78e159caff3e3acc7', 1932, '伪满洲国国务总理大臣', NULL, '原奉系将领，九一八事变后投敌，任伪满最高行政长官，协助日本统治东北，镇压抗日力量。', '辽宁大连');
