INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('56ff2ee07bdd505499554ea2de02a68b', '2300e528128d54c19855a4669664572a', 1931, '伪满洲国财政部总长、宫内府大臣', NULL, '原吉林副司令长官，率先投日，促成吉林沦陷，后长期任伪满高官。', '辽宁大连');
