INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bae1a5839eb25340a55d69d453d6faa4', '762e0b9ffb6359e2a7ffa4a6cc071aa0', 1934, '伪满洲国安东省（今丹东）省长（原辽宁籍）', NULL, '辽宁大连人，投日后历任伪职，在安东省推行“治安肃正”，屠杀抗日群众。', '辽宁大连_普兰店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e3e28f14b2e757d2a7de7e4b3d45bcac', '3de6f584b1b75a69a535180aca36f08a', 1938, '伪普兰店地区保安队队长', NULL, '辽宁复县人，组织伪保安队，配合日军扫荡普兰店周边抗日根据地，烧杀抢掠。', '辽宁大连_普兰店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1878a134663550d98c9188e7e9e60963', '8f60ed6bf0f85a62a7840ff91b875b4f', 1932, '伪满洲国经济部大臣（原辽宁籍）', NULL, '辽宁金州人（今大连金州区），投日后任伪满经济要职，协助日本掠夺东北资源。', '辽宁大连_普兰店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8ee00ac15d715d0ba06a67c8fcda309f', '0da09f00ee6a55878e86adbb70127338', 1932, '伪满洲国财政部大臣（原辽宁籍）', NULL, '辽宁辽阳人，投日后主管伪满财政，为日本侵华战争筹措军费。', '辽宁大连_普兰店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('71c9581593035cbca79f60bd1182fe68', '7afeeb75fc46530b9c3d818f463691f9', 1931, '大连地区汉奸头目、伪大连商会会长', NULL, '长期为日本殖民统治服务，组织伪商会，协助日军征粮、募捐，镇压抗日活动，出卖大连地区抗日志士。', '辽宁大连_沙河口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a86be108b04253c2893617f92cb8ab9a', 'b6338152f2385378a8ba94f3d763879d', 1932, '伪大连警察署署长', NULL, '效忠日本关东军，指挥伪警察搜捕抗日地下组织，多次参与屠杀和镇压大连沙河口地区工人罢工与抗日群众。', '辽宁大连_沙河口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3434bbe53e5a5b4184e093e2bd9b0a1a', '1c5a7c0239a3585ba753fb5dd8066643', 1931, '伪满洲国奉天省省长（曾管辖大连周边）', NULL, '虽非沙河口本地，但作为伪满高级官员，积极推行日本殖民政策，协助日军控制辽宁地区经济与治安，间接影响大连沙河口。', '辽宁大连_沙河口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('323b20c1849e5a73a4e948f577887b2e', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1932, '伪满洲国监察院院长、汉奸政客', NULL, '参与伪满政权建设，为日本侵略者出谋划策，在辽宁地区（含大连）推行奴化教育，镇压抗日力量。', '辽宁大连_沙河口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8d23d070961151a7bf4729d9df813805', '8323526fca8158adb7e5b5c41b4968f9', 1938, '伪大连市市长', NULL, '在任期间全面配合日本殖民统治，强制推行保甲制度，协助日军强征劳工，迫害沙河口地区中国居民。', '辽宁大连_沙河口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8e4315333abf5600a530b775fecf39aa', '313c5f9c10395750a5e45446fc11500f', 1939, '伪大连沙河口区区长', NULL, '直接管辖沙河口地区，为日军提供情报，抓捕抗日分子，强征民夫修建军事设施，欺压当地百姓。', '辽宁大连_沙河口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('10ec1306f83259a39d5b4f881cdc263f', '629954bc42a05671bfe89a32ffe10591', 1940, '伪沙河口警察分署署长', NULL, '指挥伪警破坏中共大连地下组织，逮捕多名抗日志士，参与“沙河口大逮捕”事件，致多人牺牲。', '辽宁大连_沙河口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6a4c1000662f50efa13fbe97a8fa733d', '345a7be6a23556b1b4b545f418450fdc', 1941, '伪沙河口区协和会会长', NULL, '组织协和会宣传“日满亲善”，诱骗青年参加伪军，协助日军进行经济掠夺，监视居民言行。', '辽宁大连_沙河口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cf8001126794540c9cb7990d3d0a0500', 'aa4192005ef257829a741e335b7e8651', 1935, '伪大连港务局沙河口码头把头', NULL, '作为日本人的“包工头”，克扣工人工资，强迫劳工超时劳动，多次向日军告密工人中的抗日活动。', '辽宁大连_沙河口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dc04ba6a55dd50719e9e6b7d0011c9f6', '62a4d32628c35cb08f36429635b022ed', 1942, '伪沙河口区保安队队长', NULL, '率保安队配合日军扫荡，围捕抗日武装，参与杀害沙河口地区抗日群众，罪行累累。', '辽宁大连_沙河口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('58ec18d15a1d5ecab080d6a0d0c5c6c2', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1931, '伪满奉天省省长、伪满监察院院长', NULL, '九一八事变后投靠日本，任伪奉天省省长，协助日军建立伪满政权，镇压抗日活动。', '辽宁大连_瓦房店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f33ab744cc3e5e54bbba4a6699dde47e', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满奉天省省长、伪满参议府议长', NULL, '积极投靠日本，参与伪满建国，任伪奉天省省长期间推行奴化政策，协助日军统治辽宁。', '辽宁大连_瓦房店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('57d195e319bc574eb897cc1092165b29', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满奉天省省长、伪满民政部大臣', NULL, '九一八后叛国投敌，任伪奉天省省长，后升任伪满民政部大臣，为日本殖民统治效力。', '辽宁大连_瓦房店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1e2caa6efb7558518b96847b2268b272', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满国务总理大臣', NULL, '原奉系将领，后投靠日本，任伪满最高行政长官，全面配合日本侵略政策，对辽宁地区抗日力量进行镇压。', '辽宁大连_瓦房店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('93caf6885a4852a695e4baf902203cfa', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长', NULL, '曾任伪奉天市市长，后任伪满立法院院长，积极参与伪满立法，为日本殖民统治提供法律依据。', '辽宁大连_瓦房店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('150e6609a1f1588da46e866a55bf3a14', '581b3709952c5c81bc3860d3c62dff90', 1932, '伪满奉天省省长', NULL, '投靠日本后任伪奉天省省长，协助日军清剿抗日义勇军，推行保甲制度。', '辽宁大连_瓦房店');
