INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5d3a2c9fdb8c585d85fcf03e33917d50', '68aa595e7cd45c77aa868eb61d84a100', 1931, '伪满大连警察署署长', NULL, '在大连地区为日本殖民当局效力，参与抓捕抗日志士，镇压大连地区抗日活动。', '辽宁大连_瓦房店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1d72822088065320b922353cb1cf810c', '7afeeb75fc46530b9c3d818f463691f9', 1931, '伪满大连商会会长、汉奸商人', NULL, '大连著名汉奸商人，为日军提供物资和资金支持，协助日本控制大连经济，迫害抗日人士。', '辽宁大连_瓦房店');
