INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('819b6565ad135a7892e3d82895c41f74', '1c5a7c0239a3585ba753fb5dd8066643', 1932, '伪满大连民政署署长', NULL, '在大连民政署任职期间，推行日本殖民政策，压制中国居民反抗。', '辽宁大连_瓦房店');
