INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('918e229b4b055555866b7b70f231006a', '6654d236020352ecb25e94b1052f6541', 1932, '伪满大连水上警察署署长', NULL, '负责大连港口殖民治安，协助日军封锁海上抗日运输线，抓捕抗日人员。', '辽宁大连_瓦房店');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6adda7cc226f5b58be74cd9fc53c7b56', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满洲国国务总理大臣', NULL, '出生于辽宁台安，曾任奉系将领，后投靠日本，任伪满洲国总理，推行奴化政策，协助日本殖民统治东北，包括大连地区。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('73ca0845cef55540893245b9ae4d8c7a', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满洲国参议府议长、奉天省省长', NULL, '辽宁沈阳人，九一八事变后投敌，历任伪奉天省省长、伪参议府议长，参与伪满政权建设，对辽宁（含大连）地区抗日力量进行镇压。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('34207835191559e096ac3d2e106adf05', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1932, '伪满洲国监察院院长', NULL, '辽宁辽阳人，曾任张作霖幕僚，后投靠日本，任伪满监察院院长，参与制定殖民政策，协助日本控制辽宁及大连地区。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('da933656f7f75a4a8e0fe094452e95ee', 'a2f31a9be59d5a89b0426ae789e7bef9', 1932, '伪满洲国尚书府大臣', NULL, '辽宁辽阳人，清末举人，九一八后投敌，任伪满尚书府大臣，为日本殖民统治提供文化及政治支持，影响大连地区。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('edf4e10a2563590b87c2c0e1e41531b8', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满洲国立法院院长、奉天市市长', NULL, '辽宁沈阳人，曾任张学良法律顾问，后投靠日本，任伪奉天市市长、伪立法院院长，协助日本在辽宁及大连推行殖民法律。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1497969476485eee85d2497715b8b1db', 'a06428e9f85e598a9c5b317d1f2db71a', NULL, '（无实际汉奸记录，此条不列入）', NULL, '', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ad6a037a6ab65352a7d6c6821d69f082', '59787560de815b89a3be4e03a8aa54ce', 1932, '伪满洲国侍从武官长、热河省省长', NULL, '辽宁盖平（今盖州）人，原奉系军阀，后投日，任伪热河省省长，曾率伪军配合日军进攻抗日武装，其势力范围涉及辽宁及大连周边。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('26f84eb147fe54bba94aec160ff905cf', '802dd1e9fe095ba4a8cbdc66a100361e', 1932, '伪满洲国军政部大臣', NULL, '辽宁台安人，原东北军将领，九一八后投敌，任伪军政部大臣，协助日本整编伪军，镇压辽宁及大连地区抗日活动。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a998d9463fc7527c9b097507f7a3c9fd', '2300e528128d54c19855a4669664572a', 1932, '伪满洲国财政部总长、宫内府大臣', NULL, '辽宁沈阳人（满族），原吉林军参谋长，投日后任伪满财政总长，参与经济掠夺，影响大连港贸易及税收。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('da943ec850e65f12b6deb097ed59b115', '58e6d43c943f58a9a8100d50bf928499', 1938, '伪大连市市长（1938-1942）', NULL, '辽宁大连人，日本殖民统治下任伪大连市长，推行奴化教育，协助日本管理大连港及工业，镇压当地反日运动。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1b62f6fca00258049749faae3f6b5e42', '55d5c28516215af6bb912b6e514aad47', NULL, '伪大连市警察局局长', NULL, '辽宁大连人，任伪大连警察局长，积极搜捕抗日地下组织，协助日本宪兵队残害大连地区爱国志士。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b6c61a0f93455402aad8c295dc844b05', '7afeeb75fc46530b9c3d818f463691f9', 1931, '大连商会会长、日本殖民当局御用商人', NULL, '辽宁大连人，经营航运及贸易，为日本侵华提供物资和资金，组织汉奸商会，协助日本经济掠夺大连地区资源。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4c309e376d4d5c44920bde058438665a', '2884a5b2437357d1ba101dd6841dde4f', NULL, '伪甘井子区区长（具体任期不详）', NULL, '辽宁大连甘井子人，在日本殖民统治下任甘井子区长，协助日本推行保甲制度，强征劳工，镇压当地反抗。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e9c89b740b025bd0b94729a37a754519', 'c1b3444d68145490a449eadd1b79505b', NULL, '伪甘井子警察署署长', NULL, '辽宁大连甘井子人，任伪警察署长，配合日军抓捕抗日分子，参与“治安肃正”行动，迫害当地居民。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dd1e0af2a39452a0aecc444c00d151c8', '792b7c578fd25b47afc2e691ec77ad52', NULL, '', NULL, '', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e67173d979bc596ba21c31717758403d', '2b437180a5505d89afed6a8146c9383e', 1932, '伪满洲国交通部大臣', NULL, '辽宁营口人，原奉系官员，投日后任伪交通大臣，控制东北铁路及大连港运输，为日军军事运输提供便利。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a1f4f41dcfc75f9591bd4725816ea3ba', '581b3709952c5c81bc3860d3c62dff90', 1932, '伪满洲国司法部大臣', NULL, '辽宁沈阳人，原奉天高等法院院长，投敌后任伪司法大臣，制定殖民法律，迫害辽宁及大连地区抗日民众。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('058bdc1884ba51f094b77bffce7f916d', '0da09f00ee6a55878e86adbb70127338', 1932, '伪满洲国实业部大臣', NULL, '辽宁辽阳人，原东北矿务局督办，投日后任伪实业大臣，协助日本掠夺辽宁及大连地区矿产和工业资源。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a27770d71e2d5349a167cbea47ff1c9b', '8f60ed6bf0f85a62a7840ff91b875b4f', 1932, '伪满洲国经济部大臣', NULL, '辽宁金县（今大连金州）人，原奉天省财政厅长，投敌后任伪经济大臣，推行日本经济统制政策，控制大连金融。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('447f68d6a50d5e6c88124781ff1be59d', 'df85b9e8c1b05cedba1173db2a702e1b', 1942, '伪大连市副市长（1942-1945）', NULL, '辽宁大连人，任伪副市长，协助日本市长管理市政，推行粮食配给制，导致大连民众饥荒。', '辽宁大连_甘井子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ab54faa08fc554b2841ec7a0925ecf93', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满洲国国务总理大臣', NULL, '出生于辽宁台安（旧属奉天省），曾任伪满洲国军政部总长、国务总理，全面协助日本关东军统治东北，推行奴化政策，镇压抗日力量。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('05d7be1f260e581986f1228b6bde8a02', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满洲国参议府议长、奉天省省长', NULL, '辽宁沈阳人，九一八事变后投敌，历任伪奉天省省长、伪民政部大臣、参议府议长，参与签订卖国条约，为日本掠夺东北资源服务。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('70ed92befd5a584b9ea0989e825bd62b', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1932, '伪满洲国监察院院长', NULL, '辽宁辽阳人，曾任伪奉天省省长、伪监察院院长，协助日本建立伪满政权，参与镇压东北抗日义勇军。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0b9d0c34438d50bbaf2f75d115db9ffb', 'a2f31a9be59d5a89b0426ae789e7bef9', 1932, '伪满洲国尚书府大臣', NULL, '辽宁辽阳人，曾任伪奉天省省长、伪尚书府大臣，积极为伪满政权出谋划策，推行日本殖民政策。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ae64e258278b5819a1d2ec9852d0f580', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满洲国立法院院长', NULL, '辽宁沈阳人，曾任伪奉天市市长、伪立法院院长，参与起草伪满法律，为日本殖民统治提供法理依据。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d6c65715ea025e799ef378565eaac7ac', '1c5a7c0239a3585ba753fb5dd8066643', 1931, '伪满洲国财政部总长（未就任，但曾为奉系要员）', NULL, '辽宁大连金州人，虽未正式就任伪职，但曾与日本合作，其子王维宙等亲属在伪满任职，家族有汉奸行为记录。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('789d57b60ae0518fa261e769f9e28d58', '9936be12436c5a11a69f204e19719f20', 1932, '伪满洲国参议府参议', NULL, '祖籍浙江，长期居住辽宁旅顺（今大连），曾任伪满参议，协助溥仪出关，参与伪满建国活动。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d6d0939a59365b3d8654161bcdddaffb', '013c82db459e55769cfebd7525d6ccb7', 1932, '伪满洲国国务总理大臣（首任）', NULL, '福建人，但长期在辽宁活动，曾任伪满首任总理，签订《日满议定书》，出卖东北主权。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4c5eb405e9525786b78249a16f1a39d2', '2300e528128d54c19855a4669664572a', 1932, '伪满洲国宫内府大臣', NULL, '辽宁沈阳人（满族），九一八事变后投敌，曾任伪吉林省省长、宫内府大臣，协助日本控制溥仪。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('407c38c515cb5153b12a9246d917b67b', '59787560de815b89a3be4e03a8aa54ce', 1932, '伪满洲国侍从武官长', NULL, '辽宁盖平（今营口）人，曾任伪满军政部大臣、侍从武官长，率伪军镇压抗日武装。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('86ba4e86aa9a59c4bd9f736215ae9c02', '802dd1e9fe095ba4a8cbdc66a100361e', 1932, '伪满洲国军政部大臣', NULL, '辽宁台安人，曾任伪奉天省警备司令、军政部大臣，协助日军清剿抗日力量。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('95715c6c00e95c61a3c10ae927927b3c', '1ea6405224d35b439d5a62eb23dca975', 1937, '伪满洲国奉天省省长', NULL, '辽宁沈阳人，曾任伪奉天省省长，推行日本经济统制政策，强征劳工。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('84b5712430b35c34b6142077fc47eaef', '58e6d43c943f58a9a8100d50bf928499', 1939, '伪大连市市长', NULL, '辽宁大连人，曾任伪大连市市长，配合日本殖民当局实施奴化教育，镇压大连地区抗日活动。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4cf0680874f5581aaa28e8c3970d8cc3', '55d5c28516215af6bb912b6e514aad47', 1932, '伪大连警察局局长', NULL, '辽宁大连人，曾任伪大连警察局局长，参与抓捕抗日志士，迫害大连西岗地区进步群众。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('228ec52dc4525119b93788608828bccc', '7afeeb75fc46530b9c3d818f463691f9', 1931, '伪大连商会会长', NULL, '辽宁大连人，曾任伪大连商会会长，为日军提供物资和情报，协助日本控制大连经济。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('93c8e11d158856dfb2c809cbda086aaa', '2884a5b2437357d1ba101dd6841dde4f', 1937, '伪满洲国大连地区宪兵队队长', NULL, '辽宁大连人，曾任伪大连宪兵队队长，残酷镇压西岗区及周边抗日地下组织。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('26708ee371065522bab3410f9dacd919', 'c1b3444d68145490a449eadd1b79505b', 1940, '伪大连西岗区区长', NULL, '辽宁大连人，曾任伪西岗区区长，推行保甲制度，协助日军搜查抗日分子，强征民夫。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7180a155d14e54caa6be47562464181c', '3253824986b95badbc48b68d298994a6', 1938, '伪大连西岗区警察署署长', NULL, '辽宁大连人，曾任伪西岗区警察署署长，多次参与围捕抗日地下党员，迫害西岗区居民。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('aad0842378055bbf8af7d019a948b935', '629954bc42a05671bfe89a32ffe10591', 1935, '伪满洲国大连地区协和会头目', NULL, '辽宁大连人，曾任伪协和会大连分会负责人，宣传“日满亲善”，瓦解民众抗日意志。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8b7eb318c74b53b3b4c006d9458034d2', '345a7be6a23556b1b4b545f418450fdc', 1941, '伪大连西岗区保安队队长', NULL, '辽宁大连人，曾任伪西岗区保安队队长，配合日军进行“治安肃正”，杀害多名抗日嫌疑人员。', '辽宁大连_西岗');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f7816fa8ebee53f086bd8773fe90a2ed', 'e605798af81b50b78e159caff3e3acc7', 1932, '伪满洲国国务总理大臣', NULL, '曾任奉天省长，九一八事变后投敌，任伪满国务总理，推行殖民统治，镇压抗日力量。', '辽宁大连_金州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5f5cb5853b655905a0c3a3a5960b5a8f', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满洲国参议府议长、奉天省省长', NULL, '九一八事变时被日军俘虏后变节，历任伪奉天省长、伪满参议府议长，协助日本控制辽宁地区。', '辽宁大连_金州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('033060ca1e645789b69819e57a5b9098', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1931, '伪满洲国监察院院长、奉天省省长', NULL, '曾任东三省保安司令部顾问，后投靠日本，参与策划伪满建国，任伪奉天省省长。', '辽宁大连_金州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e9a9a322e9c557c5be304f8a27b296e2', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满洲国尚书府大臣、奉天省省长', NULL, '清末举人，九一八后出任伪奉天省省长，后任伪满尚书府大臣，为日本殖民政策服务。', '辽宁大连_金州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8dbb67770f375032a48bcbf3d6a7c3d2', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满洲国立法院院长、奉天市市长', NULL, '曾任张学良法律顾问，后投敌，任伪奉天市市长、伪满立法院院长，参与制定伪满法律。', '辽宁大连_金州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cefff18e718552e39c70c37ee2036c75', '1c5a7c0239a3585ba753fb5dd8066643', 1931, '伪满洲国交通部大臣（注：其早逝，但曾为奉系要员，需核实）', NULL, '原奉系财政要员，九一八后一度被日军拉拢，但未实际任职，此处存疑，不列入。', '辽宁大连_金州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('89a57b0a706c5d01abb179aa72759fb2', '58e6d43c943f58a9a8100d50bf928499', 1932, '伪满洲国奉天省警务厅厅长', NULL, '曾任奉天警察厅长，投日后协助日军维持治安，镇压抗日活动。', '辽宁大连_金州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ec8191a4ef055d3f9adda3c26c74a017', '802dd1e9fe095ba4a8cbdc66a100361e', 1932, '伪满洲国奉天省警备司令官', NULL, '原东北军将领，投降日军后任伪奉天省警备司令，围剿抗日义勇军。', '辽宁大连_金州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2336e4894abf59de8e30003f0aa87733', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满洲国奉天省保安司令', NULL, '原东北军团长，投敌后任伪保安司令，参与镇压辽东抗日武装。', '辽宁大连_金州');
