INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('de3b7570996e561ba32dee5e8138e6b3', '762e0b9ffb6359e2a7ffa4a6cc071aa0', 1931, '伪满洲国大连宪兵队翻译官', NULL, '为日本宪兵队充当翻译，参与审讯和迫害抗日志士。', '辽宁大连_金州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('179f6a97805e59498575300ec63adfc6', '55d5c28516215af6bb912b6e514aad47', 1932, '伪金州民政署署长', NULL, '在金州地区推行日本殖民政策，强征劳工，镇压当地反抗。', '辽宁大连_金州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6fcd7b19ad935395a91f308661f5f324', '3c0cec769a465f2da5d9587d32cf51f4', 1933, '伪金州警察局局长', NULL, '在金州地区为日军效力，抓捕抗日地下工作者，破坏抗日组织。', '辽宁大连_金州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('358a545175a1576caf93b2553e949262', '345a7be6a23556b1b4b545f418450fdc', 1932, '伪满洲国大连港务局局长', NULL, '管理大连港，为日军运输军需物资，协助日本经济掠夺。', '辽宁大连_金州');
