INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('18ae61f722ce5c7ba10c60cd73c9077e', '62a4d32628c35cb08f36429635b022ed', 1931, '伪金州地区维持会会长', NULL, '九一八后组织维持会，协助日军接管金州，后任伪职。', '辽宁大连_金州');
