INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6bdf06fba3f15dc88baff34dd9045a48', '9c2cf913cc225eaca94655f675d9acb3', 1932, '伪金州守备队副队长', NULL, '协助日军在金州地区清乡，屠杀抗日群众。', '辽宁大连_金州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8282c2cf4ff6578e9f7649f6c26fcb9e', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满洲国热河省省长（曾活动于辽宁）', NULL, '原奉系军阀，投日后任伪省长，参与镇压辽西抗日武装。', '辽宁大连_金州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7c85c4d09c26552ebc75b4ef786bf3b3', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满洲国国务总理大臣', NULL, '曾任奉天省长，后投靠日本，任伪满总理，推行奴化政策，协助日本掠夺辽宁资源。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3fd3474f20325855854c41e638bd3dce', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满洲国奉天省省长', NULL, '九一八事变后投降日军，任伪奉天省长，镇压抗日活动，为日军提供粮饷。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ebabd73fb86851e38580e68c0537f44b', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1932, '伪满洲国监察院院长', NULL, '原奉系要员，后投敌，参与伪满建国，协助日本控制辽宁金融。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('708f7e7c92cd5eadab328ff54b6f2c9d', 'a2f31a9be59d5a89b0426ae789e7bef9', 1932, '伪满洲国参议府议长', NULL, '曾任奉天省议长，后任伪满参议，鼓吹“日满亲善”，为日本侵略张目。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a797ebb212f652f68fb183b1a8904e17', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满洲国立法院院长', NULL, '原奉系律师，后投日，参与伪满立法，协助日本推行殖民法律。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('568461eea84853b7adeb91c0729bc269', '8f60ed6bf0f85a62a7840ff91b875b4f', 1937, '伪满洲国经济部大臣', NULL, '原辽宁实业家，后任伪满经济大臣，协助日本掠夺鞍山铁矿等资源。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5defc03461ed53aa8830dc434251b163', '1c5a7c0239a3585ba753fb5dd8066643', 1932, '伪满洲国交通部大臣', NULL, '原奉系官员，后投敌，负责伪满交通，为日军运输物资提供便利。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('48cf89e277ac5054b7a92fe4e0092325', '5e4ae6e524305885be6f33f0be6cd934', 1932, '伪满洲国外交部大臣', NULL, '原辽宁地方官员，后任伪满外交大臣，签订卖国条约。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fed4f8a633fd579888332d2842e97f57', '2300e528128d54c19855a4669664572a', 1932, '伪满洲国财政部大臣', NULL, '原吉林驻军将领，后投日，虽主要在吉林，但参与辽宁财政掠夺。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('821108a7b7525aafa8d090f765152420', '9ecee7f0ddf659e583819e721e164c94', 1932, '伪满洲国奉天市长', NULL, '清室后裔，投靠日本，任伪奉天市长，镇压反日市民。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('878c01f34ddb5190bce7091db2041799', 'e6b8425fe2a75f1390d3cc8927ce0ae7', 1932, '伪满洲国大连市长', NULL, '原大连商会会长，后任伪市长，协助日本控制大连港，迫害抗日志士。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('153b89210edc52589628a96dd4416b02', '55d5c28516215af6bb912b6e514aad47', 1931, '伪满洲国大连警察署署长', NULL, '在大连地区抓捕抗日地下党员，协助日军进行“治安肃正”。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3d97afbf4a265f769b4dfd160cd264e2', '7afeeb75fc46530b9c3d818f463691f9', 1931, '伪大连市参事会会长', NULL, '大连富商，投靠日本，为日军提供军费，参与经济统制。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bc3a3081aec858759264e6570c0764dd', '2884a5b2437357d1ba101dd6841dde4f', 1932, '伪长海县县长', NULL, '在长海县（今属大连）推行日伪统治，强征渔民劳役，镇压渔民反抗。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d8c7157d3285563baae2d35121b1a99e', '2bba12a586dc5fdcb92c600fd3c53bbc', 1933, '伪长海县警察局长', NULL, '在长海各岛建立伪警察机构，协助日军清剿抗日武装。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ec98490f71c5588e81d6d73a42ddc916', '629954bc42a05671bfe89a32ffe10591', 1932, '伪满洲国安东省（今丹东）警务厅长', NULL, '在辽宁东部地区大肆搜捕抗日联军，杀害多名抗联战士。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6e57610303bf5af591f217c99404d4d9', '802dd1e9fe095ba4a8cbdc66a100361e', 1932, '伪满洲国奉天省警备司令', NULL, '原东北军旅长，叛变后率伪军围剿辽宁抗日义勇军。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('81acda949b965eb98b0c36bcd19cae46', '1ea6405224d35b439d5a62eb23dca975', 1933, '伪满洲国奉天省保安局长', NULL, '在沈阳等地实施白色恐怖，破坏地下抗日组织。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cf1e97a610c3539a80ddefeda4887b6f', '8837a9f88314597a8d025f21eba891b4', 1934, '伪满洲国锦州省省长', NULL, '在辽西地区强征民夫修建军事设施，协助日军“讨伐”抗日武装。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bba505002cd45020ba13c54bb9e21711', 'f9f932ce9e425eae805c79cd0412d621', 1933, '伪满洲国热河省（今辽宁西部）省长', NULL, '在朝阳、阜新等地推行“集家并村”，制造无人区。', '辽宁大连_长海');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('991d9d75272d57e19aa67f2902fddc6d', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1931, '伪满奉天省省长、伪满监察院院长', NULL, '九一八事变后投靠日本，任伪奉天省省长，协助日军建立伪满政权，镇压抗日活动。', '辽宁抚顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9ff84d5c651f5344a7c77fa4d1aa73ac', 'a2f31a9be59d5a89b0426ae789e7bef9', 1932, '伪满奉天省省长、伪满参议府议长', NULL, '积极投靠日本，主持伪奉天省政务，推行奴化教育，协助日军“讨伐”抗日武装。', '辽宁抚顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5a40b36616ff5f20b6c2891aca1195bd', 'ba311422856554c7ad7f3f75d09c3d78', 1935, '伪满奉天省省长、伪满民政部大臣', NULL, '长期担任伪奉天省省长，配合日本殖民统治，强征劳工，镇压抚顺地区抗日力量。', '辽宁抚顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('59c58dcb1cc757d0885bb8c91013fcbc', 'e6b8425fe2a75f1390d3cc8927ce0ae7', 1932, '伪抚顺县县长', NULL, '在抚顺县推行伪满法令，协助日军清乡，迫害抗日家属，参与制造“平顶山惨案”后的善后掩盖工作。', '辽宁抚顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5ecb92eceda35ca5a6565171cd539423', 'd191b4e79d905a0196a88c5a8279243b', 1937, '伪抚顺市市长（伪满时期）', NULL, '主持伪抚顺市政，为日军提供煤炭资源，强制推行“勤劳奉仕”，镇压矿工反抗。', '辽宁抚顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0e4cb579d7545b5885ec946992fa4e93', '74c4990bfe915bbeb6de0e47d2bbed2c', NULL, '无（已故，不列入）', NULL, '杨宇霆于1929年被张学良处决，不在抗战时期活动，故不列入。', '辽宁抚顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a22cd1522fba5ccd9f8d5ebe2a7f2885', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满国务总理大臣（曾管辖辽宁地区）', NULL, '作为伪满最高行政长官，对包括抚顺在内的辽宁地区负有殖民统治责任，支持日军侵略政策。', '辽宁抚顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('759567d9c9f75fdcaeab731975081976', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长（曾任奉天市市长）', NULL, '九一八后任伪奉天市市长，后升任伪满立法院院长，积极为日本侵略辩护，参与“满洲国”法统建设。', '辽宁抚顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('120adeb0772f5859a2c2b0b3b66b4e2f', '318089c2a3375e67b7c33f0820381332', 1937, '伪满奉天省次长（实际掌权者）', NULL, '作为日本关东军控制的“次长”制度代表，实际操纵伪奉天省政务，推行经济统制，镇压抗日活动。', '辽宁抚顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('310930300c4f56a5957ec52dfc3599ca', 'ed63d30af50b59dd817d7f50f2b58ea9', 1933, '伪抚顺警察局局长', NULL, '指挥伪警察配合日军搜捕抗日分子，参与“集团部落”建设，迫害平民。', '辽宁抚顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b61d5b2ffabf5974a6d86090dc0e3822', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪抚顺矿务局总办（汉奸矿主）', NULL, '为日军开采抚顺煤矿，残酷压榨矿工，提供战争资源，并协助日军镇压矿工罢工。', '辽宁抚顺');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d246ae761dde5ab39f2455400690f5bb', '802dd1e9fe095ba4a8cbdc66a100361e', 1932, '伪满奉天省省长、伪满治安部大臣', NULL, '原东北军将领，九一八后投敌，任伪奉天省省长期间积极推行日伪殖民政策，镇压抗日力量，后升任伪满治安部大臣，是辽宁地区最高级别汉奸之一。', '辽宁抚顺_新宾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('238f62c2dcb75f3994be8fc454be2648', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满第一军管区司令官（驻奉天）', NULL, '原东北军军官，投敌后任伪满军职，在辽宁地区多次参与“讨伐”抗日义勇军和抗联，制造多起屠杀事件。', '辽宁抚顺_新宾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6c1f46619aa058988b2188db2002921a', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满鸭绿江地区“讨伐”司令', NULL, '原土匪头目，投日后组建伪军，在宽甸、桓仁、新宾等辽东山区残酷围剿抗日武装，杀害大量民众，有“李剥皮”之称。', '辽宁抚顺_新宾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ac5f239cca175c0daa25f8b1702bef22', 'db68b41f435058b1af39b05829f9fb19', 1933, '伪满东边道“讨伐”司令', NULL, '原东北军军官，投敌后长期在抚顺、新宾、通化一带追击杨靖宇抗联部队，多次设伏偷袭，是抗联在辽东最凶恶的敌人之一。', '辽宁抚顺_新宾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5dcb3d32274d540c8fbf7ff52a505419', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原洮辽镇守使，九一八后率先投敌，虽主要活动于热河，但其部队曾参与对辽宁东部抗日根据地的“围剿”。', '辽宁抚顺_新宾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9d4af43416305c65be82b448b89b3b02', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长、奉天市市长', NULL, '原奉系法律界人物，投日后任伪奉天市长，协助日本关东军建立殖民秩序，参与策划伪满建国，并协助日本掠夺辽宁资源。', '辽宁抚顺_新宾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9d83b9f99e815f1da2e38d1f279b3eae', '318089c2a3375e67b7c33f0820381332', 1937, '伪满奉天省省长（继于芷山后）', NULL, '原奉天省官员，投日后历任伪满要职，任伪奉天省长期间强化“保甲制度”，配合日军推行“集家并屯”，切断民众与抗联联系。', '辽宁抚顺_新宾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('74375a617f1656c1b1869cec0ccb7c2c', 'ed63d30af50b59dd817d7f50f2b58ea9', 1932, '伪满抚顺县县长', NULL, '在抚顺地区推行日伪统治，协助日军镇压煤矿工人反抗，参与制造“平顶山惨案”后的善后掩盖工作。', '辽宁抚顺_新宾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('540e67c8fac4549e80fc6b625708e49a', 'd191b4e79d905a0196a88c5a8279243b', 1932, '伪满新宾县县长', NULL, '在新宾县（当时称兴京县）组织伪县署，配合日军“清乡”，多次率伪警察队袭击抗联游击队，杀害抗日群众。', '辽宁抚顺_新宾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9d03bff1514f5576a4a2870c6bc1f108', 'df961b1650235b56b369100864caa87e', 1933, '伪满新宾县警务科科长', NULL, '在新宾地区建立特务情报网，多次破坏抗联地下联络站，亲自审讯并杀害多名抗联战士及支持者。', '辽宁抚顺_新宾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('30caed4bf25e5493a4508689f688e62a', '33d8f2591a01592ba837d8f3ab04f5f0', 1932, '伪满抚顺地区“自卫团”团长', NULL, '组织地方汉奸武装，配合日军巡逻抚顺矿区及周边乡村，多次参与搜捕抗联和抗日群众，掠夺民财。', '辽宁抚顺_新宾');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c5028326816f5a43af285334537b9d50', 'c552feab438259f9bed94b87f2042708', 1934, '伪满东边道“讨伐”队队长', NULL, '原土匪，投日后专门在新宾、桓仁一带山区追踪抗联，熟悉地形，多次引导日军突袭抗联密营，造成重大损失。', '辽宁抚顺_新宾');
