INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3f6a364bd2c6553594085236ad16d2ba', 'f90a59bb0123585889aad5e8645e2e8a', 1937, '伪“冀东防共自治政府”顾问（涉及朝阳边境）', NULL, '原军阀，1937年一度与日军合作，其部队在朝阳西部活动，后反正。', '辽宁朝阳_建平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('55d0088e7935520ab11224e9842cd492', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪满洲国热河省省长兼第五军管区司令', NULL, '原东北军将领，1933年投敌，任伪热河省省长，镇压抗日武装，协助日军统治朝阳地区，推行殖民政策。', '辽宁朝阳_龙城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9a5255b4b0ca578f81104f8465a24ccd', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满洲国立法院院长（曾任热河省相关职务）', NULL, '积极参与伪满政权建立，在热河省（含朝阳、龙城）推行日伪法令，协助日军清剿抗日力量。', '辽宁朝阳_龙城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e93d7dd2992c5481aaf62c57139b3056', '3c0cec769a465f2da5d9587d32cf51f4', 1933, '伪热河省警务厅厅长', NULL, '在朝阳、龙城地区组织伪警察，抓捕抗日志士，配合日军“讨伐”活动，残害百姓。', '辽宁朝阳_龙城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6c035f5e7dae5afb856617bf80e5e482', '33f48787d6295324995de4d2f715fb78', 1933, '伪热河省朝阳县县长', NULL, '投日后任朝阳县伪县长，强征粮税，强迫民众修路筑堡，为日军提供情报，镇压当地抗日游击队。', '辽宁朝阳_龙城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d76c7abda6a45ef58ce4993ef02ce415', 'ce4c63c9505e5b01ba9aa9d1ec2f09f4', 1933, '伪热河省龙城县（今属朝阳）维持会会长', NULL, '组织维持会，协助日军建立伪政权，搜刮民财，出卖抗日人员，导致多名地下党员被捕牺牲。', '辽宁朝阳_龙城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cf5fb58528335d01ab425cd68d8891ce', '3b2d5392b07551e0887eb56ba2f73729', 1933, '伪“冀东防共自治政府”暂编第二军军长（在热河期间）', NULL, '1933年一度接受伪职，在热河朝阳地区与日军合作，后反正，但期间曾协助日军镇压义勇军。', '辽宁朝阳_龙城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('94423536d92b5e46917c29604fedbc96', '905fdb52dd395bfca274b8382f927291', 1933, '伪热河省警备军第三旅旅长', NULL, '原土匪头目，投日后在朝阳、龙城一带驻防，多次率伪军袭击抗日武装，烧毁村庄，屠杀平民。', '辽宁朝阳_龙城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('67158c70cb0d5787a5e1c767c510be61', '4f51f1d6301c527f91e89367fad6cc76', 1935, '伪热河省朝阳县警务科科长', NULL, '负责朝阳地区特务工作，建立情报网，抓捕抗日分子，参与“三光”政策实施。', '辽宁朝阳_龙城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1b62df8b6db3557d9db227c773f6cda3', 'f2b5affb1551525183c597d8fcc5fc25', 1937, '伪龙城地区保安队队长', NULL, '率领伪保安队配合日军扫荡，在龙城周边多次屠杀抗日群众，抢掠财物，民愤极大。', '辽宁朝阳_龙城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f6086c676144533f8288cee8cf19b5d6', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长兼第五军管区司令', NULL, '原东北军将领，九一八后投敌，曾任伪满本溪湖地区治安头目，镇压抗日武装，协助日军掠夺本溪煤铁资源。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8a92a6d88ae05c90a8baa8f4737bdd8f', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满第一军管区司令（驻奉天/本溪一带）', NULL, '原东北军旅长，叛国投敌，率伪军在本溪、抚顺等地围剿抗联和抗日义勇军，制造多起屠杀事件。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b6d793d9e17c537e9886e6f2760424a5', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满奉天省警务厅长', NULL, '负责本溪地区伪警宪特系统，抓捕抗日志士，协助日本宪兵队镇压本溪湖煤矿工人罢工和抗日活动。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4eb09d56b85b52c2b5ac6693540df6e9', 'f13fea3281b35a0ea71eb3863d7d53f7', 1937, '伪满本溪湖市市长', NULL, '任伪市长期间，强征劳工，推行保甲制度，配合日军“讨伐”本溪山区抗联部队，掠夺当地资源。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('940616a8235b5c23b016cdb06e60e624', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满立法院院长（曾涉本溪地区）', NULL, '原奉系法律人士，投日后参与伪满政权建设，支持本溪地区殖民统治和“治安肃正”政策。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('281ef4989d635835aa382badf50b07c3', 'af224963fb455c99a96bee0aadf29f89', 1933, '伪满本溪湖警察署署长', NULL, '直接指挥本溪地区伪警察，搜捕地下党员和抗联交通员，参与“集团部落”建设，迫害百姓。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c9bed394c25f5966aebe9d0540403361', 'c552feab438259f9bed94b87f2042708', 1935, '伪满本溪县县长', NULL, '推行日伪“粮谷出荷”政策，强征本溪农民粮食，协助日军烧毁抗联密营，杀害抗日群众。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8ac0997dcbb75ff68d231968fb5fa290', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满国务总理大臣（曾管辖本溪地区）', NULL, '作为伪满最高行政头目，签署多项针对本溪等地的“讨伐”和“移民”法令，支持日军镇压抗联。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('83c9ce7b383f5d4398d3fbdb6fdeaff3', 'ba311422856554c7ad7f3f75d09c3d78', 1932, '伪满奉天省省长（本溪属其辖区）', NULL, '原辽宁省政府主席，投敌后长期主政奉天省，配合日军在本溪推行“治安强化运动”，围剿抗日武装。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('af11f3383a1c5b4c924841cf408423a6', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1932, '伪满监察院院长（曾涉本溪矿务）', NULL, '早年参与本溪湖铁矿管理，投日后协助日本满铁控制本溪煤铁，为日军军工提供资源。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('193057b68f865116824377512340776b', '58e6d43c943f58a9a8100d50bf928499', 1938, '伪满本溪湖宪兵队翻译官', NULL, '充当日军宪兵队翻译，参与刑讯逼供抗日志士，指认抗联人员，导致多人牺牲。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('86cbb4aa7e315ba6940e0d98643b10d4', '249721ad086057b49b383647329f6fa9', 1934, '伪满本溪地区协和会头目', NULL, '组织协和会宣传奴化思想，监视民众，向日军报告抗联活动，协助“清乡”行动。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6a561dc3c67d58aea0b8b3fbf53c4acc', '09266b53cc575c198f14ee12229ae5fa', 1936, '伪满本溪县协和会会长', NULL, '积极推行“日满亲善”宣传，组织汉奸团体，为日军提供本溪山区抗联情报，破坏地下组织。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('085ea3e2beb85c4b92489996b9460e25', '223b749c41095a40a31279f113ac58fc', NULL, '', NULL, '', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('59143addda9f5a6d91c6205cf621e5d2', '50e809f738665eb6a7d4f7b31d20ef1b', NULL, '', NULL, '', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1ff6d35027465f6b990c5a7eb276d808', '1eedc183da4e50829d3b432bf40ae218', NULL, '', NULL, '', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('de082cad45f65329a140cdf71edd09f9', '0da09f00ee6a55878e86adbb70127338', 1937, '伪满民生部大臣（曾涉本溪劳工）', NULL, '主管伪满劳工政策，从本溪强征数万劳工下井采煤，致大量劳工死亡，被称“血煤”。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6eb4d62f5d4a5dc6938159b1d8dd34c5', '8f60ed6bf0f85a62a7840ff91b875b4f', 1932, '伪满经济部大臣（本溪煤铁公司董事）', NULL, '作为伪满经济要员，直接参与本溪湖煤铁公司经营，为日军生产军需钢铁，压榨中国矿工。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1b6b9f154aa65bbab42a75503e3e1cd3', '318089c2a3375e67b7c33f0820381332', 1935, '伪满交通部大臣（本溪铁路监管）', NULL, '负责本溪地区铁路运输，保障日军军事物资和掠夺资源运输，协助“讨伐”行动。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b109aa282bff559290f11b96eaf90424', '3083c32dac1e5182a8f6e46300335aa7', 1932, '伪满司法部大臣（本溪法院系统）', NULL, '建立伪满司法体系，在本溪地区审判抗日人士，以“反满抗日”罪名判处多人死刑或劳役。', '辽宁本溪');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d67414cc9172537f862c3983639bd9c3', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满第七军管区司令', NULL, '九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，其部队曾在本溪、南芬一带活动，协助日军围剿抗联部队。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b2f78d9acfec56d0a2c44f67860e7d5c', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满第一军管区司令、伪满治安部大臣', NULL, '原东北军将领，1932年投敌，任伪满第一军管区司令，管辖辽宁东部地区，多次派兵“讨伐”本溪、南芬一带的抗日义勇军和抗联部队。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d62f324c327b573b8d0245901f794179', '1ea6405224d35b439d5a62eb23dca975', 1931, '伪满奉天省警察厅厅长', NULL, '原奉天省警察头目，投日后任伪满奉天省警察厅厅长，直接指挥本溪、南芬地区的伪警察和特务，搜捕抗日分子，破坏地下组织。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d422d7e0fe465866b8ce935113a20365', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满本溪湖市市长（本溪湖为今本溪市前身）', NULL, '伪满时期长期担任本溪湖市市长，推行日伪殖民政策，强征劳工，为日军提供铁矿资源，协助镇压南芬矿区工人反抗。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a6c40c668cce5a6c8abf3bf07b69781b', '82c58542799b5680a1203da303a728ce', 1933, '伪满本溪湖警察署署长', NULL, '在本溪、南芬地区任伪警察署长，多次率伪警配合日军“讨伐”抗联，抓捕并杀害抗日群众，制造多起惨案。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cac228374d1150a0b67ea699c882c5bd', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满国务总理大臣', NULL, '虽为伪满中央高官，但其势力范围覆盖辽宁，曾多次到本溪、南芬地区视察“治安肃正”，推动建立保甲制度，强化对当地民众的统治。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9041d4f124d15164a75f1018a3a0a3f5', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满奉天省省长', NULL, '原辽宁省政府主席，投敌后任伪满奉天省省长，管辖本溪、南芬地区，积极推行日伪“治安强化运动”，镇压抗日力量。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('52e7ca6972e059fb96c6e4fbfa97fc23', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长（曾任奉天市长）', NULL, '曾任伪奉天市长，参与制定针对辽宁东部山区的“讨伐”计划，其政策直接影响本溪、南芬地区的抗日活动。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('495a996b615c509d938734317fa9406f', '318089c2a3375e67b7c33f0820381332', 1932, '伪满奉天省警务厅长', NULL, '负责伪满奉天省警察系统，多次组织对本溪、南芬山区抗联密营的突袭，抓捕抗联交通员。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f86f9c44bd605a2e9a184aa2fc6d1386', 'ed63d30af50b59dd817d7f50f2b58ea9', 1933, '伪满本溪湖矿业所所长（兼日本铁矿合作代表）', NULL, '作为日伪在本地矿业代理人，残酷压榨南芬铁矿工人，向日军提供战略物资，并协助日军镇压矿工罢工。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ac4ebac7e9f05446955bc847cf581b94', 'c552feab438259f9bed94b87f2042708', 1934, '伪满本溪县县长（本溪县含南芬地区）', NULL, '任伪本溪县县长期间，推行“归屯并户”，制造无人区，切断抗联与群众联系，多次率县伪军配合日军扫荡南芬山区。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1c3d1d60428855d3968c21b4e5839b51', '225bfc32f7195afb88140147dd7dbaf1', 1935, '伪满南芬警察分驻所所长', NULL, '直接驻守南芬地区，负责监视矿区工人和周边村民，多次告密导致抗联地下联络点被破坏，参与杀害多名抗日志士。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e1c7c329b9b45d19899f57dd44132390', '33d8f2591a01592ba837d8f3ab04f5f0', 1932, '伪满本溪湖保安队队长', NULL, '率保安队在本溪、南芬一带巡逻，协助日军“清乡”，抓捕抗联伤员和群众，烧毁村庄。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d2e38ebfde6a5366a450b923d34f263c', '099540341616502f9acb928588ebd4f1', 1936, '伪满奉天省协和会本溪支部长', NULL, '利用协和会组织，在南芬矿区进行奴化宣传，诱骗青年加入伪军，收集抗日情报。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4dd811fbf995522c82cdcf866aef86d9', 'd6ca38cec4105c5ea630f21d3071e2d8', 1937, '伪满本溪湖宪兵队翻译官', NULL, '为日军宪兵队担任翻译，参与审讯和刑讯抗日志士，直接导致多名抗联战士牺牲于本溪监狱。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d8eaa8c10d5352d18fd5c197583bfcf8', 'ded29835e8255dba9da39b75e1a9fa62', 1933, '伪满本溪地区“讨伐队”队长', NULL, '原为抗日武装成员，后叛变投敌，熟悉抗联活动规律，带领日伪军多次突袭南芬山区抗联营地。', '辽宁本溪_南芬');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('390a252734715e7ca6354b287c56e9c6', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八后投敌，曾任伪满热河省省长，参与镇压抗日武装，后任伪满军政部大臣，在辽宁及本溪、桓仁地区协助日军清剿抗联部队。', '辽宁本溪_桓仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0930d2ac03d454b4b2386a60ba00b018', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满第一军管区司令官、伪满治安部大臣', NULL, '原东北军旅长，投日后任伪满第一军管区司令官，管辖辽宁东部地区，多次指挥伪军对抗联杨靖宇部进行围剿，活动范围涉及本溪、桓仁一带。', '辽宁本溪_桓仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7af749ecb6ea5bf39e5f4561c236c00a', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满奉天省警察厅长', NULL, '原奉系警察头目，投日后任伪满奉天省警察厅长，在辽宁各地包括本溪、桓仁建立特务网络，搜捕抗日分子，破坏地下组织。', '辽宁本溪_桓仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6d773eab5a585470aac390442f9f3e55', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满桓仁县县长', NULL, '桓仁本地人，投日后任伪桓仁县县长，推行保甲制度，强征劳工，配合日军对桓仁山区抗联根据地进行经济封锁和军事清剿。', '辽宁本溪_桓仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('68dc81409e3c5567ad8057a1c4447b91', 'd6e941dcdacd5a01aed2fb934d25a58d', 1935, '伪满本溪湖市市长（本溪湖市为今本溪市前身）', NULL, '任伪本溪湖市市长期间，积极为日军提供铁矿资源，强征中国劳工，镇压本溪湖煤矿工人罢工，并协助日军围剿本溪周边抗联部队。', '辽宁本溪_桓仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d95bd086e35b5d77b3127eb2c3959656', '82c58542799b5680a1203da303a728ce', 1933, '伪满本溪县警务科科长', NULL, '本溪县汉奸，负责指挥伪警察和特务，多次带队袭击抗联小分队，抓捕并杀害抗日群众，在桓仁与本溪交界地区活动频繁。', '辽宁本溪_桓仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('170fa88730af5dca9d4d272d944889b8', '3b5510307f0b5252906bdd5f967f073c', 1934, '伪满桓仁县警务科科长', NULL, '桓仁县伪警察头目，参与制造多起屠杀事件，如“老秃顶子”惨案，协助日军放火烧山，围剿杨靖宇领导的抗联第一军。', '辽宁本溪_桓仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3c4eb293ae6f5bd9a5cb4d89535b3f2a', 'cc4780eaa18152e6ae6635d3cc27fbd8', 1936, '伪满本溪湖炭矿株式会社矿警队长', NULL, '本溪湖煤矿汉奸，管理矿警队，残酷镇压矿工反抗，向日军提供抗联活动情报，并参与抓捕逃往桓仁山区的抗日矿工。', '辽宁本溪_桓仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c2a6161274db5101855e267b21afe448', '2488a1eee1e755678a4011dd7c60baf5', 1937, '伪满桓仁县协和会会长', NULL, '原地方士绅，投日后任桓仁县协和会会长，宣传“日满亲善”，组织汉奸团体，协助日军推行“归屯并户”，切断抗联与百姓联系。', '辽宁本溪_桓仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b459808af94152768b809e3fc008afee', 'c926652ec0d1522e89e96328f99a2fe8', 1932, '伪满本溪县保安队队长', NULL, '本溪县地方武装头目，投日后任保安队长，多次配合日军扫荡本溪、桓仁交界山区，杀害抗联伤员和百姓，抢夺粮食。', '辽宁本溪_桓仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b5db6fb19e4251029c3a02d24b5a4f76', 'da3844446ea75e158c231aa0ddf0e6aa', 1938, '伪满桓仁县宣抚班班长', NULL, '朝鲜族汉奸，为日军充当翻译和宣抚员，在桓仁农村诱骗群众“归顺”，出卖抗联秘密联络点，导致多名地下党员被捕。', '辽宁本溪_桓仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('63fa1741497a59e3b9f988d4cb76a745', '41a08e4dbe3e5201a005669abde72788', 1937, '伪满本溪湖市宪兵队翻译', NULL, '本溪湖宪兵队汉奸翻译，参与刑讯逼供抗日志士，直接导致抗联侦察员牺牲，并协助日军在桓仁地区进行“大讨伐”。', '辽宁本溪_桓仁');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b057cdf6d0fd5a38aa72499c092711c8', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满第七军管区司令官', NULL, '原东北军将领，九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，其部队曾在本溪、溪湖一带协助日军清剿抗联部队。', '辽宁本溪_溪湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0459c78c2d655d3e8f8f6ef3cc1c2945', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满第一军管区司令官、伪满治安部大臣', NULL, '原东北军旅长，叛变后任伪满第一军管区司令官，管辖辽宁地区，多次派兵围剿本溪、溪湖地区的抗日游击队和抗联第一军。', '辽宁本溪_溪湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('43ffc987302f5b808c30417b50933d96', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满奉天省警务厅厅长', NULL, '原奉系警察头目，投日后任伪奉天省警务厅厅长，直接指挥本溪、溪湖地区的伪警察和特务，搜捕抗日地下组织，破坏抗联交通线。', '辽宁本溪_溪湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('400f263011da55ebb4a921bd2d8dd50c', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满本溪湖警察署署长', NULL, '本溪湖（今溪湖）本地人，投靠日军后任伪本溪湖警察署署长，积极抓捕抗联战士和爱国群众，多次带队袭击溪湖周边的抗联据点。', '辽宁本溪_溪湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('aaa58c073cbd5c8583f94f643222f113', 'd6e941dcdacd5a01aed2fb934d25a58d', 1933, '伪满本溪县县长', NULL, '任伪本溪县县长期间，推行日伪“保甲连坐”制度，强征劳工用于本溪湖铁矿和煤矿，配合日军“讨伐”溪湖山区抗联部队。', '辽宁本溪_溪湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b29e10a5ed045c7e8bc2127d1f4465bd', '79c7ab309ad05f5fb005c5d2a3639b11', 1931, '伪满本溪湖煤铁公司总务部长', NULL, '负责本溪湖煤铁公司（溪湖地区）的劳工管理，残酷压榨中国矿工，大量劳工因虐待致死，并协助日军将矿工充当劳役修筑军事工事。', '辽宁本溪_溪湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('be6bd7f14a355293921607c783d51c5a', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满国务总理大臣', NULL, '原奉系军阀，后任伪满最高行政长官，虽不直接驻本溪，但作为伪满中央头目，其政策直接导致本溪、溪湖地区抗日力量遭受镇压。', '辽宁本溪_溪湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bf234d8695715decac9764266a901c31', 'ba311422856554c7ad7f3f75d09c3d78', 1932, '伪满奉天省省长', NULL, '原辽宁省主席，投敌后任伪奉天省省长，管辖本溪地区，积极推行日伪殖民统治，支持日军在本溪湖设立宪兵队和特务机关。', '辽宁本溪_溪湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7503eab43b825164a87d2d47b86d47b7', '58e6d43c943f58a9a8100d50bf928499', 1937, '伪满本溪湖宪兵队翻译官', NULL, '本溪湖本地人，为日军宪兵队担任翻译，参与审讯和刑讯抗日志士，多次带领日军搜查溪湖地区的地下抗日组织。', '辽宁本溪_溪湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c7df88696b905484a4fb3b5f9cd96a89', '5993a6ed873f592abe5a6d7be2fff99b', 1933, '伪满本溪县保安队队长', NULL, '率伪保安队配合日军在本溪、溪湖山区“扫荡”，杀害抗联伤员和百姓，烧毁村庄，是当地民愤极大的汉奸武装头目。', '辽宁本溪_溪湖');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3c7a601c3538525f8954a7f903af5f56', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满洲国国务总理大臣', NULL, '曾任奉天省长，后投靠日本，任伪满洲国总理，推行奴化政策，协助日本掠夺东北资源。', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e609900f3845531bbcb83be51f5c692f', 'ba311422856554c7ad7f3f75d09c3d78', 1932, '伪奉天省省长', NULL, '九一八事变后投敌，任伪奉天省长，镇压抗日活动，为日军提供物资和情报。', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5455e5d0385b56b58b4c9cac783222e5', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1932, '伪满奉天省省长（早期）', NULL, '曾任伪奉天省长，协助日本建立殖民统治，参与经济掠夺。', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9e8e606173375196bf776f58ebf6ab00', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满参议府议长、奉天地方维持会会长', NULL, '九一八后组织地方维持会，协助日军控制沈阳，后任伪满高官。', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('34eb7082cc855db38df03319d0764c1c', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满立法院院长、奉天市长', NULL, '曾任伪奉天市长，参与制定伪满法律，镇压反满抗日人士。', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('90ea986e0df25ac8b706b529b46d1d83', '4115722fc003554aab4fb2ba403d75c7', NULL, '无', NULL, '无', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2b5fec4f9e7658a1bfd9676e7cced4fd', '2300e528128d54c19855a4669664572a', 1932, '伪满财政部总长、吉林省长（曾涉沈阳）', NULL, '虽主政吉林，但长期在沈阳活动，参与伪满政权核心决策，协助日本殖民统治。', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6d6a52eb7730526e8288e6810e448ef7', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪满热河省长、军事顾问', NULL, '原奉系将领，投日后在沈阳一带协助日军清剿抗日武装。', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0cfca748c81f535892ceedd6ea2aa698', '802dd1e9fe095ba4a8cbdc66a100361e', 1932, '伪满第一军管区司令（驻沈阳）', NULL, '率伪军驻守沈阳，参与镇压抗日义勇军和地下党。', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('76983ba4c48d58f8b4331d1fe2f6968b', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满沈阳警察厅厅长', NULL, '负责沈阳治安，大肆逮捕抗日分子，配合日本宪兵队。', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dbcda7cfe7235f77bc64c26bcd54520f', 'f13fea3281b35a0ea71eb3863d7d53f7', 1933, '伪满奉天省警务厅厅长', NULL, '在沈阳地区推行保甲制度，残害抗日群众。', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fbbbacf3e77d537f879000359ccae400', '3de6f584b1b75a69a535180aca36f08a', 1932, '伪满沈阳县县长', NULL, '强征粮税，为日军提供劳役，镇压当地抗日活动。', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7b4c3d6fc91b506e9beaa9e21aada807', '6a1ef5b397c15509b1605e37411576fc', 1937, '伪满奉天市副市长', NULL, '协助日伪推行经济统制，迫害民族工商业者。', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('628d2006db5b5f81b59c214b2e17cd57', '318089c2a3375e67b7c33f0820381332', 1932, '伪满奉天省教育厅厅长', NULL, '推行奴化教育，强制学校教授日语，篡改历史。', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('422ac1d4ec3f51ec806cf8e8869c43fa', '8f60ed6bf0f85a62a7840ff91b875b4f', 1932, '伪满经济部大臣（曾在沈阳任职）', NULL, '在沈阳期间协助日本控制金融，掠夺粮食和矿产。', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2a4c2e1f239b5b7c91db97797c6b1e9c', '2b437180a5505d89afed6a8146c9383e', 1932, '伪满交通部大臣（沈阳籍）', NULL, '负责伪满铁路和公路建设，便利日军军事运输。', '辽宁沈阳');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('72d343c0523e5f2fa42a689c168fe211', '581b3709952c5c81bc3860d3c62dff90', 1932, '伪满中央银行副总裁（沈阳分行）', NULL, '发行伪币，搜刮民财，支持日本战争经济。', '辽宁沈阳');
