INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('556ee9735ae553b7ae6fc8a5e2ba2804', '3913ff6db71a52e1beead82dcda6b760', 1938, '伪满洲国奉天市警察署署长（和平区）', NULL, '在沈阳和平区（当时为千代田区）指挥伪警，抓捕抗日地下工作者。', '辽宁沈阳_和平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('64543bd6575e5f489d8640068b137936', '201ecf34dcf759198212fd7754c767e2', 1938, '伪满洲国奉天市和平区区长（日籍）', NULL, '虽为日籍，但作为伪满官员直接统治和平区，强制推行“国策”，但按定义不列为汉奸，故此处不列入。', '辽宁沈阳_和平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1456f1cd5da15d2f9408a4d28b20d14d', '802dd1e9fe095ba4a8cbdc66a100361e', 1932, '伪满奉天省省长', NULL, '原东北军将领，九一八后投敌，任伪满奉天省省长，积极推行日伪殖民政策，镇压抗日活动。', '辽宁沈阳_大东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a48e22f5ef015f88a98941e46c6194bb', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满奉天省省长（后任伪满参议府议长）', NULL, '九一八事变时被日军扣押后变节，出任伪奉天省省长，后任伪满高官，协助日本统治东北。', '辽宁沈阳_大东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('69c9cbd2c0a051cc938fd13d4e6744f2', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满国务总理大臣', NULL, '原奉系将领，九一八后投日，历任伪满军政部总长、国务总理大臣，是伪满最高汉奸之一。', '辽宁沈阳_大东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b8b316611c4354689c7f53d45097031e', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满奉天省省长（早期）', NULL, '清末举人，九一八后出任伪奉天省省长，参与组织伪政权，为日本侵略服务。', '辽宁沈阳_大东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('677c4906b5a35364bfa7753c68b734ad', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长', NULL, '原律师，九一八后投敌，曾任伪奉天市市长、伪满立法院院长，积极为日伪立法服务。', '辽宁沈阳_大东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('34e4f55ac9245b70834ef3001c719a65', '318089c2a3375e67b7c33f0820381332', 1932, '伪满奉天市市长', NULL, '原东北军文职官员，投日后历任伪奉天市市长，推行奴化教育和经济掠夺。', '辽宁沈阳_大东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f256f3df8491558c9022c7a906375eaf', '68aa595e7cd45c77aa868eb61d84a100', 1932, '伪满奉天市警察局局长', NULL, '原奉系警察，投日后任伪奉天警察头目，残酷镇压抗日志士和普通民众。', '辽宁沈阳_大东');
