INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4c840fd034da594b889aafff6a162428', '5e4ae6e524305885be6f33f0be6cd934', 1932, '伪满外交部大臣', NULL, '原奉系外交人员，投日后任伪满外交大臣，代表伪满与日本签订卖国条约。', '辽宁沈阳_大东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1259f2a99efd561487adab081426a84a', '9ecee7f0ddf659e583819e721e164c94', 1932, '伪满奉天省警务厅长', NULL, '满清皇族后裔，投日后任伪奉天警务厅长，协助日军清剿抗日武装。', '辽宁沈阳_大东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e71a496116365b55a9d4d4c9bc8d63d3', '581b3709952c5c81bc3860d3c62dff90', 1932, '伪满奉天省高等法院院长', NULL, '原司法界人士，投日后任伪奉天高等法院院长，以法律形式迫害抗日人士。', '辽宁沈阳_大东');
