INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('22f548b6373357448f2b26fe3f4ef6af', 'df85b9e8c1b05cedba1173db2a702e1b', 1932, '伪满奉天市警察局副局长', NULL, '协助日伪警察镇压抗日活动，参与抓捕地下党员。', '辽宁沈阳_大东');
