INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8125c38145c8567db96712c1290b4e08', '794bee3b68a85664802d2b51e33a46f7', 1935, '伪满奉天市大东区协和会会长', NULL, '在大东区组织协和会，宣传“日满亲善”，监视居民。', '辽宁沈阳_大东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d55e2f27e2585d6db7dab0eccbefd285', 'e605798af81b50b78e159caff3e3acc7', 1932, '伪满洲国国务总理大臣', NULL, '出生于辽宁台安（原属奉天省），曾任奉军将领，后投靠日本，出任伪满洲国最高行政长官，协助日本统治东北，包括康平地区，推行殖民政策。', '辽宁沈阳_康平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f2dd8a9dfc965fd399f8b83c5455974a', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满洲国奉天省省长', NULL, '辽宁沈阳人，九一八事变后投降日本，任伪奉天省省长，管辖包括康平在内的辽宁地区，镇压抗日活动，为日军征粮派夫。', '辽宁沈阳_康平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6e43b9f5032c510c9a12e1ef25febc23', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1932, '伪满洲国监察院院长', NULL, '辽宁辽阳人，曾任奉天省议会议长，后投敌，参与伪满政权建立，对辽宁地区（含沈阳、康平）的殖民统治有协助作用。', '辽宁沈阳_康平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8ec9d01d4ec65249bd5d1d5f217f6822', 'a2f31a9be59d5a89b0426ae789e7bef9', 1932, '伪满洲国参议府参议', NULL, '辽宁辽阳人，清末举人，九一八后投靠日本，任伪满参议，参与制定奴化政策，影响沈阳及康平地区。', '辽宁沈阳_康平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fed19a87db0b57519e31a2bad2b2a335', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满洲国立法院院长', NULL, '辽宁沈阳人，曾任奉天省教育厅长，后投日，任伪满立法院院长，推动日本殖民教育在沈阳、康平等地实施。', '辽宁沈阳_康平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cd1a757dc815563089dd1ce9e158349d', '1c5a7c0239a3585ba753fb5dd8066643', 1931, '伪满洲国奉天省财政厅长（后投敌）', NULL, '辽宁沈阳人，原为奉系官员，九一八后投靠日本，任伪奉天省财政厅长，为日军搜刮康平地区资源。', '辽宁沈阳_康平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e31523ebcc0553eda5913d1e6a2a4504', '581b3709952c5c81bc3860d3c62dff90', 1933, '伪满洲国热河省省长（曾任奉天省警务厅长）', NULL, '辽宁沈阳人，曾任奉天省警务厅长，后任伪热河省长，期间参与对辽宁北部（含康平）的治安镇压。', '辽宁沈阳_康平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('16bdbd702ee654f7ac6fa2be6ea3e1fb', '58e6d43c943f58a9a8100d50bf928499', 1932, '伪满洲国奉天市市长', NULL, '辽宁沈阳人，投日后任伪奉天市长，管理沈阳城区，并配合日军对康平地区的清乡行动。', '辽宁沈阳_康平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('880bd9ae65e5596c823dd240343dd058', 'e6b8425fe2a75f1390d3cc8927ce0ae7', 1932, '伪满洲国康平县县长', NULL, '辽宁康平本地人，九一八后投靠日军，任伪康平县县长，协助日军建立伪政权，强征民夫，镇压抗日义勇军。', '辽宁沈阳_康平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('82ae11101d9059c4bea98f15b52d765a', 'a25f3a2741a35f898c5bd47dbee6501d', 1933, '伪满洲国康平县警务科长', NULL, '辽宁康平人，任伪康平县警务科长，抓捕抗日分子，为日军提供情报，参与制造多起屠杀事件。', '辽宁沈阳_康平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6cab9d8eb9845e9492633710f0e39447', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满洲国洮辽警备司令', NULL, '辽宁盖平人（原奉天省），曾任奉军师长，后投日，任洮辽警备司令，管辖范围包括康平地区，多次围剿抗日武装。', '辽宁沈阳_康平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e198c6a858e35a398b2e2531415e12dd', '802dd1e9fe095ba4a8cbdc66a100361e', 1932, '伪满洲国奉天省警备司令', NULL, '辽宁台安人，投日后任伪奉天省警备司令，负责辽宁中部及北部（含康平）的军事镇压，屠杀抗日军民。', '辽宁沈阳_康平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5800386b80b75aea83240b72508f4f5b', '1ea6405224d35b439d5a62eb23dca975', 1933, '伪满洲国奉天省保安局长', NULL, '辽宁沈阳人，任伪奉天省保安局长，在康平地区推行保甲制度，强化殖民统治，逮捕抗日志士。', '辽宁沈阳_康平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3fa64ed15fde5c1c869295100d473fa8', 'df85b9e8c1b05cedba1173db2a702e1b', 1931, '伪满洲国康平县维持会会长', NULL, '辽宁康平人，九一八后率先组织维持会迎接日军，任会长，为日军提供当地情报和物资。', '辽宁沈阳_康平');
