INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('851083a79a285512b12cc2dc9e29aac7', 'd6ca38cec4105c5ea630f21d3071e2d8', 1937, '伪满洲国康平县警察署署长', NULL, '辽宁康平人，任伪警察署长，参与抓捕抗日地下党员，迫害百姓，罪行累累。', '辽宁沈阳_康平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1fac34509d9d5411b68d20720cf53ee8', '0da09f00ee6a55878e86adbb70127338', 1932, '伪满洲国财政部大臣', NULL, '辽宁沈阳人，曾任奉天省财政厅长，后投日任伪满财政大臣，制定经济掠夺政策，影响康平地区粮食统制。', '辽宁沈阳_康平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4f64581df9275d248a75c44d7c7d08d6', '8f60ed6bf0f85a62a7840ff91b875b4f', 1932, '伪满洲国经济部大臣', NULL, '辽宁沈阳人，投日后任伪满经济部大臣，推行“产业开发计划”，在康平地区强占土地和矿产。', '辽宁沈阳_康平');
