INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('36c323d9082e5891a1246c0001d0f99c', '318089c2a3375e67b7c33f0820381332', 1932, '伪满奉天省教育厅长', NULL, '推行奴化教育，在沈阳、铁西各学校强制普及日语，删除中国历史教材，灌输“日满亲善”思想。', '辽宁沈阳_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7882f4ae93f557d48a6bca7d2589c932', 'e6b8425fe2a75f1390d3cc8927ce0ae7', 1938, '伪满铁西区区长', NULL, '铁西区伪政权头目，协助日军建立“工业区”管理，强征土地，迫害中国工人，镇压罢工。', '辽宁沈阳_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('42ec97f75e2a5923919527223b132e2f', '5b31cc548dbb589e849e68b191d9b150', 1932, '伪满奉天省警务厅长', NULL, '指挥伪警察在沈阳、铁西地区搜捕抗日分子，实施“连坐”制度，多次参与屠杀平民。', '辽宁沈阳_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0cead13715ba52be9624cdeaa8db9104', 'ed63d30af50b59dd817d7f50f2b58ea9', 1933, '伪满奉天市警察局长', NULL, '铁杆汉奸，亲自带队抓捕抗日地下党员，刑讯逼供，破坏沈阳地下抗日组织。', '辽宁沈阳_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('42fb211759125d5781f7586a1afc0902', '23d2a99a25bc56ccb75b9b643dc2ee4a', 1939, '伪满铁西区保安队长', NULL, '率伪保安队协助日军“清乡”，在铁西工厂区监视工人，举报抗日言论，导致多人被捕杀害。', '辽宁沈阳_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9d091b59325e50c08f18a0437f63a8f3', '55d5c28516215af6bb912b6e514aad47', 1934, '伪满奉天省协和会头目', NULL, '在沈阳、铁西组织“协和会”，煽动民众支持日本侵略，收集情报，破坏抗日团体。', '辽宁沈阳_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1da50bbe0d5355798c35912f4c741d32', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省警备司令、伪满将军', NULL, '原为东北军将领，九一八后投敌，在盘锦、营口一带协助日军镇压抗日武装，后任伪满热河省警备司令，参与围剿抗日义勇军。', '辽宁盘锦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f12538c806885ee9a4c2c37aa2dc3e98', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满盘山县县长', NULL, '在盘山县任伪县长期间，推行日伪殖民政策，强征劳工，镇压抗日活动，协助日军清乡。', '辽宁盘锦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e51f48901c1d5084b4cf6c5bd971d2b5', 'f13fea3281b35a0ea71eb3863d7d53f7', 1933, '伪满盘山县警务科长', NULL, '负责盘山地区伪警察机构，抓捕抗日志士，为日军提供情报，参与“讨伐”行动。', '辽宁盘锦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d8a3304d2aa952e7a4b372bbe2c42b3d', 'd6ca38cec4105c5ea630f21d3071e2d8', 1934, '伪满盘山县保安团长', NULL, '组织伪保安团协助日军扫荡盘锦地区抗日游击队，杀害多名抗日群众。', '辽宁盘锦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0bb599d529835c73873236fe2b90fcb4', '466551fbaffe5ad0a078e82d80a2cd63', 1931, '伪满营口地区（含盘锦）汉奸头目', NULL, '原为地方豪强，投日后担任伪职，在盘锦、营口交界处为日军征收粮饷，迫害百姓。', '辽宁盘锦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f221aa1773f45436974a5eba26d40c07', '5862474cdebe50a7aebd82554eee7c4a', 1937, '伪满盘山县协和会会长', NULL, '负责协和会在盘山的宣传与特务活动，煽动民众“亲日”，举报抗日分子。', '辽宁盘锦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c94f42b104bc53c7bd7578f5ed1d1e68', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满洲国国务总理大臣（关联盘锦地区活动）', NULL, '虽为伪满中央高官，但曾在盘锦地区视察并推动“治安肃正”，间接支持当地汉奸镇压抗日力量。', '辽宁盘锦');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eba929187d4d57c18b705afa1f01133c', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满洲国热河省省长、伪军将领', NULL, '原东北军将领，九一八事变后投靠日本，曾任伪满洲国热河省省长，参与镇压抗日武装，其势力范围曾涉及辽宁西部地区。', '辽宁盘锦_兴隆台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5b0721e0b226599f986acc86eed4c46a', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满洲国奉天省省长、伪军上将', NULL, '原东北军将领，投日后任伪奉天省省长，管辖范围包括今沈阳、盘锦等辽宁中南部地区，积极推行日伪殖民政策，镇压抗日力量。', '辽宁盘锦_兴隆台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7d8d2b0e6c4055018317e4f97141c3eb', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满洲国军管区司令', NULL, '原东北军军官，投日后任伪军司令，驻防辽宁中南部，参与围剿盘锦、营口一带的抗日义勇军。', '辽宁盘锦_兴隆台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2628d8e4ab8a5a0d9f226eebde996da0', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满洲国立法院院长、奉天市市长', NULL, '曾任伪奉天市市长，后升任伪立法院院长，在辽宁地区推行奴化教育和经济掠夺政策，其活动范围覆盖盘锦地区。', '辽宁盘锦_兴隆台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3cd1bd348df757f186800eb9fd620086', '318089c2a3375e67b7c33f0820381332', 1931, '伪满洲国交通部大臣、奉天省省长', NULL, '原奉系官员，投日后历任伪奉天省省长等职，管辖辽宁大部，包括盘锦地区，协助日军征粮、抓劳工，镇压抗日活动。', '辽宁盘锦_兴隆台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3793aec4ada052eda9b537d1bdfdea1a', '58e6d43c943f58a9a8100d50bf928499', 1934, '伪满洲国锦州省省长', NULL, '伪锦州省省长，管辖范围包括今盘锦西部及兴隆台周边地区，积极推行日伪“治安肃正”，参与屠杀抗日军民。', '辽宁盘锦_兴隆台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c09a4d11a6e65bf390310e6c63fdd2b2', '1c5a7c0239a3585ba753fb5dd8066643', 1931, '伪满洲国奉天省警务厅长', NULL, '伪奉天省警务厅长，负责辽宁地区警察特务系统，在盘锦、兴隆台一带设立伪警察所，搜捕抗日分子。', '辽宁盘锦_兴隆台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4da2b5877d245eb8923e3f793c5626c1', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满洲国军旅长、盘山地区伪保安队长', NULL, '原土匪头目，投日后任伪军旅长，长期盘踞盘山（今盘锦）地区，配合日军“讨伐”抗日义勇军，烧杀抢掠。', '辽宁盘锦_兴隆台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9bb4e28789955862a9317e1a2495a9bf', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满洲国国务总理大臣', NULL, '原奉系军阀，投日后任伪满洲国总理，虽为中央级汉奸，但其伪政权统治覆盖辽宁全省，包括盘锦、兴隆台地区，签署多项卖国条约。', '辽宁盘锦_兴隆台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f2a56980243a54e78fab985b3e5ec136', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满洲国参议府议长、奉天省省长', NULL, '原奉天省省长，九一八后投日，任伪奉天省省长，管辖辽宁中南部，包括盘锦地区，推行“保甲连坐”制度，镇压抗日群众。', '辽宁盘锦_兴隆台');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d39f5ac42c3258a084c950e73dff4bb7', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满洲国热河省省长、伪军将领', NULL, '原东北军将领，九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，在盘锦、双台子一带协助日军清乡', '辽宁盘锦_双台子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4aeda4d12f7850f890df050280364ce9', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满洲国锦州省警务厅长', NULL, '原为地方警察头目，投日后任伪锦州省警务厅长，管辖盘锦、双台子地区，多次组织围剿抗日义勇军，抓捕抗日志士', '辽宁盘锦_双台子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8747f3ab7da3530c8bc53f168bc211c2', 'f13fea3281b35a0ea71eb3863d7d53f7', 1933, '伪满洲国盘山县县长', NULL, '任伪盘山县县长期间，强征民夫修建日军据点，推行保甲制度，强迫百姓献粮献铁，镇压当地抗日活动', '辽宁盘锦_双台子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2eed5d0891915c2cb64c99f206b1a637', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满洲国奉天省高等法院院长', NULL, '虽主要活动于奉天（沈阳），但曾多次到盘锦、双台子地区审理“反满抗日”案件，判处多名抗日分子死刑', '辽宁盘锦_双台子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('41096842281e58459895d53d7409d234', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1931, '伪满洲国参议府参议、鞍山昭和制钢所顾问', NULL, '曾参与策划辽南地区“自治”运动，在盘锦、双台子一带煽动地方势力归顺日本，为日军侵略提供情报', '辽宁盘锦_双台子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('04bdad01e15a57a78dd02846ad09ba14', '2b437180a5505d89afed6a8146c9383e', 1932, '伪满洲国交通部大臣', NULL, '原奉系官员，投日后主管伪满交通，曾主持修建通过盘锦、双台子地区的军用公路和铁路，便利日军军事运输', '辽宁盘锦_双台子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1aa32dced7175a7a9e82aeab3cb6a34a', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满洲国国务总理大臣', NULL, '虽为伪满最高汉奸之一，但曾多次巡视盘锦、双台子地区，督促地方伪政权强化殖民统治，推行“粮谷出荷”政策', '辽宁盘锦_双台子');
