INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6af46e6664ca5e3da3b58a5aee5bbf3c', '85aa2fd10d9c5918aff4e588d092ec71', 1932, '伪满洲国司法部大臣', NULL, '曾参与制定伪满法律，在盘锦、双台子地区设立“矫正院”，关押迫害抗日群众，实施奴化教育', '辽宁盘锦_双台子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('58ef92f6b0315e25b5346b12d2882019', '581b3709952c5c81bc3860d3c62dff90', 1937, '伪满洲国奉天省省长', NULL, '管辖包括盘锦、双台子在内的奉天省，强化“协和会”组织，强迫民众参加反共集会，镇压抗日力量', '辽宁盘锦_双台子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('76b2f962c2dd5dddb6d255eab4b6ace0', '58e6d43c943f58a9a8100d50bf928499', 1938, '伪满洲国盘山县警务科科长', NULL, '直接负责盘锦、双台子地区治安，抓捕抗日地下党员，严刑逼供，曾一次逮捕并杀害多名抗日群众', '辽宁盘锦_双台子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a7dc8739b38254828d6a69a68cfdd6cc', '55d5c28516215af6bb912b6e514aad47', 1940, '伪满洲国双台子警察署署长', NULL, '在双台子地区设立多个检查站，盘查过往行人，搜捕抗日分子，并协助日军强征劳工', '辽宁盘锦_双台子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9105101125f75c67bdea2e4840048051', '0da09f00ee6a55878e86adbb70127338', 1937, '伪满洲国民生部大臣', NULL, '曾到盘锦、双台子地区推行“国民储蓄”和“勤劳奉仕”制度，强迫百姓无偿劳动，为日军服务', '辽宁盘锦_双台子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7d0016456a91531699d5e28f05f84c66', 'a2f31a9be59d5a89b0426ae789e7bef9', 1932, '伪满洲国参议府议长', NULL, '作为伪满高级顾问，曾多次到盘锦、双台子地区视察，指导地方伪政权强化殖民统治，镇压抗日运动', '辽宁盘锦_双台子');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e5cbac60fbc45ef4a97f77afa5c79597', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满洲国热河省省长、伪满军上将', NULL, '原为东北军将领，九一八事变后投敌，曾任伪满热河省省长，协助日军镇压抗日武装，在辽宁西部及盘锦、大洼一带活动，参与围剿义勇军和抗联部队。', '辽宁盘锦_大洼');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a2831f40bddd54ea8d94b45c2cbd2ea0', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满洲国奉天省省长、伪满军上将', NULL, '原东北军旅长，叛变投日后任伪奉天省省长，管辖范围包括今盘锦、大洼地区，积极推行日伪殖民政策，强征劳工，镇压抗日活动。', '辽宁盘锦_大洼');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8b0788dff1b0521fa6d66b8e3378dd3f', '1c5a7c0239a3585ba753fb5dd8066643', 1932, '伪满洲国锦州省省长（后改任）', NULL, '原为地方士绅，投靠日军后任伪锦州省省长，其辖区涵盖盘锦、大洼一带，协助日军建立保甲制度，搜刮民财，迫害抗日家属。', '辽宁盘锦_大洼');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('777d4a4eff9659c3a3c027bbc9607c45', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满洲国立法院院长、伪奉天市市长', NULL, '早年留学日本，九一八后积极参与伪满建国，曾任伪奉天市市长，对盘锦、大洼地区日伪统治有间接管辖，推动奴化教育和经济掠夺。', '辽宁盘锦_大洼');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f557451443b15a40910232f8212d5c1f', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满洲国参议府议长', NULL, '清末举人，投日后任伪满参议府议长，虽居高位，但曾参与策划对辽宁各地（包括盘锦、大洼）的“治安肃正”行动，支持日军清乡。', '辽宁盘锦_大洼');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('40e687428b8858c9884df9f14c820e1d', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满洲国国务总理大臣', NULL, '原东北军将领，后任伪满总理，其政策覆盖辽宁全境，包括盘锦、大洼，推行“粮谷出荷”和“劳工供出”，导致当地民众饥寒交迫。', '辽宁盘锦_大洼');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6eda913f6a735de3b4d810d54ab6e997', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满洲国奉天省省长（前期）', NULL, '原东北军参谋长，投敌后任伪奉天省省长，在盘锦、大洼地区设立日伪警察机构，抓捕抗日志士，强征土地。', '辽宁盘锦_大洼');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('040bc448b5aa573095b95a12ecf25452', '2300e528128d54c19855a4669664572a', 1931, '伪满洲国财政部总长、宫内府大臣', NULL, '清室后裔，投日后任伪满高官，曾参与策划对辽宁南部（含盘锦、大洼）的军事“讨伐”，并协助日军掠夺当地资源。', '辽宁盘锦_大洼');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('63ceb15716455fcfa07790b296b471cd', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1932, '伪满洲国监察院院长', NULL, '原为日本关东军翻译，后任伪满监察院院长，曾多次到辽宁各地（包括盘锦、大洼）督导“治安强化运动”，镇压抗日力量。', '辽宁盘锦_大洼');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2e1392e29ee752d7bfe60095e7785e5d', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满洲国锦州省警务厅厅长', NULL, '原为土匪头目，投日后任伪锦州省警务厅厅长，直接管辖盘锦、大洼地区警察，率伪警配合日军扫荡，杀害无辜百姓。', '辽宁盘锦_大洼');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('31b2e9835e89555893becdafb9dd051a', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满洲国盘山县县长（今盘锦市大洼区一带）', NULL, '投靠日军后任伪盘山县县长，在任期间强制推行“归屯并户”，焚烧民房，制造无人区，并强征农民充当苦力。', '辽宁盘锦_大洼');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cbf9eb0ff4c45b16a0b89fdeada9ce64', 'ea4b8090ce345fadb2090c490667411a', NULL, '无', NULL, '不列入，因未投敌。', '辽宁盘锦_大洼');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('33b37e215be9573aa9abf61b78659198', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满第5军管区司令', NULL, '原东北军将领，九一八后投敌，在盘山、营口一带协助日军镇压抗日武装，后任伪满热河省省长，围剿抗日义勇军。', '辽宁盘锦_盘山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('46225343dd8d5a22a9bf00411ce17c8a', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满奉天省警务厅厅长、伪满警察头目', NULL, '盘山县人，曾任伪满奉天省警务厅厅长，在盘锦地区推行保甲制度，抓捕抗日地下人员，参与“讨伐”抗日联军。', '辽宁盘锦_盘山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b98de79b277659329d216a613f08de8f', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长、伪满法制局总裁', NULL, '盘山籍（一说辽宁），九一八后积极投靠日本，参与伪满政权筹建，制定伪满法律，为日本殖民统治提供法理依据。', '辽宁盘锦_盘山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b0819f52917a5995a9ccf2ef70723301', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满第一军管区司令、伪满治安部大臣', NULL, '原东北军将领，投敌后任伪满第一军管区司令，管辖辽宁中南部，多次在盘山、台安一带清剿抗日义勇军。', '辽宁盘锦_盘山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('421663bf17385e10aa411badfd3d0ba0', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满国务总理大臣', NULL, '虽非盘山籍，但作为伪满最高汉奸之一，其势力覆盖辽宁全省，包括盘锦地区，支持日军对当地抗日力量的镇压。', '辽宁盘锦_盘山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('086308fc059e5a83946831dd068a9c7b', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满奉天省省长、伪满参议府议长', NULL, '原辽宁省主席，投敌后任伪满奉天省省长，管辖盘山、盘锦地区，推行奴化教育和经济掠夺政策。', '辽宁盘锦_盘山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dd03c74f27905e5e95f1d1116935baed', '581b3709952c5c81bc3860d3c62dff90', 1934, '伪满锦州省省长', NULL, '伪满锦州省辖区包括盘山部分地区，任内配合日军“治安肃正”，在盘山一带强征劳工、建立伪警察机构。', '辽宁盘锦_盘山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b86b80c845fe5b1cb6222da0bc829f22', '1c5a7c0239a3585ba753fb5dd8066643', 1932, '伪满盘山县县长（首任）', NULL, '盘山县人，九一八后投敌，任伪满盘山县县长，组织伪县公署，协助日军收缴民间武器，镇压抗日活动。', '辽宁盘锦_盘山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('48c509077baa536f87848faa1283d630', '928da6abb9a15c7384b70ef1a7a789e2', 1937, '伪满盘山县县长', NULL, '继任伪满盘山县县长，推行“保甲连坐”制度，强征粮食和劳工，为日军提供物资支持。', '辽宁盘锦_盘山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fb3ab6b8715e54268876227e9a5ff652', '55d5c28516215af6bb912b6e514aad47', 1933, '伪满盘山县警务科科长', NULL, '盘山本地人，任伪满盘山县警务科科长，亲自带队抓捕抗日义勇军家属，刑讯逼供，杀害多名抗日志士。', '辽宁盘锦_盘山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bea64c479b545867aa1260b2a7d45285', '2a816e97326c5210bdec3a2c3af8c214', 1938, '伪满盘山县协和会会长', NULL, '盘山士绅，投靠日伪后任协和会会长，宣传“日满亲善”，组织青少年奴化训练，破坏抗日地下组织。', '辽宁盘锦_盘山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4d51dde5a0a352b6b55b4dcbeb67d27f', '1cf24e0dd2285d7b95a248b021456e1c', 1932, '伪满盘山县保安队队长', NULL, '盘山土匪出身，被日伪收编后任保安队队长，在盘山、大洼一带袭击抗日游击队，烧毁村庄。', '辽宁盘锦_盘山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('62f097a355ea5139bd0239241c3e719e', 'd6ca38cec4105c5ea630f21d3071e2d8', 1935, '伪满盘山县田赋局局长', NULL, '盘山籍，任伪满田赋局局长，残酷征收“出荷粮”，导致当地农民饿死无数，并将粮食供给日军。', '辽宁盘锦_盘山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('618abfa0b080595e9f5937189c473ad6', 'aa7913ec446c597faf6a8833076cf708', 1936, '伪满盘山县教育长', NULL, '推行奴化教育，强制学生学日语，删除中国历史教材，检举有抗日思想的教师。', '辽宁盘锦_盘山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ecdbe46b40615723bc7248f9f805c946', 'a3eb8307fd6a5cd5a48713eabac55d34', 1937, '伪满盘山县司法科审判官', NULL, '盘山本地汉奸，在伪法庭上以“反满抗日”罪名判处多名爱国人士死刑或重刑。', '辽宁盘锦_盘山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('62f1d217262a5ccd9f1fd4a6c28a1e7e', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满营口市市长', NULL, '任伪满营口市长期间，推行日伪殖民政策，协助日军镇压抗日活动，强征劳工，控制港口经济为日军服务。', '辽宁营口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f034590ae2c355b89d33ead5e5b927ef', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长（曾驻营口活动）', NULL, '原东北军将领，九一八后投敌，在营口及辽南地区协助日军清剿义勇军，后任伪满省长，参与“讨伐”抗日武装。', '辽宁营口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0d08451c95925e24862afc9e397518e0', '802dd1e9fe095ba4a8cbdc66a100361e', 1932, '伪满第一军管区司令（辖营口）', NULL, '原奉军旅长，叛国投日，在营口、海城等地指挥伪军围剿抗日义勇军，残害抗日军民。', '辽宁营口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('207cbd8df98c5d28bd52387c96b248d0', 'f13fea3281b35a0ea71eb3863d7d53f7', 1933, '伪满营口警察局局长', NULL, '效忠日寇，在营口市区及周边大肆搜捕抗日地下人员，破坏抗日组织，参与“治安肃正”行动。', '辽宁营口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('af73ef7360dd5c619d59181820a02b25', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满奉天省高等法院院长（涉及营口案件）', NULL, '汉奸法律人物，曾参与审判营口地区抗日志士，为日伪司法镇压提供合法化工具。', '辽宁营口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('03680184ad18558eb35b5bc5762b7f96', 'af224963fb455c99a96bee0aadf29f89', 1931, '伪满营口商会会长', NULL, '充当日本经济侵略代理人，强制商户为日军提供物资，协助日伪掠夺营口港资源，迫害爱国商人。', '辽宁营口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('932343bd2e505c418ad39001285ca5f3', '8cd73e13b8df5e02b80d5cc5c03f0a11', 1931, '伪满营口地方维持会成员', NULL, '九一八后参与组织营口地方维持会，迎接日军占领，协助建立伪政权，为日军征粮派款。', '辽宁营口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d313b7d3e77e59469b55657da01a1bbd', '55d5c28516215af6bb912b6e514aad47', 1934, '伪满营口县县长', NULL, '在营口县推行日伪“保甲制度”，强征民夫修筑军事工事，配合日军“清乡”屠杀抗日群众。', '辽宁营口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3cbb003f6bc850449d4d03eb3d2d7dfd', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满国务总理大臣（曾巡视营口）', NULL, '作为伪满最高汉奸之一，多次到营口等地督导“治安强化运动”，推动奴化教育，支持日军经济掠夺。', '辽宁营口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5180879c6bd75b258c6e787fa3161463', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满奉天省省长（辖营口）', NULL, '原辽宁省主席，投敌后任伪奉天省长，对营口地区抗日武装进行残酷镇压，签订卖国协定。', '辽宁营口');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b70f608f20e554be9cce8e2b481cf6e5', '802dd1e9fe095ba4a8cbdc66a100361e', 1932, '伪满洲国奉天省省长、治安部大臣', NULL, '原东北军将领，九一八事变后投敌，任伪奉天省省长，积极推行日伪殖民统治，镇压抗日力量，后升任伪满洲国治安部大臣。', '辽宁营口_大石桥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1b5d4dc04f5c52efa5d59215a1dd615b', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满洲国奉天省警务厅厅长', NULL, '在营口、大石桥地区任伪警务要职，组织伪警察配合日军“讨伐”抗日武装，抓捕抗日志士，残害百姓。', '辽宁营口_大石桥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('82728497b9bd56e48c6eb16fd6a8f7a4', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满洲国热河省省长、伪满军事部大臣', NULL, '原奉系军阀，九一八后公开投敌，虽主要活动于热河，但其势力曾涉及辽南地区，协助日军镇压抗日义勇军。', '辽宁营口_大石桥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e55d949980d65adf8b26f81e28854082', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满洲国立法院院长、奉天市市长', NULL, '原东北政客，投日后任伪奉天市长，在营口、大石桥一带推行奴化教育，协助日军经济掠夺。', '辽宁营口_大石桥');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4a874424a1d55fcea2fc421e292fb504', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1931, '伪满洲国监察院院长、奉天省省长', NULL, '原奉系官僚，投敌后长期在奉天省（含营口地区）任职，为日军提供情报，参与“清乡”行动。', '辽宁营口_大石桥');
