INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('99f5eaa640075515b2c9ce4d08b198c1', '73a6791b29c251b98dbd513ac57fba15', 1939, '伪满营口市协和会事务长', NULL, '负责协和会日常活动，组织青少年进行军事训练，宣传“日满亲善”，并监视居民言行。', '辽宁营口_盖州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dbdd2fa092655d29b6dea6d4f88bfa66', 'fdc924a005d9538a8da27a0094bf8f69', 1936, '伪满盖平县教育局长', NULL, '强制推行日语教育，删改历史教材，灌输奴化思想，并检举有抗日倾向的教师和学生。', '辽宁营口_盖州');
