INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e8270d1ea2bc583f8198f3cf41f5b853', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长（曾活动于营口西市一带）', NULL, '原东北军将领，后投敌叛国，在营口及周边地区协助日军清乡，参与“讨伐”抗日武装，推行奴化教育。', '辽宁营口_西市');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c719a8324e9554da85a91d8d6df8aed9', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满奉天省警备司令（曾管辖营口地区）', NULL, '原东北军旅长，投日后在营口、西市一带组织伪军，配合日军“扫荡”，残害抗日军民，强征粮食。', '辽宁营口_西市');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1b7a08025acd5b478e0588b1728ebf90', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长（祖籍营口，曾回营口活动）', NULL, '积极鼓吹“满洲独立”，在营口西市等地发表亲日演讲，协助日本关东军建立伪政权，参与制定奴化政策。', '辽宁营口_西市');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b4c08a27e5d65268839809ef22a42d88', 'af224963fb455c99a96bee0aadf29f89', 1931, '伪满营口市商会会长', NULL, '在营口西市地区为日军筹集军饷，强迫商户捐献物资，向日伪当局举报抗日商人，协助经济统制。', '辽宁营口_西市');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0ac23f51932351ff8723740485dbac46', 'f13fea3281b35a0ea71eb3863d7d53f7', 1931, '伪满营口县保安队队长', NULL, '带领保安队在西市一带抓捕抗日地下工作者，参与屠杀无辜百姓，为日军提供劳力和情报。', '辽宁营口_西市');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0178fbf6be9859cfb25a583b8fccc5e9', '802dd1e9fe095ba4a8cbdc66a100361e', 1932, '伪满洲国奉天省省长', NULL, '曾任东北军将领，后投靠日本，任伪奉天省省长，积极推行日伪殖民政策，镇压抗日力量，其管辖范围包括营口地区。', '辽宁营口_鲅鱼圈');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('43576f200c795a3498664715240a2e7e', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满洲国营口市市长', NULL, '原营口地方士绅，日军占领营口后出任伪市长，协助日军维持统治，强征劳工，为日军提供物资支持。', '辽宁营口_鲅鱼圈');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cbca9d16479e5b1eb504045bd191b304', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪满洲国热河省省长（曾驻营口）', NULL, '原东北军将领，九一八后投敌，曾任伪热河省长，期间在营口、鲅鱼圈一带协助日军清剿抗日武装，残害百姓。', '辽宁营口_鲅鱼圈');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c1c1f55bbf2a5136bdea14c3ee829d9b', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满洲国营口地区保安队队长', NULL, '原营口警察，后任伪保安队长，多次配合日军围剿抗日游击队，在鲅鱼圈沿海地区抓捕抗日志士，强征民夫。', '辽宁营口_鲅鱼圈');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6df4d968b084562bbcc4045b17429dcf', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满洲国奉天省高等法院院长（涉及营口案件）', NULL, '原中国律师，投日后任伪法院院长，在营口地区审判抗日人士，以“反满抗日”罪名判处多人死刑或重刑。', '辽宁营口_鲅鱼圈');
