INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bb8e42e9a5b057a49fa61b736956e36c', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满洲国国务总理大臣（名义管辖营口）', NULL, '原东北军将领，后为伪满最高行政长官，其政策直接作用于营口地区，支持日军经济掠夺，强征粮食和劳工。', '辽宁营口_鲅鱼圈');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fd9ed28e2ddc522fa9ae394a9a289dea', 'ba311422856554c7ad7f3f75d09c3d78', 1932, '伪满洲国奉天省省长（前期）', NULL, '原奉天省主席，投日后任伪省长，在营口地区推行“归屯并户”，制造无人区，导致大量平民死亡。', '辽宁营口_鲅鱼圈');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('20ac8253003b56e89f4f88db22ec33ff', '58e6d43c943f58a9a8100d50bf928499', 1932, '伪满洲国营口市警察局局长', NULL, '原营口警察，投日后任伪警察局长，协助日军特务机关，在鲅鱼圈港口监控往来船只，逮捕抗日地下工作者。', '辽宁营口_鲅鱼圈');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('943de27693fe5303b68f842d5704e505', 'b0a035dbfb8b520483e87215296b61e8', 1933, '伪满洲国营口港务局局长', NULL, '原营口港职员，投日后管理鲅鱼圈港区，为日军运输军需物资，强迫中国工人无偿劳动，克扣口粮。', '辽宁营口_鲅鱼圈');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a3aa837924f954c788bfc2de368dfad0', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八后投敌，任伪满热河省省长，参与镇压抗日义勇军，协助日军进攻热河。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5d6f07d0ccd75b85a2b03edcc1faf034', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满奉天省省长、伪满治安部大臣', NULL, '原东北军旅长，投降日军后任伪奉天省省长，推行殖民统治，镇压抗日力量。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2fa1fbd09bcb5bc8ac346bc58ced26f2', '1c5a7c0239a3585ba753fb5dd8066643', 1934, '伪满锦州省省长', NULL, '原奉系官员，伪满时期任锦州省省长（辖区含今葫芦岛地区），协助日伪推行“治安肃正”和奴化教育。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('55e5c144f9f950de9d4c22e306dfb98e', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长、伪满奉天市长', NULL, '原奉系法律人士，投日后任伪奉天市长，参与建立伪满政权，协助日军在辽宁地区进行殖民统治。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3f5bb4fb87a45208a62976cddb439bc1', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满参议府议长', NULL, '原奉系政客，九一八后组织“辽宁地方维持会”，投靠日军，后任伪满参议府议长，为日本侵略张目。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5ab7117fddfd58d09f96ae2112e502cd', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满奉天省省长、伪满民政部大臣', NULL, '原东北军将领，被俘后投降，任伪奉天省省长，推行日伪政策，镇压抗日活动。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('29e8d7c736055eaa8bfde8851345afae', '2300e528128d54c19855a4669664572a', 1931, '伪满财政部总长、伪满宫内府大臣', NULL, '原吉林副司令长官，投日后参与策划伪满建国，虽主要在吉林活动，但曾参与对辽宁地区抗日力量的围剿。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2dcc5ee780145981bdb32e04a964f808', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满国务总理大臣', NULL, '原东北军将领，九一八后投敌，任伪满最高行政长官，全面协助日本统治东北，包括辽宁葫芦岛地区。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('439384838a975a80962749048b1a378d', 'd7eca4cf356953a9bd843f9ae77031f1', 1932, '伪满黑龙江省省长（短暂投敌后反正）', NULL, '曾一度投降日军任伪职，但不久反正抗日，其投敌期间未在葫芦岛地区有具体活动，但作为东北汉奸名单常被提及。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('07e3559ab91956cfb284e88e3e6fe55a', '8f60ed6bf0f85a62a7840ff91b875b4f', 1931, '伪满奉天省实业厅长、伪满经济部大臣', NULL, '原奉系商人，投日后任伪奉天省实业厅长，协助日本掠夺辽宁资源，包括葫芦岛地区的矿产和农产品。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a7a845cef1f9550b891d11a159b00864', '318089c2a3375e67b7c33f0820381332', 1935, '伪满锦州省次长（实际掌权者）', NULL, '日本关东军指派日籍官员，但作为伪满官员，在锦州省（含葫芦岛）推行“集家并村”和“治安肃正”，残害百姓。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b7c6795456df5776bfb999a979dc69fe', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满锦州省警务厅长', NULL, '原奉系警察头目，投日后任伪锦州省警务厅长，指挥伪警察在葫芦岛地区抓捕抗日志士，镇压民众。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('73fba562bd155a299986186d14b67e64', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满锦西县（今葫芦岛市连山区）县长', NULL, '投日后任伪锦西县长，协助日军建立伪政权，强征劳工，参与“讨伐”抗日义勇军。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('396a3585651959619435f228c20da876', '34279a10aeeb55cb97ee1ff96fae70fd', 1933, '伪满绥中县（今属葫芦岛市）县长', NULL, '投日后任伪绥中县长，推行日伪奴化教育，强征粮食，镇压当地抗日活动。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fe615a465bb857c2bb2d4693d32aa085', '2a816e97326c5210bdec3a2c3af8c214', 1931, '伪满兴城（今属葫芦岛市）维持会长', NULL, '九一八后短暂组织地方维持会投靠日军，后因内部矛盾被撤换，但初期协助日军稳定占领秩序。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ed1ae2b963f25af7a64031698f1f9dd1', '197ef667cd7f5fd080723764d67d1541', 1935, '伪满锦州省兴城县协和会会长', NULL, '利用家族影响，在兴城（今葫芦岛）组织协和会，宣传“日满亲善”，协助日军进行思想控制。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e82f055728245c17b74803cdcf0bbfca', 'f9f932ce9e425eae805c79cd0412d621', 1934, '伪满葫芦岛港务局局长', NULL, '投日后任伪葫芦岛港务局长，协助日军扩建港口，用于军事运输和掠夺资源。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('da346154e20e5d378e31a282160669ce', 'f5a772d6aa0a5576852bb4bc7015d992', 1933, '伪满锦西县保安队长', NULL, '组织伪保安队，配合日军在葫芦岛地区进行“扫荡”，杀害抗日军民。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1bdd0307c1eb5c548d6de3570fdcd27d', '1cf24e0dd2285d7b95a248b021456e1c', 1932, '伪满绥中县警察署长', NULL, '指挥伪警察在绥中（今葫芦岛）抓捕抗日地下党员，破坏抗日组织。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fbbd057947ba5beeb7a35da5d2b54436', '2d7b1455e7435e93804554794fd6507c', 1936, '伪满兴城县教育局长', NULL, '推行日本奴化教育，强制学校教授日语，删除中国历史内容，在葫芦岛地区毒害青少年。', '辽宁葫芦岛');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e079215beee153118ba6cbdd824a644b', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满洲国热河省省长兼第五军管区司令', NULL, '原东北军将领，九一八后投敌，在辽宁西部及兴城、绥中一带协助日军镇压抗日武装，参与“讨伐”义勇军，后任伪热河省省长，推行殖民统治。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2a627c4dd5cb57df9a5adc9bc54de7ad', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满洲国奉天省警备司令官、第一军管区司令', NULL, '原东北军旅长，1932年投降日军，在辽宁地区（包括兴城、葫芦岛一带）指挥伪军围剿抗日义勇军，制造多起屠杀事件。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c7ab29758a4b53019d1cd9f6a8f79709', '1ea6405224d35b439d5a62eb23dca975', 1931, '伪满洲国奉天省警务厅长', NULL, '原东北军军官，投敌后负责辽宁地区伪警察体系，在兴城、绥中等地建立伪警察所，协助日军抓捕抗日志士，强征劳工。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7718ca7cdba65603bbccd42050ab5683', 'f13fea3281b35a0ea71eb3863d7d53f7', 1934, '伪满洲国锦州省省长', NULL, '原锦州地区士绅，投靠日军后任伪锦州省省长，管辖范围包括葫芦岛、兴城，推行“治安肃正”，组织伪自卫团镇压抗日活动。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('811b37e736a9526192dc41d4518252bd', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满洲国立法院院长（曾任奉天市长）', NULL, '原奉系法律人士，九一八后积极参与伪满洲国建立，在辽宁地区协助日军建立殖民政权，参与制定镇压抗日法令，影响波及兴城等地。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('45817c9ae9115efeb345393bf12b9b64', 'af224963fb455c99a96bee0aadf29f89', 1932, '伪满洲国锦州省警务厅长', NULL, '原锦州警察头目，投日后任伪锦州省警务厅长，在葫芦岛、兴城一带指挥伪警“清乡”，杀害抗日军民，掠夺物资。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eb5e8b6dc043540ca1cc7258b58410af', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满洲国国务总理大臣', NULL, '原东北军将领，九一八后投敌，虽为伪满中央高官，但其势力范围及伪军行动覆盖辽宁全境，包括兴城、葫芦岛地区，支持日军“讨伐”义勇军。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2b868373318c5d99b2181cc6e5abddd0', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满洲国参议府议长（曾任奉天省长）', NULL, '原奉天省长，九一八后投降，任伪奉天省长期间，在辽宁各地（含兴城）推行保甲制度，强制民众“连坐”，协助日军清剿抗日力量。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cfe9aff4b044565d900db80285f8666b', '2300e528128d54c19855a4669664572a', 1931, '伪满洲国财政部总长兼吉林省长', NULL, '原吉林军参谋长，投敌后虽主政吉林，但曾参与策划对辽宁西部（包括兴城、葫芦岛）的军事“讨伐”，提供伪军支援。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b3023cbc046d5cf5a6eb85990af228c5', '919e31b890085c6d84989001c33a937f', 1931, '伪满洲国“安国军”司令', NULL, '日本间谍，曾以“安国军”名义在辽宁、热河一带活动，参与对兴城、绥中抗日义勇军的诱降和镇压，协助日军搜集情报。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('13aa92f2c14256889d15fde67064dbc9', '3a45ae481bcf5efd8ec8b12228da26e3', 1931, '伪满洲国“奉天地区”日籍顾问兼伪军头目', NULL, '日本浪人，加入伪满军队，在辽宁锦州、兴城一带指挥伪军“讨伐”抗日武装，手段残忍，制造多起血案。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('90e7ba25533b5157bce3ccbea938e65e', '6dbfe760db385190b48f318c9807b9cc', 1932, '伪满洲国锦州省兴城县县长', NULL, '原兴城地方士绅，投日后任伪兴城县县长，强征粮税，组织伪县公署配合日军“扫荡”，迫害抗日家属。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ed1ea63b25635d03aab54dbadd0b7247', '55d5c28516215af6bb912b6e514aad47', 1933, '伪满洲国锦州省绥中县县长（曾辖兴城周边）', NULL, '投靠日军后任绥中县长，在兴城、绥中交界地带协助日军建立“无人区”，强制村民迁移，烧毁房屋。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('53b13ab835e5514cae09e3b1b5036862', '3c0cec769a465f2da5d9587d32cf51f4', 1932, '伪满洲国锦州省警察讨伐队队长', NULL, '原土匪头目，投日后任伪警察讨伐队长，在兴城、葫芦岛山区多次袭击抗日义勇军，杀害俘虏。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c07508c62dde57ad8ecff106ec52bc0c', '2bfd7cea97c4576bb7e91c332d0275e3', 1933, '伪满洲国兴城地区自卫团团长', NULL, '兴城本地地主，组织伪自卫团，为日军提供情报，参与抓捕抗日地下人员，强征壮丁。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f5865a571ec45bc3818cafd02538fdd5', '33f48787d6295324995de4d2f715fb78', 1935, '伪满洲国“冀东防共自治政府”顾问（曾活动于辽西）', NULL, '原军阀，投日后在辽西（包括兴城、葫芦岛）协助日军策反地方武装，组织伪军，破坏抗日统一战线。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('49d59f7919f4543fa0bd497595fc2ebd', '6edb269a696555c193c5c25b9caf01c3', 1932, '伪满洲国锦州省保安队司令', NULL, '原东北军连长，投敌后任伪保安队司令，在兴城、葫芦岛沿海地区巡逻，截击抗日物资运输，参与“清乡”。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8cbbc38ff29d518bb20aedd4db6f130b', '7db565fbb6f85076949c7779b860a64f', 1931, '伪满洲国奉天市市长（曾影响辽西）', NULL, '原奉系官员，投日后任伪奉天市长，其伪政权政策覆盖辽宁全省，包括兴城地区，推行奴化教育和经济掠夺。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3b0a80ec589058b1a4ac104f32b7afc0', '7c51a2464caa5e18aaf829b24f6c43bc', 1931, '伪满洲国军政部总长（曾任东北边防军参谋长）', NULL, '原东北军高级将领，九一八后投敌，参与策划对辽宁西部抗日义勇军的围剿，其伪军部队曾在兴城、绥中作战。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a1267768de7951ef87278f57b114be0b', '58e6d43c943f58a9a8100d50bf928499', 1932, '伪满洲国锦州省兴城县警务科长', NULL, '投日后任兴城伪警务科长，直接指挥伪警察抓捕抗日群众，刑讯逼供，协助日军建立“爱护村”监控体系。', '辽宁葫芦岛_兴城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ef584e6662dc547d8e18931075caa8a8', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪满洲国热河省省长兼第五军管区司令', NULL, '原东北军将领，1933年投敌，任伪热河省省长，参与镇压抗日武装，协助日军统治建昌、凌源等地区，推行殖民政策。', '辽宁葫芦岛_建昌');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('34ea4414e7e3558580988c3ca07714fe', '181a098fc1fb5ed5a72da41548f64fed', 1934, '伪满洲国热河省警务厅厅长', NULL, '原东北军军官，投日后负责热河省（含建昌）警务，多次组织清乡，抓捕抗日志士，配合日军“讨伐”活动。', '辽宁葫芦岛_建昌');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d4374c24311b501b8859d49683f71e5f', '3c0cec769a465f2da5d9587d32cf51f4', 1933, '伪建昌县县长', NULL, '伪满初期任建昌县县长，推行保甲制度，强征劳工，为日军提供粮食和情报，镇压当地抗日民众。', '辽宁葫芦岛_建昌');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8219afd976c15e3e906409791b3126d7', 'be3ade6fd67853b8ba2a3a9d206346fe', 1935, '伪建昌县警察署署长', NULL, '长期担任建昌伪警察头目，直接参与抓捕抗日地下工作者，破坏抗日组织，多次带队“扫荡”农村抗日据点。', '辽宁葫芦岛_建昌');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0d080fdef7e15a5da0d24a1ee8d5b99d', 'f5a772d6aa0a5576852bb4bc7015d992', 1938, '伪建昌县协和会会长', NULL, '负责建昌地区协和会宣传，推行奴化教育，组织“勤劳奉仕”，强迫民众为日军修筑工事，搜集抗日情报。', '辽宁葫芦岛_建昌');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2c3aa65c2fa35b33b274359abb29fecd', '1aadec610c17599bb555d2d02824acf3', 1936, '伪热河省建昌县保安队队长', NULL, '率领伪保安队配合日军多次进攻建昌周边的抗日游击队，杀害抗日军民，烧毁村庄，罪行累累。', '辽宁葫芦岛_建昌');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fcd73fce416a506f945131db348adee6', 'a4b6b520415e5c858408bae9e7e4f97d', 1933, '伪满洲国热河省顾问（名义）', NULL, '虽为军阀投机者，但在热河期间与日军合作，默许部下参与镇压建昌地区抗日活动，提供情报和物资支持。', '辽宁葫芦岛_建昌');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('507583017d945ba0ba94a60f249e0acd', '5dc435eefa0b5af4941c63fafe2dcd4d', 1937, '伪建昌县司法科科长', NULL, '主持伪司法审判，以“反满抗日”罪名判处多名爱国人士死刑或长期监禁，协助日伪维持殖民秩序。', '辽宁葫芦岛_建昌');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8ac755aec2145e24af9e907d0a13626f', '44a56b7e5dd0548f9a90e01ab4fb636a', 1939, '伪建昌县税务局局长', NULL, '负责为日伪征收高额税赋，强征农民粮食，导致建昌地区民生凋敝，间接支持日军战争经济。', '辽宁葫芦岛_建昌');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8367fd81eae050469eda7541874f74af', 'fde502a7b6095a29a49c6c8ec56ef3b3', 1934, '伪热河省建昌县教育督学', NULL, '推行日本奴化教育，强制学校教授日语，删除中国历史内容，灌输“日满亲善”思想，毒害青少年。', '辽宁葫芦岛_建昌');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bd6fc1aa8f605385ad64f258e23a7e36', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满洲国热河省省长、伪军将领', NULL, '原东北军将领，九一八后投敌，任伪热河省省长，参与镇压抗日义勇军，在绥中、朝阳一带协助日军清剿抗日力量。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('52e1d279ea185a72bff498c8a4bc86b9', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满洲国奉天省省长、伪第一军管区司令', NULL, '原东北军旅长，叛国投日，任伪奉天省省长，管辖包括绥中在内的辽西地区，推行日伪殖民政策，镇压抗日活动。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c0928ee4ca3d5cba96a995738e94a520', '1ea6405224d35b439d5a62eb23dca975', 1937, '伪满洲国锦州省省长', NULL, '原东北军军官，投敌后任伪锦州省省长，绥中县属其管辖，积极推行“治安肃正”，配合日军围剿八路军冀热辽根据地。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d1b311e072935a4d8885b55d07f43bbc', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满洲国立法院院长、伪奉天市长', NULL, '汉奸政客，曾任伪奉天市长，参与策划辽宁地区日伪政权建设，对绥中等地实施奴化统治。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('193600d575dc51f0bcb2798bb508fba2', 'af224963fb455c99a96bee0aadf29f89', 1938, '伪满洲国锦州省警务厅长', NULL, '在锦州省（含绥中）主持伪警察机构，抓捕抗日志士，协助日军“讨伐”辽西抗日武装。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('29a39cacfc0b5324bee9e5df3330f5f2', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满洲国绥中县县长', NULL, '绥中本地汉奸，投日后任伪县长，强征民夫修建日军工事，镇压当地抗日民众。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cd373446e7ed5eb8966006432f8e88be', 'c8802c2d7c1f574987b6e310d8e9e5dd', 1933, '伪满洲国绥中县警务科长', NULL, '在绥中地区组织伪警察队，多次参与围剿抗日义勇军和八路军游击队，残害百姓。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('db4c4460dc7a508f99856c7998c8bd7f', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满洲国国务总理大臣', NULL, '原奉系军阀，全面投日，作为伪满最高行政首脑，其政策覆盖辽宁全省包括绥中，支持日军侵略。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('44e566b87d185031af9148f6aab23050', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满洲国参议府议长、伪奉天省长', NULL, '原辽宁省政府主席，九一八后投降，任伪奉天省长，对辽西绥中地区推行日伪法令。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d22c8b29d49b594f8112744afd9a709e', '2300e528128d54c19855a4669664572a', 1931, '伪满洲国财政部总长、伪宫内府大臣', NULL, '满清皇族，投日卖国，参与伪满政权建设，间接影响辽宁各地包括绥中的殖民统治。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('05b9b99d759455efaab8120a39334a11', '58e6d43c943f58a9a8100d50bf928499', 1938, '伪满洲国锦州省协和会会长', NULL, '在锦州省（含绥中）组织协和会，进行奴化宣传，搜集抗日情报，协助日军“清乡”。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('611534d835f95fd4ba3fed1518610f17', '1c5a7c0239a3585ba753fb5dd8066643', 1939, '伪满洲国绥中县协和会分会长', NULL, '绥中本地汉奸，负责协和会分会，煽动民众拥护伪满，告密抗日分子。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6491da284aed5c9295935f0a96a6f718', '2afacc26d5e95d5f89e96f3404f7e387', 1935, '伪满洲国绥中县保安队队长', NULL, '率保安队配合日军扫荡绥中西部山区，杀害抗日军民。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('32778961fca454609f0a8e4559ab916d', '1cf24e0dd2285d7b95a248b021456e1c', 1937, '伪满洲国锦州省教育厅长', NULL, '在锦州省（含绥中）推行奴化教育，篡改历史，强迫学生学日语。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6a49018151cb5e77ac5f0541071bb9fd', '2a816e97326c5210bdec3a2c3af8c214', 1933, '伪满洲国顾问（名义）', NULL, '虽未任实职，但公开支持伪满，其旧部在辽宁绥中地区协助日军维持秩序。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('52fc08b1b23c557dae8006b5322690ea', 'd7eca4cf356953a9bd843f9ae77031f1', 1932, '伪满洲国军政部总长（短暂投敌后反正）', NULL, '一度投日任伪职，影响绥中地区部分旧部附逆，后反正抗日，但前期行为已构成汉奸事实。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('478054ce839e513f870d5923e66d3b38', '8f60ed6bf0f85a62a7840ff91b875b4f', 1932, '伪满洲国经济部大臣', NULL, '参与伪满经济掠夺，在辽宁绥中地区强征粮食资源供给日军。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0a494ea1532351a3aeb3b4c1077b9344', '2b437180a5505d89afed6a8146c9383e', 1932, '伪满洲国交通部大臣', NULL, '负责伪满交通，在绥中地区修建军用公路和铁路，便利日军运输。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('aac98c38f2545781866b66ebf3c89cb8', '581b3709952c5c81bc3860d3c62dff90', 1938, '伪满洲国锦州省高等法院院长', NULL, '在锦州省（含绥中）审判抗日人士，判处大量爱国者死刑或监禁。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b6fad02e69cc540faa806c153d47eae0', 'df85b9e8c1b05cedba1173db2a702e1b', 1940, '伪满洲国绥中县副县长', NULL, '协助日籍副县长管理绥中，强征劳工，实施粮食配给制，导致民众饥荒。', '辽宁葫芦岛_绥中');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9297e189847f53c2832a2adfe039672f', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长兼第五军管区司令', NULL, '原东北军将领，九一八后投敌，任伪满要职，参与镇压辽西抗日义勇军，在连山一带协助日军清剿抗日武装。', '辽宁葫芦岛_连山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('341942fcf16950148f471a3e5ea476d7', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长、奉天市长', NULL, '原奉系官僚，九一八后投日，曾任伪奉天市长，参与建立伪满政权，其势力范围涉及锦州、葫芦岛地区，协助日军推行殖民统治。', '辽宁葫芦岛_连山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fe9fcc60096554a1a51232eae740227e', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满治安部大臣、奉天警备司令', NULL, '原东北军旅长，叛变投敌，在辽西地区（含连山）组织伪军，多次围剿抗日义勇军，屠杀抗日志士。', '辽宁葫芦岛_连山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0fd33926987857e9831b37c4fa29f734', '1ea6405224d35b439d5a62eb23dca975', 1934, '伪满锦州省省长', NULL, '原地方豪强，投日后任伪锦州省省长，管辖范围包括葫芦岛、连山地区，推行日伪“治安肃正”，强征劳工，镇压抗日活动。', '辽宁葫芦岛_连山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8503efd43d3c5aeb89c1ae3ae3b28283', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满锦州省警务厅长', NULL, '原警察头目，投日后负责锦州及连山地区警务，协助日军建立保甲制度，抓捕抗日地下人员，制造多起血案。', '辽宁葫芦岛_连山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1b7cda2f1ad25b009db9166292efa953', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满国务总理大臣', NULL, '原奉系军阀，九一八后投敌，虽为伪满中央高官，但其势力及政策影响辽宁全境，包括葫芦岛连山地区，支持日军“讨伐”抗日力量。', '辽宁葫芦岛_连山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('811116ab47bb572ca5bf1445cd2cc072', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满参议府议长、奉天省省长', NULL, '原奉天省主席，被俘后变节，任伪奉天省长期间，管辖辽西部分地区，配合日军在连山一带推行“归屯并户”，切断义勇军补给。', '辽宁葫芦岛_连山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('46076c7765ed5f01a4f9cd6c8d7ce306', '58e6d43c943f58a9a8100d50bf928499', 1931, '伪满锦州地区维持会会长', NULL, '地方士绅，日军占领锦州后出任维持会长，在连山地区组织伪政权，为日军提供粮草和情报，协助镇压抗日义勇军。', '辽宁葫芦岛_连山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a07ce330f82a500e889d814224a58970', '7ee6b737ce1d55a9866b5156643815fa', 1933, '伪满热河省警备军司令', NULL, '土匪出身，投日后任伪军头目，活动于辽西及热河交界，多次率部进攻连山一带的抗日游击队，烧杀抢掠。', '辽宁葫芦岛_连山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8a331a86789157629311b3e0a6578cb8', '1cf24e0dd2285d7b95a248b021456e1c', 1932, '伪满连山警察署署长', NULL, '原地方警察，投日后任连山地区伪警察署长，直接执行日伪“治安肃正”，逮捕、刑讯抗日嫌疑人员，参与“大检举”行动。', '辽宁葫芦岛_连山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('166cbd1d8b1d5c4aa5ea1573c38e2766', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满奉天省省长、伪满治安部大臣', NULL, '九一八事变后投靠日本，任伪奉天省省长，镇压抗日力量，推行殖民统治。', '辽宁辽阳');
