INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e870b142f7dc57b3985e105c4f1bedd2', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满洲国国务总理大臣', NULL, '原奉系军阀，九一八后投日，曾任伪奉天省长，后升任伪满国务总理，全面协助日本统治东北。', '辽宁辽阳_宏伟');
