INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('207d500c491756aba2c7415830997c6a', '1c5a7c0239a3585ba753fb5dd8066643', 1931, '伪辽阳县维持会会长', NULL, '辽阳当地士绅，日军占领辽阳后组织维持会，协助日军维持秩序，征收粮饷。', '辽宁辽阳_宏伟');
