INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1dfb9c59392c5b5c9d097a6ac61e8988', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满洲国热河省省长（曾驻辽阳一带）', NULL, '原洮辽镇守使，九一八后投敌，多次率伪军配合日军在辽宁东部（含辽阳、弓长岭山区）围剿抗日义勇军，烧杀抢掠。', '辽宁辽阳_弓长岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f2d2c2b0d81a5890a962a4b8ab127297', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满洲国奉天省辽阳县县长', NULL, '投日后任辽阳县伪县长，推行保甲制度，强征劳工，为日军在弓长岭铁矿提供劳力和物资，镇压当地抗日活动。', '辽宁辽阳_弓长岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c733832130fc54d59dfde04061cdd770', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满洲国立法院院长（原籍辽宁，活动涉及辽阳）', NULL, '原奉系法律人士，投日后任伪立法院院长，参与制定伪满洲国法律，为日本殖民统治提供法理依据，其家族在辽阳有产业并协助日伪征粮。', '辽宁辽阳_弓长岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('26dcdc85ef9c550bbad0a4f9b148c97b', '318089c2a3375e67b7c33f0820381332', 1937, '伪满洲国奉天省省长（后期）', NULL, '继于芷山后任伪奉天省长，管辖辽阳、弓长岭地区，推行“粮谷出荷”政策，强征农民粮食，支持日本对弓长岭铁矿的掠夺。', '辽宁辽阳_弓长岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9b06db15227d5677ae3e6b015e736a5c', 'ed63d30af50b59dd817d7f50f2b58ea9', 1933, '伪满洲国辽阳地区警察署署长', NULL, '在辽阳、弓长岭一带任伪警察署长，多次带队抓捕抗日地下党员和义勇军家属，刑讯逼供，协助日军建立“无人区”。', '辽宁辽阳_弓长岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bafc4f2712a0559db26f12f32f963340', '58e6d43c943f58a9a8100d50bf928499', 1932, '伪满洲国奉天省警务厅特务科科长', NULL, '负责辽阳、弓长岭地区特务工作，发展汉奸密探，破坏抗日组织，曾参与逮捕多名抗日志士并移交日军处决。', '辽宁辽阳_弓长岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3809e95678a650c58e83909ae2db4198', '0af6ba7053d65d28a6a658e260fef4aa', 1931, '伪满洲国辽阳县商会会长', NULL, '投靠日伪，组织商会为日军筹集军费，强迫商户“献金”，并协助日军在弓长岭矿区征用民夫，从中牟利。', '辽宁辽阳_弓长岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0451f593bfcc5700a05176313e39a6e4', '55d5c28516215af6bb912b6e514aad47', 1938, '伪满洲国弓长岭铁矿矿警队队长', NULL, '任弓长岭铁矿矿警队长，残酷镇压矿工反抗，克扣工资，殴打致死多名矿工，并协助日军封锁矿区消息。', '辽宁辽阳_弓长岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3ae3a6e431645b55bb894319cd4f04f4', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八后投敌，曾任伪满热河省省长，参与镇压抗日义勇军，后任伪满军政部大臣，协助日军统治辽宁地区。', '辽宁辽阳_文圣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('622fd6e4bd885e5d8d0638c63e4a607c', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满奉天省省长、伪满治安部大臣', NULL, '原东北军旅长，九一八后投降日军，任伪满奉天省（含辽阳地区）省长，推行殖民政策，镇压抗日力量，后升任伪满治安部大臣。', '辽宁辽阳_文圣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('32eaae469fc95079be85e48a99c05e97', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满辽阳地区警务处长', NULL, '在辽阳、文圣一带担任伪警务要职，协助日军搜捕抗日志士，破坏地下抗日组织，参与“治安肃正”行动。', '辽宁辽阳_文圣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e99bb65463cc5f779e89b970eb1f0703', 'f13fea3281b35a0ea71eb3863d7d53f7', 1933, '伪满辽阳县县长', NULL, '任伪辽阳县县长期间，强制推行“保甲制度”，强征劳工，为日军提供物资，并参与镇压辽阳地区抗日武装。', '辽宁辽阳_文圣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6534a8d6606a54f9bf9dafbc2fa2297e', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长、奉天市市长', NULL, '原奉系法律人士，九一八后投敌，曾任伪奉天市市长（管辖辽阳部分区域），协助日本建立伪政权，后任伪满立法院院长，参与制定殖民法律。', '辽宁辽阳_文圣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('35152903145e52b39b74f027a611e842', '318089c2a3375e67b7c33f0820381332', 1932, '伪满奉天省教育厅厅长', NULL, '在伪奉天省（含辽阳、文圣）推行奴化教育，强制学校教授日语，篡改历史教材，压制民族意识。', '辽宁辽阳_文圣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('186631d944995c4c85933893c3000ead', '3de6f584b1b75a69a535180aca36f08a', 1937, '伪满辽阳地区宪兵队翻译官', NULL, '为日军宪兵队充当翻译，参与审讯和刑讯抗日人士，直接导致多名地下党员牺牲。', '辽宁辽阳_文圣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('494309abce645583ad636887d0e1309d', '9cc8abde983e5319b2c80645c3730535', 1931, '伪满文圣区维持会会长', NULL, '在辽阳文圣区组织维持会，协助日军建立秩序，强征民夫修筑军事工事，并告密抗日活动。', '辽宁辽阳_文圣');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('609bff5d342e59b59fcdf851b764c7c7', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满奉天省省长、伪满治安部大臣', NULL, '九一八事变后投靠日本，历任伪奉天省省长、伪满治安部大臣，积极协助日军镇压东北抗日武装，推行殖民统治。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('782dc5a5390251b5b2f8b1b7b1673824', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满参议府议长、伪满尚书府大臣', NULL, '清末民初政客，九一八后投敌，参与策划伪满洲国成立，任伪参议府议长，为日本殖民统治出谋划策。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cf43b0f1cb9e598698e0929f0603525b', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满洲国国务总理大臣', NULL, '原奉系将领，九一八事变后公开投敌，任伪满军政部总长、国务总理大臣，全面配合日本侵略政策，镇压东北抗联。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('21149e307f7155b08133e3837948b9ce', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪奉天省省长、伪满民政部大臣', NULL, '原辽宁省政府主席，九一八后被日军软禁后投降，任伪奉天省省长，推行日伪各项反动法令。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7889222388a059559471493c82b8595b', '2300e528128d54c19855a4669664572a', 1931, '伪满财政部总长、伪宫内府大臣', NULL, '原吉林副司令长官，九一八时投降日军，参与建立伪满，任伪财政部总长，为日本掠夺东北资源效力。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bb1870af57015f6a95ed8950e67c7d59', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长', NULL, '原奉系法律顾问，九一八后投敌，参与起草伪满建国文件，任伪立法院院长，积极为伪满政权提供法律依据。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f02a9a1aae565960ae0a5f1a9f43ad9c', '318089c2a3375e67b7c33f0820381332', 1931, '伪满外交大臣、伪满驻日大使', NULL, '原奉天交涉员，投日后历任伪满外交部长、驻日大使，协助日本控制伪满外交，签订卖国条约。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3590f745bc7c5cf8afcfc82da3374d6f', '2b437180a5505d89afed6a8146c9383e', 1931, '伪满交通部大臣', NULL, '原东北交通委员会负责人，投日后任伪满交通部大臣，管理东北铁路、公路，为日军军事运输提供便利。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('90e02b589bfb5e5999ab1f923b1a5f67', '581b3709952c5c81bc3860d3c62dff90', 1931, '伪满中央银行总裁', NULL, '原东三省官银号总办，投日后任伪满中央银行总裁，发行伪币，搜刮民财，支持日本战争经济。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('328bbacd9a7c5399a355f0a26b2af097', '5e4ae6e524305885be6f33f0be6cd934', 1931, '伪满外交部大臣', NULL, '原奉系外交人员，投日后任伪满外交部大臣，负责与日本签订各种不平等条约，出卖东北主权。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b5f2d1dec52a555dbbada5c2cc6ab4f2', '9ecee7f0ddf659e583819e721e164c94', 1931, '伪满新京特别市市长', NULL, '原吉林旗人，投日后任伪满首都新京市长，协助日本建设殖民统治中心，镇压反满抗日活动。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('564c206da9575cb6b5bb948b28ef6c6a', 'df85b9e8c1b05cedba1173db2a702e1b', 1931, '伪辽阳县长', NULL, '九一八后投靠日军，任伪辽阳县县长，推行日伪保甲制度，强征劳工，镇压当地抗日民众。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1a937aa69093508aa73e20b1976705fa', 'a25f3a2741a35f898c5bd47dbee6501d', 1931, '伪辽阳警务局长', NULL, '任伪辽阳警务局长，协助日军搜捕抗日志士，破坏地下抗日组织，残害百姓。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3bbc2d34e17a582dadaa720c41886de8', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省长、伪满军政部顾问', NULL, '原洮辽镇守使，九一八后率部投敌，任伪热河省长，参与镇压辽西、辽北抗日义勇军。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7c01255dd8645794a378b7d4ea28ed15', '1ea6405224d35b439d5a62eb23dca975', 1931, '伪满奉天省警务厅长', NULL, '原奉天警察头目，投日后任伪奉天省警务厅长，指挥警察特务大肆搜捕抗日分子，制造多起惨案。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('01e03908d660577486ad1d829937e44e', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1931, '伪满监察院院长', NULL, '原奉系政客，九一八后投敌，任伪满监察院院长，为日本监督伪满官员，维护殖民秩序。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('77fbf825e5785239b75a8c9d7f1239a9', '0da09f00ee6a55878e86adbb70127338', 1931, '伪满财政部大臣', NULL, '原吉林省财政厅长，投日后任伪满财政部大臣，协助日本控制东北金融，推行经济掠夺政策。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('24a51c49c5d452f9a00e1d3a39e50caa', '8f60ed6bf0f85a62a7840ff91b875b4f', 1931, '伪满实业部大臣', NULL, '原奉天商会会长，投日后任伪满实业部大臣，为日本垄断东北工商业，出卖民族经济利益。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cb1148e6deed5f358e9b5a7a81f20dca', 'd7eca4cf356953a9bd843f9ae77031f1', 1932, '伪满黑龙江省长（短暂投敌后反正）', NULL, '原黑龙江抗日将领，1932年一度投日任伪黑龙江省长，但不久反正抗日，故其汉奸身份短暂且存在争议。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1c207634808d51a9a8ebd4f6e6ae5dc9', '8837a9f88314597a8d025f21eba891b4', 1931, '伪辽阳地方维持会会长', NULL, '九一八后组织辽阳地方维持会，协助日军维持秩序，征收捐税，为日军提供物资。', '辽宁辽阳_灯塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('21f8e4ac77c0558dae257a8e1b51806f', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1931, '伪满奉天省省长、汉奸', NULL, '九一八事变后投靠日本，任伪奉天省省长，协助日军维持殖民统治，镇压抗日活动。', '辽宁辽阳_白塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2c9a995ccc6350dfb95e71f93449e49e', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满参议府议长、汉奸', NULL, '曾任伪满参议府议长，积极参与伪满政权建立，为日本侵略政策服务。', '辽宁辽阳_白塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('423fe996353053c7afa3c6aef81abeb6', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满国务总理大臣、汉奸', NULL, '原奉系将领，后投敌任伪满国务总理，全面配合日本对东北的殖民统治。', '辽宁辽阳_白塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8714a4ad5d6e5f3f8e2694e957ef731a', 'ba311422856554c7ad7f3f75d09c3d78', 1932, '伪满奉天省省长、汉奸', NULL, '继于冲汉后任伪奉天省省长，推行日伪政策，镇压抗日力量。', '辽宁辽阳_白塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7da20f43adb85863a447c8ce9a52ef9b', '1c5a7c0239a3585ba753fb5dd8066643', 1931, '伪辽阳县维持会会长（注：其活动主要在辽阳地区）', NULL, '九一八后组织辽阳地方维持会，协助日军维持秩序，征收捐税供日军使用。', '辽宁辽阳_白塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0d0460ffcc235bc1b3b1f71ffc79eb42', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪辽阳县长、汉奸', NULL, '任伪辽阳县长期间，强征民夫修建日军工事，搜刮粮食资敌。', '辽宁辽阳_白塔');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('18c3568f719e5a86b23be4a19d136c31', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满立法院院长、汉奸', NULL, '参与伪满立法，为日本殖民统治提供法律依据，曾活动于辽阳一带。', '辽宁辽阳_白塔');
