INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('01dfc2980be85dd1896de56c441b2a7d', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满洲国立法院院长（曾任奉天市市长）', NULL, '原奉系人物，九一八后投靠日本，在铁岭地区活动，参与建立伪满政权，推行奴化教育，镇压反满抗日人士。', '辽宁铁岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2625bb2bb46354b69b583b33b23b943a', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满第一军管区司令（驻奉天）', NULL, '原东北军旅长，叛变后任伪满军职，在铁岭、开原等地多次率伪军“讨伐”抗日义勇军和抗联，杀害无辜百姓。', '辽宁铁岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cc12332a36025c749731b87e88281e25', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满奉天省警务厅厅长', NULL, '在铁岭地区组织伪警察，配合日军进行“治安肃正”，逮捕抗日地下工作者，实施“归屯并户”政策。', '辽宁铁岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4ee439dfa4565150bc3e394e4f134c16', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满铁岭县县长', NULL, '任伪铁岭县长期间，强征民夫修建日军工事，推行保甲制度，协助日军掠夺粮食资源，镇压抗日群众。', '辽宁铁岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7881ea819b105394b2ad9be8b747802a', '3de6f584b1b75a69a535180aca36f08a', 1933, '伪满昌图县县长', NULL, '在昌图（今属铁岭市）任伪职，积极为日军提供情报，组织汉奸武装“自卫团”，参与围剿抗联杨靖宇部。', '辽宁铁岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('55762c7cf4c1552697024682de3de779', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满洲国国务总理大臣', NULL, '原奉系军阀，后投日，虽主要活动于新京，但曾多次到铁岭地区视察“治安”，推动“日满亲善”和殖民统治。', '辽宁铁岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f9583209f9ce502b8b5ac4a9430248f4', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满奉天省省长（后任参议府议长）', NULL, '原辽宁省政府主席，投敌后管辖铁岭地区，推行“粮谷出荷”政策，导致当地百姓饥荒，并协助日军清剿抗联。', '辽宁铁岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5c28a4c99a0e58a5aeb42e70e0caf04e', '58e6d43c943f58a9a8100d50bf928499', 1932, '伪满铁岭地区警务总署署长', NULL, '在铁岭、开原、西丰等地建立特务网络，抓捕抗日志士，严刑逼供，制造多起惨案。', '辽宁铁岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8a175a9754175a9db8a4461e2e32a8fb', '47ca9628a9295f95b7a6f031aa878519', 1932, '伪满协和会铁岭支部长', NULL, '利用协和会组织在铁岭宣传“王道乐土”，强迫民众参加“日满亲善”活动，检举抗日分子。', '辽宁铁岭');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('be5648f539b45b169d407db5f17046db', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满第七军管区司令', NULL, '原东北军将领，1931年九一八事变后投敌，在辽宁西部及铁岭、开原一带协助日军镇压抗日武装，后任伪满热河省省长，积极推行日伪殖民政策。', '辽宁铁岭_开原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('22ae3a9085ea598f82ef9aa93a3abb3e', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满奉天省省长、伪满治安部大臣', NULL, '原东北军旅长，1931年投敌，在辽宁地区（包括铁岭、开原）组织伪军，配合日军“讨伐”抗日义勇军，后任伪满奉天省省长，残酷统治辽宁人民。', '辽宁铁岭_开原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d017ba86e5e154f2bb6c017a9b00274c', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长、伪满奉天市市长', NULL, '原奉系政客，九一八后投靠日本，曾任伪奉天市市长，在辽宁各地（含铁岭、开原）推行奴化教育，协助日军建立伪政权。', '辽宁铁岭_开原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fad08e58409d588fa003eaebb5800361', '1c5a7c0239a3585ba753fb5dd8066643', 1932, '伪满铁岭县县长', NULL, '原铁岭地方士绅，伪满成立后出任铁岭县县长，为日军征粮派夫，镇压当地抗日活动，强推“保甲连坐”制度。', '辽宁铁岭_开原');
