INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('48ea126f0ad153569494d000afa68558', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满国务总理大臣', NULL, '原奉系将领，九一八后投敌，虽主要活动于伪满中央，但其势力范围覆盖辽宁全省，包括铁岭、开原，支持日军对当地抗日力量的镇压。', '辽宁铁岭_开原');
