INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a6aee745666b527c8e340df2ffa9d126', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满铁岭县警察署署长', NULL, '原铁岭县警察，投日后任伪警察署长，直接指挥抓捕抗日地下人员，多次参与“讨伐”行动，民愤极大。', '辽宁铁岭_开原');
