INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5a698b65a7c95378b993b05f8a5b3bf4', '62a4d32628c35cb08f36429635b022ed', 1932, '伪满铁岭县教育局长', NULL, '原铁岭县教育界人士，投日后任伪教育局长，强制推行日语教育，篡改历史教材，毒化青少年思想。', '辽宁铁岭_开原');
