INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ee5c6b3d86fc505cae0623cbe69679b3', 'df85b9e8c1b05cedba1173db2a702e1b', 1933, '伪满开原县法院院长', NULL, '原开原县司法人员，投日后任伪法院院长，以“反满抗日”罪名判处多人死刑，为虎作伥。', '辽宁铁岭_开原');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0ff2691ea5d4576bb74c0ed05feb6294', 'a25f3a2741a35f898c5bd47dbee6501d', 1936, '伪满铁岭县协和会事务长', NULL, '原铁岭县商人，投日后任协和会事务长，组织“青少年团”，灌输军国主义思想，协助日军征兵。', '辽宁铁岭_开原');
