INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9fd073ba66105a0e826c9dce1a7b1e3f', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满第一军管区司令官、伪满治安部大臣', NULL, '原东北军旅长，1932年投敌，任伪满第一军管区司令官，在辽宁、铁岭、昌图一带围剿抗日义勇军，后升任伪满治安部大臣。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9c7f7cd846b45e8ab0bc4d2cce5f8427', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满奉天省警察厅厅长', NULL, '原奉系警察头目，投日后任伪奉天省警察厅厅长，在沈阳及铁岭、昌图地区大肆搜捕抗日分子，镇压民众反抗。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('86ce21ea0c2351679ef25a5bd5af30e7', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满奉天市市长、伪满立法院院长', NULL, '原奉系政客，九一八后投敌，任伪奉天市市长，协助日军建立殖民统治，后任伪满立法院院长，参与制定奴化政策。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('17836200926f52d89ea65433c359da3e', '318089c2a3375e67b7c33f0820381332', 1937, '伪满奉天省省长', NULL, '原东北军文职官员，投日后历任伪满要职，任伪奉天省省长期间，推行日伪“治安肃正”，在铁岭、昌图等地强征劳工、掠夺粮食。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ea1dc4e56e285501a86e83bf3bebba96', '58e6d43c943f58a9a8100d50bf928499', 1932, '伪满铁岭县县长', NULL, '铁岭本地士绅，投日后任伪铁岭县县长，协助日军建立保甲制度，强征民夫修筑公路和军事工事，镇压当地抗日活动。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('66b60f6f26cc55a39c74d147139507d5', '55d5c28516215af6bb912b6e514aad47', 1932, '伪满昌图县县长', NULL, '原昌图地方官员，投日后任伪昌图县县长，推行日伪“归屯并户”政策，制造无人区，配合日军清剿抗日武装。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('548362af15fe57618a2419e3c1597374', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满国务总理大臣', NULL, '原奉系军阀，九一八后投敌，任伪满军政部总长、国务总理大臣，是伪满最高汉奸之一，其势力范围覆盖辽宁全省，包括铁岭、昌图地区。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6877df03505654c7b057cf196743cd2e', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满奉天省省长、伪满参议府议长', NULL, '原辽宁省政府主席，九一八被俘后投敌，任伪奉天省省长，在铁岭、昌图等地推行日伪殖民政策，后任伪满参议府议长。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3acaea2c733f543181dfc5706c3e4254', '2300e528128d54c19855a4669664572a', 1931, '伪满财政部总长、伪满宫内府大臣', NULL, '原吉林副司令长官，投日后成为伪满核心汉奸，虽主要活动在吉林，但参与策划对辽宁地区抗日力量的围剿，其影响涉及铁岭、昌图。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cd7a6f261bc8504cb2b4c3bb475d60a3', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1931, '伪满监察院院长', NULL, '原奉系外交官，投日后任伪满监察院院长，曾参与“日满议定书”签订，协助日本控制辽宁经济，对铁岭、昌图地区资源掠夺负有责任。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('df23bc77878c51209810603a92a36fb4', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满奉天省省长（早期）', NULL, '原奉天省议会议长，九一八后投敌，任伪奉天省省长，在任期间组织地方伪政权，镇压铁岭、昌图一带的义勇军。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8c935098be09500ca74f902ad7764180', '2b437180a5505d89afed6a8146c9383e', 1931, '伪满交通部大臣', NULL, '原东北交通委员会官员，投日后任伪满交通部大臣，负责修建铁路和公路，为日军军事运输服务，其工程涉及铁岭、昌图地区。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('83212e8d40eb532bbab53ecbad573b56', '8f60ed6bf0f85a62a7840ff91b875b4f', 1931, '伪满经济部大臣', NULL, '原奉天商会会长，投日后任伪满经济部大臣，在辽宁推行经济统制，强征铁岭、昌图粮食和矿产，支持日本侵华战争。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e24857f6dae4502187333badbf430f79', '0da09f00ee6a55878e86adbb70127338', 1931, '伪满民生部大臣', NULL, '原吉林教育厅长，投日后任伪满民生部大臣，推行奴化教育，在铁岭、昌图等地设立日语学校，强制灌输“王道乐土”思想。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('705aaa15654f5e3bb9a023119a7c2eed', '9d9a0add0c285a94840c9d63f7e0641c', 1932, '伪满铁岭地区警务处处长', NULL, '铁岭本地警察头目，投日后任伪铁岭警务处长，组织伪警察队，多次参与“讨伐”抗日游击队，杀害无辜百姓。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8422b04725e752eea825acfc6e985e61', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满昌图地区保安队队长', NULL, '昌图地方恶霸，投日后组织伪保安队，配合日军扫荡，在昌图北部制造多起惨案，强抓壮丁补充伪军。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('24d95d3256795537a105636e34b42d37', '8837a9f88314597a8d025f21eba891b4', 1932, '伪满奉天省教育厅厅长', NULL, '原奉天教育界人士，投日后任伪奉天省教育厅长，在铁岭、昌图推行殖民教育，篡改历史教材，禁止中国传统文化传播。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3d97987d50595ef8b59b05ecd3db8299', 'e6b8425fe2a75f1390d3cc8927ce0ae7', 1933, '伪满铁岭县警察署署长', NULL, '铁岭县伪警察头目，积极执行日伪“治安肃正”计划，在铁岭城乡设立检查站，逮捕抗日地下工作者。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c9dd0c7bffae544489368d5dc96afb14', '23d2a99a25bc56ccb75b9b643dc2ee4a', 1934, '伪满昌图县协和会会长', NULL, '昌图县协和会头目，协助日军进行思想宣传，组织“勤劳奉仕”运动，强迫当地农民为日军服劳役。', '辽宁铁岭_昌图');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('39004b44d3aa538a824615a968867fe7', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满铁岭县警务科警尉', NULL, '在清河地区协助日军‘讨伐’抗日武装，抓捕抗日军民并刑讯逼供，参与制造多起惨案。', '辽宁铁岭_清河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4599ec89346559d6b4c458ebb034bfc0', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪满热河省省长（原籍铁岭清河）', NULL, '早年投靠日军，后任伪满热河省省长，在清河地区有田产，曾协助日军清乡，镇压抗日活动。', '辽宁铁岭_清河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('344ba1359e4a5db19ee8981391e6519c', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满立法院院长（祖籍铁岭清河）', NULL, '虽主要活动在伪满中央，但利用其铁岭清河籍贯影响，为日军在清河地区推行‘治安肃正’出谋划策。', '辽宁铁岭_清河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('14cd4526d5875111bfe5674d10b44a1b', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1931, '伪满监察院院长（曾任铁岭地区维持会头目）', NULL, '九一八事变后，在铁岭清河一带组织地方维持会，为日军提供粮秣和情报，协助建立伪政权。', '辽宁铁岭_清河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f3ad8b5fddf554c8997fd0c3d2f81e92', 'f13fea3281b35a0ea71eb3863d7d53f7', 1934, '伪满铁岭县清河城子警察署署长', NULL, '在清河城子一带强征劳工，抓捕抗日嫌疑犯，并直接参与日军对清河沟游击队的围剿行动。', '辽宁铁岭_清河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a4671b18b8385144bb86a0f37c81b9d3', '55d5c28516215af6bb912b6e514aad47', 1937, '伪满清河地区自卫团团长', NULL, '组织汉奸自卫团，配合日军在清河沿岸设卡盘查，多次袭击抗联小分队，杀害抗日群众。', '辽宁铁岭_清河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('836545f503ea55ae8d8cdfefcd436189', '01580a2207fc546097fc33e00c2593b9', 1938, '伪满铁岭县清河区区长', NULL, '推行伪满‘保甲连坐’制度，强迫村民报告抗日分子行踪，并贪污勒索百姓，为日军征收军粮。', '辽宁铁岭_清河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('82bdf01c760a56c39cbb9def6aa3375b', '652796264c295ca4bfd6582b3f226d42', 1940, '伪满清河地区特务情报员', NULL, '化装成商人刺探抗联情报，多次向日军告密导致清河地区地下交通站被破坏，多名抗日志士被捕。', '辽宁铁岭_清河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('38d3b26667a357dea2965c118d6293c8', '9e1735775df351d99a4b6206468b05fb', 1941, '伪满铁岭县清河警察署特务股长', NULL, '专门负责‘思想犯’侦缉，在清河地区逮捕进步教师和学生，酷刑审讯后移送抚顺监狱。', '辽宁铁岭_清河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5b00482fa2525cf38469341f68df5c0d', '09d09f9157935f86a9e0faa8d84f6243', 1935, '伪满清河地区协和会分会会长', NULL, '利用协和会组织宣传‘日满亲善’，诱骗青年参加伪军，并协助日军在清河地区进行‘归屯并户’。', '辽宁铁岭_清河');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('788ccf5f421154038ea0bf1e41f6d49b', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满西丰县县长', NULL, '任伪满西丰县县长期间，积极推行日伪殖民政策，强征劳工，镇压抗日活动，协助日军搜捕抗日志士。', '辽宁铁岭_西丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('78ffb3e1b75c5d4285433cc9eb9a1092', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪满热河省省长（原籍西丰）', NULL, '原东北军将领，后投敌叛国，任伪满热河省省长，配合日军“围剿”抗日武装，在热河及辽北地区残害抗日军民。', '辽宁铁岭_西丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b0fa92cdce1451afa8683edb9ee14b94', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满立法院院长（原籍铁岭）', NULL, '铁岭籍汉奸，积极参与伪满政权建设，为日本殖民统治出谋划策，推动“日满亲善”宣传，协助镇压东北抗日联军。', '辽宁铁岭_西丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('38d4f89ddb865b6182d3016983ce9ddc', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1932, '伪满监察院院长（原籍铁岭）', NULL, '铁岭籍汉奸，曾任伪满监察院院长，积极效忠日本关东军，参与制定殖民政策，协助日军掠夺东北资源。', '辽宁铁岭_西丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5033ce60c20c5d2b90eb06a8b7d0efc0', 'a2f31a9be59d5a89b0426ae789e7bef9', 1932, '伪满参议府议长（原籍辽阳，活动于铁岭）', NULL, '在铁岭地区活动，任伪满参议府议长，积极推动“满洲国”建国，为日本侵略者张目，参与镇压抗日力量。', '辽宁铁岭_西丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('757bfaae152e59c8bfac1962061616ec', 'c442851d3aae5b0897583c8dee016efa', 1933, '伪满热河省警备司令（原籍西丰）', NULL, '西丰籍汉奸，原奉系军阀，投日后任伪满热河省警备司令，率伪军配合日军“扫荡”抗日根据地，屠杀抗日群众。', '辽宁铁岭_西丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('63ee2d80acc954edb7704d1131397454', '9ecee7f0ddf659e583819e721e164c94', 1932, '伪满铁道守备队司令（活动于铁岭）', NULL, '在铁岭地区担任伪满铁道守备队司令，负责保护日军运输线，抓捕抗日地下工作者，破坏抗日组织。', '辽宁铁岭_西丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fa8d206dd2cb5e2ab27a13732d268022', '1c5a7c0239a3585ba753fb5dd8066643', 1932, '伪满奉天省警务厅长（原籍铁岭）', NULL, '铁岭籍汉奸，任伪满奉天省警务厅长，指挥伪警察协助日军“清乡”，在西丰、铁岭等地大肆逮捕抗日人士。', '辽宁铁岭_西丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4802d252285d52a5a92c1f31f83470cb', '581b3709952c5c81bc3860d3c62dff90', 1935, '伪满西丰县警务科科长', NULL, '任西丰县警务科科长期间，积极执行日伪“治安肃正”计划，多次带队围剿西丰境内的抗日游击队，杀害多名抗联战士。', '辽宁铁岭_西丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('718e122594d95eddbd404bbecd1aab92', 'f13fea3281b35a0ea71eb3863d7d53f7', 1937, '伪满铁岭县县长', NULL, '任铁岭县县长期间，强征农民粮食和劳工，为日军提供物资，并配合宪兵队镇压铁岭地区的抗日反满活动。', '辽宁铁岭_西丰');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9ef11eac09635221b322ae89ec7a7cf5', '1ea6405224d35b439d5a62eb23dca975', 1931, '伪满铁岭县县长', NULL, '1932年投靠日军，任伪铁岭县县长，协助日军推行“治安肃正”，镇压抗日武装，强征劳工，搜刮民财，为日军提供粮秣和情报。', '辽宁铁岭_调兵山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('20464bad53e95c8f942e6f12a9be2e9c', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长（曾驻铁岭地区）', NULL, '原奉系军阀，九一八后公开投敌，在铁岭、调兵山一带协助日军围剿抗日义勇军，后任伪热河省长，其部队参与对辽北地区的“讨伐”。', '辽宁铁岭_调兵山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('37dacdccd7fc5ac49142c5328cec12af', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满奉天省高等法院院长（涉及铁岭司法）', NULL, '汉奸法学家，参与伪满司法体系，对铁岭、调兵山地区抗日人士进行非法审判和迫害，积极为日本殖民统治提供法律依据。', '辽宁铁岭_调兵山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f00e6e1a74a85e83949f32e60b16f4ee', '802dd1e9fe095ba4a8cbdc66a100361e', 1932, '伪满第一军管区司令（辖铁岭地区）', NULL, '原东北军将领，叛变后任伪满军第一军管区司令，驻防奉天（沈阳）及铁岭一带，多次指挥伪军“讨伐”调兵山、法库等地的抗日游击队，屠杀抗日军民。', '辽宁铁岭_调兵山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0ce222ec814e5ebe8daaf6aec0e2f225', '3c0cec769a465f2da5d9587d32cf51f4', 1933, '伪满铁岭地区警察署长', NULL, '铁岭本地人，投靠日伪后任警察署长，在调兵山、晓明镇等地设立情报网，抓捕抗日地下工作者，参与“归屯并户”和“三光”政策实施。', '辽宁铁岭_调兵山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d44a45f91d695f3995705890fe45179a', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满铁岭保安队队长', NULL, '原土匪头目，被日军收编后任铁岭保安队长，在调兵山矿区镇压矿工反抗，强征民夫修筑军事工事，并配合日军扫荡周边村庄。', '辽宁铁岭_调兵山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3f926f17887854a896876f3646da3808', '55d5c28516215af6bb912b6e514aad47', 1931, '伪满调兵山维持会会长', NULL, '调兵山（时称“大明”一带）地方士绅，日军占领后主动出任维持会长，为日军筹集粮款，出卖抗日义勇军情报，导致多支小股游击队被消灭。', '辽宁铁岭_调兵山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('28a59bdad94856bc8a34ba662ea0af3e', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满国务总理大臣（曾参与铁岭地区殖民统治决策）', NULL, '作为伪满最高汉奸之一，其推行的“粮谷出荷”、“勤劳奉仕”等政策直接压榨铁岭、调兵山农民和矿工，造成大量平民死亡。', '辽宁铁岭_调兵山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('425d38dabe5254e5a574464637fdac92', '8f60ed6bf0f85a62a7840ff91b875b4f', 1937, '伪满奉天省省长（辖铁岭）', NULL, '在任期间强化铁岭地区的“保甲制度”，在调兵山一带推行“连坐”，并组织汉奸武装“自卫团”协助日军清乡，掠夺煤炭资源。', '辽宁铁岭_调兵山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d68a8860594050018e14f4170d42b126', '58e6d43c943f58a9a8100d50bf928499', 1938, '伪满铁岭县警务科科长', NULL, '铁岭县警务实际负责人，在调兵山、孤家子等地设立多个警察分驻所，亲自审讯刑讯抗日嫌疑犯，曾一次逮捕并杀害12名抗日群众。', '辽宁铁岭_调兵山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('24a4b98181c1515dabf6458964ce28c1', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八事变后投敌，曾任伪满热河省省长，协助日军镇压抗日武装，后任伪满军政部大臣，参与伪满政权军事决策。', '辽宁铁岭_银州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2b5b08825fad5618a791eff4572740d3', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满第一军管区司令官、伪满治安部大臣', NULL, '原东北军旅长，1931年率部投敌，任伪满第一军管区司令官，负责辽宁地区“讨伐”抗日义勇军，后升任伪满治安部大臣，推行殖民统治。', '辽宁铁岭_银州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0389099ad35656429144b5e1dd142d07', '1ea6405224d35b439d5a62eb23dca975', 1931, '伪满奉天省警备司令官', NULL, '原东北军营长，投敌后任伪满奉天省警备司令官，在铁岭、银州一带多次围剿抗日游击队，残害抗日军民。', '辽宁铁岭_银州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('81df2d33f55b5b8aad478b76c13fbd28', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长、伪满奉天市市长', NULL, '原奉系官员，九一八后投日，曾任伪满奉天市市长，后任伪满立法院院长，为日本殖民统治提供法律与行政支持，涉及铁岭地区伪政权建设。', '辽宁铁岭_银州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8b7adb4d2bb254aba34d22e7fc890e5c', '318089c2a3375e67b7c33f0820381332', 1931, '伪满奉天省省长', NULL, '原东北军文职官员，投敌后历任伪满奉天省省长，管辖铁岭、银州等县，推行日伪“治安肃正”政策，镇压抗日力量。', '辽宁铁岭_银州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0420ce1e9b03531f84646824cf4ee3a3', '58e6d43c943f58a9a8100d50bf928499', 1932, '伪满铁岭县县长', NULL, '原铁岭地方士绅，投日后任伪满铁岭县县长，协助日军建立保甲制度，强征劳工，搜刮粮食，迫害抗日家属。', '辽宁铁岭_银州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('adc8cb31fe1e5a7e8b27f8bf63b46d33', 'f13fea3281b35a0ea71eb3863d7d53f7', 1933, '伪满银州地区警察署署长', NULL, '原银州（今铁岭银州区）警察，投日后任伪警察署长，多次参与抓捕抗日地下工作者，严刑逼供，制造多起血案。', '辽宁铁岭_银州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d74493e66149509b825caf4522f2a305', '55d5c28516215af6bb912b6e514aad47', 1932, '伪满铁岭保安队队长', NULL, '原铁岭地方武装头目，投日后组织伪保安队，配合日军扫荡铁岭东部山区抗日根据地，烧毁村庄，杀害无辜百姓。', '辽宁铁岭_银州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3e47be3e0795541ca27f100ab9ff71da', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满国务总理大臣', NULL, '原奉系军阀，九一八后投敌，任伪满最高行政长官，虽非直接活动于铁岭银州，但其政策覆盖该地区，支持日军对辽宁的殖民统治。', '辽宁铁岭_银州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1309924fdfd1580fa185e0485684821c', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满奉天省省长（早期）', NULL, '原辽宁省主席，被日军俘虏后变节，任伪满奉天省省长，管辖铁岭地区，推行“归屯并户”，切断抗日武装与民众联系。', '辽宁铁岭_银州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('aa4f26c441c55bc1bfb3fa22163958b3', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满锦州省省长', NULL, '九一八事变后投靠日军，任伪满热河省省长，后调任伪满锦州省省长，镇压抗日力量，推行殖民统治。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('207a4653fbd95919b3d72ccde874d7d8', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长、伪满锦州省顾问', NULL, '曾任伪满立法院院长，后任锦州省顾问，协助日军在锦州地区实施奴化教育和经济掠夺。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('52b4dd83e1fd5a118438e42a4c343d95', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1931, '伪满监察院院长、伪满锦州省参议', NULL, '投靠日本后任伪满监察院院长，曾参与锦州地区伪政权建设，协助日军清剿抗日武装。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('107858a4f60d55089ae2d45f9fecd39e', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满奉天省省长、伪满锦州省高等法院院长', NULL, '曾任伪满奉天省省长，后任锦州省高等法院院长，为日军镇压抗日民众提供司法支持。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4dc59e0465c459ae88a3a1b003de1632', '1c5a7c0239a3585ba753fb5dd8066643', 1932, '伪满锦州省警务厅厅长', NULL, '任伪满锦州省警务厅厅长期间，组织警察配合日军搜捕抗日分子，实施白色恐怖。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8ad4f7c714e35557b144b270d5a0d730', 'f13fea3281b35a0ea71eb3863d7d53f7', 1933, '伪满锦州省协和会会长', NULL, '担任伪满锦州省协和会会长，推行奴化宣传，强迫民众参加反共集会。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c34ca56f5af65d6e9a81bf70b5da9bc0', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满国务总理大臣（曾兼锦州地区军事顾问）', NULL, '伪满最高汉奸之一，曾参与策划锦州地区“治安肃正”行动，屠杀抗日军民。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('15404084d1825a3dbc4c4de410923ba1', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满奉天省省长（曾管辖锦州地区）', NULL, '投日后任伪满奉天省省长，其辖区包括锦州，支持日军在锦州建立伪政权和军事据点。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4aec214ee13856109f2501399fd1c500', '2300e528128d54c19855a4669664572a', 1931, '伪满财政部总长（曾参与锦州地区伪军整编）', NULL, '伪满核心汉奸，参与组建伪满军，并协助日军在锦州地区收编土匪武装为伪军。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d1b1973693205a8e869a4012d773dfa5', 'a9c5a94bd6555f31b291ade55c77d32c', 1932, '伪满军政部总长（一度在锦州地区活动）', NULL, '早期抗日，后一度投日，任伪满军政部总长，其部队曾在锦州地区配合日军行动。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5add8dc9cf045e08967da6e6b87b4fbb', '8f60ed6bf0f85a62a7840ff91b875b4f', 1932, '伪满锦州省实业厅厅长', NULL, '任锦州省实业厅厅长期间，协助日本掠夺锦州地区矿产和粮食资源。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c9135ddcc10f5b55b1184bf3ce473d94', '58e6d43c943f58a9a8100d50bf928499', 1933, '伪满锦州省教育厅厅长', NULL, '推行奴化教育，强制学校教授日语，删除中国历史内容，迫害爱国教师。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2ba473c521e3548ebd709e5c406377b2', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满锦州地区保安队队长', NULL, '率保安队协助日军围剿锦州抗日游击队，多次制造屠杀事件。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9f56b889abe15ee7b4995c088cf2482b', '762e0b9ffb6359e2a7ffa4a6cc071aa0', 1933, '伪满锦州省宪兵队队长', NULL, '任锦州宪兵队长，严刑拷打抗日志士，参与“三光”政策实施。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8f25070c623e5b50b2e7822f5da2cd2c', '7ee6b737ce1d55a9866b5156643815fa', 1931, '伪满锦州地区土匪改编伪军头目', NULL, '原土匪头目，投日后被编为伪军，在锦州地区烧杀抢掠，破坏抗日根据地。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c6049864a2a65c6985958c73e812b23f', '49a288becde25e978fd63428c8e00545', 1934, '伪满锦州省警察署署长', NULL, '指挥警察抓捕地下党员，破坏抗日组织，协助日军进行“大检举”。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('616ff7a599825049ae8ae87da0e2d155', '0da09f00ee6a55878e86adbb70127338', 1932, '伪满锦州省民生厅厅长', NULL, '推行“粮谷出荷”政策，强征锦州农民粮食，导致大量饿殍。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0f020fb394fa5a8fb6c8e19a55c73556', '8837a9f88314597a8d025f21eba891b4', 1933, '伪满锦州省法院审判官', NULL, '以“反满抗日”罪名判处多名爱国人士死刑，充当日本司法帮凶。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fb3638612a1658a89d4e0748deaa1d5b', '0af6ba7053d65d28a6a658e260fef4aa', 1931, '伪满锦州省商会会长', NULL, '为日军筹集军饷，强迫商户捐献物资，并告发抗日商人。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1918f82262a4599abf59771f4aac3417', '85aa2fd10d9c5918aff4e588d092ec71', 1932, '伪满锦州省参事官', NULL, '参与制定锦州地区“治安维持法”，协助日军建立保甲制度。', '辽宁锦州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0c3da2a690325e1a84d69f14b4cf8323', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满洲国热河省省长、伪锦州省省长', NULL, '九一八事变后投靠日军，曾任伪热河省省长，后调任伪锦州省省长，积极推行日伪殖民政策，镇压抗日力量。', '辽宁锦州_义县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('305b75c87c325ee0bbf58748549ed1b3', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满洲国立法院院长、伪锦州省省长（短暂）', NULL, '曾任伪满洲国要职，参与筹建伪政权，后短暂担任伪锦州省省长，协助日军统治辽宁地区。', '辽宁锦州_义县');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d265a73e13795fd0a00efcfd56352562', '1c5a7c0239a3585ba753fb5dd8066643', 1932, '伪锦州省警务厅厅长', NULL, '在伪锦州省任职期间，残酷镇压抗日义勇军和地下抗日组织，协助日军进行“治安肃正”。', '辽宁锦州_义县');
