INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fc1461d957e4522aa25603d1f2e9a9e8', '55d5c28516215af6bb912b6e514aad47', 1933, '伪满阜新矿务局督办', NULL, '负责阜新煤矿生产，强迫中国矿工超负荷劳动，导致大量矿工死亡，为日军提供战略物资。', '辽宁阜新_太平');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ebf2280be341579ebb36896927d81045', '1ea6405224d35b439d5a62eb23dca975', 1933, '伪满热河省警务厅厅长（彰武县籍）', NULL, '曾任伪满热河省警务厅长，参与镇压抗日武装，协助日军推行“治安肃正”计划，在彰武、阜新一带抓捕抗日人员。', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('42c838c538735dcfa523324a01cd11a6', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪满热河省省长（曾辖阜新地区）', NULL, '原东北军将领，投日后任伪热河省省长，配合日军统治阜新、彰武地区，强征劳工开采阜新煤矿，镇压民众反抗。', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a1fb5f171fae5d75b37d97efc99ffb17', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满立法院院长（曾参与阜新地区殖民统治决策）', NULL, '伪满高层汉奸，参与制定对阜新、彰武等地的经济掠夺政策，支持日军强占煤矿资源，迫害当地百姓。', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4eb68998cfd95e3c98e93196daab2e66', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1932, '伪满中央银行总裁（阜新煤矿掠夺参与者）', NULL, '协助日本财阀控制阜新煤矿，通过金融手段榨取资源，为日军侵华战争提供资金支持。', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e3f1114c5cac5835a55a806d0966cec8', '2b437180a5505d89afed6a8146c9383e', 1932, '伪满交通部大臣（管辖阜新地区铁路运输）', NULL, '负责伪满交通体系，为日军运输阜新煤炭和军事物资，便利日军对彰武等地的军事控制。', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f11afd6a5ba95e71aed6944e55599360', '581b3709952c5c81bc3860d3c62dff90', 1934, '伪满奉天省省长（阜新、彰武曾属奉天省）', NULL, '任伪奉天省长期间，推行保甲制度，协助日军清剿抗日力量，强征阜新地区劳工。', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('167df7bf2a125d828ec9bf3c597a4abf', '58e6d43c943f58a9a8100d50bf928499', 1937, '伪满锦州省省长（彰武县曾属锦州省）', NULL, '在彰武地区推行“粮谷出荷”政策，强征粮食，配合日军“讨伐”抗日游击队。', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b7428bba86ab5d8ea574da79471a351f', '1c5a7c0239a3585ba753fb5dd8066643', 1933, '伪满阜新县县长（1933-1937）', NULL, '投靠日军后任阜新县伪县长，协助日军建立伪政权，强征民夫修建军事设施，镇压抗日活动。', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('116a1e6981365b42aa99509940d09a54', 'f13fea3281b35a0ea71eb3863d7d53f7', 1933, '伪满彰武县县长（1933-1938）', NULL, '任彰武伪县长期间，为日军提供情报，组织伪警察抓捕抗日志士，强征土地和粮食。', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('efa7e904ab7e5121b3f34567133c57da', '0da09f00ee6a55878e86adbb70127338', 1937, '伪满民生部大臣（曾管辖阜新劳工政策）', NULL, '制定伪满劳工政策，导致大量阜新、彰武农民被强征为苦工，死于煤矿和军事工程。', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('90adf1edcd295137979d642788551967', '8f60ed6bf0f85a62a7840ff91b875b4f', 1932, '伪满经济部大臣（阜新煤矿掠夺参与者）', NULL, '参与策划阜新煤矿的“统制”经营，帮助日本垄断煤炭资源，压榨中国矿工。', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('34eb90d2217657acae9ddae57e68ba04', '318089c2a3375e67b7c33f0820381332', 1932, '伪满外交部大臣（曾处理阜新地区外交事务）', NULL, '为伪满政权辩护，协助日本在阜新、彰武地区建立殖民秩序，镇压反抗。', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b025b6bd9aa451209cae587639ddadca', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满国务总理大臣（统辖阜新、彰武地区）', NULL, '伪满最高行政头目，全面配合日本对阜新、彰武的殖民统治，签发多项迫害当地民众的法令。', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5b9786df6ece5ab0af3e6cf4e89f9019', 'ba311422856554c7ad7f3f75d09c3d78', 1932, '伪满参议府议长（曾参与阜新地区政策制定）', NULL, '参与伪满高层决策，支持日军在阜新、彰武的“治安强化”运动，导致大量抗日人员被杀。', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('154d95e10deb5df7bb37df9ce275a739', '2300e528128d54c19855a4669664572a', 1932, '伪满宫内府大臣（曾参与阜新地区皇产掠夺）', NULL, '协助日本皇室和财阀侵占阜新地区土地和矿产资源，破坏当地经济。', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2aecdce2a3515396b635085d2303fc04', '9ca31194e51952dea675389daec51dc0', NULL, '无', NULL, '无', '辽宁阜新_彰武');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5b8d338721d45d1cb485b41750a5c0d8', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满洲国阜新市警察局局长', NULL, '在阜新地区积极协助日本宪兵队镇压抗日武装，抓捕抗日志士，推行“治安肃正”政策，强征劳工开采阜新煤矿，造成大量矿工死亡。', '辽宁阜新_海州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4b158423b0d252f58ab0198a395b8ff6', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪满洲国热河省省长（管辖阜新地区）', NULL, '原东北军将领，后投靠日本，任伪热河省省长期间，配合日军对阜新、海州地区进行殖民统治，强征民夫修建军事设施，镇压抗日义勇军。', '辽宁阜新_海州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c9d29c6f32db572abde6b2b078df712d', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满洲国立法院院长（曾参与阜新地区殖民政策制定）', NULL, '作为伪满高层，参与策划对阜新煤矿资源的掠夺性开采，支持日本“满炭”公司对海州矿区的控制，迫害当地矿工。', '辽宁阜新_海州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cb0ba157baf75d2f8679ca9b718710d5', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1932, '伪满洲国监察院院长（曾负责阜新地区矿务监督）', NULL, '协助日本关东军管理阜新、海州矿区，推行“以华制华”政策，组织汉奸矿警队镇压矿工反抗，克扣矿工口粮。', '辽宁阜新_海州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('eed23dab8ca952d7a1fac84e038c5f48', '2b437180a5505d89afed6a8146c9383e', 1932, '伪满洲国交通部大臣（管辖阜新铁路运输）', NULL, '负责将阜新海州煤矿的煤炭通过铁路运往日本，为日军战争机器提供资源，同时参与强制征调劳工修筑铁路，导致大量劳工死亡。', '辽宁阜新_海州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9efa8c1b41b159b58b38d2b3efd1a602', '318089c2a3375e67b7c33f0820381332', 1937, '伪满洲国经济部大臣（主管阜新矿业开发）', NULL, '积极推动日本对阜新海州露天煤矿的“重点开发”，签订掠夺性合同，压低矿工工资，造成矿区环境严重破坏和人员伤亡。', '辽宁阜新_海州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b26354ccb30a5fe080deb5fb2aecaad9', '8f60ed6bf0f85a62a7840ff91b875b4f', 1934, '伪满洲国奉天省省长（阜新地区隶属奉天省时期）', NULL, '在任期间配合日军对阜新地区进行“清乡”，组织汉奸保甲制度，强征青年为伪军，并协助日本企业霸占阜新矿区土地。', '辽宁阜新_海州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f9e5ad833db05dd4b451446815da83f3', '58e6d43c943f58a9a8100d50bf928499', 1933, '伪满洲国阜新县县长', NULL, '直接执行日本殖民政策，强征农民土地给“满炭”公司，强迫村民迁出矿区，对反抗者进行残酷镇压，多次协助日军屠杀平民。', '辽宁阜新_海州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ca65898a62045f069be026f10ae56320', 'f13fea3281b35a0ea71eb3863d7d53f7', 1935, '伪满洲国阜新市协和会会长', NULL, '宣传“日满亲善”，组织汉奸团体刺探抗日情报，协助日军抓捕地下抗日分子，并参与“勤劳奉仕”运动，强迫民众无偿劳动。', '辽宁阜新_海州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ffe045cebfdb5bd9ad15af00505510b8', '1c5a7c0239a3585ba753fb5dd8066643', 1936, '伪满洲国阜新矿务局总办（海州矿区实际管理者）', NULL, '作为日本“满炭”公司代理人，负责海州露天矿的日常管理，制定严苛劳动制度，克扣矿工工资，导致矿难频发，死亡矿工被草草掩埋。', '辽宁阜新_海州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b50756e9a452576c9ca71318750f8594', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满洲国国务总理大臣（名义上管辖阜新地区）', NULL, '作为伪满最高行政长官，签署多项出卖阜新矿产资源的法令，支持日本关东军对海州地区的军事管制，对矿区抗日活动进行镇压。', '辽宁阜新_海州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('56ef977f57ff5b209770988e8af6faf1', 'ba311422856554c7ad7f3f75d09c3d78', 1932, '伪满洲国参议府议长（曾参与阜新地区殖民规划）', NULL, '参与制定阜新地区“产业开发五年计划”，推动日本资本全面控制海州煤矿，协助日军建立矿区“无人区”，驱逐当地居民。', '辽宁阜新_海州');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('19d7e65d6b0e56288417ee369a936ae8', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满洲国奉天省省长、伪治安部大臣', NULL, '原东北军将领，九一八事变后投敌，任伪奉天省省长，协助日军镇压抗日武装，推行殖民统治。', '辽宁鞍山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('465679ea03175374a1f005fc51fe3b8a', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满洲国鞍山市长（一说为伪鞍山县长）', NULL, '在鞍山地区担任伪职，配合日军掠夺鞍山铁矿资源，强征劳工，压迫当地民众。', '辽宁鞍山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2203d013f3835b6b98c46b6181c70131', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满洲国热河省省长、伪满军事部大臣（曾活动于辽南）', NULL, '原奉系军阀，投日后在辽南一带协助日军清剿抗日义勇军，后调任伪满中央要职。', '辽宁鞍山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1e126a264a5d5bac98d84d5e06231117', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满洲国立法院院长（原籍辽宁，曾参与鞍山地区殖民统治）', NULL, '积极鼓吹“满洲独立”，参与伪满政权立法，为日本侵略提供法律依据，影响鞍山地区。', '辽宁鞍山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('80e9285933c057e7a11cdeda8ca78717', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满洲国参议府议长（辽宁籍，曾参与辽南政务）', NULL, '清末民初政客，投靠日本后任伪满高官，参与策划对辽宁地区的殖民统治。', '辽宁鞍山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('37f17253f81c5321875f25fbc49fc875', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满洲国奉天省省长（后任伪满民政部大臣）', NULL, '原奉天省主席，九一八后被俘投敌，在奉天（含鞍山地区）推行日伪政策，镇压抗日活动。', '辽宁鞍山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cc311ba4d69c562f89ed57655cbe511e', '2300e528128d54c19855a4669664572a', 1931, '伪满洲国财政部大臣、宫内府大臣（曾涉足辽南）', NULL, '清室后裔，投日后参与伪满建国，协助日本控制辽宁经济资源，包括鞍山铁矿。', '辽宁鞍山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d3d04f16dc825261842f27493a22ca63', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1932, '伪满洲国监察院院长（辽宁籍，曾参与鞍山地区事务）', NULL, '原奉系官员，投日后任伪满监察院长，为日本在鞍山等地掠夺资源提供行政支持。', '辽宁鞍山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c1366549a4bf59948587d312c5d69a0c', '2b437180a5505d89afed6a8146c9383e', 1932, '伪满洲国交通部大臣（辽宁籍，曾负责辽南铁路）', NULL, '投日后管理伪满交通，协助日军运输军事物资和掠夺鞍山钢铁资源。', '辽宁鞍山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d04c2aaf89a5594b97fa507d3fcbb514', '581b3709952c5c81bc3860d3c62dff90', 1932, '伪满洲国奉天省警务厅长（管辖鞍山地区）', NULL, '负责奉天省（含鞍山）伪警察系统，抓捕抗日志士，镇压民众反抗。', '辽宁鞍山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9967b332adcc5f4091ce0e9812e67f0b', '06e6c670e9d35f8283366667f5aaab70', 1931, '伪鞍山地方维持会会长（具体任职待考）', NULL, '九一八后组织地方维持会，协助日军接管鞍山，维持殖民秩序。', '辽宁鞍山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e600d0ec10235c4fb7ed7bc6d06054be', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪鞍山保安队队长', NULL, '率伪保安队配合日军扫荡鞍山周边抗日义勇军，残害百姓。', '辽宁鞍山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b85fdcf9ac0d598b9e49102ab608e0fc', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1931, '伪满奉天省省长、汉奸', NULL, '九一八事变后投靠日本，任伪奉天省省长，协助日军维持殖民统治，镇压抗日活动。', '辽宁鞍山_千山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('044c6d9dd3c650caafe05b04c84a3c35', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满参议府议长、汉奸', NULL, '曾任伪奉天省省长，后任伪满参议府议长，积极为日本侵略政策服务，参与伪满政权建设。', '辽宁鞍山_千山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('61babd02b7e5564f8cc07adef6b21cdb', 'ba311422856554c7ad7f3f75d09c3d78', 1932, '伪满奉天省省长、汉奸', NULL, '继于冲汉后任伪奉天省省长，推行日本殖民政策，协助日军清剿抗日义勇军。', '辽宁鞍山_千山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2ee5cbc1ffe953de9ea0d50eb8c9bd27', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满国务总理大臣、汉奸', NULL, '曾任伪满军政部总长，后任伪满国务总理大臣，全面配合日本对东北的殖民统治，包括鞍山千山地区。', '辽宁鞍山_千山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('13367580c0565a349b88f50cc37f7cde', '2300e528128d54c19855a4669664572a', 1932, '伪满宫内府大臣、汉奸', NULL, '积极参与伪满建国，曾任伪满财政部总长，后任宫内府大臣，对辽宁地区殖民统治有重要影响。', '辽宁鞍山_千山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('838894669460593bb91b2f4bcb826a05', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满立法院院长、汉奸', NULL, '曾任伪满立法院院长，参与制定伪满法律，为日本侵略合法化服务，活动范围涉及辽宁各地。', '辽宁鞍山_千山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f702f079d50b53f490106920430cf3c0', '8f60ed6bf0f85a62a7840ff91b875b4f', 1932, '伪满奉天省实业厅厅长、汉奸', NULL, '在伪奉天省任职期间，协助日本掠夺鞍山地区铁矿资源，压迫当地矿工。', '辽宁鞍山_千山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6d8039171c985037a04d224860235e42', '1c5a7c0239a3585ba753fb5dd8066643', 1932, '伪满奉天省警务厅厅长、汉奸', NULL, '负责伪奉天省警察系统，镇压千山地区抗日武装，逮捕抗日志士。', '辽宁鞍山_千山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1039c20b14685111bf97827fd9e4eace', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满鞍山地区保安队队长、汉奸', NULL, '在鞍山地区组织伪保安队，协助日军维持治安，参与围剿抗日游击队。', '辽宁鞍山_千山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('df9e4008a52d5b5ca833cb702aeab934', '59787560de815b89a3be4e03a8aa54ce', 1933, '伪满热河省省长、汉奸', NULL, '虽主要活动于热河，但曾率伪军参与对辽宁千山地区抗日力量的清剿。', '辽宁鞍山_千山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('990175fe320a5632bb82c07099843591', '802dd1e9fe095ba4a8cbdc66a100361e', 1932, '伪满第一军管区司令、汉奸', NULL, '驻防辽宁地区，指挥伪军多次进攻千山抗日根据地，残害抗日军民。', '辽宁鞍山_千山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5ae8715941315d70b93e5257eb3f9f8e', '1ea6405224d35b439d5a62eb23dca975', 1937, '伪满鞍山宪兵队翻译、汉奸', NULL, '在鞍山宪兵队担任翻译，协助日军审讯和迫害抗日人士，民愤极大。', '辽宁鞍山_千山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('34ed5f13e52254298338850c0dbd220b', '55d5c28516215af6bb912b6e514aad47', 1931, '伪满千山地区维持会会长、汉奸', NULL, '九一八后组织千山地区维持会，为日军提供粮食物资，出卖抗日情报。', '辽宁鞍山_千山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6d69880808375575ba5dbb658e63f8c0', 'd6ca38cec4105c5ea630f21d3071e2d8', 1933, '伪满鞍山铁矿监工、汉奸', NULL, '在鞍山铁矿为日本监工，残酷虐待中国劳工，造成大量矿工死亡。', '辽宁鞍山_千山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0d41aa72ad8e59918706e8c24400d3fb', '9778b9143f875560be28cf23b8bf116d', 1931, '奉系军阀将领（后投日）、汉奸', NULL, '虽早年是奉系，但九一八后曾与日本秘密接触，试图在辽宁地区建立傀儡政权，后因内部矛盾未果。', '辽宁鞍山_千山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c37b2814997f5926a6a1b028ddb54138', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满第七军管区司令', NULL, '原东北军将领，九一八后投敌，在辽宁西部及热河地区协助日军镇压抗日武装，后任伪满要职，参与“治安肃正”行动。', '辽宁鞍山_台安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1b523ab6edc45b0ba09cd96a6f93fc38', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满奉天省省长、伪满第一军管区司令', NULL, '原东北军旅长，叛变后任伪满奉天省（含鞍山、台安地区）最高军事长官，多次指挥伪军“讨伐”抗日义勇军，残害民众。', '辽宁鞍山_台安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dd5eb8584361595ba4fb5dd2959353c0', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满鞍山地区警务处长', NULL, '在鞍山及台安一带组织伪警察和保甲制度，配合日军抓捕抗日人员，强征劳工，镇压反满抗日活动。', '辽宁鞍山_台安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('da5951022bcd5fa397bdbbe55c63ba4f', 'f13fea3281b35a0ea71eb3863d7d53f7', 1933, '伪满台安县县长', NULL, '在台安县推行伪满殖民政策，强制收缴民间枪支，组织“自卫团”协助日军清乡，迫害抗日家属。', '辽宁鞍山_台安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5f6869cc1c945174adad72a7afaad2c4', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长（曾任奉天市市长）', NULL, '虽主要活动于沈阳，但作为辽宁地区伪政权核心人物，参与制定奴化教育及经济掠夺政策，影响覆盖鞍山、台安。', '辽宁鞍山_台安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f55ba2a4905e560e808b27fc4c5284ab', '318089c2a3375e67b7c33f0820381332', 1935, '伪满交通部大臣、伪满奉天省省长', NULL, '在任奉天省长期间，强化对鞍山、台安等地的殖民统治，推动“粮谷出荷”和劳工统制，导致当地民众饥荒。', '辽宁鞍山_台安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('58e26d5742745a498eb34e5b1d078942', '3de6f584b1b75a69a535180aca36f08a', 1937, '伪满鞍山宪兵队翻译官', NULL, '为日军宪兵队充当翻译，参与审讯和刑讯抗日志士，多次带队到台安地区抓捕地下抗日人员。', '辽宁鞍山_台安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5e69c495a2db5daba197ad2dc6a8f336', '55d5c28516215af6bb912b6e514aad47', 1938, '伪满台安地区“协和会”会长', NULL, '积极宣传“日满亲善”，组织青少年奴化训练，告发抗日嫌疑分子，协助日军建立“集团部落”。', '辽宁鞍山_台安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1628feb85aa653b6bbad40277b55317b', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满国务总理大臣（原奉系将领）', NULL, '作为伪满最高行政首脑，其政策直接支配辽宁各地，包括鞍山、台安，支持日军“讨伐”和资源掠夺。', '辽宁鞍山_台安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('109de69239f159aab8daf18f98fed790', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满参议府议长（原奉天省长）', NULL, '九一八后投敌，参与策划伪满建国，在辽宁地区推行“治安维持法”，对鞍山、台安抗日活动进行镇压。', '辽宁鞍山_台安');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('587bf75a14b75f379c1b45b17e30bec0', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八事变后投敌，曾任伪满热河省省长，参与镇压抗日武装，后任伪满军政部大臣，为日本侵略者效力。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b1e386548b1657ab8c413013eb3f87cd', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满第一军管区司令官', NULL, '原东北军旅长，1931年投敌，任伪满第一军管区司令官，驻防辽宁地区，多次率伪军围剿抗日义勇军和抗联部队。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d36443209bdd5cd78f6f0c3983047506', '1ea6405224d35b439d5a62eb23dca975', 1931, '伪满鞍山地区维持会会长', NULL, '鞍山本地豪绅，日军占领鞍山后出任维持会会长，协助日军征粮、抓劳工，镇压当地抗日活动。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('29e57125d56b5992871353bae35b615b', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪岫岩县县长', NULL, '原岫岩县地方官员，投日后任伪县长，推行保甲制度，配合日军清乡，抓捕抗日志士，强征民夫修建军事设施。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2a43f4b42ec55ef7ae82d2f604f39d66', '1885517c4b5b53f093b96c0dece295e7', 1933, '伪岫岩县警务科科长', NULL, '原岫岩警察，投日后任伪警务科长，组织伪警察队，多次参与对抗日武装的“讨伐”，杀害多名抗联侦察员。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0c52739f6cee5d3fb2f12345b4c05fb4', '0e3cb744f8ba581bb4073554347ef113', 1935, '伪满鞍山宪兵队翻译官', NULL, '鞍山人，精通日语，任日军宪兵队翻译，参与审讯和刑讯抗日人士，直接导致多名地下党员牺牲。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('86952ac7760e54b488d1deb9c37da4dc', '7c3e416398ce57859a8a807ff1874ba3', 1934, '伪岫岩县保安团团长', NULL, '地主武装头目，投日后任保安团长，率团丁配合日军扫荡，烧毁抗日村庄，掠夺百姓财物。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('23c750c825f1543289b5bedd9813313a', '9b0436fb47615db386551fba69ea63bb', 1936, '伪满鞍山地区协和会会长', NULL, '鞍山富商，任伪协和会会长，为日军宣传“王道乐土”，组织“献金”活动，资助日军军费。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0265599c70f45818b515cf8f77c9fa4d', '9fd1d91d9a435298996fec8a54da1629', 1932, '伪岫岩县教育局长', NULL, '原岫岩教育界人士，投日后任伪教育局长，强制推行奴化教育，删除中国历史教材，灌输亲日思想。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('66b17d4efa2a5e05b754258097f7760e', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满国务总理大臣', NULL, '原奉系军阀，九一八后投日，虽为伪满中央高官，但曾在辽宁鞍山、岫岩地区部署伪军镇压抗日力量，其势力影响该地区。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0f81a33750c0534185c59689367c9c92', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满奉天省省长', NULL, '原辽宁省政府主席，投日后任伪奉天省省长，管辖包括鞍山、岫岩在内的地区，推行日伪殖民政策。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('60bc7ce6d36650feae5ac49e4e9b7936', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1931, '伪满鞍山铁矿株式会社总办', NULL, '原鞍山铁矿中方经理，投日后任伪总办，为日军掠夺鞍山铁矿资源，强迫中国劳工超负荷劳动，造成大量死亡。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4e021f5559f551d2a144485783b3c5ec', '3f44661b09335d5a8069b4d3f2a5c441', 1932, '伪满岫岩地区“剿匪”司令', NULL, '原地方民团首领，投日后任伪“剿匪”司令，专门围剿岫岩山区抗日义勇军，手段残忍，曾屠杀村民。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7068ea497a105c26aa367ec173c04284', '73c16dc345b65ef8801f51fd74ab5211', 1933, '伪满鞍山地区警察署署长', NULL, '原鞍山巡警，投日后任伪警察署长，设立多处“留置场”（拘留所），严刑拷打抗日嫌疑犯，并协助日军抓捕抗联交通员。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('67494164102751cebf2686cfc03fe06c', '1c5a7c0239a3585ba753fb5dd8066643', 1932, '伪岫岩县财务局长', NULL, '原岫岩县财务官员，投日后任伪财务局长，为日军征收各种苛捐杂税，搜刮民财，供给伪军和日军。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('02c591c4c0cf53d3b077f1f0e3615255', '2a816e97326c5210bdec3a2c3af8c214', 1933, '伪满参议府参议（曾涉辽宁地区）', NULL, '原奉系将领，虽名义上未任伪职，但实际与日伪合作，其旧部在鞍山、岫岩地区组织伪军，间接助敌。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f36d91be57a1556f937ca30efca3b542', '58e6d43c943f58a9a8100d50bf928499', 1935, '伪满岫岩县协和会事务长', NULL, '岫岩本地人，任伪协和会事务长，组织“青少年团”进行军事训练，为日军输送伪军兵源。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('67644f9eb6ec5467b7e767a2ca58f2b7', '8971710d07f853e88929efbf675bcaed', 1934, '伪满鞍山地区“自卫团”总团长', NULL, '鞍山郊区地主，投日后组织“自卫团”，配合日军封锁山区，切断抗联补给线，并参与屠杀抗日家属。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('883f7026397654469f0ffe5dfdcd3156', 'eb16f12e82445062991b80687ab7f146', 1932, '伪满立法院院长（曾管辖辽宁司法）', NULL, '原奉天律师，投日后任伪满立法院院长，制定镇压抗日活动的法令，其司法体系覆盖鞍山、岫岩地区。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b4ffd0af90845f41b7fca64a6d18a15c', '8f60ed6bf0f85a62a7840ff91b875b4f', 1938, '伪满鞍山地区“勤劳奉仕”总队长', NULL, '鞍山商人，投日后任“勤劳奉仕”总队长，强征中国青壮年充当劳工，送往矿山和军事工地，致多人死亡。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5c2b640795f35e3ba5e7805e8ff6892c', '2d9d4ae3c5bd54e4bdae0faf68cdbb80', 1931, '伪满军政部大臣（兼）', NULL, '已列，但需注意其曾直接下令伪军参与岫岩地区“讨伐”行动。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('fb8dfc68826d59d2abedc27922efe93a', '95ff7846d44f5084991c9d5d1c60db78', 1932, '伪满司法部大臣（涉辽宁）', NULL, '原北洋政府官员，投日后任伪满司法部大臣，其推行的“治安维持法”在鞍山、岫岩地区被用于迫害抗日人士。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f962077da74c5359bf9f8ee3eff16ddb', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满参议府议长（辽宁籍）', NULL, '辽宁辽阳人，投日后任伪满参议府议长，虽居高位，但曾为日军在鞍山、岫岩地区建立伪政权出谋划策。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4a130123798854178051b89478d3a5b4', '85aa2fd10d9c5918aff4e588d092ec71', 1933, '伪满鞍山地区“靖安军”顾问', NULL, '原东北军军官，投日后任伪“靖安军”顾问，参与训练伪军，并随军到岫岩山区扫荡。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3d52c8720bdc50f7afdd7eadea4bf5d7', '7c51a2464caa5e18aaf829b24f6c43bc', 1932, '伪满军事部次长（涉辽宁）', NULL, '原东北军参谋长，投日后任伪满军事部次长，负责指挥伪军镇压辽宁各地抗日武装，包括鞍山、岫岩地区。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b24b0b0333c759c1b83866d57203bb2e', '2300e528128d54c19855a4669664572a', 1931, '伪满宫内府大臣（曾涉辽宁）', NULL, '原吉林军将领，投日后任伪满宫内府大臣，虽非直接管辖鞍山、岫岩，但其伪军系统曾调兵至该地区作战。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4b141d0054eb5c31acf6cc1dcbd6ab45', 'ff9e89d899b252749c4c67a488d7ebd2', 1932, '伪满第五军管区司令官（驻辽宁）', NULL, '原东北军旅长，投日后任伪第五军管区司令官，驻防辽宁南部，多次率部进攻岫岩、鞍山一带的抗联部队。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('15d715c093595e8ab5e1e7d2d4be8978', 'df85b9e8c1b05cedba1173db2a702e1b', 1934, '伪岫岩县警察大队大队长', NULL, '原岫岩县警佐，投日后任伪警察大队长，率伪警参与“归屯并户”，制造无人区，切断抗日武装与百姓联系。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4b29043e813b54e8b69e3a6917192f26', '55d5c28516215af6bb912b6e514aad47', 1937, '伪满鞍山地区“宣抚班”班长', NULL, '鞍山汉奸文人，任伪“宣抚班”班长，随日军到各村进行“宣抚”，诱骗百姓归顺日伪，出卖抗日情报。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('bbbd5a6f37ba57c193a80ffbc2f6641d', '53e71ec04f6057348dadc54a228588ab', 1933, '伪岫岩县商会会长', NULL, '岫岩大商户，投日后任伪商会会长，为日军筹集物资，并强迫商户“献金”，资助伪军购买武器。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ad528cd9f5145d37a90cb82c79c614bc', 'd6ca38cec4105c5ea630f21d3071e2d8', 1939, '伪满鞍山地区“青年训练所”所长', NULL, '鞍山教育汉奸，任伪青年训练所所长，对青年进行军事化奴化训练，为日军培养伪军后备力量。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('222d49e6c4745be2b902af6b6026a4da', '0da09f00ee6a55878e86adbb70127338', 1932, '伪满民生部大臣（涉辽宁）', NULL, '原吉林财政厅长，投日后任伪满民生部大臣，推行“粮谷出荷”政策，导致鞍山、岫岩地区农民饿死无数。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8019c0c81b09503e97ab07514d2f9c77', '9ecee7f0ddf659e583819e721e164c94', 1935, '伪满鞍山地区“铁路护路队”队长', NULL, '鞍山铁路职员，投日后任伪护路队长，协助日军保护铁路运输，抓捕破坏铁路的抗日分子。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('959ce7a6347f56659f501ecf28a9aaad', '7d8cfba1792a542da4df53d179b12578', 1931, '伪满热河省省长（曾率军至岫岩）', NULL, '已列，但需补充其曾派伪军到岫岩地区“清剿”抗日义勇军。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f16169e1339b59528428db929cec9126', '0dbd8fdb708c5334b9bb51593f6e9fda', 1932, '伪岫岩县财务局长', NULL, '已列，但需注意其还负责为日军征收“出荷粮”，导致当地饥荒。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('026e81acb0c652a8855225edc7a88804', '90c814f9641758cfb226f19235872719', 1932, '伪岫岩县县长', NULL, '已列，但补充其曾下令处决抗日家属。', '辽宁鞍山_岫岩');
