INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c255745982585ac5aba3434dbb7e10b9', '35da44941cbd5e3cabf7a29c3843b256', 1934, '伪岫岩县保安团团长', NULL, '已列，补充其曾参与“三光”政策。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7474bb34771651829a2c6a09caf533e6', '614a60c604445be2844fb48e31e289be', 1936, '伪满鞍山地区协和会会长', NULL, '已列，补充其曾组织“献机”活动。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ef5e69fb17a95f7bbef9ec83ff5e6f3b', '49423551ad3456fd85c284e3dbfbed30', 1932, '伪岫岩县教育局长', NULL, '已列，补充其曾强迫学生唱日本国歌。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('509a08c298965e6fb3b3f1777ddec0d4', '143ce6584bf65a4e94082cf414c2f803', 1931, '伪满鞍山铁矿株式会社总办', NULL, '已列，补充其曾克扣劳工口粮。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('88e79b5802ec5c298027e7a11fb0be40', 'a7dc715dee7955bdbfd561827a86ce52', 1932, '伪满岫岩地区“剿匪”司令', NULL, '已列，补充其曾悬赏抗日义士人头。', '辽宁鞍山_岫岩');
