INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f16169e1339b59528428db929cec9126', '0dbd8fdb708c5334b9bb51593f6e9fda', 1932, '伪岫岩县财务局长', NULL, '已列，补充其曾贪污抗日捐款。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f734b77135a956fb9823987ba2d42044', 'a4a1ad0f05cc5a8f9ea7c397ef92b157', 1935, '伪岫岩县协和会事务长', NULL, '已列，补充其曾组织“防共青年团”。', '辽宁鞍山_岫岩');
