INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2c07941ff3d5540cb8235778e22c4393', 'e63efaecf5435fffaf98b61f807ec3fc', 1938, '伪满鞍山地区“勤劳奉仕”总队长', NULL, '已列，补充其曾将劳工卖给日本矿山。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0713d88ba01d543abfe882a61b497a1b', '13763c05013c5be59bc67649e34cc6af', 1934, '伪岫岩县警察大队大队长', NULL, '已列，补充其曾参与“大讨伐”。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1f92315f6bea51409fd387f12189a7c2', '2b02c3265040584390408b2316e1dad9', 1937, '伪满鞍山地区“宣抚班”班长', NULL, '已列，补充其曾诱骗儿童当间谍。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('387acaf75bc85b559525c1e330cb4c48', '8e2831609b485f6fa507714d3917f099', 1933, '伪岫岩县商会会长', NULL, '已列，补充其曾垄断粮食贸易。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7111749adb315f1292c7b30893b76556', '4952c04ac39751129939d3989262a78c', 1939, '伪满鞍山地区“青年训练所”所长', NULL, '已列，补充其曾强迫青年宣誓效忠天皇。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c0bcc85579e65e13aa617ebe6eca9cf1', 'd80628d48ac4520aa234d7ff6f28bbb4', 1935, '伪满鞍山地区“铁路护路队”队长', NULL, '已列，补充其曾协助日军运输军火。', '辽宁鞍山_岫岩');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('9c711b8d9693520f975be9c97d11be6e', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满第七军管区司令官', NULL, '原东北军将领，九一八事变后投敌，在辽宁西部及热河地区协助日军镇压抗日武装，后任伪满高官，曾参与围剿辽西义勇军。', '辽宁鞍山_海城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('26a19b5cb0175aa8be4d8de522fcd7dc', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满奉天省省长、伪满第一军管区司令官', NULL, '原东北军旅长，1931年投降日军，任伪奉天省警备司令，后任伪满奉天省省长，在辽宁地区推行殖民统治，镇压抗日力量。', '辽宁鞍山_海城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('552359df1565535dabc42820d4694a67', '1ea6405224d35b439d5a62eb23dca975', 1931, '伪满鞍山地区治安维持会会长', NULL, '鞍山本地豪绅，日军占领鞍山后出任伪治安维持会会长，协助日军征粮、抓劳工，为日本昭和制钢所（鞍钢前身）提供劳动力。', '辽宁鞍山_海城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6aad0515833959e6a4737955eea2da24', 'f13fea3281b35a0ea71eb3863d7d53f7', 1932, '伪满海城县县长', NULL, '原海城县地方官员，投敌后任伪海城县县长，推行保甲制度，强征民夫修建军事设施，配合日军清剿海城地区的抗日游击队。', '辽宁鞍山_海城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6797a68dce615733b9af641fd5968ba0', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满奉天市市长、伪满立法院院长', NULL, '原奉系法律人士，九一八后投敌，任伪奉天市市长，后升任伪满立法院院长，在辽宁及鞍山地区推行日伪法律，镇压反满抗日活动。', '辽宁鞍山_海城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c74be4d35c6a5cb5a29f2ae4e9dedc4a', '318089c2a3375e67b7c33f0820381332', 1932, '伪满奉天省教育厅厅长', NULL, '原辽宁教育界人士，投敌后任伪奉天省教育厅长，在鞍山、海城等地推行奴化教育，强制学校使用日语教材，灌输“日满亲善”思想。', '辽宁鞍山_海城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('135d5da90306571eac185a0de166d129', '3de6f584b1b75a69a535180aca36f08a', 1932, '伪满鞍山警察署署长', NULL, '原鞍山地区警察，投敌后任伪鞍山警察署长，多次参与抓捕抗日地下党员，破坏抗日组织，协助日军实行“治安肃正”。', '辽宁鞍山_海城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8e4ae10b8d995f3b8d47497ce04b99a7', '55d5c28516215af6bb912b6e514aad47', 1933, '伪满海城保安队队长', NULL, '海城地方武装头目，投敌后组织伪保安队，配合日军扫荡海城东部山区，杀害抗日义勇军战士及无辜百姓。', '辽宁鞍山_海城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('e7b317a098e5566eb6650d0ccbe2bffc', '58e6d43c943f58a9a8100d50bf928499', 1932, '伪满辽南地区“剿匪”司令', NULL, '原辽南土匪头目，被日军收编后任伪“剿匪”司令，在鞍山、海城、岫岩一带围剿抗日武装，烧毁村庄，罪行累累。', '辽宁鞍山_海城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5cacaaede078597da515bb349fad69b0', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满国务总理大臣（曾任奉天省长）', NULL, '原奉系军阀，九一八后投敌，曾任伪奉天省省长，后任伪满国务总理，对包括鞍山、海城在内的辽宁地区负有全面殖民统治责任。', '辽宁鞍山_海城');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4e1e4a6b39c35529bf2eae60094c2267', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1931, '伪满鞍山昭和制钢所顾问、伪满中央银行监事', NULL, '协助日本帝国主义控制鞍山铁矿资源，为昭和制钢所（今鞍钢前身）提供情报与资源调配，参与伪满经济统制政策，压榨中国劳工。', '辽宁鞍山_立山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8d287090256d59bbb9726d93c900a0e1', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣（曾活动于辽南地区）', NULL, '九一八事变后公开投敌，在辽宁地区协助日军镇压抗日义勇军，后任伪满要职，参与“治安肃正”行动，残害抗日军民。', '辽宁鞍山_立山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d43b708b15f4518f9d2d07c8e6cc512c', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满鞍山地方警察署署长', NULL, '在鞍山、立山地区积极执行日伪“保甲制度”，搜捕抗日地下工作者，多次带队围剿抗日游击队，并强迫居民“连坐”举报。', '辽宁鞍山_立山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d63379abdecb5c95b9e875695f1ba6d3', 'f13fea3281b35a0ea71eb3863d7d53f7', 1931, '伪满立山地区维持会会长', NULL, '日军占领立山后主动组织维持会，为日军征集粮食、劳役，强征当地青壮年充当伪军，并协助日军建立“集团部落”以隔离抗日武装。', '辽宁鞍山_立山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('4e4eb141346a502289f566c32ea3daa0', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满立法院院长（曾参与辽南殖民统治策划）', NULL, '虽主要活动于伪满中央，但多次赴鞍山、立山矿区“视察”，推动《满洲国劳动统制法》在鞍山实施，导致大量矿工因劳致死。', '辽宁鞍山_立山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3b25236250ef57dbbbc5442376485362', '802dd1e9fe095ba4a8cbdc66a100361e', 1932, '伪满第一军管区司令（管辖辽南包括鞍山地区）', NULL, '率伪军配合日军在鞍山、海城、立山一带“讨伐”抗日义勇军，制造多起屠杀事件，并强迫农民“出荷”粮食支援日军。', '辽宁鞍山_立山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('dccd4d37c82e5ea6b4e79ce3852b6125', '9aeaa43e6c4553d2b977206f785a8b86', 1938, '伪满鞍山铁矿株式会社劳务课长', NULL, '负责从华北、山东强掳劳工至鞍山矿山，实行“以人换矿”政策，克扣口粮，导致数千劳工死亡，并参与镇压劳工暴动。', '辽宁鞍山_立山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('3c313c42513b5129aca8148518dc1b62', '55d5c28516215af6bb912b6e514aad47', 1933, '伪满立山地区保安队队长', NULL, '带领保安队为日军把守立山交通要道，多次截击抗日物资运输，并直接参与抓捕、刑讯抗日嫌疑人员，手段残忍。', '辽宁鞍山_立山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0e15fef85f9551aca0af32f4bf125329', 'e605798af81b50b78e159caff3e3acc7', 1935, '伪满国务总理大臣（曾多次巡视鞍山钢铁生产）', NULL, '作为伪满最高行政头目，推动鞍山昭和制钢所扩大生产以供应日军军需，并批准在立山增设“矫正辅导院”，关押迫害抗日群众。', '辽宁鞍山_立山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ae4d90de502e5101bb7b0af8f58b3eef', '06c1ecca7c3f5240b6bf4a99f59beae0', 1937, '伪满鞍山地方检察厅厅长', NULL, '依据《治安维持法》在鞍山、立山地区滥捕“思想犯”，判处大量爱国志士死刑或长期监禁，并协助日军“特别移送”至731部队。', '辽宁鞍山_立山');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('c66a70b8ca1b5864bc3d933eb1346ead', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1931, '伪满鞍山昭和制钢所理事、伪满奉天省省长', NULL, '曾任伪满鞍山昭和制钢所理事，后任伪满奉天省省长，积极为日本侵略者服务，压榨东北人民，协助日伪政权推行殖民统治。', '辽宁鞍山_铁东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('cda2e08581e750c298aca94f80d32059', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八事变后投敌，曾任伪满热河省省长、伪满军政部大臣，在辽宁及鞍山地区协助日军镇压抗日力量，推行“治安肃正”。', '辽宁鞍山_铁东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('8366207b78f75fa88c2e7eb878e68f73', '1c5a7c0239a3585ba753fb5dd8066643', 1931, '伪满鞍山地方维持会会长', NULL, '九一八事变后，在鞍山铁东地区组织地方维持会，协助日军维持秩序，为日本占领军提供情报和后勤支持。', '辽宁鞍山_铁东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('1ab7f90777ce58639274d53669f89618', 'eb16f12e82445062991b80687ab7f146', 1931, '伪满奉天市市长、伪满立法院院长', NULL, '曾任伪满奉天市市长，后升任伪满立法院院长，在辽宁地区（包括鞍山铁东）推行奴化教育和经济掠夺政策。', '辽宁鞍山_铁东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('f4ac0c7e1fed548098eb39006970d512', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满奉天省参议、伪满尚书府大臣', NULL, '清末举人，九一八后投靠日本，任伪满奉天省参议，参与策划辽宁地区伪政权建立，支持日本对鞍山铁矿资源的掠夺。', '辽宁鞍山_铁东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('ad0c4e5f48a652cf9a995efe73c04a62', '58e6d43c943f58a9a8100d50bf928499', 1932, '伪满鞍山警察署署长', NULL, '任伪满鞍山警察署署长期间，残酷镇压抗日爱国人士，协助日军抓捕和刑讯地下抗日分子，在铁东地区制造多起白色恐怖事件。', '辽宁鞍山_铁东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('de0db6f0c4e450dea7f90bc801e915b5', 'f13fea3281b35a0ea71eb3863d7d53f7', 1933, '伪满鞍山铁东区区长', NULL, '任伪满鞍山铁东区区长，强征劳工为昭和制钢所服务，克扣工人口粮，协助日军推行“粮谷出荷”政策，导致当地民众饥荒。', '辽宁鞍山_铁东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('30027c3b50f153b198fba981088f4a47', '1ea6405224d35b439d5a62eb23dca975', 1931, '伪满鞍山保安队队长', NULL, '原土匪出身，投日后任鞍山保安队队长，率队围剿抗日游击队，在铁东地区烧杀抢掠，杀害无辜百姓。', '辽宁鞍山_铁东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d6a408ba6c8e5b8c8fc1bc2bbbeaa757', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满国务总理大臣', NULL, '原奉系军阀，九一八后投敌，任伪满国务总理大臣，虽主要活动于新京（长春），但其影响覆盖辽宁鞍山地区，支持日本对鞍山钢铁资源的全面控制。', '辽宁鞍山_铁东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('5bf62488c936552587fa8eb1ba9995a5', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满奉天省省长、伪满参议府议长', NULL, '原奉天省省长，九一八后投降，任伪满奉天省省长，在鞍山铁东地区推行“保甲制度”和“连坐法”，强化殖民统治。', '辽宁鞍山_铁东');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a734fb757f7e5f9face26abda4b38422', 'a1e1ddf6eec858ddb7aa0e78e6c2ea2f', 1931, '伪满鞍山昭和制钢所理事、伪满奉天省省长', NULL, '曾任伪满鞍山昭和制钢所理事，后任伪满奉天省省长，积极协助日本侵略者掠夺鞍山铁矿资源，镇压抗日力量。', '辽宁鞍山_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('b83f4a77888750fba7636beb35090e23', '59787560de815b89a3be4e03a8aa54ce', 1931, '伪满热河省省长、伪满军政部大臣', NULL, '原东北军将领，九一八事变后投敌，曾任伪满热河省省长，后调任伪满军政部大臣，在辽宁、鞍山等地协助日军清剿抗日武装。', '辽宁鞍山_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a05964ffa77f5c3997c5a93b672020ca', '1c5a7c0239a3585ba753fb5dd8066643', 1931, '伪满鞍山地方维持会会长', NULL, '在鞍山沦陷后组织地方维持会，为日军提供粮食、劳力和情报，协助建立伪政权。', '辽宁鞍山_铁西');
