INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('429f3170dc38576299249c213a28f329', 'a2f31a9be59d5a89b0426ae789e7bef9', 1931, '伪满奉天省省长', NULL, '九一八后投敌，任伪满奉天省省长，管辖鞍山、铁西等地，协助日军建立保甲制度，强征劳工。', '辽宁鞍山_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('02529de620315b5d9798f3292079e26e', 'ba311422856554c7ad7f3f75d09c3d78', 1931, '伪满奉天省省长、伪满民政部大臣', NULL, '原辽宁省政府主席，投敌后任伪满奉天省省长，在鞍山铁西地区推行日伪经济统制政策。', '辽宁鞍山_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('6511a2277d9d5bffa8b6103ec3f48cda', '58e6d43c943f58a9a8100d50bf928499', 1932, '伪满鞍山警察署署长', NULL, '在鞍山铁西地区任伪警察署长，残酷镇压抗日地下组织，抓捕爱国人士。', '辽宁鞍山_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('0d1eb32e8d8252c3aa331996b6e4c849', 'f13fea3281b35a0ea71eb3863d7d53f7', 1933, '伪满铁西区区长', NULL, '任伪满鞍山铁西区区长，协助日军强征土地，建立军事设施，迫害当地居民。', '辽宁鞍山_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('31d281a70e385370bf57a4593a8d96be', 'e605798af81b50b78e159caff3e3acc7', 1931, '伪满国务总理大臣', NULL, '原东北军将领，投敌后任伪满最高行政长官，其政策覆盖辽宁鞍山铁西地区，支持日军经济掠夺。', '辽宁鞍山_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('2eba7535c2b75f9c9b5ed2089222e965', '2300e528128d54c19855a4669664572a', 1931, '伪满财政部大臣', NULL, '参与伪满政权建立，在辽宁地区推行金融统制，协助日本控制鞍山钢铁产业。', '辽宁鞍山_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('7d1830e936d05d10ac7b273368c38f99', '802dd1e9fe095ba4a8cbdc66a100361e', 1931, '伪满第一军管区司令官', NULL, '原东北军旅长，投敌后任伪满第一军管区司令，驻防辽宁，多次率伪军围剿鞍山、铁西地区的抗日游击队。', '辽宁鞍山_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('a9cc2ac898b65df0bb4fd7cf1b368264', '1ea6405224d35b439d5a62eb23dca975', 1932, '伪满鞍山保安队队长', NULL, '在鞍山铁西地区组织伪保安队，配合日军扫荡，杀害抗日军民。', '辽宁鞍山_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('d25a3f0c03995290894593e5d7536e69', '6a1ef5b397c15509b1605e37411576fc', 1934, '伪满铁西地区协和会会长', NULL, '任协和会铁西分会会长，推行奴化宣传，组织青年训练，为日军输送劳工。', '辽宁鞍山_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('88f5aed0a1fc5350a8cfd3ec3aa45f47', 'd7eca4cf356953a9bd843f9ae77031f1', 1931, '伪满黑龙江省省长（后反正）', NULL, '一度投敌任伪职，但不久反正抗日，其在辽宁鞍山地区短暂活动期间未造成重大危害。', '辽宁鞍山_铁西');
INSERT INTO `crimerecords` (`Id`, `TraitorId`, `Year`, `Title`, `Process`, `Harm`, `SourceRef`) VALUES ('545aae98bd8f5f8e9b81dbb33ff590c5', '8f60ed6bf0f85a62a7840ff91b875b4f', 1932, '伪满奉天省实业厅厅长', NULL, '主管伪满奉天省（含鞍山铁西）工矿企业，协助日本昭和制钢所扩大生产，掠夺资源。', '辽宁鞍山_铁西');
